// SimHub plugin owning the Trueforce HID session and the audio-haptic Mixer.
//
// Lifecycle:
//   Init: load settings → discover wheel → open + init + start stream →
//         create AudioCaptureSource (per-process loopback, retargeted on
//         game start/stop) and add it to the Mixer.
//   DataUpdate: the per-tick hot path. Feeds the SimHub telemetry source and
//         tracks the game name / process for the capture timer, and polls the
//         watchdogs (device recovery, G HUB, port discovery, community facts).
//   End: save settings, stop producer + capture, clean up the device.
//
// The producer thread runs independently of the SimHub data tick because
// the stream pump consumes samples at 4 kHz (our chosen 1000 packets/s × 4
// per packet; the wheel accepts a 250-1000 packets/s band, per mescon);
// SimHub's data ticks vary by game (60-200 Hz typical) and would be too
// coarse to drive the stream directly.

using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Net;
using System.Threading;
using System.Threading.Tasks;
using System.Windows.Controls;
using Newtonsoft.Json.Linq;
using System.Windows.Media;
using GameReaderCommon;
using SimHub.Plugins;
using TrueforceForAll.Core;
using TrueforceForAll.Plugin.Effects;

namespace TrueforceForAll.Plugin
{
    // Description deliberately omits the version: PluginDescription takes a
    // compile-time-constant string, and the assembly version (<Version> in
    // src\Directory.Build.props, shared by Core, Engine and Plugin) is already
    // surfaced at runtime by UpdateChecker. A copy here just goes stale on bumps.
    [PluginDescription("Everything your Logitech wheel can do, in games that never supported it. Trueforce, rev lights, the screen. For G PRO, RS50 and G923.")]
    [PluginAuthor("Mhytee")]
    [PluginName("Trueforce For All")]
    // partial: the dash remote bridge (properties + dash-triggerable actions)
    // lives in TrueforcePlugin.DashRemote.cs.
    public sealed partial class TrueforcePlugin : IDataPlugin, IWPFSettingsV2
    {
        private const int BatchSamples = TrueforceDevice.NewPerPacket; // one packet's worth

        public PluginManager PluginManager { get; set; }

        public string LeftMenuTitle => "Trueforce For All";
        public ImageSource PictureIcon => null;

        public TrueforceSettings Settings { get; private set; }

        private readonly Mixer _mixer = new Mixer();

        // Trueforce EQ: runs on the summed mix inside the Mixer (PostMix),
        // before master gain and the clamp. Global, a wheel/rig trait; the
        // band list lives in Settings and is pushed by ApplyTrueforceEq.
        private readonly ParametricEq _trueforceEq = new ParametricEq(ParametricEq.DefaultSampleRateHz);
        public ParametricEq TrueforceEq => _trueforceEq;
        // Spectrum taps either side of the EQ for the editor's live display
