        public void SetFfbSpikeTamingEnabled(bool v)
        {
            if (_device != null) _device.FfbSpikeTamingEnabled = v;
            if (Settings != null) Settings.FfbSpikeTamingEnabled = v;
        }

        public void SetFfbSpikeUseSlewLimiter(bool v)
        {
            if (_device != null) _device.FfbSpikeUseSlewLimiter = v;
            if (Settings != null) Settings.FfbSpikeUseSlewLimiter = v;
        }

        // ---- Spring mode (Mode B value 2): classic-spring games ------------
        //
        // Games on the classic Logitech protocol can command force as a
        // parametric spring instead of a streamed value; the wheel's firmware
        // normally computes the torque from its own position, but in
        // Trueforce mode it doesn't, so the game's centering silently dies
        // while every plugin effect keeps working (the FS25/G923 report,
        // 2026-08-06). Spring mode runs the firmware's math in the Mode B
        // pipeline: the tap captures the spring parameters, the steering
        // reader supplies the wheel's physical position, MaybeReshapeFfb
        // substitutes the evaluated force and applies the Mode B velocity
        // damper (a spring on a physical wheel with no damping is an
        // oscillator; the firmware damps its own rendering, so we must damp
        // ours). Riding _forceMode also inherits the Mode B contracts for
        // free: rev-light/OLED gating, GameFfbExpected suppression, and the
        // StopStreamOnPause exemption.
        //
        // Armed from bus dynamics: toggle on + the tap shows a playing
        // spring + no scalar game force for a sustained window. Farming
        // Simulator instead arms by GAME name and never disarms on a
        // scalar (see UpdateSpringModeArming). Elsewhere a scalar disarms
        // instantly (that game streams real values; pass-through must own
        // the wheel again), which also keeps the Mode B contention warning
        // unreachable. Real Mode B (value 1) wins; spring only arms from 0.
        private long _springArmCandidateSinceTicks;   // 0 = no candidate window open

        // The engine's additive copy of the game's classic spring (type 0x0b
        // under CLASSICCOND) renders zero while our own spring model owns the
        // force. Called wherever _forceMode changes rather than only once per
        // DataUpdate pass: a disarm that landed a pass late left the copy
        // silent for that window with nothing replacing it, and an arm that
        // landed a pass late left it summing beside ComputeSpringModeForce.
        // Same reasoning as the FfbBypassTapCorrections assertion in
        // ApplyModeBFromSettings, and the per-pass call in
        // UpdateSpringModeArming stays as the re-attach backstop.
        private void AssertSpringModeStandDown()
        {
            var tapStandDown = _ffbTap;
            if (tapStandDown != null)
                tapStandDown.ClassicSpringModeActive = _forceMode == ForceModeSpring;
        }

        private void UpdateSpringModeArming()
        {
            var tap = _ffbTap;
            bool toggleOn = Settings != null && Settings.ClassicSpringEmulationEnabled
                            && Settings.PluginEnabled;
            // While spring mode owns FFB there is no game FFB to capture, so
            // the tap's no-FFB watchdog must stay quiet: on a G PRO in FS
            // even the spring-parameter quiet never engages (the game sends
            // only heartbeats), and the watchdog escalated to whole-bus
            // capture + a misleading "no FFB, quit G HUB" warning two
            // minutes into a session (2026-08-08 log). Asserted every pass
            // so a recreated tap (self-heal restart) re-learns it.
            if (tap != null) tap.SyntheticFfbActive = _forceMode == ForceModeSpring;
            // Same assertion, one layer down: while spring mode renders the
            // game's captured spring itself, the engine's additive copy of
            // that same spring (classic type 0x0b, CLASSICCOND) must stand
            // down, or the wheel gets the spring twice. This pass-level call
            // is the re-attach backstop; the arm and the disarm below assert
            // it again on the spot, so neither edge lags by a DataUpdate.
            AssertSpringModeStandDown();
            // The iRacing reshape authors its own sign and takes its strength
            // from its own control, so the tapped-path corrections are switched
            // off under it. Asserted every pass rather than on mode change, so a
            // device re-attach cannot leave the flag behind.
            var devTf = _device;
            if (devTf != null) devTf.FfbBypassTapCorrections = _forceMode == ForceModeIRacing;
            // An arcade cabinet's force is authored from a decoded command, not
            // read off the wire, so the tap's sign reconciliation does not apply
            // to it. Asserted every pass for the same reason as the line above: a
            // device re-attach must not leave the flag behind. The scale still
            // applies, which is why this is not FfbBypassTapCorrections.
            if (devTf != null) devTf.FfbBypassInvert = _telemetrySource is IArcadeForceSource;
            // Farming Simulator arms by GAME, not by bus dynamics: on every
            // wheel we have traced, FS streams no force values at all (G923:
            // parametric springs; G PRO: a constant heartbeat that only
            // misdecodes), so spring rendering owns FS force feedback
            // outright and a captured "scalar" there is by definition a
            // misdecode, never a reason to disarm.
            bool fsGame = _activeGame != null
                && _activeGame.StartsWith("FarmingSimulator", StringComparison.Ordinal);

            if (_forceMode == ForceModeSpring)
            {
                bool scalar = !fsGame && tap != null && tap.TryGetFreshFfbTarget(2000).HasValue;
                // FS spring rendering never touches the tap (synthetic model
                // + steering reader only), so a tap hiccup (EndOfStream
                // crash, liveness kill, both observed once per session) must
                // not disarm it: the disarm/re-arm round trip used to open a
                // 1 s+ mode-0 window mid-drive, wheel limp then pass-through
                // (2026-08-08 review). Non-FS spring games DO render from the
                // tap's captured springs, so they keep the liveness gate.
                bool tapGone = (tap == null || !tap.IsRunning) && !fsGame;
                if (!toggleOn || tapGone || scalar)
                {
                    _forceMode = ForceModeOff;
                    AssertSpringModeStandDown();
                    _springArmCandidateSinceTicks = 0;
                    // Anything the tap captured while armed was IGNORED (the
                    // spring path replaces the target), so it must not be
                    // served by the pass-through that resumes now. On FS this
                    // was a wheel-slam: the misdecoded heartbeat scalar
                    // stayed "fresh" for up to 10 s after the game closed
                    // and pass-through drove the wheel to full lock with it.
                    //
                    // The SCALAR half only, not the full ClearLastFfbTarget
                    // this used to call. The game is mid-session here, not
                    // paused, and the full reset also wiped the decoded
                    // effect table: the engine's additive copy of the very
                    // spring this mode was rendering went with it, and Forza
                    // sends its menu spring once and leaves it playing, so
                    // the autocenter stayed silent for the rest of the
                    // session. The pause and game-change callers keep the
                    // full reset, where a wipe is what is wanted.
                    tap?.ClearCapturedForceKeepingEffects();
                    SimHub.Logging.Current.Info("[TF4ALL] Spring mode disarmed"
                        + (scalar ? " (the game is streaming force values; pass-through resumes)." : "."));
                }
                return;
            }

            if (_forceMode != ForceModeOff) { _springArmCandidateSinceTicks = 0; return; }
            bool springOnlyBus = tap != null && tap.IsRunning
                && tap.AnyClassicSpringPlaying
                && !tap.TryGetFreshFfbTarget(2000).HasValue;
            // fsGame arms without the tap (same reasoning as the disarm
            // branch: FS rendering is tap-independent).
            if (!toggleOn || !(fsGame || springOnlyBus))
            {
                _springArmCandidateSinceTicks = 0;
                return;
            }

            long now = Stopwatch.GetTimestamp();
            if (_springArmCandidateSinceTicks == 0) { _springArmCandidateSinceTicks = now; return; }
            if (now - _springArmCandidateSinceTicks < Stopwatch.Frequency) return;   // 1 s dwell
            _springArmCandidateSinceTicks = 0;
            _springRamp = 0f;
            _springRampPrevTicks = 0;
            _forceMode = ForceModeSpring;
            AssertSpringModeStandDown();
            SimHub.Logging.Current.Info(fsGame
                ? "[TF4ALL] Spring mode armed for Farming Simulator: the plugin's steering model "
                  + "replaces the game's force feedback on every wheel, rendered at the wheel's "
                  + "physical position."
                : "[TF4ALL] Spring mode armed: the game commands spring-based force feedback "
                  + "(no streamed values); rendering the game's spring from the wheel's physical position.");
        }

        // ---- Terrain feel (spring-mode enhancement #1) ----------------------
        //
        // No machinery of its own: the FS enhanced source fills the frame's
        // SuspTravelM quad, DispatchFrame runs the SAME RoadKickModel +
        // _mbKickCached pipeline Mode B's road kick uses (its own compute
        // site there, because FS frames carry suspension without slip
        // quads), and ComputeSpringModeForce consumes the cached kick with
        // the same short EMA. One model, one cache, both games.

        // ---- TF4ALL Enhanced Telemetry game mod install (Farming Simulator) ---------
        //
        // The enhanced FS telemetry needs a mod in the game's own mods
        // folder (a game constraint; FS loads mods from nowhere else). The
        // per-generation zips travel EMBEDDED in this assembly so a plain
        // DLL deploy carries them. Offer model (owner spec 2026-08-07): a
        // one-time dialog on the first FS session; declining only silences
        // the DIALOG. The offer never goes away: the Telemetry FFB tab
        // banner carries it while a spring game runs without the mod, and
        // the Settings tab's Game Mods card carries it always. After one
        // accepted install, newer plugin versions refresh the file silently
        // (the consent was to the file, not to one version of it).
        private const string FsModVersion = "0.2.24";
        private bool _fsModPromptShown;   // once per SimHub session

        /// <summary>Maps a Farming Simulator game name to its mods folder and
        /// the embedded zip for that generation. False for FS titles we do
        /// not ship a mod for (FS19 is a different scripting-API vintage,
        /// pending validation).</summary>
        private static bool TryGetFsModInfo(string game, out string modsDir, out string resource)
        {
            modsDir = null; resource = null;
            string folder;
            switch (game)
            {
                case "FarmingSimulator25":
                    folder = "FarmingSimulator2025";
                    resource = "TrueforceForAll.Plugin.TF4ALLTelemetry_FS25.zip";
                    break;
                case "FarmingSimulator22":
                    folder = "FarmingSimulator2022";
                    resource = "TrueforceForAll.Plugin.TF4ALLTelemetry_FS22.zip";
                    break;
                default:
                    return false;
            }
            try
            {
                string docs = Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments);
                string gameDir = Path.Combine(docs, "My Games", folder);
                modsDir = Path.Combine(gameDir, "mods");
                // FS lets players relocate their mods folder (gameSettings.xml
                // modsDirectoryOverride), and heavy modders use it. Installing
                // into the default folder would LOOK successful while the game
                // never loads the mod, so honor the override when active.
                try
                {
                    string gs = Path.Combine(gameDir, "gameSettings.xml");
                    if (File.Exists(gs))
                    {
                        var el = System.Xml.Linq.XDocument.Load(gs).Root?.Element("modsDirectoryOverride");
                        if (el != null && string.Equals((string)el.Attribute("active"), "true",
                                StringComparison.OrdinalIgnoreCase))
                        {
                            string dir = (string)el.Attribute("directory");
                            if (!string.IsNullOrWhiteSpace(dir)) modsDir = dir.Trim();
                        }
                    }
                }
                catch { /* malformed settings file: fall back to the default folder */ }
                return true;
            }
            catch { return false; }
        }

        /// <summary>The Telemetry FFB tab banner's state for the active FS
        /// game: 0 = enhanced telemetry feeding (nothing to say), 1 = mod not
        /// installed (offer the install), 2 = mod installed but the game is
        /// not running it (it needs enabling in the game's mod screen; we can
        /// tell because SimHub's own mod IS feeding, so the game runs, while
        /// our pipe is silent), 3 = not an FS session or the game is not
        /// running (say nothing), 4 = feeding but from an older mod version
        /// than the plugin refreshed onto disk (restart the game to load
        /// it).</summary>
        public int FsEnhancedTelemetryState()
        {
            if (_activeGame == null
                || !_activeGame.StartsWith("FarmingSimulator", StringComparison.Ordinal))
                return 3;
            var fs = _fsPipeSource;
            if (fs != null && fs.MsSinceLastFrame < 3000)
            {
                // The refresh runs on game detection, always after the game
                // scanned its mods folder, so an update trails by one game
                // restart, and a user who skips it silently misses new mod
                // features. Pre-0.2.11 mods don't report a version; they read
                // as current.
                string rep = fs.ReportedModVersion;
                if (!string.IsNullOrEmpty(rep)
                    && !string.Equals(rep, FsModVersion, StringComparison.Ordinal))
                    return 4;
                return 0;
            }
            if (!IsFsModInstalledForActiveGame()) return 1;
            bool gameFeedingSimHub = _simHubSource != null && _simHubSource.MeasuredHz > 0;
            return gameFeedingSimHub ? 2 : 3;
        }

        /// <summary>Take the mod back out for a NAMED game. Returns null on
        /// success, else a short human-readable reason.
        ///
        /// The counterpart to InstallFsMod: we write a file into somebody else's
        /// game folder, so we should be able to take it back out without asking
        /// them to go find it.
        ///
        /// Two pieces of bookkeeping travel with the delete. The install offer is
        /// marked declined, because MaybeOfferFsModInstall fires the dialog
        /// whenever the file is absent: re-offering next session would be arguing
        /// with someone who has just told us what they want. The version stamp
        /// goes with the file it describes, so no later install is read against
        /// a stamp for a mod that is not there. The tab banner still carries the
        /// offer, so nothing is lost, it just stops interrupting.</summary>
        public string UninstallFsMod(string game)
        {
            if (!TryGetFsModInfo(game, out string modsDir, out _))
                return "this game is not supported yet";
            try
            {
                string target = Path.Combine(modsDir, "TF4ALLTelemetry.zip");
                if (File.Exists(target)) File.Delete(target);

                var s = Settings;
                if (s != null)
                {
                    if (s.FsModInstalledVersions != null) s.FsModInstalledVersions.Remove(game);
                    s.FsModInstallDeclined = true;
                    PersistSettingsCore();
                }
                SimHub.Logging.Current.Info(
                    $"[TF4ALL] TF4ALL Enhanced Telemetry game mod removed for {game}.");
                return null;
            }
            catch (IOException)
            {
                // The game holds its mods open while it runs.
                return "the file is in use, so close Farming Simulator and try again";
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Warn(
                    "[TF4ALL] Could not remove the TF4ALL Enhanced Telemetry game mod: " + ex.Message);
                return ex.Message;
            }
        }

        /// <summary>One Farming Simulator title we ship a mod for, as the standing
        /// install control on the Settings tab needs it.</summary>
        // ---- Arcade cabinets (TeknoParrot): the publishing FFB plugin ----
        //
        // This installs a forked build of FFBArcadePlugin into an arcade game's own
        // folder and switches it to publish-only, so the cabinet's force feedback
        // comes to us instead of being driven straight at the wheel. That is what
        // frees the wheel's lights and screen, which cannot be written while
        // something else is pushing force down the same endpoint.
        //
        // It differs from the Farming Simulator mod in one way that matters: we are
        // REPLACING a file the user may already have put there themselves, rather
        // than adding one of ours. So this keeps a backup of whatever was there and
        // restores it on removal, which the FS installer has no need to do.

        private const string ArcadeModVersion = "1.0.0";
        public string ArcadeModVersionString => ArcadeModVersion;

        // FFBArcadePlugin is ONE binary that gets renamed per game, because a
        // wrapper DLL is only loaded if the game actually imports that name. Their
        // own setup script renames it to whichever of these the title uses:
        // opengl32 for the Lindbergh games (Initial D 4 and 5), d3d9 or d3d11 for
        // the Direct3D ones, winmm for Cruis'n Blast, dinput8 for the rest.
        //
        // So we do not choose the name, we DISCOVER it: whichever of these is
        // already sitting in the game's folder is the one that game loads, and it
        // is the file we replace.
        private static readonly string[] ArcadeWrapperNames =
        {
            "dinput8.dll", "opengl32.dll", "d3d9.dll", "d3d11.dll", "winmm.dll",
        };

        /// <summary>Which file in this game's folder is FFBArcadePlugin, or null.
        ///
        /// Verified by content, not just by name: a game can legitimately ship its
        /// own opengl32 or d3d9, and overwriting one of those would break the game
        /// rather than redirect its force feedback. Every build of that plugin
        /// reads FFBPlugin.ini, so the name appears inside the binary, and no real
        /// graphics runtime carries it.</summary>
        private static string FindArcadeWrapper(string dir)
        {
            foreach (var name in ArcadeWrapperNames)
            {
                try
                {
                    string p = Path.Combine(dir, name);
                    if (!File.Exists(p)) continue;
                    var fi = new FileInfo(p);
                    if (fi.Length > 32 * 1024 * 1024) continue;   // not a wrapper
                    byte[] bytes = File.ReadAllBytes(p);
                    if (IndexOfAscii(bytes, "FFBPlugin.ini") >= 0) return name;
                }
                catch { }
            }
            return null;
        }

        private static int IndexOfAscii(byte[] haystack, string needle)
        {
            if (haystack == null || string.IsNullOrEmpty(needle)) return -1;
            int n = needle.Length;
            for (int i = 0; i + n <= haystack.Length; i++)
            {
                int j = 0;
                while (j < n && haystack[i + j] == (byte)needle[j]) j++;
                if (j == n) return i;
            }
            return -1;
        }
        private const string ArcadeBackupSuffix = ".tf4all-backup";
        private const string ArcadeIniName = "FFBPlugin.ini";

        public sealed class ArcadeModTarget
        {
            public string ProfileName;   // TeknoParrot's own profile id, e.g. ID8
            public string FullName;      // TeknoParrot's GameNameInternal, e.g. Initial D: Arcade Stage 8 Infinity
            public string DisplayName;   // as a person would say it
            public string GameDir;       // where the game exe lives, and where the DLL goes
            public bool Is64Bit;
            public string WrapperName;   // which DLL name this cabinet loads us as, e.g. opengl32.dll
            public string ExeName;       // the game executable, without extension, for spotting it running
            public bool PublishModeOn;   // the game is actually configured to publish to us
            public bool HasStamp;        // we recorded installing into this game
            public bool GameFound;       // that folder is on this PC
            public bool IniFound;        // FFBPlugin.ini is beside the game
            public bool Installed;       // our build is the one sitting there
        }

        /// <summary>Where TeknoParrot lives, or null. Prefers a remembered path,
        /// then a running TeknoParrot, then the handful of places people put it.
        /// Whatever it finds is written back to settings so the search happens
        /// once rather than on every refresh.</summary>
        private string FindTeknoParrotRoot()
        {
            var s = Settings?.Arcade;
            try
            {
                string saved = s?.TeknoParrotPath;
                if (!string.IsNullOrEmpty(saved) && Directory.Exists(Path.Combine(saved, "UserProfiles")))
                    return saved;
            }
            catch { }

            var candidates = new List<string>();
            try
            {
                // A running TeknoParrot is the most reliable answer there is.
                foreach (var p in Process.GetProcessesByName("TeknoParrotUi"))
                {
                    try { candidates.Add(Path.GetDirectoryName(p.MainModule.FileName)); }
                    catch { }
                    finally { try { p.Dispose(); } catch { } }
                }
            }
            catch { }

            try
            {
                foreach (var d in DriveInfo.GetDrives())
                {
                    if (!d.IsReady) continue;
                    candidates.Add(Path.Combine(d.RootDirectory.FullName, "TeknoParrot"));
                }
                candidates.Add(Path.Combine(
                    Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "TeknoParrot"));
            }
            catch { }

            foreach (var c in candidates)
            {
                try
                {
                    if (string.IsNullOrEmpty(c)) continue;
                    if (!Directory.Exists(Path.Combine(c, "UserProfiles"))) continue;
                    if (s != null && !string.Equals(s.TeknoParrotPath, c, StringComparison.OrdinalIgnoreCase))
                    {
                        s.TeknoParrotPath = c;
                        try { PersistSettingsCore(); } catch { }
                    }
                    return c;
                }
                catch { }
            }
            return null;
        }

        /// <summary>Every cabinet TeknoParrot has a profile for, whether its files
        /// are on this PC and whether our publishing plugin is already in place.
        /// Reads the same folder the install writes to, so what the card says is
        /// what the game will find.</summary>
        public List<ArcadeModTarget> ArcadeModTargets()
        {
            var list = new List<ArcadeModTarget>();
            // Shelved with the rest of the arcade path, and this is the choke point for it: every
            // other caller reaches TeknoParrot through here, so one empty list closes the Game
            // mods cards, the custom-game profile lookup, the cabinet title and ActiveArcadeTarget
            // at once. It also stops the WORK, which is the part worth stopping: the root finder
            // enumerates processes and probes paths, and this then parses every profile XML on
            // disk. None of that should happen on a build that will not read a cabinet.
            if (!ArcadeUnlocked) return list;

            string root = FindTeknoParrotRoot();
            if (root == null) return list;

            string profiles = Path.Combine(root, "UserProfiles");
            string[] files;
            try { files = Directory.GetFiles(profiles, "*.xml"); }
            catch { return list; }

            foreach (var f in files)
            {
                try
                {
                    var doc = System.Xml.Linq.XDocument.Load(f);
                    var r = doc.Root;
                    if (r == null) continue;
                    string profileName = (string)r.Element("ProfileName");
                    string fullName = (string)r.Element("GameNameInternal");
                    string gamePath = (string)r.Element("GamePath");
                    if (string.IsNullOrEmpty(gamePath)) continue;

                    string dir = null;
                    try { dir = Path.GetDirectoryName(gamePath); } catch { }
                    if (string.IsNullOrEmpty(dir)) continue;

                    bool is64 = string.Equals((string)r.Element("Is64Bit"), "true",
                                              StringComparison.OrdinalIgnoreCase);

                    var t = new ArcadeModTarget
                    {
                        ProfileName = string.IsNullOrEmpty(profileName)
                            ? Path.GetFileNameWithoutExtension(f) : profileName,
                        FullName = fullName,
                        GameDir = dir,
                        Is64Bit = is64,
                        ExeName = Path.GetFileNameWithoutExtension(gamePath),
                    };
                    t.DisplayName = "TeknoParrot: " + t.ProfileName;
                    // An unreadable folder reads as not found, which is honest.
                    try { t.GameFound = Directory.Exists(dir); } catch { }
                    try { t.IniFound = t.GameFound && File.Exists(Path.Combine(dir, ArcadeIniName)); } catch { }
                    if (t.GameFound) t.WrapperName = FindArcadeWrapper(dir);
                    // Read the setting rather than assume it. Anything that
                    // rewrites the ini (a fresh FFBArcadePlugin setup over the
                    // top, a restored config, a hand edit) turns publishing off
                    // while our file and our stamp both stay put, and the card
                    // would otherwise keep saying Installed at a silent wheel.
                    if (t.IniFound)
                    {
                        try
                        {
                            string v = IniKeyWriter.GetKey(
                                File.ReadAllText(Path.Combine(dir, ArcadeIniName)), "Settings", "SharedMemoryOutput");
                            t.PublishModeOn = v == "2";
                        }
                        catch { }
                    }

                    string stamped = null;
                    var vers = Settings?.Arcade?.ModInstalledVersions;
                    if (vers != null) vers.TryGetValue(t.ProfileName, out stamped);
                    t.HasStamp = !string.IsNullOrEmpty(stamped);
                    try
                    {
                        t.Installed = t.GameFound
                            && !string.IsNullOrEmpty(stamped)
                            && !string.IsNullOrEmpty(t.WrapperName)
                            && File.Exists(Path.Combine(dir, t.WrapperName))
                            && t.PublishModeOn;
                    }
                    catch { }

                    list.Add(t);
                }
                catch { }
            }
            list.Sort((a, b) => string.Compare(a.ProfileName, b.ProfileName, StringComparison.OrdinalIgnoreCase));
            return list;
        }

        /// <summary>Puts our publishing build beside the game and switches it to
        /// publish-only. Returns null on success, else a short human reason.</summary>
        public string InstallArcadeMod(ArcadeModTarget t)
        {
            if (t == null || string.IsNullOrEmpty(t.GameDir)) return "that game is not set up in TeknoParrot";
            if (!Directory.Exists(t.GameDir)) return "the game's folder was not found";

            if (string.IsNullOrEmpty(t.WrapperName))
                return "FFBArcadePlugin was not found in this game's folder, so set that up there first";
            string dll = Path.Combine(t.GameDir, t.WrapperName);
            string ini = Path.Combine(t.GameDir, ArcadeIniName);
            if (!File.Exists(ini))
                return "FFBPlugin.ini was not found beside the game, so run it once in TeknoParrot first";

            string resource = t.Is64Bit
                ? "TrueforceForAll.Plugin.FfbArcade.dinput8_x64.dll"
                : "TrueforceForAll.Plugin.FfbArcade.dinput8_x86.dll";

            try
            {
                // Keep whatever was already there. Only ever taken ONCE, so a
                // second install cannot overwrite the user's original with our own
                // previous build.
                string backup = dll + ArcadeBackupSuffix;
                if (File.Exists(dll) && !File.Exists(backup))
                    File.Copy(dll, backup, false);

                WriteEmbeddedResource(resource, dll);
                string err = SetArcadeIniValue(ini, "SharedMemoryOutput", "2");
                if (err != null) return err;
                SetArcadeWheelSelection(t, ini);

                var vers = Settings?.Arcade?.ModInstalledVersions;
                if (vers != null) vers[t.ProfileName] = ArcadeModVersion;
                try { PersistSettingsCore(); } catch { }
                SimHub.Logging.Current.Info(
                    $"[TF4ALL] Arcade publishing plugin installed for '{t.ProfileName}' in {t.GameDir}.");
                return null;
            }
            catch (IOException)
            {
                return "the file is in use, so close the game and try again";
            }
            catch (UnauthorizedAccessException)
            {
                return "no permission to write to the game's folder";
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Warn($"[TF4ALL] Arcade plugin install failed: {ex}");
                return ex.Message;
            }
        }

        /// <summary>Puts the game back as it was: restores whatever DLL we replaced,
        /// or removes ours when there was nothing to restore, and turns publishing
        /// off again. Returns null on success, else a short human reason.</summary>
        public string UninstallArcadeMod(ArcadeModTarget t)
        {
            if (t == null || string.IsNullOrEmpty(t.GameDir)) return "that game is not set up in TeknoParrot";

            if (string.IsNullOrEmpty(t.WrapperName)) return "nothing of ours is installed there";
            string dll = Path.Combine(t.GameDir, t.WrapperName);
            string backup = dll + ArcadeBackupSuffix;
            string ini = Path.Combine(t.GameDir, ArcadeIniName);

            try
            {
                if (File.Exists(backup))
                {
                    File.Copy(backup, dll, true);
                    File.Delete(backup);
                }
                else if (File.Exists(dll))
                {
                    File.Delete(dll);
                }

                // Only touch the key we set. Their own tuning stays theirs.
                if (File.Exists(ini)) SetArcadeIniValue(ini, "SharedMemoryOutput", "0");

                var vers = Settings?.Arcade?.ModInstalledVersions;
                if (vers != null) vers.Remove(t.ProfileName);
                try { PersistSettingsCore(); } catch { }
                SimHub.Logging.Current.Info(
                    $"[TF4ALL] Arcade publishing plugin removed for '{t.ProfileName}'.");
                return null;
            }
            catch (IOException)
            {
                return "the file is in use, so close the game and try again";
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Warn($"[TF4ALL] Arcade plugin removal failed: {ex}");
                return ex.Message;
            }
        }

        // Sets one key in the [Settings] section of an ini, in place, leaving every
        // other line exactly as it was. Written by hand rather than with a parser
        // because this is someone else's configuration file: their comments,
        // ordering and spacing are theirs to keep, and a round-tripped rewrite would
        // quietly reformat all of it.
        // ---- The active cabinet's own settings file ----
        //
        // The panel edits FFBPlugin.ini directly rather than keeping a copy of
        // these values. They belong to the plugin that applies them: it reads that
        // file, our build re-reads it when it changes, and its own GUI edits the
        // same keys the same way. One file, one truth, and nothing to drift.

        /// <summary>Is the arcade path available at all on this install?
        ///
        /// Off unless the ARCADE access code has been typed; see ArcadeSettings.Enabled for why
        /// the whole path is shelved. Every arcade entry point asks this, so there is exactly one
        /// thing to turn back on: cabinet identity, both force sources, the memory map, the
        /// leaderboards and the SimHub bridge.</summary>
        public bool ArcadeUnlocked => Settings?.Arcade?.Enabled == true;

        /// <summary>True while an emulated arcade cabinet is the active game.
        /// Drives the FFB tab's arcade panel.
        ///
        /// Reads false while the path is locked, which is what keeps the arcade panel, the
        /// ID8 memory telemetry, the cabinet car id and the arcade invert behaviour off a
        /// shipping build without each of them needing its own check.</summary>
        public bool ActiveGameIsArcade => ArcadeUnlocked && IsArcadeGameName(_activeGame);

        /// <summary>The arcade cabinet matching the active game, or null.</summary>
        public ArcadeModTarget ActiveArcadeTarget()
        {
            string game = _activeGame;
            if (!IsArcadeGameName(game)) return null;
            try
            {
                foreach (var t in ArcadeModTargets())
                    if (string.Equals(ArcadeGameName(t.ProfileName), game, StringComparison.Ordinal))
                        return t;
            }
            catch { }
            return null;
        }

        /// <summary>Read one [Settings] value from the active cabinet's ini, or the
        /// fallback when the file, the key or the cabinet is missing.</summary>
        public int ArcadeIniGetInt(string key, int fallback)
        {
            string raw = ArcadeIniGetRaw(key);
            int v;
            return int.TryParse(raw, out v) ? v : fallback;
        }

        /// <summary>The raw string for a key, or null when it is absent. Null and
        /// "0" are different answers: a control for a key this game never declares
        /// should be hidden, not shown reading zero.</summary>
        public string ArcadeIniGetRaw(string key)
        {
            var t = ActiveArcadeTarget();
            if (t == null || !t.IniFound) return null;
            try
            {
                return IniKeyWriter.GetKey(
                    File.ReadAllText(Path.Combine(t.GameDir, ArcadeIniName)), "Settings", key);
            }
            catch { return null; }
        }

        /// <summary>Write one [Settings] value into the active cabinet's ini,
        /// leaving every other byte alone. Returns null on success, else a short
        /// human reason.</summary>
        public string ArcadeIniSet(string key, string value)
        {
            var t = ActiveArcadeTarget();
            if (t == null) return "no arcade game is active";
            if (!t.IniFound) return "that game has no FFBPlugin.ini";
            return SetArcadeIniValue(Path.Combine(t.GameDir, ArcadeIniName), key, value);
        }

        /// <summary>True when an arcade cabinet has handed the wheel over to us,
        /// so its HID++ pipe is free for the lights and the screen.
        ///
        /// The base rule for freeing those surfaces needs an armed force mode, and
        /// the arcade path is pass-through like Assetto Corsa's, so it fails that
        /// rule for the same reason AC did and needs the same kind of exception.
        /// This one rests on firmer ground than AC's: there the game might still
        /// write and we watch the wire to see whether it does, while here its
        /// output is suppressed inside its own process and the publisher tells us
        /// so directly.</summary>
        public bool ArcadePipeFree()
        {
            var pub = _teknoSource as FfbArcadePluginSource;
            return pub != null && pub.HandedOver && MasterMode == TrueforceMasterMode.Normal;
        }

        /// <summary>Which route the force is arriving by, for the panel to say so
        /// plainly. The two behave differently enough that a user debugging a quiet
        /// wheel needs to know which one they are on.</summary>
        /// <summary>Turn the arcade effect trace on or off (the ARCADEFX access
        /// code). Returns what to tell the user.</summary>
        public string SetArcadeEffectTrace(bool on)
        {
            var pub = _teknoSource as FfbArcadePluginSource;
            var jvs = _teknoSource as TeknoParrotJvsTelemetrySource;
            if (pub == null && jvs == null)
                return "no arcade cabinet is running, so there is nothing to trace yet. "
                     + "Start the game and enter the code again.";
            if (pub != null) pub.TraceEffects = on;
            if (jvs != null) jvs.TraceCommands = on;
            string route = pub != null ? "the arcade plugin's output" : "the cabinet IO block";
            return on
                ? "ARCADEFX on, tracing " + route + ". Drive a corner, then turn the wheel through a "
                  + "menu, then send the log. Each line names the effects that are live and which way "
                  + "the signed ones push."
                : "ARCADEFX off.";
        }

        public string ArcadeRouteLabel()
        {
            if (_teknoSource is FfbArcadePluginSource) return "the arcade plugin's own output";
            if (_teknoSource is TeknoParrotJvsTelemetrySource) return "the cabinet's IO block, decoded here";
            return null;
        }

        /// <summary>Re-points every cabinet we installed into at the wheel that is
        /// connected now.
        ///
        /// Install is not the only moment this matters. Someone can install with
        /// the wheel unplugged, or swap one wheel for another later, and in both
        /// cases the games would keep naming a device that is not there. The
        /// symptom is the worst kind: the game runs, the plugin loads, and the
        /// wheel is simply silent.
        ///
        /// Only cabinets carrying our stamp are touched, so a game the user set up
        /// themselves is never edited, and only when the value actually differs, so
        /// this rewrites nothing on a normal start. Device selection is read once
        /// when a game loads, so a change reaches a game already running at its
        /// next launch, not immediately.</summary>
        public void RefreshArcadeWheelSelection()
        {
            if (_hidWheelVid == 0 || _hidWheelPid == 0) return;
            var s = Settings?.Arcade;
            if (s == null || !s.Enabled) return;

            string vidpid = $"{_hidWheelVid:X4}:{_hidWheelPid:X4}";
            int changed = 0;

            foreach (var t in ArcadeModTargets())
            {
                if (t == null || !t.HasStamp || !t.IniFound) continue;
                string ini = Path.Combine(t.GameDir, ArcadeIniName);
                try
                {
                    string have = IniKeyWriter.GetKey(File.ReadAllText(ini), "Settings", "DeviceVidPid");
                    if (string.Equals(have, vidpid, StringComparison.OrdinalIgnoreCase)) continue;
                    if (SetArcadeIniValue(ini, "DeviceVidPid", vidpid) == null) changed++;
                }
                catch { }
            }

            if (changed > 0)
            {
                SimHub.Logging.Current.Info(
                    $"[TF4ALL] Pointed {changed} arcade game(s) at your wheel ({vidpid}). "
                    + "Any of them already running will pick it up next launch.");
            }
        }

        /// <summary>Tells the arcade plugin which wheel to use, by writing the one
        /// we are already connected to.
        ///
        /// This is the whole reason a first install used to end with a silent
        /// wheel. That plugin selects its device by SDL joystick GUID, which is not
        /// printed on the hardware, is not in Device Manager, and cannot be
        /// computed from what anyone knows about the device: it embeds a checksum
        /// of the device NAME. The usual way to obtain one is to run the game once
        /// and read it out of a log.
        ///
        /// But we do not need it. We are talking to this wheel over USB right now,
        /// so we know its vendor and product id for certain, and a GUID already
        /// CONTAINS both. Our build of that plugin accepts them directly, so we
        /// write what we know and nothing has to be guessed or discovered.</summary>
        private void SetArcadeWheelSelection(ArcadeModTarget t, string iniPath)
        {
            try
            {
                if (_hidWheelVid != 0 && _hidWheelPid != 0)
                {
                    string vidpid = $"{_hidWheelVid:X4}:{_hidWheelPid:X4}";
                    string err = SetArcadeIniValue(iniPath, "DeviceVidPid", vidpid);
                    if (err == null)
                    {
                        SimHub.Logging.Current.Info(
                            $"[TF4ALL] '{t.ProfileName}' pointed at your wheel ({vidpid}).");
                        return;
                    }
                    SimHub.Logging.Current.Info(
                        $"[TF4ALL] Could not point '{t.ProfileName}' at your wheel: {err}.");
                }

                // No wheel connected right now, so fall back to copying a GUID from
                // a cabinet that already has one.
                BorrowArcadeDeviceGuid(t, iniPath);
            }
            catch { }
        }

        /// <summary>Fills in this game's DeviceGUID from another cabinet that
        /// already has one, when it is blank.
        ///
        /// A blank one is not a harmless default: it produces a zero GUID that
        /// matches no device, and that plugin does not stop when nothing matches.
        /// It opens no wheel, every effect id comes back invalid, and the game then
        /// runs perfectly while the wheel sits silent with nothing anywhere saying
        /// why. It is the single most confusing way this can fail.
        ///
        /// Copied from a sibling rather than computed, because an SDL joystick GUID
        /// embeds a checksum of the device name and we would be guessing. If any of
        /// this user's other cabinets has a working one, it is the same wheel, so it
        /// is the right answer and it is already sitting on disk.</summary>
        private void BorrowArcadeDeviceGuid(ArcadeModTarget t, string iniPath)
        {
            try
            {
                string mine = IniKeyWriter.GetKey(File.ReadAllText(iniPath), "Settings", "DeviceGUID");
                if (!string.IsNullOrEmpty(mine)) return;

                foreach (var other in ArcadeModTargets())
                {
                    if (other == null || !other.IniFound) continue;
                    if (string.Equals(other.ProfileName, t.ProfileName, StringComparison.OrdinalIgnoreCase)) continue;
                    string otherIni = Path.Combine(other.GameDir, ArcadeIniName);
                    string guid = null;
                    try { guid = IniKeyWriter.GetKey(File.ReadAllText(otherIni), "Settings", "DeviceGUID"); }
                    catch { }
                    if (string.IsNullOrEmpty(guid)) continue;

                    string err = SetArcadeIniValue(iniPath, "DeviceGUID", guid);
                    SimHub.Logging.Current.Info(err == null
                        ? $"[TF4ALL] '{t.ProfileName}' had no wheel selected, so it was given the one "
                          + $"'{other.ProfileName}' already uses."
                        : $"[TF4ALL] '{t.ProfileName}' has no wheel selected and it could not be filled in: {err}.");
                    return;
                }

                // Nobody has one to lend. Say what to do rather than leave a wheel
                // that will be silent for a reason nothing reports.
                SimHub.Logging.Current.Info(
                    $"[TF4ALL] '{t.ProfileName}' has no wheel selected (DeviceGUID is blank) and no other "
                    + "cabinet has one to copy. That game will run with a silent wheel until one is set: "
                    + "run FFBPluginGUI.exe in its folder once and pick your wheel.");
            }
            catch { }
        }

        // Sets one key in the [Settings] section of FFBPlugin.ini, leaving every
        // other byte alone. The editing itself lives in Core (IniKeyWriter) so it
        // can be tested: this is someone else's tuning file, and "nothing else
        // moved" is a claim that needs proving rather than asserting.
        private static string SetArcadeIniValue(string iniPath, string key, string value)
        {
            try
            {
                string text = File.ReadAllText(iniPath);
                string error;
                string updated = IniKeyWriter.SetKey(text, "Settings", key, value, out error);
                if (updated == null) return "FFBPlugin.ini could not be updated: " + error;
                if (!string.Equals(updated, text, StringComparison.Ordinal))
                    File.WriteAllText(iniPath, updated);
                return null;
            }
            catch (IOException)
            {
                return "FFBPlugin.ini is in use, so close the game and try again";
            }
            catch (Exception ex)
            {
                return ex.Message;
            }
        }

        public sealed class FsModTarget
        {
            public string Game;          // SimHub game name
            public string DisplayName;   // as a person would say it
            public bool GameFound;       // its mods folder is on this PC
            public bool Installed;       // our mod is sitting in it
        }

        /// <summary>Every Farming Simulator title we ship a mod for, whether it is
        /// on this PC, and whether the mod is already there. Reads the same folder
        /// (override included) that the install writes to, so what the control says
        /// is what the game will find.</summary>
        public List<FsModTarget> FsModTargets()
        {
            var list = new List<FsModTarget>();
            AddFsModTarget(list, "FarmingSimulator25", "Farming Simulator 25");
            AddFsModTarget(list, "FarmingSimulator22", "Farming Simulator 22");
            return list;
        }

        private static void AddFsModTarget(List<FsModTarget> list, string game, string name)
        {
            var t = new FsModTarget { Game = game, DisplayName = name };
            if (TryGetFsModInfo(game, out string modsDir, out _))
            {
                try
                {
                    t.GameFound = Directory.Exists(modsDir);
                    t.Installed = t.GameFound
                        && File.Exists(Path.Combine(modsDir, "TF4ALLTelemetry.zip"));
                }
                catch { /* unreadable folder: reads as not found, which is honest */ }
            }
            list.Add(t);
        }

        /// <summary>True when the active game either has our mod installed or
        /// is not a game we ship one for. The tab banner shows on false.</summary>
        public bool IsFsModInstalledForActiveGame()
        {
            string game = _activeGame;
            if (!TryGetFsModInfo(game, out string modsDir, out _)) return true;
            try
            {
                if (!Directory.Exists(modsDir)) return true;   // game not on this PC: nothing to offer
                return File.Exists(Path.Combine(modsDir, "TF4ALLTelemetry.zip"));
            }
            catch { return true; }
        }

        /// <summary>Install (or refresh) the mod for the active game. Returns
        /// null on success, else a short human-readable reason. Called from the
        /// banner's Install button, the first-session dialog and the silent refresh.</summary>
        public string InstallFsModForActiveGame() => InstallFsMod(_activeGame);

        /// <summary>Install (or refresh) the mod for a NAMED game, so the settings
        /// UI can offer it for a title that is not running (the mods folder is on
        /// disk whether or not the game is open).</summary>
        public string InstallFsMod(string game)
        {
            if (!TryGetFsModInfo(game, out string modsDir, out string resource))
                return "this game is not supported yet";
            try
            {
                if (!Directory.Exists(modsDir))
                    return "the game's mods folder was not found";
                string target = Path.Combine(modsDir, "TF4ALLTelemetry.zip");
                using (var res = typeof(TrueforcePlugin).Assembly.GetManifestResourceStream(resource))
                {
                    if (res == null) return "the mod is missing from this plugin build";
                    using (var f = new FileStream(target, FileMode.Create, FileAccess.Write))
                        res.CopyTo(f);
                }
                var s = Settings;
                if (s != null)
                {
                    if (s.FsModInstalledVersions == null)
                        s.FsModInstalledVersions = new Dictionary<string, string>();
                    s.FsModInstalledVersions[game] = FsModVersion;
                    PersistSettingsCore();
                }
                SimHub.Logging.Current.Info(
                    $"[TF4ALL] TF4ALL Enhanced Telemetry game mod installed for {game} (loads on the game's next start).");
                return null;
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Warn("[TF4ALL] Could not install the TF4ALL Enhanced Telemetry game mod: " + ex.Message);
                return ex.Message;
            }
        }

        private void MaybeOfferFsModInstall()
        {
            var s = Settings;
            if (s == null || _fsModPromptShown) return;
            string game = _activeGame;
            if (!TryGetFsModInfo(game, out string modsDir, out _)) return;
            try { if (!Directory.Exists(modsDir)) return; } catch { return; }

            _fsModPromptShown = true;

            bool installed = false;
            try { installed = File.Exists(Path.Combine(modsDir, "TF4ALLTelemetry.zip")); } catch { }
            if (installed)
            {
                // Silent refresh: consent was given when the file first went in.
                string stamped = null;
                s.FsModInstalledVersions?.TryGetValue(game, out stamped);
                if (!string.IsNullOrEmpty(stamped)
                    && !string.Equals(stamped, FsModVersion, StringComparison.Ordinal)
                    && InstallFsModForActiveGame() == null)
                {
                    SimHub.Logging.Current.Info(
                        $"[TF4ALL] TF4ALL Enhanced Telemetry game mod updated to {FsModVersion}.");
                }
                return;
            }
            if (s.FsModInstallDeclined) return;   // dialog silenced; the tab banner carries the offer

            try
            {
                System.Windows.Application.Current?.Dispatcher?.BeginInvoke((Action)(() =>
                {
                    try
                    {
                        bool? ok = TrueforceDialog.Show(null,
                            "Install the TF4ALL Farming Simulator Enhanced Telemetry Mod?",
                            "This mod provides more telemetry than SimHub receives from the game: "
                            + "per-wheel suspension, ground contact, and more, at up to 100 Hz "
                            + "where SimHub delivers 10 Hz (60 Hz with a licensed SimHub). This "
                            + "unlocks Telemetry Based FFB enhancements to the game's force "
                            + "feedback, such as Terrain feel. It works alongside SimHub's own "
                            + "telemetry mod; keep both enabled in the game's mod list.",
                            DialogKind.Confirm, "Install", "Not now",
                            goldOk: true, quietCancel: true);
                        var st = Settings;
                        if (st == null) return;
                        if (ok == true)
                        {
                            // Both outcomes need a word: a failure must say
                            // why and point at the standing retry (the
                            // Telemetry FFB tab banner), and a success must
                            // say the game reads its mods only at startup.
                            string err = InstallFsModForActiveGame();
                            if (err != null)
                                TrueforceDialog.Show(null, "Install failed",
                                    "The mod could not be installed: " + err + ". "
                                    + "You can retry from the banner on the Telemetry FFB tab.",
                                    DialogKind.Error);
                            else
                                TrueforceDialog.Show(null, "Mod installed",
                                    "It loads the next time Farming Simulator starts, so restart "
                                    + "the game if it is running now. The plugin picks it up by "
                                    + "itself; no SimHub restart is needed.",
                                    DialogKind.Info);
                        }
                        else
                        {
                            // Silences only this dialog; the Telemetry FFB tab
                            // banner keeps offering until the mod is installed.
                            st.FsModInstallDeclined = true;
                            PersistSettingsCore();
                        }
                    }
                    catch (Exception ex)
                    {
                        SimHub.Logging.Current.Warn("[TF4ALL] FS mod install prompt failed: " + ex.Message);
                    }
                }));
            }
            catch { }
        }

        // Our own centering for FS wheels the game gives no spring commands
        // to (the G PRO gets a constant heartbeat, trace-proven 2026-08-07).
        // Curve shape is the Center firmness slider's job (soft quadratic to
        // near-linear); this constant only sets full lock = this fraction of
        // full scale. The shared Damping slider provides the stability half.
        private const float SyntheticFsSpringStrength = 0.6f;

        // Evaluate the steering spring at the wheel's physical position: in
        // Farming Simulator always the plugin's own model, everywhere else
        // the game's own captured spring. Null when the position is stale
        // (or, outside FS, the tap is gone): rendering a spring against a
        // frozen position would hold a constant torque.
        private short? EvaluateClassicSpringForce()
        {
            var s = Settings;
            if (s == null || !s.ClassicSpringEmulationEnabled) return null;
            var sr = _steeringReader;
            if (sr == null || sr.LastUpdateTicks == 0) return null;
            if (Stopwatch.GetTimestamp() - sr.LastUpdateTicks > SteerMaxAgeTicks) return null;
            // The tap is only needed BELOW, for rendering a non-FS game's own
            // captured springs; the FS synthetic model must keep rendering
            // through tap restarts (EndOfStream crash / liveness kill).

            // Farming Simulator: ALWAYS the plugin's model, on every wheel
            // (owner call 2026-08-08). Classic-protocol wheels (G923) do
            // receive readable game springs here, but rendering those on one
            // wheel family and our tunable model on another split the feel
            // and made the centering sliders dead on half the hardware. One
            // model everywhere; the captured decode still feeds arming
            // diagnostics on non-FS classic-spring games below.
            if (_activeGame != null
                && _activeGame.StartsWith("FarmingSimulator", StringComparison.Ordinal))
            {
                // Telemetry-freshness gate: between frames stopping and the
                // game-changed disarm a rendered spring pushes the wheel with
                // no game attached (both close-the-game pulls). No frames for
                // 1.5 s = no synthetic spring; menus keep it alive (the SimHub
                // fallback still emits frames there), and the 100 ms spring
                // ramp turns the cut into a fade.
                long lastFrame = System.Threading.Interlocked.Read(ref _lastFrameTicks);
                if (lastFrame == 0
                    || Stopwatch.GetTimestamp() - lastFrame > SpringTelemetryMaxAgeTicks)
                    return null;

                // Mod users: the spring ALSO dies with the pipe itself. The
                // gate above rides _lastFrameTicks, which the SimHub source
                // keeps stamping with the dead game's frozen data for
                // seconds after a close (GameRunning lags process death),
                // and that window is exactly where every game-close pull
                // lived. If the mod fed this game session and has gone
                // silent, no spring, regardless of who is stamping frames.
                // Menus stay alive (the mod keeps sending inVehicle=false
                // frames there); quit-to-main-menu correctly goes limp.
                var fsPipe = _fsPipeSource;
                if (fsPipe != null && _fsPipeFedThisGame
                    && fsPipe.MsSinceLastFrame > 1500)
                    return null;

                float steer = sr.SteerNorm;
                if (steer > 1f) steer = 1f; else if (steer < -1f) steer = -1f;
                // Speed-scaled centering: real steering lightens toward
                // standstill (self-aligning torque vanishes) and firms with
                // road speed. The floor keeps a parked wheel from going
                // fully limp; full strength from 30 km/h.
                // Centering strength: user-tunable, and 0 is a REAL off (the
                // rest of spring mode, damper, terrain, effects, keeps
                // running on the zero force).
                float centerGain = (float)(s.SpringModeCenterGain);
                if (centerGain < 0.01f) return (short)0;

                float spd = _lastSpeedKmh;
                if (spd < 0f) spd = 0f;
                float ramp01 = Math.Min(spd / 30f, 1f);
                // Speed effect slider: 0 = constant centering at all speeds,
                // 1 = fully speed-scaled (limp standstill). The standstill
                // floor is (1 - this), so the 0.70 default holds 30%.
                float speedFx = (float)s.SpringModeSpeedEffect;
                if (speedFx < 0f) speedFx = 0f; else if (speedFx > 1f) speedFx = 1f;
                float speedScale = (1f - speedFx) + speedFx * ramp01;
                // Center firmness slider: the curve's linear fraction near
                // straight-ahead (0 = soft quadratic, 1 = crisp). At rest
                // that fraction is 0.7 x this (59.5% on the 0.85 default),
                // morphing to 80% at speed. Separate from strength: this
                // shapes WHERE the force lives, not how much there is.
                float firm = (float)s.SpringModeCenterFirmness;
                if (firm < 0f) firm = 0f; else if (firm > 1f) firm = 1f;
                float mag = Math.Abs(steer);
                float linBase = 0.7f * firm;
                float linFrac = linBase + (0.8f - linBase) * ramp01;
                float shape = mag + (1f - mag) * linFrac;
                // Same sign space as the spring evaluator and the stationary
                // spring: steer right of center produces a positive
                // (leftward, centering) force.
                float f01 = steer * shape * SyntheticFsSpringStrength * centerGain * speedScale;

                // Min force on the spring, deflection- and speed-gated (owner
                // ask): light centering lifts above a belt wheel's internal
                // friction so the center doesn't read dead on a G923.
                // Straight-ahead (|steer| <= 0.03) stays unremapped (chatter),
                // and the floor scales with the speed ramp so a parked wheel
                // stays limp (the Speed effect contract). Drag and cornering
                // weight multiply AFTER this, inheriting the floored value.
                float minSpring = s != null ? (float)s.SpringModeMinForce : 0f;
                if (minSpring > 0f && mag > 0.03f && f01 != 0f)
                {
                    if (minSpring > 0.5f) minSpring = 0.5f;
                    float minEff = minSpring * speedScale;
                    if (minEff > 0f)
                        f01 = (float)ModeBComposer.MinForceRemap(f01, minEff);
                }

                // Feedback-sanity guard (the game-close pull, 2026-08-08,
                // trace-proven). A centering spring is negative feedback; at
                // teardown the loop can turn positive and drive the wheel INTO
                // lock at full push for seconds. Detect the impossible state
                // (large sustained push with the wheel parked at full lock)
                // and let go until it comes off the lock.
                //
                // Gated on mod-pipe liveness (stuck-at-lock report,
                // 2026-08-09): force and position alone cannot tell that pull
                // from a hand holding full lock, and with default sliders the
                // force threshold is crossed from ~12 km/h, so the ungated
                // latch fired mid-drive and parked the wheel at the stop. A
                // pipe frame within the last 500 ms proves the game is running
                // (the mod goes silent within a frame of process death), so
                // the force is the driver's hand: never latch, and release any
                // latch already held (a pipe hiccup can latch legitimately;
                // recovery must not wait for the hand). Fallback sessions keep
                // the ungated guard: SimHub re-emits the dead game's frozen
                // frames for seconds after a close, so freshness proves
                // nothing there and this guard is that population's only
                // defense against the pull.
                bool pipeLive = fsPipe != null && _fsPipeFedThisGame
                    && fsPipe.MsSinceLastFrame < 500;
                long nowLs = Stopwatch.GetTimestamp();
                if (_springLockStallLatched)
                {
                    if (pipeLive || mag < 0.85f) _springLockStallLatched = false;
                    else return null;
                }
                if (!pipeLive && mag >= 0.95f && Math.Abs(f01) > 0.35f)
                {
                    if (_springLockStallStartTicks == 0)
                        _springLockStallStartTicks = nowLs;
                    else if (nowLs - _springLockStallStartTicks > Stopwatch.Frequency * 35 / 100)
                    {
                        _springLockStallLatched = true;
                        _springLockStallStartTicks = 0;
                        SimHub.Logging.Current.Info(
                            "[TF4ALL] Spring suppressed: pushing hard against a wheel parked at full lock "
                            + "(fighting an external force, likely the game releasing the wheel); "
                            + "re-engages when the wheel comes off the lock.");
                        return null;
                    }
                }
                else _springLockStallStartTicks = 0;

                int v = (int)(f01 * 32767f);
                if (v > short.MaxValue) v = short.MaxValue;
                else if (v < short.MinValue) v = short.MinValue;
                return (short)v;
            }

            // Non-FS classic-spring games (e.g. FH5's autocenter when the
            // bus-driven arming engages): render the game's own captured
            // spring, its parameters are its real intent there.
            var tap = _ffbTap;
            if (tap == null || !tap.IsRunning) return null;
            return tap.TryEvaluateClassicSprings(sr.SteerNorm);
        }

        // Spring mode's engage/stall ramp. Mode B's _mbRamp is driven by
        // Forza slip-sample freshness, which a spring game never feeds, so
        // spring mode keeps its own: force ramps in over ~250 ms while the
        // spring evaluates, out over ~100 ms when it stops (spring gone,
        // position stale, capture dead). The reshape damper is scaled by the
        // same ramp, so disengage fades rather than steps. Runs on the pump
        // thread only.
        private float _springRamp;
        private long  _springRampPrevTicks;
        // Lock-stall guard state (pump thread only, no sync needed): see the
        // feedback-sanity guard in EvaluateClassicSpringForce.
        private long  _springLockStallStartTicks;
        private bool  _springLockStallLatched;

        // Hybrid drag weighting (owner call): full engine-load weight while
        // something is actually WORKING (implement lowered or powered on, per
        // the mod's impl flag), a user-tunable fraction (Engine strain slider)
        // under plain strain so acceleration still adds a touch of weight.
        // Pre-0.2.6 mods don't report the flag (ImplementActive == null) and
        // keep the ungated full weight. Both drag consumers (spring scale +
        // damper thickening) read through this.
        private float EffectiveDragLoad01()
        {
            var fs = _fsPipeSource;
            float load = fs?.MotorLoad01 ?? -1f;
            if (load <= 0f) return -1f;
            if (fs.ImplementActive.HasValue)
            {
                // Loadedness blend (owner design): a working implement counts
                // in full, otherwise the best attached fill fraction raises
                // the strain floor continuously, so a filling grain trailer
                // grows into full drag weight with no threshold cliff. The
                // Engine strain slider is the floor; magnitude stays engine
                // load's job (a full-but-light load stays light).
                float loadedness = fs.ImplementActive == true ? 1f : fs.AttachedFill01;
                if (loadedness < 0f) loadedness = 0f; else if (loadedness > 1f) loadedness = 1f;
                float frac = (float)(Settings?.SpringModeDragStrainFraction ?? 0.35);
                if (frac < 0f) frac = 0f; else if (frac > 1f) frac = 1f;
                load *= frac + (1f - frac) * loadedness;
            }
            return load;
        }
        private float _springKickEma;   // pump-thread EMA over the shared road-kick cache
        private long  _ptKickPrevTicks; // pass-through terrain's own dt tracker (pump thread)
        // Freshness stamp for the FS kick compute: frames stopping (game
        // closing) must let the kick DECAY, not hold its last value against
        // the wheel; the death-spike freeze pulled hard for seconds.
        private long  _fsKickStampTicks;   // Interlocked; 32-bit host

        private short ComputeSpringModeForce()
        {
            long now = Stopwatch.GetTimestamp();
            double dtMs = _springRampPrevTicks == 0
                ? 1.0
                : (now - _springRampPrevTicks) * 1000.0 / Stopwatch.Frequency;
            if (dtMs < 0.05) dtMs = 0.05; else if (dtMs > 50.0) dtMs = 50.0;
            _springRampPrevTicks = now;

            short? f = EvaluateClassicSpringForce();
            _springRamp += f.HasValue ? (float)(dtMs / 250.0) : (float)(-dtMs / 100.0);
            if (_springRamp < 0f) _springRamp = 0f; else if (_springRamp > 1f) _springRamp = 1f;
            if (_springRamp <= 0f || !f.HasValue) return 0;

            var s = Settings;
            float spring = f.Value;

            // Enhancement scaling on the SPRING component only (terrain and
            // the ramp stay unscaled). Implement drag rides engine load;
            // cornering weight rides yaw-derived lateral G (v * yawRate via
            // the mod's chassis rates). No data means scale 1.0.
            if (s != null)
            {
                float scale = 1f;
                if (s.SpringModeDragEnabled)
                {
                    float load = EffectiveDragLoad01();
                    if (load > 0f) scale += load * (float)s.SpringModeDragGain * 0.8f;
                }
                if (s.SpringModeChassisWeightEnabled)
                {
                    float latG = Math.Abs(_lastSwayAccel) / 9.81f;
                    if (latG > 2f) latG = 2f;
                    scale += latG * (float)s.SpringModeChassisWeightGain * 0.5f;
                }
                spring *= scale;
            }

            // Terrain kick (spring-mode enhancement #1): the shared road-kick
            // cache, computed in DispatchFrame from the FS source's suspension
            // quad, consumed here through the same short EMA Mode B's force
            // path uses so 60 Hz telemetry steps do not land as clicks.
            // Kick full scale at gain 1.0 = half of full force, mirroring the
            // Mode B mapping.
            float terrainLsb = 0f;
            if (s != null && s.SpringModeTerrainEnabled)
            {
                // Stale cache (pause, game closing) decays to zero.
                long kStamp = System.Threading.Interlocked.Read(ref _fsKickStampTicks);
                float kickTarget = (kStamp != 0 && now - kStamp < Stopwatch.Frequency / 4)
                    ? _mbKickCached : 0f;
                float kickAlpha = (float)(1.0 - Math.Exp(-dtMs / 8.0));
                _springKickEma += (kickTarget - _springKickEma) * kickAlpha;
                terrainLsb = _springKickEma * (float)s.SpringModeTerrainGain * 0.5f * 32767f;

                // Min force on the kick channel: faint terrain transients lift
                // above a belt wheel's internal friction. FS's own floor
                // (SpringModeMinForce, per-game by owner call); the spring's
                // gated floor is in EvaluateClassicSpringForce, damping stays
                // unremapped (chatter).
                float minF = (float)s.SpringModeMinForce;
                if (minF > 0f && terrainLsb != 0f)
                {
                    if (minF > 0.5f) minF = 0.5f;
                    terrainLsb = (float)(ModeBComposer.MinForceRemap(
                        terrainLsb / 32767.0, minF) * 32767.0);
                }
            }
            else _springKickEma = 0f;

            // Overall strength (the FS Strength slider): scales the composed
            // force, never the damper, so turning it down does not also
            // remove stability.
            float strength = s != null ? (float)s.SpringModeStrength : 1f;
            if (strength < 0f) strength = 0f;

            int v = (int)Math.Round((spring + terrainLsb) * strength * _springRamp);
            if (v > short.MaxValue) v = short.MaxValue;
            else if (v < short.MinValue) v = short.MinValue;
            return (short)v;
        }

        // Stationary-spring setters. Settings-only: the FfbTargetProvider
        // lambda reads them every tick so changes apply live. Persistence is
        // the caller's: the UI marks the section dirty, Save commits it.
        // The stationary spring is per game: the checkbox and sliders edit the
        // active game's entry. The checkbox persists immediately (one event); the
        // sliders let the UI debounce the disk write.
        public void SetStationarySpringEnabled(bool v)
        {
            var e = SpringEntryForActive(create: true);
            if (e == null) return;
            e.Enabled = v;
            if (Settings != null) Settings.StationarySpringEnabled = v;   // snapshot field
            try { PersistSettings(); } catch { }
        }
        public void SetStationarySpringStrength(double v)
        { var e = SpringEntryForActive(create: true); if (e != null) e.Strength = v; }
        public void SetStationarySpringCutoffKmh(double v)
        { var e = SpringEntryForActive(create: true); if (e != null) e.CutoffKmh = v; }

        // The active game's spring entry, optionally creating it seeded from the
        // current effective values so a fresh entry is self-contained.
        private StationarySpringGameConfig SpringEntryForActive(bool create)
        {
            var s = Settings;
            if (s == null || string.IsNullOrEmpty(_activeGame)) return null;
            if (s.StationarySpringByGame == null)
                s.StationarySpringByGame = new Dictionary<string, StationarySpringGameConfig>();
            if (!s.StationarySpringByGame.TryGetValue(_activeGame, out var e))
            {
                if (!create) return null;
                e = new StationarySpringGameConfig
                {
                    Enabled   = EffectiveStationarySpringEnabled(_activeGame),
                    Strength  = EffectiveStationarySpringStrength(_activeGame),
                    CutoffKmh = EffectiveStationarySpringCutoff(_activeGame),
                };
                s.StationarySpringByGame[_activeGame] = e;
            }
            return e;
        }

        /// <summary>The spring's on/off for a game: its entry if one exists, else
        /// OFF. It is an option, not a default (owner, 2026-09-13): offered in
        /// Assetto Corsa and RaceRoom, both rig-validated on every route, and
        /// the user ticks it where they want it.
        ///
        /// Elsewhere the whole thing is behind the SPRING access code while it is
        /// tested game by game. Locked, a saved per-game entry is IGNORED rather
        /// than honoured: a tester who unlocks, tunes a game, then locks again
        /// must get the shipped behaviour back, or the gate proves nothing. The
        /// entry survives, so unlocking returns their tuning.</summary>
        public bool EffectiveStationarySpringEnabled(string game)
        {
            var s = Settings;
            if (!StationarySpringShipsIn(game) && !(s?.StationarySpringUnlocked ?? false)) return false;
            if (s?.StationarySpringByGame != null && !string.IsNullOrEmpty(game)
                && s.StationarySpringByGame.TryGetValue(game, out var e) && e != null)
                return e.Enabled;
            return false;
        }

        /// <summary>The games the spring is offered in (off until ticked), and
        /// where the SPRING lock does not apply. One list, read by the force
        /// path, the checkbox gate and the badge.</summary>
        private static bool StationarySpringShipsIn(string game)
            => string.Equals(game, "AssettoCorsa", StringComparison.OrdinalIgnoreCase)
               || IsR3EGame(game)
               || IsLmuGame(game)
               || IsForzaGameName(game);   // Telemetry Based FFB only; the capture route excludes it

        /// <summary>The spring's strength for a game: its entry, else that game's
        /// default, else the shared default (the top-level StationarySpringStrength).</summary>
        public double EffectiveStationarySpringStrength(string game)
        {
            var s = Settings;
            if (s == null) return 0.5;
            if (s.StationarySpringByGame != null && !string.IsNullOrEmpty(game)
                && s.StationarySpringByGame.TryGetValue(game, out var e) && e != null)
                return e.Strength;
            return DefaultStationarySpringStrength(game, s.StationarySpringStrength);
        }

        /// <summary>Per-game starting strength for a game with no saved entry.
        /// RaceRoom needs about three times the shared default: on the USB tap
        /// route the game's own parked-wheel damping comes through with its
        /// force, and the spring has to move the wheel against that damping to
        /// be felt at all. 0.5 was barely there; 1.5 felt right (owner, on the
        /// rig, 2026-09-12). Only fresh entries see this; a game the user has
        /// tuned keeps its entry.</summary>
        private static double DefaultStationarySpringStrength(string game, double shared)
        {
            if (IsR3EGame(game)) return 1.5;
            return shared;
        }

        /// <summary>The spring's fade-out speed for a game: its entry, else the
        /// shared default (the top-level StationarySpringCutoffKmh).</summary>
        public double EffectiveStationarySpringCutoff(string game)
        {
            var s = Settings;
            if (s == null) return 12.0;
            if (s.StationarySpringByGame != null && !string.IsNullOrEmpty(game)
                && s.StationarySpringByGame.TryGetValue(game, out var e) && e != null)
                return e.CutoffKmh;
            return s.StationarySpringCutoffKmh;
        }

        // What the FFB tab's spring controls read for the active game.
        public bool   StationarySpringEnabledForActiveGame  => EffectiveStationarySpringEnabled(_activeGame);
        public double StationarySpringStrengthForActiveGame => EffectiveStationarySpringStrength(_activeGame);
        public double StationarySpringCutoffForActiveGame   => EffectiveStationarySpringCutoff(_activeGame);

        /// <summary>Clear the "shown once / dismissed forever" latches so the
        /// one-time notices can appear again (networked welcome, what's new,
        /// iRacing Trueforce, stepped-aside, MAIRA tap, AC CSP setup offer,
        /// Telemetry Based FFB intro, share CTA). Persists.</summary>
        public void ResetOneTimeNotices()
        {
            if (Settings == null) return;
            Settings.HasSeenNetworkedWelcome = false;
            Settings.WelcomeDeclineCount = 0;
            Settings.WelcomeNextShowAt = null;
            Settings.IRacingTrueforceNoticeDismissed = false;
            // RaceRoom's handover notice and its once-a-session guard, which the
            // button had missed since the notice was added.
            Settings.R3ETrueforceNoticeDismissed = false;
            _r3eNoticeShownThisSession = false;
            Settings.LmuTrueforceNoticeDismissed = false;
            _lmuNoticeShownThisSession = false;
            // The stepped-aside notice, for every game it was dismissed in, and
            // its once-per-demotion guard.
            Settings.StandDownNoticeDismissedGames?.Clear();
            _standDownNoticeShownThisDemotion = false;
            Settings.MairaTapNoticeDismissed = false;
            _mairaTapWarned = false;
            // Re-arm the Assetto Corsa CSP setup offer (its dismiss latch doubles
            // as the notice latch) and its once-a-session guard.
            Settings.CspBridgeInstallDeclined = false;
            _acCspNoticeShownThisSession = false;
            // Re-arm the Telemetry Based FFB (Mode B) intro so it shows again the
            // next time a supported game's tab is opened. The WELCOME dev code
            // clears this too; keep the two paths in sync.
            Settings.HasSeenModeBIntro = false;
            Settings.ShareCtaDismissed = false;
            Settings.LastSeenVersion = null;
            PersistSettings();
        }

        // Fast gate on the baseline FFB path: when the spring is off AND no
        // desk self-test is armed, return the game's FFB target untouched
        // WITHOUT entering the spring logic at all (one atomic read + a bool),
        // keeping the stationary spring out of the FFB regression surface for
        // the common feature-off case. ApplyStationarySpring keeps its own
        // equivalent guards too, so it's still correct if called directly.
        private short? ApplyStationarySpringIfActive(short? gameTarget)
        {
            // FXTEST owns the wheel while it runs: the parked-car spring
            // would contaminate the very feel being compared.
            if (_fxTestMode != 0) return gameTarget;
            bool testArmed = System.Threading.Interlocked.Read(ref _springTestEndTicks) != 0;
            var s = Settings;
            if (!testArmed && (s == null || !EffectiveStationarySpringEnabled(_activeGame)))
                return gameTarget;
            short? sprungOut = ApplyStationarySpring(gameTarget);
            _lastSpringAddLsb = sprungOut.HasValue ? sprungOut.Value - (gameTarget ?? 0) : 0;
            return sprungOut;
        }

        /// <summary>What the stationary spring added to the last frame's force, in
        /// LSB. Diagnostic only: the spring and the soft lock are deliberately
        /// independent now, and three attempts at coupling them all failed.</summary>
        private int _lastSpringAddLsb;


        // Stationary-spring FFB floor. The plugin streams the game's own FFB
        // to the motor; a parked car produces ~0 self-aligning torque, so the
        // wheel goes limp. This tops the centering force up to a desired
        // magnitude that fades out by a low cutoff speed. It only ever fills a
        // DEFICIT in the game's same-direction force, never reduces or opposes
        // it, so it cannot fight the game's FFB and auto-disengages the moment
        // the game does its own centering or the car starts moving.
        //
        // Returns the (possibly augmented) target in the GAME's FFB sign space
        // (FfbInvertSign / FfbScale / spike taming are applied downstream in
        // TrueforceDevice, so the spring rides through the same chain).
        // No-ops, returning the input unchanged, when: disabled; the game
        // sends no target; iRacing (the sim already produces real standstill
        // weight); any Forza session (see the exclusion below); steering is
        // stale from both the game and the physical reader; or already at or
        // above the cutoff speed.
        private short? ApplyStationarySpring(short? gameTarget, bool inSynthesis = false)
        {
            // SPRING desk self-test: while the deadline is in the future,
            // synthesize a centering force with a simulated wheel position
            // that flips direction every ~1.5 s, so the user feels the spring
            // push one way then the other without a game. Bypasses every
            // normal gate (enabled / game / speed / steering freshness).
            long springTestEnd = System.Threading.Interlocked.Read(ref _springTestEndTicks);
            if (springTestEnd != 0)
            {
                long nowSt = Stopwatch.GetTimestamp();
                if (nowSt >= springTestEnd)
                {
                    System.Threading.Interlocked.CompareExchange(ref _springTestEndTicks, 0, springTestEnd);
                }
                else
                {
                    var ts = Settings;
                    double remainSec  = (springTestEnd - nowSt) / (double)Stopwatch.Frequency;
                    double elapsedSec = SpringTestDurationSec - remainSec;
                    float steerT = ((int)(elapsedSec / 1.5) % 2 == 0) ? 0.8f : -0.8f;
                    float strengthT = Math.Max(0.4f, (float)EffectiveStationarySpringStrength(_activeGame));
                    const float MaxLsbT = 32767f;
                    float ffbScaleT = _device != null ? _device.FfbScale : 1f;
                    if (ffbScaleT < 0.05f) ffbScaleT = 0.05f;
                    float desiredMagT = strengthT * Math.Abs(steerT) * MaxLsbT / ffbScaleT;
                    float dirT = (steerT > 0f) ? 1f : -1f;
                    int baseT = gameTarget ?? 0;
                    int resultT = baseT + (int)(desiredMagT * dirT);
                    if (resultT >  32767) resultT =  32767;
                    else if (resultT < -32768) resultT = -32768;
                    return (short)resultT;
                }
            }

            var s = Settings;
            if (s == null || !EffectiveStationarySpringEnabled(_activeGame)) return gameTarget;
            if (!gameTarget.HasValue) return gameTarget;
            // iRacing and arcade cabinets, both stated once in
            // ActiveGameAllowsStationarySpring so the FFB tab hides the control
            // on exactly the same rule that skips it here.
            if (!ActiveGameAllowsStationarySpring) return gameTarget;
            // Armed takeover or Telemetry Based FFB: MaybeReshapeFfb assigns
            // over whatever this returns, so the spring is rendered THERE (the
            // wantReshapeSpring block in the takeover's own sign and scale; a
            // call back into this method with inSynthesis for the synthesis,
            // whose sign space is the same as the tap's). Anything added here
            // would be computed and thrown away.
            if (!inSynthesis && (_forceMode == ForceModeIRacing || _forceMode == ForceModeModeB
                                 || _forceMode == ForceModeSpring))
                return gameTarget;   // spring mode assigns over the chain too, and renders no spring of ours
            // Forza exclusion (user's call, 2026-05-28). The spring conflicted
            // with Forza's FFB during the matchmaking-found transition and
            // could pull the wheel to the rotational stop, sometimes with
            // violent back-and-forth against it. The interaction was never
            // isolated (direction is correct in normal use, and several
            // narrower gates failed to catch the case), so the whole Forza
            // session is bypassed. Gate on the SESSION, not the active source:
            // a Forza session running on the SimHub fallback (Data Out pointed
            // at SimHub) reports source SimHub, yet must still stay excluded.
            // The conflict was with the game's own force on the CAPTURE route.
            // Under Telemetry Based FFB that force is not on the wire, so the
            // spring is offered there (owner, 2026-09-13).
            if (InForzaSession && !inSynthesis)
                return gameTarget;

            // Steering source. Prefer the GAME's value: it shares the game's
            // own FFB reference frame, so the spring and the game's forces
            // agree (AC reports a high-rate angle whenever the sim runs,
            // stationary or moving, engine on or off). Switch to the wheel's
            // PHYSICAL position only when game steering is stale (sim paused
            // / telemetry stopped) or an authoritative-session source reports
            // paused while frames keep coming (Forza zeros steering through
            // the pre-race countdown / pause): no live game FFB to fight
            // there. Physical WHILE driving fought the game's own FFB near
            // center (different reference frames) -> jerky.
            long now = Stopwatch.GetTimestamp();
            long gameAge = now - System.Threading.Interlocked.Read(ref _lastSteerTicks);
            var src2 = _telemetrySource;
            bool authoritativePaused = (src2?.HasAuthoritativeSessionState ?? false)
                                       && !(src2?.IsSessionActive ?? true);
            bool gameStale = gameAge > SteerMaxAgeTicks;
            var sr = _steeringReader;
            bool physFresh = sr != null && sr.LastUpdateTicks != 0
                             && (now - sr.LastUpdateTicks) <= SteerMaxAgeTicks;
            float steerRaw;
            if (!gameStale && !authoritativePaused)
                steerRaw = _lastSteerNorm;          // game is tracking the wheel: use it (smooth)
            else if (physFresh)
                steerRaw = sr.SteerNorm;            // paused / countdown: physical position
            else if (!gameStale)
                steerRaw = _lastSteerNorm;          // no physical reader; fall back to game value
            else
                return gameTarget;                  // no steering at all

            float cutoff = (float)EffectiveStationarySpringCutoff(_activeGame);
            float speed  = _lastSpeedKmh;
            if (cutoff <= 0f || speed >= cutoff) return gameTarget;

            if (steerRaw >  1f) steerRaw =  1f;
            else if (steerRaw < -1f) steerRaw = -1f;

            // Low-pass the position so a coarse (8-bit) source doesn't notch
            // the force and so we interpolate between telemetry updates. We
            // only reach here while the spring is actively engaged, so the EMA
            // updates every provider call; a stale gap resumes from the last
            // value and re-converges within the time constant.
            _springSteerEma += SpringSteerEmaAlpha * (steerRaw - _springSteerEma);
            float steer = _springSteerEma;

            // Linear speed fade: full at standstill, zero at cutoff. The
            // deficit-fill below is the primary safety mechanism; this fade
            // is a belt-and-braces backstop so the spring is provably gone
            // by the time real cornering forces exist.
            float fade = 1f - (speed / cutoff);
            if (fade <= 0f) return gameTarget;

            // Desired centering magnitude (FFB LSB). Strength is a fraction of
            // full *felt* scale at full lock while parked; scales with |steer|
            // so there's no notch at center and it grows as you wind lock on.
            const float MaxLsb = 32767f;
            float desiredMag = (float)EffectiveStationarySpringStrength(_activeGame)
                             * Math.Abs(steer) * fade * MaxLsb;
            if (desiredMag < 1f) return gameTarget;

            // Pre-compensate the downstream FfbScale: TrueforceDevice
            // multiplies everything we return by it, so without this the
            // user's FFB-strength trim (default 0.80) silently caps the
            // spring below full scale. Dividing makes strength=1.0 land at
            // true full motor torque. Floor the divisor so a tiny FfbScale
            // can't explode it (the ±32767 clamp below is the real net).
            float ffbScale = _device != null ? _device.FfbScale : 1f;
            if (ffbScale < 0.05f) ffbScale = 0.05f;
            desiredMag /= ffbScale;

            // Re-centering direction in the game's FFB sign space. The
            // steer->FFB sign relationship is wheel/protocol AND source
            // dependent: confirmed correct on AC + G PRO (the un-inverted form
            // pushed away from center). A source that re-centers the wrong way
            // should flip its own SteeringAngle sign, not special-case here.
            float dir = (steer > 0f) ? 1f : -1f;

            int g = gameTarget.Value;
            // Deficit-fill: only the game force already pushing the SAME way as
            // our centering counts toward the floor. Top it up to desiredMag,
            // never beyond, never against, so the spring can't fight the game's
            // own FFB and self-disengages once the game centers.
            float have = (Math.Sign((float)g) == Math.Sign(dir)) ? Math.Abs((float)g) : 0f;
            float add  = desiredMag - have;
            if (add <= 0f) return gameTarget;                // game already centers enough

            int result = g + (int)(add * dir);
            if (result >  32767) result =  32767;
            else if (result < -32768) result = -32768;
            return (short)result;
        }

        /// <summary>Set or clear the audio-capture exe override for a game.
        /// Pass null/whitespace to clear. Drops any currently-captured
        /// process so the next capture tick re-evaluates against the new
        /// override within ~1 s.</summary>
        public void SetAudioCaptureExeOverride(string game, string exe)
        {
            if (Settings == null || string.IsNullOrEmpty(game)) return;
            if (Settings.AudioCaptureExeOverrides == null)
                Settings.AudioCaptureExeOverrides = new Dictionary<string, string>();

            string trimmed = exe?.Trim();
            if (!string.IsNullOrEmpty(trimmed) && trimmed.EndsWith(".exe", StringComparison.OrdinalIgnoreCase))
                trimmed = trimmed.Substring(0, trimmed.Length - 4);

            if (string.IsNullOrEmpty(trimmed))
                Settings.AudioCaptureExeOverrides.Remove(game);
            else
                Settings.AudioCaptureExeOverrides[game] = trimmed;

            PersistSettingsCore();

            // Force a re-scan: drop the cached process so the next CaptureTick
            // doesn't fast-path the alive-check on the wrong process.
            var prev = System.Threading.Interlocked.Exchange(ref _capturedProcess, null);
            if (prev != null)
            {
                try { prev.Dispose(); } catch { }
                try { _audio?.Stop(); } catch { }
                try { _helperHost?.SetTargetPid(0); } catch { }
            }
        }

        /// <summary>The exe override currently configured for the active
        /// game (or null if none). Used by the UI to populate the textbox.</summary>
        public string ActiveCaptureExeOverride
        {
            get
            {
                if (string.IsNullOrEmpty(_activeGame) || Settings?.AudioCaptureExeOverrides == null) return null;
                return Settings.AudioCaptureExeOverrides.TryGetValue(_activeGame, out var v) ? v : null;
            }
        }

        /// <summary>Trigger an effect's test playback. Forces the device into
        /// active ep3 mode for the duration so the test is audible with no game
        /// running (no FFB tap data, so the stream would otherwise be keepalive).
        /// Drives effect.TestUpdate(phase) at ~60 Hz over the test window so
        /// effects can simulate dynamic behavior (RPM ramps, slip pulses, etc).</summary>
        public void TestEffect(TelemetryEffect effect) => RunEffectTest(effect, null);

        /// <summary>Shared test runner: <paramref name="start"/> arms the effect
        /// and returns its duration (null = the effect's own TestPlay). Holds
        /// the device active for the run, drives TestUpdate at ~60 Hz, and
        /// resets the effect when it ends.</summary>
        private void RunEffectTest(TelemetryEffect effect, Func<int> start)
        {
            if (effect == null)
            {
                SimHub.Logging.Current.Info("[TF4ALL] TestEffect: effect was null");
                return;
            }
            if (_device == null)
            {
                SimHub.Logging.Current.Info($"[TF4ALL] TestEffect '{effect.Name}': device not initialized");
                return;
            }
            int durationMs = start != null ? start() : effect.TestPlay();
            SimHub.Logging.Current.Info($"[TF4ALL] TestEffect '{effect.Name}' duration={durationMs} ms");
            if (durationMs <= 0) return;

            _device.ForceActiveFor(durationMs + 200);

            long startTicks = DateTime.UtcNow.Ticks;
            long endTicks   = startTicks + durationMs * TimeSpan.TicksPerMillisecond;
            System.Threading.Interlocked.Increment(ref _activeTestTasks);
            System.Threading.Tasks.Task.Run(() =>
            {
                try
                {
                    while (DateTime.UtcNow.Ticks < endTicks && !_shuttingDown)
                    {
                        long now = DateTime.UtcNow.Ticks;
                        double elapsedMs = (now - startTicks) / (double)TimeSpan.TicksPerMillisecond;
                        double phase = Math.Min(1.0, Math.Max(0, elapsedMs / durationMs));
                        try { effect.TestUpdate(phase); } catch { }
                        Thread.Sleep(16);  // ~60 Hz update rate
                    }
                }
                catch { }
                finally
                {
                    // Clear any state TestPlay/TestUpdate latched (amplitudes,
                    // envelopes, hold timers). Without this, ABS Pulse leaves
                    // _amp = ActiveAmp*Gain set and, with no telemetry to zero
                    // it (no game running), it keeps rendering into later tests.
                    try { effect.Reset(); } catch { }
                    System.Threading.Interlocked.Decrement(ref _activeTestTasks);
                }
            });
        }

        /// <summary>SPRING access-code test. Opens the device active path and
        /// arms the stationary-spring self-test window (see the synthetic
        /// branch in ApplyStationarySpring): the wheel pushes one way, then the
        /// other, every ~1.5 s for a few seconds, so the user can feel the
        /// spring's strength and force direction on the desk with no game.
        /// Engages regardless of whether the spring is enabled in settings.</summary>
        public void StartStationarySpringTest()
        {
            if (_device == null) return;
            int ms = (int)(SpringTestDurationSec * 1000);
            System.Threading.Interlocked.Exchange(
                ref _springTestEndTicks,
                Stopwatch.GetTimestamp() + (long)(SpringTestDurationSec * Stopwatch.Frequency));
            _device.ForceActiveFor(ms + 200);
        }

        /// <summary>FAULT access-code test: force the live device into the
        /// stream-fault state so the recovery watchdog (MaybeRecoverDevice)
        /// re-attaches it, exercising the "Stream lost, auto-reconnecting"
        /// status + transparent recovery without physically unplugging.</summary>
        public void DebugForceStreamFault() => _device?.DebugForceStreamFault();

        /// <summary>WHATSNEW access-code test: clear the changelog/seen state
        /// so the "What's new" banner and every per-effect NEW badge reappear
        /// (LastSeenVersion "0.0.0" shows the full history). The UI layer
        /// refreshes the banner + badges after calling this.</summary>
        public void DebugResetChangelogSeen()
        {
            if (Settings == null) return;
            Settings.SeenEffects = new System.Collections.Generic.List<string>();
            Settings.LastSeenVersion = "0.0.0";
            PersistSettings();
        }

        /// <summary>"Plugin X, Core Y, Engine Z" with a mismatch flag. The three
        /// assemblies must be deployed as a matched set; a stale Core or Engine
        /// DLL beside a newer Plugin fails silently (dead wheel / missing
        /// effects). Directory.Build.props stamps all three from one version.
        /// EngineLoop lives in Engine, TrueforceDevice in Core, so
        /// typeof(...).Assembly resolves each despite the shared namespace. Used
        /// by the startup cross-check, Export-logs manifest and issue body.</summary>
        internal static string GetAssemblyVersionLine(out bool mismatch)
        {
            mismatch = false;
            try
            {
                var plugin = System.Reflection.Assembly.GetExecutingAssembly().GetName().Version;
                var core   = typeof(TrueforceDevice).Assembly.GetName().Version;
                var engine = typeof(EngineLoop).Assembly.GetName().Version;
                mismatch = !(plugin == core && core == engine);
                // The build stamp: every dev build of a version shares the
                // same number, so a log alone could not say WHICH build a
                // tester ran. The DLL's own write time is set by the build
                // and survives the installer, so it names the build exactly.
                string stamp = "";
                try
                {
                    string path = System.Reflection.Assembly.GetExecutingAssembly().Location;
                    if (!string.IsNullOrEmpty(path) && System.IO.File.Exists(path))
                        stamp = $", built {System.IO.File.GetLastWriteTimeUtc(path):yyyy-MM-dd HH:mm} UTC";
                }
                catch { }
                return $"Plugin {plugin}, Core {core}, Engine {engine}{stamp}";
            }
            catch { return "(unavailable)"; }
        }

        /// <summary>SimHub's own version ("9.11.22"), or null when it can't be
        /// read. Not from the host exe: SimHubWPF.exe ships no version resource
        /// (FileVersion and ProductVersion read 1.0.0.0 on every build, as do
        /// SimHub.Plugins.dll and GameReaderCommon.dll), so the real number lives
        /// only in SimHub's own parsed version, the one its startup log banner
        /// prints. Null rather than a placeholder so callers fall back to
        /// prompting the reporter.</summary>
        internal static string GetSimHubVersion()
        {
            // The property access sits in its own non-inlined method so that on
            // a SimHub build without it, the missing-member failure surfaces
            // when THAT method is JITted, which happens at the call below and
            // therefore inside this try.
            try
            {
                string v = ReadSimHubVersionCore();
                return string.IsNullOrEmpty(v) ? null : v;
            }
            catch { return null; }
        }

        [System.Runtime.CompilerServices.MethodImpl(
            System.Runtime.CompilerServices.MethodImplOptions.NoInlining)]
        private static string ReadSimHubVersionCore()
            => SimHub.Plugins.Configuration.SimHubVersion?.GetVersionAsString();

        /// <summary>Human-readable Windows version ("Windows 11 Home 24H2 build
        /// 26200"). Registry-sourced: Environment.OSVersion is capped by the
        /// host exe's compatibility manifest, so it can under-report. The
        /// CurrentVersion key is WOW64-shared, so the 32-bit SimHub process
        /// reads the real values. ProductName still says "Windows 10" on
        /// Windows 11 installs; build 22000 is the actual boundary.</summary>
        internal static string GetWindowsVersionLine()
        {
            try
            {
                using (var key = Microsoft.Win32.Registry.LocalMachine.OpenSubKey(
                    @"SOFTWARE\Microsoft\Windows NT\CurrentVersion"))
                {
                    if (key == null) return Environment.OSVersion.VersionString;
                    string product = key.GetValue("ProductName") as string ?? "Windows";
                    string display = key.GetValue("DisplayVersion") as string ?? "";
                    string build   = key.GetValue("CurrentBuildNumber") as string ?? "";
                    if (int.TryParse(build, out int buildNum) && buildNum >= 22000)
                        product = product.Replace("Windows 10", "Windows 11");
                    string line = (product + " " + display).Trim();
                    return build.Length > 0 ? $"{line} build {build}" : line;
                }
            }
            catch { return Environment.OSVersion.VersionString; }
        }

        private static void LogAssemblyVersionCrossCheck()
        {
            string line = GetAssemblyVersionLine(out bool mismatch);
            if (!mismatch)
                SimHub.Logging.Current.Info($"[TF4ALL] Assembly versions: {line}.");
            else
                SimHub.Logging.Current.Warn(
                    "[TF4ALL] Assembly version MISMATCH: " + line + ". The Plugin, "
                    + "Core, and Engine DLLs must come from the same build - a stale "
                    + "copy causes silent failures (dead wheel / missing effects). "
                    + "Reinstall via the installer, or copy all three DLLs together.");
        }

        public void Init(PluginManager pluginManager)
        {
            // SimHub injects this property too, but assign it explicitly so it's
            // guaranteed set for code that reads the property rather than the
            // parameter (e.g. TryGetLiveLapDelta, called from DispatchFrame).
            PluginManager = pluginManager;
            // TLS 1.2 process-wide before any network client (auth / community /
            // backup): net48 on older Windows can default to a protocol Supabase
            // rejects. Otherwise it is only set as a side effect of the update check.
            try { System.Net.ServicePointManager.SecurityProtocol |= System.Net.SecurityProtocolType.Tls12; } catch { }
            SimHub.Logging.Current.Info("[TF4ALL] Init: loading settings...");
            LogAssemblyVersionCrossCheck();
            SimHub.Logging.Current.Info(
                "[TF4ALL] Logitech processes at startup: " + SnapshotLogitechProcesses());
            // The installer flips SimHub's "Start minimized" off to open it visibly
            // after an install/update, so put the user's real preference back in
            // SimHub's in-memory model before exit persists the off. One-shot,
            // marker-file gated. See StartMinimizedRestore.
            StartMinimizedRestore.ConsumeMarkerAndRestore();
            // wasFreshInstall flips iff the factory ran (no prior settings file
            // for us), the cleanest first-run signal ReadCommonSettings gives.
            bool wasFreshInstall = false;
            Settings = this.ReadCommonSettings("GeneralSettings", () => { wasFreshInstall = true; return new TrueforceSettings(); });
            // Kept for the whole session: wheel detection runs later (and again
            // on a replug) and needs to know this PC had no settings file, so
            // first-run-only defaults can never reach an existing setup.
            _wasFreshInstall = wasFreshInstall;
            // Defensive nulls in case an older settings file was deserialized
            // without one of these dictionaries.
            if (Settings.Presets      == null) Settings.Presets      = new Dictionary<string, GameSettingsSnapshot>();
            if (Settings.GameDefaults == null) Settings.GameDefaults = new Dictionary<string, string>();
            if (Settings.GameEnabled  == null) Settings.GameEnabled  = new Dictionary<string, bool>();
            if (Settings.GameModes    == null) Settings.GameModes    = new Dictionary<string, TrueforceMasterMode>();
            // The spring/FFB-recreation toggle left the UI (owner call: it is HOW
            // Farming Simulator works, not an option; FS requires telemetry-based
            // FFB). A false from an older build would leave FS silently dead.
            Settings.ClassicSpringEmulationEnabled = true;
            // Max force is per car, always (see the setting's own note). The
            // choice is retired rather than removed so the resolution order
            // keeps honouring a shared number set before this release.
            Settings.IRacingMaxForcePerCar = true;
            // StopStreamOnPause: 0.3.0 flipped beta-era files to ON once (the
            // shipped default then). 0.4.0 ships it OFF (see the setting), and
            // nearly every stored ON came from that flip rather than a choice,
            // so flip once more; the checkbox choice then sticks.
            if (!Settings.StopStreamOnPauseMigrated) Settings.StopStreamOnPauseMigrated = true;
            if (!Settings.StopStreamOnPauseDefaultOffMigrated)
            {
                Settings.StopStreamOnPauseDefaultOffMigrated = true;
                Settings.StopStreamOnPause = false;
            }
            // The condition engine's own data migrations (the inertia-spec repair and the
            // generation reset). They live in a method rather than here because a restore or
            // an import can land values that predate them, and the fix then has to run again
            // outside startup. Same call, same order, same behavior as when it was inline.
            ApplyConditionMigrations();
            // The Le Mans Ultimate full scale's first, provisional default (15
            // Nm, before the rig had measured what the cars push) was persisted
            // by the one settings file that ran that build. Move it to the
            // measured number; a value anyone set by hand is left alone.
            if (Math.Abs(Settings.LmuFullScaleNm - 15f) < 0.01f)
                Settings.LmuFullScaleNm = 50f;
            // The two spike-reduction methods used to share one number, read as
            // a rate under the rate limiter and as a magnitude threshold under
            // the peak limiter. Give the peak limiter its own: someone already
            // using it keeps the value they tuned, everyone else gets the
            // shipped default instead of whatever their rate happened to be.
            Settings.SeedSpikeTransientThreshold();
            // Bring an installed TF4ALL CSP Bridge up to date NOW, while Assetto
            // Corsa is almost certainly closed, rather than waiting for the
            // game-change edge. CSP reads its scripts once at startup, so an
            // update applied on entering AC cannot take effect until the launch
            // AFTER that one: the user plays a whole session on the old script,
            // and a fix they were told shipped appears not to work. Updating at
            // plugin start means their next launch already has it (owner,
            // 2026-09-09). The game-change call stays as the backstop for a
            // bridge installed later in the session.
            MaybeUpdateAcCspBridge();
            // Provision the official community backend: nothing is baked into the code, so a
            // fresh install can't reach sign-in / community / backup ("could not reach the
            // sign-in server"). Seeded every launch and authoritative, so a key rotation
            // propagates on the next release. Safe to ship: the publishable key only grants what
            // RLS allows anon/authenticated (NOT the service_role key or an Edge Function secret).
            Settings.CommunityBackendUrl     = CommunityBackend.Url;
            Settings.CommunityBackendAnonKey = CommunityBackend.AnonKey;
            // Dev-only safety net: a new TOP-LEVEL TrueforceSettings property nobody
            // classified in BackupProjection.cs would silently miss cloud backups, so warn
            // until it gets its one-line classification. New fields INSIDE an existing
            // effect object are auto-covered and never trip this.
            if (Settings.DevModeUnlocked)
            {
                try
                {
                    var backupUnclassified = BackupProjection.FindUnclassifiedFields();
                    var backupDoubled      = BackupProjection.FindDoubleClassifiedFields();
                    // The two guards below face the other way: not "is every field classified"
                    // but "does every classification still name a real field", and the same
                    // question for the Forza/Arcade splits. That direction had no check at all,
                    // which is how two Portable entries came to match no property for a month
                    // while the list implied the settings were being backed up.
                    var backupStale        = BackupProjection.FindStaleClassifications();
                    var partialUnclassified = BackupProjection.FindUnclassifiedPartialFields();
                    if (backupUnclassified.Count > 0)
                        SimHub.Logging.Current.Warn("[TF4ALL][DEV] Backup: " + backupUnclassified.Count
                            + " unclassified TrueforceSettings field(s); add each to a BackupProjection bucket "
                            + "(Portable / MachineLocal / Excluded): " + string.Join(", ", backupUnclassified));
                    if (backupDoubled.Count > 0)
                        SimHub.Logging.Current.Warn("[TF4ALL][DEV] Backup: field(s) classified in more than "
                            + "one BackupProjection bucket: " + string.Join(", ", backupDoubled));
                    if (backupStale.Count > 0)
                        SimHub.Logging.Current.Warn("[TF4ALL][DEV] Backup: classified name(s) that match no "
                            + "property, so they back up nothing: " + string.Join(", ", backupStale));
                    if (partialUnclassified.Count > 0)
                        SimHub.Logging.Current.Warn("[TF4ALL][DEV] Backup: Forza/Arcade field(s) in neither the "
                            + "portable nor the machine-local half of their split: " + string.Join(", ", partialUnclassified));
                    if (backupUnclassified.Count == 0 && backupDoubled.Count == 0
                        && backupStale.Count == 0 && partialUnclassified.Count == 0)
                        SimHub.Logging.Current.Info("[TF4ALL][DEV] Backup classification OK: all "
                            + "TrueforceSettings fields are classified for backup/sync.");
                }
                catch (Exception ex)
                {
                    SimHub.Logging.Current.Warn("[TF4ALL][DEV] Backup classification audit failed: " + ex.Message);
                }
            }
            // The lighting tab shipped, but a new default cannot reach a stored
            // LightsyncTabUnlocked=false. Flip once, latched (opt-out sticks).
            if (!Settings.LightsyncReleasedMigrated)
            {
                Settings.LightsyncTabUnlocked = true;
                Settings.LightsyncReleasedMigrated = true;
                try { PersistSettingsCore(); } catch { }
            }

            // The master switch became three-state. Everyone lands on Normal: the old
            // bool was never a global choice, it was the LIVE state pushed from the
            // per-game map on every game change, so a stored "false" is just the
            // last game selected and reading it as a global Off would switch the
            // plugin off everywhere. The map still demotes the games it always did.
            // Latched, so a user who then picks lights-only or off is left alone.
            if (!Settings.MasterModeMigratedV1)
            {
                Settings.MasterMode = TrueforceMasterMode.Normal;

                // Drop the per-game "off" entries WE wrote for native-Trueforce
                // games. Older builds stamped one on first sight of each, so an
                // existing install pins iRacing, ACC and the rest to off and the new
                // default (Lightsync only) can never apply (the map is read first).
                // A deliberate off is indistinguishable from ours, so this resets it
                // too, to a less intrusive mode (the game keeps its FFB either way).
                if (Settings.GameEnabled != null)
                {
                    var ours = new List<string>();
                    foreach (var kv in Settings.GameEnabled)
                        if (!kv.Value && IsNativeTrueforceGame(kv.Key)) ours.Add(kv.Key);
                    foreach (var g in ours) Settings.GameEnabled.Remove(g);
                }

                Settings.MasterModeMigratedV1 = true;
                try { PersistSettingsCore(); } catch { }
            }

            // The per-game choice became a MODE. Every stored "off" becomes Lightsync
            // only, not Off: it says the same "not the force layer here" while still
            // lighting the wheel for the car you are in, and anyone who wants a title
            // silent can pick Off again in one click, which then sticks.
            if (!Settings.GameModeMapMigratedV1)
            {
                if (Settings.GameEnabled != null && Settings.GameModes != null)
                {
                    foreach (var kv in Settings.GameEnabled)
                    {
                        if (Settings.GameModes.ContainsKey(kv.Key)) continue;
                        Settings.GameModes[kv.Key] = kv.Value
                            ? TrueforceMasterMode.Normal
                            : TrueforceMasterMode.LightsyncOnly;
                    }
                }
                Settings.GameModeMapMigratedV1 = true;
                try { PersistSettingsCore(); } catch { }
            }
            // Ask SimHub what is already running before the mode is latched: a
            // game on screen at Init decides the mode as surely as one that
            // starts later, and the force path is opened further down this
            // method, long before the first DataUpdate could say so.
            _startupGameName = ReadRunningGameFromSimHub();
            if (!string.IsNullOrEmpty(_startupGameName))
                SimHub.Logging.Current.Info(
                    $"[TF4ALL] '{_startupGameName}' is already running: resolving its master mode now, "
                    + "before the wheel's force path is opened.");

            // Latch the effective mode from what we just loaded, so nothing reads
            // the field's compile-time default before the first game arrives.
            ApplyEffectiveMode("settings loaded");

            // One-time folder restructure: move the three legacy sibling
            // folders (TrueforceForAll-Presets / -Library / -Imports) into the
            // collapsed PluginsData\Common\TrueforceForAll\{factory,user,user\import}
            // layout. Idempotent; skipped once stamped. Runs BEFORE the stores
            // load so they read from the new location on the first new launch.
            if (!Settings.FoldersRestructuredV3)
            {
                RestructureFoldersIfNeeded();
                Settings.FoldersRestructuredV3 = true;
                // Persist now: the later SaveCommonSettings only fires on a fresh
                // install, so otherwise the restructure re-runs every startup.
                try { PersistSettingsCore(); } catch { }
            }
            // Load the file-based built-in presets (folder override -> shipped
            // default) before anything seeds or queries them below.
            BuiltinPresets.Initialize(Settings.BuiltinPresetsFolder);
            // Load the user-library folder (where user-saved presets live as
            // files; mirrors the built-in folder layout). Defaults under
            // PluginsData/Common, user-writable.
            UserPresets.Initialize(Settings.UserLibraryFolder);
            // Fold the OLDEST-format Settings.GamePresets dict into
            // Settings.Presets/GameDefaults BEFORE the file migration below:
            // MigrateLegacyUserPresetsToFolder reads only those two dicts,
            // early-returns (no backup, no files) when both are empty, then
            // latches PresetsMigratedV2, so folding in later loses those presets
            // to the folder rebuild, unbacked. No-op on v0.1.0+ (GamePresets empty).
            MigrateLegacyGamePresets();
            // One-time migration: legacy in-dict user presets -> user-library files,
            // settings file backed up first. IsFactoryBuiltinName (currently-shipped
            // OR RetiredBuiltinNames) drops factory entries so the library carries
            // only user content. Skipped once stamped.
            if (!Settings.PresetsMigratedV2)
            {
                // Latch only when the migration completed with a downgrade
                // backup in place. A failed backup returns false and keeps the
                // legacy dicts (the sole v0.1.25-downgrade copy), so leaving the
                // latch unset retries the backup + clear on the next launch.
                if (MigrateLegacyUserPresetsToFolder())
                {
                    Settings.PresetsMigratedV2 = true;
                    try { PersistSettingsCore(); } catch { }
                }
            }
            // One-time car migration: legacy TrueforceCars/*.tfcar.json ->
            // user library cars/ tree + Settings.CarDefaults -> car-defaults.json.
            // Separate flag from the game migration because it shipped later;
            // users who already migrated games still need this on first run.
            if (!Settings.CarsMigratedV2)
            {
                MigrateLegacyUserCarsToFolder();
                Settings.CarsMigratedV2 = true;
                try { PersistSettingsCore(); } catch { }
            }
            // Housekeeping: rename leftover "TrueforceCars.bak-..." backup
            // folders to the on-brand name. Idempotent; runs every Init.
            RebrandLegacyCarsBackup();
            if (Settings.Performance  == null) Settings.Performance  = new PerformanceSettings();
            if (Settings.Forza        == null) Settings.Forza        = new ForzaSettings();
            if (Settings.SeenEffects  == null) Settings.SeenEffects  = new List<string>();
            if (Settings.CarCylinderCache == null)
                Settings.CarCylinderCache = new Dictionary<string, Dictionary<string, int>>();
            if (Settings.GamesWithRedline == null)
                Settings.GamesWithRedline = new HashSet<string>();
            // Scrub any Forza title an earlier build wrongly learned as a
            // redline game (its per-car redline can pass the sanity gate, but
            // Forza has no precise rev limit), so the engage-% control comes back.
            Settings.GamesWithRedline.RemoveWhere(IsForzaGameName);

            // One-time re-validation: builds before the realRedline split faked a
            // redline from MaxRpm, so the gate accepted EVERY non-Forza game
            // (MaxRpm always passes the 0.5..1.02x gate against itself), which
            // hides the engage-% control. Clear once so it re-learns under the new
            // rule (only games reporting a real CarSettings_RedLineRPM qualify).
            if (!Settings.GamesWithRedlineRevalidated)
            {
                Settings.GamesWithRedline.Clear();
                Settings.GamesWithRedlineRevalidated = true;
                try { PersistSettingsCore(); } catch { }
            }

            // One-time: the home-screen gain tile is now on by default. Flip it
            // on for existing installs that predate that change, once, so an
            // update lights it up. A later user opt-out (Settings toggle) sticks
            // because the latch is already set.
            if (!Settings.FeedbackBoxDefaultedOn)
            {
                Settings.ShowFeedbackBox = true;
                Settings.FeedbackBoxDefaultedOn = true;
                try { PersistSettingsCore(); } catch { }
            }

            // One-shot v0.1.21 -> v0.1.22 migration: clear any saved manual
            // USBPcap override. A stale pin (wheel moved to a different address
            // / USBPcap interface) reads as "FFB stopped working after an
            // update" (issue #17); auto-discovery + identity-based self-heal
            // cover the realistic cases; the MANUALPIN access code re-reveals
            // the picker so a user who needs one can pin again. The latch
            // stops this re-clearing a deliberate post-migration pin.
            if (!Settings.ManualOverrideClearedV0_1_22)
            {
                bool hadOverride = !string.IsNullOrEmpty(Settings.ManualUsbPcapInterface)
                                || Settings.ManualUsbPcapDeviceAddress > 0;
                if (hadOverride)
                {
                    SimHub.Logging.Current.Info(
                        "[TF4ALL] Migration: cleared saved manual USBPcap override " +
                        $"({Settings.ManualUsbPcapInterface} dev {Settings.ManualUsbPcapDeviceAddress}); " +
                        "auto-discovery now picks the wheel. Re-enable manual pinning with the MANUALPIN access code if needed.");
                    Settings.ManualUsbPcapInterface = "";
                    Settings.ManualUsbPcapDeviceAddress = 0;
                    Settings.ManualUsbPcapVid = 0;
                    Settings.ManualUsbPcapPid = 0;
                }
                Settings.ManualOverrideClearedV0_1_22 = true;
                try { PersistSettingsCore(); } catch { }
            }

            // Fresh install (factory ran) or a settings file predating the badge
            // feature (LastSeenVersion never stamped): seed every known effect as
            // already-seen and stamp LastSeenVersion to the running build, so an
            // upgrader isn't badged on effects they already use. After the seed,
            // badges fire only for effects introduced in strictly newer versions.
            if (wasFreshInstall || string.IsNullOrEmpty(Settings.LastSeenVersion))
            {
                foreach (var id in EffectChangelog.KnownEffectIds)
                {
                    if (!Settings.SeenEffects.Contains(id)) Settings.SeenEffects.Add(id);
                }
                Settings.LastSeenVersion = CurrentVersionString();
                PersistSettingsCore();
            }

            // Hand the resolver the persisted cache (write-through; a version
            // bump clears it). See AttachPersistentCache.
            int cacheVer = Settings.CarCylinderCacheVersion;
            CarCylinderResolver.AttachPersistentCache(Settings.CarCylinderCache, ref cacheVer);
            Settings.CarCylinderCacheVersion = cacheVer;
            // One-time migration: promote the cylinder-only CarCylinderCache
            // entries into seed Stock EngineVariants in Settings.CarFacts so
            // the new apply path has something to work with on day one.
            // Idempotent; flag-gated.
            if (!Settings.CarFactsMigratedV1)
            {
                MigrateCarCylinderCacheToCarFacts();
                Settings.CarFactsMigratedV1 = true;
                try { PersistSettingsCore(); } catch { }
            }
            // (MigrateCarPresetOrdinalNames and MigrateLegacyGamePresets both
            // moved out of here; the ordering reasons live at their call sites.)
            InstallBuiltinPresetsIfMissing();

            // Per-car file store, rooted at the cars/ subfolder of the user
            // library (TrueforceForAll-Library). LoadAndMigrateCarPresets loads
            // files into Settings.CarOverrides (file wins on conflict) then
            // writes any Settings.CarOverrides / preset.CarOverrides lacking a
            // file. Files are canonical; Settings.CarOverrides is an in-memory
            // cache only. Built-in cars live in BuiltinPresets and merge in there.
            _carStore = new CarPresetStore(
                () => UserPresets.CurrentFolder,
                msg => SimHub.Logging.Current.Info(msg));
            _installedPacks = new InstalledPacksStore(
                () => UserPresets.CurrentFolder,
                msg => SimHub.Logging.Current.Info(msg));
            LoadAndMigrateCarPresets();

            // Normalize legacy "Forza_<n>" car ids to "Car_<n>" exactly once.
            // Released builds stored Forza car tunings under "Forza_<ordinal>";
            // this branch looks them up as "Car_<ordinal>" (see the runtime
            // alias in DataUpdate), so without this an upgrading user's
            // per-car Forza Horizon tuning silently stops applying. Runs after
            // the car files are in the new layout and BEFORE the ordinal-name
            // pass below, so a normalized "Car_<n>" still gets its human name.
            // Content-preserving: a Forza_<n> that collides with an existing
            // Car_<n> is merged (distinct tunings kept), never dropped.
            if (!Settings.ForzaCarIdsNormalizedV1)
            {
                try { DevNormalizeForzaCarIds(out _); }
                catch (Exception ex)
                {
                    SimHub.Logging.Current.Warn($"[TF4ALL] Forza car-id normalization failed: {ex.Message}");
                }
                Settings.ForzaCarIdsNormalizedV1 = true;
                try { PersistSettingsCore(); } catch { }
            }

            // One-time engine-choice relocation: per-car picks on
            // CarOverride.EnginePulse (Layout / CustomEngineId) move into the
            // matching CarFacts variants' UserEngineLayout pin. Runs after the
            // car files load into Settings.CarOverrides and after id
            // normalization so carIds line up with CarFacts keys. Global and
            // game-preset picks are dropped deliberately (they aren't car-bound).
            if (!Settings.EngineChoiceMovedToCarFactsV1)
            {
                try
                {
                    MigrateEngineChoicesToCarFacts();
                    // Latch only on SUCCESS: the migration is idempotent
                    // (existing pins are never overwritten), so a throw
                    // simply retries on the next start instead of silently
                    // abandoning unmigrated picks.
                    Settings.EngineChoiceMovedToCarFactsV1 = true;
                    try { PersistSettingsCore(); } catch { }
                }
                catch (Exception ex)
                {
                    SimHub.Logging.Current.Warn(
                        $"[TF4ALL] Engine-choice migration failed (will retry next start): {ex.Message}");
                }
            }

            // Follow-up prune: overrides whose only purpose was the engine
            // pick (relocated above) kept an "overridden" Engine badge and
            // froze feel against future preset edits for no reason. Runs
            // after the relocation so the pick already lives in the pin.
            if (!Settings.EngineOnlyOverridesPrunedV1)
            {
                try
                {
                    PruneEngineOnlyCarOverrides();
                    Settings.EngineOnlyOverridesPrunedV1 = true;
                    try { PersistSettingsCore(); } catch { }
                }
                catch (Exception ex)
                {
                    SimHub.Logging.Current.Warn(
                        $"[TF4ALL] Engine-only override prune failed (will retry next start): {ex.Message}");
                }
            }

            // Anon car facts (0100): whenever sharing is on (the default, or
            // an old opt-in), treat the consent question as answered and make
            // sure the anon id exists (covers fresh installs, the upgrade
            // path, and a restored backup missing the id).
            if (Settings.AutoSubmitCarFacts)
            {
                if (!Settings.CarFactsConsentAsked)
                {
                    Settings.CarFactsConsentAsked = true;
                    try { PersistSettingsCore(); } catch { }
                }
                EnsureCarFactsAnonId();
            }

            // Default-on re-pitch: CommunityEnabled's default flipped to ON, but
            // existing settings files carry an explicit false from the old opt-in
            // default, so re-show the networked welcome once for those installs
            // (any dismissal enables community + sharing). Community-on users are
            // NOT re-pitched; if their stored AutoSubmitCarFacts is false the
            // consent gate asks once at their next fact-worthy save instead.
            if (!Settings.CommunityDefaultOnRepitchedV1)
            {
                if (!Settings.CommunityEnabled)
                {
                    Settings.HasSeenNetworkedWelcome = false;
                    Settings.WelcomeDeclineCount     = 0;
                    Settings.WelcomeNextShowAt       = null;
                }
                Settings.CommunityDefaultOnRepitchedV1 = true;
                try { PersistSettingsCore(); } catch { }
            }

            // Rename Car_NNN-style car-preset names to human car names (per
            // game). Must run after _carStore is initialised and after
            // LoadAndMigrateCarPresets moved the files into the new layout; the
            // V2 flag re-runs the pass for users whose V1 ran early and no-opped.
            if (!Settings.CarPresetOrdinalNamesMigratedV2)
            {
                MigrateCarPresetOrdinalNames();
                Settings.CarPresetOrdinalNamesMigratedV1 = true;   // keep V1 set too
                Settings.CarPresetOrdinalNamesMigratedV2 = true;
                try { PersistSettingsCore(); } catch { }
            }

            // Community backend HTTP client. Inert until
            // Settings.CommunityEnabled is true and a URL + anon key are
            // configured (see supabase/README.md). Identity (submitter_id) is
            // the signed-in auth.uid(), else 'anon:' + Settings.CarFactsAnonId
            // (0100); the hashed client IP is only a rate-limit / ban key.
            _auth = new CommunityAuth(
                () => Settings,
                () => PersistSettingsCore(),
                msg => SimHub.Logging.Current.Info(msg));
            _community = new CommunityClient(
                () => Settings,
                msg => SimHub.Logging.Current.Info(msg),
                System.Reflection.Assembly.GetExecutingAssembly().GetName().Version?.ToString(),
                async () => _auth != null ? await _auth.GetAccessTokenAsync() : null);
            // B5/F03 migration: legacy installs may have plaintext
            // AuthSession tokens on disk. Encrypt-in-place idempotently
            // so users stay signed in and on-disk tokens become
            // DPAPI-wrapped from this run forward.
            try { _auth.MigrateLegacyPlaintextSession(); } catch { }
            // Mount the right per-local-user data slot up front so
            // legacy installs get migrated on first run, then the
            // active slot's DownloadedCommunityPresets + SharingAuthor
            // are visible through the existing Settings fields.
            EnsureUserSlotsMounted();
            // Re-mount whenever auth flips (sign-in / sign-out). Also
            // raises AuthIdentityChanged so UI panels can reset their
            // per-session latches + in-memory caches without having
            // to subscribe to CommunityAuth directly.
            _auth.ActiveIdentityChanged += OnActiveIdentityChanged;
            _presetSharing = new PresetSharingClient(
                () => Settings,
                msg => SimHub.Logging.Current.Info(msg),
                System.Reflection.Assembly.GetExecutingAssembly().GetName().Version?.ToString(),
                async () => _auth != null ? await _auth.GetAccessTokenAsync() : null);
            // Browse-result cache, scoped to the active local-user slot (it reloads
            // the right slot's file transparently on an identity switch).
            _browseCache = new CommunityBrowseCacheStore(
                () => Settings?.ActiveSlotKey ?? "",
                msg => SimHub.Logging.Current.Info(msg));

            // Cloud backup/sync transport (Phase 2). Same auth wiring as the other
            // clients; a signed-in session, plus supporter status for uploads (0034).
            _backupClient = new BackupClient(
                () => Settings,
                msg => SimHub.Logging.Current.Info(msg),
                async () => _auth != null ? await _auth.GetAccessTokenAsync() : null);

            // Standalone Discord link transport (Phase 2, M5). Same auth wiring; the
            // browser/loopback OAuth dance lives in DiscordOAuthFlow.
            _discordLinkClient = new DiscordLinkClient(
                () => Settings,
                msg => SimHub.Logging.Current.Info(msg),
                async () => _auth != null ? await _auth.GetAccessTokenAsync() : null);

            // Patreon link transport (Phase 2). Proves supporter status in-plugin (badge + cloud
            // backup without Discord); the browser/loopback OAuth dance lives in PatreonOAuthFlow.
            _patreonLinkClient = new PatreonLinkClient(
                () => Settings,
                msg => SimHub.Logging.Current.Info(msg),
                async () => _auth != null ? await _auth.GetAccessTokenAsync() : null);

            // Read-only supporter entitlement (for the in-plugin supporter badge).
            _entitlementClient = new EntitlementClient(
                () => Settings,
                msg => SimHub.Logging.Current.Info(msg),
                async () => _auth != null ? await _auth.GetAccessTokenAsync() : null);

            // Read-only Patreon supporters roster (for the Account tab's Supporters wall).
            // Public read; uses the signed-in token when present, else the anon key.
            _supportersClient = new SupportersClient(
                () => Settings,
                msg => SimHub.Logging.Current.Info(msg),
                async () => _auth != null ? await _auth.GetAccessTokenAsync() : null);

            // Achievement tracker (progress) + immediate self-scoped role sync.
            _achievementClient = new AchievementClient(
                () => Settings,
                msg => SimHub.Logging.Current.Info(msg),
                async () => _auth != null ? await _auth.GetAccessTokenAsync() : null);

            // Account session list + per-session revoke (Account tab "Active sessions").
            _sessionClient = new SessionClient(
                () => Settings,
                msg => SimHub.Logging.Current.Info(msg),
                async () => _auth != null ? await _auth.GetAccessTokenAsync() : null);

            // Moderation notices (warn/removal/ban) + appeal, surfaced when the
            // user opens "My uploads". Same auth plumbing as the session client.
            _moderationClient = new ModerationClient(
                () => Settings,
                msg => SimHub.Logging.Current.Info(msg),
                async () => _auth != null ? await _auth.GetAccessTokenAsync() : null);

            // Anonymous usage statistics (opt-out; migration 0127). No auth wiring:
            // the ping is deliberately never tied to an account. Fire once shortly
            // after start, then on a slow timer so a long-running session still
            // counts each day; MaybeSendUsagePing self-gates on the toggle and the
            // once-a-day stamp, so the extra ticks are cheap no-ops.
            _telemetryClient = new TelemetryClient(
                () => Settings,
                msg => SimHub.Logging.Current.Info(msg));
            try
            {
                _usagePingTimer = new System.Threading.Timer(
                    _ => MaybeSendUsagePing(), null,
                    TimeSpan.FromMinutes(2), TimeSpan.FromHours(6));
            }
            catch { /* timer construction never fatal to boot */ }
            // Prune the queued game-days on every start, whatever the toggle says. This
            // is the one pruner an opted-out install ever reaches: everything else in
            // this feature sits behind ShareUsageStats, so without it a user who turned
            // the switch off would carry the days queued at that moment forever. Only
            // writes when something actually went.
            try { if (PruneUsageGameDays()) PersistSettingsCore(); }
            catch { /* prune is housekeeping; never fatal to boot */ }

            // Fire-and-forget plugin-load account sync. If a session was
            // restored from Settings.AuthSession, refresh the profile so
            // SharingAuthor matches whatever the server says
            // profile.username is right now (catches renames done from a
            // different machine). Non-blocking - the plugin keeps booting.
            if (_auth != null && _auth.IsSignedIn)
            {
                Task.Run(async () =>
                {
                    try
                    {
                        var profile = await _auth.GetMyProfileAsync();
                        if (profile.SignedIn && !string.IsNullOrEmpty(profile.Username)
                            && Settings != null
                            && !string.Equals(Settings.SharingAuthor, profile.Username,
                                              StringComparison.Ordinal))
                        {
                            Settings.SharingAuthor = profile.Username;
                            try { PersistSettingsCore(); }
                            catch { }
                        }
                    }
                    catch (Exception ex)
                    {
                        SimHub.Logging.Current.Warn(
                            "[TF4ALL] Plugin-load profile sync failed: " + ex.Message);
                    }
                });
            }

            // One-time cleanup: archives user/games + user/cars files that are
            // leftovers from before the file-based factory (commit c89c3f7 era),
            // and drops their user/game-defaults + user/car-defaults entries so
            // the factory seed takes over. The match rules live on the method.
            //
            // Runs AFTER LoadAndMigrateCarPresets so user/cars reflects
            // the full set of user-tier car files (step 1 of that method
            // creates files from legacy Settings.CarOverrides). Flag
            // stamps so it runs exactly once.
            if (!Settings.LegacyBuiltinsCleanedV1)
            {
                CleanupLegacyBuiltinsInUserLibrary();
                Settings.LegacyBuiltinsCleanedV1 = true;
                try { PersistSettingsCore(); } catch { }
                // Re-run the car cache rebuild so Settings.CarDefaults
                // reflects the post-cleanup state (factory seed for
                // bindings whose user-side entry just got dropped).
                LoadAndMigrateCarPresets();
            }
            MigrateEngineHighRpmHelpersDefaults();
            // (No rev-limiter Threshold migration: the field is gone and the
            // redline comes from the Car facts cascade. See RevLimiterSettings.)

            // One-time: the imports inbox was renamed from "drop" to "import";
            // move a leftover default "drop" folder to the new name.
            try
            {
                string legacyDropFolder = Path.Combine(UserPresets.DefaultFolder, "drop");
                string newImportFolder  = Path.Combine(UserPresets.DefaultFolder, UserImportsFolderName);
                if (Directory.Exists(legacyDropFolder) && !Directory.Exists(newImportFolder))
                    Directory.Move(legacyDropFolder, newImportFolder);
            }
            catch { /* best-effort rename */ }

            // Make sure all three folders exist with their READMEs, then auto-
            // import anything the user dropped into the imports folder. All
            // best-effort: folder access errors degrade gracefully.
            WriteReadmeIfMissing(BuiltinPresets.CurrentFolder, BuiltinReadmeText);
            WriteReadmeIfMissing(UserPresets.CurrentFolder, UserLibraryReadmeText);
            WriteReadmeIfMissing(UserImportsFolderPath, ImportsReadmeText);
            ImportFromUserImportsFolder();

            _mixer.MasterGain = Settings.MasterGain;
            _mixer.PostMix = new ProcessorChain(_eqTapPre, _trueforceEq, _eqTapPost);
            SeedTrueforceEqIfNeeded();
            ApplyTrueforceEq();

            // Start the GitHub update poller BEFORE the wheel bring-up below,
            // so a user whose wheel is unplugged (or whose G HUB is holding
            // the HID) still learns that a fix shipped without waiting on
            // discovery. A null _updateChecker would leave the in-panel banner
            // and the Check-for-updates button dead. The check itself doesn't
            // touch wheel state.
            _updateCheckerCts = new System.Threading.CancellationTokenSource();
            _updateChecker = new UpdateChecker
            {
                Logger = msg => SimHub.Logging.Current.Info($"[TF4ALL] {msg}"),
            };
            System.Threading.Tasks.Task.Run(async () =>
            {
                try
                {
                    await _updateChecker.CheckAsync(_updateCheckerCts.Token);
                    // Beta channel: auto-enroll a beta build and re-select the
                    // latest target so a prerelease can surface in the banner
                    // on the very first check. No-op for Stable on stable.
                    RefreshUpdateChannel();
                    // Downloaded-preset auto-update rides the same startup
                    // check. Short delay so the sweep doesn't compete with
                    // the rest of startup.
                    await System.Threading.Tasks.Task.Delay(15000);
                    await MaybeAutoUpdateCommunityPresetsHeadless();
                }
                catch (Exception ex)
                {
                    SimHub.Logging.Current.Warn($"[TF4ALL] Update check task crashed: {ex.Message}");
                }
            });
            // Arm the background re-check: the startup poll above is one-shot.
            // Re-runs CheckAsync on the user-configured cadence
            // (Settings.UpdateCheckIntervalHours). Lives on the plugin, not the
            // settings-panel timer, which only ticks while the panel is open.
            // The wakeup is a fixed cheap cadence and the tick decides whether
            // enough time has elapsed, so a runtime cadence change needs no re-arm.
            MarkUpdateChecked();
            _updateCheckTimer = new System.Threading.Timer(
                UpdateCheckTimerTick, null, UpdateCheckPollMs, UpdateCheckPollMs);

            // Bring up the wheel (discover -> open -> init -> FFB tap ->
            // stream). Extracted so the recovery watchdog (MaybeRecoverDevice)
            // can re-run exactly this on a hot-replug / G-HUB-closed / init
            // retry. If it fails now we DON'T bail out of Init: the rest of
            // the plugin (telemetry, effects, audio capture, capture-poll
            // thread) still comes up so the watchdog only has to re-attach
            // the device, not reconstruct the whole pipeline.
            if (MasterMode != TrueforceMasterMode.Normal)
            {
                // Off and lights-only never open the Trueforce endpoint: no HID
                // handle, no init sequence, no USBPcap capture, no 1 kHz stream.
                // Discovery still runs because the wheel's identity is what the
                // LED path and every lighting control read.
                WheelMatch found;
                if (!DiscoverWheel(out found))
                {
                    SimHub.Logging.Current.Warn(
                        "[TF4ALL] No supported wheel found; the lighting controls will stay empty "
                        + "until one is detected.");
                }
                SimHub.Logging.Current.Info(
                    $"[TF4ALL] Master mode is {ModeLabel(MasterMode)}: the wheel's force path was not started.");
            }
            else if (!TryBringUpDevice())
            {
                SimHub.Logging.Current.Warn(
                    "[TF4ALL] Wheel not ready at startup; the plugin will "
                    + "keep retrying automatically (replug the wheel / close G HUB).");
            }
            else
            {
                // G923 audio-path wedge (2026-07-06): a cold bring-up on a
                // wheel left in a stale streaming state (any SimHub restart
                // while a game holds the wheel) makes the wheel honor cur but
                // silently DISCARD the audio window. Force feels fine, every
                // audio effect is dead, and nothing in software can tell. One
                // close/reopen/re-init cycle heals it (proved on hardware with
                // the FAULT access code; G HUB is NOT needed), so force one
                // fault and let the recovery watchdog run that cycle ~3 s in.
                // Costs one reconnect blip at startup, before anyone is driving.
                var d = _device;
                System.Threading.Tasks.Task.Run(async () =>
                {
                    try
                    {
                        await System.Threading.Tasks.Task.Delay(3000);
                        if (_shuttingDown || !ReferenceEquals(_device, d)) return;
                        SimHub.Logging.Current.Info(
                            "[TF4ALL] Startup re-attach: cycling the device once to clear "
                            + "the G923 stale-state audio wedge (expected, not an error).");
                        d.DebugForceStreamFault();
                    }
                    catch { }
                });
            }

            InitPipeline();

            // Arm the cloud auto-pull timer (it self-gates on active + a peer being online, so a solo
            // or idle user makes no calls). Sign-in/out transitions and the auto-sync toggle re-call it.
            UpdateAutoPullTimer();
            // The revoke heartbeat starts only once a second session is detected; nothing to do here
            // until presence is probed. (Kept for the signed-out -> stop path and idempotency.)
            UpdateSessionHeartbeatTimer();
            // One-shot startup reconcile: probe presence, run the drift backstop, and catch up if a
            // peer is online. ignoreActivity so an auto-started-minimized PC still pulls the latest
            // without first requiring an interaction; the peer gate still spares solo users.
            ReconcileSyncState(ignoreActivity: true);

            // Bindable input mappings for SimHub's Controls system.
            // IMPORTANT: AddInputMapping (NOT AddAction). AddAction
            // registers a macro/event-callable entry that shows up in the
            // Actions list but is NOT bindable - it sets IsInput=false, so
            // the Controls binder skips it and pressing a bound button
            // produces nothing. AddInputMapping flips IsInput=true so the
            // entry surfaces in the Controls binder and fires on hardware
            // input.
            //
            // Name MUST be just the bare action name (no plugin prefix):
            // PluginManager.GetName prepends "TrueforcePlugin." itself,
            // so the dictionary key becomes "TrueforcePlugin.MasterGainUp".
            // The ControlsEditor in XAML must bind to that exact string
            // or the dispatch lookup misses and the action never fires.
            //
            // Each press nudges master gain by MasterGainStep (persisted,
            // default 0.05, clamped to [0.01, 0.5]), and the result is
            // clamped to [0, 2]. Wrapped so a SimHub API hiccup can't
            // abort Init.
            try
            {
                // The readout rides the bound button: you press it without
                // looking at a screen, so it is the entry point that has to
                // say where the gain got to.
                pluginManager.AddInputMapping("MasterGainUp", GetType(),
                    (pm, a) => { NudgeMasterGain(+MasterGainStep); DashReadoutGain("TRUEFORCE GAIN", MasterGain); },
                    (pm, a) => { });
                pluginManager.AddInputMapping("MasterGainDown", GetType(),
                    (pm, a) => { NudgeMasterGain(-MasterGainStep); DashReadoutGain("TRUEFORCE GAIN", MasterGain); },
                    (pm, a) => { });

                // Telemetry Based FFB strength and the wheel screen, from the
                // rim. Both report through the same readout channel as the gain
                // controls, so the dash bar and the wheel screen both answer.
                pluginManager.AddInputMapping("ModeBStrengthUp", GetType(),
                    (pm, a) => NudgeModeBStrength(+0.05f), (pm, a) => { });
                pluginManager.AddInputMapping("ModeBStrengthDown", GetType(),
                    (pm, a) => NudgeModeBStrength(-0.05f), (pm, a) => { });
                // Auto force from the rim: runs the active game's own
                // auto-calibration (per-game behaviour on TriggerAutoForce).
                pluginManager.AddInputMapping("AutoForce", GetType(),
                    (pm, a) => TriggerAutoForce(), (pm, a) => { });
                pluginManager.AddInputMapping("OledScreenNext", GetType(),
                    (pm, a) => CycleOledScreen(+1), (pm, a) => { });
                pluginManager.AddInputMapping("OledScreenPrev", GetType(),
                    (pm, a) => CycleOledScreen(-1), (pm, a) => { });
                // Rev-light pattern from the rim. Same pick semantics as the
                // settings dropdown: the wheelbase's selection changes and stays.
                pluginManager.AddInputMapping("RevLightPatternNext", GetType(),
                    (pm, a) => CycleRevLightPattern(+1), (pm, a) => { });
                pluginManager.AddInputMapping("RevLightPatternPrev", GetType(),
                    (pm, a) => CycleRevLightPattern(-1), (pm, a) => { });
                pluginManager.AddInputMapping("DashTabNext", GetType(),
                    (pm, a) => CycleDashTab(+1), (pm, a) => { });
                pluginManager.AddInputMapping("DashTabPrev", GetType(),
                    (pm, a) => CycleDashTab(-1), (pm, a) => { });
                // Max force from the rim / dash: iRacing's own workflow is
                // nudging the read number to make a car heavier or lighter
                // without touching Strength. 0.5 Nm per press through the
                // same targeting rule as the settings number box.
                pluginManager.AddInputMapping("IRacingMaxForceUp", GetType(),
                    (pm, a) => NudgeIRacingMaxForce(+0.5), (pm, a) => { });
                pluginManager.AddInputMapping("IRacingMaxForceDown", GetType(),
                    (pm, a) => NudgeIRacingMaxForce(-0.5), (pm, a) => { });
                // RaceRoom deliberately has NO bindings of its own. Its
                // press-to-apply is the same gesture as iRacing's Auto button and
                // rides AutoForce; its per-car max is the same concept as
                // iRacing's and rides the pair above. Three R3E-specific mappings
                // lived here briefly and were the wrong shape: a fourth binding
                // for a fourth game does not scale, and it left AutoForce still
                // running the grip-cal reset in RaceRoom.

                // The dash's -/+ pair fires ACTIONS (ButtonItem.TriggerAction),
                // which AddInputMapping does not register: the mappings above
                // serve the bindings rows, these serve the dash buttons
                // (CalibrateCarForce set the precedent). DISTINCT names on
                // purpose: sharing the mapping's name made the dash lookup
                // resolve to the mapping entry and the taps died silently.
                this.AddAction("DashMaxForceUp",
                    (a, b) => { DashNoteActivity(); NudgeIRacingMaxForce(+0.5); });
                this.AddAction("DashMaxForceDown",
                    (a, b) => { DashNoteActivity(); NudgeIRacingMaxForce(-0.5); });
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Warn($"[TF4ALL] AddInputMapping (master gain) failed: {ex.Message}");
            }

            // Dash remote bridge (TrueforcePlugin.DashRemote.cs): properties +
            // actions for the TF4ALL Remote dashboard. Wrapped so a SimHub
            // registration hiccup can't abort Init.
            try { InitDashRemote(pluginManager); }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Warn($"[TF4ALL] Dash remote bridge init failed: {ex.Message}");
            }
        }

        // Rate limit for the G923 PlayStation-mode switch, deliberately not a
        // one-shot: that wheel forgets PC mode whenever it loses power, which is
        // why the G HUB workaround it replaces had to be repeated at every boot.
        // A wheel arriving in PlayStation mode mid-session is therefore normal
        // and must be switched again. A latch would have to catch the gap
        // between the old device leaving and the new one arriving, and
        // rediscovery ticks are far enough apart to miss it, leaving us latched
        // against a wheel we could have fixed. One attempt a minute instead, the
        // same rhythm LogDiscoveryDiagnostic uses: it costs a log line and
        // cannot get stuck.
        private long _lastPcModeSwitchTicks;

        /// <summary>Offer a PlayStation-mode G923 the PC-mode switch, so the user
        /// does not have to run G HUB after every computer start to get the wheel
        /// out of a mode where it exposes no Trueforce interface. Only ever reached from the
        /// no-wheel-found path, and only ever aimed at product id 0xC267: a
        /// working setup is never touched, and no other wheel sees the command.
        /// See WheelPcModeSwitch for why this is a refusal rather than a risk if
        /// Windows will not carry the report.</summary>
        private void MaybeSwitchG923PsToPcMode()
        {
            try
            {
                // Cheap check first, so the cooldown only ever governs real
                // attempts: a wheel that arrives seconds after a failed one still
                // gets switched on the next discovery pass rather than waiting out
                // a minute it had nothing to do with.
                if (!WheelPcModeSwitch.AnyPresent()) return;

                long now = Stopwatch.GetTimestamp();
                if (_lastPcModeSwitchTicks != 0
                    && now - _lastPcModeSwitchTicks < Stopwatch.Frequency * 60)
                    return;
                _lastPcModeSwitchTicks = now;

                var result = WheelPcModeSwitch.TrySwitch(
                    m => SimHub.Logging.Current.Info("[TF4ALL] " + m));

                // On success the wheel USB-resets and comes back as 0xC266, which
                // the recovery watchdog picks up on its next pass; nothing here
                // waits for it.
                if (result == WheelPcModeSwitch.Result.Sent)
                    WheelStatus = "Switching the wheel to PC mode...";
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Warn(
                    $"[TF4ALL] PC-mode switch failed: {ex.GetType().Name}: {ex.Message}");
            }
        }

        /// <summary>Find the wheel and take its identity WITHOUT opening it.
        ///
        /// Split out of bring-up because lights-only mode never opens the Trueforce
        /// endpoint but still has to know which wheel is attached: _hidWheelPid is
        /// what tells the LED path a strip exists, and it is what the pattern
        /// pickers and the wheel diagnostics read. Left inside bring-up, the Off
        /// and Lightsync-only modes would report "no wheel" and every lighting
        /// control would quietly empty out.</summary>
        private bool DiscoverWheel(out WheelMatch match)
        {
            match = null;
            if (_shuttingDown) return false;

            SimHub.Logging.Current.Info("[TF4ALL] Discovering wheel...");
            var matches = WheelDiscovery.FindAll();
            if (matches.Count == 0)
            {
                WheelStatus = "Not detected (open/close G HUB once, then restart SimHub)";
                SimHub.Logging.Current.Warn(
                    "[TF4ALL] No supported wheel found. Make sure a supported wheel " +
                    "(G PRO / RS50 / G923) is plugged in. If it is, open G HUB once and let it " +
                    "finish detecting the wheel, then close G HUB (it must stay closed while this " +
                    "plugin runs) and restart SimHub.");
                LogDiscoveryDiagnostic();
                MaybeSwitchG923PsToPcMode();
                return false;
            }

            match = matches[0];
            _hidWheelVid = match.Vid;
            _hidWheelPid = match.Pid;
            _hidWheelProductString = match.ProductString;

            // Now that we know which wheel this is, make sure every arcade cabinet
            // we installed into is pointing at it. Installing with the wheel
            // unplugged, or swapping wheels afterwards, would otherwise leave those
            // games aimed at a device that is not there, which shows up as a game
            // that runs perfectly with a silent wheel.
            try { RefreshArcadeWheelSelection(); }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Warn($"[TF4ALL] Arcade wheel re-point failed: {ex.Message}");
            }

            // Wheels with a selectable rev-light pattern (G PRO and RS50) get
            // the LIGHTSYNC tab as a standing feature, no access code needed:
            // it is verified working on them. Auto-unlock once on first
            // sight; the LIGHTSYNC code still reveals the tab on other wheels.
            if (WheelHasSelectableLightPattern && Settings != null && !Settings.LightsyncTabUnlocked)
            {
                Settings.LightsyncTabUnlocked = true;
                try { PersistSettingsCore(); } catch { }
            }

            // Product-string identity outranks the PID table for the label: an
            // RS50 in G PRO compatibility mode enumerates under the G PRO PID
            // (c272) but keeps its RS50 product string (mescon, 2026-07).
            // Additive only: an unknown or unreadable string changes nothing.
            string modelLabel = WheelDiscovery.DisplayModel(match);
            if (!string.Equals(modelLabel, match.Model, StringComparison.Ordinal))
            {
                SimHub.Logging.Current.Info(
                    $"[TF4ALL] Product string '{match.ProductString}' identifies this as {modelLabel} behind PID 0x{match.Pid:X4}.");
            }
            WheelStatus = $"{modelLabel}  (VID 0x{match.Vid:X4}, PID 0x{match.Pid:X4})"
                        + (match.Unverified ? "  [unconfirmed model]" : "");
            SimHub.Logging.Current.Info($"[TF4ALL] Found {WheelStatus}.");

            // Remember the last wheel used on this PC for the Account "Active sessions"
            // list. Machine-local + persisted so it survives unplugs and restarts; only
            // written on a real detection (never cleared on a discovery miss), and only
            // persisted when it actually changes so we don't churn settings on reconnect.
            try
            {
                string shortModel = WheelDiscovery.ShortModel(modelLabel);
                if (!string.IsNullOrEmpty(shortModel) && Settings != null
                    && !string.Equals(Settings.LastUsedWheel, shortModel, StringComparison.Ordinal))
                {
                    Settings.LastUsedWheel = shortModel;
                    try { PersistSettingsCore(); } catch { }
                }

                // Per-wheel defaults merge, once per chassis + defaults generation
                // on this PC. Target = factory values + the detected wheel's own
                // defaults (G PRO / RS50 / G923 each have their own). Every recipe
                // field still holding a SHIPPED default (current factory, the
                // defaults this code wrote for the PREVIOUS wheel per the latch, or
                // any previously shipped recipe generation) upgrades to the target;
                // every field the user moved keeps its value (the silent-revert
                // lesson: user tuning is never touched without asking). So a fresh
                // install lands fully on its wheel's defaults, a strength-only
                // tuner still receives every other new default, and a fully dialed
                // setup is untouched (Reset applies the full defaults on demand).
                // Logged either way, so an update or wheel swap is never a feel
                // mystery.
                string latchTarget = shortModel + "#" + ModeBDefaultsGeneration;
                if (!string.IsNullOrEmpty(shortModel) && Settings != null
                    && !string.Equals(Settings.WheelDefaultsApplied, latchTarget, StringComparison.Ordinal))
                {
                    var target = new TrueforceSettings();
                    ApplyWheelDefaults(target, shortModel);

                    // Trueforce master gain, FRESH INSTALLS ONLY: the wheel's
                    // own starting level (the G923's belt renders the haptic
                    // stream fainter than the direct drives, so it starts at
                    // 1.5). Gated on the first-run signal AND on the gain still
                    // sitting exactly on the factory value, and it runs before
                    // the latch is stamped, so it happens at most once on a PC
                    // and an update never moves a level someone chose.
                    if (_wasFreshInstall && string.IsNullOrEmpty(Settings.WheelDefaultsApplied)
                        && Settings.MasterGain == new TrueforceSettings().MasterGain
                        && target.MasterGain != Settings.MasterGain)
                    {
                        float gainBefore = Settings.MasterGain;
                        Settings.MasterGain = target.MasterGain;
                        if (_mixer != null) _mixer.MasterGain = Settings.MasterGain;
                        SimHub.Logging.Current.Info(
                            $"[TF4ALL] New install: master gain {gainBefore:0.00} to {Settings.MasterGain:0.00} (the {shortModel} starting level).");
                        try { MasterGainChangedExternally?.Invoke(); } catch { }
                    }

                    var oldRecipes = new System.Collections.Generic.List<TrueforceSettings>
                    {
                        new TrueforceSettings(),   // current factory (per-wheel fields differ from target)
                    };
                    if (!string.IsNullOrEmpty(Settings.WheelDefaultsApplied))
                    {
                        // Prior latch names the wheel whose defaults this code last
                        // wrote (strip the #generation suffix; the first latched
                        // build stored the bare wheel name).
                        string priorLatch = Settings.WheelDefaultsApplied;
                        int gen = priorLatch.IndexOf('#');
                        string priorWheel = gen >= 0 ? priorLatch.Substring(0, gen) : priorLatch;
                        var priorDefaults = new TrueforceSettings();
                        ApplyWheelDefaults(priorDefaults, priorWheel);
                        oldRecipes.Add(priorDefaults);
                    }
                    oldRecipes.AddRange(PreviousShippedModeBRecipes());

                    int upgraded = MergeWheelDefaults(Settings, target, oldRecipes);
                    Settings.WheelDefaultsApplied = latchTarget;
                    if (upgraded > 0)
                    {
                        ApplyModeBFromSettings();
                        ApplyModeBFeel();
                        SimHub.Logging.Current.Info(
                            $"[TF4ALL] Applied the {shortModel} Mode B defaults: {upgraded} setting(s) still on shipped defaults moved to the new values; customized settings kept.");
                        // Repaint an open settings panel so stale sliders cannot
                        // write the old values back over the defaults (the Mode B
                        // write-all handler persists whatever the controls hold;
                        // same hazard the access-code path fixes the same way).
                        try { LibraryReloaded?.Invoke(); } catch { }
                    }
                    else
                    {
                        SimHub.Logging.Current.Info(
                            $"[TF4ALL] Wheel defaults check ({shortModel}): nothing to change (each Mode B setting already matches the {shortModel} defaults or is customized). 'Reset FFB tuning to defaults' applies the full {shortModel} defaults.");
                    }
                    try { PersistSettingsCore(); } catch { }
                }
            }
            catch { /* wheel-label persistence is best-effort, never block bring-up */ }

            // Unverified PIDs: resolve + stream by inference from the shared
            // HID++ family, but not hardware-tested. None today (every supported
            // PID is owner-confirmed), so this is dormant until a new wheel is
            // added on inference alone. Surface a notice asking the user to
            // report the one failure mode we can't rule out (init/handshake
            // divergence: Trueforce effects play but game FFB pass-through
            // stays silent).
            if (match.Unverified)
            {
                _unverifiedWheelNotice =
                    $"{modelLabel} is supported by inference but not hardware-tested. " +
                    "If the plugin's effects work but your game's force feedback is silent, " +
                    "please report it (Report an issue, at the bottom of the Settings tab; attach Export logs).";
                SimHub.Logging.Current.Warn($"[TF4ALL] {_unverifiedWheelNotice}");
            }
            else
            {
                _unverifiedWheelNotice = null;
            }

            return true;
        }

        // Blind-capture self-heal state. A "blind" USBPcap tap delivers the
        // wheel's ep0 control chatter but none of its interrupt traffic, so our
        // own ep3 stream is invisible to the capture and the game's FFB is
        // mirrored as nothing (limp wheel in Trueforce mode). The only fix is a
        // real re-enumeration (hub port cycle); a PnP restart is refused while
        // we hold the wheel. Capped so a wheel that stays blind after cycling
        // can't loop forever.
        private const int BlindCaptureMaxCycles = 2;
        private const int BlindProbeInitialDelayMs = 4000; // let the G923 re-attach settle first
        private const int BlindProbeStreamMs = 2000;       // force ep3 active across the measurement
        private const int BlindProbeWindowMs = 1500;       // measure interrupt-out over this window
        private int _blindCycleAttempts;
        private int _blindProbeInFlight;   // 0/1 guard, Interlocked

        // Measure whether the freshly started tap can see our ep3 stream, and
        // if not, re-enumerate the wheel once by cycling its hub port. Runs off
        // the bring-up thread. Self-guards: honors the setting, requires
        // elevation and a real Logitech identity, never fires while a game is
        // driving (a port cycle drops the wheel), and caps attempts per session.
        private void ScheduleBlindCaptureProbe(ushort vid, ushort pid)
        {
            if (!(Settings?.AutoReEnumerateOnBlindCapture ?? true)) return;
            if (!IsRunningElevated) return;
            if (vid == 0) return;                              // manual/unknown identity: no safe VID/PID to cycle
            if (_blindCycleAttempts >= BlindCaptureMaxCycles) return;
            if (System.Threading.Interlocked.CompareExchange(ref _blindProbeInFlight, 1, 0) != 0) return;

            var device = _device;
            var tap = _ffbTap;
            if (device == null || tap == null) { _blindProbeInFlight = 0; return; }

            System.Threading.Tasks.Task.Run(async () =>
            {
                try
                {
                    await System.Threading.Tasks.Task.Delay(BlindProbeInitialDelayMs);
                    if (_shuttingDown || !ReferenceEquals(_device, device) || !ReferenceEquals(_ffbTap, tap)) return;

                    // Never cycle the wheel out from under an active drive.
                    if (tap.GameFfbExpected) return;

                    // Force the ep3 stream active for the measurement even with
                    // no game running, then compare our successful writes to
                    // what the capture actually saw on the wheel's interrupt
                    // endpoint.
                    long sentBefore = device.PacketsSent;
                    long seenBefore = tap.InterruptOutSeen;
                    device.ForceActiveFor(BlindProbeStreamMs);
                    await System.Threading.Tasks.Task.Delay(BlindProbeWindowMs);
                    if (_shuttingDown || !ReferenceEquals(_device, device) || !ReferenceEquals(_ffbTap, tap)) return;

                    long sentDelta = device.PacketsSent - sentBefore;
                    long seenDelta = tap.InterruptOutSeen - seenBefore;

                    if (!TrueforceForAll.Core.BlindCaptureClassifier.IsInterruptBlind(sentDelta, seenDelta))
                    {
                        // Healthy (or we couldn't stream enough to judge). A
                        // capture that recovered resets the attempt budget.
                        if (seenDelta > 0) _blindCycleAttempts = 0;
                        return;
                    }

                    _blindCycleAttempts++;
                    SimHub.Logging.Current.Warn(
                        $"[TF4ALL] FFB capture is blind: streamed {sentDelta} packets to the wheel but the capture " +
                        $"saw none of them (USBPcap has no filter on this device). Re-enumerating the wheel by " +
                        $"cycling its USB port (attempt {_blindCycleAttempts}/{BlindCaptureMaxCycles}).");

                    bool ok = TrueforceForAll.Core.UsbHubPortCycler.TryCycleDevicePort(
                        vid, pid, msg => SimHub.Logging.Current.Info($"[TF4ALL] {msg}"), out string detail);

                    if (ok)
                    {
                        // The wheel disconnects and comes back on a fresh PDO;
                        // the reader thread's re-attach + the device-loss
                        // recovery re-run bring-up, which schedules another
                        // probe to confirm capture is now healthy.
                        SimHub.Logging.Current.Info($"[TF4ALL] Wheel re-enumeration requested ({detail}); reconnecting.");
                    }
                    else if (_blindCycleAttempts >= BlindCaptureMaxCycles)
                    {
                        SimHub.Logging.Current.Warn(
                            "[TF4ALL] Could not re-enumerate the wheel automatically (" + detail + "). "
                            + "Please unplug the wheel's USB cable and plug it back in, then it will work for this session.");
                    }
                    else
                    {
                        SimHub.Logging.Current.Warn($"[TF4ALL] Wheel re-enumeration attempt failed ({detail}); will retry on the next bring-up.");
                    }
                }
                catch (Exception ex)
                {
                    SimHub.Logging.Current.Warn($"[TF4ALL] Blind-capture probe error: {ex.Message}");
                }
                finally
                {
                    System.Threading.Interlocked.Exchange(ref _blindProbeInFlight, 0);
                }
            });
        }

        // Discover the wheel, open it, run the init sequence, start the FFB
        // tap and the 1 kHz stream. Returns true on success. Safe to call
        // repeatedly: the recovery watchdog calls this after CleanupDevice()
        // when the stream has faulted or no wheel was present yet. The
        // producer thread is plugin-lifetime and reused across re-attaches,
        // it's only created on the first successful bring-up.
        /// <summary>Discover the wheel and OPEN it: the HID handle, the init
        /// sequence, the FFB tap and the 1 kHz stream. Normal mode only. The two
        /// other modes call DiscoverWheel and stop there.</summary>
        private bool TryBringUpDevice()
        {
            WheelMatch match;
            if (!DiscoverWheel(out match)) return false;

            try
            {
                _device = new TrueforceDevice(match.Device);
                _device.Open();

                // Init sequence is required: empirically, skipping it leaves the
                // wheel in slower-default-rate mode and Trueforce response is
                // noticeably delayed (~game tick of latency). It does NOT cause
                // the FFB-suppression problem either way, diagnosed 2026-05-03.
                SimHub.Logging.Current.Info("[TF4ALL] Sending init sequence (68 packets x 2)...");
                _device.RunInitSequence();

                // Spawn the USBPcap FFB tap. Reads the game's outgoing HID++
                // FFB target off the bus and feeds it to TrueforceDevice so we
                // can mirror it into ep3 bytes 6-9. Without this, our ep3
                // stream overrides the game's FFB with zero motor torque when
                // Trueforce content plays (cur-as-torque-target confirmed by
                // mescon on RS50, 2026-07).
                // Override precedence: env var > persisted manual picker > auto.
                // The persisted picker exists because USBPcap's descriptor-cache
                // can go stale for hot-plugged wheels, leaving auto-discovery
                // unable to find a wheel that HID enumeration sees fine.
                var (ifaceOverride, devOverride) = ResolveUsbPcapOverride();
                _ffbTap = new UsbPcapFfbTap(ifaceOverride, devOverride, Settings?.UsbPcapCmdPathOverride)
                {
                    Logger = msg => SimHub.Logging.Current.Info($"[TF4ALL] {msg}"),
                    HostElevated = IsRunningElevated,
                };
                _ffbTap.SetHidDiscoveredWheel(match.Vid, match.Pid);
                _ffbTap.SetOverrideIdentity((ushort)(Settings?.ManualUsbPcapVid ?? 0), (ushort)(Settings?.ManualUsbPcapPid ?? 0));
                WireFfbTapCallbacks(_ffbTap);
                ApplyUsbBytesLoggingSetting();

                // Physical steering reader for the stationary spring (works when
                // the game reports no steering, e.g. a Forza countdown / pause).
                try
                {
                    _steeringReader = new WheelSteeringReader(match.Vid, match.Pid)
                    {
                        Logger = msg => SimHub.Logging.Current.Info($"[TF4ALL] {msg}"),
                    };
                    _steeringReader.Start();
                }
                catch (Exception ex)
                {
                    SimHub.Logging.Current.Warn($"[TF4ALL] Steering reader failed to start: {ex.Message}");
                    _steeringReader = null;
                }
                _device.FfbTargetProvider = () =>
                {
                    // Shutdown: the stream thread outlives most of End()'s
                    // teardown, and the wheel LATCHES whatever cur the final
                    // packet carried once the stream dies. Null here means
                    // silent packets, so the last thing on the wire before
                    // teardown is always a released wheel (the close-SimHub
                    // pull, 2026-08-08).
                    if (_shuttingDown) return null;
                    // DIDAMP spike / DAMPCAL native phase / FXTEST NATIVE:
                    // the stream is stopped outright for these, so a
                    // DirectInput effect we create is the only thing the
                    // firmware renders; null here covers the transition.
                    if (_diSpikeHold || _dampCalHold || _fxTestNativeHold) return null;

                    // Focus release. Same outcome as the pause release below
                    // and for the same physical reason, but the pause release
                    // needs an authoritative session flag or telemetry to
                    // stop, and a title still idling its car in the background
                    // offers neither, so the tap's last force streamed for its
                    // full hold and the wheel walked to lock.
                    if (_gameFocusLost && _autoTuner == null && _fxTestMode == 0
                        && _dampCal == null && !_diSpikeHold)
                    {
                        // Bench tools own the stream; a latched focus-loss
                        // from an idle background game must not silence them
                        // (audit stale-focus-latch / AT2-03).
                        NoteFfbSource("focus-release");
                        // Zero the game's CONSTANT force (the frozen value that
                        // walked the wheel to lock), but still render the
                        // game's decoded conditions: a title's menu centring
                        // is a DirectInput spring, and the wheel firmware does
                        // not render it while we stream. Without this the menu
                        // wheel went limp unless "hand the wheel back while
                        // paused" was on (owner, Forza, 2026-09-13).
                        return ReleasedWheelForce();
                    }

                    // Pause release (issue #13). When the game is paused / in a
                    // menu, replaying the last captured force is wrong: the FFB
                    // tap keeps returning that value for up to FfbTargetMaxAgeMs
                    // (10 s), and with no self-aligning torque on a stationary
                    // car a held force walks the wheel to its rotational stop
                    // ("snaps to full lock"). Return 0 (cur = 0x8000, zero motor
                    // force) so the wheel goes free instead.
                    //   - An authoritative pause flag (Forza IsRaceOn) is the
                    //     reliable case: telemetry keeps flowing during a Forza
                    //     pause, so only the flag tells us we're paused.
                    //   - MeasuredHz <= 0 covers games that simply stop sending
                    //     telemetry when paused, for any source.
                    // We do NOT release on the physics proxy alone, since it
                    // also reads inactive at a legitimate standstill (grid,
                    // stall), which would drop FFB mid-session.
                    var src = _telemetrySource;
                    // This zero-return applies to Mode B as well, on every
                    // Forza title: IsRaceOn is "is the player driving" (1 in
                    // free-roam too, despite the name), 0 during pause / menu
                    // / cutscene / replay, exactly when the synthesized force
                    // should be quiet. Keepalive packets no longer flap the
                    // flag mid-race (see ForzaUdpTelemetrySource.ShouldEmit),
                    // so this reads stable while driving.
                    // DAMPCAL / AUTO-TUNE own the stream while they run (no
                    // game, so IsSessionActive is false and this release
                    // branch would short-circuit their scripted output before
                    // it ever reached the wheel; verify workflow 2026-09-01).
                    if (src != null && !src.IsSessionActive && _dampCal == null && _autoTuner == null
                        // FXTEST ENGINE with no game: the always-attached
                        // SimHub fallback source reads "paused" here and this
                        // early return silenced every bench engine effect
                        // (rig, 2026-09-01). The bench owns the stream too.
                        && _fxTestMode == 0
                        && (src.HasAuthoritativeSessionState || src.MeasuredHz <= 0))
                    {
                        // Paused / menu / pre-race countdown / race-end results.
                        // Earlier versions tried a SHORT-freshness pass-through
                        // here on the theory that paused games either stop
                        // sending FFB (so the tap goes stale and we release) or
                        // send a gentle centering force we should preserve. FH6
                        // does neither: it keeps re-emitting FFB packets during
                        // pause / results / pre-race transitions that often
                        // carry the frozen pre-pause force (the wheel position
                        // at the moment the pause hit, which during cornering
                        // is a hard force pegged to one side). The tap
                        // re-timestamps on every captured packet regardless of
                        // value, so the freshness check never expired and we
                        // streamed that force as cur on ep3, and the wheel
                        // snapped to or sat on full lock until the user resumed.
                        //
                        // The stationary-spring layer is skipped here on the
                        // capture route: the spring is designed for a
                        // STATIONARY car during an ACTIVE driving session (e.g.
                        // AC's pre-race grid) and it conflicted with Forza's own
                        // FFB across pause-state transitions. Under Telemetry
                        // Based FFB the game's force is not on the wire, so
                        // ReleasedWheelForce renders our spring there.
                        NoteFfbSource("pause-release");
                        // As on the focus release above: the constant force is
                        // silenced, the game's spring and damper shapes still
                        // play through the DirectInput engine, so a pause menu
                        // centres the wheel the way the game intends.
                        return ReleasedWheelForce();
                    }

                    // EXPERIMENTAL driver-intercept path takes precedence ONLY
                    // when it's active AND has a fresh sample. The intercepted
                    // bytes ARE the game's HID++ 0x8123 fn2 frames; USBPcap
                    // won't see them once the driver completes the write before
                    // it reaches the USB stack. _driverChannel is non-null only
                    // when ExperimentalDriverIntercept is on (it's gated in Init),
                    // so when the setting is off this whole block is skipped and
                    // the FFB pipeline behaves exactly as it does without the
                    // feature: fall back to the USBPcap tap.
                    short? chosen = null;
                    string ffbSrc = "none";
                    if (_driverChannel != null && _driverChannel.IsOpen)
                    {
                        chosen = _driverChannel.TryGetFreshFfbTarget(_device.FfbTargetMaxAgeMs);
                        if (chosen.HasValue) ffbSrc = "driver";
                    }
                    // Force from Assetto Corsa itself, no USBPcap involved.
                    // Automatic: CspBridgeFfbEnabled defaults on and exists
                    // only as a dev force-off (the CSPFFB access code); there
                    // is no user checkbox. When the TF4ALL CSP Bridge script
                    // (gamemods/AssettoCorsaCsp) is installed it supplies;
                    // when it is not, the bridge is never fresh and we fall
                    // through to the USB tap below (the "finalff" field reads
                    // AC's own page and needs no script). The bridge's "pure"
                    // and "torque" fields are PRE-gain, the only ones that
                    // still carry force with the in-game gain at 0, so the
                    // game writes nothing to the wheel and LED or screen
                    // writes have nothing to collide with. The default
                    // "value" and finalFF are post-gain, so in-game FFB must
                    // stay ON for them: gain 0 zeroes finalFF and the source
                    // hands back to the tap when it sees that. Consulted
                    // after the driver intercept and before the pcap tap, so
                    // a machine that also has USBPcap running doesn't deliver
                    // the same signal twice. SHORT freshness window on
                    // purpose: the latch only re-timestamps on new physics
                    // packets, so a paused AC (frozen page) ages out here
                    // within a quarter second instead of replaying a held
                    // force for FfbTargetMaxAgeMs (the issue #13 class); a
                    // ~333 Hz source that missed ~80 ticks is not driving.
                    if (!chosen.HasValue && (Settings?.CspBridgeFfbEnabled ?? true))
                    {
                        const int cspMaxAgeMs = 250;
                        var acSrc = _telemetrySource as AcSharedMemoryTelemetrySource;
                        if (acSrc != null)
                        {
                            // "finalff" reads AC's vanilla finalFF (the field
                            // FFB Clip reads too); the CSP script only frees the
                            // pipe. Everything else reads the bridge field.
                            if (CspFieldIsFinalFf)
                            {
                                chosen = acSrc.TryGetFreshFfbTarget(cspMaxAgeMs);
                                if (chosen.HasValue) ffbSrc = "csp:finalff";
                            }
                            else
                            {
                                chosen = acSrc.TryGetFreshCspFfbTarget(cspMaxAgeMs);
                                if (chosen.HasValue) ffbSrc = "csp";
                            }
                        }
                    }
                    // Arcade cabinets under TeknoParrot. The game writes its force
                    // to the emulated IO board, so this is the game's own force,
                    // read from a published block rather than sniffed off the wire.
                    // Consulted before the tap so a machine also running USBPcap
                    // does not deliver the same signal twice. Only the constant
                    // command lands here; springs and rumble are effect shapes and
                    // go to the DI engine instead, which is why this can be null
                    // while the cabinet is still commanding something.
                    if (!chosen.HasValue)
                    {
                        var arcSrc = _telemetrySource as IArcadeForceSource;
                        if (arcSrc != null)
                        {
                            // Short window for the same reason as AC's: the reader
                            // stops latching the moment the IO block freezes, and
                            // anything older than this is a pause we should not be
                            // replaying into the wheel.
                            chosen = arcSrc.TryGetFreshFfbTarget(250);
                            if (chosen.HasValue) ffbSrc = "arcade";
                        }
                    }

                    // True when the value below is a quiet-spell substitute, not
                    // a captured force. The trace must record the tap as stale
                    // then, or a TRACE CSV could no longer tell a stale edge
                    // from a captured zero (a classic STOP publishes a real 0).
                    bool tapQuiet = false;
                    if (!chosen.HasValue)
                    {
                        // The wire tap answers TWO questions, on two windows.
                        //
                        // "Is this value still current?" 500 ms. The tap
                        // re-timestamps only on a captured packet, so a game
                        // that stops sending, on a pause it never announces or
                        // on losing focus, used to leave us streaming its last
                        // force for ten seconds with no self-aligning torque to
                        // oppose it, and the wheel walked to its rotational stop
                        // (Wreckfest alt-tab, owner 2026-08-16; same class as
                        // issue #13). Nothing older than 500 ms is replayed.
                        //
                        // "Is the game still driving the wheel?" FfbTargetMaxAgeMs
                        // (10 s). This one decides the PACKET SHAPE, and that
                        // matters because the audio window only rides active
                        // packets: a null here means keepalive, and keepalive
                        // carries no effects at all (TrueforceDevice.StreamTick).
                        // The Logitech force path never resends an unchanged
                        // value (owner's captures, 2026-08-28: holes of 0.5 to
                        // 7.5 s are routine with a parked or held wheel; driving
                        // never gaps past 100 ms), so a parked car goes quiet on
                        // the wire within a second. Collapsing both questions
                        // into the 500 ms window (2026-08-17 to 2026-08-28) muted
                        // every effect and the stationary spring at any
                        // standstill, and touching a pedal brought them back
                        // for half a second at a time.
                        //
                        // So: a current value streams as is; a game that has
                        // gone quiet gets ZERO force in the ACTIVE shape (the
                        // audio window survives, the spring can still center a
                        // parked car, and a held force still cannot outlive
                        // 500 ms). "Gone quiet" is decided by the session, not
                        // by a clock: a 10 s window shipped first and a tester's
                        // RS50 parked in AC sat 25 s between force writes, so the
                        // effects died after ten seconds and needed a gear change
                        // to come back. The hold now lasts as long as telemetry
                        // says the car is live, the tap has decoded force this
                        // session, the capture is still delivering packets, and
                        // no force write is arriving that we are not decoding.
                        // Each guard closes one way of holding a zero on a wheel
                        // the game is actually driving: a tap-less rig never
                        // decodes (no hold, native FFB as before), a capture that
                        // dies stops delivering packets within milliseconds (our
                        // own ep3 stream is in that count), and an undecoded
                        // shape trips the traffic guard. A game that holds a
                        // static non-zero force through a park without resending
                        // it is the one case this zeroes, and none of the games
                        // we capture does that.
                        const int pcapStreamMaxAgeMs = 500;
                        chosen = _ffbTap?.TryGetFreshFfbTarget(pcapStreamMaxAgeMs);
                        if (chosen.HasValue) ffbSrc = "pcap";
                        else if (_ffbTap != null
                                 // The game has driven the wheel this session
                                 // (the arbiter settled on a report) and the car
                                 // is live by telemetry, or the last force is
                                 // simply recent.
                                 && (_ffbTap.TryGetFreshFfbTarget(_device?.FfbTargetMaxAgeMs ?? 10000).HasValue
                                     || (_ffbTap.LiveForceReport != 0 && (src?.IsSessionActive ?? false))
                                     // A live decoded condition/periodic is
                                     // game FFB too: without this, a game that
                                     // sends only parametric effects never
                                     // enters the active shape and the engine
                                     // renders to nobody (audit 2026-09-01).
                                     || _ffbTap.AnyHidppParametricPlaying)
                                 // The capture itself is alive: packets for the
                                 // wheel within the last two seconds.
                                 && _ffbTap.MsSinceDevicePacket < 2000
                                 // A quiet spell is the GAME going quiet. If the
                                 // wheel is still receiving force writes we are not
                                 // decoding (an undecided report, the NOFFB
                                 // simulation), holding an active zero would cancel
                                 // the game's own force; keepalive hands it back.
                                 && !_ffbTap.ForceTrafficSinceLastSample)
                        {
                            chosen = (short)0;
                            ffbSrc = "pcap-quiet";
                            tapQuiet = true;
                        }
                    }
                    // Farming Simulator streams NO real force values on any
                    // wheel (trace-proven): a captured scalar there is by
                    // definition a misdecode (the G PRO's constant HID++
                    // heartbeat reads as a large constant force). Spring mode
                    // replaces the target while armed, but the misdecode used
                    // to leak through every window where _forceMode was
                    // still 0: the cold-start arming dwell, the 1 s+ after
                    // any disarm, and whole sessions with the spring toggle
                    // off (2026-08-08 review). Drop it at the source instead
                    // of trusting the arming state machine's timing.
                    if (chosen.HasValue && _activeGame != null
                        && _activeGame.StartsWith("FarmingSimulator", StringComparison.Ordinal))
                    {
                        chosen = null;
                        ffbSrc = "none";
                    }
                    if (_driverChannel != null)
                    {
                        long diagTick = System.Threading.Interlocked.Increment(ref _ffbDiagTick);
                        if ((diagTick % 1000) == 1)
                            SimHub.Logging.Current.Info(
                                $"[TF4ALL] ffb-pipeline tick#{diagTick} src={ffbSrc} target={(chosen.HasValue ? chosen.Value.ToString() : "null")} driverDecoded={_driverChannel.FfbSamplesDecoded}");
                    }
                    // Mode B rides this tail: MaybeReshapeFfb REPLACES the
                    // game-derived target with the synthesized force while
                    // Mode B is armed (everything the spring added is
                    // discarded with it; the spring is also excluded for the
                    // whole Forza session, and all Mode B games are Forza).
                    // DAMPCAL friction/synth conditions: the stream in raw
                    // torque mode at zero, so only friction (and the
                    // synthesized damper below) act on the wheel.
                    // AUTO-TUNE owns the stream through its engine phases:
                    // the scripted probe pulse plus the effect under test,
                    // nothing else may shape the wheel.
                    var autoTuner = _autoTuner;
                    if (autoTuner != null)
                    {
                        NoteFfbSource("autotune");
                        return AutoTuneTick(autoTuner);
                    }
                    if (_dampCalActiveZero)
                    {
                        // Calibration is authoritative: raw zero plus ONLY
                        // the synthesized damper under test. The reshape /
                        // stationary-spring tail must not repaint the
                        // calibration zero (verify workflow 2026-09-01).
                        NoteFfbSource("dampcal");
                        return AddSynthesizedDamper((short)0);
                    }
                    // The game's DirectInput conditions (damper, spring,
                    // friction, inertia), periodics and ramps, decoded off the
                    // wire by the tap, ride the game force here. Only in the
                    // ACTIVE shape: a null (keepalive) hands the wheel back
                    // to the firmware, which then renders them itself.
                    chosen = AddHidppDiEffects(chosen);
                    // FXTEST ENGINE: a hand-triggered synthetic effect through
                    // the same renderer, streamed even with no game (base 0).
                    chosen = ApplyFxTestEngine(chosen);
                    // Arcade cabinets command springs and rumble as DirectInput
                    // effect shapes, not as a torque. Rendered here, after the
                    // scalar constant the source publishes, for the same reason
                    // FXTEST is here: `(force ?? 0) + t` streams with no game
                    // force at all, which AddHidppDiEffects cannot do.
                    chosen = ApplyArcadeEffects(chosen);
                    var afterSpring = ApplyStationarySpringIfActive(chosen);
                    var finalOut    = MaybeReshapeFfb(afterSpring);
                    finalOut = AddSynthesizedDamper(finalOut);
                    // LAST, deliberately. A soft lock is a wall, and its whole
                    // value is the sharpness of its onset: run it through spike
                    // reduction or the smoothing above and it arrives as a
                    // suggestion. Owner's call (2026-09-09) that it applies at
                    // the very end of our chain rather than riding ffbValue.
                    // All three locks land here: the AC bridge's, and the ones
                    // built for iRacing and RaceRoom from each sim's own
                    // steering position and lock.
                    finalOut = ApplySoftLock(finalOut);
                    TraceFfb(tapQuiet ? (short?)null : chosen, afterSpring, finalOut);
                    NoteFfbSource(finalOut.HasValue
                        ? (chosen.HasValue ? ffbSrc : "authored")
                        : "keepalive");
                    return finalOut;
                };
                _device.FfbScale                 = Settings.FfbScale;
                _device.FfbInvertSign            = Settings.FfbInvertSign;
                _device.FfbSmoothTimeConstantMs  = EffectiveSmoothingMs();
                _device.FfbSpikeTamingEnabled    = Settings.FfbSpikeTamingEnabled;
                _device.FfbSpikeUseSlewLimiter   = Settings.FfbSpikeUseSlewLimiter;
                _device.FfbSpikeMaxLsbPerMs      = Settings.FfbSpikeMaxLsbPerMs;
                _device.FfbPeakSoftLimitLsb      = Settings.FfbPeakSoftLimitLsb;
                _device.FfbSpikeTransientThresholdLsb = Settings.EffectiveSpikeTransientThresholdLsb;

                // Persisted condition-render tuning (FXTEST / DAMPCAL): the
                // gains, damper direction, inertia mode and output filter below
                // are every-session defaults, not session-only knobs.
                _damperGain      = (float)Settings.FfbConditionDamperGain;
                _damperSign      = Settings.FfbConditionSignInverted ? -1 : 1;
                _conditionLpfHz  = Settings.FfbConditionLpfHz;
                _damperLpfHz     = Settings.FfbConditionDamperLpfHz;
                _springLpfHz     = Settings.FfbConditionSpringLpfHz;
                _frictionLpfHz   = Settings.FfbConditionFrictionLpfHz;
                _inertiaLpfHz    = Settings.FfbConditionInertiaLpfHz;
                _springGain      = (float)Settings.FfbConditionSpringGain;
                _frictionGain    = (float)Settings.FfbConditionFrictionGain;
                _inertiaGain     = (float)Settings.FfbConditionInertiaGain;
                _periodicGain    = (float)Settings.FfbConditionPeriodicGain;
                _rampGain        = (float)Settings.FfbConditionRampGain;
                _inertiaCoasts   = Settings.FfbConditionInertiaCoasts;
                _inertiaAsDamping = Settings.FfbConditionInertiaAsDamping;
                ApplyConditionLpf();

                // Apply persisted ring capacity. Sanitize: a value outside the
                // allowed range falls back to the default, an in-range one
                // rounds down to a power of two, so a hand-edited settings file
                // can't crash the plugin. Settings is updated back so the UI
                // sees the same value the device runs on.
                Settings.Performance.TfRingSize = SanitizePow2(
                    Settings.Performance.TfRingSize,
                    TrueforceDevice.MinRingSize, TrueforceDevice.MaxRingSize, TrueforceDevice.DefaultRingSize);
                _device.SetRingCapacity(Settings.Performance.TfRingSize);

                _ffbTap?.Start();

                _device.StartStream();

                // If USBPcap came up blind (no capture filter on the wheel,
                // typically because the wheel's device stack was built before
                // USBPcap's hub filter at boot), re-enumerate the wheel by
                // cycling its hub port so the tap can actually see the game's
                // FFB. Fire-and-forget; self-guards on setting/elevation/driving
                // and caps its own attempts. See ScheduleBlindCaptureProbe.
                ScheduleBlindCaptureProbe(match.Vid, match.Pid);

                // The producer is plugin-lifetime and reads the _device field
                // each iteration, so a re-attach reuses the existing thread
                // (it idles harmlessly while _device is null between attempts,
                // see ProducerLoop). Only create it on the first bring-up, or
                // if it somehow died, never a second concurrent producer.
                if (_producerThread == null || !_producerThread.IsAlive)
                {
                    _producerThread = new Thread(ProducerLoop)
                    {
                        IsBackground = true,
                        Name = "TrueforceProducer",
                        Priority = ThreadPriority.AboveNormal,
                    };
                    _producerThread.Start();
                }

                _streamStatus = "Streaming (4 kHz, 1000 packets/s)";
                SimHub.Logging.Current.Info("[TF4ALL] Stream started.");

                // Master toggle may already be off at bring-up (persisted from
                // a prior session, e.g. auto-disabled for a native-Trueforce
                // game), and StartStream just force-reset the pause flag.
                // Without this reconcile the pump emits keepalives at 1 kHz on
                // ep3 forever while "disabled", and a native-Trueforce game's
                // own ep3 stream interleaves with ours at the wheel as harsh
                // garbage vibrations (issue #37). Mirrors the toggle-off wire
                // sequence (Stop, then Pause; StreamTick dispatches the pending
                // Stop before the pause gate). Also covers the recovery
                // watchdog and the manual reconnect, which re-attach through
                // this same path and would otherwise un-pause a disabled
                // plugin.
                SyncDeviceToPluginEnabled("Bring-up");
            }
            catch (Exception ex)
            {
                _streamStatus = $"Init failed: {ex.Message}";
                SimHub.Logging.Current.Error("[TF4ALL] Init failed", ex);
                CleanupDevice();
                return false;
            }
            return true;
        }

        // Verbose diagnostic for the "wheel not detected" state: dumps what HidSharp
        // currently sees on the Logitech VID so a recurrence in the field tells us
        // whether the wheel is genuinely absent, present without its MI_02 Trueforce
        // interface (G HUB holding it / a partial enumeration), or in console mode
        // (wheel-like name, unsupported PID). Throttled to once per minute by
        // _lastDiscoveryDiagTicks; the recovery watchdog retries every few seconds.
        private void LogDiscoveryDiagnostic()
        {
            long now = Stopwatch.GetTimestamp();
            if (_lastDiscoveryDiagTicks != 0
                && now - _lastDiscoveryDiagTicks < Stopwatch.Frequency * 60)
                return;
            _lastDiscoveryDiagTicks = now;

            try
            {
                int total = 0, mi02 = 0;
                var sb = new System.Text.StringBuilder();
                foreach (var dev in HidSharp.DeviceList.Local.GetHidDevices(WheelDiscovery.LogitechVid))
                {
                    total++;
                    int pid; try { pid = dev.ProductID; } catch { pid = 0; }
                    string path; try { path = dev.DevicePath ?? ""; } catch { path = ""; }
                    bool isMi02 = path.IndexOf("mi_02", StringComparison.OrdinalIgnoreCase) >= 0;
                    if (isMi02) mi02++;
                    if (sb.Length > 0) sb.Append(", ");
                    sb.Append($"0x{pid:X4}").Append(isMi02 ? " [MI_02]" : "");
                }
                string hids = total == 0 ? "none"
                    : $"{total} interface(s) [MI_02 present: {mi02 > 0}] PIDs {sb}";

                int consoleMode = 0;
                try { consoleMode = WheelDiscovery.FindUnsupportedWheelLike().Count; } catch { }
                int noTfIface = 0;
                try { noTfIface = WheelDiscovery.FindSupportedWithoutTrueforceInterface().Count; } catch { }

                SimHub.Logging.Current.Info(
                    "[TF4ALL] Discovery diagnostic (wheel not found): "
                    + $"Logitech HID = {hids}; supported-wheel-without-MI_02 = {noTfIface}; "
                    + $"wheel-like-unsupported-PID (console mode?) = {consoleMode}; "
                    + $"G HUB UI running = {_isGHubRunning}.");
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Info($"[TF4ALL] Discovery diagnostic failed: {ex.GetType().Name}: {ex.Message}");
            }
        }

        // One-time pipeline setup: loopback helper, audio capture, telemetry
        // effects, telemetry source, capture-poll thread. Split out of Init so
        // device bring-up can fail and retry independently. Runs exactly once
        // from Init regardless of whether the wheel came up; the recovery
        // watchdog only re-attaches the device (TryBringUpDevice), never this,
        // so effects/audio/telemetry are constructed a single time and simply
        // start producing the moment the device re-attaches.
        private void InitPipeline()
        {
            // Sweep orphaned capture children from a previous SimHub run that
            // died hard (taskkill /F, crash): an orphaned USBPcapCMD holds the
            // USBPcap device AND our UDP sockets under a dead PID, so the tap
            // and the Forza listener silently fail until it is gone. New
            // children are job-bound (ChildProcessJob.TryAssign) so they die
            // with us; this sweep is the recovery path for the old ones.
            try
            {
                ChildProcessJob.KillOrphans("USBPcapCMD",
                    msg => SimHub.Logging.Current.Info($"[TF4ALL] {msg}"));
            }
            catch { }

            // What follows is split by mode. The orphan sweep above runs in ALL of
            // them (it only cleans up, and a capture child left by a previous full
            // session would otherwise hold the USBPcap device forever), but every
            // subsystem below either opens hardware, spawns a process or starts a
            // thread, and lights-only promises none of that. The effects and the
            // engine loop ARE still constructed in every mode: they are inert
            // objects until the producer thread ticks them, that thread only exists
            // after a successful bring-up, and leaving them null would null-ref
            // every settings binding and redline lookup that reads them.
            bool fullPipeline = MasterMode == TrueforceMasterMode.Normal;

            // Spawn the loopback helper child process. It does the actual
            // per-process WASAPI loopback in modern .NET (where COM interop is
            // reliable), and streams audio bytes back to us over stdout.
            if (fullPipeline)
            {
                try
                {
                    string pluginDir = System.IO.Path.GetDirectoryName(typeof(TrueforcePlugin).Assembly.Location);
                    string helperExe = System.IO.Path.Combine(pluginDir, "TrueforceForAll.LoopbackHelper.exe");
                    _helperHost = new HelperHost(helperExe);
                    _helperHost.Spawn();
                    SimHub.Logging.Current.Info($"[TF4ALL] Loopback helper spawned ({helperExe}).");
                }
                catch (Exception ex)
                {
                    SimHub.Logging.Current.Error("[TF4ALL] Failed to spawn loopback helper", ex);
                    _helperHost = null;
                }

            }

            // Audio capture: create the source, attach it to the helper, hook it
            // into the mixer. Capture stays inactive (silent) until the poll thread
            // detects a sim and tells the host to retarget.
            //
            // The SOURCE is built in every mode and the ATTACH is not. Constructing
            // it opens no device (the capture itself lives in the helper child), and
            // a dozen settings, preset and import paths write to _audio without a
            // null check, so leaving it null would turn a mode switch into a crash
            // the next time anyone touched an audio slider. With no helper attached
            // and no mixer registration it simply never produces a sample.
            _audio = new AudioCaptureSource
            {
                Enabled = Settings.AudioCapture.Enabled,
                Gain    = Settings.AudioCapture.Gain,
            };
            Settings.Performance.AudioRingSize = SanitizePow2(
                Settings.Performance.AudioRingSize,
                AudioCaptureSource.MinRingSamples, AudioCaptureSource.MaxRingSamples, AudioCaptureSource.DefaultRingSamples);
            _audio.SetRingCapacity(Settings.Performance.AudioRingSize);
            if (fullPipeline)
            {
                if (_helperHost != null) _audio.Attach(_helperHost);
                _mixer.Add(_audio);
                _audioInMixer = true;
            }

            // Telemetry effects: construct them, register in the mixer in
            // display order. Frames reach them from the engine loop's 500 Hz
            // resampled tick on the producer thread, not the telemetry thread
            // (the active ITelemetrySource's OnFrame lands in DispatchFrame
            // below, which ingests into the loop).
            EnginePulse  = new EnginePulseEffect();
            RoadBumps    = new RoadBumpsEffect();
            TractionLoss = new TractionLossEffect
            {
                // The engine assembly carries no SimHub reference; the host
                // injects the diagnostic sink.
                DiagLog = m => SimHub.Logging.Current.Info(m),
            };
            AxleSlip     = new AxleSlipEffect();
            KerbThump    = new KerbThumpEffect();
            LockupJudder = new LockupJudderEffect();
            GearShift    = new GearShiftEffect();
            AbsClick     = new AbsClickEffect();
            PitLimiter   = new PitLimiterEffect();
            Drs          = new DrsEffect();
            Collision    = new CollisionEffect();
            RevLimiter   = new RevLimiterEffect();
            // Diagnostic-only voice: renders solely during its TestPlay
            // window (SWEEP access code); telemetry never drives it.
            MotorSweep    = new MotorSweepEffect();
            ImplementThud = new ImplementThudEffect();
            Airborne     = new AirborneEffect();
            // Airborne is last: it's a coordinator, not a voice, but it still
            // needs OnTelemetry (to read frame.Airborne) and Reset, both of
            // which are fanned out over _effects (OnTelemetry by the engine
            // loop, Reset by the plugin). Its no-op RenderAdd in the mixer
            // costs nothing.
            _effects = new TelemetryEffect[] { EnginePulse, RoadBumps, TractionLoss, AxleSlip, KerbThump, LockupJudder, GearShift, AbsClick, PitLimiter, Drs, Collision, RevLimiter, MotorSweep, ImplementThud, Airborne };
            foreach (var fx in _effects) _mixer.Add(fx);

            // Sidechain ducker (Engine assembly): a field per ducked effect,
            // all null-checked inside (MotorSweep has none: ActivityLevel 0,
            // it never ducks). Audio is re-assigned every producer tick
            // because the capture source is created after Init and can be
            // retargeted live.
            _ducking.EnginePulse  = EnginePulse;
            _ducking.RoadBumps    = RoadBumps;
            _ducking.TractionLoss = TractionLoss;
            _ducking.AxleSlip     = AxleSlip;
            _ducking.KerbThump    = KerbThump;
            _ducking.LockupJudder = LockupJudder;
            _ducking.GearShift    = GearShift;
            _ducking.AbsClick     = AbsClick;
            _ducking.PitLimiter   = PitLimiter;
            _ducking.Drs          = Drs;
            _ducking.Collision    = Collision;
            _ducking.RevLimiter   = RevLimiter;
            _ducking.ImplementThud = ImplementThud;
            _ducking.Airborne     = Airborne;

            // The engine tick: effect OnTelemetry at a fixed 500 Hz on
            // resampled frames, then ducking, mixer render, silence floor,
            // device push. The resampler runs on Stopwatch time in
            // production; the replay harness constructs its own EngineLoop
            // on a virtual clock.
            _engineLoop = new EngineLoop(_mixer, _ducking, new DeviceSink(this),
                new FrameResampler(Stopwatch.Frequency))
            {
                Effects = _effects,
            };

            // Load the persisted Mode B tunables into the live model (arming
            // happens on game change, once _activeGame is known).
            ApplyModeBFromSettings();
            // Push the persisted Mode B feel toggles into the live models.
            ApplyModeBFeel();

            _rpmLeds = new RpmLedController(msg => SimHub.Logging.Current.Info(msg));
            _oledDash = new OledDashController(msg => SimHub.Logging.Current.Info(msg));
            _audioLeds = new AudioOutputMeter(msg => SimHub.Logging.Current.Info(msg));
            // Constructed always, started only if the user has asked for it.
            SyncAudioOutputMeter();

            // Repay a light slot a CRASHED session left borrowed. Backgrounded
            // because it may have to open the HID++ channel, and plugin init must
            // not block on the wheel. A normal launch answers this from disk with
            // nothing owed and never touches the hardware at all.
            Task.Run(() =>
            {
                try
                {
                    // Bring the channel up now when lighting is in use, so the
                    // first pattern pick or bound button press acts immediately
                    // instead of being the one that quietly opens it.
                    if (MasterMode != TrueforceMasterMode.Off
                        && (LovelyLightingEnabled || Settings?.LightsyncTabUnlocked == true))
                        EnsureLedChannelOpen();

                    // RestoreOwedSlots stays unconditional in every mode, Off
                    // included. It answers "nothing owed" from disk without
                    // touching the wheel, and when something IS owed it is the
                    // only route back to the user's own colors after a crash.

                    string restored = RestoreOwedSlots();
                    if (!string.IsNullOrEmpty(restored)) SimHub.Logging.Current.Info("[TF4ALL] " + restored);
                }
                catch (Exception ex)
                {
                    SimHub.Logging.Current.Warn("[TF4ALL] owed-slot restore at launch failed: " + ex.Message);
                }
            });

            // EXPERIMENTAL: open the kernel-driver IOCTL channel ONLY when the
            // user has opted in via ExperimentalDriverIntercept (hidden DRIVER
            // access code). Wrapped in try/catch so a missing or misbehaving
            // driver can never crash plugin init. The channel itself is also
            // fault-tolerant: if the driver isn't installed, construction
            // succeeds but IsOpen = false. When the setting is off, none of
            // this runs and _driverChannel / _driverLedChannel stay null.
            // Normal only: it opens its own HID++ channel to the wheel and puts the
            // kernel filter driver into the write path between the game and the
            // wheel, which is the largest possible violation of "touch nothing".
            if (fullPipeline && Settings != null && Settings.ExperimentalDriverIntercept)
            {
                try
                {
                    SimHub.Logging.Current.Info("[TF4ALL] ExperimentalDriverIntercept enabled; opening TFFA filter control channel...");

                    // Plugin-owned HID++ LED channel: while the filter driver
                    // owns the wheel and we are the only authorised writer, our
                    // LED writes don't contend with game FFB writes.
                    _driverLedChannel = new WheelLedChannel(msg => SimHub.Logging.Current.Info(msg));
                    bool ledOk = false;
                    try { ledOk = _driverLedChannel.OpenAndResolve(); }
                    catch (Exception ex) { SimHub.Logging.Current.Warn($"[TF4ALL] driver-LED channel open threw: {ex.GetType().Name}: {ex.Message}"); }
                    if (!ledOk)
                    {
                        SimHub.Logging.Current.Warn("[TF4ALL] driver-LED channel did not open; LED path disabled this session (retries on wheel re-attach).");
                        try { _driverLedChannel?.Dispose(); } catch { }
                        _driverLedChannel = null;
                    }
                    else
                    {
                        SimHub.Logging.Current.Info("[TF4ALL] driver-LED channel open and ready.");
                    }

                    _driverChannel = new TFFADriverChannel(
                        log: msg => SimHub.Logging.Current.Info(msg),
                        onIntercepted: (buf, len) =>
                        {
                            long n = System.Threading.Interlocked.Increment(ref _driverChannelIntercepts);
                            // The driver intercepts the game's FFB (feat 0x0E)
                            // and LED (feat 0x09) writes. RecvLoop decodes the
                            // int16 target at bytes 10-11 of CONSTANT FFB
                            // writes (condition downloads are dropped) into the
                            // channel's _packed for the TF stream packer to use
                            // as ep3 cur; that already happened before this
                            // callback. Here we only classify for logging - we
                            // do NOT echo (FFB is absorbed after decode, LEDs
                            // are driven by the plugin from telemetry), so the
                            // wheel only receives writes the plugin produced.
                            string klass = "other";
                            if (len >= 4)
                            {
                                byte b0 = buf[0], b1 = buf[1], b2 = buf[2], b3 = buf[3];
                                bool hidpp = (b0 == 0x10 || b0 == 0x11 || b0 == 0x12) && b1 == 0xFF;
                                if (hidpp)
                                {
                                    if (b2 == 0x0E && ((b3 & 0xF0) == 0x20 || (b3 & 0xF0) == 0x30)) klass = "FFB";
                                    else if (b2 == 0x09) klass = "LED";
                                }
                            }

                            if (n <= 30 || (n % 100) == 1)
                            {
                                int show = len < 12 ? len : 12;
                                var sb = new System.Text.StringBuilder(160);
                                sb.AppendFormat("[TF4ALL] intercept #{0} len={1} class={2} decoded={3} bytes[0..{4}]=",
                                    n, len, klass,
                                    _driverChannel != null ? _driverChannel.FfbSamplesDecoded : 0,
                                    show - 1);
                                for (int i = 0; i < show; i++) { if (i > 0) sb.Append(' '); sb.AppendFormat("{0:X2}", buf[i]); }
                                SimHub.Logging.Current.Info(sb.ToString());
                            }
                        });
                    if (_driverChannel.IsOpen)
                    {
                        SimHub.Logging.Current.Info("[TF4ALL] TFFA filter channel open; plugin is now the wheel owner.");
                    }
                    else
                    {
                        SimHub.Logging.Current.Warn("[TF4ALL] TFFA filter channel did not open; experimental intercept inactive this session.");
                        _driverChannel.Dispose();
                        _driverChannel = null;
                    }
                }
                catch (Exception ex)
                {
                    SimHub.Logging.Current.Warn($"[TF4ALL] TFFA filter channel init threw {ex.GetType().Name}: {ex.Message}");
                    try { _driverChannel?.Dispose(); } catch { }
                    _driverChannel = null;
                    try { _driverLedChannel?.Dispose(); } catch { }
                    _driverLedChannel = null;
                }
            }

            // Pull initial values from globals (no car detected yet).
            ApplyActiveCarOverride();

            // Telemetry source: SimHub fallback initially. The first DataUpdate
            // tick triggers the game-change block (since _activeGame starts
            // null) and SwapTelemetrySource picks an enhanced source if the
            // running game has one.
            //
            // Normal only. Lights-only needs no telemetry at all: the car's colors
            // come from its published ramp, not from a frame, and the car's identity
            // arrives in DataUpdate, which SimHub calls whether or not we run a
            // source. Skipping it here is also what keeps the promise about the UDP
            // port: SwapTelemetrySource is where the Forza listener binds 5300, and
            // a lights-only plugin sitting on that port would steal Data Out from
            // the game while claiming to touch nothing.
            if (fullPipeline)
            {
                _simHubSource = new SimHubTelemetrySource { OnFrame = DispatchFrame };
                _simHubSource.Start();
                _telemetrySource = _simHubSource;
                SimHub.Logging.Current.Info($"[TF4ALL] Telemetry source: {_telemetrySource.Name}.");

                _capturePollThread = new Thread(CapturePollLoop)
                {
                    IsBackground = true,
                    Name = "TrueforceCapturePoll",
                };
                _capturePollThread.Start();
                SimHub.Logging.Current.Info("[TF4ALL] Audio capture armed; waiting for a supported game to start.");
            }

            // Default-on (Settings.ShowFeedbackBox): splice a Trueforce gain tile
            // into SimHub's home "Feedback" section. Self-retrying + defensive; if
            // the home tab isn't realized yet (or the layout differs), it just
            // won't appear (cosmetic, never throws).
            _feedbackInjector = new FeedbackBoxInjector(this);
            _feedbackInjector.Start();

            // What this pass actually built, so a later mode switch adds or removes
            // the difference rather than guessing.
            _fullPipelineRunning = fullPipeline;
            _pipelineReady = true;
        }
        private System.Threading.CancellationTokenSource _updateCheckerCts;
        public System.Threading.CancellationToken UpdateCheckerToken
            => _updateCheckerCts?.Token ?? System.Threading.CancellationToken.None;

        // ---- Background "check for updates" re-poll ----
        // Periodic GitHub-release re-check on the user-configured cadence. The
        // timer wakes on a fixed cheap interval and each tick decides whether
        // Settings.UpdateCheckIntervalHours has elapsed since the last check, so
        // changing the cadence at runtime needs no re-arm. 0 hours = "On startup
        // only" -> the tick no-ops. _lastUpdateCheckTicks is a monotonic
        // Stopwatch stamp; the manual "Check for updates" link refreshes it via
        // MarkUpdateChecked() so an auto-check doesn't fire moments after one.
        private System.Threading.Timer _updateCheckTimer;
        private long _lastUpdateCheckTicks;
        private const int UpdateCheckPollMs = 10 * 60 * 1000; // wake every 10 min

        // Debug-only (UPDATEPOLL test code): when > 0, the background re-check
        // uses this many SECONDS as its cadence instead of the configured
        // UpdateCheckIntervalHours (and ignores the "On startup only" floor),
        // and the wakeup timer is sped up to match. Lets a tester watch the
        // periodic re-check fire on its own within seconds rather than hours.
        private int _updateCheckDebugSeconds;

        /// <summary>Stamp "an update check just happened (or is starting) now."
        /// Called after the startup check, by the background re-poll before it
        /// awaits, and by the manual "Check for updates" link so the next
        /// background check is measured from the most recent check of any kind.</summary>
        public void MarkUpdateChecked()
            => System.Threading.Interlocked.Exchange(
                   ref _lastUpdateCheckTicks, Stopwatch.GetTimestamp());

        private void UpdateCheckTimerTick(object _)
        {
            try
            {
                if (_shuttingDown || _updateChecker == null) return;

                // Debug fast cadence (UPDATEPOLL) overrides the configured hours
                // and the "On startup only" floor; otherwise honor the setting.
                long intervalTicks;
                int debugSeconds = _updateCheckDebugSeconds;
                if (debugSeconds > 0)
                {
                    intervalTicks = Stopwatch.Frequency * debugSeconds;
                }
                else
                {
                    int hours = Settings?.UpdateCheckIntervalHours ?? 2;
                    if (hours <= 0) return;   // "On startup only": no background re-check.
                    intervalTicks = Stopwatch.Frequency * 3600L * hours;
                }

                long last = System.Threading.Interlocked.Read(ref _lastUpdateCheckTicks);
                if (Stopwatch.GetTimestamp() - last < intervalTicks) return;

                // Stamp BEFORE the async check so a slow/queued GitHub call can't
                // let the next 10-min wakeup fire a second overlapping check.
                MarkUpdateChecked();
                var token = _updateCheckerCts?.Token ?? System.Threading.CancellationToken.None;
                System.Threading.Tasks.Task.Run(async () =>
                {
                    try
                    {
                        await _updateChecker.CheckAsync(token);
                        // Beta auto-enroll + channel re-select (cheap no-op
                        // for Stable users on stable builds).
                        RefreshUpdateChannel();
                        // Downloaded-preset auto-update shares the user's
                        // re-check cadence (owner decision 2026-07-20).
                        await MaybeAutoUpdateCommunityPresetsHeadless();
                    }
                    catch (Exception ex)
                    {
                        SimHub.Logging.Current.Warn($"[TF4ALL] Periodic update check crashed: {ex.Message}");
                    }
                });
            }
            catch { }
        }

        /// <summary>Debug (UPDATEPOLL test code): toggle a fast background
        /// update re-check. When on, the periodic timer fires every
        /// <paramref name="seconds"/> and re-runs CheckAsync regardless of
        /// UpdateCheckIntervalHours, so a tester can watch the re-check fire
        /// (SimHub log shows a repeated "Update check OK" line) within seconds
        /// instead of hours. Returns the active cadence in seconds, or 0 when
        /// it toggled OFF (back to the normal 10-min wakeup + configured hours).</summary>
        public int DebugToggleFastUpdatePolling(int seconds)
        {
            if (_updateCheckDebugSeconds > 0)
            {
                _updateCheckDebugSeconds = 0;
                try { _updateCheckTimer?.Change(UpdateCheckPollMs, UpdateCheckPollMs); } catch { }
                // Drop the simulated release (hides the banner now) and re-poll
                // GitHub in the background to restore the real up-to-date state.
                _updateChecker?.DebugClearForcedUpdate();
                var token = _updateCheckerCts?.Token ?? System.Threading.CancellationToken.None;
                System.Threading.Tasks.Task.Run(async () =>
                {
                    try { await _updateChecker.CheckAsync(token); } catch { }
                });
                SimHub.Logging.Current.Info("[TF4ALL] Debug update polling OFF (normal cadence; simulated release cleared).");
                return 0;
            }
            _updateCheckDebugSeconds = Math.Max(1, seconds);
            // Arm the simulated newer release. It does NOT take effect now: only
            // the next background CheckAsync applies it (see UpdateChecker), so
            // the banner is absent until a re-check discovers it on its own.
            if (_updateChecker != null) _updateChecker.DebugForceUpdateAvailable = true;
            int periodMs = Math.Max(1000, _updateCheckDebugSeconds * 1000);
            // Measure the first debug re-check from now so it visibly fires one
            // interval later (not instantly off the older startup stamp).
            MarkUpdateChecked();
            try { _updateCheckTimer?.Change(periodMs, periodMs); } catch { }
            SimHub.Logging.Current.Info($"[TF4ALL] Debug update polling ON: every {_updateCheckDebugSeconds}s (will surface a simulated newer release).");
            return _updateCheckDebugSeconds;
        }

        // ---- "NEW" badges + changelog banner ----

        /// <summary>Plugin assembly version in ToString(3) form ("X.Y.Z").
        /// Used as the stamp on Settings.LastSeenVersion, and as the version
        /// this install reports (auth User-Agent, session heartbeat).</summary>
        public static string CurrentVersionString()
        {
            var v = System.Reflection.Assembly.GetExecutingAssembly().GetName().Version;
            return v != null ? v.ToString(3) : "0.0.0";
        }

        /// <summary>True iff <paramref name="effectId"/> hasn't been seen by
        /// the user yet. Drives the per-section "NEW" badge in the settings
        /// UI. Defensive: returns false for a null/empty ID and before
        /// settings load, so the UI can query freely without guarding.</summary>
        public bool IsEffectUnseen(string effectId)
        {
            if (Settings?.SeenEffects == null || string.IsNullOrEmpty(effectId)) return false;
            return !Settings.SeenEffects.Contains(effectId);
        }

        /// <summary>Record that the user has seen / interacted with the
        /// given effect; the "NEW" badge stops showing. Idempotent.
        /// Persists settings only on an actual state change so the chatty
        /// per-slider call site doesn't write the file on every value tick.</summary>
        public void MarkEffectSeen(string effectId)
        {
            if (Settings == null || string.IsNullOrEmpty(effectId)) return;
            if (Settings.SeenEffects == null) Settings.SeenEffects = new List<string>();
            if (Settings.SeenEffects.Contains(effectId)) return;
            Settings.SeenEffects.Add(effectId);
            PersistSettingsCore();
        }

        // How many times the Effects view is opened (while NEW badges are showing)
        // before the still-unseen effects auto-retire their badges. Chosen so a badge
        // the user keeps ignoring fades on its own instead of lingering forever.
        private const int NewEffectViewDismissThreshold = 4;

        /// <summary>Call when the Effects view is opened. While any NEW badge is
        /// showing, advances a counter; once the user has opened the view
        /// NewEffectViewDismissThreshold times without interacting, the remaining
        /// unseen effects are marked seen so their badges clear on their own. A newly
        /// shipped effect grows the unseen set and restarts the countdown, so it still
        /// gets its full run of views. Returns true if the seen set changed (the caller
        /// should refresh the visible badges).</summary>
        public bool NoteEffectsViewOpened()
        {
            if (Settings == null) return false;

            int unseen = 0;
            foreach (var id in EffectChangelog.KnownEffectIds)
                if (IsEffectUnseen(id)) unseen++;

            // No badges showing: hold the counter at zero so the next new effect starts clean.
            if (unseen == 0)
            {
                if (Settings.NewEffectViewCount != 0 || Settings.NewEffectBadgeUnseenBaseline != 0)
                {
                    Settings.NewEffectViewCount = 0;
                    Settings.NewEffectBadgeUnseenBaseline = 0;
                    PersistSettingsCore();
                }
                return false;
            }

            // A new effect appeared since the last open -> restart the countdown so the
            // fresh badge gets its full run of views before auto-dismiss.
            if (unseen > Settings.NewEffectBadgeUnseenBaseline)
                Settings.NewEffectViewCount = 0;
            Settings.NewEffectBadgeUnseenBaseline = unseen;

            Settings.NewEffectViewCount++;

            bool changed = false;
            if (Settings.NewEffectViewCount >= NewEffectViewDismissThreshold)
            {
                if (Settings.SeenEffects == null) Settings.SeenEffects = new List<string>();
                foreach (var id in EffectChangelog.KnownEffectIds)
                {
                    if (IsEffectUnseen(id))
                    {
                        Settings.SeenEffects.Add(id);
                        changed = true;
                    }
                }
                Settings.NewEffectViewCount = 0;
                Settings.NewEffectBadgeUnseenBaseline = 0;
            }
            PersistSettingsCore();
            return changed;
        }

        /// <summary>Returns every changelog version strictly newer than the
        /// user's stamped LastSeenVersion (all of them when it is unset or
        /// unparseable). Empty = no bundled notes for the modal; the banner's
        /// own visibility comes from HasUnseenChangelog.</summary>
        public IReadOnlyList<ChangelogVersion> GetPendingChangelog()
        {
            if (Settings == null) return Array.Empty<ChangelogVersion>();
            EffectChangelog.TryParseVersion(Settings.LastSeenVersion, out var since);
            return EffectChangelog.EntriesNewerThan(since);
        }

        /// <summary>True when GitHub has a published release whose version
        /// matches the running build, prerelease or not: the user is literally
        /// running it, so its notes are always fair to show. The What's new
        /// modal prefers GitHub notes only in that case; a dev build ahead of
        /// any release falls back to the bundled EffectChangelog, so changelogs
        /// can be authored and previewed before a public release exists.</summary>
        public bool GitHubHasReleaseForCurrentVersion()
        {
            var all = UpdateChecker?.AllReleases;
            var current = UpdateChecker?.CurrentVersion;
            if (all == null || current == null) return false;
            foreach (var r in all)
                if (r != null && r.Version != null && Compare3(r.Version, current) == 0)
                    return true;
            return false;
        }

        /// <summary>True when LastSeenVersion is strictly older than the
        /// running plugin's assembly version. Drives the What's new banner's
        /// visibility independently of EffectChangelog content, so the
        /// banner fires for any version upgrade even after we stop adding
        /// EffectChangelog entries (GitHub release notes are canonical now).
        /// Compares on Major.Minor.Build only because LastSeenVersion is
        /// stamped via ToString(3); a four-component Assembly Version with
        /// Revision=0 would otherwise read as "newer" than the parsed
        /// three-component value (Revision=-1) and pin the banner on
        /// forever after dismissal.</summary>
        public bool HasUnseenChangelog
        {
            get
            {
                if (Settings == null || UpdateChecker == null) return false;
                if (!EffectChangelog.TryParseVersion(Settings.LastSeenVersion, out var since)) return false;
                return Compare3(UpdateChecker.CurrentVersion, since) > 0;
            }
        }

        // 3-component Version comparison (Major.Minor.Build). Missing
        // components on either side are treated as 0 so a freshly-parsed
        // "0.1.7" (Build=7, Revision=-1) compares equal to an Assembly
        // "0.1.7.0" (Build=7, Revision=0).
        private static int Compare3(Version a, Version b)
        {
            if (a == null) return b == null ? 0 : -1;
            if (b == null) return 1;
            int c = a.Major.CompareTo(b.Major); if (c != 0) return c;
            c = a.Minor.CompareTo(b.Minor); if (c != 0) return c;
            int aBuild = a.Build < 0 ? 0 : a.Build;
            int bBuild = b.Build < 0 ? 0 : b.Build;
            return aBuild.CompareTo(bBuild);
        }

        /// <summary>Filter the fetched GitHub release list to the releases
        /// the post-upgrade What's new modal should display: strictly newer
        /// than LastSeenVersion and no newer than the running build, with
        /// prereleases included only on the Beta channel or when the release
        /// IS the running build. Returns empty when the fetch hasn't
        /// completed or failed (caller falls back to EffectChangelog).</summary>
        public IReadOnlyList<ReleaseInfo> GetGitHubReleasesForBanner()
        {
            if (Settings == null || UpdateChecker?.AllReleases == null
                || UpdateChecker.AllReleases.Count == 0)
                return Array.Empty<ReleaseInfo>();
            if (!EffectChangelog.TryParseVersion(Settings.LastSeenVersion, out var since) || since == null)
                return Array.Empty<ReleaseInfo>();
            var current = UpdateChecker.CurrentVersion;
            // Beta testers get prerelease notes too; and the release matching
            // the RUNNING build always counts even with the channel off (a
            // beta build that opted out still deserves its own notes, instead
            // of silently falling back to the offline changelog).
            bool includePre = BetaChannelAllowed();
            var list = new List<ReleaseInfo>();
            foreach (var r in UpdateChecker.AllReleases)
            {
                if (r == null || r.Version == null) continue;
                if (r.IsPrerelease && !includePre && Compare3(r.Version, current) != 0) continue;
                if (r.Version <= since) continue;
                if (r.Version > current) continue;
                list.Add(r);
            }
            list.Sort((a, b) => b.Version.CompareTo(a.Version));
            return list;
        }

        /// <summary>True when prereleases (the "Beta" channel) should be
        /// eligible in the in-app updater: the user opted in via the Settings
        /// toggle. Open to everyone; beta testing is participation, not a perk
        /// (prereleases are public on GitHub regardless).</summary>
        private bool BetaChannelAllowed()
            => Settings != null && Settings.BetaUpdatesEnabled;

        /// <summary>Push the effective update channel into the poller. Cheap
        /// (recomputes the "latest" target off the already fetched release list,
        /// no network), so it's safe to call whenever the setting changes. Also
        /// feeds the switch-back signal: a user who EXPLICITLY toggled beta off
        /// while running a beta build gets offered the newest main release as a
        /// downgrade.</summary>
        internal void ApplyUpdateChannel()
        {
            var uc = _updateChecker;
            if (uc == null) return;
            // Switch-back is offered ONLY on an explicit opt-out: the latch says
            // beta was acknowledged for this very version, and the flag is now
            // off. A beta build with no latch yet (first run before a successful
            // release check) just waits for the auto-enroll below.
            uc.OfferStableSwitchBack = Settings != null
                && !Settings.BetaUpdatesEnabled
                && string.Equals(Settings.BetaAutoEnrolledVersion,
                                 uc.CurrentVersion.ToString(3), StringComparison.Ordinal);
            uc.IncludePrereleases = BetaChannelAllowed();
        }

        /// <summary>Auto-enroll anyone running a beta build into the Beta update
        /// channel: installing a pre-release is already a statement of intent,
        /// so the tester follows the beta branch without a manual toggle instead
        /// of stranding on a stale beta waiting for stable to catch up. The
        /// one-shot latch (BetaAutoEnrolledVersion) records that beta was
        /// acknowledged for this version, so a user who then toggles beta OFF
        /// stays off and gets the switch-back-to-main offer instead of being
        /// re-enrolled. Called from RefreshUpdateChannel after every release
        /// fetch (CurrentVersionIsPrerelease needs a fetched list).</summary>
        internal void MaybeAutoEnrollBetaChannel()
        {
            var uc = _updateChecker;
            var s  = Settings;
            if (uc == null || s == null || !uc.CurrentVersionIsPrerelease) return;
            string cur = uc.CurrentVersion.ToString(3);
            if (string.Equals(s.BetaAutoEnrolledVersion, cur, StringComparison.Ordinal)) return;
            s.BetaAutoEnrolledVersion = cur;
            if (!s.BetaUpdatesEnabled)
            {
                s.BetaUpdatesEnabled = true;
                SimHub.Logging.Current.Info(
                    $"[TF4ALL] Beta build v{cur}: update channel switched to Beta automatically.");
            }
            try { PersistSettingsCore(); } catch { }
            ApplyUpdateChannel();
        }

        /// <summary>Auto-enroll a beta build, then push the resulting channel
        /// into the poller. Called after each release fetch (startup, the
        /// periodic re-poll, the manual check link), so a prerelease can
        /// surface in the banner without a restart. Purely local: the channel
        /// depends only on the stored toggle (the beta channel is open to
        /// everyone), so there is no entitlement round-trip.</summary>
        internal void RefreshUpdateChannel()
        {
            MaybeAutoEnrollBetaChannel();
            ApplyUpdateChannel();
        }

        /// <summary>Explicit beta opt-out on a beta build: stamp the enroll
        /// latch to the running version so the next release check can't
        /// silently re-enroll this install, and so the switch-back offer
        /// unlocks even when this install was never auto-enrolled (settings
        /// wiped, or freshly restored from a pre-beta backup). No-op on
        /// stable builds and before the first successful release fetch.
        /// The caller persists.</summary>
        internal void AcknowledgeBetaOptOut()
        {
            var uc = _updateChecker;
            var s  = Settings;
            if (uc == null || s == null || !uc.CurrentVersionIsPrerelease) return;
            s.BetaAutoEnrolledVersion = uc.CurrentVersion.ToString(3);
        }

        /// <summary>Stamps LastSeenVersion to the running build. Hides the
        /// banner permanently for this version. Idempotent.</summary>
        public void DismissChangelog()
        {
            if (Settings == null) return;
            string current = CurrentVersionString();
            if (Settings.LastSeenVersion == current) return;
            Settings.LastSeenVersion = current;
            PersistSettingsCore();
        }

        // ---- Word-of-mouth prompt ----------------------------------------

        // Earned-value gate. The banner only surfaces after this many
        // cumulative seconds of the wheel actually being driven with a game
        // running, so it never lands on a user who is still fighting setup.
        private const double ShareCtaThresholdSeconds = 2.0 * 60.0 * 60.0; // 2 h

        // Flush the in-memory odometer to settings at most this often, so we
        // don't write the settings file every frame.
        private const double StreamFlushIntervalSeconds = 120.0;

        // Stopwatch ts of the previous AccumulateStreamingTime call (0 = unset),
        // and seconds counted since the last flush to Settings.
        private long _streamClockTicks;
        private double _streamSecondsSinceFlush;

        /// <summary>True once the user has banked past the earned-seat-time
        /// threshold and hasn't already dismissed or acted on the prompt.
        /// One-and-done: ShareCtaDismissed latches it off forever.</summary>
        public bool ShouldShowShareCta
        {
            get
            {
                return Settings != null
                    && !Settings.ShareCtaDismissed
                    && Settings.ActiveStreamingSeconds >= ShareCtaThresholdSeconds;
            }
        }

        /// <summary>Latches the word-of-mouth prompt off permanently. Called
        /// whether the user acts on it or dismisses it. Idempotent.</summary>
        public void DismissShareCta()
        {
            if (Settings == null || Settings.ShareCtaDismissed) return;
            Settings.ShareCtaDismissed = true;
            PersistSettingsCore();
        }

        // ---------------- support prompt (periodic Patreon modal) ----------------
        //
        // Paced off the same earned-seat-time odometer as the share CTA, so the ask
        // only ever lands on someone the plugin has actually worked for. The ladder
        // is cumulative hours: first ask well clear of the share banner's ~2h, then
        // a long back-off, then gaps that close as the hours pile up, on the reading
        // that the more someone uses it the more the ask is earned.
        private static readonly double[] SupportPromptLadderHours = { 5, 30, 55, 75 };
        private const double SupportPromptRepeatHours   = 20;   // spacing once past the ladder
        private const double SupportPromptDeclineHours  = 10;   // added per consecutive decline
        private const double SupportPromptDeclineCapHrs = 60;   // ceiling on that back-off
        private const int    SupportPromptFloorDays     = 7;    // real-time floor between asks

        /// <summary>True once this account has ever backed the project (current
        /// supporter, or a past one via supporter_since). Latched locally, so it
        /// survives being offline or signed out.</summary>
        internal bool EverSupported => (Settings != null && Settings.HasEverSupported) || LastKnownSupporter;

        /// <summary>Latches ever-supported on. Idempotent; persists once.</summary>
        internal void NoteEverSupported()
        {
            if (Settings == null || Settings.HasEverSupported) return;
            Settings.HasEverSupported = true;
            PersistSettingsCore();
        }

        /// <summary>SimHub reports a game running, i.e. the user is mid-session.
        /// The support prompt waits for idle rather than interrupting that.</summary>
        internal bool GameIsRunning => !string.IsNullOrEmpty(_currentGameName);

        // Set once an entitlement read completes for the signed-in account. Guards the
        // prompt against the window where a real supporter would still read as false.
        private volatile bool _entResolvedThisSession;

        /// <summary>Whether supporter status is settled enough to act on. Nothing to
        /// resolve when signed out (entitlements are per-account), and that is the
        /// common case since the community went account-free, so a signed-out user is
        /// not held back; the prompt tells them how to sign in instead.</summary>
        internal bool SupporterStatusSettled => !AuthIsSignedIn || _entResolvedThisSession;

        /// <summary>Cumulative seat time at which the next support prompt is due.</summary>
        private double NextSupportPromptHours()
        {
            int shown = Settings?.SupportPromptCount ?? 0;
            double baseHours = shown < SupportPromptLadderHours.Length
                ? SupportPromptLadderHours[shown]
                : SupportPromptLadderHours[SupportPromptLadderHours.Length - 1]
                  + (shown - (SupportPromptLadderHours.Length - 1)) * SupportPromptRepeatHours;
            double penalty = Math.Min((Settings?.SupportPromptDeclineCount ?? 0) * SupportPromptDeclineHours,
                                      SupportPromptDeclineCapHrs);
            return baseHours + penalty;
        }

        /// <summary>Whether to show the support prompt on this open of the plugin page.</summary>
        internal bool ShouldShowSupportPrompt
        {
            get
            {
                if (Settings == null) return false;
                if (EverSupported) return false;            // supported once, never asked again
                if (!SupporterStatusSettled) return false;  // don't ask before we'd know
                if (GameIsRunning) return false;            // never mid-session
                if (Settings.ActiveStreamingSeconds < NextSupportPromptHours() * 3600.0) return false;
                var last = Settings.SupportPromptLastUtc;
                if (last.HasValue && (DateTime.UtcNow - last.Value).TotalDays < SupportPromptFloorDays)
                    return false;
                return true;
            }
        }

        /// <summary>Records that the prompt was shown and how it was answered.
        /// Clicking through to Patreon clears the decline back-off; dismissing adds
        /// to it, so repeated no's push the next ask further out.</summary>
        internal void NoteSupportPromptShown(bool declined)
        {
            if (Settings == null) return;
            Settings.SupportPromptCount++;
            Settings.SupportPromptLastUtc = DateTime.UtcNow;
            if (declined) Settings.SupportPromptDeclineCount++;
            else Settings.SupportPromptDeclineCount = 0;
            PersistSettingsCore();
        }

        // Called once per producer iteration. Adds wall time to the odometer
        // only while we're actually driving a running game; a long gap (sleep,
        // debugger, wheel gone) is discarded by the dt ceiling so idle time
        // never counts toward the earned-value threshold.
        private void AccumulateStreamingTime()
        {
            long now = Stopwatch.GetTimestamp();
            long prev = _streamClockTicks;
            _streamClockTicks = now;
            if (prev == 0) return; // first sample: just establish the baseline

            if (Settings == null || !Settings.PluginEnabled || _device == null
                || string.IsNullOrEmpty(_currentGameName))
                return;

            double dt = (now - prev) / (double)Stopwatch.Frequency;
            if (dt <= 0.0 || dt > 2.0) return; // discard stalls / resume gaps

            _streamSecondsSinceFlush += dt;
            if (_streamSecondsSinceFlush < StreamFlushIntervalSeconds) return;
            Settings.ActiveStreamingSeconds += _streamSecondsSinceFlush;
            _streamSecondsSinceFlush = 0.0;
            // Persist OFF the producer thread (this runs only in ProducerLoopCore).
            // SaveCommonSettings does a full serialize + backup rotation +
            // synchronous disk write; on a slow/contended disk that stalls the
            // producer long enough to underrun the device ring (audible glitch +
            // ratchet UP). The odometer is already updated in memory above.
            ScheduleSettingsFlush();
        }

        // Single-flight background flush of Settings. Used by callers on
        // latency-sensitive threads (the streaming odometer and the ring-size
        // auto-ratchet, both on the producer thread) where the in-memory state
        // is already updated and the disk write is not time-sensitive. Skips if
        // a flush is already queued/running; the next flush persists the latest
        // in-memory state anyway.
        private int _settingsFlushInFlight;
        private void ScheduleSettingsFlush()
        {
            if (System.Threading.Interlocked.Exchange(ref _settingsFlushInFlight, 1) == 1)
                return;
            System.Threading.Tasks.Task.Run(() =>
            {
                try { PersistSettingsCore(); }
                catch { }
                finally { System.Threading.Interlocked.Exchange(ref _settingsFlushInFlight, 0); }
            });
        }

        // Persist CarFacts changes OFF the telemetry/data thread, the same reason
        // ScheduleSettingsFlush exists: SaveCommonSettings does a full
        // serialize + backup rotation + synchronous disk write, which must not
        // run inline on the producer thread. The serialize-vs-mutation exclusion
        // now lives inside PersistSettingsCore (which takes _carFactsLock), so
        // this loop no longer needs its own lock. A "dirty" flag is re-checked
        // after each pass so the latest mutation is always persisted even if it
        // lands while a flush is in flight.
        private int _carFactsFlushRunning;
        private int _carFactsDirty;
        private void ScheduleCarFactsFlush()
        {
            System.Threading.Interlocked.Exchange(ref _carFactsDirty, 1);
            if (System.Threading.Interlocked.Exchange(ref _carFactsFlushRunning, 1) == 1) return;
            System.Threading.Tasks.Task.Run(() =>
            {
                try
                {
                    while (System.Threading.Interlocked.Exchange(ref _carFactsDirty, 0) == 1)
                    {
                        try { PersistSettingsCore(); } catch { }
                    }
                }
                finally
                {
                    System.Threading.Interlocked.Exchange(ref _carFactsFlushRunning, 0);
                    // A mutation that arrived during the final drain would have
                    // set dirty after our last check; re-arm so it isn't lost.
                    if (System.Threading.Volatile.Read(ref _carFactsDirty) == 1)
                        ScheduleCarFactsFlush();
                }
            });
        }

        // ---- GC latency mode (scoped to active gameplay) ----
        // GCSettings.LatencyMode is process-global, so we capture the previous
        // mode when a capture session starts and restore it when it stops, and
        // only hold SustainedLowLatency while a game is actually streaming (idle
        // SimHub keeps its normal GC). SustainedLowLatency avoids blocking gen2
        // collections, trimming the GC-suspend spikes that can underrun the 1 kHz
        // threads and trip the ring ratchet. Best-effort: restricted hosts throw.
        private int _gcLowLatencyActive;
        private System.Runtime.GCLatencyMode _gcPrevLatencyMode;

        private void EnterStreamingGcMode()
        {
            if (System.Threading.Interlocked.Exchange(ref _gcLowLatencyActive, 1) == 1) return;
            try
            {
                _gcPrevLatencyMode = System.Runtime.GCSettings.LatencyMode;
                System.Runtime.GCSettings.LatencyMode = System.Runtime.GCLatencyMode.SustainedLowLatency;
                SimHub.Logging.Current.Info("[TF4ALL] GC latency mode -> SustainedLowLatency (streaming).");
            }
            catch { System.Threading.Interlocked.Exchange(ref _gcLowLatencyActive, 0); }
        }

        private void ExitStreamingGcMode()
        {
            if (System.Threading.Interlocked.Exchange(ref _gcLowLatencyActive, 0) == 0) return;
            try
            {
                System.Runtime.GCSettings.LatencyMode = _gcPrevLatencyMode;
                SimHub.Logging.Current.Info("[TF4ALL] GC latency mode restored.");
            }
            catch { }
        }

        public void End(PluginManager pluginManager)
        {
            // Shut the mode reconcile down BEFORE anything is disposed. It runs on a
            // thread-pool thread and rebuilds whatever it finds missing, so one still
            // in flight would spawn a fresh loopback helper and reopen the wheel
            // right after this method had torn both down. On the plugin-disable path
            // there is no process exit to reap that orphaned child.
            // Deliberately NOT _shuttingDown here: that flag is set further down, on
            // purpose, so the owed-slot restore just below still runs. _pipelineReady
            // is the narrower switch and every arm of the reconcile tests it.
            _pipelineReady = false;
            for (int i = 0; i < 100 && System.Threading.Volatile.Read(ref _pipelineReconciling) != 0; i++)
                System.Threading.Thread.Sleep(50);

            // Bench tools own real hardware: a run left alive would keep the
            // wheel exclusively acquired and PULSING after "Plugin stopped"
            // (audit AT-05). Tear them down before anything else goes away.
            try
            {
                CancelAutoTune(silent: true);
                StopFxTest(silent: true);
                CancelDamperCalibration();
                StopDiDamperSpike();
                StopWheelMotion();
            }
            catch (Exception ex) { SimHub.Logging.Current.Warn("[TF4ALL] bench teardown on exit: " + ex.Message); }

            // Give back any borrowed light slot FIRST, while the HID++ channel is
            // still up. A slot write persists on the wheel, so leaving one held
            // means the user's own colors stay overwritten after we exit. Runs
            // before the teardown below closes the streams this needs.
            try
            {
                string restored = RestoreOwedSlots();
                if (!string.IsNullOrEmpty(restored)) SimHub.Logging.Current.Info("[TF4ALL] " + restored);

                // Leave the strip dark. Writing a slot has to light it briefly to
                // land the colors, and whatever we were showing is ours, not the
                // user's: a lit LED sitting there after SimHub closes looks like
                // the wheel is stuck.
                try { _rpmLeds?.Channel?.Clear(); } catch { }
            }
            catch (Exception ex) { SimHub.Logging.Current.Warn("[TF4ALL] slot restore on exit failed: " + ex.Message); }

            _shuttingDown = true;

            // Stop the direct reader FIRST. It owns a background thread holding a
            // view on the sim's shared memory, and it must not still be
            // publishing latches into an instance that is being torn down.
            try { StopIRacingDirect(); } catch { }
            try { _irSdk?.Dispose(); } catch { }
            _irSdk = null;
            try { StopR3EDirect(); } catch { }
            try { _r3e?.Dispose(); } catch { }
            _r3e = null;
            try { StopLmuDirect(); } catch { }
            try { _lmu?.Dispose(); } catch { }
            _lmu = null;

            // Restore the process GC latency mode if a game was still streaming.
            ExitStreamingGcMode();

            // Stop the auto-sync timers so they can't fire into a dead instance.
            try { _autoSyncTimer?.Dispose(); } catch { }
            _autoSyncTimer = null;
            try { _autoPullTimer?.Dispose(); } catch { }
            _autoPullTimer = null;
            try { _sessionHeartbeatTimer?.Dispose(); } catch { }
            try { _usagePingTimer?.Dispose(); } catch { }
            _sessionHeartbeatTimer = null;

            // Flush a pending dash redline share (see DashScheduleRedlineShare)
            // so quitting inside the quiet window doesn't drop it, then stop
            // the timer.
            try { DashFlushRedlineShare(); } catch { }
            try { _dashRedlineShareTimer?.Dispose(); } catch { }
            _dashRedlineShareTimer = null;

            // Tear down the home Feedback tile (best-effort; dispatches to the UI
            // thread, which may already be shutting down).
            try { _feedbackInjector?.Stop(); } catch { }
            _feedbackInjector = null;

            // Stop the background update re-poll so it can't fire into a dead
            // instance after teardown.
            try { _updateCheckTimer?.Dispose(); } catch { }
            _updateCheckTimer = null;

            // Cancel any in-flight update check / installer download so they
            // don't outlive the plugin and write to a dead instance.
            try { _updateCheckerCts?.Cancel(); } catch { }
            try { _updateCheckerCts?.Dispose(); } catch { }
            _updateCheckerCts = null;

            // Drain in-flight TestEffect tasks. They poll _shuttingDown every
            // ~16 ms, so a short bounded wait is plenty in practice; the
            // bound just means we don't deadlock if one is hung in TestUpdate.
            System.Threading.SpinWait.SpinUntil(
                () => System.Threading.Volatile.Read(ref _activeTestTasks) == 0,
                250);

            // Let any in-flight device-recovery thread-pool item finish so it
            // can't resurrect a device after we've torn one down. It already
            // checks _shuttingDown after CleanupDevice, so it bails fast; the
            // bound just prevents a hang if a bring-up is mid-init-sequence.
            System.Threading.SpinWait.SpinUntil(() => System.Threading.Volatile.Read(ref _recoveryInProgress) == 0, 1000);

            try { _capturePollThread?.Join(2000); } catch { }
            _capturePollThread = null;

            // Stop the active telemetry source so PushFromGameData becomes a
            // no-op for any late SimHub tick that lands during teardown.
            try { _telemetrySource?.Dispose(); } catch { }
            // The keep-alive Forza listener may be bound but not the active
            // source (SimHub fallback), so dispose it explicitly too.
            if (_forzaUdp != null && _forzaUdp != _telemetrySource)
            {
                try { _forzaUdp.Dispose(); } catch { }
            }
            _forzaUdp        = null;
            _forzaOnSimHubFallback = false;
            // Same rule for the FS pipe server: disposed via _telemetrySource
            // when active, explicitly when the SimHub fallback was active.
            if (_fsPipeSource != null && _fsPipeSource != _telemetrySource)
            {
                try { _fsPipeSource.Dispose(); } catch { }
            }
            _fsPipeSource    = null;
            // And the arcade reader: a named shared-memory handle left open would
            // outlive the plugin unload.
            if (_teknoSource != null && _teknoSource != _telemetrySource)
            {
                try { _teknoSource.Dispose(); } catch { }
            }
            _teknoSource     = null;
            _telemetrySource = null;
            _simHubSource    = null;

            // Fold any unflushed earned seat time into the odometer so a
            // clean shutdown doesn't lose the last partial flush window.
            if (Settings != null && _streamSecondsSinceFlush > 0.0)
            {
                Settings.ActiveStreamingSeconds += _streamSecondsSinceFlush;
                _streamSecondsSinceFlush = 0.0;
            }

            // Grip auto-cal: fold the session's learning into the settings
            // dict so the next session starts where this one left off.
            try { FlushGripCal(); } catch { }

            // UI changes are written through to Settings on the fly, so just save.
            // Guarded like the other PersistSettingsCore call sites: a throw here
            // (disk full / settings file locked) must not skip the remaining disposes
            // below (helper-process kill, device cleanup), which on a plugin-disable
            // (no host exit) would orphan the LoopbackHelper child process.
            try { if (Settings != null) PersistSettingsCore(); } catch { }

            try { _rpmLeds?.Dispose(); } catch { }
            _rpmLeds = null;

            try { _arcadeMemory?.Dispose(); } catch { }
            _arcadeMemory = null;
            try { _audioLeds?.Dispose(); } catch { }
            _audioLeds = null;

            try { _oledDash?.Dispose(); } catch { }
            _oledDash = null;

            // Release kernel-driver ownership early in the shutdown sequence so
            // any in-flight RECV IOCTL completes promptly. Dispose closes the
            // control-device handle, which reverts the driver to passthrough.
            // Both fields are null when ExperimentalDriverIntercept is off, so
            // this is a no-op in the default case.
            try { _driverChannel?.Dispose(); } catch { }
            _driverChannel = null;
            try { _driverLedChannel?.Dispose(); } catch { }
            _driverLedChannel = null;

            try { _f8Leds?.Dispose(); } catch { }
            _f8Leds = null;

            try { _audio?.Dispose(); } catch { }
            _audio = null;

            try { _helperHost?.Dispose(); } catch { }
            _helperHost = null;

            try { _capturedProcess?.Dispose(); } catch { }
            _capturedProcess = null;

            // Wake the producer if it's parked inside PushFloats on a full
            // ring, the plugin's _shuttingDown flag doesn't propagate into
            // the device's wait condition, so without this the join below can
            // time out and leave the producer alive while CleanupDevice tears
            // the device down underneath it.
            try { _device?.StopAcceptingSamples(); } catch { }

            try { _producerThread?.Join(2000); } catch { }
            if (_producerThread != null && _producerThread.IsAlive)
                SimHub.Logging.Current.Warn("[TF4ALL] Producer thread did not exit cleanly.");
            _producerThread = null;

            try { _device?.ClearStream(); } catch { }
            // Brief pause so the center-wheel samples drain to the device.
            Thread.Sleep(60);
            CleanupDevice();
            SimHub.Logging.Current.Info("[TF4ALL] Plugin stopped.");
        }

        public void DataUpdate(PluginManager pluginManager, ref GameData data)
        {
            // SPIKE (2026-09-06): read back and unwind last tick's write into
            // SimHub's own fields. First, so nothing below sees a spoof.
            ArcadeBridgeSpikeRestore(pluginManager, data);

            _currentGameName = data?.GameRunning == true ? data.GameName : null;
            // Analytics asks a DIFFERENT question from the force path, so it gets a
            // different signal. GameRunning means the reader is delivering telemetry:
            // it is false in menus, on loading screens, while paused, and for the whole
            // life of a title whose data never reaches SimHub at all. _currentGameName
            // is therefore the right input for the force path (no data, no effects) and
            // the wrong one for "what did they play": a measured FH6 session sat open
            // for 96 seconds with Data Out off, emitted nothing, and was recorded as no
            // game, while the plugin had already adopted it and loaded its preset.
            //
            // RunningGameProcessDetected is SimHub's separate "this title's process is
            // up" flag, which is exactly the question. Taken as a UNION with the old
            // gate so this can only ever record more than before, never less, and so a
            // title that is live but somehow not process-detected still counts.
            _usageGameName = (data?.GameRunning == true || data?.RunningGameProcessDetected == true)
                ? data.GameName : null;
            // Usage stats: note game-day activity on a transition into a game
            // (one ordinal compare per frame; the record runs only on change).
            try { NoteTelemetryGameActivity(_usageGameName); } catch { /* never disturb DataUpdate */ }
            // Radar dots and proximity, from this frame's opponents.
            try { DashUpdateRadar(data); } catch { /* display only, never fatal */ }

            // SUPPORT TOOL, armed only by the IRRAW access code. Off is one
            // volatile bool read per tick and nothing else. Kept deliberately
            // (owner, 2026-08-14): the iRacing path reaches SimHub's SDK by
            // reflection, and when a user's setup degrades it, "type IRRAW
            // and send the log" answers remotely what their SimHub actually
            // exposes. See the block near DebugToggleIracingRawProbe.
            IrRawProbeTick(data);

            // iRacing reshape: latch the sim's own steering torque for the
            // 1 kHz FFB thread. Gated on the GAME, not the force mode: returns
            // immediately unless iRacing is the live game.
            IRacingTelemetryTick(data);

            // RaceRoom shared-memory route (dev): run or stop the "$R3E"
            // reader. Normal mode only; returns immediately unless RaceRoom is the
            // live game with the route or its probe switched on.
            R3ETelemetryTick();

            // Le Mans Ultimate handover: run or stop the "LMU_Data" reader.
            // Same contract.
            LmuTelemetryTick();

            // Re-read the wheel's light slots when a sync could not. Silent
            // unless one is owed; see NoteSlotSyncOutcome for why this exists.
            RetrySlotSyncIfUnread();

            // Continuous (telemetry-independent) tick: tell the FFB tap whether
            // force feedback should be flowing right now, from the active
            // source's session signal (Forza IsRaceOn, else a universal
            // engine/motion proxy). Set here, not in the per-frame handler, so
            // it correctly goes false when telemetry stops (pause/menu). Also
            // clears the no-FFB notice once force feedback is captured again.
            if (_ffbTap != null)
            {
                // Spring mode (Mode B value 2) arms/disarms on the live bus
                // picture; run it before GameFfbExpected below reads the mode.
                UpdateSpringModeArming();
                // One-time offer to install the FS game mod (no-op elsewhere).
                MaybeOfferFsModInstall();
                // Mode B: the game is SUPPOSED to send nothing (in-game FFB
                // off, synthesis owns the wheel), so an empty tap is correct
                // and the "no game FFB reaching the plugin" escalation chain
                // (broad capture retry + user-facing warning) must stay quiet.
                // Same for the tap-free AC path: while ACFFB is armed and
                // finalFF is flowing, the user may not even have USBPcap
                // installed, so an empty tap is the expected state, not a
                // capture failure.
                _ffbTap.GameFfbExpected = _forceMode == ForceModeOff
                    && !CspBridgeSupplying()
                    && (_telemetrySource?.IsSessionActive ?? false);
                if (_noFfbCaptureNotice != null && _ffbTap.MsSinceLastSample < 1000)
                    _noFfbCaptureNotice = null;
            }

            // Race context for the wheel's OLED. Read here because this is the
            // only place SimHub's own status object is in scope; DispatchFrame,
            // which draws the panel, sees a TelemetryFrame and nothing else.
            // Stored as ints (milliseconds, not TimeSpan ticks) deliberately:
            // SimHub is a 32-bit host, so a 64-bit field could tear across the
            // telemetry and dispatch threads, and no lap is long enough to need
            // the range.
            if (data?.NewData != null)
            {
                try
                {
                    var race = data.NewData;
                    _shPosition   = race.Position;
                    _shCurrentLap = race.CurrentLap;
                    _shTotalLaps  = race.TotalLaps;
                    _shLastLapMs  = (int)race.LastLapTime.TotalMilliseconds;
                    _shBestLapMs  = (int)race.BestLapTime.TotalMilliseconds;
                    // Pedals for the OLED meters. SimHub reports these 0-100
                    // while everything on the telemetry frame is 0-1, so they
                    // are normalized here rather than at every use.
                    _shBrake01     = (float)(race.Brake / 100.0);
                    _shClutch01    = (float)(race.Clutch / 100.0);
                    _shHandbrake01 = (float)(race.Handbrake / 100.0);
                }
                catch { /* a game that reports none of this must not break DataUpdate */ }
            }

            // The OLED with no game running. There is no force anywhere, so the
            // panel is free and a readout is still worth seeing: the gain you
            // just nudged with a wheel button, or a message. Lives here because
            // DispatchFrame only runs on telemetry frames and there are none
            // without a game. With nothing to report this hands the screen back,
            // so the wheel's own menu is what you see at rest.
            // Normal only, and that gate is not cosmetic: ModeBOledEnabled defaults
            // ON, so before this the plugin wrote the wheel's screen with the
            // master switch off and no game running. Lights-only leaves the screen
            // alone too: it promises the lights and nothing else.
            if (_oledDash != null && MasterMode == TrueforceMasterMode.Normal
                && (Settings?.ModeBOledEnabled ?? false)
                && NoTelemetryArriving())
            {
                string idleLabel = null, idleValue = null;
                if (TryGetActiveReadout(out string il, out string iv))
                { idleLabel = il; idleValue = iv; }
                try { _oledDash.OnIdle(idleLabel, idleValue); }
                catch (Exception ex) { SimHub.Logging.Current.Error("[TF4ALL] OLED idle error", ex); }
            }

            // Normal only. This is a SECOND continuous 0x807A level writer, behind the
            // experimental driver intercept, and it reads none of the gates the
            // main rev-light path does. Armed in either new mode it would write
            // levels the mode promises not to.
            // EXPERIMENTAL: when the kernel-driver intercept is active it drops
            // the GAME's HID++ FFB writes before they reach the wheel, so no
            // force traffic is left on that endpoint for LED writes to contend
            // with (our own force goes out on ep3). That is what makes driving
            // rev LEDs from the game's RPM safe here. NB the enabling condition
            // is ZERO FFB on the HID++ endpoint, not "we are the sole writer on
            // it": sole-writer was tested and still dropped out (2026-07-29),
            // and being ignored is not the same as being absent, the game's
            // writes contend even while the wheel ignores them. Gated to
            // non-iRacing because
            // RpmLedController already owns the iRacing LED path. _driverLedChannel
            // is null unless ExperimentalDriverIntercept is on, so this is a
            // no-op in the default case.
            var ledCh = _driverLedChannel;
            if (ledCh != null && ledCh.IsReady && data?.NewData != null
                && MasterMode == TrueforceMasterMode.Normal
                && !string.Equals(_activeGame, "IRacing", StringComparison.Ordinal))
            {
                try
                {
                    // (Pattern picks/remembered cars ride _rpmLeds; this
                    // parked driver-path channel just drives levels.)
                    double rpm    = (double)data.NewData.Rpms;
                    double maxRpm = (double)data.NewData.MaxRpm;
                    if (maxRpm > 0)
                    {
                        // Standard rev-light curve: ramp from 70%-100% RPM over
                        // the wheel's own step count (fn0: 10 on G PRO/RS50,
                        // 5 on a G923). Below 70% no LEDs; at maxRpm all lit.
                        double pct = rpm / maxRpm;
                        int steps = ledCh.StripLength;
                        int level = 0;
                        if (pct > 0.70)
                        {
                            level = (int)Math.Round((pct - 0.70) * (steps / 0.30));
                            if (level > steps) level = steps;
                        }
                        ledCh.SetLevel(level);
                    }
                }
                catch { /* never let LED issues break DataUpdate */ }
            }

            // Continuous (telemetry-independent) tick: settle sustained effects
            // when the telemetry feed goes stale. Effects like the engine pulse,
            // rev/pit limiter, DRS hum, and traction-loss buzz hold a steady
            // amplitude set by the last frame; they only drop to silence on a
            // received frame (e.g. engine-off). When the source stops emitting
            // entirely (the game closed mid-session, crashed, or its shared-
            // memory page froze), no such frame ever arrives and the wheel keeps
            // playing the last sensation forever. Switching games and back used
            // to be the only way out. Detect the gap here, on a tick that keeps
            // running after frames stop, and tell those effects to fall silent.
            long stamp = System.Threading.Interlocked.Read(ref _lastFrameTicks);
            if (stamp != 0 && !_telemetryStalled
                && Stopwatch.GetTimestamp() - stamp > FrameStallTicks)
            {
                _telemetryStalled = true;
                SettleEffectsOnStall();
            }

            // The HID++ surfaces get a longer rope than the effects; see
            // ReleaseHidppSurfacesOnStall for why they are no longer on the same
            // window. Separate latch, because this one fires later and clears on
            // the same resumed frame.
            if (stamp != 0 && !_surfacesReleasedOnStall
                && Stopwatch.GetTimestamp() - stamp > SurfaceStallTicks)
            {
                _surfacesReleasedOnStall = true;
                ReleaseHidppSurfacesOnStall();
            }

            // The rim LEDs with no game feeding us: SimHub open with nothing
            // playing, or a game that has stopped. Same
            // reasoning as the OLED idle readout further up, and placed AFTER
            // the settle above rather than beside it: the settle hands the
            // strip back on the stall edge, so driving first would light the
            // bar and have it cleared again in the same tick.
            DriveAmbientLedsIdle();

            // Steering-reader self-heal: the HID stream dies silently when
            // something grabs the device (G HUB, USB hiccup), and both the
            // damper and Direct centering then fall back to lagged telemetry
            // for the rest of the session. Poll liveness here on the tick
            // that keeps running regardless of game state; the healthy path
            // is a few field reads, and any reopen runs off-thread inside.
            _steeringReader?.EnsureAlive();

            // A native-Trueforce title we are set to Normal in: hold our stream
            // off the wheel until the endpoint proves quiet (see
            // UpdateNativeTrueforceProbe). Runs first: while it holds, there is
            // no stream of ours for the watch below to compare against.
            UpdateNativeTrueforceProbe();

            // A game streaming its own Trueforce beside ours: drop to Lightsync
            // only (see UpdateNativeTrueforceStreamWatch). Runs before the pause
            // gate so that gate sees the mode change on the same tick.
            UpdateNativeTrueforceStreamWatch();
            UpdateMairaTapWatch();

            // Issue #13 test path: when StopStreamOnPause is on, hand the wheel
            // fully back to the game while paused (see UpdateStopStreamOnPauseGate).
            UpdateStopStreamOnPauseGate();

            // Mode B contention watchdog. Mode B's contract is that the game
            // sends NOTHING to the wheel (in-game FFB off): two writers on
            // the TrueForce path interleave into jumping/buzzing that reads
            // as bad tuning (tenth wheel test: GT4 "feels like shit", trace
            // showed the game streaming full-scale forces the whole time).
            // The FFB tap sees every game write, so sustained fresh captures
            // while Mode B streams = the game is fighting us. Name it loudly.
            // Mode 1 (Forza synthesis) only: its contract is that the game
            // sends nothing. Spring mode (2) is the OPPOSITE contract, the
            // game's spring traffic is our input, and any scalar there is a
            // misdecode (FS G PRO heartbeat), so warning on it is noise.
            // Suppressed while the slip feed is dead (never stamped, or stale
            // past the starved dwell): in that state the game's FFB is (or is
            // about to be) deliberately passed through, so "set the game's
            // FFB to 0" would zero the only force the wheel has left. Keyed
            // on the LIVE feed state, not the starved warn latch: the latch
            // needs 250 ms of live driving to land, and the contention timer
            // must never win that race (engaging Mode B from a pause menu
            // gives contention a 3 s head start otherwise).
            long slipStampC = System.Threading.Interlocked.Read(ref _lastSlipAngleTicks);
            bool slipFeedDead = slipStampC == 0
                || (Stopwatch.GetTimestamp() - slipStampC) * 1000.0 / Stopwatch.Frequency
                    > ModeBSlipStarvedAfterMs;
            if (_forceMode == ForceModeModeB && _ffbTap != null && !slipFeedDead)
            {
                bool gameWriting = _ffbTap.TryGetFreshFfbTarget(250).HasValue;
                long nowC = Stopwatch.GetTimestamp();
                if (!gameWriting)
                {
                    _contentionSinceTicks = 0;
                    // Recovery edge. The banner's advice is "zero the game's
                    // FFB", and a user who follows it mid-session must see the
                    // banner go away without toggling anything (owner rig,
                    // 2026-08-14: it held for the rest of the session). 10 s
                    // of sustained quiet, counted only while the watchdog is
                    // eligible, so a pause (slip feed dead, ineligible) never
                    // clears a verdict that would resume with driving.
                    if (ModeBContentionDetected)
                    {
                        if (_contentionQuietSinceTicks == 0)
                            _contentionQuietSinceTicks = nowC;
                        else if ((nowC - _contentionQuietSinceTicks) / (double)Stopwatch.Frequency > 10.0)
                        {
                            _contentionWarned = false;
                            ModeBContentionDetected = false;
                            _contentionQuietSinceTicks = 0;
                            SimHub.Logging.Current.Info(
                                "[TF4ALL] Mode B contention resolved: the game's own force "
                                + "feedback went quiet; synthesized FFB is the only writer again.");
                        }
                    }
                }
                else
                {
                    _contentionQuietSinceTicks = 0;
                    if (_contentionSinceTicks == 0) _contentionSinceTicks = nowC;
                    else if (!_contentionWarned
                             && (nowC - _contentionSinceTicks) / (double)Stopwatch.Frequency > 3.0)
                    {
                        _contentionWarned = true;
                        ModeBContentionDetected = true;
                        SimHub.Logging.Current.Warn(
                            "[TF4ALL] Mode B CONTENTION: the game is streaming its own wheel "
                            + "forces while synthesized FFB is active; the two interleave and the "
                            + "wheel feels jumpy/buzzy. Fix: in the game's wheel settings set force "
                            + "feedback / vibration scale to 0 so this plugin is the only writer.");
                    }
                }
            }
            else
            {
                // Timer always resets: a fresh contention verdict needs a
                // fresh 3 s of sustained game writes once the watchdog is
                // eligible again. The quiet tracker resets with it: quiet
                // counts toward recovery only while the watchdog is live.
                _contentionSinceTicks = 0;
                _contentionQuietSinceTicks = 0;
                // The LATCHES clear on genuine disarm only. While Mode B
                // stays armed this branch also runs whenever the slip feed
                // is dead (that suppression is what routes us here), and
                // wiping a latched banner every tick would flap the UI: a
                // contention verdict latched during a healthy phase may
                // outlive a fast-travel halt, and the starved latch is what
                // keeps the contention watchdog's wrong-advice suppressed.
                // (Pre-existing behavior for the contention latch: cleared
                // whenever Mode B is off, so the banner cannot outlive the
                // user turning Mode B off.)
                if (_forceMode != ForceModeModeB)
                {
                    _contentionWarned = false;
                    ModeBContentionDetected = false;
                    _starvedLiveTicks = 0;
                    // The slip-starved verdict describes this game run's
                    // telemetry ROUTING, and a pause does not change routing.
                    // FH6 pauses on focus loss, which auto-disarms Mode B, so
                    // clearing here made the banner vanish the moment the
                    // user alt-tabbed to act on it (owner, 2026-08-14: the
                    // banner could never be read). It survives until the game
                    // goes away or the user turns the feature off; the
                    // re-engage reset still runs on resume, so a fixed port
                    // gets its fresh verdict on the next drive.
                    if (_currentGameName == null || !ModeBEnabledForActiveGame)
                    {
                        _slipStarvedWarned = false;
                        ModeBSlipStarvedDetected = false;
                    }
                }
            }

            // First time we see telemetry for a real game in a session
            // (game != null), nudge the networked-welcome modal so users
            // who never open the Trueforce panel still get the pitch.
            // Self-gates on HasSeenNetworkedWelcome + backend-config
            // inside MaybeShowNetworkedWelcomeFromInit; the latch here
            // just avoids dispatching every frame.
            if (!_initWelcomePromptOffered
                && data?.GameRunning == true
                && Settings != null
                && !Settings.HasSeenNetworkedWelcome
                && !string.IsNullOrEmpty(Settings.CommunityBackendUrl)
                && !string.IsNullOrEmpty(Settings.CommunityBackendAnonKey))
            {
                _initWelcomePromptOffered = true;
                try
                {
                    var app = System.Windows.Application.Current;
                    if (app != null)
                        app.Dispatcher.BeginInvoke(
                            new Action(MaybeShowNetworkedWelcomeFromInit),
                            System.Windows.Threading.DispatcherPriority.Background);
                }
                catch (Exception ex)
                {
                    SimHub.Logging.Current.Info(
                        "[TF4ALL] Init-side welcome dispatch failed: " + ex.Message);
                }
            }

            // Track game changes and auto-apply that game's default preset
            // (if one is bound in GameDefaults). Done before per-car override
            // so the loaded preset's CarOverrides dict is in place by the
            // time ApplyActiveCarOverride runs below.
            string gameName = data?.GameName;

            // SimHub does not know every game. An emulated arcade title has no
            // SimHub profile at all: no game name, no GameRunning, no telemetry,
            // so without this it never reaches any of the machinery below and
            // gets no preset, no source and no arming. Supplying a synthetic
            // identity here is the whole of process-detected mode: everything
            // downstream (the source swap, the preset auto-apply, the per-game
            // mode resolve, the teardown when it exits) then runs unchanged.
            //
            // The test is whether SimHub's game is RUNNING, not whether it named
            // one. GameName is deliberately not gated on GameRunning a few lines
            // above, so it keeps reporting the last profile the user selected long
            // after that game closed. Checking it for emptiness therefore never
            // fires: someone who played Assetto Corsa yesterday still has
            // "AssettoCorsa" sitting in that field today, and an arcade cabinet
            // starting up would be ignored in favour of a game that is not on.
            //
            // A running SimHub game still wins outright. We only speak when
            // nothing of SimHub's is actually playing.
            // A SimHub CUSTOM GAME for an arcade cabinet is the second case, and it
            // arrives by the opposite door. Once such a profile exists SimHub DOES
            // report a running game, so the test above stops firing and the identity
            // becomes SimHub's "Custom_<guid>" code. That is the wrong name for us in
            // three separate ways: it is the preset key, it is the car-folder name,
            // and HasUsefulTelemetry reads false for anything carrying that prefix,
            // so the panel would call a fully mapped cabinet telemetry-less.
            //
            // ArcadeGameName was built without the prefix for exactly these reasons.
            // A user creating a game profile in SimHub must not silently re-file
            // their tuning, so the cabinet identity wins over the code whenever the
            // profile is describing the cabinet we are already reading.
            bool simHubHasGame = data?.GameRunning == true;
            bool customCode = simHubHasGame && gameName != null
                && gameName.StartsWith("Custom_", StringComparison.OrdinalIgnoreCase);
            // ArcadeUnlocked first, and it gates the NAMING rather than only the consumers:
            // renaming the active game to a cabinet re-keys presets, car folders and car facts,
            // so a locked build must never do it. With this off, _activeGame never becomes an
            // arcade name and IsArcadeGameName is false everywhere downstream by construction.
            if (ArcadeUnlocked && (!simHubHasGame || customCode))
            {
                string arcadeGame = DetectArcadeGameName();

                // "TeknoParrotArcade" is the FALLBACK identity, returned whenever a
                // cabinet is present but no profile matched the running process. It
                // is an answer of last resort rather than an answer, so it must not
                // outrank one we can work out for ourselves.
                bool fallbackOnly = string.Equals(arcadeGame, GenericArcadeGameName,
                                                  StringComparison.Ordinal);
                bool resolved = !string.IsNullOrEmpty(arcadeGame) && !fallbackOnly;

                if (resolved && (!customCode || CustomGameIsThisArcadeCabinet(gameName)))
                {
                    // Detection identified the running process, which beats anything
                    // inferred from a profile's configured name.
                    gameName = arcadeGame;
                }
                else if (customCode)
                {
                    // Detection cannot answer, but a SimHub custom game whose process
                    // belongs to a TeknoParrot profile IS that cabinet, and we can say
                    // so now. Naming it here rather than waiting is what keeps the
                    // arcade path engaged: held at its guid, ActiveGameIsArcade reads
                    // false and no arcade telemetry source is ever built.
                    string profile = ProfileForCustomGame(gameName);
                    if (!string.IsNullOrEmpty(profile))
                    {
                        string named = ArcadeGameName(profile);
                        if (!string.Equals(named, _customGameNamedAs, StringComparison.Ordinal))
                        {
                            _customGameNamedAs = named;
                            SimHub.Logging.Current.Info(
                                $"[TF4ALL] This custom game runs the same program as TeknoParrot's "
                                + $"'{profile}' cabinet, so its settings are saved under '{named}' rather "
                                + "than the placeholder name SimHub uses for a game it does not know.");
                        }
                        gameName = named;
                    }
                    else if (fallbackOnly)
                    {
                        // Something arcade-shaped is running that no profile claims.
                        // The fallback is a poor name but it is an arcade one, so the
                        // arcade path still engages.
                        gameName = arcadeGame;
                    }
                }
                else if (fallbackOnly)
                {
                    gameName = arcadeGame;
                }
            }

            // Remember the last game SimHub named so the process-table rescue
            // (IsKnownGameProcessRunning) has a target to fuzzy-match against
            // after a pause nulls _activeGame.
            if (!string.IsNullOrEmpty(gameName)) _lastNamedGame = gameName;
            // The startup seed bridges Init to this first tick and no further:
            // from here SimHub's own data says what is running, including that
            // nothing is.
            _startupGameName = null;
            // While offline-editing a CAR, _activeGame is pinned to that car's game
            // (EnterOfflineEditCar) so the Car-facts panel keys against the right
            // (game, carId). IsOfflineEditing is keyed on the PRESET-edit flag, so it
            // doesn't cover a car edit; without !IsOfflineEditingCar here the block
            // would stomp the pin AND fire ApplyGamePreset over the edit baseline.
            if (gameName != _activeGame && !IsOfflineEditingCar)
            {
                _activeGame = gameName;
                // The demotion for a game's own Trueforce stream belongs to the
                // game session that earned it. The resolve below lands the new
                // game on its own default.
                _nativeStreamDemoted = false;
                // Same for the probe that precedes it: whether the LAST game
                // streamed says nothing about this one, so the new title earns
                // its own verdict.
                _nativeProbeSettled = false;
                // "Does this game report an engine" is a fact about one game,
                // so the next one gets to answer it for itself. Until it does,
                // the audio meter may take the rev bar.
                _revDataSeen = false;
                _standDownNoticeShownThisDemotion = false;
                _mairaTapDegraded = false;
                _mairaTapWarned = false;
                _mairaTapCheckTicks = 0;
                _tfContention.Reset();
                // New game (or game gone): the FS pipe's fed-this-game latch
                // belongs to the session that set it (it lengthens the
                // SimHub-fallback dwell in EvaluateFsTelemetryFallback).
                _fsPipeFedThisGame = false;
                // Normal only. The enhanced sources bind sockets and open shared
                // memory, and the Forza one takes UDP 5300, which is the game's own
                // Data Out port. A mode that promises to touch nothing but the
                // wheel's lights must not be holding it.
                if (MasterMode == TrueforceMasterMode.Normal) SwapTelemetrySource(gameName);
                // Re-arm/disarm Mode B for the new game (Mode B capable games
                // = synthesized force; everything else = the normal pass-
                // through path). The contention watchdog latch resets here
                // explicitly: a capable-to-capable game switch keeps
                // _forceMode == ForceModeModeB, so the clean-engage reset inside
                // ApplyModeBFromSettings would not run, and a warning latched
                // on the previous game would suppress (and misattribute) the
                // new game's verdict.
                _contentionWarned = false;
                _contentionSinceTicks = 0;
                ModeBContentionDetected = false;
                // Same reasoning for the slip-starved latch: each game's
                // telemetry setup deserves its own verdict, and a stale
                // debounce count must not let the next game's first starved
                // tick warn instantly.
                _slipStarvedWarned = false;
                ModeBSlipStarvedDetected = false;
                _starvedLiveTicks = 0;
                // Spring mode is armed against ONE game's bus picture; a game
                // switch invalidates it (and must not suppress the new game's
                // GameFfbExpected escalation while stale-armed). The arming
                // machine re-arms within ~1 s if the new game springs too.
                if (_forceMode == ForceModeSpring)
                {
                    _forceMode = ForceModeOff;
                    _springArmCandidateSinceTicks = 0;
                    // Same stale-capture hygiene as the arming machine's
                    // disarm: pass-through resumes and must find nothing.
                    _ffbTap?.ClearLastFfbTarget();
                    SimHub.Logging.Current.Info("[TF4ALL] Spring mode disarmed (game changed).");
                }
                ApplyModeBFromSettings();
                // Smoothing is game-aware (RaceRoom carries its own ~3 ms), so
                // push the value for the new game to the device now.
                ApplyEffectiveSmoothing();
                // Traction loss is per-game gated (FS: Axle slip owns slip);
                // re-apply on every game change so the gate flips even when
                // the new game has no bound preset to trigger the apply-all.
                ApplyTractionSettings(GetActiveCarOverride()?.TractionLoss ?? Settings?.TractionLoss);
                // Auto-apply the bound game default, UNLESS the user is
                // offline-editing a preset. In that case we don't clobber
                // their in-progress edits; the SettingsControl banner stays
                // up so they can decide (Save / Save as new / Discard).
                if (!IsOfflineEditing
                    && !string.IsNullOrEmpty(gameName) && Settings?.GameDefaults != null
                    && Settings.GameDefaults.TryGetValue(gameName, out var presetName)
                    && !string.IsNullOrEmpty(presetName)
                    && Settings.Presets != null
                    && Settings.Presets.TryGetValue(presetName, out var snap) && snap != null)
                {
                    ApplyGamePreset(snap);
                    _activePresetName = presetName;
                    SimHub.Logging.Current.Info($"[TF4ALL] Loaded preset '{presetName}' as default for '{gameName}'.");
                }
                else if (!IsOfflineEditing
                    && !string.IsNullOrEmpty(gameName)
                    && Settings?.GameDefaults != null
                    && !Settings.GameDefaults.ContainsKey(gameName)
                    && !IsNativeTrueforceGame(gameName))
                {
                    // Unmapped game (no built-in binding, no user default):
                    // give it its own preset seeded from the Assetto Corsa
                    // baseline so a new / unsupported title starts from the
                    // user's tuned-on-a-GPRO AC values instead of bland class
                    // defaults, and so edits land in a per-game preset they
                    // keep rather than silently mutating globals.
                    EnsureSeededGamePreset(gameName);
                }

                // Per-game master enable. Default is "true" for unseen games,
                // EXCEPT for games that bring Trueforce of their own, which default
                // to LIGHTSYNC ONLY: our ep3 stream would fight theirs, but the
                // wheel's patterns cost the game nothing, so we keep those and hand
                // the force back. Saved values always win over defaults, so a user
                // who explicitly enabled us for one of those games keeps that choice.
                //
                // Nothing is WRITTEN to the per-game map here any more. The map is a
                // record of the user's own choices; writing our default into it made
                // that default indistinguishable from a decision they had made, and
                // it is what pinned every native-Trueforce game to off.
                if (Settings != null)
                {
                    bool sawSaved = !string.IsNullOrEmpty(gameName)
                        && ((Settings.GameModes != null && Settings.GameModes.ContainsKey(gameName))
                            || (Settings.GameEnabled != null && Settings.GameEnabled.ContainsKey(gameName)));
                    if (!sawSaved && IsNativeTrueforceGame(gameName))
                    {
                        SimHub.Logging.Current.Info(IsIRacingReshapeGame(gameName)
                            ? "[TF4ALL] iRacing brings Trueforce of its own, so we start on Lightsync only: our "
                              + "Trueforce effects and FFB tap are off, the Lightsync features stay. Normal carries "
                              + "iRacing's own force feedback through the plugin with our effects and the wheel's "
                              + "screen on top, after a short setup in iRacing."
                            : $"[TF4ALL] '{gameName}' brings Trueforce of its own, so we start on Lightsync only: "
                              + "our Trueforce effects and FFB tap are off, the Lightsync features stay. For our "
                              + "Trueforce instead of the game's, switch the game's own off and pick Normal; while "
                              + "the game is still streaming, Normal drops back to Lightsync only by itself.");
                    }
                    // iRacing's setup notice, on sight rather than on panel-open.
                    MaybeFireIracingNotice(gameName);
                    // Assetto Corsa CSP setup offer, same "on sight" timing.
                    MaybeFireAcCspNotice(gameName);

                    // RESOLVE rather than push. This used to write the master switch
                    // itself from the per-game map, which under a third state would
                    // drag a lights-only user into Normal the moment they started a
                    // game they had once enabled. ResolveEffectiveMode keeps the
                    // old Normal/Off behaviour bit for bit and leaves the stored
                    // choice where the user put it.
                    ApplyEffectiveMode("game change");
                }

                // Drive-tab boxes follow the game, when the user asked them
                // to. Nothing is written here: the refresh re-reads which
                // stored list is in force now that _activeGame has moved, so
                // a game with no layout of its own simply keeps showing the
                // shared one. Cheap enough to run unconditionally, but gated
                // anyway so an install that never turned this on cannot be
                // affected by it at all.
                if (Settings?.DashDriveSlotsPerGame == true)
                {
                    try { RefreshDashTabSlots(); }
                    catch (Exception ex)
                    {
                        SimHub.Logging.Current.Warn(
                            "[TF4ALL] Per-game Drive layout refresh failed: " + ex.Message);
                    }
                }
                // What the picker greys out is a fact about the GAME, so it is
                // rebuilt here rather than polled. Unconditional: this one is
                // not behind a setting.
                try { RecomputeDashUnsupported(); }
                catch (Exception ex)
                {
                    SimHub.Logging.Current.Warn(
                        "[TF4ALL] Game capability refresh failed: " + ex.Message);
                }
                // A count belongs to the session that produced it. Leaving one
                // behind would print an iRacing incident total over a Forza
                // session and, worse, measure the next iRacing session's first
                // reading against it.
                IRacingIncidentsReset();
            }

            // The condition renderer's damper is a feedback loop, so it wants
            // the freshest velocity available for as long as it is rendering.
            try { MaintainRendererMotionSource(); } catch { }
            try { MaintainStreamNotStuckSuspended(); } catch { }

            // Watch what this game reports, so the picker learns which boxes
            // it can never fill. After the block above, so a frame of the new
            // game's data is never credited to the old one.
            try { DashLearnCapabilities(data); } catch { /* display only */ }

            // Track car changes and apply per-car override (or revert).
            string carId = data?.NewData?.CarId ?? data?.NewData?.CarModel;
            // RaceRoom (R3E) exposes a friendly car name in telemetry; capture
            // it so CarFacts (header, Rename prefill) shows e.g. "Honda Accord
            // Super Touring" instead of a blank or a numeric id. Some RaceRoom
            // builds prefix a numeric model id ("8645,Honda ..."); drop it.
            if (IsR3EGame(_activeGame))
            {
                string r3eName = data?.NewData?.CarModel;
                if (!string.IsNullOrEmpty(r3eName))
                {
                    int comma = r3eName.IndexOf(',');
                    if (comma > 0)
                    {
                        bool allDigits = true;
                        for (int i = 0; i < comma; i++)
                            if (!char.IsDigit(r3eName[i])) { allDigits = false; break; }
                        if (allDigits) r3eName = r3eName.Substring(comma + 1).Trim();
                    }
                    if (!string.IsNullOrEmpty(r3eName)) _r3eCarDisplayName = r3eName;
                }
                // The one engine fact RaceRoom publishes: combustion, electric
                // or hybrid. Read once per car (it cannot change without a car
                // change) so the cost is a reflection walk per switch, not one
                // per frame.
                if (!string.Equals(_r3eEngineTypeCarId, carId, StringComparison.Ordinal))
                {
                    _r3eEngineTypeCarId = carId;
                    _r3eEngineType = ReadR3EEngineType(data);
                }
            }
            // Forza fallback when SimHub's data feed has no CarId: a user with
            // UDP forwarding misconfigured, or who hasn't selected a Forza
            // profile in SimHub, gives us null here even while the Forza game
            // is live and our UDP source IS reading packets. Our source parses
            // CarOrdinal direct from the UDP stream so we can still detect
            // per-car switches and apply per-car overrides without depending
            // on SimHub's profile being wired up. Prefix Car_<ordinal> to
            // match SimHub's NewData.CarModel format for Forza, so the
            // SimHub-supplied path and this fallback converge on one key for
            // the same physical car. (Was Forza_<ordinal> historically;
            // legacy entries are migrated by the startup Forza car-id migration.)
            if (string.IsNullOrEmpty(carId) && IsForzaGameName(_activeGame))
            {
                var fzForCarId = _telemetrySource as ForzaUdpTelemetrySource;
                int? ordinal = fzForCarId?.CurrentCarOrdinal;
                if (ordinal.HasValue) carId = "Car_" + ordinal.Value.ToString(System.Globalization.CultureInfo.InvariantCulture);
            }
            // Farming Simulator: SimHub has NO car identity for FS and
            // fabricates a per-session placeholder ("DC__" + its own startup
            // timestamp), so every session every vehicle was a brand-new
            // "car": presets, car facts and engine pins never resolved
            // across sessions, and community facts keyed on garbage. The
            // TF4ALL mod (>= 0.2.5) reports the vehicle's configFileName;
            // the pipe source turns it into a stable cross-machine id.
            // Prefer it whenever the mod has reported one this session; the
            // placeholder remains only for users without the mod.
            if (_activeGame != null
                && _activeGame.StartsWith("FarmingSimulator", StringComparison.Ordinal))
            {
                string fsCarId = _fsPipeSource?.StableCarId;
                if (!string.IsNullOrEmpty(fsCarId)) carId = fsCarId;
            }
            // Arcade cabinets: SimHub knows nothing about them at all, so without this every car
            // is "no car selected" and the whole per-car layer stays empty. Car facts, presets, the
            // engine pin and the community lookups are all keyed on this one string. The code from
            // the game's own car table is the right key: it is stable across launches, unique per
            // car, and legible in the UI, which a raw ordinal would not be.
            //
            // NOT gated on carId being empty. Once a SimHub custom game profile exists for a
            // cabinet, SimHub reports a running game and fabricates the same per-session
            // "DC__<startup timestamp>" placeholder it invents for Farming Simulator. That is not
            // a car, it is a different string every session, and while it sat here the cabinet's
            // real car could never take the slot: the panel offered to auto-detect an engine for
            // 'DC__260906032116' before a car had even been chosen, and every preset, car fact and
            // community lookup would have keyed on a value that changes on every launch.
            if (ActiveGameIsArcade)
            {
                var arcadeCar = ArcadeCarNow();
                if (arcadeCar != null) carId = "ID8_" + arcadeCar.Code;
                else if (IsSimHubPlaceholderCarId(carId)) carId = null;   // no car chosen yet
            }

            // Runtime alias: a legacy Forza_<n> id arriving from any source
            // (older SimHub build, third-party plugin, an older Trueforce
            // install that wasn't normalized yet) gets rewritten to Car_<n>
            // before any lookup. Without this, a stored Car_<n> preset would
            // miss when telemetry happens to feed us the Forza_ shape.
            // Forza-game scoped so a hypothetical non-Forza carId starting
            // with "Forza_" wouldn't get clobbered.
            if (!string.IsNullOrEmpty(carId)
                && IsForzaGameName(_activeGame)
                && carId.StartsWith("Forza_", System.StringComparison.Ordinal))
            {
                carId = "Car_" + carId.Substring("Forza_".Length);
            }
            // Forza un-sets the active car whenever the game loses focus
            // (alt-tab, screensaver, etc.), then re-sets it the moment focus
            // returns. Treating those transient nulls as a real "car gone"
            // event resets every effect's auto-cylinder / IIR state and
            // strands the user on a no-car-selected settings UI while
            // they're trying to tune. Latch the previous carId across null
            // gaps for Forza specifically; a real car switch (going to a
            // different car) still passes through because the next non-null
            // carId differs from _activeCarId. A real game-exit changes
            // _activeGame first (handled above), so this latch doesn't
            // hold a stale Forza car into another game.
            if (string.IsNullOrEmpty(carId)
                && !string.IsNullOrEmpty(_activeCarId)
                && IsForzaGameName(_activeGame))
            {
                carId = _activeCarId;
            }
            // While offline-editing a car preset, freeze the active car to the
            // one being edited: a live car change must not switch away (which
            // would discard the edit and aim a save at the wrong car).
            if (IsOfflineEditingCar)
                carId = _offlineEditCarId;
            if (carId != _activeCarId)
            {
                // Switching cars discards the outgoing car's UNSAVED draft
                // (per-car edits that weren't saved): restore its in-memory
                // override to the persisted baseline before we move on.
                DiscardUnsavedCarDraft(_activeCarId);
                _activeCarId = carId;
                // Grip auto-cal is (re)loaded per VARIANT on the telemetry
                // thread by the variant-change detector in DispatchFrame, not
                // here: the variant signature isn't resolved at car-change time
                // (EnginePulse observations are reset just below), and the
                // learner must only be touched from the thread that Ticks it.
                // Clearing _lastAppliedVariantSignature below makes that
                // detector fire on the next frame, which flushes this car's
                // outgoing variant and loads the new one.
                // Drop the prior car's community consensus so the resolver
                // doesn't briefly attribute it to the new car. Repopulated by
                // MaybeRefreshCommunityFactsHeadless below (cache replay +
                // TTL fetch); an open SettingsControl re-fetches too for its
                // community-context row.
                _activeCarCommunityKey = null;
                _activeCarCommunityConsensus = null;
                _activeCarCommunityNameKey = null;
                _activeCarCommunityNameConsensus = null;
                _activeCarCommunityRedlineKey = null;
                _activeCarCommunityRedlineConsensus = null;
                // Reset EnginePulse observation fields here (not in
                // ResolveAndApplyCarFactsForActiveCar) so the variant
                // signature gets a clean slate for the new car. Next
                // telemetry frames repopulate.
                if (EnginePulse != null)
                {
                    EnginePulse.ObservedCyl = null;
                    EnginePulse.ObservedIsElectric = false;
                    EnginePulse.ObservedMaxRpm = 0.0;
                    EnginePulse.ObservedRedlineRpm = 0.0;
                }
                // Variant-signature cache pinned to the OLD car gets cleared
                // here so the first telemetry frame for the new car (which
                // arrives after the ResolveAndApply below has stamped the
                // cache for "empty sig at car-change") triggers a fresh
                // mid-session re-resolve when discriminators appear.
                _lastAppliedVariantSignature = null;
                // Clear any per-car edge-detected / IIR state on the effects and
                // the device's FFB filter chain so the new car's first frames
                // don't get blended with the previous car's last sample (e.g. a
                // spurious gear thud from a 4→1 apparent transition, or an FFB
                // smoothing transient biased toward the old car's last torque).
                if (_effects != null)
                {
                    for (int i = 0; i < _effects.Length; i++)
                    {
                        try { _effects[i].Reset(); } catch { }
                    }
                }
                _device?.ResetFfbFilters();
                // New car, discard the previous car's auto-detected layout so
                // the next resolver hit (or first telemetry frame) populates
                // fresh. Then re-run the CarFacts cascade for the new carId.
                ResolveAndApplyCarFactsForActiveCar(carId, logResolution: true);
                // Community facts must apply with the settings panel CLOSED
                // too (SimHub on another view / remote-dash-only sessions):
                // replay the offline cache + TTL-fetch for the new car. The
                // signature is still partial here; the variant-change
                // detector in DispatchFrame re-runs this when telemetry
                // fills the signature in.
                MaybeRefreshCommunityFactsHeadless();
                // Re-resolve the new car's preset from disk so the applied
                // tuning always MATCHES the car you just switched to. A car
                // cleared to "None" stays cleared on re-entry: the explicit
                // None is latched in SuppressedCarDefaults and wins over any
                // factory binding until the user picks a preset again. When
                // the car is gone (carId null, e.g. back to a menu) we can't
                // resolve, so fall back to applying globals as before.
                if (!string.IsNullOrEmpty(_activeCarId))
                    ReloadActiveCarOverrideFromStore();
                else
                    ApplyActiveCarOverride();
                // Opportunistic backfill: legacy migration (and pre-fix
                // built-ins) wrote car preset files with GameName="" because
                // no game was active at the time. Now that we know which game
                // this car belongs to, retag any of its on-disk presets that
                // are still empty. Skips built-ins (refreshed by
                // InstallOrUpdateBuiltinCarPresets on Init from the bundled
                // JSON), skips files already tagged. Dedup'd per
                // (game, carId) per session.
                if (_carStore != null
                    && !string.IsNullOrEmpty(_activeGame)
                    && !string.IsNullOrEmpty(_activeCarId)
                    && _gameNameBackfillDone.Add(_activeGame + "|" + _activeCarId))
                {
                    BackfillGameNameForActiveCar();
                }
                // Similar one-shot per-car for DisplayName: rename legacy
                // presets whose name was just the carId (e.g. "Car_424") into
                // the friendlier resolver-provided name ("1997 Mazda RX-7").
                // Gated on resolver having a DisplayName for this car so it
                // doesn't fire for AC where carIds are already descriptive.
                if (_carStore != null
                    && !string.IsNullOrEmpty(_activeGame)
                    && !string.IsNullOrEmpty(_activeCarId)
                    && !string.IsNullOrEmpty(_activeCarDisplayName)
                    && _displayNameBackfillDone.Add(_activeGame + "|" + _activeCarId))
                {
                    BackfillDisplayNameForActiveCar();
                }

                // The DATA edge, deliberately out here rather than down in the
                // LED branch. Redlines and blink rate are not a lighting
                // feature: they move the shift cue and the limiter buzz, which
                // every wheel has. Left inside `if (levelWheel)` this never ran
                // for a G923 PS/PC, which is exactly the wheel the split was
                // meant to reach. Latched per car inside, so the lighting edge
                // calling it again a few lines later costs nothing.
                if (MasterMode != TrueforceMasterMode.Off)
                    OnLovelyCarChanged(_activeGame, _activeCarId);

                // Lights-only runs no telemetry source, so the car-load edge that
                // normally arrives on a frame has to be driven from here. Normal mode
                // deliberately keeps using the frame path: it can prove the HID++
                // pipe is free of the game's force and this cannot, and the latch
                // inside means only the first caller acts either way.
                if (MasterMode == TrueforceMasterMode.LightsyncOnly)
                    ApplyCarLightsForActiveCar(ffbQuietProven: false);
            }

            // Same reasoning for handing a slot back when the user turns the base's
            // own dial away from ours: in lights-only there is no frame to notice it
            // on. Cheap (four early returns) so it rides the data tick.
            if (MasterMode == TrueforceMasterMode.LightsyncOnly)
                ReleaseBorrowIfWheelMovedAway();

            // G HUB UI presence check. Polled every ~5 s; logs on transitions.
            // Surfaced in the UI as a warning banner because the G HUB UI can
            // block our HID open call and is a common "wheel doesn't respond"
            // cause. Only lghub.exe counts here (not the background agent).
            {
                long nowG = Stopwatch.GetTimestamp();
                if (nowG - _lastGHubCheckTicks > GHubCheckIntervalTicks)
                {
                    _lastGHubCheckTicks = nowG;
                    bool running = false;
                    try
                    {
                        // GetProcessesByName("lghub") matches ONLY lghub.exe (the
                        // G HUB UI), not lghub_agent / lghub_updater / lghub_system_tray.
                        // Deliberate: the background agent is essentially always
                        // present, so counting it here made _isGHubRunning latch true
                        // for the whole session and stopped MaybeRecoverDevice from
                        // ever re-attaching after an idle-time stream fault. The wheel
                        // then stayed "not detected" until SimHub restarted (which
                        // re-runs the ungated startup bring-up). The agent does not
                        // hold the wheel's MI_02 Trueforce interface.
                        var ghubProcs = System.Diagnostics.Process.GetProcessesByName(GHubProcessName);
                        if (ghubProcs.Length > 0) running = true;
                        // Dispose the snapshot Process objects so their handles aren't
                        // left to the finalizer on every 5s check while G HUB is open.
                        foreach (var gp in ghubProcs) { try { gp.Dispose(); } catch { } }
                    }
                    catch { /* process enumeration can fail under some sandbox conditions; treat as not-running */ }
                    if (running != _gHubLastLoggedState)
                    {
                        _gHubLastLoggedState = running;
                        SimHub.Logging.Current.Info(
                            running
                                ? "[TF4ALL] Logitech G HUB detected. It claims the wheel's HID interface and blocks Trueforce. Close G HUB and restart SimHub."
                                : "[TF4ALL] Logitech G HUB no longer detected. Wheel access should be available again.");
                        SimHub.Logging.Current.Info(
                            "[TF4ALL] Logitech processes running: " + SnapshotLogitechProcesses());
                    }
                    _isGHubRunning = running;
                }
            }

            // Transparently re-attach the wheel after a hot-unplug, a faulted
            // stream, a closed-G-HUB, or a wheel that wasn't present at
            // startup. Cheap when healthy (a couple of field checks); the
            // blocking bring-up runs off-thread.
            MaybeRecoverDevice();

            // Retry enhanced-source acquisition once per second while we have
            // an enhanced-eligible game running but are still on the SimHub
            // fallback. Covers the AC menu→session window (MMF not yet
            // created), and any other source that needs to wait for the game
            // to be fully loaded before its data surface is available.
            // Excludes a Forza session whose listener is already bound: there
            // EvaluateForzaTelemetryFallback owns the enhanced<->SimHub choice,
            // so re-Swapping here would yank the active source back to the
            // silent listener for a tick every second (a periodic FFB dropout).
            // A failed Forza bind leaves _forzaUdp null, so the retry still
            // re-attempts the bind in that case.
            if (!string.IsNullOrEmpty(_activeGame)
                && _telemetrySource != null && !_telemetrySource.IsEnhanced
                && IsEnhancedEligible(_activeGame)
                && _forzaUdp == null)
            {
                long now = Stopwatch.GetTimestamp();
                if (now - _lastEnhancedRetryTicks > Stopwatch.Frequency)
                {
                    _lastEnhancedRetryTicks = now;
                    SwapTelemetrySource(_activeGame, silent: true);
                }
            }

            MaybeStartPortDiscovery();

            // Cache slow-rate fields for the enhanced-source overlay step in
            // DispatchFrame. Always populated from SimHub regardless of which
            // source is currently dispatching, so the cache stays warm during
            // an enhanced run and is immediately available when AC starts.
            var nd = data?.NewData;
            if (nd != null)
            {
                _lastSimHubMaxRpm           = nd.MaxRpm;
                _lastSimHubAbsActive        = nd.ABSActive;
                _lastSimHubPitLimiterActive = nd.PitLimiterOn;
                _lastSimHubDrsActive        = nd.DRSEnabled;
            }

            // SimHub's own not-driving flags (paused / in menu / replay),
            // for the slip-starved pass-through gate. The SimHub fallback
            // source cannot see Forza's raceOn, and its physics proxy reads
            // a replay or a frozen pause frame as a live session; these
            // flags are the only pause/replay signal that exists on the
            // fallback. Best effort: game readers that never set them leave
            // this false, which is exactly the pre-flag behavior.
            _gameNotDrivingState = data != null
                && (data.GamePaused || data.GameInMenu || data.GameReplay);

            // Hand the GameData to the SimHub source. It builds a
            // TelemetryFrame and fires OnFrame → DispatchFrame, which is
            // where we update audio gain and fan out to effects. Done this
            // way so an enhanced source (AC MMF, etc.) drives the same
            // dispatch path at its native rate without forking effect code.
            _simHubSource?.PushFromGameData(data);

            // Now that _simHubSource.MeasuredHz reflects this tick, decide
            // whether a Forza session should run on the enhanced UDP source or
            // the SimHub fallback. No-op outside Forza.
            EvaluateForzaTelemetryFallback();
            // Same decision for Farming Simulator's pipe source. No-op outside FS.
            EvaluateFsTelemetryFallback();

            // Cache the SimHub-computed redline RPM after the push (it's derived
            // there from CarSettings_RedLineRPM). Overlaid onto enhanced-source
            // frames in DispatchFrame so the rev limiter gets the real redline
            // on AC / etc. Mirror it EXACTLY, including 0: LastRedlineRpm is now
            // 0 for games that report no real redline, and an old `> 0` guard
            // would leave a previous redline-game's value cached and bleed it
            // onto a no-redline game (firing the buzz at a phantom redline).
            if (_simHubSource != null)
                _lastSimHubRedlineRpm = _simHubSource.LastRedlineRpm;

            // Learn, once per game, that this title reports a usable redline,
            // so the rev-limiter UI is stable (engage-% row hides for redline
            // games even before telemetry flows next session). Positive-only;
            // persisted once on first observation. Forza is excluded outright:
            // its per-car redline can legitimately land inside the sanity gate
            // (an RX-7 in FH6 passed it), but Forza has no precise rev limit we
            // can fire AT, so it must keep the engage-% control. The sanity gate
            // alone wasn't enough; the game-family exclusion is the real rule.
            if (!string.IsNullOrEmpty(_activeGame) && !IsForzaGameName(_activeGame)
                && Settings?.GamesWithRedline != null
                && !Settings.GamesWithRedline.Contains(_activeGame))
            {
                double r = _lastSimHubRedlineRpm, m = _lastSimHubMaxRpm;
                if (r > 100.0 && (m <= 100.0 || (r <= m * 1.02 && r >= m * 0.5)))
                {
                    // Structural mutation on the data thread: hold _carFactsLock so a
                    // concurrent settings serialize can't enumerate the set mid-Add.
                    lock (_carFactsLock) { Settings.GamesWithRedline.Add(_activeGame); }
                    // Flush off-thread (this runs on the data tick; the disk write is
                    // not time-sensitive). GamesWithRedline is backup-Excluded, so
                    // skipping PersistSettings' auto-backup arm is correct here.
                    ScheduleSettingsFlush();
                }
            }

            // SPIKE (2026-09-06): publish arcade telemetry into SimHub's own
            // standard fields. Last, so every consumer above ran unspoofed.
            ArcadeBridgeSpikeWrite(pluginManager, data);
        }

        /// <summary>OnFrame handler bound to whichever ITelemetrySource is
        /// currently active. Runs on the source's polling thread (SimHub's
        /// data tick today; an MMF reader thread once enhanced sources land).
        /// Updates audio-throttle modulation and dispatches to each effect;
        /// per-effect exceptions are swallowed so one bad effect can't
        /// break the rest of the haptic pipeline.</summary>
        private void DispatchFrame(TelemetryFrame frame)
        {
            // Freshness stamp for the stall watchdog in DataUpdate. A real frame
            // just arrived, so clear the stall latch and re-arm the timer.
            System.Threading.Interlocked.Exchange(ref _lastFrameTicks, Stopwatch.GetTimestamp());
            _telemetryStalled = false;
            _surfacesReleasedOnStall = false;

            // Fill the fields SimHub's generic reader leaves null for iRacing,
            // before Caps is computed and before any effect sees the frame.
            ApplyIRacingOverlay(ref frame);

            // Engine data read out of an arcade game's own memory, stamped HERE rather than inside
            // a force source. Those two things are unrelated, and binding them cost a session: an
            // unrelated bug in arcade source selection meant the force source never started, which
            // silently took the telemetry with it. Owned by the plugin, it survives source swaps
            // and works whichever arcade route is live.
            ApplyArcadeMemoryTelemetry(ref frame);

            // Frame enrichment (SimHub-cache overlay for enhanced sources +
            // universal collision derivation) moved to the Engine's
            // FrameEnricher in phase 0c so the replay harness runs the exact
            // production logic. Rationale comments live there.
            var src = _telemetrySource;
            // FS: slow vehicles need a lower collision bar (a tractor into a
            // tree at 25 km/h peaks near 3.5g, under the 5g racing default,
            // and FS driving never brakes past ~0.7g so 2g is safe).
            bool fsFrames = _activeGame != null
                && _activeGame.StartsWith("FarmingSimulator", StringComparison.Ordinal);
            FrameEnricher.Enrich(ref frame,
                sourceIsEnhanced: src != null && src.IsEnhanced,
                new SimHubOverlay
                {
                    MaxRpm           = _lastSimHubMaxRpm,
                    AbsActive        = _lastSimHubAbsActive,
                    RedlineRpm       = _lastSimHubRedlineRpm,
                    PitLimiterActive = _lastSimHubPitLimiterActive,
                    DrsActive        = _lastSimHubDrsActive,
                },
                suppressRedlineOverlay: IsForzaGameName(_activeGame),
                collisionThresholdMps2: fsFrames ? 20.0 : 49.0,
                sourcePublishesPhysics: src == null || src.PublishesPhysics);

            // Live RPM for the remote dash's rev strip (Dash.Rpm / Dash.RpmPct
            // in TrueforcePlugin.DashRemote.cs). Stashed post-enrichment so the
            // strip sees the same RPM the effects do.
            // Menu knocks. Here rather than anywhere race-scoped, because the whole point is the
            // moments when no race is running: an arcade source keeps emitting frames in its menus,
            // which is what makes this reachable at all.
            TickArcadeMenuHaptics();

            // A cabinet meters its audio between races without being asked to, so the meter has to
            // start when one appears. The mode-change path that normally syncs it does not run for
            // a game arriving, so the moment the map proves out is the moment to ask again.
            var arcadeForMeter = _arcadeMemory;
            bool arcadeMapped = arcadeForMeter != null && arcadeForMeter.Verified;
            if (arcadeMapped != _arcadeMeterSynced)
            {
                _arcadeMeterSynced = arcadeMapped;
                try { SyncAudioOutputMeter(); } catch { }
            }

            _dashLiveRpm = (float)frame.Rpms;
            // Gear and speed for the Drive tab's center readout, from the same
            // enriched frame. These come from whichever source is live, so a
            // Forza player who never turned on "Also forward to SimHub" still
            // gets them: SimHub's own properties are empty for that setup, and
            // the two biggest numbers on the screen would otherwise read N and
            // "--" while every box around them worked.
            // Shown exactly as the source reports it. The mid-shift "10" was
            // Forza's shift sentinel and is handled where it arrives, in
            // ForzaUdpTelemetrySource, so the readout has no reason to second
            // guess the frame: a filter here would only make the dash disagree
            // with the in-game gear.
            _dashLiveGear = frame.Gear ?? "";
            _dashLiveSpeedKmh = (float)frame.SpeedKmh;
            // Driver inputs for the Drive tab's inputs box. Steering is the
            // interesting one: SimHub has no universal steering property (see
            // TelemetryFrame.SteeringAngle), so this is the only place the
            // dash can get it. -2 means "this source does not report it",
            // which the box shows as a dash rather than a centered wheel.
            _dashLiveThrottle = (float)frame.Throttle01;
            _dashLiveSteer = frame.SteeringAngle.HasValue ? (float)frame.SteeringAngle.Value : -2f;

            // Latch motion for the stationary-spring FFB floor. Speed is
            // universal; steering is stamped only when the active source
            // actually reports it (AC), so the spring stays disengaged on
            // sources that don't (the freshness check in the provider).
            _lastSpeedKmh = (float)frame.SpeedKmh;
            _lastThrottle01 = (float)frame.Throttle01;
            _lastRpms = (float)frame.Rpms;
            // The grip re-learn request is consumed here rather than inside the learning block:
            // it must land in EVERY mode and on every source. The learning block
            // needs tire quads and Mode B, so leaving the consumption in there
            // meant a reset typed while in spring or iRacing mode sat queued and
            // then fired on whatever car was loaded the next time Mode B ran,
            // wiping a calibration the user never asked to lose.
            ConsumeGripCalResetRequest();
            // Foreground tracking for the focus release. Telemetry thread, rate
            // limited internally; the FFB thread only reads the resulting flag.
            UpdateGameFocusState();
            // Mode B synthesis inputs: longitudinal accel for the weight-
            // transfer term, and the front-pair combined slip as the grip
            // utilization source. Written here (telemetry thread), read on
            // the FFB thread; slip angle freshness (below) doubles as the
            // gate for all of them.
            if (frame.AccelerationSurge.HasValue)
                _lastSurgeAccel = (float)frame.AccelerationSurge.Value;
            if (frame.AccelerationSway.HasValue)
                _lastSwayAccel = (float)frame.AccelerationSway.Value;
            if (frame.HasTireQuads)
            {
                // Load-weighted axle rollups (CtmComposer) instead of plain
                // pair averages: the loaded outside tire dominates the
                // reading, so cornering breakaway registers at the tire that
                // is actually doing the gripping. The EngineLoop recomposes
                // on its own resampled copy; Compose is stamp-guarded and
                // deterministic, so composing here too is safe.
                CtmComposer.Compose(ref frame);
                _lastFrontCombined = (float)frame.FrontGrip01.Value;

                // Braking-lockup gate input (issue #38): the worst (most
                // negative) front-pair SIGNED slip ratio, cached for the FFB
                // thread which fades the synthesized force out as the fronts
                // lock. Same worst-of-front-pair reading AxleSlipEffect gates on.
                _lastFrontSlipRatio = (float)Math.Min(frame.TireSlipRatio.FL, frame.TireSlipRatio.FR);
                // Friction-circle input: worst front |slip ratio| so wheelspin
                // spends the grip budget the same way lockup does.
                _lastFrontSlipRatioAbs = (float)Math.Max(
                    Math.Abs(frame.TireSlipRatio.FL), Math.Abs(frame.TireSlipRatio.FR));

                // Grip auto-cal input: the grip-peak learner watches the raw
                // front channel (it runs its own spike pre-filter). Learning
                // happens only while Mode B SYNTHESIS is live; _mbAutoCalOn only
                // gates whether the cached divisor leaves 1.0.
                //
                // ModeB and not "any mode but off": Farming Simulator runs spring
                // mode, and the FS source publishes tire quads once the newer mod
                // is installed, so this block used to learn a grip calibration
                // from tractor telemetry that nothing in spring mode reads back.
                // It wrote a per-car slot, flushed it, carried it into backups,
                // and logged "auto-cal converged" for a game where the number is
                // never applied.
                if (_forceMode == ForceModeModeB)
                {
                    long nowCal = Stopwatch.GetTimestamp();
                    double dtMsCal = _calPrevTicks == 0
                        ? 16.7
                        : (nowCal - _calPrevTicks) * 1000.0 / Stopwatch.Frequency;
                    _calPrevTicks = nowCal;
                    _gripCal.Tick(frame.FrontGrip01.Value, _lastSpeedKmh, dtMsCal);
                    if (_mbAutoCalOn) _mbCalPeak = (float)_gripCal.EffectivePeak;
                    // Auto strength: learn the composed-force ceiling from the
                    // FFB thread's pre-scale peak. Learning runs whenever Mode B
                    // is live (like the grip cal); the toggle only gates whether
                    // the scale leaves 1.0, so flipping it on later applies
                    // everything learned so far.
                    _strengthCal.Tick(_mbForceRawPeak, _lastSpeedKmh, dtMsCal);
                    _mbAutoStrengthScale = _mbAutoStrengthOn
                        ? (float)ModeBComposer.AutoStrengthScale(
                            _strengthCal.EffectivePeak, AutoStrengthTarget,
                            AutoStrengthMinScale, AutoStrengthMaxScale)
                        : 1f;
                    // Learned grip peak for the braking-grip radius (friction
                    // circle / gate). Tracked ALWAYS, regardless of the
                    // u-normalization toggle, so the radius follows each car's
                    // grip cal. Per the friction-circle model braking and
                    // cornering share one grip budget, so the (cornering-learned)
                    // peak is that budget; a trim absorbs any braking-vs-cornering
                    // offset.
                    _mbGripPeakForRadius = (float)_gripCal.EffectivePeak;
                    // Auto strength decided a number for this car and nothing
                    // ever showed it. Say it once per car, when the learner is
                    // confident enough for the scale to mean something (either
                    // freshly converged or restored from the car's saved slot).
                    if (!_autoStrengthAnnounced && _mbAutoStrengthOn
                        && _strengthCal.Confidence >= 1.0)
                    {
                        _autoStrengthAnnounced = true;
                        DashReadoutGain("AUTO STRENGTH", _mbAutoStrengthScale);
                    }
                    if (!_calConvergedLogged && _gripCal.Confidence >= 1.0)
                    {
                        _calConvergedLogged = true;
                        SimHub.Logging.Current.Info(
                            $"[TF4ALL] Grip auto-cal converged for '{_gripCalKey}': "
                            + $"peak={_gripCal.Peak:0.000} "
                            + $"({(_mbAutoCalOn ? "applied" : "learned, auto-cal off")})");
                    }
                }
                else
                {
                    // Not learning: forget when we last ticked, so the first
                    // frame back in Mode B measures one frame rather than the
                    // whole excursion through another mode.
                    _calPrevTicks = 0;
                }

                // Road-kick input: one-wheel bump kick from the FL/FR travel
                // difference rate. Ticked here (telemetry thread) at frame
                // rate; the FFB provider smooths the cached value to 1 kHz.
                if (_mbRoadKickOn)
                {
                    // Re-assert the Forza tuning every tick: the model is
                    // shared with the FS terrain site below, which runs its
                    // own gentler constants (property sets are free).
                    _roadKick.FullKickRateMps = 1.5;
                    _roadKick.Deadband = 0.12;
                    long nowK = Stopwatch.GetTimestamp();
                    double dtMsK = _kickPrevTicks == 0
                        ? 16.0
                        : (nowK - _kickPrevTicks) * 1000.0 / Stopwatch.Frequency;
                    _kickPrevTicks = nowK;
                    _mbKickCached = (float)_roadKick.Tick(
                        frame.SuspTravelM.FL, frame.SuspTravelM.FR, dtMsK);
                }
            }
            else if (frame.WheelSlip.HasValue)
            {
                // Degraded (no quads): the source's scalar slip stands in for the
                // front pair (quad sources take the branch above).
                _lastFrontCombined = (float)frame.WheelSlip.Value;
                _lastFrontSlipRatio = 0f;   // no signed slip on a scalar source: gate stays open
                _lastFrontSlipRatioAbs = 0f; // friction circle: full lateral share
            }
            // Axle rollups for the dash friction circle: composed above on quad
            // sources, carried natively otherwise. Farming Simulator is both,
            // depending on the mod: the newer one publishes all four wheels and
            // takes the quad branch, the older one carries only the rollups. A
            // source with one axle reports it for both rather than losing the box.
            if (frame.FrontGrip01.HasValue || frame.RearGrip01.HasValue)
            {
                _dashSlipFront   = (float)(frame.FrontGrip01 ?? frame.RearGrip01).Value;
                _dashSlipRear    = (float)(frame.RearGrip01 ?? frame.FrontGrip01).Value;
                _dashSlipStampMs = Environment.TickCount;
                if (!_dashSlipSeen)
                {
                    // First slip of this game run: un-grey the friction box
                    // now rather than at the next capability flush.
                    _dashSlipSeen = true;
                    RecomputeDashUnsupported();
                }
            }
            // Axle slip needs BOTH rollups, not either: it reads front and rear
            // utilization separately and returns silent without the pair. Latched
            // per game run so the panel can hide a section that provably cannot
            // speak here, instead of naming games one at a time.
            if (frame.FrontGrip01.HasValue && frame.RearGrip01.HasValue) _axleFeedSeen = true;
            if (_axleFeedFrames < AxleFeedVerdictFrames) _axleFeedFrames++;
            // Suspension-load input: front suspension compression vs its own
            // slow baseline = live front-axle load ratio. The baseline EMA
            // (~3 s) learns the car's ride height, so the ratio reads dive,
            // kerbs and dips without per-car calibration. Telemetry thread
            // writes; ComputeModeBForce reads.
            if (frame.FrontSuspTravelMeters.HasValue)
            {
                float travel = (float)frame.FrontSuspTravelMeters.Value;
                if (travel > 0.001f)
                {
                    float baseline = _mbSuspBaseline;
                    _mbSuspBaseline = baseline <= 0f
                        ? travel
                        : baseline + (travel - baseline) * 0.005f;   // ~3 s at 60 Hz
                    _lastFrontSuspRatio = travel / Math.Max(0.005f, _mbSuspBaseline);
                }
            }
            if (frame.SteeringAngle.HasValue)
            {
                float newSteer = (float)frame.SteeringAngle.Value;
                long nowTicks = Stopwatch.GetTimestamp();

                // Wheel angular velocity for the FFB damper: d(steer)/dt with the
                // real frame interval, EMA-smoothed. Guard dt to a sane window so a
                // hitch or the first frame can't spike a huge velocity.
                if (_prevSteerVelTicks != 0)
                {
                    double dt = (nowTicks - _prevSteerVelTicks) / (double)Stopwatch.Frequency;
                    if (dt > 0.0005 && dt < 0.5)
                    {
                        float instVel = (float)((newSteer - _prevSteerForVel) / dt);
                        _steerVel += (instVel - _steerVel) * 0.3f;
                    }
                }
                _prevSteerForVel  = newSteer;
                _prevSteerVelTicks = nowTicks;

                _lastSteerNorm = newSteer;
                System.Threading.Interlocked.Exchange(ref _lastSteerTicks, nowTicks);
            }

            // Farming Simulator terrain: the same road-kick model and cache
            // Mode B's road kick uses, at its own compute site because FS
            // frames carry a suspension quad without the slip quads that gate
            // the Mode B branch above. Gated on the GAME, not on spring mode:
            // HID++ wheels (G PRO) take the pass-through path in FS, and
            // their terrain rides MaybeReshapeFfb's pass-through branch.
            // Never concurrent with the Mode B branch (Forza is not an FS
            // game), so sharing _roadKick / _mbKickCached / _kickPrevTicks
            // stays safe, same physical quantity in the same units.
            if ((Settings?.SpringModeTerrainEnabled ?? false)
                && _activeGame != null
                && _activeGame.StartsWith("FarmingSimulator", StringComparison.Ordinal)
                && (frame.SuspTravelM.FL != 0.0 || frame.SuspTravelM.FR != 0.0))
            {
                // FS tuning: farm texture is small suspension motion that
                // Forza's kerb-strike constants filter out entirely (owner
                // report 2026-08-07: only large bumps came through). Half
                // the deadband, half the full-scale rate, so field grain
                // reaches the rim while idle jitter still zeroes.
                _roadKick.FullKickRateMps = 0.75;
                _roadKick.Deadband = 0.06;
                long nowK = Stopwatch.GetTimestamp();
                double dtMsK = _kickPrevTicks == 0
                    ? 16.0
                    : (nowK - _kickPrevTicks) * 1000.0 / Stopwatch.Frequency;
                _kickPrevTicks = nowK;
                _mbKickCached = (float)_roadKick.Tick(
                    frame.SuspTravelM.FL, frame.SuspTravelM.FR, dtMsK);
                System.Threading.Interlocked.Exchange(ref _fsKickStampTicks, nowK);
            }

            // Cache the front slip angle for the FFB thread (Forza populates
            // it; other sources leave it null, so the stamp goes stale). Mode B
            // uses it for the force DIRECTION, and the tick stamp is the
            // telemetry-freshness gate its stall ramp ages against.
            if (frame.FrontSlipAngleRad.HasValue)
            {
                _lastFrontSlipAngle = (float)frame.FrontSlipAngleRad.Value;
                System.Threading.Interlocked.Exchange(ref _lastSlipAngleTicks, Stopwatch.GetTimestamp());
            }

            // The FFB tap's "force feedback should be flowing" hint is set from
            // IsSessionActive in DataUpdate (a continuous tick), not here, so it
            // also goes false when telemetry stops (pause/menu) instead of
            // sticking at its last value.

            // Golden-capture row (dev CAPTURE access code): raw enriched frame
            // + session flag + fresh tap target, written on this thread; the
            // log object is internally locked and no-ops once disposed.
            var cap = _captureLog;
            if (cap != null)
                cap.LogRow(in frame,
                           _telemetrySource?.IsSessionActive ?? false,
                           _ffbTap?.TryGetFreshFfbTarget(_device?.FfbTargetMaxAgeMs ?? 10000));

            if (_audio != null)
                _audio.ThrottleNormalized = (float)frame.Throttle01;

            // Phase 1: effects no longer tick here on the telemetry thread.
            // The enriched frame goes to the engine's resampler; effects tick
            // at a fixed 500 Hz on the producer thread with interpolated /
            // predicted frames (see FrameResampler), which also puts their
            // state updates on the same thread as RenderAdd.
            _engineLoop?.IngestFrame(in frame);

            // Update telemetry-derived inputs to the community variant
            // signature. Latest-valid (not peak): an in-session engine
            // swap that LOWERS the rev ceiling has to be visible, and a
            // peak tracker would silently retain the stock value.
            // Threshold (>100) filters out the "engine off / source
            // hasn't populated yet" zero frames so we don't clobber a
            // known value with a noise dip. Cyl, MaxRpm, and RedlineRpm
            // are tracked independently because games surface different
            // subsets - signature reflects what THIS game gives us.
            //
            // Gated on the session being LIVE: when the game pauses (Forza
            // alt-tab / menu) it can keep streaming with stock specs, which
            // would clobber the on-track tuned MaxRpm and flip the variant
            // signature back to a stale tune. Holding the last live values
            // through a pause keeps editing (e.g. setting a redline while
            // alt-tabbed) pinned to the variant the user was actually driving.
            bool sessionLive = _telemetrySource?.IsSessionActive ?? true;
            // ...and never while offline-editing a car: _activeCarId is frozen to
            // the edit car, but live frames are for the car actually running, so
            // stamping Observed*/signature here would write the running car's
            // telemetry into the frozen edit car's CarFacts. The car-change block
            // already freezes on IsOfflineEditingCar; mirror that here.
            if (EnginePulse != null && sessionLive && !IsOfflineEditingCar)
            {
                if (frame.NumCylinders is int liveCyl && liveCyl >= 1 && liveCyl <= 16)
                    EnginePulse.ObservedCyl = liveCyl;
                // A game can also say a car has NO cylinders, which is an
                // answer ("electric"), not a missing one. Re-resolve on the
                // spot: this moves no part of the variant signature, so the
                // mid-session detector below would never notice it, and the
                // rev limiter reads the electric state off that resolve.
                if (frame.EngineIsElectric == true && !EnginePulse.ObservedIsElectric)
                {
                    EnginePulse.ObservedIsElectric = true;
                    if (!string.IsNullOrEmpty(_activeCarId))
                        ResolveAndApplyCarFactsForActiveCar(_activeCarId, logResolution: true);
                }
                if (frame.MaxRpm > 100)     EnginePulse.ObservedMaxRpm     = frame.MaxRpm;
                // Per-gear redline is excluded from the variant signature (it
                // changes every shift; including it spawns a junk variant per
                // gear). The buzz still uses frame.RedlineRpm directly.
                if (frame.RedlineRpm > 100 && !frame.RedlineRpmPerGear)
                    EnginePulse.ObservedRedlineRpm = frame.RedlineRpm;

                // Mid-session variant-change detection: when the live
                // signature differs from what we last applied for this
                // car, re-run the resolver. This is what makes Forza
                // in-game engine swaps (different MaxRpm at same cyl)
                // auto-pick a different stored variant and what makes
                // first-telemetry-frame fully populate a Scanner row
                // on SimHub-fallback games. Cheap: one string compose
                // + compare per frame; the expensive path (resolver +
                // EnsureVariantForLiveSignature) only fires on change.
                if (!string.IsNullOrEmpty(_activeCarId))
                {
                    string liveSig = ComputeActiveCarVariantSignature(_activeGame, _activeCarId);
                    if (!string.Equals(liveSig, _lastAppliedVariantSignature, StringComparison.Ordinal))
                    {
                        ResolveAndApplyCarFactsForActiveCar(_activeCarId, logResolution: false);
                        // Swap the grip auto-cal learner to this variant: its
                        // tires / downforce, and so its grip ceiling, can differ
                        // from the previous variant's. Flushes the outgoing
                        // variant's learned peak, loads this one (or starts
                        // fresh). Same thread as the learner Tick above.
                        LoadGripCal(_activeGame, _activeCarId, liveSig);
                        // The community cache + consensus are keyed by this
                        // signature; now that it changed (car-change warm-up
                        // or a Forza engine swap), replay/fetch for the new
                        // key so community facts apply panel-closed too.
                        MaybeRefreshCommunityFactsHeadless();
                    }
                }
            }

            // Which preset is live, announced when it changes. Watched here
            // rather than hooked onto every apply path: presets land from the
            // panel, the phone, a game switch and a car switch, and a change
            // detector cannot miss one of them. Rides the same readout channel
            // as the gain controls, so the answer to "did the right preset
            // load" appears on the dash bar and the wheel screen together.
            string livePreset = _activePresetName ?? "";
            if (!string.Equals(livePreset, _lastAnnouncedPreset, StringComparison.Ordinal))
            {
                _lastAnnouncedPreset = livePreset;
                if (livePreset.Length > 0) DashReadout("PRESET", livePreset);
            }

            // Rim rev/shift LEDs. Two sanctioned contexts, both defined by
            // the same rule: LED writes are only SAFE when no game PID is on
            // the wheel's HID++ pipe (an LED write against live PID stalls
            // FFB ~1.5 s at the firmware).
            //   2. Telemetry based FFB (Mode B) on a G PRO: the game is
            //      configured to send nothing and we render force on ep3, so
            //      the HID++ pipe is free. Verified LIVE via the FFB tap
            //      (2 s quiet window), not assumed from the mode: FH6 still
            //      emits PID in some states, and sole-writer must be proven.
            //      Per wheel: G PRO, RS50 and the G923 Xbox all speak the HID++
            //      0x807A level protocol (10-level bar); only the G923 PS uses
            //      the legacy F8-12 report (5-LED strip). G PRO is hardware-
            //      validated; the G923 Xbox 0x807A transport (SHORT commands
            //      padded onto its 20-byte HID++ collection) follows the
            //      documented protocol, pending on-wheel confirmation.
            if (_rpmLeds != null)
            {
                // Wheel LED family by chassis. HID++ 0x807A level channel (10-level
                // bar, WheelLedChannel via _rpmLeds): G PRO + RS50 AND the G923 Xbox
                // (C26D/C26E), which drives the same 0x807A feature, just over its
                // 20-byte HID++ collection since it exposes no 7-byte one. RS50 in
                // G PRO compat mode spoofs the G PRO PID (C272); its native PID
                // (C276) is handled too. Only the G923 PS (C266) uses the legacy
                // F8-12 report (5-LED strip, the F8 path via DriveG923Leds).
                bool levelWheel = WheelIsHidppLevelBar;
                bool g923Wheel  = WheelIsLegacyF8;                                    // G923 PS/PC (legacy F8-12)

                // Fail CLOSED: quiet must be PROVEN by a live capture, never
                // assumed. A null tap, a tap whose USBPcap child never
                // started, or one that died mid-session is blind, and a blind
                // tap returning nothing looks identical to real silence. The
                // tap keeps capturing under Mode B exactly so this probe (and
                // the contention watchdog) stay valid. LEDs are only safe while
                // the game FFB is proven quiet (Mode B owns the wheel); the
                // driver lifts this later.
                var ledTap = _ffbTap;
                // Scalar captures only: a playing classic spring does NOT
                // count as loud here. In spring mode (2) the spring is our
                // INPUT (we render it; only our ep3 stream commands force),
                // and on the F8 wheel (C266) LED writes interleaving with
                // classic FFB is native-game behavior (owner's ACC capture:
                // ~13k f8 12 writes alongside slot traffic).
                // Force from AC itself: a fresh finalFF latch PROVES the game
                // is emitting force, so the bus cannot be quiet no matter
                // what the tap sees (with the shm path supplying, the user
                // has no reason to keep USBPcap healthy, so a blind-but-
                // running tap gets likelier and its "no captures" must not
                // read as silence). Owner-confirmed contention model
                // (2026-08-14): ANY force values on the HID++ endpoint plus
                // an LED/OLED write cuts FFB; our ep3 stream overriding the
                // ep0 force does NOT make those writes safe.
                bool gameFfbQuiet = ledTap != null && ledTap.IsRunning
                            && !ledTap.TryGetFreshFfbTarget(2000).HasValue;
                // Only while actively driving. On pause / menu / replay the
                // session goes inactive: the Mode B force is already zeroed
                // there, and without this the rev bar would freeze on the
                // paused RPM (flashing if you paused near the redline, since
                // the latch stays set). Mirrors the force pause-release.
                //
                // Not the source's raw answer: see HidppSessionActive, which
                // prefers a game's own session state where we have it and
                // otherwise stops a momentary telemetry hiccup from handing the
                // rev bar back to the game mid-corner.
                bool sessionActive = HidppSessionActive();
                if (sessionActive)
                {
                    int nowTick = Environment.TickCount;
                    _sessionLiveMs = nowTick == 0 ? 1 : nowTick;
                }
                // iRacing states it outright, so there is nothing to infer. That
                // matters twice. With the sim's own force feedback off there is
                // no ep0 traffic left to capture, so the tap probe would fail
                // closed and the lights could never come on at all. And it means
                // the rev lights and the screen stop depending on a USB kernel
                // sniffer running during an online race. Still fails closed: no
                // telemetry frame yet means not proven.
                bool ffbQuietProven;
                if (_forceMode == ForceModeIRacing)
                {
                    var irFfbFrame = _irFrame;
                    ffbQuietProven = irFfbFrame != null && !irFfbFrame.GameFfbOn;
                }
                else
                {
                    ffbQuietProven = gameFfbQuiet;
                }
                // The one safety condition both HID++ surfaces share: a force
                // mode armed, the game's FFB proven quiet, session live.
                // MasterMode is the first term, and it has to be checked HERE rather
                // than left to the pipeline teardown. Switching out of full hands the
                // wheel back synchronously but disposes the telemetry source on a
                // background task, so frames keep arriving for a moment afterwards.
                // Without this, the very next frame's level write would re-arm the
                // keepalive AbandonWheel had just stopped, and nothing would stop it
                // a second time: a level pair every second, forever, on the endpoint
                // the game's force feedback shares.
                // CSP bridge at gain 0: the game writes NOTHING to the wheel's
                // HID++ pipe (the pre-gain force rides our ep3 stream instead),
                // so the pipe is free for the screen and rev lights even though
                // the force mode is pass-through (ForceModeOff). ffbQuietProven
                // still gates it: raise the in-game gain and the tap sees force
                // again, the proof drops, and the surfaces fail closed. This is
                // the path the finalFF revert pointed to (gain up kept the pipe
                // busy; gain 0 genuinely frees it).
                // The base rule: a force mode armed (not pass-through), the
                // game's FFB proven quiet, session live. This is what gates us
                // DRIVING the rev lights, and it stays exactly as it was: in
                // Assetto Corsa the force mode is pass-through, so this is
                // false and we never touch the rev bar there. AC drives its
                // own rev lights, and we leave them to it.
                bool hidppFree = MasterMode == TrueforceMasterMode.Normal
                              && _forceMode != ForceModeOff && ffbQuietProven && sessionActive;
                // Is somebody else driving the rev bar right now? Measured off
                // the wire (see ForeignRevBarWriterActive), not assumed from a
                // list of games. Both HID++ surfaces below defer to it: one
                // writer at a time on this pipe, and the game's rev lights
                // outrank our screen, because the bar is a stock wheel feature
                // the game owns and the screen is an opt-in extra of ours.
                bool foreignBar = ForeignRevBarWriterActive();
                // The CSP bridge frees the wheel's HID++ pipe (the game writes
                // nothing to it), so the SCREEN, the rev lights and one-shot
                // pattern changes all become reachable even in AC's
                // pass-through mode, where the base rule above is false.
                //
                // This used to stop at the screen, on the reasoning that AC
                // owns the bar and two writers would fight. That reasoning was
                // right; it just did not need to be a permanent assumption now
                // that the wire can answer it. Where AC still drives the bar
                // foreignBar is true and nothing changes. Where the user has
                // told AC to stop (CSP's g27_lights MODE=DISABLED, which that
                // module documents as the way to hand the lights to an external
                // tool) the bar is genuinely free and we may take it.
                bool cspSupplying = CspBridgeSupplying();
                bool cspPipeFree = MasterMode == TrueforceMasterMode.Normal
                              && cspSupplying && ffbQuietProven && sessionActive;
                // An arcade cabinet running through our publishing build has given
                // the wheel up entirely, which is the whole point of that route: it
                // is what lets the lights and the screen work in games that would
                // otherwise hold the pipe for their force.
                //
                // NOT also gated on sessionActive. On this route that flag is the
                // publisher's frame counter advancing, which tracks whether the
                // game is submitting force right now rather than whether it owns
                // the wheel, so holding the wheel still made the term drop and the
                // lights change behaviour under the driver's hands.
                //
                // And NOT deferring to foreignBar, which it used to. The cabinet's
                // force is intercepted inside the game's own process and reaches
                // us instead of the wheel, so on this route the lights and the
                // screen are ours to write (owner, 2026-09-05). foreignBar is a
                // wire measurement that cannot tell a cabinet's own rev-bar writes
                // from anything else at that feature index, and on the publishing
                // route there is no game writer left for it to be seeing.
                bool arcadePipeFree = ArcadePipeFree();
                bool hidppFreeForLeds   = hidppFree || arcadePipeFree || (cspPipeFree && !foreignBar);
                bool hidppFreeForScreen = arcadePipeFree
                                       || ((hidppFree || cspPipeFree) && !foreignBar);
                bool modeBLeds = (Settings?.ModeBRevLightsEnabled ?? true) && hidppFreeForLeds;
                // EXPERIMENTAL wheel-base OLED, its own opt-in (default off).
                // The 2026-08-28 finding (the screen stalls the game's own
                // rev-light writes) is why hidppFreeForScreen carries the
                // foreignBar term: the CSP bridge frees the pipe of the game's
                // FORCE, which is what the 2026-08-29 re-enable measured, but
                // its LIGHTS are a separate writer and the screen starves them.
                bool modeBOled = MasterMode == TrueforceMasterMode.Normal
                            && (Settings?.ModeBOledEnabled ?? false)
                            && hidppFreeForScreen;
                // Latched for the settings panel, which runs on another
                // thread. TWO gates, because they answer different questions.
                // A preview sweep writes rev-light LEVELS, so it rides the
                // lights rule: where a game still owns the bar and re-zeroes it
                // constantly, a preview flickers against that writer (tester,
                // 2026-08-31), and foreignBar is exactly that condition.
                _oledHidppFree = hidppFreeForScreen;
                _ledsHidppFree = hidppFreeForLeds;
                // The quiet term alone, for one-shot user actions (the rev
                // pattern picker). hidppFree bundles "force mode armed" and
                // "session live", which gate CONTINUOUS driving of the
                // surfaces; a single user-initiated write only needs the pipe
                // itself force-free, and demanding the rest made picks look
                // dead from the garage and the menus.
                _ffbQuietNow = ffbQuietProven;
                // Ownership is logged on change whatever the diagnostic is
                // doing: it is one line per config edit, and it answers "who
                // is driving my lights" without asking for a code first.
                NoteAcLedOwnershipChanges();
                NoteAcCarShiftLights();
                MaintainAcRevLightModule();
                MaybeLogRevLightContention(modeBLeds, modeBOled);

                double pct     = frame.RpmPercent;
                bool   redline = frame.RedlineReached;
                // One-way latch: has this game ever mentioned an engine? A
                // ceiling is enough on its own, since every sim publishes one
                // whether or not the engine is currently turning, and it is the
                // absence of BOTH that says "this title has no revs to draw"
                // (an emulated arcade cabinet sends force feedback and nothing
                // else). 100 rather than 0 so a source that pads the field with
                // a rounding-error zero does not count as an engine.
                if (!_revDataSeen && (frame.MaxRpm > 100 || frame.Rpms > 100))
                {
                    _revDataSeen = true;
                    // Said once per game, because "why are my lights on the audio meter" is
                    // otherwise unanswerable from outside: the rim strip falls back to the no-revs
                    // choice for exactly as long as this is false, and nothing else reports it.
                    SimHub.Logging.Current.Info(
                        $"[TF4ALL] Rev data seen for '{_activeGame}' (rpm {frame.Rpms:0}, ceiling {frame.MaxRpm:0}), "
                        + "so the rev lights take the rim strip back from the no-revs ambient mode.");
                }
                // Does the audio meter get the bar this frame? Decided once
                // here so both wheel families below answer it the same way.
                // Is anything actually being PLAYED? Frames arriving is not the
                // same question, and conflating the two cost a whole evening's
                // testing. The arcade source publishes frames for as long as the
                // cabinet IO block EXISTS, so leaving TeknoParrot open with no
                // game running had the plugin naming a game, running its
                // telemetry source, and answering "a game is feeding us" with a
                // straight face. The no-revs occasion then owned the strip
                // permanently, the idle occasion could never be reached, and the
                // safety gate below was shut because no session was live: dark
                // lights, no game, nothing in the log to say which of the two
                // was to blame.
                //
                // SimHub naming no game AND no source claiming a live session is
                // as close to "nothing is happening" as the plugin can get. The
                // arcade source's own liveness is whether its block is CHANGING,
                // which is a statement about force being submitted right now and
                // not about whether a cabinet is running. A detected arcade game
                // therefore counts as playing on its own (owner, 2026-09-05):
                // holding the wheel still is not leaving the game, and letting it
                // read as "nothing is playing" both flipped the lights under the
                // driver's hands and opened the write gate on a pipe that a
                // running cabinet may still own.
                bool gamePlaying = !string.IsNullOrEmpty(_currentGameName)
                                || SessionRecentlyLive;
                // What takes the strip when the revs cannot: a sweep, the
                // audio meter, or nothing. Decided once here so both wheel
                // families below answer it the same way.
                var ambientMode = ResolveAmbientMode(gamePlaying: gamePlaying);
                bool ambientBar = ambientMode != AmbientLedMode.Off;
                // The ambient gate is the SAFETY half of modeBLeds and not its
                // feature half. Both surfaces need the pipe proven force-free,
                // and neither may write without it. But "Add rev light support
                // to games when possible" is the rev lights' own switch, and
                // bundling it in meant a user who had turned the rev lights off
                // (their game drives them natively) could choose an ambient
                // mode, watch its preview bar move in the panel, and never get
                // a lit LED, with nothing on screen saying which control was in
                // the way. Each feature answers for itself.
                // With nothing being played there is no force anywhere, so the
                // wheel's HID++ pipe is nobody's to cut. That is the same claim
                // DriveAmbientLedsIdle makes from the other side of the fence
                // (it tests for no frames at all rather than for no game), and
                // it has to be made here too: a source that keeps feeding us
                // after its game has gone means the idle driver never runs.
                bool ambientLedGate = hidppFreeForLeds || !gamePlaying;
                if (modeBLeds && !ambientBar && (levelWheel || g923Wheel))
                {
                    // Forza UDP has no RpmPercent or redline flag, so derive
                    // both from raw revs. Fill and flash share ONE reference:
                    // the redline RPM the rev-limiter buzz already fires at
                    // (RevLimiter.EffectiveRedlineRpm, which runs the full
                    // cascade: the per-variant CarFacts redline when known,
                    // else the community/telemetry value, else 0.85 of Forza's
                    // EngineMaxRpm). So the all-LED flash and the buzz go off
                    // together as one "shift now" signal, and a known redline
                    // pins the strip exactly. Fill spans the top window below
                    // that point; the latch has hysteresis so limiter bounce
                    // blinks cleanly. (EffectiveRedlineRpm is written on the
                    // engine thread; this eventual-consistency read is fine for
                    // LEDs, worst case one glitch frame that self-corrects.)
                    int? rl = RevLimiter?.EffectiveRedlineRpm;
                    double full = (rl.HasValue && rl.Value > 100)
                        ? rl.Value
                        // No redline resolved yet (engine off / first frame):
                        // RevLimiter's own 0.85-of-MaxRpm default, so the
                        // fallback still agrees with the buzz.
                        : frame.MaxRpm * 0.85;
                    if (full > 100)
                    {
                        pct = ForzaRevBar(frame.Rpms, full);
                        // Flash on AT the redline, release as soon as you drop
                        // back below it. The 1% dead band only de-bounces
                        // telemetry jitter while holding right at the line;
                        // wider than that and the flash stays stuck on after
                        // you have clearly backed off (a 4% band did that).
                        if (_forzaRedlineLatch) { if (frame.Rpms < full * 0.99) _forzaRedlineLatch = false; }
                        else if (frame.Rpms >= full) _forzaRedlineLatch = true;
                        redline = _forzaRedlineLatch;
                    }
                    else
                    {
                        // No usable rev ceiling from this game (spring-mode
                        // titles may report Rpms with MaxRpm 0). Without this
                        // guard, full=0 makes Rpms >= full latch the redline
                        // flash permanently. Dark bar instead.
                        pct = 0;
                        redline = false;
                        _forzaRedlineLatch = false;
                    }
                }
                else
                {
                    _forzaRedlineLatch = false;
                }

                if (levelWheel)
                {
                    // G PRO / RS50 / G923 Xbox: HID++ 0x807A level channel
                    // Any wheel whose firmware does not answer 0x807A simply
                    // never resolves the channel and the LEDs stay dark (no harm).
                    try
                    {
                        // Car-load edge. In lights-only mode there is no telemetry
                        // source to reach this line, so DataUpdate drives the same
                        // call; the latch inside makes whichever arrives first the
                        // only one that acts.
                        ApplyCarLightsForActiveCar(ffbQuietProven);

                        // Per-car published data, when the user has turned it on
                        // and we hold some for this car. Null curve = today's
                        // behaviour, unchanged. The cascade itself lives in
                        // CarFillCurve: the F8 path below has to reach the same
                        // verdict, and a second copy of it would be a second
                        // opinion about which source wins.
                        _rpmLeds.LevelCurve = CarFillCurve(frame.Gear);

                        // The FLASH deliberately does NOT resolve its own
                        // redline here. It rides `redline`, which upstream takes
                        // from RevLimiter.EffectiveRedlineRpm, so the flash, the
                        // fill onset and the limiter buzz are one "shift now"
                        // signal by construction rather than by three call sites
                        // agreeing. The published per-gear redlines that make the
                        // wheel line up with the sim's own dash are fed INTO that
                        // cascade (RevLimiterEffect.ResolveEffectiveRedline), not
                        // spliced in at this call site: doing it here once made
                        // the lights flash at the car's redline while the wheel
                        // buzzed at ours (owner, 2026-08-24).
                        // Hand a borrowed slot back if the user has selected
                        // something else on the base itself.
                        ReleaseBorrowIfWheelMovedAway();

                        // The audio meter, where this game gives us no revs to
                        // draw or the car is parked and the user asked for it.
                        // Same gate as the rev lights: metering is still a
                        // level write on the pipe the game's force shares, so
                        // it waits on the same tap-proven quiet.
                        if (ambientBar)
                            _rpmLeds.OnAmbientLevel(
                                AmbientLevelFor(ambientMode, _rpmLeds.MirrorSteps), ambientLedGate);
                        else _rpmLeds.OnFrame(pct, frame.Rpms, frame.MaxRpm,
                                              redline, modeBLeds);

                        // Mirror to the dash. Deliberately outside the gate above:
                        // drawing on screen sends nothing to the wheel, so it works
                        // in games where writing an LED would cut the game's force,
                        // and in the ones the plugin disables itself for. OnFrame
                        // decides LastLevel before it consults any of those gates,
                        // so this is the live bar even while the wheel is somebody
                        // else's to write.
                        PublishDashLights(_rpmLeds.LastLevel, redline && !ambientBar, _rpmLeds.MirrorSteps);

                        // Whenever the selection moves, and only while the pipe
                        // is force-free: what is the wheel actually showing? Until
                        // it answers, the mirror draws our own ramp. The gate is
                        // ffbQuietProven rather than the LED gate above, because
                        // this only reads: the narrower gate also demands Mode B
                        // be armed, which would leave the dash stale for anyone
                        // whose game lights its own wheel.
                        SyncDashLightProfile(ffbQuietProven);
                    }
                    catch (Exception ex)
                    {
                        SimHub.Logging.Current.Error("[TF4ALL] RPM-LED telemetry error", ex);
                    }
                }
                else if (g923Wheel)
                {
                    // G923 PS (C266): legacy F8-12 rev bar, 5 LEDs. The G923 Xbox
                    // is NOT here; it takes the HID++ 0x807A path above.
                    //
                    // modeBLeds carries the ffbQuietProven term, and that is
                    // deliberate even though this path does not touch HID++. The
                    // F8 report rides the gamepad/DirectInput collection, which is
                    // the collection PID FFB rides, so a game producing classic
                    // force is driving the pipe we would write levels into. Until
                    // a G923 PS owner has tested that with force flowing, the gate
                    // stays: dark LEDs are a better failure than dead force. See
                    // the header of LegacyLedF8Channel for the full reasoning.
                    //
                    // F8ANY lifts the quiet term for THIS path only, so that
                    // testing it means driving and revving rather than watching a
                    // synthetic sweep. Everything else about the path is unchanged,
                    // so what the tester sees is the real feature.
                    bool f8Gate = (Settings?.ModeBRevLightsEnabled ?? true)
                               && MasterMode == TrueforceMasterMode.Normal
                               && sessionActive
                               && (modeBLeds || (Settings?.F8IgnoreQuietGate ?? false));
                    // The ambient modes feed the same five-step bar, just from
                    // a different number and with no shift flash. Same gate
                    // minus the rev lights' own switch (see ambientLedGate
                    // above); the F8ANY escape hatch still applies, since it is
                    // about this path's quiet term rather than about which
                    // signal is driving it.
                    bool f8AmbientGate = MasterMode == TrueforceMasterMode.Normal
                                      && sessionActive
                                      && (ambientLedGate || (Settings?.F8IgnoreQuietGate ?? false));
                    if (ambientBar)
                        DriveG923Leds(AmbientLevelFor(ambientMode, G923LedCount) / (double)G923LedCount,
                                      false, f8AmbientGate);
                    // The same per-car cascade the level channel installs as its
                    // LevelCurve, asked directly because this path has no
                    // controller to hang one on. Without it a G923 PS owner drove
                    // the plain linear ramp while every other wheel lit at the
                    // car's own switch-on points, which is the whole reason the
                    // dataset is worth fetching.
                    else DriveG923Leds(pct, redline, f8Gate,
                                       CarFillCurve(frame.Gear)?.Invoke(frame.Rpms, G923LedCount));
                    // Not mirrored: this path never builds a level or a color
                    // profile, so there is nothing for the dash to follow and it
                    // should draw its own strip instead of a frozen one.
                    ClearDashLights();
                }
                else
                {
                    // A wheel we do not light. Same reasoning: better the dash's
                    // own strip than the last one we happened to publish.
                    ClearDashLights();
                }

                // Wheel-base Dynamic OLED (feature 0x8130), G PRO / RS50 only.
                // Lives inside this block because it needs the same tap probe
                // the LEDs just computed; _oledDash is created and nulled in
                // lockstep with _rpmLeds, so the outer null check covers both.
                // A wheel without the screen never resolves the feature and
                // this stays inert.
                if (_oledDash != null)
                {
                    try
                    {
                        var ctx = new OledFrameContext
                        {
                            GateOpen = modeBOled,
                            Screen   = Settings?.OledScreen ?? OledScreen.SpeedOverGear,
                            UseMph   = Settings?.OledUseMph ?? false,
                            CustomLayout = Settings?.OledCustomLayout ?? OledLayoutKind.FourCenter,
                            CustomSlots  = Settings?.OledCustomSlots?.ToArray(),
                            CustomTexts  = Settings?.OledCustomTexts?.ToArray(),
                            // Same evidence the dash's box picker greys "Lap
                            // times" out with: the curated per-game gaps plus
                            // what this title has been driven long enough to
                            // never have reported.
                            DeltaSupported = GameReportsLapDelta,
                            GameFfbContending = ModeBContentionDetected,
                            // Empty in every game but iRacing, and empty there
                            // too until the count actually moves.
                            IncidentFlash = Settings?.DashIncidentsEnabled == false
                                ? "" : IRacingIncidentFlashShort,
                            Position   = _shPosition,
                            // An emulated cabinet tells SimHub nothing, so these read zero there
                            // and the lap line goes blank mid-race. The memory map has both, so
                            // prefer it when it is live and fall back to SimHub everywhere else.
                            CurrentLap = ArcadeLapOrDefault(_shCurrentLap),
                            TotalLaps  = ArcadeTotalLapsOrDefault(_shTotalLaps),
                            LastLapMs  = ArcadeLastLapOrDefault(_shLastLapMs),
                            BestLapMs  = ArcadeBestLapOrDefault(_shBestLapMs),
                            TechniqueText = ArcadeTechniqueText(),
                            TechniqueIsImpact = _arcadeTechniqueIsImpact,
                            CountdownText      = ArcadeCountdownText(),
                            ResultText         = ArcadeResultText(),
                            BetweenRacesTop    = ArcadeBetweenRacesTop(),
                            BetweenRacesBottom = ArcadeBetweenRacesBottom(),
                            // No captions before a card is swiped: DRIVER over a blank row asserts
                            // something we do not know.
                            BetweenRacesTopLabel    = ArcadeHasCard() ? "DRIVER" : "",
                            BetweenRacesBottomLabel = ArcadeHasCard() ? "CAR" : "",
                            GreetingEnabled = Settings?.OledGreetingEnabled != false,
                            GreetingText    = Settings?.OledGreetingText,
                            WriteIntervalMs = Settings?.OledWriteIntervalMs ?? 100,
                            // The frame wins when its source reports pedals,
                            // and SimHub's copy is the fallback. That ordering
                            // is what makes these work in a Forza setup pointed
                            // straight at the plugin with forwarding off, where
                            // SimHub's own numbers are all zero.
                            Brake01     = frame.Brake01     ?? _shBrake01,
                            Clutch01    = frame.Clutch01    ?? _shClutch01,
                            Handbrake01 = frame.Handbrake01 ?? _shHandbrake01,
                            // Ours: the force actually written to the wheel, and
                            // the texture riding the Trueforce stream. Magnitude
                            // only, and de-scaled the same way the dash scope
                            // does it so a reduced output scale still reads full
                            // when the wheel is actually railed.
                            FfbTorque01      = LiveFfbMagnitude01(),
                            TrueforceLevel01 = LiveTrueforceLevel01(),
                            ShiftFlashEnabled = Settings?.OledShiftFlash != false,
                            FlashStyle = Settings?.OledShiftFlashStyle ?? OledFlashStyle.CenteredGear,
                            LapResultEnabled  = Settings?.OledLapResult != false,
                        };
                        // A finished lap is the moment its TIME lands, not the
                        // moment the counter ticks: the counter moves at the
                        // line and the time can arrive a frame later, and it is
                        // the time we are about to show.
                        if (ctx.LastLapMs != _oledPrevLastLapMs)
                        {
                            _oledPrevLastLapMs = ctx.LastLapMs;
                            // Back to zero is a session reset, not a lap.
                            ctx.LapJustCompleted = ctx.LastLapMs > 0;
                        }
                        // Only pay for the delta lookup when the panel is live
                        // and the game actually has one to give. Also needed on
                        // the lap-result frame, whatever screen is selected.
                        if (modeBOled && ctx.DeltaSupported)
                            ctx.LapDelta = TryGetLiveLapDelta(PluginManager);
                        // A bound control that just changed a number takes the
                        // screen over for its readout window, same signal and
                        // same expiry as the dash's readout bar.
                        if (modeBOled && TryGetActiveReadout(out string rl, out string rv))
                        { ctx.ReadoutLabel = rl; ctx.ReadoutValue = rv; }

                        _oledDash.OnFrame(frame, ctx);
                    }
                    catch (Exception ex)
                    {
                        SimHub.Logging.Current.Error("[TF4ALL] OLED telemetry error", ex);
                    }
                }
            }
        }

        // ---- G923 PS rev LEDs (legacy F8-12 path) -------------------------
        // The G923 PlayStation variant (C266) drives its rev strip with the
        // legacy Logitech F8-12 report on the gamepad collection
        // (LegacyLedF8Channel), NOT HID++ 0x807A. It has 5 shift LEDs (bit 0
        // first green .. bit 4 last red), per the Linux hid-lg4ff driver,
        // confirmed identical on the G29 and G923 (Vcha2268/ForzaG29Leds). The
        // F8 byte is a (1<<n)-1 bitmask. The G923 Xbox (C26D/C26E) uses HID++
        // 0x807A instead (see the level path above); routing it here would open
        // an input-only collection and every write would be rejected.
        private const int G923LedCount = 5;
        private int _g923OpenState;   // 0 idle, 1 opening, 2 open, 3 failed

        /// <param name="carLevel">Whole steps the active car's own data asks
        /// for, or null to fill from <paramref name="pct"/> on the plain ramp.
        /// Takes precedence exactly as RpmLedController's LevelCurve does, and
        /// for the same reason: a switch-on threshold is a hard edge, so there is
        /// nothing here to interpolate.</param>
        private void DriveG923Leds(double pct, bool redline, bool gateOpen, int? carLevel = null)
        {
            var f8 = _f8Leds;
            if (!gateOpen)
            {
                try { f8?.ClearLevel(); } catch { }
                return;
            }
            // Lazy background open, one-shot (Open enumerates + opens a HID
            // stream; keep it off the telemetry thread). Shares the _f8Leds
            // instance with the F8SWEEP test code; production SetLevel no-ops
            // while a sweep owns the channel.
            if (f8 == null)
            {
                f8 = new TrueforceForAll.Core.LegacyLedF8Channel(
                    msg => SimHub.Logging.Current.Info(msg));
                _f8Leds = f8;
            }
            if (_g923OpenState == 0)
            {
                _g923OpenState = 1;
                var chan = f8;
                System.Threading.Tasks.Task.Run(() =>
                {
                    bool ok = false;
                    try { ok = chan.Open(); } catch { }
                    _g923OpenState = ok ? 2 : 3;
                });
                return;
            }
            if (_g923OpenState != 2) return;

            int level = redline
                ? ((((DateTime.UtcNow.Ticks / TimeSpan.TicksPerMillisecond) / 185L) & 1L) == 0L
                       ? G923LedCount : 0)                              // ~2.7 Hz shift flash
                : carLevel.HasValue
                ? (carLevel.Value < 0 ? 0
                   : carLevel.Value > G923LedCount ? G923LedCount : carLevel.Value)
                : (int)Math.Floor(pct * G923LedCount + 0.5);
            try { f8.SetLevel(level, G923LedCount); } catch { }
        }

        /// <summary>Telemetry feed went stale (the active source stopped
        /// emitting: game closed, crashed, or its physics page froze). Hand
        /// the settle to the engine loop: the resampler holds-newest through
        /// a hard stall, so both the resampler reset and the OnTelemetryStall
        /// fan-out must execute ON the engine thread at a tick boundary.
        /// Settling from this (DataUpdate) thread can interleave with an
        /// in-flight 500 Hz effect tick that already sampled the held frame,
        /// and an OnTelemetry(heldFrame) landing after the silencing
        /// re-latches the sustained amplitude with no recovery (the ring is
        /// empty afterwards; the shipped AC engine-pulse stall fix would be
        /// intermittently undone). The next engine tick lands within ~1 ms,
        /// well inside the 500 ms stall window.</summary>
        private void SettleEffectsOnStall()
        {
            _engineLoop?.RequestStallSettle();
            SimHub.Logging.Current.Info("[TF4ALL] Telemetry stalled; settling sustained effects on the engine tick.");
        }

        /// <summary>Hand the rev bar and the base screen back after the feed has
        /// stopped for good, not merely hiccuped.
        ///
        /// Both are driven from DispatchFrame, not the engine tick, so when
        /// frames stop entirely (game exit/crash/frozen page) OnFrame never runs
        /// again and the bar would freeze on its last bucket while the panel held
        /// a stale speed. That is what this releases. Idempotent: ForceOff no-ops
        /// once cleared and yields to an active test sweep.
        ///
        /// This used to ride the 500 ms effect-settle window, which was too eager
        /// by far. A sustained effect must fall silent quickly because it is
        /// audible, but a display is not improved by being right 500 ms sooner,
        /// and the game keeps writing the rev bar throughout: every hiccup handed
        /// it back and the strip visibly flicked between our pattern and the
        /// game's. The owner's RaceRoom log has eleven of those in sixteen
        /// minutes. So the surfaces get their own, longer window, matched to the
        /// hold in HidppSessionActive so the two cannot disagree.</summary>
        private void ReleaseHidppSurfacesOnStall()
        {
            _rpmLeds?.ForceOff();
            _oledDash?.ForceOff();
            SimHub.Logging.Current.Info(
                "[TF4ALL] Telemetry stopped; handing the rev lights and the base screen back.");
        }

        /// <summary>Toggle the aligned telemetry+FFB capture log (dev CAPTURE
        /// access code). On: opens a timestamped v2 golden-capture CSV under
        /// Documents\TrueforceForAll and DispatchFrame logs one row per telemetry
        /// frame (full frame incl. per-tire quads) with the game's tapped FFB
        /// target, the replay-harness fixture format, which doubles as the
        /// offline FFB-remodeling dataset. Off: closes the file. Returns a status
        /// line for the access-code UI. Pure observation, no force is produced,
        /// safe to run while driving.</summary>
        public string ToggleFfbCapture()
        {
            var existing = _captureLog;
            if (existing != null)
            {
                _captureLog = null;   // DispatchFrame stops logging on its next frame
                long rows = existing.RowsWritten;
                string donePath = existing.Path;
                try { existing.Dispose(); } catch { }
                return $"FFB capture stopped: {rows} rows -> {donePath}";
            }

            try
            {
                string dir = System.IO.Path.Combine(
                    Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),
                    "TrueforceForAll");
                string path = System.IO.Path.Combine(dir,
                    "ffb_capture_" + DateTime.Now.ToString("yyyyMMdd_HHmmss") + ".csv");
                _captureLog = new GoldenCaptureLog(path,
                    _telemetrySource?.Name ?? "unknown",
                    _currentGameName ?? "unknown",
                    m => SimHub.Logging.Current.Info("[TF4ALL] " + m));
                return $"FFB capture (v2 golden) started -> {path}  (drive, then type CAPTURE again to stop).";
            }
            catch (Exception ex)
            {
                return "FFB capture failed to start: " + ex.Message;
            }
        }

        /// <summary>Stamp the high-rate FFB trace (no-op when not armed). Called
        /// from the provider thread with the three chain stages; reads steer and
        /// the physical wheel position for phase analysis.</summary>
        private void TraceFfb(short? rawTap, short? afterSpring, short? finalOut)
        {
            var trace = _ffbTrace;
            if (trace == null) return;
            var sr = _steeringReader;
            float phys = (sr != null && sr.LastUpdateTicks != 0) ? sr.SteerNorm : float.NaN;
            // The condition renderer's inputs, so a ringing damper can be read
            // back to its cause: the reader's own velocity, the estimator's
            // filtered velocity that the damper actually multiplies, and the
            // force the renderer added. NaN where a source is not live, which
            // the CSV writes as a blank cell.
            var wheel = _wheelMotion;
            float diVel = wheel != null && wheel.IsRunning
                ? (float)wheel.Velocity : float.NaN;
            float estVel = _hidppMotion.HasState
                ? (float)_hidppMotion.Velocity : float.NaN;
            trace.Record(
                rawTap.HasValue ? (int?)rawTap.Value : null,
                afterSpring.HasValue ? (int?)afterSpring.Value : null,
                finalOut.HasValue ? (int?)finalOut.Value : null,
                _lastSteerNorm, phys, _steerVel, _lastSpeedKmh,
                diVel, estVel, _lastConditionTerm);
        }

        /// <summary>Whether the FFB trace is recording. Drives the bench
        /// button's label, which is the only way to tell from the UI.</summary>
        public bool FfbTraceRunning => _ffbTrace != null;

        /// <summary>Toggle the high-rate FFB signal-chain trace (TRACE access
        /// code). On: starts recording every provider tick into a ring buffer
        /// (~30 s window). Off: dumps the captured window to a CSV under
        /// Documents\TrueforceForAll for offline analysis of oscillations.
        /// Returns a status line for the access-code UI.</summary>
        public string ToggleFfbTrace()
        {
            var existing = _ffbTrace;
            if (existing != null)
            {
                _ffbTrace = null;   // provider stops recording on its next tick
                try
                {
                    string dir = System.IO.Path.Combine(
                        Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),
                        "TrueforceForAll");
                    string path = System.IO.Path.Combine(dir,
                        "ffb_trace_" + DateTime.Now.ToString("yyyyMMdd_HHmmss") + ".csv");
                    int rows = existing.Dump(path);
                    return $"FFB trace stopped: {rows} samples -> {path}";
                }
                catch (Exception ex)
                {
                    return "FFB trace failed to write: " + ex.Message;
                }
            }

            // ~30 s at the 1 kHz provider cap (32768 pow2 slots); the ring just
            // keeps the most recent window if the trace runs longer.
            _ffbTrace = new FfbTrace(32768);
            return "FFB trace started (recording every FFB tick). Reproduce the issue, then type TRACE again to save the CSV.";
        }

        // TRACE armed during a game-close repro: the interesting window is
        // the seconds AFTER the captured process dies (the close pull), so
        // dump the ring automatically 8 s later instead of making the user
        // race the 30 s window by hand. No-op unless the trace is armed;
        // a manual TRACE-off (or a second exit) in the meantime wins.
        private void MaybeAutoDumpFfbTraceOnGameExit()
        {
            var trace = _ffbTrace;
            if (trace == null) return;
            System.Threading.Tasks.Task.Run(async () =>
            {
                try
                {
                    await System.Threading.Tasks.Task.Delay(8000).ConfigureAwait(false);
                    if (!ReferenceEquals(_ffbTrace, trace)) return;
                    _ffbTrace = null;
                    string dir = System.IO.Path.Combine(
                        Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),
                        "TrueforceForAll");
                    string path = System.IO.Path.Combine(dir,
                        "ffb_trace_gameclose_" + DateTime.Now.ToString("yyyyMMdd_HHmmss") + ".csv");
                    int rows = trace.Dump(path);
                    SimHub.Logging.Current.Info(
                        $"[TF4ALL] FFB trace auto-dumped on game close: {rows} samples -> {path}");
                }
                catch (Exception ex)
                {
                    SimHub.Logging.Current.Warn("[TF4ALL] FFB trace auto-dump failed: " + ex.Message);
                }
            });
        }

        // ---------- Mode B: full force synthesis from telemetry ----------
        // The game contributes NOTHING in this mode (run the game with its own
        // FFB off: it then sends no FFB and no stream, and we are the wheel's
        // only writer). Force = SatForceModel over slip-angle-derived
        // utilization, with a stall ramp so telemetry loss decays the force
        // instead of holding it. Toggled per game from the Telemetry Based FFB
        // tab (ApplyModeBFromSettings); tuned from that tab's sliders and the
        // surviving Mode B access codes (see SetModeBParam).
        // Which pipeline currently AUTHORS wheel torque. Anything non-zero
        // means "the plugin is the sole writer": that is the contract the
        // rev-light / OLED gate, GameFfbExpected suppression, the tap's
        // send-activity probe and the spring-arming lockout all read, and it
        // must hold for every mode added here. Only the stages that are
        // specific to one pipeline test a particular value.
        // Kept a plain int (not an enum) because the 1 kHz FFB thread reads it
        // every pass and volatile int is the cheapest correct read.
        private const int ForceModeOff     = 0;   // game FFB passes through
        private const int ForceModeModeB   = 1;   // Forza: force SYNTHESIZED from slip telemetry
        private const int ForceModeSpring  = 2;   // Farming Sim: classic PID spring rendered at the wheel
        private const int ForceModeIRacing = 3;   // iRacing: the sim's OWN torque reshaped, not synthesized
        private volatile int _forceMode;
        private readonly SatForceModel _satModel = new SatForceModel { DropFloor = 0.50 };   // pre-Init placeholder; ApplyModeBFromSettings owns the live value
        private float _pModeBSign    = 1f;     // ModeBSign: flips SAT direction if Forza's slip sign is inverted vs the wheel
        private float _pModeBPeakU   = 1.0f;   // ModeBPeakUtil (manual grip limit): combined-slip value treated as the grip limit (u = combined / peak)
        private float _pModeBEmaMs   = 25f;    // ModeBEmaMs: input smoothing time constant (raise to calm a noisy slip signal)
        private float _pModeBDirSoft = 0.12f;  // BDIRK: dir-blend center softness (0 = linear; kills center buzz/ring)
        // Mode B damping + centering: their OWN gains, used by the
        // damper/center stages in MaybeReshapeFfb only while Mode B is
        // active. Centering is speed-scaled by the model's trail ramp so a
        // parked wheel isn't spring-loaded.
        private float _pModeBDamperGain = 0.15f;   // "Damping" slider
        private float _pModeBLockRecoverMs = 130f; // "Lockup recovery" slider: slow re-open tau for the lockup gate / friction circle
        private float _pModeBLockupPoint = 0.8f;   // BLOCKPT: |slip ratio| = fully spent (gate full point + circle reference); higher = lightens deeper into braking
        private float _pModeBCenterGain = 0.10f;   // "Centering" slider
        // Minimum-force floor ("Min force" slider): the smallest force
        // the wheel actually renders. Belt-reduction motors (G923 class) eat
        // faint torques as internal friction, so the model's light states
        // (drop floor, trail ramp, recovery fades) read as DEAD instead of
        // light; the remap (ModeBComposer.MinForceRemap) compresses 0..1 into
        // floor..1 with a true zero preserved. 0 = off (the shipped default;
        // wheels that already render faint detail need none).
        private float _pModeBMinForce = 0f;
        // Per-axle feel terms (ModeBComposer): cornering weight from lateral
        // g, counter torque from rear utilization excess over the front.
        private float _pModeBLatGain     = 0.6f;   // "Cornering weight" slider
        // Reversal softening (drift-catch snap, issue #38's lateral twin): fade
        // the composed force while a slide collapses toward center, scaled by how
        // fast, so the full-scale sign flip stops snapping and the ring loses loop
        // gain. Default OFF (A/B feel toggle); strength is its own slider.
        private volatile bool _mbReversalDampOn;   // "Reversal damping" feel toggle
        private float _pModeBReversalGain = 0.4f;  // "Reversal damping strength" slider (owner 2026-07-25 baseline)
        // Trail spring (drift countersteer settle): the direction ramp saturates
        // at ~1.7deg of slip angle, so during a slide the force is a constant shove
        // with no proportional restoring and the wheel slews to the lock instead of
        // settling into a countersteer like real pneumatic trail. Widen the ramp
        // during a slide (gated on rear breakaway) so the force eases off as the
        // front realigns = a stable equilibrium. Grip driving keeps the narrow
        // window. Default OFF (A/B feel toggle); range is its own slider.
        // Phase lead (anticipation): the synthesized SAT closes a lagged telemetry
        // loop (wheel -> 60Hz telemetry -> force -> wheel), so the restoring spring
        // rings near its target instead of settling like real physics-computed FFB.
        // Extrapolate the slip angle feeding dir forward by its rate so the force
        // anticipates where the wheel is going and the loop lag is recovered.
        // Default OFF (A/B feel toggle); lead time is its own slider.
        private volatile bool _mbPhaseLeadOn;        // "Anticipation" feel toggle
        private float _pModeBPhaseLeadMs = 40f;      // "Lead" slider: prediction horizon in ms
        // Direct centering (PD spring): the centering term springs on the
        // wheel's OWN position from the HID steering reader (~report rate,
        // minimal lag) instead of the game's 60 Hz steer report, plus a
        // look-ahead term on the band-limited wheel velocity so the spring
        // aims at where the wheel is HEADED. A spring on a lagged position is
        // an oscillator (the issue #38 family); springing on the fresh
        // position with a velocity lead gives the classic PD shape whose
        // damping scales with the spring gain, so the centering cannot ring
        // however the sliders are set. Falls back to the telemetry steer when
        // the reader is absent or stale. Default OFF (A/B feel toggle);
        // toggle off = the legacy path bit-for-bit.
        private volatile bool _mbCenterPdOn;         // MBCPD / "Direct centering" feel toggle
        private float _pModeBCenterLeadMs = 30f;     // "Look-ahead" slider: velocity lead in ms
        // Slew-limited centering position (PD path only), FFB-thread-only.
        // The spring's position source can switch between the HID reader and
        // the game steer when the reader crosses the 500 ms staleness
        // boundary (G HUB grabbing the device, USB hiccup); the two disagree
        // by the telemetry lag during wheel motion, so an unfiltered switch
        // pops the spring force in one tick. A per-tick slew cap ~2x the
        // fastest real wheel swing passes genuine motion untouched and
        // smears a source step over ~15 ms.
        private float _mbCenterSteerPrev;
        // Centering slide-duck: centering pulls toward STRAIGHT, but during a slide
        // the wheel's stable home is the COUNTERSTEER angle, so centering fights the
        // trail spring. Ease centering out on the same rear-breakaway gate the trail
        // spring uses, so it stays for grip driving and gets out of the way in a
        // slide. Default OFF (A/B feel toggle); duck amount is its own slider.
        private volatile float _lastSurgeAccel;    // m/s², cached in DispatchFrame
        private volatile float _lastSwayAccel;     // m/s² lateral, cached in DispatchFrame
        // Suspension-load feel: front suspension compression over its learned
        // ride height, the live front-load ratio (1.0 = static, >1 = loaded).
        private float _mbSuspBaseline;
        private volatile float _lastFrontSuspRatio = 1f;
        private volatile bool _mbSuspLoadOn;
        // Grip utilization source: the game's own per-tire combined slip
        // (front pair), NOT slip angle. Slip angle correlates with steering
        // input — a slip-angle threshold makes "grip" break at a fixed wheel
        // angle regardless of actual tire state (first wheel test caught
        // this). Combined slip is Forza's tire model's own limit metric
        // (~1.0 = at the limit, load/surface/speed baked in); slip angle
        // keeps exactly one job here: the force DIRECTION.
        private volatile float _lastFrontCombined;
        // Worst (most negative) front-pair signed slip ratio, cached for the FFB
        // thread's braking-lockup gate (issue #38). 0 on scalar/quad-less sources
        // leaves the gate open.
        /// <summary>Latest Mode B grip utilization (0 = free, 1 = at the
        /// limit). Display only: the dash friction circle reads it.</summary>
        internal float ModeBUtilization => _mbLastUtil;
        private volatile float _mbLastUtil;

        private volatile float _lastFrontSlipRatio;
        // Worst front-pair |slip ratio| for the friction-circle law (covers
        // wheelspin as well as lockup). 0 on scalar sources = full lateral share.
        private volatile float _lastFrontSlipRatioAbs;
        // Friction-circle A/B toggle (ModeBFrictionCircle; replaces the lockup
        // gate's multiplier when on).
        private volatile bool _mbFrictionCircleOn;
        // Latest front slip angle (rad) cached from DispatchFrame for the FFB
        // thread. float (32-bit) so the read is atomic even on 32-bit SimHub;
        // the Stopwatch-tick stamp is Mode B's telemetry-freshness gate (the
        // stall ramp in ComputeModeBForce ages against it).
        private volatile float _lastFrontSlipAngle;
        private long _lastSlipAngleTicks;
        // FFB-thread state (1 kHz): defensive input EMAs + stall ramp.
        private float _mbSlipEma;      // signed slip angle (direction only)
        private float _mbPrevSlipEma;  // previous smoothed slip angle, for the reversal-rate derivative
        private float _mbSlipRateEma;  // smoothed slip-angle rate (rad/s), reversal softening
        private float _mbGripEma;      // front combined slip (magnitude)
        // Diagnostics only (ModeB.* properties). Written on the FFB provider
        // thread, read on SimHub's property thread: a stale read by a tick is
        // harmless for a readout, and 32-bit aligned float reads cannot tear.
        private float _mbLockRatioEma; // smoothed front slip ratio for the lockup gate
        private float _mbCircleRatioEma; // smoothed front |slip ratio| for the friction circle
        private float _mbRamp;
        private long  _mbPrevTicks;

        /// <summary>True if the user has opted Mode B in for the active game
        /// (per-game toggle; a missing key = off) AND that game has enough
        /// telemetry to support it (IsModeBCapableGame).</summary>
        public bool ModeBEnabledForActiveGame
        {
            get
            {
                var g = _activeGame;
                return !string.IsNullOrEmpty(g)
                    && IsTelemetryFfbCapableGame(g)
                    && Settings?.ModeBGameEnabled != null
                    && Settings.ModeBGameEnabled.TryGetValue(g, out bool v) && v;
            }
        }

        /// <summary>True if the active game supports Telemetry Based FFB at all
        /// (drives whether the tab's toggle is enabled). Empty in menus.
        /// Covers both pipelines: Forza synthesis and iRacing reshape.</summary>
        public bool ActiveGameSupportsModeB => IsTelemetryFfbCapableGame(_activeGame);

        /// <summary>True while the active game's Telemetry Based FFB is a
        /// reshape (iRacing, or RaceRoom on the R3EFFB route) rather than Forza
        /// synthesis. Surfaces that show tuning controls use this to hide the
        /// slip-model sliders, which do nothing on the reshape path.</summary>
        public bool ActiveGameIsReshapeGame => IsReshapeGame(_activeGame);

        /// <summary>True while RaceRoom is the active game, whatever the route.
        /// The FFB tab uses this to keep the take-over checkbox present for
        /// RaceRoom even on the tap route, so it is the one A/B switch for the
        /// R3EFFB shared-memory route.</summary>
        public bool ActiveGameIsR3E => IsR3EGame(_activeGame);

        /// <summary>True while Le Mans Ultimate is the active game, whatever
        /// the route, for the same reason as ActiveGameIsR3E.</summary>
        public bool ActiveGameIsLmu => IsLmuGame(_activeGame);

        /// <summary>False in the games where the parked-car spring is skipped
        /// outright, so a surface can hide the control rather than offer
        /// something that will do nothing. ApplyStationarySpring reads this, and
        /// so does the FFB tab, which is the point: the two used to state the
        /// rule separately and had already drifted.
        ///
        /// iRacing solves its own self-aligning torque and already weights a
        /// parked car, which is the whole job the spring does elsewhere. Arcade
        /// cabinets publish force and no physics at all, so speed reads zero
        /// forever: the spring would believe the car is permanently parked and
        /// centre against the cabinet for the entire session.
        ///
        /// RaceRoom is not hidden, although it shares iRacing's reshape route:
        /// on the USB tap route ApplyStationarySpring renders the spring, and
        /// with the takeover armed MaybeReshapeFfb renders its own term in the
        /// reshape's frame. An earlier note here claimed the upstream spring
        /// was "reshaped along with the game's own force". It was not:
        /// MaybeReshapeFfb assigns ComputeIRacingForce() over the incoming
        /// target and never reads it, so anything added upstream was dropped
        /// (verified 2026-09-12), which is why the reshape now has its own.
        ///
        /// The Forza exclusion is not here either. That one is a session state
        /// rather than a property of the game, and it already says so through
        /// the unsupported badge instead of vanishing.</summary>
        /// <summary>The section is not shown where the spring can do nothing:
        /// iRacing and the arcade cabinets (ruled out by the game), a game it is
        /// not offered in (no SPRING unlock), and Forza on the capture route.
        /// It stays, with a badge, only where a setting the user can flip would
        /// bring it to life: RaceRoom's handover with the friction off (owner,
        /// 2026-09-19: "if it is inert it should not be showing").</summary>
        public bool ActiveGameHidesStationarySpring
            => string.Equals(_activeGame, "IRacing", StringComparison.Ordinal)
               || ActiveGameIsArcade
               || IsSpringModeGame(_activeGame)          // spring mode assigns over the chain; ours never reaches the wheel
               || StationarySpringLockedHere
               || !ActiveSourceSupportsStationarySpring;

        /// <summary>True while the device is actually bypassing FfbScale and
        /// FfbInvertSign, which it does under the armed reshape and nowhere
        /// else. The FFB tab hides those two controls on this rather than on
        /// "the active game is a reshape game": the reshape can be SUPPORTED
        /// and switched off, and with takeover off the tapped force runs
        /// through both corrections as usual. Hiding on the game took them away
        /// from a driver who still needed them.</summary>
        public bool TapCorrectionsBypassed => _forceMode == ForceModeIRacing;

        /// <summary>True where the Invert control cannot do anything, so a
        /// surface can hide it. On an arcade cabinet the force is authored rather
        /// than tapped and the device skips the inversion, which leaves the
        /// checkbox showing a state it no longer has any effect on.</summary>
        public bool InvertIsDead => TapCorrectionsBypassed || ActiveGameIsArcade;

        // ONE answer for the force path and the FFB tab. They used to ask two
        // different questions (this one, and ActiveSourceSupportsStationarySpring
        // for the badge), so iRacing had its spring skipped with no badge.
        //
        // A property of the GAME only. The route decides which stage renders
        // the spring, not whether it exists: ApplyStationarySpring on the tap
        // route, and the reshape's own term in MaybeReshapeFfb while the
        // takeover is armed (the reshape assigns over its input, so a spring
        // added upstream never reached the wheel; 2026-09-12).
        public bool ActiveGameAllowsStationarySpring
            => !string.Equals(_activeGame, "IRacing", StringComparison.Ordinal)
               && !ActiveGameIsArcade;

        /// <summary>True where the spring is switched off for this version:
        /// outside Assetto Corsa, RaceRoom, Le Mans Ultimate and Forza with the SPRING code not entered. Kept apart
        /// from "allows" because the tab must DISABLE the checkbox here rather
        /// than dim it. A tick wrote the game's entry and then read back the
        /// gated value, so the box unticked itself and the sliders vanished: a
        /// control that silently refuses (rig, 2026-09-12).</summary>
        public bool StationarySpringLockedHere
            => !StationarySpringShipsIn(_activeGame)
               && !(Settings?.StationarySpringUnlocked ?? false);

        /// <summary>Why the spring section is inert for the active game, in the
        /// words the badge shows, or null when it is live. Ordered so the reason
        /// the user can act on comes last: unlocking does nothing if the route
        /// would discard the spring anyway.</summary>
        public string StationarySpringInertReason
        {
            get
            {
                if (!ActiveSourceSupportsStationarySpring) return "not used in Forza on the capture route";
                if (ActiveGameIsArcade) return "not used on an arcade cabinet";
                if (string.Equals(_activeGame, "IRacing", StringComparison.Ordinal)) return "not used in iRacing";
                if (StationarySpringLockedHere) return "off outside Assetto Corsa, RaceRoom, Le Mans Ultimate and Forza in this version";
                if (_forceMode == ForceModeIRacing && IsSharedMemoryTakeoverGame(_activeGame)
                    && !((Settings?.R3EStationaryDamper ?? false) && (Settings?.R3EStationaryDamperStrength ?? 0.0) > 0.0001))
                    return "needs the stationary friction on";
                return null;
            }
        }

        /// <summary>True when the RaceRoom shared-memory reshape (R3EFFB) is the
        /// active route, so its stationary-friction tuning applies. Drives the
        /// FFB tab's stationary-friction controls (shown only for RaceRoom on the
        /// R3EFFB route, since that path replaces the game force that carried it).</summary>
        public bool R3EStationaryDamperApplies
            => SharedMemoryTakeoverOn(_activeGame)   // RaceRoom or Le Mans Ultimate handed over
               || (IsForzaGameName(_activeGame) && ModeBEnabledForActiveGame)
               || IsSpringModeGame(_activeGame);   // spring mode is how Farming Simulator works

        /// <summary>True while a spring-mode game (Farming Simulator) is the
        /// active game. Deliberately not folded into ActiveGameSupportsModeB:
        /// FS runs the spring pipeline with its own tunable set, so surfaces
        /// that key off this (desktop panels, the dash Tele-FFB screen) show
        /// the FS controls instead of the Forza recipe.</summary>
        public bool ActiveGameIsSpringGame => _activeGame != null
            && _activeGame.StartsWith("FarmingSimulator", StringComparison.Ordinal);

        /// <summary>Toggle Mode B for the active game (the tab checkbox).
        /// Persists the per-game flag and re-arms. No-op in menus / unsupported
        /// games.</summary>
        public void SetModeBEnabledForActiveGame(bool on)
        {
            var g = _activeGame;
            if (Settings == null || string.IsNullOrEmpty(g) || !IsTelemetryFfbCapableGame(g)) return;
            if (Settings.ModeBGameEnabled == null)
                Settings.ModeBGameEnabled = new System.Collections.Generic.Dictionary<string, bool>();
            Settings.ModeBGameEnabled[g] = on;
            ApplyModeBFromSettings();
            PersistSettings();
        }

        /// <summary>Push the persisted Mode B settings into the live model and
        /// (re)compute whether Mode B is armed: opted in for THIS game (the
        /// per-game toggle) AND the game is Mode B capable (IsModeBCapableGame).
        /// Called at Init, on game change, and from the settings UI; access
        /// codes remain the raw dev override on top.</summary>
        public void ApplyModeBFromSettings(bool save = false)
        {
            var s = Settings;
            if (s == null) return;
            _satModel.SatGain   = s.ModeBSatGain;
            _satModel.RiseGamma = s.ModeBRiseGamma;
            _satModel.DropFloor = s.ModeBDropFloor;
            _pModeBPeakU   = s.ModeBPeakUtil;
            _pModeBEmaMs   = s.ModeBEmaMs;
            _pModeBSign    = s.ModeBSign < 0 ? -1f : 1f;
            _pModeBDamperGain = s.ModeBDamper;
            _pModeBCenterGain = s.ModeBCenter;
            _pModeBLatGain     = s.ModeBLatGain;
            _pModeBDirSoft     = s.ModeBDirSoft;
            _pModeBLockRecoverMs = s.ModeBLockupRecoverMs < 20f ? 20f
                                 : s.ModeBLockupRecoverMs > 400f ? 400f : s.ModeBLockupRecoverMs;
            _pModeBLockupPoint = s.ModeBLockupPoint < 0.2f ? 0.2f
                               : s.ModeBLockupPoint > 2.0f ? 2.0f : s.ModeBLockupPoint;
            _pModeBGripTrim = s.ModeBGripTrim < 0.3f ? 0.3f
                            : s.ModeBGripTrim > 1.5f ? 1.5f : s.ModeBGripTrim;
            _pModeBMinForce = s.ModeBMinForce < 0f ? 0f
                            : s.ModeBMinForce > 0.5f ? 0.5f : s.ModeBMinForce;

            bool want = ModeBEnabledForActiveGame;
            // Which pipeline the opt-in arms. Reshape games (iRacing, RaceRoom
            // on the R3EFFB route) render the sim's own torque; every other
            // capable game synthesizes from slip.
            int wantMode = IsReshapeGame(_activeGame)
                         ? ForceModeIRacing : ForceModeModeB;
            if (want && _forceMode != wantMode)
            {
                // Clean engage: ramp from zero, EMAs seeded from current state.
                // Contention watchdog re-arms so a fixed in-game FFB setting
                // gets a fresh verdict. (Covers the 2->1 handoff too: real
                // Mode B taking over from spring mode still seeds.)
                _contentionWarned = false;
                _contentionSinceTicks = 0;
                ModeBContentionDetected = false;
                // Slip-starved latch re-arms too: a fixed Data Out port gets
                // a fresh verdict on the next engage (SeedModeBEngageState
                // below restarts the dwell and the debounce count).
                _slipStarvedWarned = false;
                ModeBSlipStarvedDetected = false;
                _crashDuck.Reset();
                SeedModeBEngageState();
                // The reshape path rides its own ramp, seeded here so engaging
                // fades force in instead of stepping to full torque.
                _irRamp = 0f;
                _irPrevTicks = 0;
            }
            // Preserve an armed spring mode: this method runs on every settings
            // apply (slider drags included), and clobbering it to off here would
            // blip the force out until the arming machine re-arms a second
            // later. Game switches disarm explicitly instead.
            _forceMode = want ? wantMode
                       : (_forceMode == ForceModeSpring ? ForceModeSpring : ForceModeOff);
            // Assert the device's authored-sign bypass at the mode change as
            // well, not only on the next DataUpdate pass (UpdateSpringModeArming):
            // a takeover packet, the soft lock included, can leave on the FFB
            // thread before that pass, and until then the device would still
            // run it through FfbInvertSign and send it out flipped (review,
            // 2026-09-13). The per-pass assertion stays as the re-attach backstop.
            var devMode = _device;
            if (devMode != null) devMode.FfbBypassTapCorrections = _forceMode == ForceModeIRacing;
            // Same window, same fix: leaving spring mode here would otherwise
            // keep the engine's copy of the game's classic spring stood down
            // until the next DataUpdate pass.
            AssertSpringModeStandDown();

            if (save) PersistSettings();
        }

        // Compressor feel: soft-knee ceiling on the Mode B force so stacked
        // cornering-weight + counter terms compress into the top of the range
        // instead of hard-clipping.
        private volatile bool _mbCompressorOn;
        private readonly SoftKneeCompressor _mbCompressor =
            new SoftKneeCompressor { Gain = 1.0, Threshold01 = 0.70, Ceiling01 = 0.95 };

        // Road kick: the model differences per-corner front suspension travel
        // on the telemetry thread (DispatchFrame); the FFB provider reads the
        // cached kick and applies its own short EMA so 60 Hz telemetry steps
        // don't land as steps at 1 kHz.
        private volatile bool _mbRoadKickOn;
        private volatile float _pRoadKickGain = 1.0f;
        private readonly RoadKickModel _roadKick = new RoadKickModel();
        private volatile float _mbKickCached;   // telemetry thread writes
        private float _mbKickEma;               // provider thread only
        private long _kickPrevTicks;            // telemetry thread only

        // Mode B damper band-limit state (FFB provider thread only). See the
        // damper block in MaybeReshapeFfb: the raw velocity path self-
        // oscillated at ~70 Hz through the wheel's physical motion.
        private float _mbDamperVelLp;
        private long  _mbDampPrevTicks;
        // Low-pass state for the R3E stationary friction FORCE. Smooths the
        // staircase the quantized wheel velocity leaves at this friction's higher
        // gain, which read as graininess (owner, 2026-09-05).
        private float _r3eFrictionLp;
        // Position EMA for the reshape's own stationary spring. Separate from
        // _springSteerEma so a route switch never resumes from the other
        // stage's stale value.
        private float _rsSpringSteerEma;

        // Crash duck: impact protection for the synthesized force (Mode B
        // core behavior, not a feel toggle — a crash buzz can physically
        // yank hands). Ticked on the FFB thread inside ComputeModeBForce.
        private readonly CrashDuckModel _crashDuck = new CrashDuckModel();

        // Per-VARIANT grip-limit auto-calibration. The learner ALWAYS ticks
        // while Mode B runs (so seat time accumulates regardless of the
        // checkbox); the checkbox only gates whether the learned peak is
        // applied as the utilization divisor. State swaps on variant change
        // and persists per "game|car|variant" in Settings.CarGripCalibration.
        private volatile bool _mbAutoCalOn;
        private readonly GripPeakLearner _gripCal = new GripPeakLearner();
        private volatile float _mbCalPeak = 1f;   // telemetry thread writes

        // Per-car auto strength ("Auto strength per car"): a SECOND
        // GripPeakLearner instance watching the composed Mode B force in
        // INTRINSIC units (Strength slider divided out), so each car variant
        // learns its own force ceiling and gets its own scale toward
        // AutoStrengthTarget, iRacing style: a weak car boosts, a monster
        // trims, each settles at its own strength, and the user's Strength
        // slider stays the true baseline underneath (delivered ceiling moves
        // with the slider; the learned peaks survive Strength retunes).
        // NominalPeak == target makes an unlearned car exactly identity
        // (scale 1) via the confidence fade. The learner MUST see the
        // PRE-scale force (see AutoStrengthScale's doc: feeding the scaled
        // force back converges to only sqrt of the correction), so the FFB
        // thread publishes a decaying pre-scale intrinsic peak
        // (_mbForceRawPeak) and this learner ticks on the telemetry thread
        // next to the grip cal, sharing its variant swap, flush, and re-learn reset.
        private const double AutoStrengthTarget   = 0.90;   // intrinsic (SatGain-normalized) ceiling
        private const double AutoStrengthMinScale = 0.60;
        private const double AutoStrengthMaxScale = 1.60;
        private volatile bool _mbAutoStrengthOn;
        private readonly GripPeakLearner _strengthCal = new GripPeakLearner
        {
            NominalPeak    = AutoStrengthTarget,
            CorneringFloor = 0.15,   // intrinsic force units: only meaningful-force time teaches
            PeakMin        = 0.30,
            PeakMax        = 1.50,   // intrinsic can exceed 1 when SatGain < 1 (f01 clamps at 1)
        };
        private volatile float _mbAutoStrengthScale = 1f;  // telemetry writes, FFB reads
        private volatile float _mbForceRawPeak;            // FFB writes (decaying max), telemetry reads

        // R3E auto-strength, iRacing press-to-apply style. RaceRoom's
        // SteeringForcePercentage tops out well below 1 (rig 2026-09-05: ~0.18
        // in normal driving), and on the reshape path FfbScale and the iRacing
        // max-force are both bypassed, so the wheel is left weak with no working
        // strength knob. So: a PEAK-HOLD observer (no decay) accumulates the
        // hardest this car pushed since the last apply; when it has settled
        // (R3EPeakSettled) the driver presses Apply, which commits it as the
        // car's max and resets the observer. NOT continuous, exactly like
        // iRacing's Auto button, so the strength never drifts under you.
        // _r3eAppliedPeak (the committed/nudged max) drives _r3eFullScaleFrac;
        // ComputeIRacingForce multiplies the R3E full scale by it.
        private volatile float _r3eFullScaleFrac = 1f;     // reader writes, FFB reads (MaxNm multiplier)
        private volatile float _r3eAppliedPeak;            // committed/nudged max (0 = none -> no boost yet)
        private float  _r3ePeakObs;                        // reader thread: peak-hold since last apply
        private string _r3ePeakCarId;                      // reader thread: car the observed peak is for
        private long   _r3ePeakGrowthTicks;                // when the peak last grew (settle detection)
        private double _r3ePeakRacingMs;                   // driving time accumulated for this car
        private long   _r3ePrevStrengthTicks;              // reader-thread dt for the racing-time clock
        private string _r3eLastLoadedCar;                  // reader thread: car the applied max is loaded for
        private readonly object _r3eStrengthLock = new object();
        private const double R3EPeakSettleMs   = 12000.0;  // no growth for this long
        private const double R3EPeakMinDriveMs = 20000.0;  // and at least this much driving

        /// <summary>The scale auto strength is currently applying (1.0 = none).
        /// Read-only view for the panel: this feature decided a number for the
        /// car and, until now, said so exactly once in a dash toast.</summary>
        public double ModeBAutoStrengthScale { get { return _mbAutoStrengthScale; } }

        /// <summary>0 to 1, how much near-limit seat time the strength learner
        /// has on this car variant. Below 1 the scale is faded toward 1.0, so a
        /// number shown without this reads as more settled than it is.</summary>
        public double ModeBStrengthConfidence { get { return _strengthCal.Confidence; } }

        /// <summary>The intrinsic force ceiling learned for this car variant, in
        /// the same units as AutoStrengthTarget. Exposed alongside the scale
        /// because the two together are what make a reading diagnosable: a peak
        /// sitting exactly on PeakMax means the learner railed rather than
        /// converged.</summary>
        public double ModeBStrengthPeak { get { return _strengthCal.Peak; } }

        /// <summary>True when the learned peak is against its own sanity ceiling.
        /// The scale is then pinned at its minimum for every car that gets there,
        /// which is a measurement problem, not a per-car result.</summary>
        public bool ModeBStrengthRailed
        {
            get { return _strengthCal.Peak >= _strengthCal.PeakMax - 1e-6; }
        }

        /// <summary>Grip auto-cal confidence for the active variant, 0 to 1. The
        /// strength scale is normalized by this learner's output, so a strength
        /// number read before this one settles is measured against a moving
        /// denominator.</summary>
        public double ModeBGripConfidence { get { return _gripCal.Confidence; } }
        // Braking-grip radius source (issue #38 follow-up): when the
        // ModeBLongitudinalGripLearn toggle is on, the friction-circle / gate
        // radius follows each car's grip-cal learned peak (times _pModeBGripTrim)
        // instead of the manual BLOCKPT point. The grip cal is stable + per-car;
        // the earlier bespoke slip-at-peak-decel learner was too noisy on-wheel
        // and its class was deleted 2026-08-02. Telemetry thread writes
        // _mbGripPeakForRadius; the FFB thread reads it.
        private volatile bool  _mbBrakeLearnOn;
        // Lateral-demand A/B (issue #38 loop root-cause): base the SAT grip
        // utilization on lateral (cornering) slip, not combined slip, so
        // straight-line braking cannot inflate the loop gain and self-oscillate.
        private volatile bool  _mbLateralDemandOn;
        private volatile float _mbGripPeakForRadius = 1f;  // grip cal EffectivePeak; telemetry writes, FFB reads
        private float _pModeBGripTrim = 1f;                // BGTRIM: radius = trim x grip-cal peak (1 = raw detected grip)
        private long   _calPrevTicks;             // telemetry thread only
        private string _gripCalKey;               // settings key of the loaded state
        private bool   _calConvergedLogged;       // one log line per variant per load
        private bool   _autoStrengthAnnounced;    // one readout per car per load
        private string _lastAnnouncedPreset;      // change detector for the preset readout

        // Race context for the OLED, captured from SimHub in DataUpdate and
        // read on the dispatch thread. See the capture site for why these are
        // ints rather than TimeSpans.
        private volatile int _shPosition, _shCurrentLap, _shTotalLaps;
        private volatile int _shLastLapMs, _shBestLapMs;
        private int _oledPrevLastLapMs;           // lap-completion edge detector
        private volatile bool _oledHidppFree;     // last computed SCREEN gate, for the settings panel
        private volatile bool _ledsHidppFree;     // last computed rev-LIGHTS gate (never opens under the CSP bridge)
        private volatile bool _ffbQuietNow;       // just the FFB-quiet term, for one-shot writes

        /// <summary>Is anything actually being PLAYED right now?
        ///
        /// "Frames are arriving" is a different question, and the two came apart
        /// in testing. The arcade source publishes for as long as the cabinet IO
        /// block EXISTS, so TeknoParrot left open at its menu keeps a telemetry
        /// source running and NoTelemetryArriving answering false with nothing
        /// being played at all. Every gate that meant "no game to fight" and
        /// asked the frames question instead was wrong in that state: the rim
        /// lights refused to preview a pattern change and logged "a game is
        /// driving the bar" in a room with no game running.
        ///
        /// SimHub naming no game AND no source claiming a live session is as
        /// close as the plugin gets to "nothing is happening". A real sim sitting
        /// in its menus still names a game, so this stays false there and none of
        /// the in-game safety is loosened.</summary>
        private bool NothingIsPlaying =>
            string.IsNullOrEmpty(_currentGameName) && !SessionRecentlyLive;

        /// <summary>The pipe-safety rule for a one-shot level write: never while a
        /// game's own force feedback is live. With nothing being played, or no
        /// telemetry arriving at all, there is no game to fight, so the answer is
        /// yes; with a game running, only the proven-quiet term says so.
        ///
        /// Outside Normal mode no telemetry source runs, so NoTelemetryArriving
        /// is trivially true and this cannot stand in for the mode check. Callers
        /// test the mode first.</summary>
        private bool OneShotLevelWritesAllowed =>
            NothingIsPlaying || NoTelemetryArriving() || _ffbQuietNow;

        /// <summary>Whether a pattern change may SHOW itself with the preview
        /// sweep or the lit hold, seconds of level writes that drive the
        /// strip. Never while a game is on unless the strip is provably ours
        /// (a force mode armed with the game's force off, i.e. hidppFree):
        /// in a game that lights its own bar the sweep fights the game's
        /// writer and the strip flickers. The quiet-pipe term alone is not
        /// enough here, because the wire tap goes quiet at every standstill
        /// in a tap-path game and opened the sweep mid-session (owner, AC,
        /// 2026-08-29). With nothing being played, or no telemetry at all,
        /// there is no game and no bar to fight, so the answer is yes.</summary>
        private bool PreviewSweepAllowed =>
            NothingIsPlaying || NoTelemetryArriving() || _ledsHidppFree;

        /// <summary>The level to leave the strip at after a slot rewrite that
        /// must not show itself: what the game last wrote to it, as seen on
        /// the wire, or -1 (the channel's own level) when nothing recent was
        /// seen. The upload raises the level to at least one to land, and
        /// settling to our own level, which is zero in a game that drives its
        /// own bar, left the strip dark until the game next changed it.</summary>
        private int StripLevelFromWire()
        {
            var tap = _ffbTap;
            var leds = _rpmLeds;
            if (tap == null || leds == null) return -1;
            byte idx = leds.RevFeatureIndex;
            if (idx == 0) return -1;
            return tap.TryGetLastLevelWrite(idx, 3000, out int level) ? level : -1;
        }
        private string _revCarKeyApplied;         // last car whose remembered pattern was applied

        // ---- per-car rev-light data (lovely-car-data) ----
        private LovelyCarDataStore _lovelyStore;
        private LovelyCarProfile   _lovelyCar;    // active car's published data, null when none
        private string             _lovelyCarKey; // "game/carId" the above was loaded for
        private string             _lovelyGear;   // gear the ramp below was picked for
        private LovelyGearRamp     _lovelyRamp;   // ramp in force, re-picked on gear change

        /// <summary>Cache for per-car rev-light data, created on first use. Lives
        /// beside the preset library so a backup of that folder carries it, and so
        /// a user can delete it by hand without touching anything else.</summary>
        private LovelyCarDataStore LovelyStore
        {
            get
            {
                if (_lovelyStore == null)
                {
                    _lovelyStore = new LovelyCarDataStore(
                        Path.Combine(TfPaths.CommonRoot, "TrueforceForAll-Library", "lovely-cache"))
                    {
                        Log = m => SimHub.Logging.Current.Info(m)
                    };
                }
                return _lovelyStore;
            }
        }

        /// <summary>Community features were switched, so the dataset that rides
        /// them has just become available or unavailable. On means read the active
        /// car now rather than at the next car load; off means drop what is held,
        /// including anything already published into the rev-limiter cascade.</summary>
        public void OnLovelyDataAvailabilityChanged()
        {
            if (LovelyDataEnabled)
            {
                OnLovelyCarChanged(_activeGame, _activeCarId, force: true);
                return;
            }

            _lovelyCar  = null;
            _lovelyRamp = null;
            _lovelyGear = null;
            _lovelyCarKey = null;
            _lovelyStore?.ForgetMemory();
            PublishLovelyRedlines();
            if (_rpmLeds != null) _rpmLeds.LevelCurve = null;
            HandBackLovelyLighting();
        }

        /// <summary>Whether the Lovely per-car dataset may be fetched and used
        /// at all.
        ///
        /// It follows the community switch rather than a control of its own,
        /// because it IS a community data source: it is fetched over the network
        /// and cached, exactly like car facts. Tying it to a checkbox on the
        /// LIGHTSYNC tab put it out of reach of every wheel whose strip has one
        /// fixed look, since that tab is collapsed for them. Those wheels cannot
        /// show a per-car pattern, but the same records carry per-gear redlines
        /// and each car's blink rate, and those work on any wheel.</summary>
        public bool LovelyDataEnabled => Settings?.CommunityEnabled == true;

        /// <summary>Whether that data may drive the wheel's LIGHTS.
        ///
        /// Deliberately a second, opt-in switch rather than part of the first.
        /// Lighting a car's own pattern means borrowing one of the user's five
        /// wheel slots, and community features ship on, so folding the two
        /// together would start writing to the wheels of everyone who upgrades
        /// without them asking for it. Reading the data costs them nothing.</summary>
        public bool LovelyLightingEnabled
            => LovelyDataEnabled && Settings?.LovelyCarDataEnabled == true;

        /// <summary>A detected wheel whose rev strip has one fixed look, so there
        /// is no pattern slot to borrow and no LIGHTSYNC tab. Both G923 variants,
        /// and a G PRO wearing G923 compatibility mode.
        ///
        /// Requires a DETECTED wheel on purpose. The capability property answers
        /// false both for "cannot" and for "no wheel found yet", and this one
        /// turns a feature ON, so an unknown wheel must not qualify.</summary>
        public bool WheelHasFixedLightPattern
            => WheelDetected && !WheelHasSelectableLightPattern;

        /// <summary>Whether the dataset may drive the strip's FILL TIMING: how far
        /// up the bar the revs have got, taken from the car's own switch-on points
        /// instead of an even spread from idle to redline.
        ///
        /// Split from the lighting switch because the two ask for different
        /// things. Lighting borrows a wheel slot, which is why it is opt-in.
        /// Filling borrows nothing: it changes a number we were already sending,
        /// costs no extra traffic and touches nothing of the user's.
        ///
        /// So on a fixed-strip wheel it follows community features and the user
        /// opts OUT. That is the only half of the feature those wheels can have,
        /// the tab carrying the opt-in is collapsed for them, and the permission
        /// the opt-in exists to ask for is meaningless on a strip with no slots.
        /// A programmable wheel keeps the single opt-in, where filling and
        /// lighting arrive together as one decision.</summary>
        public bool LovelyFillEnabled
            => LovelyDataEnabled
            && (Settings?.LovelyCarDataEnabled == true
                || (WheelHasFixedLightPattern && Settings?.LovelyFixedStripOptOut != true));

        /// <summary>The per-car data switch was flipped. Turning it ON adopts the
        /// active car immediately rather than waiting for the next car change;
        /// turning it OFF drops what is loaded so the lights fall back to the
        /// built-in ramp on the very next frame.</summary>
        public void OnLovelyEnabledChanged()
        {
            if (LovelyLightingEnabled)
            {
                OnLovelyCarChanged(_activeGame, _activeCarId, force: true);
            }
            else
            {
                // The LIGHTS stop, the DATA stays. This switch governs only
                // whether the car's pattern reaches the strip; its redlines and
                // blink rate are the half that works on every wheel, so dropping
                // _lovelyCar here would quietly take the shift cue away from a
                // user who only wanted their own colours back.
                _lovelyRamp = null;
                _lovelyGear = null;
                PublishLovelyRedlines();
                if (_rpmLeds != null) _rpmLeds.LevelCurve = null;
                HandBackLovelyLighting();
            }
        }

        /// <summary>Stop lighting cars: put the user's own pattern back if we are
        /// the ones who moved it, and hand the borrowed slot over.
        ///
        /// Shared by both switches that can turn the lighting off, because they
        /// mean the same thing to the wheel and had drifted apart once already.
        /// Switching a feature off means OFF, not "off from the next restart":
        /// sitting on someone's colours until shutdown is not a thing to do.</summary>
        private void HandBackLovelyLighting()
        {
            if (_autoAppliedColors)
            {
                _autoAppliedColors = false;
                try { ApplyStickyPattern(); }
                catch (Exception ex)
                {
                    SimHub.Logging.Current.Warn("[TF4ALL] sticky pattern restore failed: " + ex.Message);
                }
            }

            Task.Run(() =>
            {
                try
                {
                    string restored = RestoreOwedSlots();
                    if (!string.IsNullOrEmpty(restored)) SimHub.Logging.Current.Info("[TF4ALL] " + restored);
                }
                catch (Exception ex)
                {
                    SimHub.Logging.Current.Warn("[TF4ALL] slot restore on disable failed: " + ex.Message);
                }
            });
        }

        /// <summary>Car-load edge for the wheel's lights: whatever this car should
        /// be showing, applied ONCE when it becomes active, so a manual pick made
        /// mid-session still sticks until the next remembered car arrives. Not a
        /// per-frame push: the wheel's selection is a real selector, not a state we
        /// continuously enforce.
        ///
        /// Deliberately reads no telemetry frame. The colors come from the car's
        /// own published ramp rather than the live gear, and the car id is
        /// established in DataUpdate, so lights-only mode can drive this edge with
        /// no telemetry source running at all.
        ///
        /// Callable from either thread: the latch is exchanged atomically, so the
        /// telemetry path and the DataUpdate path cannot both apply the same car.</summary>
        /// <param name="ffbQuietProven">Whether the HID++ pipe is known to be free
        /// of the game's own force right now. False only stages a remembered pick
        /// instead of writing it, which is the correct answer whenever we cannot
        /// prove the pipe is ours.</param>
        private void ApplyCarLightsForActiveCar(bool ffbQuietProven)
        {
            if (MasterMode == TrueforceMasterMode.Off || _rpmLeds == null) return;

            string carKey = (!string.IsNullOrEmpty(_activeGame) && !string.IsNullOrEmpty(_activeCarId))
                ? _activeGame + "/" + _activeCarId : null;
            if (carKey == null) return;
            string prev = System.Threading.Interlocked.Exchange(ref _revCarKeyApplied, carKey);
            if (string.Equals(prev, carKey, StringComparison.Ordinal)) return;

            // A remembered PATTERN of ours wins over a remembered wheel effect:
            // picking one of our patterns for a car is the more specific choice,
            // and the two are kept mutually exclusive when either is saved.
            bool lightsOnly = MasterMode == TrueforceMasterMode.LightsyncOnly;

            var rememberedPattern = GetCarRememberedLightPattern();
            if (rememberedPattern != null)
            {
                var p = rememberedPattern;
                Task.Run(() =>
                {
                    string msg;
                    // No confirmation sweep in lights-only. The sweep is roughly
                    // seven seconds of level writes (a 0-to-10 ramp, a lit hold, a
                    // ramp back down) on the endpoint the game's force feedback
                    // shares, at every car load, which is precisely the continuous
                    // level driving this mode exists to avoid. The colors land
                    // either way, and in this mode the game lights the bar.
                    if (!ApplyLightPattern(p, out msg, sweep: !lightsOnly))
                        SimHub.Logging.Current.Info("[TF4ALL] remembered pattern not applied: " + msg);
                });
            }
            else if (Settings?.CarRevLightEffect != null
                && Settings.CarRevLightEffect.TryGetValue(carKey, out int remembered)
                && remembered > 0)
                // In lights-only the write is allowed even though the pipe cannot be
                // proven quiet: a remembered pick is a single selection write at car
                // load, no different from the selection a slot upload already emits,
                // and staging it instead meant it never landed at all, since nothing
                // in this mode ever arms the bar to consume a staged pick.
                _rpmLeds.ApplyRemembered(remembered, ffbQuietProven || lightsOnly);

            OnLovelyCarChanged(_activeGame, _activeCarId);
        }

        // True while the FULL pipeline's own subsystems are up: the loopback helper
        // attached, audio registered in the mixer, a telemetry source running, the
        // capture poll thread alive and the device open. Tracked rather than
        // inferred, because a live mode switch has to add or remove exactly the
        // pieces that are missing or present, and adding a second copy of any of
        // them is worse than not switching at all.
        // Volatile: written inside _pipelineLock but READ unlocked by the cheap
        // pre-check in ReconcileFullPipeline, which runs on SimHub's data thread and
        // on the WPF dispatcher. A stale read there would skip a reconcile the mode
        // actually needs.
        private volatile bool _fullPipelineRunning;
        private bool _audioInMixer;   // touched only under _pipelineLock
        private volatile bool _capturePollStop;
        // Set once InitPipeline has finished, so a mode change that lands during
        // startup cannot start a subsystem before the code that owns it has run.
        private volatile bool _pipelineReady;

        /// <summary>Bring the force pipeline up or down to match the mode, live,
        /// without a SimHub restart. The effects and the engine loop are NOT part of
        /// this: they are built in every mode and are inert until the producer
        /// thread ticks them, so they never need adding or removing.</summary>
        private readonly object _pipelineLock = new object();
        private int _pipelineReconciling;   // 0/1: single-flight AND re-entrancy guard

        private void ReconcileFullPipeline(TrueforceMasterMode now)
        {
            // Init resolves the mode BEFORE it builds the pipeline, and it builds
            // the right one for the mode. Reconciling before that point would start
            // subsystems ahead of the code that owns them.
            if (!_pipelineReady) return;
            if ((now == TrueforceMasterMode.Normal) == _fullPipelineRunning) return;
            // NEVER inline. Tearing down waits on a child process to exit and
            // bringing up runs the wheel's ~136-packet init sequence, and every
            // caller is either SimHub's data thread (a game change) or the WPF
            // dispatcher (the combo, the home tile). Blocking either for seconds is
            // how a mode switch becomes a freeze.
            Task.Run((Action)ReconcilePipelineCore);
        }

        /// <summary>The pipeline reconcile itself, on a background thread, one at a
        /// time.</summary>
        private void ReconcilePipelineCore()
        {
            // Single-flight, and re-entrancy-proof: StartFullPipelineParts reaches
            // SyncDeviceToPluginEnabled, which calls back into ReconcileFullPipeline.
            if (System.Threading.Interlocked.CompareExchange(ref _pipelineReconciling, 1, 0) != 0) return;
            try
            {
                lock (_pipelineLock)
                {
                    // Loop rather than act once. A mode change that lands WHILE we
                    // are working is picked up here instead of being lost, which is
                    // what let a stop racing a start finish with the pipeline torn
                    // down and the mode still reading full: a green UI over a dead
                    // wheel. Bounded so a user flipping the combo cannot spin us.
                    for (int guard = 0; guard < 4; guard++)
                    {
                        // Re-tested every pass: End() clears _pipelineReady and then
                        // waits for us, so a teardown that starts mid-loop must not
                        // find us rebuilding what it just disposed.
                        if (!_pipelineReady || _shuttingDown) return;
                        bool wantFull = MasterMode == TrueforceMasterMode.Normal;
                        if (wantFull == _fullPipelineRunning) return;
                        if (wantFull) StartFullPipelineParts();
                        else StopFullPipelineParts();
                    }
                }
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Error("[TF4ALL] pipeline reconcile failed", ex);
            }
            finally
            {
                System.Threading.Volatile.Write(ref _pipelineReconciling, 0);
                // A request that arrived while we held the flag returned without
                // acting, so re-check once we have let go.
                if (_pipelineReady && !_shuttingDown
                    && (MasterMode == TrueforceMasterMode.Normal) != _fullPipelineRunning)
                    Task.Run((Action)ReconcilePipelineCore);
            }
        }

        private void StopFullPipelineParts()
        {
            _fullPipelineRunning = false;
            SimHub.Logging.Current.Info(
                "[TF4ALL] Standing the force pipeline down: capture, telemetry and the "
                + "Trueforce stream all stop here.");

            // The producer THREAD is deliberately left alive. With the mode no longer
            // full it parks in the same idle sleep a disabled plugin has always used,
            // and tearing it down would mean rebuilding it on the way back for no gain.
            try { StopIRacingDirect(); } catch { }
            try { StopR3EDirect(); } catch { }
            try { StopLmuDirect(); } catch { }

            _capturePollStop = true;
            var poll = _capturePollThread;
            _capturePollThread = null;
            // Joined HERE rather than in the background: the loop only samples the
            // stop flag between 100 ms sleep slices, so a fast flip back to full
            // would otherwise start a second poll thread while the first was still
            // in a sleep, and both would run CaptureTick for the rest of the
            // session. This method already runs on a background thread.
            if (poll != null) { try { poll.Join(2000); } catch { } }

            // Release the capture itself. Detaching the helper is not enough: the
            // tick's fast path returns early while _capturedProcess is alive, so a
            // brand-new helper spawned on the way back to full would never be told
            // which process to record, and the audio layer would produce silence for
            // the rest of the game session while the status still read "Capturing".
            try
            {
                var held = System.Threading.Interlocked.Exchange(ref _capturedProcess, null);
                if (held != null)
                {
                    try { held.Dispose(); } catch { }
                    try { _audio?.Stop(); } catch { }
                    ExitStreamingGcMode();
                }
            }
            catch { }

            // Same order and the same explicit-dispose reasoning as End(): a keep-alive
            // listener may be bound without being the active source.
            try { _telemetrySource?.Dispose(); } catch { }
            if (_forzaUdp != null && _forzaUdp != _telemetrySource)
            { try { _forzaUdp.Dispose(); } catch { } }
            _forzaUdp = null;
            _forzaOnSimHubFallback = false;
            if (_fsPipeSource != null && _fsPipeSource != _telemetrySource)
            { try { _fsPipeSource.Dispose(); } catch { } }
            _fsPipeSource    = null;
            // Lights-only promises to touch nothing but the wheel's lights, and a
            // live shared-memory reader thread breaks that the way a bound UDP
            // port would.
            if (_teknoSource != null && _teknoSource != _telemetrySource)
            { try { _teknoSource.Dispose(); } catch { } }
            _teknoSource     = null;
            _telemetrySource = null;
            _simHubSource    = null;

            // The helper is a child process, so leaving it running would be the most
            // visible way to break the promise this mode makes.
            try { _audio?.Detach(); } catch { }
            try { _helperHost?.Dispose(); } catch { }
            _helperHost = null;

            // Release the kernel filter driver. This one is not merely untidy to
            // leave open: while we hold the control device the driver ABSORBS the
            // game's force writes instead of passing them through, and the ep3
            // stream that used to re-emit them is being torn down two lines below,
            // so the wheel would go completely dead in a mode that promised to touch
            // nothing. Closing the handle is what reverts the driver to passthrough.
            // Not rebuilt on the way back to full: the intercept is an experimental
            // opt-in whose own UI already says it applies at the next restart.
            if (_driverChannel != null || _driverLedChannel != null)
            {
                try { _driverChannel?.Dispose(); } catch { }
                _driverChannel = null;
                try { _driverLedChannel?.Dispose(); } catch { }
                _driverLedChannel = null;
                SimHub.Logging.Current.Info(
                    "[TF4ALL] Filter-driver intercept released; the wheel is back on passthrough. "
                    + "Restart SimHub to use the intercept again.");
            }

            // Tap, steering reader and the device itself.
            //
            // Wait for any bring-up already in flight first, or its CleanupDevice +
            // TryBringUpDevice would land AFTER this teardown and leave a live ep3
            // stream and a capture child running in a mode that has none. Bounded:
            // a bring-up is a HID open plus a ~136-packet init, so a few seconds is
            // the honest upper bound, and the work item re-checks the mode itself as
            // a second line of defence.
            for (int i = 0; i < 100 && System.Threading.Volatile.Read(ref _recoveryInProgress) != 0; i++)
                System.Threading.Thread.Sleep(50);
            CleanupDevice();
        }

        private void StartFullPipelineParts()
        {
            // Nothing starts once the plugin is on its way out. Checked here as well
            // as in the loop above because this is the method that spawns a child
            // process and opens the wheel.
            if (!_pipelineReady || _shuttingDown) return;
            SimHub.Logging.Current.Info("[TF4ALL] Starting the force pipeline.");

            if (_helperHost == null)
            {
                try
                {
                    string pluginDir = System.IO.Path.GetDirectoryName(typeof(TrueforcePlugin).Assembly.Location);
                    string helperExe = System.IO.Path.Combine(pluginDir, "TrueforceForAll.LoopbackHelper.exe");
                    _helperHost = new HelperHost(helperExe);
                    _helperHost.Spawn();
                    SimHub.Logging.Current.Info($"[TF4ALL] Loopback helper spawned ({helperExe}).");
                }
                catch (Exception ex)
                {
                    SimHub.Logging.Current.Error("[TF4ALL] Failed to spawn loopback helper", ex);
                    _helperHost = null;
                }
            }
            if (_audio != null && _helperHost != null) _audio.Attach(_helperHost);
            // Mixer.Add appends without checking, so a second registration would
            // render the same source twice.
            if (_audio != null && !_audioInMixer) { _mixer.Add(_audio); _audioInMixer = true; }

            if (_simHubSource == null)
            {
                _simHubSource = new SimHubTelemetrySource { OnFrame = DispatchFrame };
                _simHubSource.Start();
                _telemetrySource = _simHubSource;
                SimHub.Logging.Current.Info($"[TF4ALL] Telemetry source: {_telemetrySource.Name}.");
            }

            _capturePollStop = false;
            if (_capturePollThread == null)
            {
                _capturePollThread = new Thread(CapturePollLoop)
                {
                    IsBackground = true,
                    Name = "TrueforceCapturePoll",
                };
                _capturePollThread.Start();
            }

            // Last, because it is the slow one (HID open plus the init sequence) and
            // because everything above should already be waiting for it.
            //
            // Claims the same single-flight slot the recovery watchdog and the UI
            // probe use. Without it, the watchdog on the data thread sees
            // MasterMode == Normal and _device == null the instant the mode latches,
            // and starts a SECOND bring-up whose first act is CleanupDevice, which
            // disposes this one's half-built device out from under it.
            if (_device == null)
            {
                if (System.Threading.Interlocked.CompareExchange(ref _recoveryInProgress, 1, 0) == 0)
                {
                    try
                    {
                        // Stamp the attempt so the watchdog's rate limiter starts
                        // from now rather than from whenever it last ran in full.
                        _lastRecoveryAttemptTicks = Stopwatch.GetTimestamp();
                        if (!TryBringUpDevice())
                            SimHub.Logging.Current.Warn(
                                "[TF4ALL] Wheel not ready; the recovery watchdog will keep retrying.");
                    }
                    finally { System.Threading.Volatile.Write(ref _recoveryInProgress, 0); }
                }
            }
            // Set even when the wheel is not ready: the watchdog is now allowed to
            // run, and it is the thing that finishes the job.
            _fullPipelineRunning = true;

            // The game we are already in never went through the game-change path in
            // this mode, so pick its telemetry source and arm its force mode now.
            if (!string.IsNullOrEmpty(_activeGame))
            {
                try { SwapTelemetrySource(_activeGame, silent: true); } catch { }
                try { ApplyModeBFromSettings(); } catch { }
            }
        }

        /// <summary>Put the LIGHT subsystems where a new master mode says they
        /// belong. Separate from the ep3 device transition because the lights ride
        /// their own endpoint and answer to their own rules: entering Off has to
        /// give a borrowed slot back, and entering any mode that does not drive a
        /// live rev bar has to stop the keepalive that would otherwise keep writing
        /// levels once a second forever.</summary>
        private void ReconcileLightSubsystems(TrueforceMasterMode was, TrueforceMasterMode now, string context)
        {
            try
            {
                // Normal is the only mode that drives a live bar. AbandonWheel
                // rather than ForceOff: ForceOff stands down while a sweep owns the
                // strip, which is exactly the case if the switch is made
                // mid-preview, and that sweep would then keep writing levels for
                // seconds afterwards with its auto-off ramp firing later still. This
                // also stops the keepalive, which otherwise resends a level once a
                // second forever on a pipe the game now owns.
                if (now != TrueforceMasterMode.Normal)
                {
                    _rpmLeds?.AbandonWheel();
                    // The screen goes back with the lights. Nothing else hands it
                    // over: the gate-off path rides telemetry frames, and outside
                    // full there are none, so a panel we were drawing on would stay
                    // ours with no way for the wheel's own menu to return.
                    // AbandonScreen rather than ForceOff, which stands down while a
                    // test or layout report holds the panel: those run up to 25 s.
                    try { _oledDash?.AbandonScreen(); } catch { }
                    // The G923's legacy rev bar is a different channel on a
                    // different report, so nothing above touches it. A running
                    // F8 sweep would otherwise keep writing at ~60 Hz.
                    try { _f8Leds?.StopSweep(); } catch { }
                    try { _f8Leds?.SetLevel(0, 5); } catch { }
                }
                else try { _oledDash?.AllowScreen(); } catch { }

                // The audio meter follows the mode too. Off means off: leaving
                // its thread polling the sound card for a mode that will never
                // write a level is a background cost with nothing to show for
                // it, and the AbandonWheel above has already taken the strip.
                try { SyncAudioOutputMeter(); } catch { }

                // Re-apply this car's lights on the way INTO a mode that may show
                // them. The car-load edge is latched and only fires on a car change,
                // so without this, choosing lights-only while already sitting in a
                // car did nothing at all until the user swapped car, and coming back
                // to full after an off (which restores the user's own colors) left
                // the wheel showing those instead of the car's for the rest of the
                // session.
                if (now != TrueforceMasterMode.Off && was != now)
                {
                    System.Threading.Interlocked.Exchange(ref _revCarKeyApplied, null);
                    Task.Run(() =>
                    {
                        try { ApplyCarLightsForActiveCar(ffbQuietProven: now == TrueforceMasterMode.LightsyncOnly); }
                        catch (Exception ex)
                        { SimHub.Logging.Current.Warn("[TF4ALL] car lights on mode change failed: " + ex.Message); }
                    });
                }

                if (was == TrueforceMasterMode.Normal && now == TrueforceMasterMode.LightsyncOnly)
                    SimHub.Logging.Current.Info(
                        "[TF4ALL] Lightsync only: the force layer is standing down; we keep setting the wheel's patterns.");

                if (now != TrueforceMasterMode.Off) return;

                // Off means off, so the user's own colors go back now rather than
                // sitting in a borrowed slot until shutdown. Same shape as
                // OnLovelyEnabledChanged above: off the caller's thread, and never
                // throwing into it.
                Task.Run(() =>
                {
                    try
                    {
                        string restored = RestoreOwedSlots();
                        if (!string.IsNullOrEmpty(restored)) SimHub.Logging.Current.Info("[TF4ALL] " + restored);
                    }
                    catch (Exception ex)
                    {
                        SimHub.Logging.Current.Warn("[TF4ALL] slot restore on switch-off failed: " + ex.Message);
                    }
                });
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Warn("[TF4ALL] light reconcile failed: " + ex.Message);
            }
        }

        /// <summary>Car-load edge: adopt whatever published rev-light data we hold
        /// for this car, then refresh it in the background. Cache first so a car
        /// we already know lights correctly on lap one rather than after a round
        /// trip, and so the telemetry thread never waits on a network call.</summary>
        private void OnLovelyCarChanged(string game, string carId)
            => OnLovelyCarChanged(game, carId, force: false);

        /// <summary>As above. `force` is for the two switches that have to reload
        /// the SAME car (the lighting box and community features), where the latch
        /// would otherwise read the car as already handled and do nothing.</summary>
        private void OnLovelyCarChanged(string game, string carId, bool force)
        {
            // Two edges reach this: the wheel-agnostic car change above, and the
            // lighting edge at the end of ApplyCarLightsForActiveCar. Whichever
            // arrives first does the work. Without the latch the second one
            // refetches and republishes on every car load, and re-runs the colour
            // apply that borrows a wheel slot.
            string key = (game ?? "") + "/" + (carId ?? "");
            if (!force && string.Equals(_lovelyCarKey, key, StringComparison.Ordinal)) return;
            _lovelyCarKey = key;

            _lovelyCar  = null;
            _lovelyRamp = null;
            _lovelyGear = null;
            PublishLovelyRedlines();

            // Both early returns below skip ApplyCarColorsOnLoad, which is the
            // only thing that hands the lights back. Without this, colors we
            // borrowed for the PREVIOUS car survive switching to a car with no
            // id (an unrecognised car) or turning the feature off mid-session,
            // and the wheel keeps showing a car the user is no longer in.
            //
            // The gate here is the DATA one: a wheel that cannot show a pattern
            // still wants this car's redlines, so the fetch has to run for it.
            // Whether any of it reaches the strip is decided further down.
            if (!LovelyDataEnabled
                || string.IsNullOrEmpty(game) || string.IsNullOrEmpty(carId))
            {
                if (_autoAppliedColors)
                {
                    _autoAppliedColors = false;
                    ApplyStickyPattern();
                }
                return;
            }

            try
            {
                var store = LovelyStore;
                _lovelyCar = store.GetCached(game, carId);
                PublishLovelyRedlines();
                // Cached cars light correctly on lap one rather than after a
                // round trip; the refresh below covers a car we have not seen.
                // Both calls are unguarded on purpose: ApplyCarColorsOnLoad
                // gates itself on LovelyLightingEnabled, and it has to run even
                // when lighting is off so its !haveData branch can hand a
                // previous car's borrowed colours back.
                ApplyCarColorsOnLoad(game, carId);
                Task.Run(() =>
                {
                    try
                    {
                        var fresh = store.Refresh(game, carId);
                        // Only adopt if the car has not changed again underneath us,
                        // AND the master switch has not moved to Off while the fetch
                        // was in flight: a network round trip easily outlives a
                        // click, and landing colors after "off" is exactly the bug
                        // this mode work exists to fix.
                        if (MasterMode != TrueforceMasterMode.Off
                            && string.Equals(_activeGame, game, StringComparison.Ordinal)
                            && string.Equals(_activeCarId, carId, StringComparison.Ordinal))
                        {
                            _lovelyCar  = fresh;
                            _lovelyRamp = null;
                            _lovelyGear = null;
                            PublishLovelyRedlines();
                            // A car seen for the first time has no cached data at
                            // the car-load edge, so this is where its colors
                            // become available.
                            ApplyCarColorsOnLoad(game, carId);
                        }
                    }
                    catch (Exception ex)
                    {
                        SimHub.Logging.Current.Warn("[TF4ALL] lovely refresh failed: " + ex.Message);
                    }
                });
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Warn("[TF4ALL] lovely lookup failed: " + ex.Message);
            }
        }

        /// <summary>Which per-car source should fill the strip this frame, as a
        /// curve over (rpm, steps), or null when none of them has data and the
        /// plain ramp should stand.
        ///
        /// The CAR's own shift lights win where the game hands them over (AC
        /// publishes each dash LED's switch-on RPM through the CSP bridge):
        /// nothing beats the data of the car being driven. Then the published
        /// dataset, then nothing.
        ///
        /// Shared by both wheel families on purpose. The HID++ level channel
        /// installs the result as its LevelCurve and the G923 PS F8 path invokes
        /// it per frame, because that path writes a bitmask straight to the wheel
        /// and has no controller to hold a curve for it. Step count is the
        /// caller's, so a five-step bar and a ten-step one both land correctly.</summary>
        private Func<double, int, int?> CarFillCurve(string gear)
        {
            var acSteps = (_telemetrySource as AcSharedMemoryTelemetrySource)?.CspAcLedStepRpms;
            if (acSteps != null && acSteps.Length > 0)
                return (r, steps) => AcCarLevel(acSteps, r, steps);
            if (_lovelyCar != null && LovelyFillEnabled)
                return (r, steps) => LovelyLevel(gear, r, steps);
            return null;
        }

        /// <summary>The active car's fill curve, or null when we have no data for
        /// it. Runs on the telemetry thread, so it only reads already-loaded state
        /// and re-picks the gear ramp when the gear actually changes.</summary>
        private int? LovelyLevel(string gear, double rpms, int steps)
        {
            var car = _lovelyCar;
            if (car == null || !LovelyFillEnabled) return null;

            var ramp = RampFor(car, gear);
            if (ramp == null || !ramp.IsUsable) return null;

            return LovelyLightMath.LevelForRpm(ramp, rpms, steps);
        }

        /// <summary>Ramp for this gear, re-picked only when the gear actually
        /// changes. Called per frame, so the dictionary lookup is cached.</summary>
        private LovelyGearRamp RampFor(LovelyCarProfile car, string gear)
        {
            if (!string.Equals(gear, _lovelyGear, StringComparison.Ordinal) || _lovelyRamp == null)
            {
                _lovelyGear = gear;
                _lovelyRamp = car.RampForGear(gear);
            }
            return _lovelyRamp;
        }

        /// <summary>Hand the active car's published per-gear redlines to the
        /// rev-limiter, which owns the one redline cascade everything reads.
        ///
        /// Deliberately routed through that cascade rather than applied at the
        /// LED call site: the flash, the fill onset and the limiter buzz all read
        /// EffectiveRedlineRpm, so going through it keeps them one "shift now"
        /// signal. The cascade ranks these above the game's own telemetry redline,
        /// because telemetry reports the engine limiter while these record where
        /// the real car's dash lights up. Null when the feature is off or the car
        /// has no entry, which restores the previous behaviour exactly.</summary>
        private void PublishLovelyRedlines()
        {
            bool have = LovelyDataEnabled && _lovelyCar != null;

            var rl = RevLimiter;
            if (rl != null)
                rl.PublishedGearRedlines = have ? _lovelyCar.ForwardGearRedlines() : null;

            // The car's OWN dash outranks the published dataset where the game
            // hands it to us: BLINK_HZ comes out of the very car being driven,
            // where the dataset is somebody's reading of that car.
            int? acBlink = AcCarBlinkIntervalMs();

            // null means we know nothing about this car, which is NOT the same
            // as the car publishing zero. Zero is an answer: it does not blink.
            PublishCarBlinkRate(acBlink ?? (have ? (int?)_lovelyCar.RedlineBlinkIntervalMs : null));
        }

        /// <summary>Half-period of the active AC car's own shift-light flash,
        /// from its data, or null when we are not in AC, the script is older
        /// than v4, or the car models no shift lights.
        ///
        /// BLINK_HZ counts full flashes per second; PublishCarBlinkRate wants
        /// how long one STATE lasts, so a 12 Hz car is 500/12 = 42 ms lit and
        /// 42 ms dark.</summary>
        private int? AcCarBlinkIntervalMs()
        {
            var src = _telemetrySource as AcSharedMemoryTelemetrySource;
            if (src == null) return null;
            var s = src.CspLastSample;
            if (s.AcLedCount <= 0) return null;
            // A car with shift lights but no blink figure is saying it does not
            // flash, which is an answer, not a gap: zero reaches
            // PublishCarBlinkRate as "holds the bar solid".
            if (s.AcLedBlinkHz <= 0f) return 0;
            return Math.Max(1, (int)Math.Round(500.0 / s.AcLedBlinkHz));
        }

        /// <summary>Level for the active AC car's OWN shift lights: how many of
        /// its dash LEDs are lit at these revs, scaled onto the wheel's bar.
        ///
        /// Scaled rather than mapped one-to-one because the two rarely match: a
        /// car with five dash LEDs on a ten-step rim lights two steps per LED,
        /// which keeps the wheel's bar full exactly when the car's dash is full.
        /// The thresholds are the car's, so the ONSET matches the dash in front
        /// of the driver instead of a percentage of the rev range.</summary>
        private static int AcCarLevel(float[] stepRpms, double rpms, int steps)
        {
            int lit = 0;
            for (int i = 0; i < stepRpms.Length; i++)
                if (rpms >= stepRpms[i]) lit++;
            if (lit <= 0) return 0;
            if (lit >= stepRpms.Length) return steps;
            int level = (int)Math.Round((double)steps * lit / stepRpms.Length);
            return level < 1 ? 1 : level > steps ? steps : level;
        }

        /// <summary>Hand the active car's own blink rate to the two things that
        /// can express it.
        ///
        /// The LED flash takes it directly: it IS the redline blink, so a car that
        /// flashes fast now flashes fast. The pit-limiter HAPTIC takes it as a
        /// pulse rate, which is how a per-car cadence reaches the driver at all in
        /// games where we never touch the lights. Flashing needs a stream of level
        /// writes and that cuts the game's force on the shared pipe; a rate is
        /// just a number, and the wheel can pulse it for free.
        ///
        /// 0 means the car publishes no blink (470 of 717 do not), which restores
        /// the built-in rate and the user's own pulse setting.</summary>
        private void PublishCarBlinkRate(int? published)
        {
            // Three states, not two. No data at all leaves everything at the
            // built-in behaviour; a published zero means this car holds the bar
            // solid at redline; anything else is its own rate.
            int intervalMs = published ?? 0;
            if (_rpmLeds != null) _rpmLeds.RedlineBlinks = !published.HasValue || published.Value > 0;

            // Straight across: the published figure is how long each state
            // LASTS, not a full on-plus-off cycle.
            //
            // This was halved for a while, on the reading that it was a full
            // period. Their README does not say either way, its whole spec being
            // "The Speed at which the redline blinks in ms" (checked 2026-08-24),
            // so it came down to observation: halved, the wheel blinks visibly
            // faster than the same car does in iRacing, which is exactly what
            // halving a half-period looks like. The same dataset's zeros match
            // iRacing's non-blinking cars precisely, so the sim is a fair
            // reference for the rate too.
            //
            // The pit limiter reads the same number as a PERIOD (1000/interval
            // Hz) and keeps doing so. That is not an inconsistency: a haptic
            // pulse is one event per cycle, where a light has an on phase and an
            // off phase, so the same figure means a full pulse there and one
            // state here.
            int half = intervalMs > 0 ? Math.Max(1, intervalMs) : 185;
            if (_rpmLeds != null) _rpmLeds.RedlineBlinkHalfMs = half;

            if (PitLimiter != null)
                PitLimiter.PublishedPulseHz = intervalMs > 0 ? (float?)(1000.0f / intervalMs) : null;

            // Logged because the difference between 4 Hz and 5.4 Hz is not
            // something anyone can judge by eye, so without this the only honest
            // answer to "did the flash rate sync" is a shrug.
            if (intervalMs != _lastBlinkIntervalMs)
            {
                _lastBlinkIntervalMs = intervalMs;
                SimHub.Logging.Current.Info(intervalMs > 0
                    ? $"[TF4ALL] car blink rate: {intervalMs} ms period "
                      + $"({1000.0 / intervalMs:0.0} Hz), LED half-period {half} ms"
                    : "[TF4ALL] car blink rate: none published, using the built-in 185 ms half-period");
            }
        }

        /// <summary>Last blink period we announced, so the log carries a line per
        /// CHANGE rather than one per car-data refresh.</summary>
        private int _lastBlinkIntervalMs = -1;
        private volatile float _shBrake01, _shClutch01, _shHandbrake01;

        // Grip re-learn request (the Re-learn car button on the Telemetry
        // Based FFB tab and the dash RE-LEARN action). The learner and the
        // calibration dict are owned by the telemetry thread (Tick /
        // LoadGripCal / FlushGripCal), and double writes are not atomic on
        // 32-bit SimHub, so the UI thread only raises this flag; the
        // telemetry frame path consumes it.
        private volatile bool _gripCalResetRequested;

        // WHICH car the queued reset is for, captured at request time. The
        // request names a key back to the user ("reset queued for 'X'"), and
        // that promise has to survive the gap until a telemetry frame consumes
        // it: _gripCalKey only advances inside LoadGripCal, which runs late in
        // the frame and only while the session is live, so parked in a pit box
        // it can still name the PREVIOUS car for a long time. Consuming against
        // whatever is current would wipe a calibration the user never named.
        private volatile string _gripCalResetKey;

        /// <summary>Queue a wipe of the active variant's learned grip
        /// calibration (peak + confidence), for the Re-learn car button and
        /// the dash RE-LEARN action: the stored slot is removed and the
        /// learner starts fresh, for when a tune / tire change left the old
        /// calibration feeling off. Returns user-facing status.</summary>
        public string RequestGripCalReset()
        {
            string key = _gripCalKey;
            if (string.IsNullOrEmpty(key))
                return "No car variant loaded yet. Drive with Telemetry Based FFB active, then press Re-learn car again.";
            _gripCalResetKey = key;
            _gripCalResetRequested = true;
            // Only synthesis re-learns. Spring mode and iRacing reshape never
            // tick the learners, so promising a re-learn there would have the
            // user driving laps waiting for a convergence that cannot happen.
            string tail = _forceMode == ForceModeModeB
                ? "applies on the next telemetry frame, then re-learns as you corner."
                : "applies on the next telemetry frame. It re-learns only in games running Telemetry Based FFB synthesis, not in spring or iRacing mode.";
            return $"Grip auto-cal reset queued for '{key}' (auto strength included); {tail}";
        }

        /// <summary>Consume a queued grip re-learn. Called from the telemetry thread
        /// on every frame, in every force mode: the learner and the calibration
        /// dictionary are owned by that thread (see RequestGripCalReset), but the
        /// reset itself must not wait for Mode B to be the live mode, or it lands
        /// on whichever car happens to be loaded when Mode B next runs.</summary>
        private void ConsumeGripCalResetRequest()
        {
            if (!_gripCalResetRequested) return;
            _gripCalResetRequested = false;
            string target = _gripCalResetKey;
            _gripCalResetKey = null;
            if (string.IsNullOrEmpty(target)) return;
            // Remove bumps the dictionary version too: same lock as
            // FlushGripCal, or a concurrent serialize throws.
            lock (_carFactsLock) { Settings?.CarGripCalibration?.Remove(target); }
            ScheduleSettingsFlush();

            // The LIVE learners only get reset when they are the ones the user
            // named. If the car moved on between the request and this frame, the
            // stored slot is still the right thing to delete (that is what the
            // status line promised) but the in-flight learning belongs to a
            // different car and must not be thrown away with it.
            bool live = string.Equals(target, _gripCalKey, StringComparison.Ordinal);
            if (!live)
            {
                SimHub.Logging.Current.Info(
                    $"[TF4ALL] Grip auto-cal reset for '{target}' (re-learn): stored calibration removed. "
                    + "The car changed before it applied, so the car now loaded keeps what it has learned.");
                return;
            }
            _gripCal.Reset();
            _strengthCal.Reset();   // the removed slot carried the force peak too
            _mbAutoStrengthScale = 1f;
            _mbForceRawPeak = 0f;   // the old car's decaying peak is not evidence about this one
            _mbCalPeak = _mbAutoCalOn ? (float)_gripCal.EffectivePeak : 1f;
            _calConvergedLogged = false;
            _autoStrengthAnnounced = false;   // re-announce once it re-learns
            SimHub.Logging.Current.Info(
                $"[TF4ALL] Grip auto-cal reset for '{target}' (re-learn): peak back to {_gripCal.EffectivePeak:0.000}, confidence 0"
                + (_forceMode == ForceModeModeB
                    ? "; re-learning (auto strength included)."
                    : "; it re-learns once you drive a game running Telemetry Based FFB synthesis."));
        }

        // Mode B contention watchdog state (see DataUpdate). Warned resets on
        // Mode B re-engage so a fixed in-game setting re-arms the detector.
        private long _contentionSinceTicks;
        private long _contentionQuietSinceTicks;
        private bool _contentionWarned;
        /// <summary>True once sustained game FFB was detected during Mode B
        /// (diagnostic surface for the settings UI).</summary>
        public bool ModeBContentionDetected { get; private set; }

        // Mode B slip-starved fallback state. Latched on the FFB thread the
        // first time Mode B sits armed past the dwell with no slip telemetry
        // to synthesize from (MaybeReshapeFfb passes the game's tapped force
        // through meanwhile). Cleared on recovery, disarm, and game change.
        // The bools and the int are plain like the contention latch:
        // cross-thread races are benign (one extra or lost tick of a
        // diagnostic banner). The 64-bit stamp goes through Interlocked
        // (32-bit process; same rule as _lastSlipAngleTicks).
        private long _mbArmedTicks;      // stamped on every clean engage (Interlocked)
        private bool _slipStarvedWarned;
        // Consecutive live starved pass-through ticks (FFB thread only).
        // Debounces the warning: the unpause race can land a handful of
        // starved ticks on a healthy enhanced source (raceOn flips true a
        // few ms before the resume frame's slip stamp lands), and a false
        // "fix your Data Out" diagnosis on a correct setup is worse than a
        // late one on a broken setup.
        private int _starvedLiveTicks;
        private const int StarvedWarnAfterTicks = 250;   // ~250 ms at the 1 kHz provider
        private const double ModeBSlipStarvedAfterMs = 3000.0;
        // SimHub's own paused/menu/replay rollup, cached from DataUpdate for
        // the FFB thread's pass-through gate. The fallback source cannot see
        // Forza's raceOn; these flags are the only pause/replay signal that
        // exists there. (GameData.Spectating is obsolete in the SDK and
        // deliberately not included.)
        private volatile bool _gameNotDrivingState;
        /// <summary>True while Mode B is armed but slip telemetry is absent,
        /// so the game's tapped FFB is passed through (diagnostic surface for
        /// the settings UI banner).</summary>
        public bool ModeBSlipStarvedDetected { get; private set; }

        /// <summary>FFB thread. Called from MaybeReshapeFfb whenever Mode B is
        /// armed but has no slip telemetry to synthesize from. Latches the
        /// diagnostic flag and logs one actionable warning per starvation
        /// episode (a genuine recovery re-arms it), after an engage dwell
        /// plus a consecutive-live-tick debounce so a normal engage or an
        /// unpause race (the first slip frame lands a tick or two behind the
        /// session flag) can never false-positive.</summary>
        private void NoteModeBSlipStarved()
        {
            if (_starvedLiveTicks < int.MaxValue) _starvedLiveTicks++;
            if (_slipStarvedWarned) return;
            if (_starvedLiveTicks < StarvedWarnAfterTicks) return;
            long armed = System.Threading.Interlocked.Read(ref _mbArmedTicks);
            if (armed == 0
                || (Stopwatch.GetTimestamp() - armed) * 1000.0 / Stopwatch.Frequency
                    < ModeBSlipStarvedAfterMs) return;
            _slipStarvedWarned = true;
            ModeBSlipStarvedDetected = true;
            // A contention verdict latched during an earlier healthy phase is
            // stale advice now (it says to zero the game's FFB, which is the
            // only force the pass-through has): this diagnosis supersedes it.
            // Cross-thread bool stores, same benign-race class as the rest of
            // the latch state.
            _contentionWarned = false;
            ModeBContentionDetected = false;
            SimHub.Logging.Current.Warn(
                "[TF4ALL] Mode B FALLBACK: no tire-slip telemetry is reaching the plugin, "
                + "so there is nothing to synthesize steering force from; the game's own force "
                + "feedback (if the game is sending any) is passed through instead. Telemetry "
                + "Based FFB needs Forza's telemetry sent DIRECTLY to this plugin: give the "
                + "plugin its own Forza UDP port in the Settings tab (one no other app listens "
                + "on, SimHub included), point the game's Data Out at IP 127.0.0.1 with that "
                + "port, and enable the plugin's forwarding so SimHub keeps receiving telemetry.");
        }

        /// <summary>FFB thread. Clears the slip-starved latch once synthesis is
        /// genuinely running again (ramp above zero, so a transient ramp-out
        /// zero cannot flicker the banner).</summary>
        private void NoteModeBSlipRecovered()
        {
            _starvedLiveTicks = 0;
            if (!_slipStarvedWarned || _mbRamp <= 0f) return;
            _slipStarvedWarned = false;
            ModeBSlipStarvedDetected = false;
            SimHub.Logging.Current.Info(
                "[TF4ALL] Mode B slip telemetry restored; synthesized FFB is active again.");
        }

        /// <summary>Snapshot the loaded learner into the settings dict.
        /// Cheap (no disk I/O) — callers decide when settings actually save.</summary>
        private void FlushGripCal()
        {
            if (Settings == null || string.IsNullOrEmpty(_gripCalKey)) return;
            if (_gripCal.QualifyingSec <= 0.0
                && _strengthCal.QualifyingSec <= 0.0) return;   // never learned: don't pollute the dict
            // Structural dict mutation from the TELEMETRY thread: a new variant
            // key is an Add, which bumps the dictionary version and throws
            // "Collection was modified" inside any concurrent serialize
            // (PersistSettingsCore, BuildEnvelopeLocked, the account-switch
            // profile snapshot). Those all hold _carFactsLock; this is the
            // writer that was missing it, so the save it collided with was
            // silently lost. Monitor is reentrant and the body is allocation
            // only, so holding it here costs the telemetry thread nothing.
            lock (_carFactsLock)
            {
                if (Settings.CarGripCalibration == null)
                    Settings.CarGripCalibration = new Dictionary<string, CarGripCal>();
                Settings.CarGripCalibration[_gripCalKey] = new CarGripCal
                {
                    Peak          = (float)_gripCal.Peak,
                    QualifyingSec = (float)_gripCal.QualifyingSec,
                    ForcePeak     = (float)_strengthCal.Peak,
                    ForceQualSec  = (float)_strengthCal.QualifyingSec,
                };
            }
        }

        /// <summary>Swap the learner to the active VARIANT: flush the outgoing
        /// variant's state, then restore the incoming one (or start fresh).
        /// Keyed per variant, not per car, but the signature is ENGINE-derived
        /// (cyl + banded max rpm / redline): engine-visible tunes learn and
        /// store separately, while a tire-only tune keeps its slot and the
        /// learner re-converges in place (Re-learn car wipes it on demand).
        /// A null / empty variant signature (the car just changed
        /// and telemetry has not resolved the signature yet) parks the learner
        /// with no key until the variant-change detector calls again with the
        /// resolved signature. Runs only on the telemetry thread (the same one
        /// that Ticks the learner), so no cross-thread learner access.</summary>
        private void LoadGripCal(string game, string carId, string variantSig)
        {
            string key = (string.IsNullOrEmpty(carId) || string.IsNullOrEmpty(variantSig))
                ? null
                : (game ?? "") + "|" + carId + "|" + variantSig;
            if (key == _gripCalKey) return;
            FlushGripCal();
            _gripCalKey = key;
            // A queued reset is NOT dropped here any more. It carries the key it
            // was raised against, so it still finds the car the user named even
            // though FlushGripCal just wrote that car's calibration back out one
            // line above. Dropping it here meant a reset typed just before a car
            // change was silently undone by the flush it raced.
            CarGripCal saved = null;
            if (key != null) Settings?.CarGripCalibration?.TryGetValue(key, out saved);
            if (saved != null) _gripCal.Restore(saved.Peak, saved.QualifyingSec);
            else _gripCal.Reset();
            // Auto strength rides the same slot; ForcePeak 0 (older entries)
            // means never learned. Recompute the cached scale for the incoming
            // car immediately so the first ticks don't run the old car's scale.
            if (saved != null && saved.ForcePeak > 0f)
                _strengthCal.Restore(saved.ForcePeak, saved.ForceQualSec);
            else
                _strengthCal.Reset();
            _mbForceRawPeak = 0f;
            _mbAutoStrengthScale = _mbAutoStrengthOn
                ? (float)ModeBComposer.AutoStrengthScale(
                    _strengthCal.EffectivePeak, AutoStrengthTarget,
                    AutoStrengthMinScale, AutoStrengthMaxScale)
                : 1f;
            // Honor the adaptive-grip toggle, exactly like ApplyModeBFeel. With
            // auto-cal OFF the force path multiplies the manual Grip limit by
            // _mbCalPeak, so writing the learned peak here silently double-scaled
            // it on every car change (worse since the fresh-car nominal moved off
            // 1.0): the wheel came out lighter than the visible slider claimed.
            _mbCalPeak = _mbAutoCalOn ? (float)_gripCal.EffectivePeak : 1f;
            _mbGripPeakForRadius = (float)_gripCal.EffectivePeak;   // radius follows the new car's grip cal
            _calPrevTicks = 0;
            _calConvergedLogged = _gripCal.Confidence >= 1.0;
            // New car: say its auto strength once, restored slot or not.
            _autoStrengthAnnounced = false;
            if (saved != null)
                SimHub.Logging.Current.Info(
                    $"[TF4ALL] Grip auto-cal restored for '{key}': peak={_gripCal.Peak:0.000}, "
                    + $"confidence={_gripCal.Confidence:0.00}");
        }

        /// <summary>Push the persisted Mode B feel toggles into the live
        /// models. Called at Init after the models exist and from the settings
        /// UI on every checkbox change. These are global (not preset-scoped);
        /// the design's layers 1-5 and 12 live elsewhere on this branch as
        /// first-class effects (AxleSlip / KerbThump / LockupJudder) and
        /// DuckFrequencyAware, so this method deliberately does not touch
        /// them.</summary>
        public void ApplyModeBFeel(bool save = false)
        {
            var s = Settings;
            if (s == null) return;
            _mbCompressorOn = s.ModeBCompressor;
            _mbSuspLoadOn   = s.ModeBSuspensionLoad;
            // Early torque peak: plateau the SAT rise from 75% utilization
            // (real pneumatic trail peaks before the grip peak). 1.0 = legacy
            // shape. Lives on the model, so the grip limit and rise gamma still apply below it.
            _satModel.PlateauStartU = s.ModeBEarlyTorquePeak ? 0.75 : 1.0;
            // Road kick: reset on disable so a later re-enable can't
            // difference against week-old travel state.
            if (_mbRoadKickOn && !s.ModeBRoadKick) { _roadKick.Reset(); _mbKickCached = 0f; }
            _mbRoadKickOn  = s.ModeBRoadKick;
            _pRoadKickGain = s.ModeBRoadKickGain;
            // Reversal softening (drift-catch snap): toggle + strength, applied
            // live like the road-kick pair above.
            _mbReversalDampOn = s.ModeBReversalDamp;
            _pModeBReversalGain = s.ModeBReversalDampGain;
            // Phase lead (anticipation): toggle + lead time, applied live.
            _mbPhaseLeadOn = s.ModeBPhaseLead;
            _pModeBPhaseLeadMs = s.ModeBPhaseLeadMs;
            // Direct centering (PD spring): toggle + look-ahead, applied live.
            _mbCenterPdOn = s.ModeBCenterPd;
            _pModeBCenterLeadMs = s.ModeBCenterLeadMs < 0f ? 0f
                                : s.ModeBCenterLeadMs > 100f ? 100f : s.ModeBCenterLeadMs;
            // Per-car grip auto-cal. Off = nominal divisor (1.0); the learner
            // keeps accumulating either way so flipping it on later applies
            // everything learned so far.
            _mbAutoCalOn = s.ModeBGripAutoCal;
            _mbCalPeak = s.ModeBGripAutoCal ? (float)_gripCal.EffectivePeak : 1f;
            // Per-car auto strength: same shape as auto-cal (the learner keeps
            // accumulating either way; the toggle gates only the applied scale).
            _mbAutoStrengthOn = s.ModeBAutoStrength;
            _mbAutoStrengthScale = s.ModeBAutoStrength
                ? (float)ModeBComposer.AutoStrengthScale(
                    _strengthCal.EffectivePeak, AutoStrengthTarget,
                    AutoStrengthMinScale, AutoStrengthMaxScale)
                : 1f;
            // Friction circle: on a toggle, seed the INCOMING law's EMA from the
            // live ratio so its first gated tick eases in instead of stepping
            // from a value the other branch left frozen (each branch's EMA stops
            // updating while the other runs).
            if (!_mbFrictionCircleOn && s.ModeBFrictionCircle)
                _mbCircleRatioEma = _lastFrontSlipRatioAbs;
            else if (_mbFrictionCircleOn && !s.ModeBFrictionCircle)
                _mbLockRatioEma = _lastFrontSlipRatio;
            _mbFrictionCircleOn = s.ModeBFrictionCircle;
            _mbBrakeLearnOn = s.ModeBLongitudinalGripLearn;
            _mbLateralDemandOn = s.ModeBLateralDemand;

            if (save) PersistSettings();
        }

        /// <summary>Per-wheel Mode B defaults, layered ON TOP of the coded
        /// factory values (which ARE the G PRO defaults). The table (owner
        /// 2026-08-07): strength 0.50 / 0.60 / 1.00 for G PRO / RS50 / G923;
        /// min force 0.05 for all three; G923 damping held at its gen-2 value
        /// 0.09 (chosen for the belt's own friction; the G PRO factory damping
        /// later moved below it to 0.07). Weight buildup is 0.80 for every
        /// wheel and lives in the factory values, not here.
        ///
        /// The G923's own strength (1.25) and stiction floor (0.25) are RETIRED
        /// as of this generation, on the owner's retune. The floor was set on
        /// the theory that a belt drive swallows the smallest commanded
        /// torques, so the model's light states needed lifting to stay
        /// perceptible; the wheel now takes the same 0.05 as the others.
        /// Damping is the only thing still separating the G923 from the G PRO.
        ///
        /// The table also carries the Trueforce master gain (1.5 on the G923,
        /// the factory 1.0 elsewhere), but that field is read ONLY by the
        /// fresh-install seed on first wheel detection. It is not in
        /// ModeBRecipeFields, so the defaults merge never moves it, and
        /// "Reset FFB tuning to defaults" does not copy it: an existing
        /// user's gain is theirs and is never changed under them.
        ///
        /// Used by "Reset FFB tuning to defaults" (wheel-aware) and by the one-time
        /// fresh-install specialization on wheel detection.</summary>
        public static void ApplyWheelDefaults(TrueforceSettings s, string wheelModel)
        {
            if (s == null) return;
            switch ((wheelModel ?? "").Trim())
            {
                case "RS50":
                    s.ModeBSatGain  = 0.60f;   // "Strength": RS50 defaults
                    break;
                case "G923":
                    // Trueforce master gain (owner call 2026-09-15): the belt
                    // motor renders the haptic stream fainter than the direct
                    // drives, so the G923 starts at 1.5 where every other
                    // wheel starts at the factory 1.0. Global, not preset
                    // scoped, so a built-in preset applied on a G923 inherits
                    // it (presets never carry MasterGain). Read only by the
                    // fresh-install seed; never merged onto an existing setup.
                    s.MasterGain    = 1.5f;
                    s.ModeBSatGain  = 1.00f;   // "Strength": headroom on the weaker motor, retuned down from 1.25
                    s.ModeBDamper   = 0.09f;   // belt friction already damps; two clicks under the G PRO
                    // Min force is NOT set here any more: the G923 takes the
                    // factory 0.05 like every other wheel.
                    // FS spring floor (owner call 2026-08-09): the belt
                    // motor's friction eats FS's light spring and terrain
                    // cues; every other wheel ships 0.
                    s.SpringModeMinForce = 0.15;
                    // FS spring strength stays where it was when the factory
                    // value dropped to 0.80 for the direct-drive wheels
                    // (owner call 2026-08-10). Same reasoning as the floor
                    // above: the belt eats what the G PRO delivers, so it
                    // keeps the headroom rather than following the retune.
                    s.SpringModeStrength = 1.0;
                    // Effect-bench render gains (owner call 2026-09-22, from a
                    // G923 owner's bench session). These are calibration for
                    // the condition renderer rather than a taste setting, so
                    // they join the defaults merge and move an install that
                    // never deliberately tuned them.
                    //
                    // Inertia: the tester settled on 0.50. Their waveform
                    // number came in at 1.2 where the owner judged 1.0 right,
                    // so the same correction puts inertia near 0.42 and it
                    // ships at 0.40. That is four times the G PRO's 0.10,
                    // which still sits under the torque ratio between the two
                    // wheels, so it is the conservative end of the reading.
                    s.FfbConditionInertiaGain  = 0.40;
                    // Waveform: the tester's 1.2 taken down to the owner's
                    // 1.0, against the factory 0.9 the direct drives use.
                    s.FfbConditionPeriodicGain = 1.00;
                    break;
                // G PRO (and anything unrecognized): the coded defaults stand.
            }
        }

        /// <summary>Bump when the shipped Mode B recipe (factory values or the
        /// per-wheel defaults table) changes: the wheel-defaults latch embeds this,
        /// so every latched install re-evaluates once on the new build. The merge is
        /// PER FIELD: fields still on any shipped default move to the new values,
        /// fields the user tuned stay theirs. When bumping, move the outgoing recipe
        /// (including its per-wheel variants) into PreviousShippedModeBRecipes so it
        /// stays recognized as a shipped default. Generation 1 = the beta
        /// 0.2.0-0.2.4 recipe; generation 2 = the 2026-08-01 morning drift
        /// recipe + G PRO/RS50/G923 table; generation 3 = the 2026-08-01
        /// evening re-snapshot of the owner's wheel (strength 0.50 / 0.60 /
        /// 1.25 plus the retuned feel values); generation 4 = the 2026-08-02
        /// slide-feel clear-out (countersteer, its growth option, the trail spring
        /// and the centering ease all removed after on-wheel testing). No SURVIVING
        /// field's target moved between 3 and 4 (those fields were deleted rather
        /// than retuned), but the number is still bumped: it is
        /// monotone by contract and the recipe's SHAPE changed, so an install that
        /// re-evaluates once on the new build costs nothing and keeps the latch
        /// honest. Generation 5 = the 2026-08-07 G923 retune (strength 1.25 to
        /// 1.00, min force 0.25 back to the shared 0.05). Generation 6 = the
        /// 2026-08-09 FS spring recipe: the SpringMode* fields joined the merge
        /// list, factory = the owner's tuned values (enhancements ON, firmness
        /// 0.85, speed effect 0.70, strain 0.50, min force 0 with the G923 at
        /// 0.15 per wheel). Generation 7 = the 2026-08-10 FS strength
        /// re-snapshot: SpringModeStrength 1.0 to 0.80, the owner's own G PRO
        /// value, with the G923 pinned at the outgoing 1.0 in the per-wheel
        /// table so the belt wheel keeps its headroom. The 2026-09-15 G923
        /// master gain did NOT bump this: it is seeded on fresh installs only
        /// and never merged, so no latched install needs to re-evaluate.
        /// Generation 8 = the 2026-09-22 effect-bench gains: FfbConditionInertiaGain
        /// and FfbConditionPeriodicGain joined the merge list, factory stays the
        /// owner's G PRO calibration (0.10 and 0.9) and the G923 carries 0.40 and
        /// 1.00 from a G923 owner's bench session.</summary>
        private const int ModeBDefaultsGeneration = 8;

        /// <summary>True when this session started with no settings file for us
        /// (see Init). Gates first-run-only defaults such as the per-wheel
        /// starting master gain.</summary>
        private bool _wasFreshInstall;

        /// <summary>Recipes an UNTOUCHED install may legitimately hold besides the
        /// current factory values: every previously SHIPPED defaults-set, expressed
        /// in the CURRENT settings model (fields a build lacked deserialize to the
        /// current initializers, exactly like that build's JSON loading today). Lets
        /// the wheel-defaults hook upgrade never-customized users to each new
        /// defaults generation instead of stranding them on the old shipped feel;
        /// anyone who moved any slider stays untouched, as always.</summary>
        private static IEnumerable<TrueforceSettings> PreviousShippedModeBRecipes()
        {
            // Beta v0.2.0 through v0.2.4 (verified identical across them in git; the
            // stable channel never shipped Mode B). Only the fields whose defaults
            // differ from the current factory values need overrides.
            yield return new TrueforceSettings
            {
                ModeBSatGain      = 1.0f,
                ModeBRiseGamma    = 0.5f,
                ModeBDropFloor    = 0.20f,
                ModeBDamper       = 0.15f,
                ModeBCenter      = 0.10f,
                ModeBDirSoft      = 0.12f,
                ModeBRoadKickGain = 1.0f,
            };
            // FS spring strength as shipped through generation 6. One field, so
            // it gets its own entry: the merge compares PER FIELD against any
            // entry, and every other generation-6 value is still current.
            // Without this, a G PRO sitting on the shipped 1.0 would read as
            // user-tuned and never receive the 0.80 retune. The G923 is
            // unaffected either way, since its per-wheel target is still 1.0
            // and the merge finds it already there.
            yield return new TrueforceSettings { SpringModeStrength = 1.0 };
            // The 2026-08-08 FS spring factory (generations <= 5): the
            // enhancement toggles shipped OFF and the feel values pre-date
            // the owner's tuned recipe. Only fields whose defaults differ
            // from the current factory carry overrides.
            yield return new TrueforceSettings
            {
                SpringModeCenterFirmness       = 0.5,
                SpringModeSpeedEffect          = 0.65,
                SpringModeMinForce             = 0.05,
                SpringModeTerrainEnabled       = false,
                SpringModeDragEnabled          = false,
                SpringModeDragStrainFraction   = 0.35,
                SpringModeChassisWeightEnabled = false,
            };
            // Generation 2 (the 2026-08-01 morning drift recipe; dev/test
            // builds only, never in a published release): the fields that
            // differ from the gen-3 evening re-snapshot. One entry carries
            // them all (the merge compares per field against ANY entry).
            // Beta lacked the recover/lead/duck/center-lead fields entirely
            // (they deserialize to the current initializers = the target, so
            // they need no coverage). The RS50 strength variant gets its own
            // entry; the G923 variant (1.25/0.25/0.09) was identical through
            // generations 2 to 4 and is archived by the last entry below, now
            // that generation 5 has retuned it.
            yield return new TrueforceSettings
            {
                ModeBSatGain            = 0.80f,
                ModeBDamper             = 0.13f,
                ModeBCenter             = 0.20f,
                ModeBLockupRecoverMs    = 32f,
                ModeBRoadKickGain       = 0.6994894f,
                ModeBPhaseLeadMs        = 20f,
                ModeBCenterLeadMs       = 30f,
            };
            yield return new TrueforceSettings { ModeBSatGain = 0.90f };
            // The G923 variant as shipped in generations 2 through 4 (strength
            // 1.25, min force 0.25; damping 0.09 is unchanged in 5 and still
            // comes from the live table). Without this a G923 latched at any of
            // those generations reads as USER-TUNED on both fields, because the
            // prior-latch path rebuilds the old recipe by calling the CURRENT
            // ApplyWheelDefaults, which now returns the new values. It would
            // then keep 1.25/0.25 forever instead of upgrading. This entry is
            // what makes the retune actually reach untouched G923 installs.
            yield return new TrueforceSettings
            {
                ModeBSatGain  = 1.25f,
                ModeBMinForce = 0.25f,
            };
            // The 2026-08-02 dev builds only (never published): the slide gate was
            // a hard cap at 1.0 before on-wheel logging showed the excess spanning
            // 0.4 to 62 and forced the soft saturation. Only a machine that ran one
            // of that day's builds can hold a stored 1.0, and it means "the old
            // default" rather than a considered choice.

            // Dev builds only: the effect-bench inertia gain before it was
            // retuned to the current 0.10. These fields have never appeared in
            // a published release, so only a dev or beta machine can hold the
            // older number, and it means "the old default" rather than a bench
            // session's result.
            yield return new TrueforceSettings { FfbConditionInertiaGain = 0.15 };
        }

        // The Mode B recipe fields the defaults machinery owns (every tunable +
        // feel toggle; ModeBGameEnabled is per-user, not recipe). Drives the
        // per-field defaults merge, so a field added to the recipe only needs
        // listing here plus its initializer.
        // NOTE: MasterGain is deliberately NOT a recipe field. The wheel table
        // carries a master gain (the G923's 1.5), but it is seeded on a FRESH
        // INSTALL only, never merged: master gain is the control users reach
        // for constantly, and 1.0 is a value plenty of people chose on purpose,
        // so the merge could not tell "untouched" from "deliberately 1.0".
        private static readonly string[] ModeBRecipeFields =
        {
            "ModeBSatGain", "ModeBRiseGamma", "ModeBPeakUtil", "ModeBDropFloor",
            "ModeBEmaMs", "ModeBSign", "ModeBDamper", "ModeBCenter",
            "ModeBLatGain", "ModeBDirSoft",
            "ModeBLockupRecoverMs", "ModeBLockupPoint", "ModeBMinForce",
            "ModeBCompressor", "ModeBSuspensionLoad", "ModeBEarlyTorquePeak",
            "ModeBRoadKick", "ModeBRoadKickGain",
            "ModeBReversalDamp", "ModeBReversalDampGain",
            "ModeBPhaseLead", "ModeBPhaseLeadMs",
            "ModeBCenterPd", "ModeBCenterLeadMs",
            "ModeBGripAutoCal", "ModeBFrictionCircle",
            "ModeBLongitudinalGripLearn", "ModeBGripTrim", "ModeBLateralDemand",
            "ModeBAutoStrength",
            // FS spring recipe (joined the merge with generation 6, when the
            // owner's tuned values became the shipped factory).
            "SpringModeStrength", "SpringModeMinForce",
            "SpringModeCenterGain", "SpringModeCenterFirmness", "SpringModeSpeedEffect",
            "SpringModeTerrainEnabled", "SpringModeTerrainGain",
            "SpringModeDragEnabled", "SpringModeDragGain", "SpringModeDragStrainFraction",
            "SpringModeChassisWeightEnabled", "SpringModeChassisWeightGain",
            // Effect-bench render gains (joined the merge with generation 8).
            // The bench itself is behind an access code, so an install holding
            // a shipped value here has never been tuned and should follow the
            // calibration; anyone who did set one on the bench keeps it, the
            // same contract every other field in this list carries.
            "FfbConditionInertiaGain", "FfbConditionPeriodicGain",
        };

        // Per-field defaults merge: every recipe field in <paramref name="s"/> still
        // holding a SHIPPED default value (any entry in <paramref name="oldRecipes"/>)
        // moves to <paramref name="target"/>'s value; fields the user moved keep their
        // values. So a user who only tuned Strength still receives every other new
        // default, and a fully tuned setup is untouched. Exact equality on purpose:
        // these fields are only written by initializers, sliders, codes, and
        // ApplyWheelDefaults, so any user write moves them off the coded constants
        // bit-for-bit. (Inherent ambiguity, accepted: a user who deliberately dialed
        // a value that EQUALS an old shipped default reads as untouched for that
        // field and rides along to the new default.) Returns the upgraded count.
        private static int MergeWheelDefaults(TrueforceSettings s, TrueforceSettings target,
                                              System.Collections.Generic.List<TrueforceSettings> oldRecipes)
        {
            if (s == null || target == null) return 0;
            int upgraded = 0;
            foreach (var name in ModeBRecipeFields)
            {
                var p = typeof(TrueforceSettings).GetProperty(name);
                if (p == null)
                {
                    SimHub.Logging.Current.Warn("[TF4ALL] Defaults merge: unknown recipe field " + name);
                    continue;
                }
                object cur = p.GetValue(s);
                object tgt = p.GetValue(target);
                if (Equals(cur, tgt)) continue;             // already on the new default
                bool wasShippedDefault = false;
                foreach (var old in oldRecipes)
                {
                    if (Equals(cur, p.GetValue(old))) { wasShippedDefault = true; break; }
                }
                if (wasShippedDefault)
                {
                    p.SetValue(s, tgt);
                    upgraded++;
                }
            }
            return upgraded;
        }

        /// <summary>Reset the Telemetry Based FFB (Mode B) tuning recipe to the
        /// shipped defaults for the detected wheel: every tunable slider and
        /// feel-feature toggle back to the coded factory values plus the
        /// wheel's own defaults on top (ApplyWheelDefaults: G PRO / RS50 /
        /// G923 each have their own strength, the G923 also a min-force
        /// floor). Deliberately leaves the per-game enable (ModeBGameEnabled)
        /// and each car's learned grip calibration (CarGripCalibration)
        /// untouched. Applies live and persists. Defaults are read from a
        /// fresh TrueforceSettings so this can never drift from the model's
        /// initializers.</summary>
        /// <summary>Restore the shipped tuning for the family the ACTIVE GAME
        /// uses, and only that family. Farming Simulator drives the SpringMode*
        /// recipe, the Forza titles drive the ModeB* one, and the two never
        /// share a field, so resetting in FS must leave a Forza setup exactly
        /// as its owner left it (owner call 2026-08-10). With no game running
        /// the Forza family is the one on screen, so that is what resets.</summary>
        public void ResetModeBTuningToDefaults()
        {
            var s = Settings;
            if (s == null) return;
            // The wheel's shipped baseline for BOTH families, built on a scratch
            // instance: ApplyWheelDefaults writes Forza AND spring values (a G923
            // gets its own damping and its own FS floor and strength), so running
            // it against the live settings would clobber the family we are meant
            // to leave alone.
            var d = new TrueforceSettings();
            ApplyWheelDefaults(d, s.LastUsedWheel);

            if (IsSpringModeGame(_activeGame))
            {
                s.SpringModeStrength             = d.SpringModeStrength;
                s.SpringModeMinForce             = d.SpringModeMinForce;
                s.SpringModeCenterGain           = d.SpringModeCenterGain;
                s.SpringModeCenterFirmness       = d.SpringModeCenterFirmness;
                s.SpringModeSpeedEffect          = d.SpringModeSpeedEffect;
                s.SpringModeTerrainEnabled       = d.SpringModeTerrainEnabled;
                s.SpringModeTerrainGain          = d.SpringModeTerrainGain;
                s.SpringModeDragEnabled          = d.SpringModeDragEnabled;
                s.SpringModeDragGain             = d.SpringModeDragGain;
                s.SpringModeDragStrainFraction   = d.SpringModeDragStrainFraction;
                s.SpringModeChassisWeightEnabled = d.SpringModeChassisWeightEnabled;
                s.SpringModeChassisWeightGain    = d.SpringModeChassisWeightGain;
            }
            else
            {
                s.ModeBSatGain     = d.ModeBSatGain;
                s.ModeBRiseGamma   = d.ModeBRiseGamma;
                s.ModeBPeakUtil    = d.ModeBPeakUtil;
                s.ModeBDropFloor   = d.ModeBDropFloor;
                s.ModeBEmaMs       = d.ModeBEmaMs;
                s.ModeBSign        = d.ModeBSign;
                s.ModeBDamper      = d.ModeBDamper;
                s.ModeBCenter      = d.ModeBCenter;
                s.ModeBLatGain     = d.ModeBLatGain;
                s.ModeBDirSoft     = d.ModeBDirSoft;
                s.ModeBLockupRecoverMs = d.ModeBLockupRecoverMs;
                s.ModeBLockupPoint     = d.ModeBLockupPoint;
                s.ModeBMinForce        = d.ModeBMinForce;
                s.ModeBCompressor         = d.ModeBCompressor;
                s.ModeBSuspensionLoad     = d.ModeBSuspensionLoad;
                s.ModeBEarlyTorquePeak    = d.ModeBEarlyTorquePeak;
                s.ModeBRoadKick           = d.ModeBRoadKick;
                s.ModeBRoadKickGain       = d.ModeBRoadKickGain;
                s.ModeBReversalDamp       = d.ModeBReversalDamp;
                s.ModeBReversalDampGain   = d.ModeBReversalDampGain;
                s.ModeBPhaseLead          = d.ModeBPhaseLead;
                s.ModeBPhaseLeadMs        = d.ModeBPhaseLeadMs;
                s.ModeBCenterPd           = d.ModeBCenterPd;
                s.ModeBCenterLeadMs       = d.ModeBCenterLeadMs;
                s.ModeBGripAutoCal        = d.ModeBGripAutoCal;
                s.ModeBAutoStrength       = d.ModeBAutoStrength;
                s.ModeBFrictionCircle     = d.ModeBFrictionCircle;
                s.ModeBLongitudinalGripLearn = d.ModeBLongitudinalGripLearn;
                s.ModeBGripTrim              = d.ModeBGripTrim;
                s.ModeBLateralDemand         = d.ModeBLateralDemand;
            }
            ApplyModeBFromSettings();
            ApplyModeBFeel();
            PersistSettings();
        }

        /// <summary>Put FFB spike reduction back to the shipped defaults: the
        /// on/off gate, the method, and BOTH methods' tuning. Global (not
        /// preset-scoped), so unlike the Mode B reset there is no game family to
        /// pick between. The per-section revert button next to the expander
        /// restores the active PRESET's values, which left no route back to the
        /// shipped ones once a preset had saved something else.</summary>
        public void ResetSpikeReductionToDefaults()
        {
            var s = Settings;
            if (s == null) return;
            var d = new TrueforceSettings();
            s.FfbSpikeTamingEnabled   = d.FfbSpikeTamingEnabled;
            s.FfbSpikeUseSlewLimiter  = d.FfbSpikeUseSlewLimiter;
            s.FfbSpikeMaxLsbPerMs     = d.FfbSpikeMaxLsbPerMs;
            s.FfbPeakSoftLimitLsb     = d.FfbPeakSoftLimitLsb;
            // Explicit, not d's null: the seed only runs at load, so copying a
            // fresh instance's null would leave the peak limiter falling back to
            // the rate value again, which is the trap the split removed.
            s.FfbSpikeTransientThresholdLsb = TrueforceSettings.DefaultSpikeTransientThresholdLsb;
            if (_device != null)
            {
                _device.FfbSpikeTamingEnabled  = s.FfbSpikeTamingEnabled;
                _device.FfbSpikeUseSlewLimiter = s.FfbSpikeUseSlewLimiter;
                _device.FfbSpikeMaxLsbPerMs    = s.FfbSpikeMaxLsbPerMs;
                _device.FfbPeakSoftLimitLsb    = s.FfbPeakSoftLimitLsb;
                _device.FfbSpikeTransientThresholdLsb = s.EffectiveSpikeTransientThresholdLsb;
            }
            PersistSettings();
        }

        /// <summary>True while a Farming Simulator title is the active game, i.e.
        /// while spring mode owns the force and the SpringMode* recipe is what the
        /// Telemetry FFB tab is showing.</summary>
        public static bool IsSpringModeGame(string game)
        {
            return !string.IsNullOrEmpty(game)
                && game.StartsWith("FarmingSimulator", StringComparison.Ordinal);
        }

        /// <summary>Seed the FFB-thread Mode B smoothing state from the latest
        /// telemetry on a clean 0->1 engage, so the first tick eases from live
        /// values instead of stepping from stale ones. Kept as the one engage
        /// seed (ApplyModeBFromSettings calls it) so a second engage site can
        /// never drift, which is how the lockup/circle EMAs were once missed on
        /// the production path.</summary>
        private void SeedModeBEngageState()
        {
            _mbRamp = 0f;
            _mbPrevTicks = 0;
            // Arming timestamp for the slip-starved warning's engage dwell
            // (NoteModeBSlipStarved): a normal engage sees its first slip
            // frame within a tick or two, so only a feed that stays absent
            // for ModeBSlipStarvedAfterMs past this point warns. Interlocked
            // like the other cross-thread tick stamps (32-bit process, torn
            // 64-bit reads). The debounce counter restarts with the dwell.
            System.Threading.Interlocked.Exchange(ref _mbArmedTicks, Stopwatch.GetTimestamp());
            _starvedLiveTicks = 0;
            _mbSlipEma = _lastFrontSlipAngle;
            _mbPrevSlipEma = _lastFrontSlipAngle;   // so the first reversal-rate sample is ~0, not a step
            _mbSlipRateEma = 0f;
            _mbGripEma = _lastFrontCombined;
            _mbLockRatioEma = _lastFrontSlipRatio;
            _mbCircleRatioEma = _lastFrontSlipRatioAbs;
        }

        private short? ComputeModeBForce()
        {
            long now = Stopwatch.GetTimestamp();
            long stamp = System.Threading.Interlocked.Read(ref _lastSlipAngleTicks);
            if (stamp == 0) return null;                    // never saw telemetry: keepalive

            double dtMs = _mbPrevTicks == 0 ? 1.0 : (now - _mbPrevTicks) * 1000.0 / Stopwatch.Frequency;
            if (dtMs < 0.1) dtMs = 0.1; else if (dtMs > 50.0) dtMs = 50.0;
            _mbPrevTicks = now;

            // Stall ramp: fresh telemetry ramps force in over ~250 ms; stale
            // (>150 ms without a slip sample) ramps out over ~100 ms. Never a
            // step. This also gives a Mode B engage a soft start from zero.
            double ageMs = (now - stamp) * 1000.0 / Stopwatch.Frequency;
            _mbRamp += ageMs > 150.0 ? (float)(-dtMs / 100.0) : (float)(dtMs / 250.0);
            if (_mbRamp < 0f) _mbRamp = 0f; else if (_mbRamp > 1f) _mbRamp = 1f;
            // Slip feed dead past the dwell = the active source cannot provide
            // slip at all (the 2026-08-13 RS50/FH6 report: Forza UDP bind lost
            // to a port conflict, SimHub fallback carries no slip), not a menu
            // blip. Null hands the decision to MaybeReshapeFfb's starved
            // branch, which passes the game's tapped force through ONLY while
            // the session is provably live and holds zero otherwise (pauses,
            // fast travel, and UDP halts must not replay the tap's frozen
            // force; the reasoning lives at that branch). Short stalls keep
            // the ramp-out zero below.
            if (ageMs > ModeBSlipStarvedAfterMs) return null;
            if (_mbRamp <= 0f) return 0;

            // Smooth the INPUTS, not the force (the validated reshape
            // principle). ModeBEmaMs raises the time constant when the game's slip
            // signals are noisy.
            float alpha = (float)(1.0 - Math.Exp(-dtMs / Math.Max(2f, _pModeBEmaMs)));
            _mbSlipEma += (_lastFrontSlipAngle - _mbSlipEma) * alpha;
            // Slip-angle rate off the smoothed signal, then a short EMA to tame the
            // finite-difference noise (the input EMA already pre-smooths the slip). Feeds the
            // reversal-softening gate below; ~0 in steady cornering, large only when
            // a slide is being caught fast.
            double slipRate = (_mbSlipEma - _mbPrevSlipEma) * 1000.0 / dtMs;   // rad/s
            _mbPrevSlipEma = _mbSlipEma;
            _mbSlipRateEma += (float)((slipRate - _mbSlipRateEma) * (1.0 - Math.Exp(-dtMs / 12.0)));
            // Front grip EMA is ASYMMETRIC (fifth wheel test: "when I catch
            // traction again on my front wheels it snaps very hard"). Rising
            // utilization (breaking away) tracks fast — the go-light cue must
            // be instant. FALLING utilization (re-gripping) is slowed 4x so
            // the drop factor climbs back from DropFloor over ~150 ms instead
            // of stepping: weight returns like a tire reloading, not a slam.
            // Physically this is pneumatic trail rebuilding over the tire's
            // relaxation length, which is not instantaneous either.
            float gripAlpha = _lastFrontCombined >= _mbGripEma
                ? alpha
                : (float)(1.0 - Math.Exp(-dtMs / (4.0 * Math.Max(2f, _pModeBEmaMs))));
            _mbGripEma += (_lastFrontCombined - _mbGripEma) * gripAlpha;

            // Direction blend through center, v4. v1 hard sign() = spazz;
            // v2 linear ramp = noise spring at center (buzz + hands-off
            // ring, sixth test); v3 smoothstep = flat center but a 1.5×
            // mid-band wall that made ±3° rocking jumpy (seventh test).
            // v4 rational curve: zero slope at exact center only, near-
            // linear body. BDIRK tunes the softness live (0 = pure linear).
            //
            // Direction-ramp window, fixed at 0.03. The "trail spring" widened it
            // during a slide so dir would stay proportional rather than saturating;
            // on-wheel logging 2026-08-02 proved it never once acted, with the front
            // slip beyond the window in 50 of 50 samples at every setting tried.
            // Root cause: this 0.03 is not 1.7 deg. FrontSlipAngleRad carries Forza's
            // TireSlipAngle, which is NORMALISED slip (~1.0 = the tire's peak slip
            // angle), not radians, so the window is really 3% of peak slip and dir
            // has always been sign(slip) in anything but a straight line. Retired
            // 2026-08-02; the full account is in the ModeBComposer header. Nothing
            // else reads the magnitude, which is why the model is unaffected: force
            // SIZE comes from u (combined slip), whose units are right.
            const double dirWindow = 0.03;
            // Phase lead ("Anticipation" toggle): push the slip angle forward by its rate so dir
            // anticipates where the wheel is heading, recovering the telemetry-loop
            // lag that otherwise makes the spring ring near its target (worst on a
            // hands-off release). Uses the already-smoothed rate; sign-safe.
            double slipForDir = _mbPhaseLeadOn
                ? ModeBComposer.PhaseLeadSlip(_mbSlipEma, _mbSlipRateEma, _pModeBPhaseLeadMs * 0.001)
                : _mbSlipEma;
            double dir = ModeBComposer.CenterSoftDir(
                slipForDir * _pModeBSign / dirWindow, _pModeBDirSoft);

            // Utilization from the game's grip metric: combined slip with
            // ~1.0 = at the limit. ModeBPeakUtil rescales where we treat the limit;
            // grip auto-cal multiplies in the per-car learned ceiling (1.0
            // until the learner has near-limit seat time in THIS car). The
            // noise floor zeroes the fuzz the grip channel emits parked /
            // dead straight, the other half of the center-buzz fix.
            // When the per-car learner owns the ceiling (adaptive/auto-cal on),
            // the manual grip-limit slider (ModeBPeakUtil) is hidden in the UI and must
            // NOT also scale the learned peak, or a stale slider value silently
            // double-scales it. Learned peak alone when adaptive; the manual
            // slider applies only in manual mode (auto-cal off, _mbCalPeak = 1).
            double peakBase = _mbAutoCalOn ? 1.0 : _pModeBPeakU;
            double peakDiv = Math.Max(0.2, peakBase * (double)_mbCalPeak);
            double u     = ModeBComposer.UtilizationFloor(_mbGripEma     / peakDiv);
            // Published for the dash's friction-circle box: how much of the
            // tyre's grip this model thinks is in use (1.0 = at the limit).
            // Display only, written once per FFB tick.
            _mbLastUtil = (float)u;
            // Lateral-demand utilization (issue #38 loop root-cause A/B): weight
            // the front SAT grip reading by |dir| so it tracks LATERAL (cornering)
            // grip, not combined slip. |dir| is ~0 with no lateral slip and ~1 in
            // a corner, so under straight-line braking - where combined slip is
            // pumped high by longitudinal lockup - u collapses toward zero: no
            // phantom aligning force, so the direction-feedback loop has nothing
            // to swing the wheel with. Cornering (|dir| ~ 1) is unchanged, and the
            // force stays super-linear in dir at center so the loop gain there is
            // zero (it cannot self-excite from noise).
            if (_mbLateralDemandOn) u *= Math.Abs(dir);

            // Load, v1: longitudinal weight transfer only — braking (surge < 0)
            // loads the front axle, throttle unloads it. ~0.35 of static per g.
            double load01 = 1.0 - 0.35 * (_lastSurgeAccel / 9.81);
            // Suspension-load feel: real front load from suspension compression
            // vs learned ride height replaces the surge approximation — dive,
            // kerb strikes and crests breathe through the steering weight.
            if (_mbSuspLoadOn)
            {
                double r = _lastFrontSuspRatio;
                if (r < 0.4) r = 0.4; else if (r > 1.8) r = 1.8;
                load01 = r;
            }

            double sat = _satModel.Force01(u, 1.0, load01, _lastSpeedKmh) * dir;
            double trail = Math.Min(Math.Max((double)_lastSpeedKmh, 0.0) / Math.Max(1.0, _satModel.SpeedFullKmh), 1.0);
            double f01 = ModeBComposer.Compose(
                sat, latG: Math.Abs(_lastSwayAccel) / 9.81, latGain: _pModeBLatGain);
            // Road kick: one-wheel bump kick, a signed transient in the
            // FORCE channel (the whole rim moves — this is a steering event,
            // not texture). Short EMA melts the 60 Hz telemetry staircase;
            // trail-gated so a parked car on a kerb edge stays quiet. Added
            // BEFORE the compressor so the compressor owns the ceiling.
            if (_mbRoadKickOn)
            {
                float kickAlpha = (float)(1.0 - Math.Exp(-dtMs / 8.0));
                _mbKickEma += (_mbKickCached - _mbKickEma) * kickAlpha;
                f01 += _mbKickEma * _pRoadKickGain * 0.5 * trail;
            }
            // Per-car auto strength. MEASURE the car's INTRINSIC force ceiling:
            // the pre-scale force with the Strength slider divided out, so the
            // learner sees what the CAR produces, not what the user dialed.
            // Measuring downstream of SatGain would turn the loop into an
            // absolute-target controller that cancels the Strength slider and
            // the per-wheel strength defaults (adversarial review of this
            // feature proved it), and every stored peak would go stale on a
            // Strength change; intrinsic units keep the slider as the real
            // baseline and the stored peaks valid across retunes. Decaying max
            // (~140 ms half-life at the 1 kHz tick) so the 60 Hz telemetry
            // sampling can't miss inter-sample peaks. Measuring before the
            // scale multiply is load-bearing: feeding the loop its own output
            // converges to only sqrt of the correction. Before the compressor
            // on purpose: it keeps shaping the top of whatever the scale makes.
            {
                float satGainNow = (float)_satModel.SatGain;
                if (satGainNow < 0.05f) satGainNow = 0.05f;
                float rawAbs = (float)Math.Abs(f01) / satGainNow;
                float held = _mbForceRawPeak * 0.995f;
                _mbForceRawPeak = rawAbs > held ? rawAbs : held;
            }
            if (_mbAutoStrengthOn) f01 *= _mbAutoStrengthScale;
            if (_mbCompressorOn) f01 = _mbCompressor.Apply(f01);   // soft-knee compressor
            // Low-speed validity gate (twelfth wheel test: stuck off-road at
            // crawl speed, slip signals garbage, force buzzing the rim).
            // Kills ALL slip-derived synthesis below walking pace; identical
            // from 20 km/h up. Centering/damper live outside f01 and keep
            // their own behavior.
            double lowGate = ModeBComposer.LowSpeedGate(_lastSpeedKmh);
            f01 *= lowGate;
            // Braking-lockup gate (issue #38): u is combined slip, so a locking
            // front tire pumps it to peak and drives the aligning force to full
            // scale. Under heavy brake/slide that near-peak force, with the laggy
            // direction relay and little velocity damping, swings the wheel left
            // and right. Physically a locked/hard-sliding front makes almost no
            // aligning torque, so fade the composed force (SAT + counter) out as
            // the fronts lock. The gate/circle thresholds scale with the
            // braking-grip point (lockL below: manual BLOCKPT or the learned
            // knee), not fixed to the texture gate's. Asymmetric smoothing:
            // track FAST as grip is being spent
            // (lockup/spin onset) so the mute lands promptly, but recover SLOWLY
            // ("Lockup recovery" slider) as grip returns so the force
            // eases back like a reloading tire instead of snapping from light to
            // heavy (owner on-wheel note); same re-grip philosophy as the grip
            // EMA. A/B (ModeBFrictionCircle): the friction-circle law replaces
            // the gate; |slip ratio| spends the one grip budget (wheelspin too)
            // and the force scales by the lateral share left, no threshold.
            // Radius (slip ratio where the tyre is fully spent) for both laws:
            // the per-car grip-cal peak times the trim when the toggle is on
            // (trim 1 = the raw detected grip), else the manual BLOCKPT point.
            // The grip cal fades from ~1.0 by confidence, so a fresh car eases in.
            double lockL = _mbBrakeLearnOn ? _pModeBGripTrim * _mbGripPeakForRadius : _pModeBLockupPoint;
            if (lockL < 0.2) lockL = 0.2; else if (lockL > 2.0) lockL = 2.0;
            if (_mbFrictionCircleOn)
            {
                float circRaw = _lastFrontSlipRatioAbs;
                double circTau = circRaw > _mbCircleRatioEma ? 12.0 : _pModeBLockRecoverMs;
                _mbCircleRatioEma += (float)((circRaw - _mbCircleRatioEma) * (1.0 - Math.Exp(-dtMs / circTau)));
                f01 *= ModeBComposer.FrictionCircleLateralShare(_mbCircleRatioEma, lockL);
            }
            else
            {
                double lockTau = _lastFrontSlipRatio < _mbLockRatioEma ? 12.0 : _pModeBLockRecoverMs;
                float lockAlpha = (float)(1.0 - Math.Exp(-dtMs / lockTau));
                _mbLockRatioEma += (_lastFrontSlipRatio - _mbLockRatioEma) * lockAlpha;
                f01 *= ModeBComposer.LockupGate(_mbLockRatioEma, -0.4 * lockL, -lockL);
            }
            // Reversal softening (drift-catch snap, issue #38's lateral twin):
            // fade the composed force while the slide COLLAPSES toward center,
            // scaled by how fast, so the full-scale sign flip stops snapping and
            // the wheel->slip->force loop loses its gain. Digging deeper into a
            // slide passes untouched, so loaded drift weight survives. Sign-blind
            // (a product of two signed inputs), so the direction sign needs no undoing.
            if (_mbReversalDampOn)
                f01 *= ModeBComposer.ReversalSoften(_mbSlipEma, _mbSlipRateEma, _pModeBReversalGain);
            // Crash duck (eleventh wheel test: wall hit buzzed the wheel).
            // Impacts slam every synthesis input to saturation at once and
            // the composed force whipsaws; go soft instantly, breathe back
            // over ~600 ms. Horizontal g only, so kerbs never trigger it.
            double gMag = Math.Sqrt(
                (double)_lastSurgeAccel * _lastSurgeAccel
                + (double)_lastSwayAccel * _lastSwayAccel) / 9.81;
            double duckF = _crashDuck.Tick(gMag, dtMs);
            f01 *= duckF;
            // Minimum-force floor ("Min force"): LAST in the shaping chain by
            // design. The feel fades above (lockup gate/circle, reversal
            // soften) express LIGHTNESS, exactly what a belt wheel's
            // internal-friction floor swallows, so their faded-but-nonzero
            // output SHOULD be lifted to stay perceptible. The SILENCE gates
            // are different: the low-speed gate suppresses crawl-speed slip
            // garbage by attenuation (it is exactly 0 only below ~6 km/h) and
            // the crash duck bottoms out at 15%, so a raw floor would lift
            // exactly the states they exist to mute (adversarial review of
            // this change proved both numerically: gravel-trap buzz at
            // 6-20 km/h, wall-hit whipsaw at 2.4x the vetted level). Scaling
            // the floor by both gate factors keeps quiet-by-design states
            // quiet: full floor in normal driving, floor melting away exactly
            // as fast as the gates close. Exact zero stays exact (utilization
            // floor / sub-6 km/h), and the stage sits BEFORE the ramp multiply
            // so menus and telemetry loss still decay to a true zero stream.
            // Synthesis channel only; the centering/damper stability terms in
            // MaybeReshapeFfb stay unremapped (a damper boosted to a floor
            // would chatter).
            if (_pModeBMinForce > 0f)
            {
                double minEff = _pModeBMinForce * lowGate * duckF;
                if (minEff > 0.0)
                    f01 = ModeBComposer.MinForceRemap(f01, minEff);
            }
            double v = f01 * _mbRamp * 32767.0;
            if (v > short.MaxValue) v = short.MaxValue;
            else if (v < short.MinValue) v = short.MinValue;
            return (short)v;
        }

        // ---------- iRacing: reshape the sim's own steering torque ----------
        // iRacing solves steering-column torque in its own physics and publishes
        // it, so there is nothing to synthesize here. What we add is delivery:
        // the sim's 360 Hz sub-tick torque, upsampled onto our 1 kHz ep3 stream
        // and put through the same stability chain every other mode uses.
        //
        // Everything below is name-based reflection against SimHub's raw iRacing
        // object. No compile-time reference is taken on iRacingSDK.dll or
        // ICarsReader.dll: SimHub ships both and can rename or drop either, and
        // a hard reference would take the whole plugin down with it. If any
        // lookup fails the mode simply never arms.

        // One immutable snapshot per SimHub tick. Published by a single volatile
        // reference swap so the 1 kHz FFB thread can never see a torn pairing of
        // samples, scale and timestamp.
        private sealed class IRacingTorqueFrame
        {
            public float[] Sub;        // sub-tick torque, oldest first, Nm
            public float   Latest;     // the per-frame scalar, Nm
            public float   MaxNm;      // SteeringWheelMaxForceNm, the sim's own full-scale
            public bool    GameFfbOn;  // SteeringFFBEnabled: the sim is driving the wheel itself
            public bool    FixedScale; // frame already carries its final scale (the R3E route
                                       // publishes a normalized value): the iRacing max-force
                                       // override and per-car map must not rescale it
            // Steering, for the soft lock. Normalised to the CAR's lock: +/-1 at
            // the car's limit, beyond it past, carrying the sign the lock stage
            // expects. iRacing: the angle over half of SteeringWheelAngleMax
            // (the channel is lock-to-lock; MAIRA halves it the same way).
            // RaceRoom: the raw axis scaled by the game's wheel rotation over
            // the car's, signed from the physical wheel. HasSteer is false when
            // the route did not stamp it.
            public bool    HasSteer;
            public float   SteerNorm;
            public float   SteerSpeed; // d(SteerNorm)/dt per second, from consecutive frames
            public float   LockDeg;    // the car's per-side lock, degrees
            public long    Ticks;      // Stopwatch timestamp at arrival
        }
        private volatile IRacingTorqueFrame _irFrame;
        // Previous frame's steer for the lock's speed term. One pair for both
        // routes: they never run together, and a route swap costs one bogus
        // sample that the clamp on the target absorbs.
        private float  _irSteerPrevNorm;
        private long   _irSteerPrevTicks;
        private double _irLastLoggedLockRad;
        private float  _irSteerSpeedLp;            // low-passed speed for high-rate sources
        private int    _r3eLastLoggedCarRot, _r3eLastLoggedRoadLock, _r3eLastLoggedWheelRot;
        private long   _r3eNoPhysLogMs;            // Warn at most once a minute
        private long   _r3eLastSoftLockDiagMs;
        private long   _r3ePhysLastTicks;          // last physical update seen by the R3E handler
        private float  _r3eRawAtPhys;              // the sim's raw axis at that update
        private float  _r3eAxisRatio;              // |raw| / |physical|, slow average
        private int    _r3eAxisRatioN;
        private bool   _r3eAxisRatioLogged;
        private float _irRamp;
        private long  _irPrevTicks;
        // Lead-mode frame-join continuity (see ComputeIRacingForce). PrevOut is
        // the last torque the Lead branch emitted, FrameTicks identifies the
        // frame currently being blended from (0 = no previous, after a gap),
        // and Offset is the error being carried across the join.
        private double _irLeadPrevOut;
        private long   _irLeadFrameTicks;
        private double _irLeadOffset;

        // Telemetry iRacing publishes that SimHub's generic reader drops on the
        // floor. SimHubTelemetrySource fills 20 fields and leaves steering,
        // surface feel and collision null, which is why most of our texture
        // effects are silent in iRacing. These come off the SAME raw object the
        // force reshape already reads, so it costs one extra pass per tick.
        //
        // Deliberately NOT setting HasTireQuads: iRacing publishes no per-tire
        // slip angle, slip ratio or wheel rotation speed, and claiming the quads
        // are valid would make CtmComposer derive grip from zeros.
        private sealed class IRacingOverlay
        {
            public double? SteerAngleRad;
            public double? Heave;          // m/s^2, peak-abs across the 360 Hz sub-tick
            public double? Sway;
            public double? Surge;
            public double? SurfaceRumble;  // 0..1-ish, from the sim's per-tire rumble pitch
            public bool?   OnRumbleStrip;  // PlayerTrackSurfaceMaterial in the irsdk rumble range
            public double? CollisionMag;
            // Signed accelerations in m/s^2, from the 360 Hz sub-tick arrays,
            // matching TelemetryFrame's documented units and sign conventions.
            // Heave is GRAVITY-REMOVED here, the way SimHub already delivers it,
            // so the two are interchangeable and nothing downstream re-tunes.
            public double? HeaveHp;        // signed peak of the bump content
            public double? SwayMean;
            public double? SurgeMean;
            // Yaw rate in deg/s from the 360 Hz array. Traction loss runs on a
            // heuristic in iRacing (no per-tire slip exists there), and yaw rate
            // is one of its main inputs, so feeding it the sub-tick value makes
            // the one slip voice iRacing CAN have noticeably quicker to react.
            // Consumers take its absolute value, so the sign convention between
            // iRacing and SimHub does not have to be reconciled here.
            public double? YawRateDeg;
            // MEASURED sideslip in degrees, signed, from iRacing's own velocity
            // vector. This is the honest version of what traction loss has been
            // guessing at: the guess solves AccelSway = v x yawRate x cos(beta)
            // for beta, which only holds in a settled corner, goes non-linear
            // through acos exactly where the slide starts, and loses the sign.
            // Two channels the sim already publishes replace all of it.
            public double? SideslipDeg;
            public long    Ticks;
        }
        private volatile IRacingOverlay _irOverlay;

        // Car identity and engine truth, from iRacing's SESSION INFO rather than
        // its per-tick telemetry. iRacing publishes all of it, so none of this
        // needs a car database, community consensus or user entry.
        private sealed class IRacingCarInfo
        {
            public string CarPath;        // already our CarFacts key format, e.g. "mx5 mx52016"
            public string ScreenName;     // e.g. "Mazda MX-5 Cup"
            public int?   Cylinders;      // DriverCarEngCylinderCount
            public int?   RedlineRpm;     // DriverCarRedLine
            public int?   ForwardGears;   // DriverCarGearNumForward
        }
        private volatile IRacingCarInfo _irCarInfo;

        // Direct reader. When it is connected the whole latch below is driven
        // from ITS thread at the sim's own cadence, and the SimHub path stops
        // running entirely: staying on DataUpdate would keep us behind exactly
        // the hop this exists to remove.
        private IRacingSdkReader _irSdk;
        private long _irResumeStampTicks;   // FFB thread; 0 = no fade-in being traced
        private int  _irResumeSlot = -1;
        private System.Text.StringBuilder _irResumeTrace;
        private volatile bool _irSdkLive;
        private bool _irSdkChannelsMissingLogged;   // one Warn per gap, reader thread only
        private long _irSdkLastAttemptTicks;

        /// <summary>True while iRacing telemetry is coming straight from the
        /// sim's shared memory rather than by way of SimHub. Surfaced so the
        /// settings panel can say which path is live, because "enhanced" versus
        /// "fallback" changes what a support log means.</summary>
        // Watches the sim's full-scale figure and logs when it MOVES. This
        // settles a question we cannot answer by reading code: does iRacing's
        // own auto force mode still work while its force feedback is switched
        // off, and does trimming a car heavier or lighter still land here?
        //
        // If this value changes as cars change, or when the driver adjusts a
        // car's strength in the sim, then Auto is inheriting live per-car tuning
        // and is the right default. If it never moves, Auto is inheriting one
        // frozen number and users who rely on iRacing's auto mode need our own
        // override instead. SteeringWheelPeakForceNm is logged alongside it
        // because -1 is a sentinel whose meaning ("auto mode off" versus "auto
        // mode cannot measure with FFB off") we have assumed rather than proven.
        private double _irLastLoggedMaxNm = -1.0;

        // Learned peak torque for this car, in Nm. A RATCHET with a slow lerp
        // rather than a plain maximum: it climbs toward real peaks but no single
        // sample can define the whole scale, so one kerb strike or one spin does
        // not permanently shrink every other force.
        //
        // Learned ONLY while genuinely racing: on track, on a racing surface.
        // Kerbs, grass, gravel and the pit lane all produce torque that has
        // nothing to do with how hard the car pushes in a corner, and letting
        // them in is how an auto-calibration ends up scaled by its own noise.
        // The surface channels it needs are ones we already read for kerb
        // detection.
        private float _irPeakNm;
        private string _irPeakCarId;
        // When the peak last GREW meaningfully. A peak that has stopped climbing
        // is the only honest signal that we have seen what this car can do, and
        // it is what tells the driver when pressing Auto is worth anything.
        // Without it they are guessing, and pressing too early sets Max force
        // from an out-lap, which quietly makes everything too strong.
        private long _irPeakGrowthTicks;
        // Racing-surface time accumulated for this car. Guards the case where a
        // peak "settles" simply because the car has been parked: no growth for
        // 20 seconds means nothing if only 3 of those were spent driving.
        private double _irPeakRacingMs;

        private const double IRacingPeakSettleMs   = 15000.0;   // no growth for this long
        private const double IRacingPeakMinDriveMs = 30000.0;   // and at least this much racing

        // The lazy car-change reset lives inside LearnIRacingPeak, which only
        // runs while driving on track. Between a garage car swap and the first
        // lap, the peak still describes the OLD car, and the readiness UI was
        // offering to write it into the new car's slot (owner rig,
        // 2026-08-15). Every public surface therefore checks ownership first.
        private bool IRacingPeakIsForActiveCar =>
            string.Equals(_irPeakCarId, _activeCarId, StringComparison.Ordinal);

        /// <summary>True once the observed peak has stopped climbing for a while
        /// AND enough racing has actually happened. The Auto button uses this to
        /// show whether it is worth pressing yet.</summary>
        public bool IRacingPeakSettled
        {
            get
            {
                if (!IRacingPeakIsForActiveCar) return false;
                if (_irPeakNm <= 0.05f || _irPeakGrowthTicks == 0) return false;
                if (_irPeakRacingMs < IRacingPeakMinDriveMs) return false;
                double sinceMs = (Stopwatch.GetTimestamp() - _irPeakGrowthTicks)
                                 * 1000.0 / Stopwatch.Frequency;
                return sinceMs >= IRacingPeakSettleMs;
            }
        }

        /// <summary>0 to 1, how far along the settling is. Drives a dash button's
        /// appearance so the driver can watch it come up to readiness rather than
        /// poll a boolean that flips with no warning.</summary>
        public double IRacingPeakConfidence
        {
            get
            {
                if (!IRacingPeakIsForActiveCar) return 0.0;
                if (_irPeakNm <= 0.05f || _irPeakGrowthTicks == 0) return 0.0;
                double drive = _irPeakRacingMs / IRacingPeakMinDriveMs;
                if (drive > 1.0) drive = 1.0;
                double sinceMs = (Stopwatch.GetTimestamp() - _irPeakGrowthTicks)
                                 * 1000.0 / Stopwatch.Frequency;
                double quiet = sinceMs / IRacingPeakSettleMs;
                if (quiet > 1.0) quiet = 1.0;
                // The lower of the two: both conditions must hold, so readiness
                // is governed by whichever is further behind.
                return drive < quiet ? drive : quiet;
            }
        }

        /// <summary>Apply the learned peak as Max force, once, the way iRacing's
        /// own auto button does: drive a lap or two, press it, keep a number you
        /// can see and edit. Deliberately NOT continuous. A scale that keeps
        /// drifting under you as the car does something slightly bigger than
        /// before is the kind of wrong that is almost impossible to diagnose by
        /// feel, because everything simply gets quieter and nothing announces it.
        ///
        /// Writes the per-car slot when cars are kept separate, otherwise the
        /// shared one, so the button always sets whatever is actually in use.
        /// Returns the value written, or 0 if there is nothing learned yet.</summary>
        /// <summary>Whether the Nm max force is kept per car here: the user's
        /// choice in iRacing, always in Le Mans Ultimate. That game's numbers are
        /// rack torque, 50 to 130 Nm, and iRacing's shared "for every car"
        /// figure is a wheel rating of 10 to 20, so the two must never meet:
        /// this game reads and writes only the per-car map.</summary>
        public bool MaxForcePerCarHere
            => (Settings?.IRacingMaxForcePerCar ?? false) || IsLmuGame(_activeGame);

        /// <summary>The games whose Auto is iRacing's: learn the car's peak in
        /// Nm, adopt it as that car's max force. iRacing, and Le Mans Ultimate
        /// on its handover (its torque is Nm too). RaceRoom's is the normalized
        /// press-to-apply, because RaceRoom publishes a percentage.</summary>
        private bool IRacingStyleAutoHere
            => IsIRacingReshapeGame(_activeGame) || IsLmuGame(_activeGame);

        public double ApplyIRacingAutoMaxForce()
        {
            double learned = IRacingLearnedMaxNm;
            if (learned <= 0.5 || Settings == null) return 0.0;
            if (MaxForcePerCarHere && !string.IsNullOrEmpty(_activeCarId))
            {
                if (Settings.IRacingMaxForceByCar == null)
                    Settings.IRacingMaxForceByCar = new Dictionary<string, float>();
                Settings.IRacingMaxForceByCar[_activeCarId] = (float)learned;
            }
            else
            {
                Settings.IRacingMaxForceNmOverride = (float)learned;
            }
            PersistSettings();

            // APPLY AND RESET, the way iRacing's own auto button does it. Every
            // press then means the same thing: "the hardest this car pushed
            // SINCE I LAST PRESSED THIS".
            //
            // This is what makes a bad reading self-correcting without any decay
            // logic. A spin, a wall or a heavy save inflates the peak and would
            // otherwise poison the number for the rest of the session; instead
            // the driver does a clean lap and presses again, and the previous
            // mess is simply not in the window any more. Decay would be the
            // plugin GUESSING when a reading went stale. This lets the person
            // who knows whether the lap was clean decide.
            _irPeakNm = 0f;
            _irPeakCarId = _activeCarId;
            // The readiness clocks restart with the observer. Carrying them over
            // would light the button again after a few quiet seconds, on a window
            // that has seen almost no driving, which is exactly the reading the
            // settle test exists to refuse.
            _irPeakGrowthTicks = 0;
            _irPeakRacingMs = 0.0;
            _irPeakLastTicks = 0;

            SimHub.Logging.Current.Info(
                "[TF4ALL] iRacing Max force auto-set to "
                + learned.ToString("F1", System.Globalization.CultureInfo.InvariantCulture)
                + " Nm for " + (_activeCarId ?? "?")
                + ". Peak observer reset: drive a clean lap and press again to redo it.");
            return learned;
        }

        /// <summary>The Max force number the settings slider edits, resolved
        /// by the SAME targeting rule as the Auto button: the active car's
        /// slot when cars are kept separate and a car is active, else the
        /// shared override. iRacing's own workflow is nudging the read
        /// number to make a car heavier or lighter without touching the
        /// Strength slider; before this the slider always wrote the shared
        /// override, which the per-car slot shadows, so in per-car mode a
        /// nudge silently did nothing for the car being driven.</summary>
        public double GetEditableMaxForceNm()
        {
            var s = Settings;
            if (s == null) return 0.0;
            if (MaxForcePerCarHere && !string.IsNullOrEmpty(_activeCarId)
                && s.IRacingMaxForceByCar != null
                && s.IRacingMaxForceByCar.TryGetValue(_activeCarId, out float pc) && pc > 0.5f)
                return pc;
            return IsLmuGame(_activeGame) ? 0.0 : s.IRacingMaxForceNmOverride;
        }

        /// <summary>Write the panel's number to whatever the force path is
        /// actually using (see <see cref="GetEditableMaxForceNm"/>). Values
        /// under 0.5 clear the target back to "follow iRacing"; the panel shows
        /// that state as an empty box rather than as a zero, because no car has
        /// a peak torque of zero and a 0 in a Nm field reads as "no force".</summary>
        public void SetEditableMaxForceNm(double v)
        {
            var s = Settings;
            if (s == null) return;
            bool clear = v < 0.5;
            if (MaxForcePerCarHere && !string.IsNullOrEmpty(_activeCarId))
            {
                if (s.IRacingMaxForceByCar == null)
                    s.IRacingMaxForceByCar = new Dictionary<string, float>();
                if (clear) s.IRacingMaxForceByCar.Remove(_activeCarId);
                else s.IRacingMaxForceByCar[_activeCarId] = (float)v;
            }
            else
            {
                s.IRacingMaxForceNmOverride = clear ? 0.0f : (float)v;
            }
            PersistSettings();
        }

        /// <summary>Step the effective Max force from a bound control or the
        /// dash's +/- pair. Starts from whatever the force path is actually
        /// using (the live iRacing number when nothing is overridden), writes
        /// through the same targeting rule as the number box, and announces
        /// the result on the dash readout.</summary>
        public void NudgeIRacingMaxForce(double delta)
        {
            // Taps are human-rate; one line each is cheap and settles "did
            // the dash button fire at all" without a debugger on the rig.
            SimHub.Logging.Current.Info(
                $"[TF4ALL] max force nudge fired (delta={delta:+0.0;-0.0})");
            // RaceRoom's per-car max is the same concept on a different scale, so
            // the one pair of bindings serves both rather than each reshape game
            // growing its own. Deliberately NOT every game: this nudges a learned
            // per-car maximum, which only the reshape routes have.
            if (IsR3EGame(_activeGame) && (Settings?.R3ESharedMemoryFfb ?? false))
            {
                NudgeR3EStrength(delta > 0 ? +1 : -1);
                return;
            }
            if (!IRacingStyleAutoHere || !ModeBEnabledForActiveGame)
            {
                DashReadout("PEAK FORCE","IRACING ONLY");
                return;
            }
            double cur = GetEditableMaxForceNm();
            if (cur < 0.5) cur = IRacingEffectiveMaxForceNm;
            if (cur < 0.5)
            {
                // No override, and iRacing has not published a number yet.
                DashReadout("PEAK FORCE","NO NUMBER YET");
                return;
            }
            double v = Math.Max(1.0, Math.Min(IsLmuGame(_activeGame) ? 400.0 : 50.0, cur + delta));
            SetEditableMaxForceNm(v);
            DashReadout("PEAK FORCE", v.ToString("0.0",
                System.Globalization.CultureInfo.InvariantCulture) + " NM");
        }

        /// <summary>Peak this car has actually produced, plus a margin, in Nm.
        /// The number a "learn from driving" control would adopt. 0 until enough
        /// racing has happened to mean anything.</summary>
        public double IRacingLearnedMaxNm
        {
            get
            {
                return IRacingPeakIsForActiveCar && _irPeakNm > 0.05f
                    ? _irPeakNm * 1.10 : 0.0;
            }
        }

        /// <summary>Feed the peak learner. Surface gating is the caller's job so
        /// this stays a pure ratchet.</summary>
        private void LearnIRacingPeak(double absTorqueNm, bool racingSurface)
        {
            if (!racingSurface || absTorqueNm <= 0.0 || absTorqueNm > 400.0) return;
            // A car change resets it: the previous car's ceiling says nothing
            // about this one, which is the entire reason this is per-car.
            string car = _activeCarId;
            if (!string.Equals(car, _irPeakCarId, StringComparison.Ordinal))
            {
                _irPeakCarId = car;
                _irPeakNm = 0f;
                _irPeakGrowthTicks = 0;
                _irPeakRacingMs = 0.0;
            }

            long nowP = Stopwatch.GetTimestamp();
            if (_irPeakLastTicks != 0)
            {
                double dt = (nowP - _irPeakLastTicks) * 1000.0 / Stopwatch.Frequency;
                // Clamped so a pause, an alt-tab or a stall cannot credit
                // minutes of "racing" that never happened.
                if (dt > 0.0 && dt < 250.0) _irPeakRacingMs += dt;
            }
            _irPeakLastTicks = nowP;

            float before = _irPeakNm;
            float lerped = _irPeakNm + (float)(absTorqueNm - _irPeakNm) * 0.01f;
            if (lerped > _irPeakNm) _irPeakNm = lerped;
            if (absTorqueNm > _irPeakNm && _irPeakNm <= 0.05f) _irPeakNm = (float)absTorqueNm;

            // Only MEANINGFUL growth counts as unsettled. The lerp creeps upward
            // by tiny amounts almost every sample, so any growth at all would
            // mean it never settles and the button never lights.
            if (before <= 0.05f || _irPeakNm > before * 1.005f)
                _irPeakGrowthTicks = nowP;
        }
        private long _irPeakLastTicks;

        private void MaybeLogIRacingFullScale(double maxNm, double peakNm)
        {
            if (maxNm <= 0.0) return;
            if (_irLastLoggedMaxNm > 0.0 && Math.Abs(maxNm - _irLastLoggedMaxNm) < 0.1) return;
            double prev = _irLastLoggedMaxNm;
            _irLastLoggedMaxNm = maxNm;
            SimHub.Logging.Current.Info(
                "[TF4ALL] iRacing full scale: SteeringWheelMaxForceNm="
                + maxNm.ToString("F2", System.Globalization.CultureInfo.InvariantCulture)
                + (prev > 0.0 ? " (was " + prev.ToString("F2", System.Globalization.CultureInfo.InvariantCulture) + ")" : " (first)")
                + " peakForceNm=" + peakNm.ToString("F2", System.Globalization.CultureInfo.InvariantCulture)
                + " car=" + (_activeCarId ?? "?"));
        }

        /// <summary>Steering fields for the torque frame, from a steer already
        /// normalised to the car's lock (+/-1 at the limit, carrying the sign
        /// the lock stage expects) and that lock in degrees per side. The speed
        /// comes from consecutive frames; the first frame after a gap gets 0
        /// rather than a spike, and a source faster than ~125 Hz (RaceRoom's
        /// 400 Hz block) is low-passed so axis quantisation does not become
        /// speed noise at the wall. The 60 Hz iRacing feed is untouched.</summary>
        private void StampSteerFields(float norm, float lockDeg, long ticks, IRacingTorqueFrame f)
        {
            if (float.IsNaN(norm) || float.IsInfinity(norm) || !(lockDeg > 1f)) return;
            float speed = 0f;
            long prevT = _irSteerPrevTicks;
            if (prevT != 0)
            {
                double dt = (ticks - prevT) / (double)Stopwatch.Frequency;
                if (dt < 0.001)
                {
                    // Two samples inside a millisecond: hold the last speed and
                    // the filter state rather than dividing by next to nothing.
                    speed = _irSteerSpeedLp;
                }
                else if (dt < 0.25)
                {
                    speed = (float)((norm - _irSteerPrevNorm) / dt);
                    if (dt < 0.008)
                    {
                        float a = (float)(1.0 - Math.Exp(-dt / 0.016));
                        speed = _irSteerSpeedLp + (speed - _irSteerSpeedLp) * a;
                    }
                }
                // A gap of 250 ms or more: speed stays 0 and the filter restarts.
            }
            _irSteerSpeedLp = speed;
            _irSteerPrevNorm = norm;
            _irSteerPrevTicks = ticks;
            f.HasSteer = true;
            f.SteerNorm = norm;
            f.SteerSpeed = speed;
            f.LockDeg = lockDeg;
        }

        /// <summary>iRacing: the wheel angle over the car's per-side lock, which
        /// is half of SteeringWheelAngleMax (lock-to-lock). The angle's own sign
        /// is the one the lock stage expects on this route (positive is left,
        /// and a positive authored value pulls right).</summary>
        private void IRacingSteerFields(double angleRad, double angleMaxRad, long ticks,
                                        IRacingTorqueFrame f)
        {
            if (double.IsNaN(angleRad) || double.IsInfinity(angleRad) || !(angleMaxRad > 0.01)) return;
            double lockRad = angleMaxRad * 0.5;
            StampSteerFields((float)(angleRad / lockRad), (float)(lockRad * 180.0 / Math.PI), ticks, f);
            MaybeLogIRacingSteerRange(angleMaxRad);
        }

        /// <summary>One line per change of the car's rotation, its road-wheel
        /// lock or the game's wheel-rotation setting, so a rig can see where the
        /// wall will sit on the axis before trusting it.</summary>
        private void MaybeLogR3ESteerLock(int carRotDeg, int roadLockDeg, int wheelRotDeg)
        {
            if (carRotDeg == _r3eLastLoggedCarRot && roadLockDeg == _r3eLastLoggedRoadLock
                && wheelRotDeg == _r3eLastLoggedWheelRot) return;
            _r3eLastLoggedCarRot = carRotDeg;
            _r3eLastLoggedRoadLock = roadLockDeg;
            _r3eLastLoggedWheelRot = wheelRotDeg;
            var ci = System.Globalization.CultureInfo.InvariantCulture;
            string wheel = wheelRotDeg == 0
                ? "Auto (the game sets the wheel's own range to the car's, so the wheel's stop is the lock and none is added)"
                : wheelRotDeg < 0 ? "not published"
                : wheelRotDeg.ToString(ci) + " deg (Manual)";
            string at = wheelRotDeg >= 180 && carRotDeg > 0
                ? ", so the car's lock sits at " + ((double)carRotDeg / wheelRotDeg).ToString("F2", ci) + " of the axis"
                : "";
            SimHub.Logging.Current.Info(
                "[TF4ALL] RaceRoom steering: car rotation " + carRotDeg.ToString(ci)
                + " deg lock-to-lock (road wheel lock " + roadLockDeg.ToString(ci) + " deg), wheel rotation "
                + wheel + at + ". car=" + (_activeCarId ?? "?"));
        }

        /// <summary>One line per change of the car's steering range, so the rig
        /// can confirm the channel is lock-to-lock (a 540 degree car should
        /// print 540, not 270) before anyone trusts where the wall sits.</summary>
        private void MaybeLogIRacingSteerRange(double angleMaxRad)
        {
            if (Math.Abs(angleMaxRad - _irLastLoggedLockRad) < 0.01) return;
            _irLastLoggedLockRad = angleMaxRad;
            double deg = angleMaxRad * 180.0 / Math.PI;
            SimHub.Logging.Current.Info(
                "[TF4ALL] iRacing steering range: SteeringWheelAngleMax="
                + angleMaxRad.ToString("F3", System.Globalization.CultureInfo.InvariantCulture) + " rad = "
                + deg.ToString("F0", System.Globalization.CultureInfo.InvariantCulture) + " deg lock-to-lock ("
                + (deg * 0.5).ToString("F0", System.Globalization.CultureInfo.InvariantCulture) + " per side)"
                + " car=" + (_activeCarId ?? "?"));
        }

        /// <summary>Full scale in Nm as the sim currently reports it, so the
        /// panel can show what Auto resolved to. An auto setting that displays
        /// nothing is indistinguishable from one that is broken.</summary>
        public double IRacingLiveMaxForceNm
        {
            get { var fr = _irFrame; return fr != null ? fr.MaxNm : 0.0; }
        }

        /// <summary>The raw observed peak for this car in Nm, WITHOUT the Auto
        /// margin. Zero until enough racing has happened, including right after
        /// an Auto press, which resets the observer on purpose.</summary>
        public double IRacingObservedPeakNm { get { return _irPeakNm > 0.05f ? _irPeakNm : 0.0; } }

        /// <summary>The divisor actually in use, resolved the same way the force
        /// path resolves it. The panel needs this to predict clipping honestly
        /// rather than assuming Max force came from Auto.</summary>
        public double IRacingEffectiveMaxForceNm
        {
            get
            {
                var s = Settings;
                if (s != null)
                {
                    float perCar;
                    if (MaxForcePerCarHere && s.IRacingMaxForceByCar != null
                        && !string.IsNullOrEmpty(_activeCarId)
                        && s.IRacingMaxForceByCar.TryGetValue(_activeCarId, out perCar)
                        && perCar > 0.5f)
                        return perCar;
                    if (!IsLmuGame(_activeGame) && s.IRacingMaxForceNmOverride > 0.5f) return s.IRacingMaxForceNmOverride;
                }
                var fr = _irFrame;
                return fr != null ? fr.MaxNm : 0.0;
            }
        }

        public bool IRacingDirectActive { get { return _irSdkLive; } }
        public long IRacingDirectTicks { get { var r = _irSdk; return r != null ? r.TicksSeen : 0; } }
        public long IRacingDirectMissed { get { var r = _irSdk; return r != null ? r.TicksMissed : 0; } }

        /// <summary>Try to attach the direct reader, at most once a second so a
        /// closed sim does not turn into a retry storm. Mirrors the promote half
        /// of EvaluateForzaTelemetryFallback.</summary>
        private void MaybeStartIRacingDirect()
        {
            if (!IsIRacingReshapeGame(_activeGame)) { StopIRacingDirect(); return; }
            if (_irSdk != null && _irSdkLive) return;

            long now = Stopwatch.GetTimestamp();
            if (_irSdkLastAttemptTicks != 0
                && (now - _irSdkLastAttemptTicks) < Stopwatch.Frequency) return;
            _irSdkLastAttemptTicks = now;

            if (_irSdk == null)
            {
                _irSdk = new IRacingSdkReader
                {
                    Logger = msg => SimHub.Logging.Current.Info("[TF4ALL] " + msg),
                };
                _irSdk.OnTick = IRacingDirectTick;
            }
            if (_irSdk.Start())
            {
                _irSdkLive = true;
                SimHub.Logging.Current.Info(
                    "[TF4ALL] iRacing telemetry: DIRECT (shared memory). SimHub's copy is now the fallback only.");
            }
        }

        private void StopIRacingDirect()
        {
            if (_irSdk == null) return;
            bool was = _irSdkLive;
            _irSdkLive = false;
            try { _irSdk.Stop(); } catch { }
            if (was)
                SimHub.Logging.Current.Info(
                    "[TF4ALL] iRacing telemetry: direct reader stopped, back to SimHub's copy.");
        }

        // ------------------------------------------------------------------
        // RaceRoom shared-memory FFB route (dev; the R3EFFB and R3EPROBE
        // access codes). Reads the sim's own pre-gain steering force straight
        // from its "$R3E" block at the sim's physics rate and publishes it as
        // reshape frames, so RaceRoom can run tap-free the way iRacing does:
        // no USBPcap, and with the in-game FFB at 0 no HID++ force traffic
        // left for the rev lights and screen to contend with. The A/B against
        // the tap route is the whole point right now; nothing here runs unless
        // the route or the probe is switched on.

        private R3ESharedMemoryReader _r3e;
        private bool _r3eLive;
        // RaceRoom's own answer to "is the player driving right now", latched by
        // the reader thread and read by the HID++ gate. See HidppSessionActive.
        private volatile bool _r3eInCar;
        private long _r3eSessionTicks;      // Stopwatch stamp of the latch above
        // Friendly car name RaceRoom reports in telemetry, captured in
        // DataUpdate and fed to the CarFacts name cascade (RaceRoom has no
        // FS-style pipe source; this is its telemetryName input).
        private volatile string _r3eCarDisplayName;
        // VehicleInfo.EngineType for the car we are in: 0 combustion,
        // 1 electric, 2 hybrid, -1 not read yet. Refreshed on car change from
        // SimHub's copy of the same block, so it is there in every RaceRoom
        // session and not only under the shared-memory route.
        private volatile int _r3eEngineType = -1;
        private volatile string _r3eEngineTypeCarId;
        private volatile bool _r3eProbe;            // R3EPROBE: log signal lines, force not required
        private volatile bool _r3eInvert;           // R3EFFB INV: flip the published sign (session)
        private volatile float _r3eRawFullScaleNm;  // >0 = read raw SteeringForce with this full
                                                    // scale (R3EFFB NM n); 0 = the percentage
                                                    // channel (default)
        private long _r3eProbeLogTicks;
        private volatile float _r3ePrMinF, _r3ePrMaxF, _r3ePrMinP, _r3ePrMaxP;
        private volatile bool _r3ePrHave;

        // Le Mans Ultimate handover (LMUFFB), the RaceRoom route's shape on
        // the sim's official shared memory. See LmuTelemetryTick.
        private LmuSharedMemoryReader _lmu;
        private bool _lmuLive;
        private volatile bool _lmuProbe;            // LMUPROBE: log signal lines, force not required
        private volatile bool _lmuInvert;           // LMUFFB INV: flip the published sign (session)
        private long _lmuProbeLogTicks;
        private volatile float _lmuPrMinT, _lmuPrMaxT, _lmuPrMinF, _lmuPrMaxF;
        private volatile bool _lmuPrHave;
        private long _lmuNoPhysLogMs;               // Warn at most once a minute
        private long _lmuNoSimHubLogMs;             // same cadence, SimHub not reading the game
        private float  _lmuAxisRatio;               // |raw| / |physical|, slow average, per car
        private int    _lmuAxisRatioN;
        private int    _lmuAxisRatioCarRot = -1;
        private string _lmuLockLogKey;
        private float  _lmuPrevRawSteer;
        private const int LmuAxisRatioSettleN = 200; // ~2 s of steady cornering at the sim's 100 Hz

        // RaceRoom's r3e_engine_type. Combustion and hybrid are both "it fires",
        // so only the electric value is acted on; the others are kept for the
        // probe line, which reads better in words than as a bare number.
        private const int R3EEngineCombustion = 0;
        private const int R3EEngineElectric   = 1;
        private const int R3EEngineHybrid     = 2;

        // Reflection handles onto SimHub's copy of the "$R3E" block. Resolved
        // once per raw type rather than per car: the type never changes inside
        // a session, and a GetField walk per car switch would be waste.
        private static Type _r3eRawTypeSeen;
        private static System.Reflection.FieldInfo _r3eRawVehicleInfo;
        private static System.Reflection.FieldInfo _r3eRawEngineType;

        /// <summary>VehicleInfo.EngineType from SimHub's raw RaceRoom sample:
        /// 0 combustion, 1 electric, 2 hybrid, -1 when it cannot be read. Our
        /// own reader has the same field at OFF_ENGINE_TYPE, but that reader
        /// only runs under the shared-memory route, and whether a car is an EV
        /// matters in every RaceRoom session. Reflection because the struct
        /// lives in SimHub's RaceRoom reader assembly, which this plugin does
        /// not reference.</summary>
        private static int ReadR3EEngineType(GameData data)
        {
            try
            {
                object raw = data?.NewData?.GetRawDataObject();
                if (raw == null) return -1;
                var t = raw.GetType();
                if (!ReferenceEquals(t, _r3eRawTypeSeen))
                {
                    const System.Reflection.BindingFlags PubI =
                        System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Instance;
                    _r3eRawTypeSeen = t;
                    _r3eRawVehicleInfo = t.GetField("VehicleInfo", PubI);
                    _r3eRawEngineType = _r3eRawVehicleInfo?.FieldType.GetField("EngineType", PubI);
                }
                if (_r3eRawVehicleInfo == null || _r3eRawEngineType == null) return -1;
                object vi = _r3eRawVehicleInfo.GetValue(raw);
                if (vi == null) return -1;
                return _r3eRawEngineType.GetValue(vi) is int et ? et : -1;
            }
            catch
            {
                // A layout change in SimHub's reader must never cost us a frame;
                // -1 just means the EV fallback stays out of the cascade.
                return -1;
            }
        }

        /// <summary>Once per SimHub tick: run or stop the "$R3E" reader for
        /// the active game. Cheap and silent for every other game.</summary>
        private void R3ETelemetryTick()
        {
            // The reader is no longer only the FFB route's. It is also the one
            // place RaceRoom's own session state (control type, paused, menus,
            // replay, garage) reaches us, and the rev lights and the base screen
            // need that to stop guessing from physics. So it runs for those too:
            // reading a shared-memory page costs one thread, and the alternative
            // is a rev bar that flicks back to the game on every telemetry gap.
            var r3eCfg = Settings;
            bool wantForSurfaces = (r3eCfg?.ModeBRevLightsEnabled ?? true)
                                || (r3eCfg?.ModeBOledEnabled ?? false);
            bool want = IsR3EGame(_activeGame)
                && MasterMode == TrueforceMasterMode.Normal
                && (_r3eProbe || (r3eCfg?.R3ESharedMemoryFfb ?? false) || wantForSurfaces);
            if (!want) { StopR3EDirect(); return; }

            if (_r3e == null)
            {
                _r3e = new R3ESharedMemoryReader
                {
                    Logger = msg => SimHub.Logging.Current.Info("[TF4ALL] " + msg),
                    OnSample = R3EDirectSample,
                };
            }
            if (!_r3eLive)
            {
                _r3e.Start();   // the reader retries the open itself while the sim is absent
                _r3eLive = true;
                SimHub.Logging.Current.Info("[TF4ALL] R3E shared-memory reader started"
                    + (_r3eProbe ? " (probe on)" : "") + ".");
            }

            if (_r3eProbe) MaybeLogR3EProbe();
        }

        private void StopR3EDirect()
        {
            if (_r3e == null || !_r3eLive) return;
            _r3eLive = false;
            // Drop the session latch with the reader, so a later gate cannot
            // answer from a reading nothing is refreshing any more.
            _r3eInCar = false;
            System.Threading.Interlocked.Exchange(ref _r3eSessionTicks, 0L);
            try { _r3e.Stop(); } catch { }
            SimHub.Logging.Current.Info("[TF4ALL] R3E shared-memory reader stopped.");
        }

        /// <summary>The takeover routes' per-car auto-strength, one physics
        /// update's worth: load the incoming car's applied max, grow the
        /// peak-hold observer while genuinely driving, and publish the full
        /// scale fraction ComputeIRacingForce divides by. Written for RaceRoom
        /// lifted out of the RaceRoom handler as its own step: the learner is keyed by
        /// game and car, and <paramref name="latest"/> over
        /// <paramref name="maxNm"/> is the same normalized force whichever
        /// units the route publishes in. Reader thread.</summary>
        private void TakeoverAutoStrengthTick(float latest, float maxNm, float speedMps)
        {
            // Auto-strength (iRacing press-to-apply): the reader thread owns the
            // peak-hold observer and the applied max. ComputeIRacingForce reads
            // the published fraction, and its low-speed ramp fades the boost out
            // while parked so the closed loop can't ring at a standstill.
            if (Settings?.R3EAutoStrength ?? true)
            {
                // Per-car load on a car change: bring in the committed max and
                // start a fresh peak observer for the incoming car.
                string curCar = _activeCarId;
                if (!string.Equals(curCar, _r3eLastLoadedCar, StringComparison.Ordinal))
                {
                    lock (_r3eStrengthLock)
                    {
                        _r3eAppliedPeak = R3ETryLoadStrength(curCar, out float lp) && lp > 0.01f ? lp : 0f;
                    }
                    _r3eLastLoadedCar = curCar;
                    _r3ePeakCarId = curCar;
                    _r3ePeakObs = 0f;
                    _r3ePeakGrowthTicks = 0;
                    _r3ePeakRacingMs = 0.0;
                    _r3ePrevStrengthTicks = 0;
                }

                // Peak-hold observer, no decay: while genuinely driving, grow the
                // peak and accumulate driving time so R3EPeakSettled knows when
                // Apply is worth pressing. Reset only by an apply.
                long nowTicks = Stopwatch.GetTimestamp();
                double dtMs = _r3ePrevStrengthTicks == 0
                    ? 0.0 : (nowTicks - _r3ePrevStrengthTicks) * 1000.0 / Stopwatch.Frequency;
                _r3ePrevStrengthTicks = nowTicks;
                if (dtMs < 0.0) dtMs = 0.0; else if (dtMs > 100.0) dtMs = 100.0;
                if (speedMps * 3.6 >= 15.0)   // driving, not parked/pitting
                {
                    _r3ePeakRacingMs += dtMs;
                    double norm = maxNm > 0.0001f ? Math.Abs(latest) / maxNm : 0.0;
                    if (norm > _r3ePeakObs + 0.001)
                    {
                        _r3ePeakObs = (float)norm;
                        _r3ePeakGrowthTicks = nowTicks;
                    }
                }

                // Press-to-apply, iRacing style: an unlearned car gets NO boost
                // (frac 1.0), so R3EFFB matches the sim's own scale and the wheel
                // feels like the game until the driver applies this car's learned
                // max. Nothing changes under you until you press it. Only a
                // committed peak boosts: a weak car's peak sits below target, so
                // frac < 1 shrinks the divisor and lifts it toward target.
                float applied = _r3eAppliedPeak;
                double frac = applied > 0.01f ? applied / AutoStrengthTarget : 1.0;
                if (frac < 0.08) frac = 0.08; else if (frac > 1.5) frac = 1.5;
                _r3eFullScaleFrac = (float)frac;
            }
            else _r3eFullScaleFrac = 1f;
        }

        /// <summary>Reader thread, once per NEW physics tick: aggregate for
        /// the probe and, while the reshape is armed for RaceRoom, publish the
        /// force frame the iRacing consumer already knows how to render.</summary>
        private void R3EDirectSample(R3EFfbSample s)
        {
            // Authoritative session state FIRST, before any of the force route's
            // own gates: the rev lights and the screen need this whether or not
            // the FFB reshape is armed, and RaceRoom has no telemetry source of
            // its own to carry it. Without this the surfaces fall back to the
            // physics proxy and stand down on every hiccup in SimHub's feed.
            // Deliberately WITHOUT the garage term the force route uses below.
            // There it guards against a runaway on a parked wheel, which is a
            // real hazard; there is no such hazard in lighting the rev bar, and
            // blipping the throttle in the garage is exactly when someone looks
            // at it. Everything else (AI, remote, replay, menus, pause) means
            // the player is not driving and both surfaces should stand down.
            _r3eInCar = s.ControlType == 0 && !s.GamePaused && !s.GameInMenus
                     && !s.GameInReplay;
            System.Threading.Interlocked.Exchange(ref _r3eSessionTicks, Stopwatch.GetTimestamp());

            if (_r3eProbe)
            {
                float fv = (float)s.SteeringForce, pv = (float)s.SteeringForcePct;
                if (!_r3ePrHave)
                {
                    _r3ePrMinF = _r3ePrMaxF = fv;
                    _r3ePrMinP = _r3ePrMaxP = pv;
                    _r3ePrHave = true;
                }
                else
                {
                    if (fv < _r3ePrMinF) _r3ePrMinF = fv;
                    if (fv > _r3ePrMaxF) _r3ePrMaxF = fv;
                    if (pv < _r3ePrMinP) _r3ePrMinP = pv;
                    if (pv > _r3ePrMaxP) _r3ePrMaxP = pv;
                }
            }

            if (_forceMode != ForceModeIRacing || !IsR3EGame(_activeGame)) return;
            var cfg = Settings;
            if (cfg == null || !cfg.R3ESharedMemoryFfb) return;

            // Player at the wheel, actually driving. Anything else (AI,
            // remote, replay, menus, garage, pause) publishes nothing and the
            // 250 ms age gate in ComputeIRacingForce decays whatever was last
            // shown: same shape as iRacing's IsOnTrack guard against the
            // parked-car runaway.
            bool inCar = s.ControlType == 0 && !s.GamePaused && !s.GameInMenus
                && !s.GameInReplay && !s.InGarage;
            if (!inCar) { _irFrame = null; return; }

            float latest, maxNm;
            float rawScale = _r3eRawFullScaleNm;
            if (rawScale > 0.5f) { latest = (float)s.SteeringForce; maxNm = rawScale; }
            else { latest = (float)s.SteeringForcePct; maxNm = 1f; }
            if (float.IsNaN(latest) || float.IsInfinity(latest)) return;
            // Sign. RaceRoom's in-game Invert FFB flips this shared-memory value
            // (it affects the torque-target route, not just the tap). On this
            // wheel the driver keeps that in-game invert ON for the tap route to
            // read right (owner, 2026-09-05), so R3EFFB expects invert ON and
            // takes the value as-is. R3EFFB INV flips it for a rig that runs the
            // in-game invert OFF.
            if (_r3eInvert) latest = -latest;

            TakeoverAutoStrengthTick(latest, maxNm, s.CarSpeedMps);

            var prev = _irFrame;
            var frR3e = new IRacingTorqueFrame
            {
                Sub = null,          // no sub-tick history; the scalar holds
                Latest = latest,
                MaxNm = maxNm,
                GameFfbOn = false,   // R3E publishes no such flag; the setup
                                     // instruction (in-game FFB at 0) is the guard
                FixedScale = true,
                Ticks = Stopwatch.GetTimestamp(),
            };
            // Steering for the soft lock. The raw axis spans the wheel rotation
            // set in the game's controller profile (Manual), and the car's own
            // rotation says where its lock sits on that axis. Not from
            // steer_lock_degrees: that is the ROAD wheel's lock (17 for a
            // Formula RaceRoom 3), and the first cut used it as the steering
            // wheel's, which put the wall a tenth of the way in with a band six
            // times too wide (rig, 2026-09-13). The PHYSICAL wheel supplies the
            // sign: the raw axis's sign convention is undocumented, while the
            // physical one is what the whole takeover path is authored
            // against. No fresh physical position, no lock, rather than a
            // guessed sign, said once in the log.
            // The PHYSICAL wheel position is the axis, not the sim's raw value.
            // steer_input_raw is normalised to the CAR's lock and clamps at 1
            // there (rig, 2026-09-13: raw over physical measured 3.08 against
            // a wheel-over-car of 3.09, and raw sat at 1.000 while the wheel
            // went on to 0.42 of its travel), so it can never say how far past
            // the lock the wheel is, and a wall built from it stopped early.
            // The physical position is what the whole takeover path is
            // authored against, so it supplies magnitude and sign alike. The
            // raw value is kept to measure the two against each other (the
            // ratio log below), which is how that was established.
            //
            // Liveness, not age: a wheel held still sends no reports, so a 500
            // ms freshness gate flapped stale on every straight (11 warnings
            // in one session). The receiver's own IsRunning is the death
            // signal (WheelSteeringReader self-heal), backed by one sanity
            // check: the raw axis moving while the physical one has not for
            // two seconds is a reader that stopped without saying so.
            var physRd = _steeringReader;
            long physT = physRd != null ? physRd.LastUpdateTicks : 0;
            bool physLive = physRd != null && physRd.IsRunning && physT != 0;
            if (physLive)
            {
                if (physT != _r3ePhysLastTicks)
                {
                    _r3ePhysLastTicks = physT;
                    _r3eRawAtPhys = s.SteerInputRaw;
                }
                else if (frR3e.Ticks - physT > Stopwatch.Frequency * 2
                         && Math.Abs(s.SteerInputRaw - _r3eRawAtPhys) > 0.05f)
                {
                    physLive = false;
                }
            }
            float physNow = physLive ? physRd.SteerNorm : float.NaN;
            float r3eSteer = IRacingSoftLock.R3ESteer(physNow, s.CarRotationDeg, s.WheelMaxRotationDeg);
            MaybeLogR3ESteerLock(s.CarRotationDeg, s.RoadWheelLockDeg, s.WheelMaxRotationDeg);
            if (!float.IsNaN(r3eSteer))
            {
                StampSteerFields(IRacingSoftLock.SignedByPhysical(r3eSteer, physNow),
                                 s.CarRotationDeg * 0.5f, frR3e.Ticks, frR3e);
            }
            else if (!physLive && (Settings?.IRacingSoftLockEnabled ?? false)
                     && s.WheelMaxRotationDeg >= 180)
            {
                long wMs = Environment.TickCount;
                if (wMs - _r3eNoPhysLogMs >= 60000)
                {
                    _r3eNoPhysLogMs = wMs;
                    SimHub.Logging.Current.Warn(
                        "[TF4ALL] RaceRoom soft lock: no physical steering position from the wheel "
                        + (physRd == null ? "(steering reader not started)"
                           : !physRd.IsRunning ? "(steering reader stopped; it will try to reopen)"
                           : "(steering reader silent while the sim's axis moves)")
                        + ", so no lock is rendered.");
                }
            }
            // What the sim's raw axis IS, measured: its magnitude over the
            // physical position, averaged where both are well off centre. 1.0
            // means the device axis; the car's rotation over the wheel's means
            // it is normalised to the car's lock. Logged once it has settled.
            if (physLive && Math.Abs(s.SteerInputRaw) > 0.3f && Math.Abs(physNow) > 0.1f)
            {
                float ratio = Math.Abs(s.SteerInputRaw) / Math.Abs(physNow);
                _r3eAxisRatio = _r3eAxisRatioN == 0 ? ratio : _r3eAxisRatio + (ratio - _r3eAxisRatio) * 0.02f;
                if (_r3eAxisRatioN < int.MaxValue) _r3eAxisRatioN++;
                if (!_r3eAxisRatioLogged && _r3eAxisRatioN >= 400)
                {
                    _r3eAxisRatioLogged = true;
                    var rci = System.Globalization.CultureInfo.InvariantCulture;
                    SimHub.Logging.Current.Info(
                        "[TF4ALL] RaceRoom steering axis: raw over physical = "
                        + _r3eAxisRatio.ToString("F2", rci)
                        + (Math.Abs(_r3eAxisRatio - 1f) < 0.1f
                           ? " (the sim's raw axis is the device axis)"
                           : " (the sim's raw axis is scaled; the wheel's rotation over the car's is "
                             + (s.CarRotationDeg > 0 && s.WheelMaxRotationDeg > 0
                                ? ((float)s.WheelMaxRotationDeg / s.CarRotationDeg).ToString("F2", rci) : "?")
                             + ")"));
                }
            }
            // SOFTLOCK diagnostic, from the numbers this route builds the lock
            // with. ApplySoftLock's own line only fires once a frame carries
            // steering, so the states that keep it from doing so (Auto
            // rotation, no physical position) would otherwise leave no trace.
            if (_softLockDiag)
            {
                long dMs = Environment.TickCount;
                if (dMs - _r3eLastSoftLockDiagMs >= 500
                    && (Math.Abs(s.SteerInputRaw) > 0.25f || (physLive && Math.Abs(physNow) > 0.25f)))
                {
                    _r3eLastSoftLockDiagMs = dMs;
                    var dci = System.Globalization.CultureInfo.InvariantCulture;
                    SimHub.Logging.Current.Info(
                        "[TF4ALL] SOFTLOCK r3e raw=" + s.SteerInputRaw.ToString("F3", dci)
                        + " phys=" + (physLive ? physNow.ToString("F3", dci) : "none")
                        + " wheelRot=" + s.WheelMaxRotationDeg.ToString(dci)
                        + " carRot=" + s.CarRotationDeg.ToString(dci)
                        + " steer=" + (frR3e.HasSteer ? frR3e.SteerNorm.ToString("F3", dci) : "none")
                        + " speed=" + (frR3e.HasSteer ? frR3e.SteerSpeed.ToString("F2", dci) : "-")
                        + " ratio=" + (_r3eAxisRatioN > 0 ? _r3eAxisRatio.ToString("F2", dci) : "-"));
                }
            }
            _irFrame = frR3e;

            if (prev == null)
            {
                var rd = _r3e;
                var ci = System.Globalization.CultureInfo.InvariantCulture;
                SimHub.Logging.Current.Info(
                    "[TF4ALL] R3E FFB: authoring force from "
                    + (rawScale > 0.5f
                        ? "SteeringForce (full scale " + rawScale.ToString("F1", ci) + ")"
                        : "SteeringForcePercentage")
                    + (_r3eInvert ? " INVERTED" : "")
                    + ", tick rate " + (rd != null ? rd.MeasuredHz.ToString("F0", ci) : "?")
                    + "/s. Disable RaceRoom's force feedback so the game is not also driving the wheel.");
            }
        }

        /// <summary>One probe line every ~2 s while R3EPROBE is on, kept alive
        /// even when the sim is paused and the tick counter is frozen so the
        /// control state stays visible. SimHub data thread.</summary>
        private void MaybeLogR3EProbe()
        {
            long now = Stopwatch.GetTimestamp();
            if (_r3eProbeLogTicks != 0 && (now - _r3eProbeLogTicks) < Stopwatch.Frequency * 2) return;
            _r3eProbeLogTicks = now;

            var rd = _r3e;
            if (rd == null) return;
            if (!rd.IsOpen)
            {
                SimHub.Logging.Current.Info("[TF4ALL] R3EPROBE waiting for RaceRoom ($R3E not found yet).");
                return;
            }
            var s = rd.LastSample;
            if (s == null)
            {
                SimHub.Logging.Current.Info("[TF4ALL] R3EPROBE map open (layout " + rd.VersionSeen + "), no sample yet.");
                return;
            }
            var inv = System.Globalization.CultureInfo.InvariantCulture;
            string ctrl = s.ControlType == 0 ? "player" : s.ControlType == 1 ? "AI"
                : s.ControlType == 2 ? "remote" : s.ControlType == 3 ? "replay"
                : s.ControlType.ToString(inv);
            SimHub.Logging.Current.Info(
                "[TF4ALL] R3EPROBE layout=" + rd.VersionSeen
                + " ticksPerSec=" + rd.MeasuredHz.ToString("F0", inv)
                + " force=" + s.SteeringForce.ToString("F3", inv)
                + " [" + _r3ePrMinF.ToString("F2", inv) + ".." + _r3ePrMaxF.ToString("F2", inv) + "]"
                + " pct=" + s.SteeringForcePct.ToString("F3", inv)
                + " [" + _r3ePrMinP.ToString("F2", inv) + ".." + _r3ePrMaxP.ToString("F2", inv) + "]"
                + " steer=" + s.SteerInputRaw.ToString("F2", inv)
                + " speedKmh=" + (s.CarSpeedMps * 3.6f).ToString("F0", inv)
                + " gear=" + s.Gear
                + " ctrl=" + ctrl
                + " paused=" + (s.GamePaused ? "Y" : "n")
                + " menus=" + (s.GameInMenus ? "Y" : "n")
                + " replay=" + (s.GameInReplay ? "Y" : "n")
                + " garage=" + (s.InGarage ? "Y" : "n")
                + " model=" + s.ModelId
                + " engine=" + (s.EngineType == R3EEngineCombustion ? "combustion"
                    : s.EngineType == R3EEngineElectric ? "electric"
                    : s.EngineType == R3EEngineHybrid ? "hybrid"
                    : s.EngineType.ToString(inv)) + ".");
            _r3ePrHave = false;   // fresh min/max window per line
        }

        // ---- Access-code surface (SettingsControl) ----

        /// <summary>R3EFFB: flip the RaceRoom shared-memory route. Enabling
        /// also opts RaceRoom into Telemetry Based FFB so one code is the
        /// whole A/B switch; disabling returns to the tap route.</summary>
        public bool ToggleR3ESharedMemoryFfb()
        {
            var s = Settings;
            if (s == null) return false;
            SetR3ETakeover(!s.R3ESharedMemoryFfb);
            return s.R3ESharedMemoryFfb;
        }

        /// <summary>Set the RaceRoom shared-memory route (R3EFFB) on or off. This
        /// is the FFB tab's "take over force feedback" checkbox for RaceRoom, and
        /// the R3EFFB access code routes through it too, so both are one A/B
        /// switch. Keeps the route flag and the per-game opt-in in lockstep: on
        /// arms the reshape, off returns to the tap route (never Mode B synthesis,
        /// which RaceRoom has no slip model for). Persists.</summary>
        public void SetR3ETakeover(bool on)
        {
            var s = Settings;
            if (s == null) return;
            s.R3ESharedMemoryFfb = on;
            if (s.ModeBGameEnabled == null) s.ModeBGameEnabled = new Dictionary<string, bool>();
            // Both RaceRoom game keys, so a settings file written under either name
            // stays consistent.
            s.ModeBGameEnabled["RaceRoomRacingExperience"] = on;
            s.ModeBGameEnabled["RRRE"] = on;
            ApplyModeBFromSettings(save: true);
            SimHub.Logging.Current.Info("[TF4ALL] R3E shared-memory FFB route " + (on ? "ON" : "OFF") + ".");
        }

        /// <summary>R3EFFB AUTO: toggle the R3E per-car auto-strength (persisted).
        /// Returns the new state (true = ON). Resets the learner so the change
        /// is felt from the current car's next ticks.</summary>
        public bool ToggleR3EAutoStrength()
        {
            var s = Settings;
            if (s == null) return false;
            bool on = !s.R3EAutoStrength;
            s.R3EAutoStrength = on;
            _r3eFullScaleFrac = 1f;
            _r3ePeakObs = 0f;
            _r3ePeakGrowthTicks = 0;
            _r3ePeakRacingMs = 0.0;
            _r3ePrevStrengthTicks = 0;
            _r3eLastLoadedCar = null;   // force a reload on the next sample
            try { PersistSettings(); } catch { }
            SimHub.Logging.Current.Info("[TF4ALL] R3E auto-strength " + (on ? "ON" : "OFF") + ".");
            return on;
        }

        /// <summary>R3EFFB DAMP access code: toggle or tune the R3E stationary
        /// friction. No number toggles it on/off; one number sets the parked
        /// strength (0..1 of full scale); a second sets the car speed (km/h) at
        /// which it fades to nothing. The FFB thread reads these live; persisted.</summary>
        public string SetR3EStationaryDamper(double? strength, double? fade)
        {
            var s = Settings;
            if (s == null) return "settings not ready";
            if (!strength.HasValue && !fade.HasValue)
            {
                s.R3EStationaryDamper = !s.R3EStationaryDamper;
                try { PersistSettings(); } catch { }
                SimHub.Logging.Current.Info("[TF4ALL] R3E stationary friction " + (s.R3EStationaryDamper ? "ON" : "OFF") + ".");
                return s.R3EStationaryDamper
                    ? $"R3E stationary friction ON: firm when parked (strength {s.R3EStationaryDamperStrength:0.00}), fading to nothing by {s.R3EStationaryDamperFadeKmh:0} km/h. Persists. Set strength with 'R3EFFB DAMP 0.5', fade with 'R3EFFB DAMP 0.5 30'."
                    : "R3E stationary friction OFF. Persists.";
            }
            if (strength.HasValue)
            {
                double v = strength.Value;
                if (v < 0.0) v = 0.0; else if (v > 1.0) v = 1.0;
                s.R3EStationaryDamperStrength = v;
                s.R3EStationaryDamper = v > 0.0001;
            }
            if (fade.HasValue)
            {
                double f = fade.Value;
                if (f < 1.0) f = 1.0; else if (f > 200.0) f = 200.0;
                s.R3EStationaryDamperFadeKmh = f;
            }
            try { PersistSettings(); } catch { }
            SimHub.Logging.Current.Info(
                $"[TF4ALL] R3E stationary friction: strength={s.R3EStationaryDamperStrength:0.00} fade={s.R3EStationaryDamperFadeKmh:0}km/h {(s.R3EStationaryDamper ? "on" : "off")}.");
            return $"R3E stationary friction: strength {s.R3EStationaryDamperStrength:0.00}, fades to nothing by {s.R3EStationaryDamperFadeKmh:0} km/h. {(s.R3EStationaryDamper ? "On" : "Off")}. Persists.";
        }

        private string R3EStrengthKey(string carId) =>
            string.IsNullOrEmpty(carId) ? null : (_activeGame ?? "") + "|" + carId;

        // Persist a car's applied R3E max (no disk I/O; the settings save cadence
        // writes it). Under _r3eStrengthLock.
        private void R3EStoreStrength(string carId, float peak)
        {
            var s = Settings; if (s == null) return;
            string key = R3EStrengthKey(carId); if (key == null) return;
            if (s.R3EStrengthByCar == null) s.R3EStrengthByCar = new Dictionary<string, R3ECarStrength>();
            s.R3EStrengthByCar[key] = new R3ECarStrength { Peak = peak };
        }

        private bool R3ETryLoadStrength(string carId, out float peak)
        {
            peak = 0f;
            var s = Settings; if (s?.R3EStrengthByCar == null) return false;
            string key = R3EStrengthKey(carId); if (key == null) return false;
            if (!s.R3EStrengthByCar.TryGetValue(key, out var v) || v == null) return false;
            peak = v.Peak;
            return true;
        }

        private bool R3EPeakIsForActiveCar =>
            string.Equals(_r3ePeakCarId, _activeCarId, StringComparison.Ordinal);

        /// <summary>True once the observed R3E peak has stopped climbing for a
        /// while AND enough driving has happened, so pressing Apply is worth it.
        /// Mirrors iRacing's IRacingPeakSettled.</summary>
        public bool R3EPeakSettled
        {
            get
            {
                if (!R3EPeakIsForActiveCar || _r3ePeakObs <= 0.02f || _r3ePeakGrowthTicks == 0) return false;
                if (_r3ePeakRacingMs < R3EPeakMinDriveMs) return false;
                double sinceMs = (Stopwatch.GetTimestamp() - _r3ePeakGrowthTicks) * 1000.0 / Stopwatch.Frequency;
                return sinceMs >= R3EPeakSettleMs;
            }
        }

        /// <summary>0..1 progress toward R3EPeakSettled, for a dash readout.</summary>
        public double R3EPeakConfidence
        {
            get
            {
                if (!R3EPeakIsForActiveCar || _r3ePeakObs <= 0.02f || _r3ePeakGrowthTicks == 0) return 0.0;
                double drive = _r3ePeakRacingMs / R3EPeakMinDriveMs; if (drive > 1.0) drive = 1.0;
                double sinceMs = (Stopwatch.GetTimestamp() - _r3ePeakGrowthTicks) * 1000.0 / Stopwatch.Frequency;
                double quiet = sinceMs / R3EPeakSettleMs; if (quiet > 1.0) quiet = 1.0;
                return drive < quiet ? drive : quiet;
            }
        }

        /// <summary>Apply the observed peak as this car's R3E max, once, the way
        /// iRacing's Auto button does: drive, wait for R3EPeakSettled, press,
        /// keep a value you can then nudge. Commits + resets the observer.
        /// Returns the applied max, or 0 if nothing has been observed yet.</summary>
        public float ApplyR3EAutoStrength()
        {
            string car; float applied;
            lock (_r3eStrengthLock)
            {
                if (!R3EPeakIsForActiveCar || _r3ePeakObs <= 0.02f) return 0f;
                applied = _r3ePeakObs;
                _r3eAppliedPeak = applied;
                car = _r3eLastLoadedCar;
                if (!string.IsNullOrEmpty(car)) R3EStoreStrength(car, applied);
                // Apply-and-reset: the next observation is "hardest since this press".
                _r3ePeakObs = 0f;
                _r3ePeakGrowthTicks = 0;
                _r3ePeakRacingMs = 0.0;
            }
            try { PersistSettings(); } catch { }
            SimHub.Logging.Current.Info($"[TF4ALL] R3E strength applied for '{car}': max = {applied:0.000}.");
            return applied;
        }

        /// <summary>Nudge the ACTIVE car's applied R3E max (persisted), like
        /// iRacing's Max Force nudge. steps &gt; 0 STRENGTHENS (lowers the max),
        /// &lt; 0 weakens; ~7% per step. Bound to R3EStrengthUp/Down.</summary>
        public void NudgeR3EStrength(int steps)
        {
            if (steps == 0) return;
            string car; float newPeak;
            lock (_r3eStrengthLock)
            {
                car = _r3eLastLoadedCar;
                float cur = _r3eAppliedPeak > 0.01f ? _r3eAppliedPeak : (float)AutoStrengthTarget;
                newPeak = cur * (float)Math.Pow(1.0 / 1.07, steps);   // stronger = smaller max
                if (newPeak < 0.08f) newPeak = 0.08f; else if (newPeak > 1.20f) newPeak = 1.20f;
                _r3eAppliedPeak = newPeak;
                if (!string.IsNullOrEmpty(car)) R3EStoreStrength(car, newPeak);
            }
            try { PersistSettings(); } catch { }
            SimHub.Logging.Current.Info(
                $"[TF4ALL] R3E max for '{car}' nudged to {newPeak:0.000} ({(steps > 0 ? "stronger" : "weaker")}).");
        }

        /// <summary>This car's applied R3E max (normalized), or 0 if none applied
        /// yet. The FFB tab shows it in an editable box.</summary>
        public float R3EAppliedPeak => _r3eAppliedPeak;

        /// <summary>The R3E max actually in use for the active car: the applied
        /// value, or the auto-strength target (which means no boost) when nothing
        /// is applied yet. This is the number the tab's "Car's max" box shows.</summary>
        public float R3EEffectivePeak => _r3eAppliedPeak > 0.01f ? _r3eAppliedPeak : (float)AutoStrengthTarget;

        /// <summary>The peak the active car is currently observed to push (0 while
        /// none seen), so the tab can show what the car actually makes.</summary>
        public float R3EObservedPeak => R3EPeakIsForActiveCar ? _r3ePeakObs : 0f;

        /// <summary>Set the active car's R3E max directly (the tab's editable box
        /// and typed edits). Lower = heavier (more boost), higher = lighter.
        /// Clamped and persisted per car.</summary>
        public void SetR3EAppliedPeak(float peak)
        {
            if (peak < 0.08f) peak = 0.08f; else if (peak > 1.5f) peak = 1.5f;
            string car;
            lock (_r3eStrengthLock)
            {
                car = _r3eLastLoadedCar;
                _r3eAppliedPeak = peak;
                if (!string.IsNullOrEmpty(car)) R3EStoreStrength(car, peak);
            }
            try { PersistSettings(); } catch { }
            SimHub.Logging.Current.Info($"[TF4ALL] R3E max for '{car}' set to {peak:0.000}.");
        }

        public bool ToggleR3EProbe()
        {
            _r3eProbe = !_r3eProbe;
            _r3ePrHave = false;
            _r3eProbeLogTicks = 0;
            SimHub.Logging.Current.Info("[TF4ALL] R3EPROBE " + (_r3eProbe ? "ON" : "OFF") + ".");
            return _r3eProbe;
        }

        public bool ToggleR3EForceInvert()
        {
            _r3eInvert = !_r3eInvert;
            return _r3eInvert;
        }

        public double SetR3ERawFullScaleNm(double nm)
        {
            float v = (float)(nm < 1.0 ? 1.0 : nm);
            _r3eRawFullScaleNm = v;
            return v;
        }

        public void UseR3EPctChannel() => _r3eRawFullScaleNm = 0f;

        // ---- Le Mans Ultimate handover (LMUFFB) ----
        // The RaceRoom route's shape on the sim's official "LMU_Data" shared
        // memory: the reader publishes the player's physics updates, this
        // handler turns each into the FixedScale torque frame the iRacing
        // consumer renders, and the stationary friction, the spring and the
        // soft lock are the RaceRoom ones, shared. What differs: the force is
        // mSteeringShaftTorque in Nm (RaceRoom publishes a percentage), so the
        // strength is iRacing's model, the car's peak force in Nm kept per
        // car, with LmuFullScaleNm as the scale until a car has one; and the
        // sim has Trueforce of its own, which must be off in the game before
        // any of this runs (the native stand-down drops the plugin to
        // Lightsync only otherwise).

        /// <summary>Once per SimHub tick: run or stop the "LMU_Data" reader
        /// for the active game. Cheap and silent for every other game.</summary>
        private void LmuTelemetryTick()
        {
            var cfg = Settings;
            bool want = IsLmuGame(_activeGame)
                && MasterMode == TrueforceMasterMode.Normal
                && (_lmuProbe || (cfg?.LmuSharedMemoryFfb ?? false));
            if (!want) { StopLmuDirect(); return; }

            if (_lmu == null)
            {
                _lmu = new LmuSharedMemoryReader
                {
                    Logger = msg => SimHub.Logging.Current.Info("[TF4ALL] " + msg),
                    OnSample = LmuDirectSample,
                };
            }
            if (!_lmuLive)
            {
                _lmu.Start();   // the reader retries the open itself while the sim is absent
                _lmuLive = true;
                SimHub.Logging.Current.Info("[TF4ALL] LMU shared-memory reader started"
                    + (_lmuProbe ? " (probe on)" : "") + ".");
            }

            if (_lmuProbe) MaybeLogLmuProbe();

            // The handover publishes frames from the game's own shared memory,
            // but the force producer still takes the session state (paused,
            // menu, not running) from SimHub's telemetry, and SimHub reads
            // this game through its rFactor 2 plugin, which the driver has to
            // let SimHub install. With that plugin disabled SimHub delivers
            // nothing, the producer holds the wheel released as for a pause,
            // and the route's frames go nowhere (rig, 2026-09-20). Say so.
            var lmuRd = _lmu;
            var lmuSrc = _telemetrySource;
            if ((cfg?.LmuSharedMemoryFfb ?? false) && lmuRd != null
                && (lmuRd.LastSample?.PlayerHasVehicle ?? false)
                && (lmuSrc == null || lmuSrc.MsSinceLastFrame > 3000))
            {
                long nowMs = Environment.TickCount;
                if (nowMs - _lmuNoSimHubLogMs >= 60000)
                {
                    _lmuNoSimHubLogMs = nowMs;
                    SimHub.Logging.Current.Warn(
                        "[TF4ALL] Le Mans Ultimate is on track by its own shared memory, but SimHub has delivered no "
                        + "telemetry for it, so the force pipeline holds the wheel released as for a pause. SimHub reads "
                        + "this game through its rFactor 2 plugin: with the game closed, open SimHub's Games page, pick "
                        + "Le Mans Ultimate and let SimHub configure it (it enables the plugin in the game's "
                        + "CustomPluginVariables.JSON), then start the game again.");
                }
            }
        }

        private void StopLmuDirect()
        {
            if (_lmu == null || !_lmuLive) return;
            _lmuLive = false;
            try { _lmu.Stop(); } catch { }
            SimHub.Logging.Current.Info("[TF4ALL] LMU shared-memory reader stopped.");
        }

        /// <summary>Reader thread, once per NEW physics update: aggregate for
        /// the probe and, while the handover is armed, publish the force frame
        /// the iRacing consumer already knows how to render.</summary>
        private void LmuDirectSample(LmuFfbSample s)
        {
            if (_lmuProbe)
            {
                float tv = (float)s.ShaftTorqueNm, fv = s.FfbTorque;
                if (!_lmuPrHave)
                {
                    _lmuPrMinT = _lmuPrMaxT = tv;
                    _lmuPrMinF = _lmuPrMaxF = fv;
                    _lmuPrHave = true;
                }
                else
                {
                    if (tv < _lmuPrMinT) _lmuPrMinT = tv;
                    if (tv > _lmuPrMaxT) _lmuPrMaxT = tv;
                    if (fv < _lmuPrMinF) _lmuPrMinF = fv;
                    if (fv > _lmuPrMaxF) _lmuPrMaxF = fv;
                }
            }

            if (_forceMode != ForceModeIRacing || !IsLmuGame(_activeGame)) return;
            var cfg = Settings;
            if (cfg == null || !cfg.LmuSharedMemoryFfb) return;

            // Player at the wheel, actually driving: in the car (realtime, not
            // the monitor), the scoring row says the local player controls it,
            // and not sat in the garage stall. Anything else (AI, remote,
            // replay, monitor, garage, a scoring row not found yet) publishes
            // nothing and the 250 ms age gate in ComputeIRacingForce decays
            // whatever was last shown: same shape as iRacing's IsOnTrack guard
            // against the parked-car runaway. A pause freezes the elapsed
            // time, so no sample arrives and the same gate covers it.
            bool inCar = s.PlayerHasVehicle && s.InRealtime && s.ScoringMatched
                && s.Control == 0 && !s.InGarageStall && s.GamePhase != 9;
            if (!inCar) { _irFrame = null; return; }

            float latest = (float)s.ShaftTorqueNm;
            if (float.IsNaN(latest) || float.IsInfinity(latest)) return;
            float maxNm = cfg.LmuFullScaleNm;
            if (!(maxNm >= 1f)) maxNm = 50f;
            // Sign. The sim's shaft torque reads OPPOSITE to the takeover's
            // authored space (owner's rig, 2026-09-20: as published, the wheel
            // pulled into corners), so it is negated here. LMUFFB INV flips it
            // back for a rig that reads the other way.
            latest = -latest;
            if (_lmuInvert) latest = -latest;

            // iRacing's learner, since the torque is Nm here too: the peak this
            // car pushes on track, adopted as its max force by the Auto button.
            // "Racing" = out of the pit lane and moving, iRacing's own bar.
            LearnIRacingPeak(Math.Abs(latest), !s.InPits && s.SpeedMps > 10f);

            var prev = _irFrame;
            var fr = new IRacingTorqueFrame
            {
                Sub = null,          // no sub-tick history; the scalar holds
                Latest = latest,
                MaxNm = maxNm,       // the fallback full scale until this car
                                     // has a max force of its own
                GameFfbOn = false,   // LMU publishes no such flag, and needs
                                     // none: the wheel drops the game's slots
                                     // while our stream runs
                FixedScale = false,  // scaled by the car's Nm, as iRacing's are
                Ticks = Stopwatch.GetTimestamp(),
            };
            // Steering for the soft lock, from the PHYSICAL wheel position as
            // the RaceRoom route does. What the lock needs is the wheel's
            // rotation over the car's (the car's is the visual range the sim
            // publishes; its physical range field reads 0 on the rig,
            // 2026-09-20). Two sources, measured first:
            //   - the sim's raw axis over the physical position. With "Range
            //     From Vehicle" and a wheel it could not re-range, the sim
            //     rescales its axis so the car's lock is +/-1 and clamps
            //     there, exactly as RaceRoom's does, and that ratio IS the
            //     wheel's rotation over the car's. Averaged where both are
            //     well off centre and the raw axis is short of its clamp.
            //   - a rotation range the tap saw the host set on the wheel.
            // A ratio near 1 means the sim's axis is the device axis: either
            // the wheel's stop already is the car's lock, or the sim does not
            // rescale, and with no range in degrees from anywhere the two
            // cannot be told apart, so the lock stays quiet and says so.
            var physRd = _steeringReader;
            bool physLive = physRd != null && physRd.IsRunning && physRd.LastUpdateTicks != 0;
            float physNow = physLive ? physRd.SteerNorm : float.NaN;
            int carRot = (int)Math.Round(s.VisualRangeDeg);
            if (carRot != _lmuAxisRatioCarRot)
            {
                // The ratio is per car (its lock differs); start over.
                _lmuAxisRatioCarRot = carRot;
                _lmuAxisRatioN = 0;
                _lmuAxisRatio = 0f;
            }
            float rawSteer = s.SteerUnfiltered;
            bool steerSlow = Math.Abs(rawSteer - _lmuPrevRawSteer) < 0.01f;   // under 1% per update
            _lmuPrevRawSteer = rawSteer;
            if (physLive && steerSlow && Math.Abs(rawSteer) > 0.25f && Math.Abs(rawSteer) < 0.97f
                && Math.Abs(physNow) > 0.1f)
            {
                float ratio = Math.Abs(rawSteer) / Math.Abs(physNow);
                if (ratio > 0.2f && ratio < 5f)
                {
                    _lmuAxisRatio = _lmuAxisRatioN == 0 ? ratio : _lmuAxisRatio + (ratio - _lmuAxisRatio) * 0.02f;
                    if (_lmuAxisRatioN < int.MaxValue) _lmuAxisRatioN++;
                }
            }
            float wheelOverCar = float.NaN;
            string lockSrc = null;
            if (_lmuAxisRatioN >= LmuAxisRatioSettleN)
            {
                if (_lmuAxisRatio > 1.03f) { wheelOverCar = _lmuAxisRatio; lockSrc = "measured"; }
                else lockSrc = "device axis";
            }
            if (float.IsNaN(wheelOverCar) && lockSrc == null)
            {
                // Only until the measurement settles, and only if the visual
                // range is the car's lock, which the rig says it is not
                // (ratio 2.0 against 1080 over 719), so this rarely helps.
                int tapDeg = _ffbTap?.ObservedRotationRangeDeg ?? 0;
                if (tapDeg >= 180 && carRot >= 40 && tapDeg > carRot + 10)
                {
                    wheelOverCar = (float)tapDeg / carRot;
                    lockSrc = "range the host set (" + tapDeg + " degrees)";
                }
            }
            MaybeLogLmuSteerLock(carRot, wheelOverCar, lockSrc);
            if (!float.IsNaN(wheelOverCar) && physLive && !float.IsNaN(physNow))
            {
                StampSteerFields(IRacingSoftLock.SignedByPhysical(physNow * wheelOverCar, physNow),
                                 carRot * 0.5f, fr.Ticks, fr);
            }
            else if (!physLive && (Settings?.IRacingSoftLockEnabled ?? false))
            {
                long wMs = Environment.TickCount;
                if (wMs - _lmuNoPhysLogMs >= 60000)
                {
                    _lmuNoPhysLogMs = wMs;
                    SimHub.Logging.Current.Warn(
                        "[TF4ALL] Le Mans Ultimate soft lock: no physical steering position from the wheel "
                        + (physRd == null ? "(steering reader not started)"
                           : "(steering reader stopped; it will try to reopen)")
                        + ", so no lock is rendered.");
                }
            }
            _irFrame = fr;

            if (prev == null)
            {
                var rd = _lmu;
                var ci = System.Globalization.CultureInfo.InvariantCulture;
                SimHub.Logging.Current.Info(
                    "[TF4ALL] LMU FFB: authoring force from mSteeringShaftTorque (full scale "
                    + maxNm.ToString("F1", ci) + " Nm)"
                    + (_lmuInvert ? " (sign flipped back by LMUFFB INV)" : "")
                    + ", update rate " + (rd != null ? rd.MeasuredHz.ToString("F0", ci) : "?")
                    + "/s.");
            }
        }

        /// <summary>Say, once per change, what the soft lock is built from in
        /// this car: the measured axis ratio, a range the host was seen
        /// setting, or nothing yet (with why).</summary>
        private void MaybeLogLmuSteerLock(int carRot, float wheelOverCar, string src)
        {
            string key = carRot + "|" + (src ?? "-") + "|"
                + (float.IsNaN(wheelOverCar) ? "-" : ((int)Math.Round(wheelOverCar * 4f)).ToString());
            if (key == _lmuLockLogKey) return;
            _lmuLockLogKey = key;
            var ci = System.Globalization.CultureInfo.InvariantCulture;
            string head = "[TF4ALL] Le Mans Ultimate soft lock: the car's wheel animates through " + carRot + " degrees; ";
            if (!float.IsNaN(wheelOverCar))
            {
                SimHub.Logging.Current.Info(head
                    + (src == "measured"
                        ? "the sim's steering axis reads " + wheelOverCar.ToString("F2", ci) + " times the physical position, so the car's lock"
                        : "the " + src + " puts the car's lock")
                    + " sits at " + ((int)Math.Round(100f / wheelOverCar)) + " percent of the wheel's travel, and the wall goes there.");
            }
            else if (src == "device axis")
            {
                SimHub.Logging.Current.Info(head
                    + "the sim's raw axis equals the physical position, so either the wheel's stop already is the car's lock "
                    + "or the sim is not rescaling; with no rotation range in degrees from the sim or the host, the lock stays quiet.");
            }
            else
            {
                SimHub.Logging.Current.Info(head
                    + "measuring the sim's raw axis against the wheel (a few seconds of cornering) before the lock is placed.");
            }
        }

        /// <summary>One probe line every ~2 s while LMUPROBE is on, kept alive
        /// even when the sim is paused so the session state stays visible.
        /// SimHub data thread.</summary>
        private void MaybeLogLmuProbe()
        {
            long now = Stopwatch.GetTimestamp();
            if (_lmuProbeLogTicks != 0 && (now - _lmuProbeLogTicks) < Stopwatch.Frequency * 2) return;
            _lmuProbeLogTicks = now;

            var rd = _lmu;
            if (rd == null) return;
            if (!rd.IsOpen)
            {
                SimHub.Logging.Current.Info("[TF4ALL] LMUPROBE waiting for Le Mans Ultimate (LMU_Data not found yet).");
                return;
            }
            var s = rd.LastSample;
            if (s == null)
            {
                SimHub.Logging.Current.Info("[TF4ALL] LMUPROBE map open (game version " + rd.VersionSeen + "), no sample yet.");
                return;
            }
            var inv = System.Globalization.CultureInfo.InvariantCulture;
            if (!s.PlayerHasVehicle)
            {
                SimHub.Logging.Current.Info("[TF4ALL] LMUPROBE version=" + rd.VersionSeen
                    + " no player vehicle (at the monitor or between sessions), ffbHz="
                    + rd.MeasuredFfbHz.ToString("F0", inv) + ".");
                return;
            }
            string ctrl = s.Control == 0 ? "player" : s.Control == 1 ? "AI"
                : s.Control == 2 ? "remote" : s.Control == 3 ? "replay"
                : s.ScoringMatched ? s.Control.ToString(inv) : "unmatched";
            SimHub.Logging.Current.Info(
                "[TF4ALL] LMUPROBE version=" + rd.VersionSeen
                + " updatesPerSec=" + rd.MeasuredHz.ToString("F0", inv)
                + " ffbHz=" + rd.MeasuredFfbHz.ToString("F0", inv)
                + " torqueNm=" + s.ShaftTorqueNm.ToString("F3", inv)
                + " [" + _lmuPrMinT.ToString("F2", inv) + ".." + _lmuPrMaxT.ToString("F2", inv) + "]"
                + " ffb=" + s.FfbTorque.ToString("F3", inv)
                + " [" + _lmuPrMinF.ToString("F2", inv) + ".." + _lmuPrMaxF.ToString("F2", inv) + "]"
                + " steer=" + s.SteerUnfiltered.ToString("F2", inv)
                + " physRange=" + s.PhysicalRangeDeg.ToString("F0", inv)
                + " visRange=" + s.VisualRangeDeg.ToString("F0", inv)
                + " speedKmh=" + (s.SpeedMps * 3.6f).ToString("F0", inv)
                + " gear=" + s.Gear
                + " phase=" + s.GamePhase
                + " realtime=" + (s.InRealtime ? "Y" : "n")
                + " ctrl=" + ctrl
                + " garage=" + (s.InGarageStall ? "Y" : "n")
                + " pits=" + (s.InPits ? "Y" : "n")
                + " car='" + s.VehicleName + "'.");
            _lmuPrHave = false;   // fresh min/max window per line
        }

        /// <summary>LMUFFB: flip the Le Mans Ultimate handover. Enabling also
        /// opts the game into Telemetry Based FFB so one code is the whole
        /// switch; disabling returns to the tap route.</summary>
        public bool ToggleLmuSharedMemoryFfb()
        {
            var s = Settings;
            if (s == null) return false;
            SetLmuTakeover(!s.LmuSharedMemoryFfb);
            return s.LmuSharedMemoryFfb;
        }

        /// <summary>Set the Le Mans Ultimate handover on or off. This is the
        /// FFB tab's "take over force feedback" checkbox for the game, and the
        /// LMUFFB access code routes through it too. Keeps the route flag and
        /// the per-game opt-in in lockstep: on arms the reshape, off returns to
        /// the tap route. Persists.</summary>
        public void SetLmuTakeover(bool on)
        {
            var s = Settings;
            if (s == null) return;
            s.LmuSharedMemoryFfb = on;
            if (s.ModeBGameEnabled == null) s.ModeBGameEnabled = new Dictionary<string, bool>();
            s.ModeBGameEnabled["LMU"] = on;
            ApplyModeBFromSettings(save: true);
            SimHub.Logging.Current.Info("[TF4ALL] LMU shared-memory FFB route " + (on ? "ON" : "OFF") + ".");
        }

        public bool ToggleLmuProbe()
        {
            _lmuProbe = !_lmuProbe;
            _lmuPrHave = false;
            _lmuProbeLogTicks = 0;
            SimHub.Logging.Current.Info("[TF4ALL] LMUPROBE " + (_lmuProbe ? "ON" : "OFF") + ".");
            return _lmuProbe;
        }

        public bool ToggleLmuForceInvert()
        {
            _lmuInvert = !_lmuInvert;
            return _lmuInvert;
        }

        /// <summary>LMUFFB NM n: the shaft torque, in Nm, that is full wheel
        /// force before a car's own peak is applied. Persists.</summary>
        public double SetLmuFullScaleNm(double nm)
        {
            float v = (float)(nm < 1.0 ? 1.0 : nm > 100.0 ? 100.0 : nm);
            var s = Settings;
            if (s != null)
            {
                s.LmuFullScaleNm = v;
                try { PersistSettings(); } catch { }
            }
            return v;
        }

        /// <summary>Called on the reader's own thread, once per sim tick. Builds
        /// exactly the same latches the SimHub path builds, from the same
        /// channels, so everything downstream is unaware of which route is live.</summary>
        private void IRacingDirectTick()
        {
            var r = _irSdk;
            if (r == null || !_irSdkLive) return;
            try
            {
                byte[] frame;
                Dictionary<string, IRacingSdkReader.VarDef> vars;
                if (!r.TryGetSnapshot(out frame, out vars)) return;

                // Demote the moment the sim disconnects rather than waiting for
                // the force path to notice a stale latch.
                if (!r.IsConnected) { _irSdkLive = false; return; }

                double torque, maxNm;
                if (!SdkScalar(frame, vars, "SteeringWheelTorque", out torque)
                    || !SdkScalar(frame, vars, "SteeringWheelMaxForceNm", out maxNm))
                {
                    // Never silent: with the reader live the SimHub copy is
                    // not consulted, so a missing channel here is a dead wheel
                    // with no other line in the log (rig, 2026-09-13).
                    if (!_irSdkChannelsMissingLogged)
                    {
                        _irSdkChannelsMissingLogged = true;
                        SimHub.Logging.Current.Warn(
                            "[TF4ALL] iRacing direct reader: SteeringWheelTorque / SteeringWheelMaxForceNm not in the sim's "
                            + vars.Count.ToString(System.Globalization.CultureInfo.InvariantCulture)
                            + "-channel table, so no force is authored from it.");
                    }
                    return;
                }
                _irSdkChannelsMissingLogged = false;
                if (!(maxNm > 0.01)) return;

                double ffbOnD;
                bool ffbOn = SdkScalar(frame, vars, "SteeringFFBEnabled", out ffbOnD) && ffbOnD != 0.0;

                // Dash halves first: these keep working with the driver OUT
                // of the car (menu, replay, tow), where the force must not.
                double peakNm;
                if (!SdkScalar(frame, vars, "SteeringWheelPeakForceNm", out peakNm)) peakNm = -1.0;
                MaybeLogIRacingFullScale(maxNm, peakNm);
                MaybeParseIRacingSessionYaml(r);

                // Incident count rides the same snapshot. It HAS to be read
                // here: IRacingTelemetryTick (which hosts the SimHub-route
                // incidents tick) returns before it the moment this reader is
                // live, so without this call the feature is dark on every
                // healthy rig. Same channel priority as ReadIncidentCount.
                double inc;
                if (SdkScalar(frame, vars, "PlayerCarMyIncidentCount", out inc)
                    || SdkScalar(frame, vars, "PlayerCarDriverIncidentCount", out inc)
                    || SdkScalar(frame, vars, "PlayerCarTeamIncidentCount", out inc))
                {
                    if (inc >= 0.0) ConsumeIncidentCount((int)inc, "direct");
                }

                // Force half: ONLY while the driver is actually in the car.
                // Out of the car (hold ESC to the menu, tow, replay) iRacing
                // keeps publishing a steering torque for the PARKED car, and
                // at standstill that torque follows the wheel's displacement
                // instead of centering it, so reproducing it faithfully is a
                // positive-feedback runaway to full lock (owner, 2026-08-13:
                // wheel left of center pulled hard left until back in car).
                // Drop the latch outright so the wheel goes light NOW instead
                // of aging out a held force. The texture overlay and the peak
                // learner are gated with it: neither means anything out of
                // the car.
                double onTrackD;
                bool inCar = SdkScalar(frame, vars, "IsOnTrack", out onTrackD) && onTrackD != 0.0;
                if (!inCar)
                {
                    _irFrame = null;
                    return;
                }

                float[] sub = SdkArray(frame, vars, "SteeringWheelTorque_ST");
                if (sub != null && sub.Length < IRacingSubSamples) sub = null;

                // Kerb strikes softened here, on our own copy of the samples,
                // so the frame the force thread sees is already the one to play.
                long nowT = Stopwatch.GetTimestamp();
                float latestF = (float)torque;
                if (sub != null && (Settings?.IRacingKerbSofteningEnabled ?? false))
                {
                    double matD, pLF, pRF;
                    bool onStrip = (SdkScalar(frame, vars, "PlayerTrackSurfaceMaterial", out matD)
                                    && matD >= 10.5 && matD <= 14.5)   // irsdk_TrkSurf rumble strips are 11 to 14
                        || (SdkScalar(frame, vars, "TireLF_RumblePitch", out pLF) && pLF > 0.0)
                        || (SdkScalar(frame, vars, "TireRF_RumblePitch", out pRF) && pRF > 0.0);
                    SoftenIRacingKerbStrikes(sub, ref latestF,
                        SdkArray(frame, vars, "LFshockVel_ST"), SdkArray(frame, vars, "RFshockVel_ST"),
                        SdkArray(frame, vars, "LRshockVel_ST"), SdkArray(frame, vars, "RRshockVel_ST"),
                        nowT, (float)maxNm, onStrip);
                }
                else _kerbPrevTicks = 0;

                var fr = new IRacingTorqueFrame
                {
                    Sub = sub,
                    Latest = latestF,
                    MaxNm = (float)maxNm,
                    GameFfbOn = ffbOn,
                    Ticks = nowT,
                };
                // Steering for the soft lock, filled in BEFORE the frame is
                // published so the force thread never sees a half-built one.
                double slAngle, slMax;
                if (SdkScalar(frame, vars, "SteeringWheelAngle", out slAngle)
                    && SdkScalar(frame, vars, "SteeringWheelAngleMax", out slMax))
                    IRacingSteerFields(slAngle, slMax, fr.Ticks, fr);
                _irFrame = fr;

                BuildIRacingOverlayFromSdk(frame, vars, maxNm);
            }
            catch { /* never let the reader thread die on one bad tick */ }
        }

        private static bool SdkScalar(byte[] frame, Dictionary<string, IRacingSdkReader.VarDef> vars,
                                      string name, out double value)
        {
            value = 0.0;
            IRacingSdkReader.VarDef v;
            if (vars == null || !vars.TryGetValue(name, out v)) return false;
            return IRacingSdkReader.TryReadDouble(frame, v, 0, out value);
        }

        // ---- Kerb strike softening for the takeover (producer thread) ------
        // One producer runs at a time (the direct reader, or SimHub's copy
        // while the reader is not live), and both call
        // SoftenIRacingKerbStrikes on the six torque sub-samples before the
        // frame is published, so the state below is single-writer. The FFB
        // thread only ever sees the finished frame.
        private float _kerbBaseNm;         // running average of the torque the wheel gets, Nm
        private float _kerbLevelMps;       // slow average of shock speed between strikes, m/s
        private float _kerbPrevMask;       // the last sub-sample's mask, for the dilation across frames
        private long  _kerbPrevTicks;      // last frame softened; a gap resets the average
        private bool  _kerbInStrike;
        private long  _kerbLastLogTicks;
        private long  _kerbStripUntilTicks;  // the surface flag said "rumble strip"; held a little past it
        private const float KerbStripHoldMs = 120f;
        private int   _kerbLogCount;       // the strike line stops after KerbLogMax a session
        private const int KerbLogMax = 60;
        private readonly float[] _kerbShock = new float[IRacingSubSamples];
        private readonly float[] _kerbMask  = new float[IRacingSubSamples];
        private readonly float[] _kerbDil   = new float[IRacingSubSamples];
        // Calibrated on the rig (MX-5, 2026-09-13): the road between strikes
        // reads 0.03 to 0.12 m/s, kerbs and hits 0.36 to 0.75. The first guess
        // (floor 0.35, full mask at twice the threshold) sat on top of the
        // strikes and cut them by a percent or two.
        private const float KerbShockFloorMps  = 0.25f;   // below this a shock speed is never a strike
        private const float KerbShockLevelMult = 2.5f;    // a strike is this many times the running level
        private const float KerbShockCeilMps   = 0.40f;   // a rough track raises the bar, but never past this
        private const float KerbMaskRampMps    = 0.15f;   // the mask goes 0 to 1 over this much above the threshold
        private const float KerbBaseAlpha      = 0.085f;  // ~30 ms at 360 Hz: follows the load, not the spike
        private const float KerbLevelAlpha     = 0.0014f; // ~2 s at 360 Hz

        /// <summary>Soften the torque sub-samples that coincide with a shock
        /// burst on a wheel. The fronts carry the steering, so they set the
        /// mask; the rears count half. A sample's mask grows from 0 at the
        /// threshold to 1 a small step above it, is widened by one sample each way so
        /// a spike that lands a sample off the burst is still covered, and
        /// blends that sample toward the running average of the torque by
        /// the user's strength. The threshold is a floor or a multiple of a
        /// slow average of the shock speed between strikes, whichever is
        /// higher, so a bumpy track raises its own bar. One log line per
        /// strike, rate-limited, carries the numbers for tuning.</summary>
        private void SoftenIRacingKerbStrikes(float[] sub, ref float latest,
                                              float[] lf, float[] rf, float[] lr, float[] rr,
                                              long ticks, float maxNm, bool onStrip)
        {
            var cfg = Settings;
            if (cfg == null || sub == null || lf == null || rf == null
                || lf.Length < IRacingSubSamples || rf.Length < IRacingSubSamples)
            { _kerbPrevTicks = 0; return; }
            float strength = cfg.IRacingKerbSoftening;
            if (strength <= 0f) { _kerbPrevTicks = 0; return; }
            if (strength > 1f) strength = 1f;
            float sens = cfg.IRacingKerbSensitivity;
            if (!(sens > 0.05f)) sens = 1f;
            bool rearsOk = lr != null && rr != null
                && lr.Length >= IRacingSubSamples && rr.Length >= IRacingSubSamples;
            // One bad torque sample would otherwise sit in the average until
            // the next gap; the frame passes untouched instead.
            for (int i = 0; i < IRacingSubSamples; i++)
                if (float.IsNaN(sub[i]) || float.IsInfinity(sub[i])) { _kerbPrevTicks = 0; return; }

            // A gap (pause, out of the car) means the average is stale.
            bool fresh = _kerbPrevTicks != 0
                && (ticks - _kerbPrevTicks) * 1000.0 / Stopwatch.Frequency < 250.0;
            _kerbPrevTicks = ticks;

            float peakShock = 0f, minShock = float.MaxValue;
            int quietest = 0;
            for (int i = 0; i < IRacingSubSamples; i++)
            {
                float v = Math.Max(Math.Abs(lf[i]), Math.Abs(rf[i]));
                if (rearsOk) v = Math.Max(v, 0.5f * Math.Max(Math.Abs(lr[i]), Math.Abs(rr[i])));
                if (float.IsNaN(v) || float.IsInfinity(v)) v = 0f;
                _kerbShock[i] = v;
                if (v > peakShock) peakShock = v;
                if (v < minShock) { minShock = v; quietest = i; }
            }
            if (!fresh)
            {
                // Seeded from the quietest sample of the frame, so a resume
                // that lands mid-strike does not make the strike the average
                // (model, 2026-09-13).
                _kerbBaseNm = sub[quietest];
                _kerbPrevMask = 0f;
                _kerbInStrike = false;
                _kerbStripUntilTicks = 0;
            }
            if (!fresh || _kerbLevelMps <= 0f)
                _kerbLevelMps = Math.Min(minShock, KerbShockFloorMps);
            float threshold = Math.Min(KerbShockCeilMps,
                                  Math.Max(KerbShockFloorMps, KerbShockLevelMult * _kerbLevelMps)) / sens;

            for (int i = 0; i < IRacingSubSamples; i++)
            {
                float m = (_kerbShock[i] - threshold) / KerbMaskRampMps;
                _kerbMask[i] = m <= 0f ? 0f : (m >= 1f ? 1f : m);
                // The level learns only from the quiet samples, so a strike
                // never raises its own bar.
                if (_kerbMask[i] <= 0f)
                    _kerbLevelMps += (_kerbShock[i] - _kerbLevelMps) * KerbLevelAlpha;
            }
            // Riding a rumble strip: a front tyre's rumble pitch (per tyre,
            // nonzero while it is on a strip) or the car's surface flag says
            // so, and the ridges that do not trip the shock detector are still
            // the buzz the driver feels, so the whole traverse is masked. Held
            // a little past the flag so its exit lag does not leave a hard tail
            // (owner, 2026-09-13: strikes softened, strips not; the car-level
            // flag alone fired three times in three minutes of strips).
            if (onStrip)
                _kerbStripUntilTicks = ticks + (long)(KerbStripHoldMs / 1000.0 * Stopwatch.Frequency);
            bool strip = ticks < _kerbStripUntilTicks;
            if (strip)
                for (int i = 0; i < IRacingSubSamples; i++) _kerbMask[i] = 1f;

            float prevM = _kerbPrevMask;
            float maxMask = 0f;
            for (int i = 0; i < IRacingSubSamples; i++)
            {
                float next = i + 1 < IRacingSubSamples ? _kerbMask[i + 1] : _kerbMask[i];
                float d = Math.Max(prevM, Math.Max(_kerbMask[i], next));
                prevM = _kerbMask[i];
                _kerbDil[i] = d;
                if (d > maxMask) maxMask = d;
            }
            _kerbPrevMask = _kerbMask[IRacingSubSamples - 1];

            float peakRawAbs = 0f, peakRaw = 0f, peakOutAbs = 0f, peakOut = 0f;
            for (int i = 0; i < IRacingSubSamples; i++)
            {
                float raw = sub[i];
                float bse = _kerbBaseNm;
                float d = _kerbDil[i];
                if (d > 0f)
                {
                    float outV = bse + (raw - bse) * (1f - strength * d);
                    // Softening only ever reduces: an average that crept up
                    // under the strike must not lift the quiet sample on the
                    // way out of it (model, 2026-09-13).
                    if (Math.Abs(outV) > Math.Abs(raw)) outV = raw;
                    sub[i] = outV;
                    float ra = Math.Abs(raw), oa = Math.Abs(outV);
                    if (ra > peakRawAbs) { peakRawAbs = ra; peakRaw = raw; }
                    if (oa > peakOutAbs) { peakOutAbs = oa; peakOut = outV; }
                }
                // The average follows the raw torque at full rate between
                // strikes and at a quarter of it under a mask, so a load that
                // changes under a strike is partly followed and the rest lands
                // when the mask clears.
                _kerbBaseNm = bse + (raw - bse) * KerbBaseAlpha * Math.Max(0.25f, 1f - d);
            }
            latest = sub[IRacingSubSamples - 1];

            if (maxMask > 0f)
            {
                if (!_kerbInStrike)
                {
                    _kerbInStrike = true;
                    if (_kerbLogCount < KerbLogMax
                        && (ticks - _kerbLastLogTicks) * 1000.0 / Stopwatch.Frequency >= 500.0)
                    {
                        _kerbLastLogTicks = ticks;
                        _kerbLogCount++;
                        int n = 0;
                        for (int i = 0; i < IRacingSubSamples; i++) if (_kerbDil[i] > 0f) n++;
                        var ci = System.Globalization.CultureInfo.InvariantCulture;
                        double full = maxNm > 0.01f ? maxNm : 1.0;
                        SimHub.Logging.Current.Info(
                            "[TF4ALL] iRacing curb strike: shock " + peakShock.ToString("0.00", ci)
                            + " m/s (level " + _kerbLevelMps.ToString("0.00", ci)
                            + ", threshold " + threshold.ToString("0.00", ci) + "), "
                            + n.ToString(ci) + " of 6 samples softened, torque "
                            + ((int)(peakRaw * 100.0 / full)).ToString(ci) + "% -> "
                            + ((int)(peakOut * 100.0 / full)).ToString(ci) + "% at the peak."
                            + (strip ? " On a rumble strip." : "")
                            + (_kerbLogCount >= KerbLogMax ? " (Last strike line this session.)" : ""));
                    }
                }
            }
            else _kerbInStrike = false;
        }

        private static float[] SdkArray(byte[] frame, Dictionary<string, IRacingSdkReader.VarDef> vars, string name)
        {
            IRacingSdkReader.VarDef v;
            if (vars == null || !vars.TryGetValue(name, out v)) return null;
            return IRacingSdkReader.TryReadArray(frame, v);
        }

        /// <summary>The same overlay the SimHub path builds, from the same
        /// channels and the same derivations, just resolved out of the direct
        /// snapshot. Downstream must not be able to tell which route produced it.
        /// </summary>
        private void BuildIRacingOverlayFromSdk(byte[] frame,
                                                Dictionary<string, IRacingSdkReader.VarDef> vars,
                                                double maxNm)
        {
            float[] vertArr = SdkArray(frame, vars, "VertAccel_ST");
            float[] latArr  = SdkArray(frame, vars, "LatAccel_ST");
            float[] longArr = SdkArray(frame, vars, "LongAccel_ST");

            double? swayMean  = IRacingSubMean(latArr);
            double? surgeMean = IRacingSubMean(longArr);
            double? heaveHp   = TrackGravityAndPeak(vertArr);

            // Collision: horizontal axes only, since VertAccel carries gravity.
            // Normalised exactly as FrameEnricher does, because a raw magnitude
            // clamps every hit to full amplitude.
            double impact = 0.0;
            double? p;
            p = SubPeakOf(latArr);  if (p.HasValue && p.Value > impact) impact = p.Value;
            p = SubPeakOf(longArr); if (p.HasValue && p.Value > impact) impact = p.Value;
            double? collision = null;
            if (impact > 49.0) collision = (impact - 49.0) * 0.02;

            // Surface texture from the sim's own per-tire rumble pitch.
            double rumbleSum = 0.0; int rumbleN = 0;
            string[] rk = { "TireLF_RumblePitch", "TireRF_RumblePitch", "TireLR_RumblePitch", "TireRR_RumblePitch" };
            for (int i = 0; i < rk.Length; i++)
            {
                double d;
                if (!SdkScalar(frame, vars, rk[i], out d) || d <= 0.0) continue;
                rumbleSum += d; rumbleN++;
            }
            double? surfaceRumble = null;
            if (rumbleN > 0)
            {
                double rr = (rumbleSum / rumbleN) / 100.0;
                surfaceRumble = rr > 1.0 ? 1.0 : rr;
            }

            // Kerbs, from irsdk_TrkSurf: rumble strips are 11 to 14.
            bool? onRumble = null;
            double matD;
            bool racingSurface = false;
            if (SdkScalar(frame, vars, "PlayerTrackSurfaceMaterial", out matD))
            {
                int mat = (int)Math.Round(matD);
                if (mat >= 0) onRumble = mat >= 11 && mat <= 14;
                // Asphalt (1-4), concrete (5-6) and racing dirt (7-8) are the
                // surfaces a lap is actually driven on. Paint, kerbs, grass,
                // gravel and sand are all excluded, because torque generated
                // there says nothing about how hard this car pushes in a corner.
                racingSurface = mat >= 1 && mat <= 8;
            }
            // And only while genuinely on track: the pit lane and the garage
            // would otherwise contribute their own nonsense.
            double trkLoc;
            if (racingSurface && SdkScalar(frame, vars, "PlayerTrackSurface", out trkLoc))
                racingSurface = (int)Math.Round(trkLoc) == 3;   // irsdk_OnTrack
            else if (racingSurface) racingSurface = false;

            // And only while actually DRIVING. A car sitting still on the
            // racing surface passes every location check above, but the
            // readiness clock is a promise that driving happened; it was
            // observed climbing while parked on track (owner, 2026-08-13).
            // Raised from 5 to 10 m/s (~36 km/h) after the readiness still
            // rose at a crawl (owner, 2026-08-15): below that the wheel is
            // mostly stationary scrub, which is huge, says nothing about how
            // hard the car pushes in a corner, and would inflate the peak.
            // Still well under any real cornering speed.
            double speedMs;
            if (racingSurface && SdkScalar(frame, vars, "Speed", out speedMs))
                racingSurface = speedMs > 10.0;
            else if (racingSurface) racingSurface = false;

            double peakTorque;
            if (racingSurface && SdkScalar(frame, vars, "SteeringWheelTorque", out peakTorque))
                LearnIRacingPeak(Math.Abs(peakTorque), true);

            // Steering, normalised to roughly [-1,1] by the car's own lock.
            double? steerNorm = null;
            double sr, smax;
            if (SdkScalar(frame, vars, "SteeringWheelAngle", out sr)
                && SdkScalar(frame, vars, "SteeringWheelAngleMax", out smax) && smax > 0.01)
            {
                // SteeringWheelAngleMax is lock-to-lock, so half of it is the
                // per-side limit this normalises to. Dividing by the whole
                // range (as this did until 2026-09-13) topped out at half
                // scale at the car's full lock.
                double n = sr / (smax * 0.5);
                if (n > 1.5) n = 1.5; else if (n < -1.5) n = -1.5;
                steerNorm = n;
            }

            _irOverlay = new IRacingOverlay
            {
                SteerAngleRad = steerNorm,
                Heave = SubPeakOf(vertArr),
                Sway = SubPeakOf(latArr),
                Surge = SubPeakOf(longArr),
                SurfaceRumble = surfaceRumble,
                OnRumbleStrip = onRumble,
                CollisionMag = collision,
                HeaveHp = heaveHp,
                SwayMean = swayMean,
                SurgeMean = surgeMean,
                YawRateDeg = YawRateDegFrom(SdkArray(frame, vars, "YawRate_ST")),
                SideslipDeg = SideslipDegFrom(frame, vars),
                Ticks = Stopwatch.GetTimestamp(),
            };
        }

        /// <summary>Signed sideslip in degrees from iRacing's body-axis velocity
        /// vector: atan2(lateral, longitudinal). Null below walking pace, where
        /// the angle is real but meaningless (a car being pushed sideways in the
        /// pits is at 90 degrees of "slip"), and null when the sim does not
        /// publish the channels, which leaves the old estimator in charge.</summary>
        private static double? SideslipDegFrom(byte[] frame,
                                               Dictionary<string, IRacingSdkReader.VarDef> vars)
        {
            double vx, vy;
            if (!SdkScalar(frame, vars, "VelocityX", out vx)) return null;
            if (!SdkScalar(frame, vars, "VelocityY", out vy)) return null;
            // VelocityX is forward in m/s. Below ~5 m/s the ratio is dominated by
            // parking-speed noise and the effect is gated off down there anyway.
            if (vx < 5.0) return null;
            if (double.IsNaN(vy) || double.IsInfinity(vy)) return null;
            return Math.Atan2(vy, vx) * 180.0 / Math.PI;
        }

        /// <summary>Mean of the 360 Hz yaw-rate array, converted from the
        /// radians per second iRacing publishes to the degrees per second
        /// TelemetryFrame documents.</summary>
        private static double? YawRateDegFrom(float[] arr)
        {
            double? m = IRacingSubMean(arr);
            return m.HasValue ? (double?)(m.Value * (180.0 / Math.PI)) : null;
        }

        private static double? SubPeakOf(float[] arr)
        {
            if (arr == null || arr.Length == 0) return null;
            double peak = 0.0;
            for (int i = 0; i < arr.Length; i++)
            {
                double a = arr[i] < 0 ? -arr[i] : arr[i];
                if (a > peak) peak = a;
            }
            return peak;
        }

        /// <summary>Gravity-tracked vertical bump content. Shared by both routes
        /// so the reference, the freeze band and the seeding behave identically
        /// whichever one is live.</summary>
        private double? TrackGravityAndPeak(float[] vertArr)
        {
            if (vertArr == null || vertArr.Length == 0) return null;
            double vMean = 0.0;
            for (int i = 0; i < vertArr.Length; i++) vMean += vertArr[i];
            vMean /= vertArr.Length;

            long nowG = Stopwatch.GetTimestamp();
            bool stale = _irGBaseTicks != 0
                && (nowG - _irGBaseTicks) * 1000.0 / Stopwatch.Frequency > 250.0;
            if (!_irGBaseSeeded || stale) { _irGBase = vMean; _irGBaseSeeded = true; }
            _irGBaseTicks = nowG;
            if (_irGBase < 4.0 || _irGBase > 20.0) _irGBase = 9.81;

            double dev = vMean - _irGBase;
            if (dev < 5.0 && dev > -5.0) _irGBase += (vMean - _irGBase) * 0.02;

            double best = 0.0;
            for (int i = 0; i < vertArr.Length; i++)
            {
                double hp = vertArr[i] - _irGBase;
                if (Math.Abs(hp) > Math.Abs(best)) best = hp;
            }
            return best;
        }

        private void MaybeParseIRacingSessionYaml(IRacingSdkReader r)
        {
            string yaml = r.SessionYaml;
            if (yaml == null || ReferenceEquals(yaml, _irLastSessionYaml)) return;
            _irLastSessionYaml = yaml;
            // The incident LIMIT lives in this same YAML. The SimHub-route
            // reader (ReadIncidentLimit) never runs while the direct reader
            // is live, so it has to be picked up here or the dash band shows
            // a count with no denominator.
            _irIncidentLimit = ParseIncidentLimit(yaml);
            var parsed = ParseIRacingSessionInfo(yaml);
            if (parsed == null) return;
            var prevInfo = _irCarInfo;
            _irCarInfo = parsed;
            // The YAML string is replaced on every session-info update (drivers
            // joining, timing), so the reference check above only dedupes
            // ticks. Log the car when the CAR changes, not once a second for
            // the whole session (log, 2026-09-13).
            if (prevInfo != null
                && string.Equals(prevInfo.CarPath, parsed.CarPath, StringComparison.Ordinal)
                && prevInfo.Cylinders == parsed.Cylinders
                && prevInfo.RedlineRpm == parsed.RedlineRpm
                && prevInfo.ForwardGears == parsed.ForwardGears)
                return;
            SimHub.Logging.Current.Info(
                "[TF4ALL] iRacing car: " + (parsed.ScreenName ?? "?")
                + " path=" + (parsed.CarPath ?? "?")
                + " cylinders=" + (parsed.Cylinders.HasValue ? parsed.Cylinders.Value.ToString(System.Globalization.CultureInfo.InvariantCulture) : "?")
                + " redline=" + (parsed.RedlineRpm.HasValue ? parsed.RedlineRpm.Value.ToString(System.Globalization.CultureInfo.InvariantCulture) : "?")
                + " forwardGears=" + (parsed.ForwardGears.HasValue ? parsed.ForwardGears.Value.ToString(System.Globalization.CultureInfo.InvariantCulture) : "?")
                + " [direct]");
        }

        /// <summary>The car's official name straight from the sim, when the sim
        /// tells us. iRacing publishes CarScreenName in its session info, so its
        /// cars never need the user to type a name or wait for a community
        /// consensus to form. Null for every game that does not publish one.</summary>
        public string ActiveSimCarName
        {
            get
            {
                if (!IsIRacingReshapeGame(_activeGame)) return null;
                var ci = _irCarInfo;
                return ci != null && !string.IsNullOrEmpty(ci.ScreenName) ? ci.ScreenName : null;
            }
        }
        // Change detection by REFERENCE. Strings are immutable, so a republished
        // session info is always a new object; comparing references costs
        // nothing and re-parsing a 13 KB YAML every tick would be pure waste.
        private string _irLastSessionYaml;

        /// <summary>Pull car identity and engine data out of iRacing's session
        /// YAML. Called only when the YAML object actually changes.</summary>
        private static IRacingCarInfo ParseIRacingSessionInfo(string yaml)
        {
            if (string.IsNullOrEmpty(yaml)) return null;
            var info = new IRacingCarInfo();
            int driverIdx = -1;
            // Two passes are not needed: DriverCarIdx appears in DriverInfo
            // before the per-driver Drivers list, and the car fields we want
            // from that list belong to the FIRST entry whose CarIdx matches.
            int currentCarIdx = -1;
            foreach (var line in yaml.Split('\n'))
            {
                string t = line.Trim();
                int c = t.IndexOf(':');
                if (c <= 0) continue;
                string key = t.Substring(0, c).Trim();
                string val = t.Substring(c + 1).Trim();
                if (val.Length == 0) continue;
                switch (key)
                {
                    case "DriverCarIdx":
                        int di;
                        if (int.TryParse(val, System.Globalization.NumberStyles.Integer,
                                         System.Globalization.CultureInfo.InvariantCulture, out di)) driverIdx = di;
                        break;
                    case "DriverCarEngCylinderCount":
                        info.Cylinders = ParseIRacingInt(val);
                        break;
                    case "DriverCarRedLine":
                        info.RedlineRpm = ParseIRacingInt(val);
                        break;
                    case "DriverCarGearNumForward":
                        info.ForwardGears = ParseIRacingInt(val);
                        break;
                    case "CarIdx":
                        currentCarIdx = ParseIRacingInt(val) ?? -1;
                        break;
                    case "CarPath":
                        // Only the player's own entry. A full grid repeats this
                        // key once per driver, and the last one would win.
                        if (info.CarPath == null && (currentCarIdx < 0 || currentCarIdx == driverIdx))
                            info.CarPath = val;
                        break;
                    case "CarScreenName":
                        if (info.ScreenName == null && (currentCarIdx < 0 || currentCarIdx == driverIdx))
                            info.ScreenName = val;
                        break;
                }
            }
            return info;
        }

        private static int? ParseIRacingInt(string s)
        {
            double d;
            if (double.TryParse(s, System.Globalization.NumberStyles.Float,
                                System.Globalization.CultureInfo.InvariantCulture, out d)
                && !double.IsNaN(d) && !double.IsInfinity(d) && d > 0.0 && d < 100000.0)
                return (int)Math.Round(d);
            return null;
        }

        /// <summary>Peak absolute value across a 360 Hz sub-tick array, or null.
        /// Peak rather than mean on purpose: these feed impact and texture
        /// voices, and averaging six samples is exactly what smears a kerb strike
        /// into nothing.</summary>
        /// <summary>The raw sub-tick array, or null. Callers that need signs or
        /// their own statistic use this rather than the peak helper.</summary>
        private static float[] IRacingSubArray(IDictionary<string, object> dict, string key)
        {
            if (dict == null) return null;
            object v;
            try { if (!dict.TryGetValue(key, out v)) return null; }
            catch { return null; }
            var arr = v as float[];
            if (arr == null || arr.Length == 0) return null;
            for (int i = 0; i < arr.Length; i++)
                if (float.IsNaN(arr[i]) || float.IsInfinity(arr[i])) return null;
            return arr;
        }

        /// <summary>Signed mean across a sub-tick array. The right statistic for
        /// a value whose SIGN carries meaning and whose steady level is what
        /// downstream wants, as opposed to its biggest transient.</summary>
        private static double? IRacingSubMean(float[] arr)
        {
            if (arr == null || arr.Length == 0) return null;
            double s = 0.0;
            for (int i = 0; i < arr.Length; i++) s += arr[i];
            return s / arr.Length;
        }

        private static double? IRacingSubPeak(IDictionary<string, object> dict, string key)
        {
            if (dict == null) return null;
            object v;
            try { if (!dict.TryGetValue(key, out v)) return null; }
            catch { return null; }
            var arr = v as float[];
            if (arr == null || arr.Length == 0) return null;
            double peak = 0.0;
            for (int i = 0; i < arr.Length; i++)
            {
                float s = arr[i];
                if (float.IsNaN(s) || float.IsInfinity(s)) continue;
                double a = s < 0 ? -s : s;
                if (a > peak) peak = a;
            }
            return peak;
        }
        // Reflection cache, rebuilt only when the telemetry type changes. A null
        // entry is NORMAL and means "read this one from the dictionary": only
        // 217 of iRacing's 333 channels are generated as typed properties, and
        // SteeringFFBEnabled is one of the ones that is not (proven by the IRRAW
        // probe, which resolved it via [dict]). Never treat a null here as a
        // failure, or the whole mode goes silent.
        private Type _irTelTypeCached;
        private System.Reflection.PropertyInfo _irPropTorque;
        private System.Reflection.PropertyInfo _irPropMaxNm;
        private System.Reflection.PropertyInfo _irPropFfbOn;

        /// <summary>Read one named iRacing channel: generated typed property
        /// first, then the dictionary the telemetry type inherits. Either route
        /// is legitimate; which one answers depends on whether the SDK's
        /// generator emitted that channel.</summary>
        private static bool IRacingChannel(object tel, IDictionary<string, object> dict,
                                           System.Reflection.PropertyInfo pi,
                                           string name, out object value)
        {
            value = null;
            if (pi != null)
            {
                try { value = pi.GetValue(tel, null); if (value != null) return true; }
                catch { }
            }
            if (dict != null)
            {
                try { if (dict.TryGetValue(name, out value)) return value != null; }
                catch { }
            }
            return false;
        }
        // Sub-tick samples per 60 Hz frame. iRacing solves physics at 360 Hz and
        // bundles the intermediate samples into its _ST arrays (verified on the
        // wheel 2026-08-10: six genuinely different values, not a padded scalar).
        private const int IRacingSubSamples = 6;

        // Gravity reference for VertAccel. iRacing's vertical acceleration
        // INCLUDES gravity (about 9.81 at rest), and subtracting a fixed 9.81 is
        // wrong the moment the car is on banking or over a crest, where the
        // measured specific force genuinely changes. So track it slowly instead.
        //
        // This tracker is why the first attempt at 360 Hz accelerations shipped
        // a bug: without it, raw VertAccel went straight into RoadBumps, whose
        // gate saturates near 5.0, and the effect pegged permanently.
        private double _irGBase;          // slow-moving gravity reference, m/s^2
        private bool   _irGBaseSeeded;
        private long   _irGBaseTicks;

        // Replay-mode state. Owned exclusively by the 1 kHz FFB thread, so no
        // locking: the telemetry thread only ever publishes _irFrame, and this
        // side notices a new one by its timestamp.
        //
        // Eight slots because Hermite needs a sample either side of the pair it
        // is interpolating between. A frame brings six, so the two newest of the
        // previous frame are kept to give the first of the new six something to
        // curve away from.
        private readonly float[] _irRing = new float[8];
        private bool  _irRingPrimed;
        private long  _irRingFrameTicks;

        // Learned lag cancellation for Replay mode. The replay is a CONSTANT one
        // frame behind (it renders Sub[0] at frame arrival and Sub[5] a frame
        // later), so what has to be predicted is exactly "how much will torque
        // move over one frame", and that is what this learns.
        //
        // Regressors, all measured at the moment of prediction:
        //   [0] wheel velocity, band-limited, read from the wheel's own HID
        //       position. The key input: it has NO telemetry delay, so it is
        //       fresh evidence about a stale signal. Self-aligning torque
        //       opposes wheel motion, so the sign relationship is real physics
        //       rather than a curve fit, but its STRENGTH varies by car and
        //       speed, which is precisely what a fixed gain cannot track.
        //   [1] the torque slope over the last frame, normalised. Carries
        //       momentum: a force already climbing tends to keep climbing.
        //   [2] constant, absorbing any steady bias.
        // ONE FIT PER CAR. What the predictor learns is a property of the
        // vehicle: its steering rack, caster, tyre and how hard it fights back.
        // That does not change when you pause, visit the pits or sit in the
        // garage, so a fit should follow the car rather than being thrown away
        // on every gap in telemetry and re-earned a second at a time.
        //
        // Kept in memory only, deliberately. The fit also depends on the wheel's
        // own inertia and friction and on the current force settings, so it is
        // not a fact about the car that could be shared or restored onto another
        // machine, and it re-converges in about a second anyway. Persisting it
        // would risk applying a stale fit made under different settings, for
        // almost no gain. See CarGripCalibration for the opposite case, where
        // re-learning genuinely costs seat time and so does travel.
        private readonly Dictionary<string, HorizonPredictor> _irRlsByCar =
            new Dictionary<string, HorizonPredictor>(StringComparer.Ordinal);
        private const int IRacingRlsMaxCars = 32;
        private string _irRlsCarId;
        private HorizonPredictor _irRls = NewIRacingPredictor();
        private readonly double[] _irRlsX = new double[4];
        // The correction for the frame currently being rendered, worked out once
        // when the frame lands rather than 16 times while it plays.
        private double _irPredCorrection;

        /// <summary>Regressors: [1, torque, wheel velocity, frame slope], all
        /// normalised by the car's full scale so a fit means the same thing on a
        /// 26 Nm formula car and a 12 Nm road car.
        ///
        /// Including TORQUE ITSELF is what lets it learn mean reversion, which
        /// self-aligning torque genuinely has: a loaded wheel tends back toward
        /// centre, so where the force goes next depends partly on how big it
        /// already is. A predictor built only on velocity and slope cannot
        /// express that.
        ///
        /// Seeded at [0, 1, 0, 0], which reads as "it will be what it is now".
        /// That is the correct thing to believe before any evidence, so the
        /// first predictions are sensible rather than merely harmless.</summary>
        private static HorizonPredictor NewIRacingPredictor()
        {
            return new HorizonPredictor(4, IRacingPredictHorizon, 0.995, 100.0,
                                        new double[] { 0.0, 1.0, 0.0, 0.0 });
        }

        // One frame. The replay runs exactly one frame behind by construction.
        // Worth revisiting only once the transport delay through SimHub has
        // actually been measured, rather than guessed at.
        private const int IRacingPredictHorizon = 1;
        // Below this the fit is too green to act on, and a prediction from two
        // samples is worse than none. 60 frames is about a second.
        private const long IRacingRlsMinSamples = 60;

        /// <summary>Latch iRacing's steering torque off SimHub's raw data object,
        /// once per SimHub tick. Cheap and silent for every other game.</summary>
        private void IRacingTelemetryTick(GameData data)
        {
            // Gated on the GAME, not the force mode: the telemetry overlay below
            // feeds the texture effects, which run whether or not the reshape is
            // armed. The force half still checks the mode before it publishes.
            if (!IsIRacingReshapeGame(_activeGame)) { StopIRacingDirect(); return; }

            // The MASTER mode is a different question, and the answer is yes only
            // in full: the direct reader opens the sim's shared memory and runs its
            // own thread, which is telemetry, which the other two modes do not do.
            // Stopping rather than just returning matters on a live mode switch.
            if (MasterMode != TrueforceMasterMode.Normal) { StopIRacingDirect(); return; }

            // Prefer the sim's own memory. Attempted here rather than on a timer
            // because DataUpdate is already the "iRacing is running" signal.
            MaybeStartIRacingDirect();

            // FALLBACK ONLY. While the direct reader is live it owns every latch
            // below, on its own thread at the sim's cadence. Continuing to also
            // build them here would re-impose the very hop the reader exists to
            // remove, and would race two writers onto the same volatile fields.
            if (_irSdkLive) return;
            try
            {
                var nd = data != null ? data.NewData : null;
                if (data == null || data.GameRunning != true || nd == null) return;
                object raw = nd.GetRawDataObject();
                if (raw == null) return;

                // Session info: car identity and engine truth. Re-parsed only
                // when iRacing republishes it. Strings are immutable, so a new
                // session info is always a new object and a reference compare
                // is both free and exact; the YAML is ~13 KB and parsing it 60
                // times a second would be pure waste.
                try
                {
                    const System.Reflection.BindingFlags PubI =
                        System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Instance;
                    var sdProp = raw.GetType().GetProperty("SessionData", PubI);
                    object sd = sdProp != null ? sdProp.GetValue(raw, null) : null;
                    if (sd != null)
                    {
                        // Raw is a FIELD on iRacingSDK.SessionData, not a
                        // property. Looking only for a property silently finds
                        // nothing and falls back to the SDK's parsed subset,
                        // which does not carry the engine data at all.
                        string yaml = sd as string;
                        if (yaml == null)
                        {
                            var rf = sd.GetType().GetField("Raw", PubI);
                            if (rf != null && rf.FieldType == typeof(string)) yaml = rf.GetValue(sd) as string;
                            if (yaml == null)
                            {
                                var rp = sd.GetType().GetProperty("Raw", PubI);
                                if (rp != null && rp.PropertyType == typeof(string) && rp.CanRead)
                                    yaml = rp.GetValue(sd, null) as string;
                            }
                        }
                        if (yaml != null && !ReferenceEquals(yaml, _irLastSessionYaml))
                        {
                            _irLastSessionYaml = yaml;
                            var parsed = ParseIRacingSessionInfo(yaml);
                            if (parsed != null)
                            {
                                _irCarInfo = parsed;
                                SimHub.Logging.Current.Info(
                                    "[TF4ALL] iRacing car: " + (parsed.ScreenName ?? "?")
                                    + " path=" + (parsed.CarPath ?? "?")
                                    + " cylinders=" + (parsed.Cylinders.HasValue ? parsed.Cylinders.Value.ToString(System.Globalization.CultureInfo.InvariantCulture) : "?")
                                    + " redline=" + (parsed.RedlineRpm.HasValue ? parsed.RedlineRpm.Value.ToString(System.Globalization.CultureInfo.InvariantCulture) : "?")
                                    + " forwardGears=" + (parsed.ForwardGears.HasValue ? parsed.ForwardGears.Value.ToString(System.Globalization.CultureInfo.InvariantCulture) : "?"));
                            }
                        }
                    }
                }
                catch { /* session info is a bonus, never fatal */ }

                object tel = raw;
                var telProp = raw.GetType().GetProperty("Telemetry",
                    System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Instance);
                if (telProp != null && telProp.CanRead && telProp.GetIndexParameters().Length == 0)
                {
                    object t = telProp.GetValue(raw, null);
                    if (t != null) tel = t;
                }

                var telType = tel.GetType();
                if (!ReferenceEquals(telType, _irTelTypeCached))
                {
                    const System.Reflection.BindingFlags Pub =
                        System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Instance;
                    _irPropTorque = telType.GetProperty("SteeringWheelTorque", Pub);
                    _irPropMaxNm  = telType.GetProperty("SteeringWheelMaxForceNm", Pub);
                    _irPropFfbOn  = telType.GetProperty("SteeringFFBEnabled", Pub);
                    _irTelTypeCached = telType;
                }
                var dict = tel as IDictionary<string, object>;

                // ---- Overlay first, so it survives a bad force read ----
                // Everything here is at 360 Hz where iRacing offers it, which is
                // the difference between road texture you can feel and a 60 Hz
                // staircase you cannot.
                double? heave = IRacingSubPeak(dict, "VertAccel_ST");
                double? sway  = IRacingSubPeak(dict, "LatAccel_ST");
                double? surge = IRacingSubPeak(dict, "LongAccel_ST");

                // ---- 360 Hz accelerations for the frame ----
                // Separate derivations from the unsigned peaks above, because
                // these serve a different purpose. Collision wants the biggest
                // transient in the frame; the frame fields want the sim's own
                // signed value at the documented units, since SIGN IS LOAD
                // BEARING: surge feeds the Mode B load model as
                // (1 - 0.35 * surge/9.81), so an always-positive surge makes
                // braking read as acceleration.
                var vertArr  = IRacingSubArray(dict, "VertAccel_ST");
                var latArr   = IRacingSubArray(dict, "LatAccel_ST");
                var longArr  = IRacingSubArray(dict, "LongAccel_ST");
                double? swayMean  = IRacingSubMean(latArr);
                double? surgeMean = IRacingSubMean(longArr);

                double? heaveHp = null;
                if (vertArr != null)
                {
                    double vMean = 0.0;
                    for (int i = 0; i < vertArr.Length; i++) vMean += vertArr[i];
                    vMean /= vertArr.Length;

                    long nowG = Stopwatch.GetTimestamp();
                    bool stale = _irGBaseTicks != 0
                        && (nowG - _irGBaseTicks) * 1000.0 / Stopwatch.Frequency > 250.0;
                    if (!_irGBaseSeeded || stale)
                    {
                        // Seed from the first real reading rather than from 0.
                        // Starting at zero would emit the whole ~9.8 as bump
                        // content and peg RoadBumps for seconds on every entry.
                        _irGBase = vMean;
                        _irGBaseSeeded = true;
                    }
                    _irGBaseTicks = nowG;

                    // Sanity: a plausible specific-force magnitude only. Outside
                    // this the reading is not gravity and must not become the
                    // reference.
                    if (_irGBase < 4.0 || _irGBase > 20.0) _irGBase = 9.81;

                    // FREEZE BAND. Adapt only while the frame looks like steady
                    // support. A landing, a kerb or a crash is a real signal, and
                    // letting it drag the reference would quietly cancel exactly
                    // the events we are trying to feel.
                    double dev = vMean - _irGBase;
                    if (dev < 5.0 && dev > -5.0)
                        _irGBase += (vMean - _irGBase) * 0.02;   // ~0.8 s at 60 Hz

                    // Signed peak of the bump content: the largest excursion in
                    // the frame, sign preserved. Peak rather than mean because a
                    // single sharp hit inside a frame is the whole point of
                    // reading at 360 Hz, and a mean averages it away.
                    double best = 0.0;
                    for (int i = 0; i < vertArr.Length; i++)
                    {
                        double hp = vertArr[i] - _irGBase;
                        if (Math.Abs(hp) > Math.Abs(best)) best = hp;
                    }
                    heaveHp = best;
                }

                // Surface texture. iRacing publishes its OWN per-tire road
                // texture signal, TireXX_RumblePitch, which is a far better
                // source than inferring coarseness from shock velocity: it is
                // the sim's own answer rather than our threshold guess.
                // Mean across the four corners, since a single wheel on a kerb
                // should not read as the whole car on gravel.
                double rumbleSum = 0.0; int rumbleN = 0;
                string[] rumbleKeys = { "TireLF_RumblePitch", "TireRF_RumblePitch",
                                        "TireLR_RumblePitch", "TireRR_RumblePitch" };
                for (int i = 0; i < rumbleKeys.Length; i++)
                {
                    object rv;
                    if (!IRacingChannel(tel, dict, null, rumbleKeys[i], out rv)) continue;
                    try
                    {
                        double d = Convert.ToDouble(rv, System.Globalization.CultureInfo.InvariantCulture);
                        if (double.IsNaN(d) || double.IsInfinity(d) || d <= 0.0) continue;
                        rumbleSum += d; rumbleN++;
                    }
                    catch { }
                }
                double? surfaceRumble = null;
                if (rumbleN > 0)
                {
                    // Scale is unconfirmed (it is a "pitch", so plausibly Hz).
                    // Normalizing against a nominal 100 keeps it inside [0,1]
                    // until a live capture says otherwise. Tune, do not guess
                    // twice: this is exactly where the road-bumps regression
                    // came from.
                    double r = (rumbleSum / rumbleN) / 100.0;
                    surfaceRumble = r > 1.0 ? 1.0 : r;
                }

                // Kerbs. PlayerTrackSurfaceMaterial is the sim's own surface
                // classification, and your surface tour mapped it: 1 asphalt,
                // 9 paint at the track edge, 12 rumble strip, 15 grass, 19 dirt.
                // That matches irsdk_TrkSurf, where rumble strips are 11 to 14.
                bool? onRumble = null;
                object oMat;
                if (IRacingChannel(tel, dict, null, "PlayerTrackSurfaceMaterial", out oMat))
                {
                    try
                    {
                        int mat = Convert.ToInt32(oMat, System.Globalization.CultureInfo.InvariantCulture);
                        if (mat >= 0) onRumble = mat >= 11 && mat <= 14;
                    }
                    catch { }
                }

                // Collision. FrameEnricher's accel-spike fallback needs a single
                // 60 Hz sample over its threshold, which a sub-tick peak will
                // clear when the 60 Hz average never would.
                // HORIZONTAL axes only: VertAccel carries gravity (about 9.81 at
                // rest), so including it would bias every reading upward and let
                // a hard kerb read as a crash.
                // CollisionMagnitude is a NORMALIZED scale, not raw m/s^2:
                // FrameEnricher emits (peak - 49.0) * 0.02 and CollisionEffect
                // reads it against MinThreshold 0.20 with NormalizationScale 2.0.
                // Match that exactly. Getting either half wrong is loud:
                //   - a raw magnitude (26 to 40) clamps every hit to full
                //     amplitude, so there is no dynamic range at all;
                //   - a 25 m/s^2 bar is 2.5 g, which a GT3 clears in any fast
                //     corner, so it fires a collision thud per corner entry;
                //   - and because this stamp runs BEFORE FrameEnricher, a
                //     non-null value suppresses the correct derivation.
                // The sub-tick peak is still worth having: it catches impacts a
                // 60 Hz sample averages away, which is why collision has been
                // effectively silent for every SimHub-fallback game.
                const double CollisionThresholdMps2 = 49.0;   // ~5 g, matches FrameEnricher
                const double CollisionNormalizePerMps2 = 0.02;
                double? collision = null;
                double impact = 0.0;
                if (sway.HasValue && sway.Value > impact) impact = sway.Value;
                if (surge.HasValue && surge.Value > impact) impact = surge.Value;
                if (impact > CollisionThresholdMps2)
                    collision = (impact - CollisionThresholdMps2) * CollisionNormalizePerMps2;

                // TelemetryFrame.SteeringAngle is NORMALIZED to roughly [-1, 1],
                // not an angle. iRacing publishes radians, so it has to be
                // divided by the car's own lock. Stamping raw radians would hand
                // the stationary spring +/-7.85 on a 900 degree wheel.
                object oSteer, oSteerMax;
                double? steerNorm = null;
                double slAngleRaw = 0.0, slMaxRaw = 0.0;   // radians, for the soft lock below
                if (IRacingChannel(tel, dict, null, "SteeringWheelAngle", out oSteer)
                    && IRacingChannel(tel, dict, null, "SteeringWheelAngleMax", out oSteerMax))
                {
                    try
                    {
                        double sr  = Convert.ToDouble(oSteer, System.Globalization.CultureInfo.InvariantCulture);
                        double max = Convert.ToDouble(oSteerMax, System.Globalization.CultureInfo.InvariantCulture);
                        if (!double.IsNaN(sr) && !double.IsInfinity(sr) && max > 0.01)
                        {
                            // SteeringWheelAngleMax is lock-to-lock, so half of
                            // it is the per-side limit this normalises to.
                            double n = sr / (max * 0.5);
                            if (n > 1.5) n = 1.5; else if (n < -1.5) n = -1.5;
                            steerNorm = n;
                            slAngleRaw = sr;
                            slMaxRaw = max;
                        }
                    }
                    catch { }
                }

                _irOverlay = new IRacingOverlay
                {
                    SteerAngleRad = steerNorm,
                    Heave = heave,
                    Sway = sway,
                    Surge = surge,
                    SurfaceRumble = surfaceRumble,
                    OnRumbleStrip = onRumble,
                    CollisionMag = collision,
                    HeaveHp = heaveHp,
                    SwayMean = swayMean,
                    SurgeMean = surgeMean,
                    YawRateDeg = YawRateDegFrom(IRacingSubArray(dict, "YawRate_ST")),
                    Ticks = Stopwatch.GetTimestamp(),
                };

                // Incident points ride the same raw sample. Read BEFORE the
                // force gate below: the count is dash data and has nothing to
                // do with whether we are authoring force, so it has to keep
                // working for someone running iRacing's own FFB.
                IRacingIncidentsTick(raw, tel, dict);

                // ---- Force half. Only published while the reshape is armed. ----
                if (_forceMode != ForceModeIRacing) return;

                object oTorque, oMaxNm, oFfbOn;
                if (!IRacingChannel(tel, dict, _irPropTorque, "SteeringWheelTorque", out oTorque)) return;
                if (!IRacingChannel(tel, dict, _irPropMaxNm, "SteeringWheelMaxForceNm", out oMaxNm)) return;

                float latest, maxNm;
                try
                {
                    latest = Convert.ToSingle(oTorque, System.Globalization.CultureInfo.InvariantCulture);
                    maxNm  = Convert.ToSingle(oMaxNm, System.Globalization.CultureInfo.InvariantCulture);
                }
                catch { return; }
                // A zero or negative full-scale would divide the force to
                // nonsense. Bail rather than guess a wheel rating.
                if (!(maxNm > 0.01f) || float.IsNaN(latest) || float.IsInfinity(latest)) return;

                // Not a typed property on the shipped SDK, so this MUST go
                // through the dictionary fallback. Defaulting it to false on a
                // failed read would silently disable conflict detection.
                // Same full-scale watch on the SimHub fallback route, so the
                // question gets answered whichever path happens to be live.
                object oPeak; double peakNmS = -1.0;
                if (IRacingChannel(tel, dict, null, "SteeringWheelPeakForceNm", out oPeak))
                {
                    try { peakNmS = Convert.ToDouble(oPeak, System.Globalization.CultureInfo.InvariantCulture); }
                    catch { peakNmS = -1.0; }
                }
                MaybeLogIRacingFullScale(maxNm, peakNmS);

                bool ffbOn = false;
                if (IRacingChannel(tel, dict, _irPropFfbOn, "SteeringFFBEnabled", out oFfbOn))
                {
                    try { ffbOn = Convert.ToBoolean(oFfbOn); }
                    catch { ffbOn = false; }
                }

                // ONLY while the driver is actually in the car, for the same
                // reason as the direct route: out of the car iRacing keeps
                // publishing a torque for the parked car that follows the
                // wheel's displacement, and reproducing it is a runaway to
                // full lock. Failed read counts as out-of-car: no force is
                // safer than a runaway when the channel is unreadable.
                bool inCar = false;
                object oOnTrack;
                if (IRacingChannel(tel, dict, null, "IsOnTrack", out oOnTrack))
                {
                    try { inCar = Convert.ToBoolean(oOnTrack); }
                    catch { inCar = false; }
                }
                if (!inCar)
                {
                    _irFrame = null;
                    return;
                }

                // The 360 Hz array is dictionary-only: it is not among the
                // generated typed properties. Absent is survivable, we just run
                // on the 60 Hz scalar instead.
                float[] sub = null;
                if (dict != null)
                {
                    object stVal;
                    if (dict.TryGetValue("SteeringWheelTorque_ST", out stVal))
                    {
                        var stArr = stVal as float[];
                        if (stArr != null && stArr.Length >= IRacingSubSamples)
                        {
                            sub = new float[IRacingSubSamples];
                            bool ok = true;
                            for (int i = 0; i < IRacingSubSamples; i++)
                            {
                                float v = stArr[i];
                                if (float.IsNaN(v) || float.IsInfinity(v)) { ok = false; break; }
                                sub[i] = v;
                            }
                            if (!ok) sub = null;
                        }
                    }
                }

                long nowT = Stopwatch.GetTimestamp();
                if (sub != null && dict != null && (Settings?.IRacingKerbSofteningEnabled ?? false))
                {
                    bool onStrip = false;
                    object oMatK;
                    if (IRacingChannel(tel, dict, null, "PlayerTrackSurfaceMaterial", out oMatK))
                    {
                        try
                        {
                            int mat = Convert.ToInt32(oMatK, System.Globalization.CultureInfo.InvariantCulture);
                            onStrip = mat >= 11 && mat <= 14;
                        }
                        catch { }
                    }
                    string[] frontPitch = { "TireLF_RumblePitch", "TireRF_RumblePitch" };
                    for (int i = 0; i < frontPitch.Length && !onStrip; i++)
                    {
                        object pv;
                        if (!IRacingChannel(tel, dict, null, frontPitch[i], out pv)) continue;
                        try
                        {
                            double d = Convert.ToDouble(pv, System.Globalization.CultureInfo.InvariantCulture);
                            if (!double.IsNaN(d) && !double.IsInfinity(d) && d > 0.0) onStrip = true;
                        }
                        catch { }
                    }
                    SoftenIRacingKerbStrikes(sub, ref latest,
                        IRacingSubArray(dict, "LFshockVel_ST"), IRacingSubArray(dict, "RFshockVel_ST"),
                        IRacingSubArray(dict, "LRshockVel_ST"), IRacingSubArray(dict, "RRshockVel_ST"),
                        nowT, (float)maxNm, onStrip);
                }
                else _kerbPrevTicks = 0;

                var prev = _irFrame;
                var fr = new IRacingTorqueFrame
                {
                    Sub = sub,
                    Latest = latest,
                    MaxNm = maxNm,
                    GameFfbOn = ffbOn,
                    Ticks = nowT,
                };
                // Steering for the soft lock, read with the overlay above and
                // stamped before the frame is published.
                if (slMaxRaw > 0.01) IRacingSteerFields(slAngleRaw, slMaxRaw, fr.Ticks, fr);
                _irFrame = fr;

                // One line on the first good frame, then only when the sim's own
                // FFB flips. Enough to tell "never latched" from "latched but
                // suppressed" without tailing a log at 60 Hz.
                if (prev == null || prev.GameFfbOn != ffbOn)
                {
                    var dsrc = _telemetrySource;
                    SimHub.Logging.Current.Info(
                        "[TF4ALL] iRacing FFB: torque=" + latest.ToString("F2", System.Globalization.CultureInfo.InvariantCulture)
                        + "Nm maxForce=" + maxNm.ToString("F2", System.Globalization.CultureInfo.InvariantCulture)
                        + "Nm subTick=" + (sub != null ? "yes(360Hz)" : "no(60Hz only)")
                        + " simFfbOn=" + ffbOn
                        + " sessionActive=" + (dsrc != null ? dsrc.IsSessionActive.ToString() : "n/a")
                        + " measuredHz=" + (dsrc != null ? dsrc.MeasuredHz.ToString("F0", System.Globalization.CultureInfo.InvariantCulture) : "n/a")
                        + (ffbOn ? " -> SUPPRESSED, turn iRacing's own force feedback off" : " -> authoring force"));
                }
            }
            catch
            {
                // Never throw into SimHub's data pump. A failed read just leaves
                // the previous frame to go stale, which ramps the force down.
            }
        }

        /// <summary>Stamp iRacing's richer channels onto a frame SimHub's generic
        /// reader built. Only fills what the source left NULL, so it can never
        /// fight a value SimHub did provide. No-op for every other game.</summary>
        private void ApplyIRacingOverlay(ref TelemetryFrame frame)
        {
            var o = _irOverlay;
            if (o == null) return;
            // Same staleness rule as the force path: a frozen overlay would keep
            // a stale kerb or impact alive after the sim stopped publishing.
            if ((Stopwatch.GetTimestamp() - o.Ticks) * 1000.0 / Stopwatch.Frequency > 250.0) return;

            if (!frame.SteeringAngle.HasValue && o.SteerAngleRad.HasValue)
                frame.SteeringAngle = o.SteerAngleRad;

            // Car truth from the session info. iRacing publishes all of this, so
            // for this game none of it needs a car database, a community
            // consensus or a user entry.
            var ci = _irCarInfo;
            if (ci != null)
            {
                // Forward gear count. Lets the redline buzz stay quiet in top
                // gear, where it is a shift cue with nothing to shift into.
                if (!frame.ForwardGearCount.HasValue && ci.ForwardGears.HasValue)
                    frame.ForwardGearCount = ci.ForwardGears;
                // The sim's own redline beats our 0.85 x MaxRpm guess outright.
                if (frame.RedlineRpm <= 0 && ci.RedlineRpm.HasValue)
                    frame.RedlineRpm = ci.RedlineRpm.Value;
                if (!frame.NumCylinders.HasValue && ci.Cylinders.HasValue && ci.Cylinders.Value > 0)
                    frame.NumCylinders = ci.Cylinders.Value;
            }

            // 360 Hz accelerations, now that both hazards that broke the first
            // attempt are handled rather than assumed away:
            //   1. UNITS are settled. Measured on the wheel, SimHub's sway and
            //      the SDK's LatAccel are identical to five figures, so both are
            //      m/s^2 and no conversion belongs here. The earlier worry that
            //      SimHub reported G was simply wrong.
            //   2. GRAVITY is removed by the tracked reference, not a constant.
            //      SimHub already delivers heave gravity-free (its value equals
            //      SDK VertAccel minus 9.81), so these are interchangeable and
            //      nothing downstream needs retuning.
            // What this buys: a bump that lives entirely inside one 60 Hz frame
            // now reaches the wheel instead of being averaged out of existence.
            if (o.HeaveHp.HasValue)   frame.AccelerationHeave = o.HeaveHp;
            if (o.SwayMean.HasValue)  frame.AccelerationSway  = o.SwayMean;
            if (o.SurgeMean.HasValue) frame.AccelerationSurge = o.SurgeMean;
            if (o.YawRateDeg.HasValue) frame.YawRateDegPerSec = o.YawRateDeg;
            if (o.SideslipDeg.HasValue) frame.SideslipDeg = o.SideslipDeg;

            if (!frame.SurfaceRumble.HasValue && o.SurfaceRumble.HasValue)
                frame.SurfaceRumble = o.SurfaceRumble;

            // Revives KerbThumpEffect: EventDeriver only raises RumbleStripStart
            // when this has a value, and SimHub's reader never sets it.
            if (!frame.OnRumbleStrip.HasValue && o.OnRumbleStrip.HasValue)
                frame.OnRumbleStrip = o.OnRumbleStrip;

            if (!frame.CollisionMagnitude.HasValue && o.CollisionMag.HasValue)
                frame.CollisionMagnitude = o.CollisionMag;
        }

        /// <summary>Compose the iRacing reshape force. Returns null when there is
        /// nothing to author (no frame yet, telemetry stale, or the sim's own FFB
        /// is on), which leaves the wheel free rather than holding a stale pull.
        /// </summary>
        private short? ComputeIRacingForce()
        {
            var f = _irFrame;
            if (f == null)
            {
                // Out of the car, or the reader not live: nothing is authored,
                // so the next engagement fades in the way arming does. Only the
                // aged-out exit below used to reset the ramp; a pause that
                // dropped the frame instead came back as a step to the
                // corner's torque (rig, 2026-09-13).
                _irRamp = 0f; _irPrevTicks = 0;
                _irLeadFrameTicks = 0;
                _irRingPrimed = false;
                return null;
            }

            long now = Stopwatch.GetTimestamp();
            double ageMs = (now - f.Ticks) * 1000.0 / Stopwatch.Frequency;

            // The sim is driving the wheel itself. Two writers on one wheel is
            // the worst first impression this feature can make, so refuse rather
            // than fight. Authoritative, unlike the tap-based heuristic the Forza
            // watchdog has to use.
            if (f.GameFfbOn)
            {
                _irRamp = 0f; _irPrevTicks = 0;
                _irRingPrimed = false;
                _irLeadFrameTicks = 0;   // nothing to be continuous with
                return null;
            }

            // Follow the car. Read once here rather than reacting to a car-change
            // event, so this stays entirely on the FFB thread: a string reference
            // read is atomic, and a swap arriving a millisecond late is harmless.
            string irCar = _activeCarId;
            if (!string.Equals(irCar, _irRlsCarId, StringComparison.Ordinal))
            {
                _irRlsCarId = irCar;
                _irRingPrimed = false;
                HorizonPredictor forCar;
                if (string.IsNullOrEmpty(irCar))
                {
                    forCar = NewIRacingPredictor();
                }
                else if (!_irRlsByCar.TryGetValue(irCar, out forCar) || forCar == null)
                {
                    // Bounded so a long multi-class session cannot grow this
                    // without limit. Clearing wholesale rather than evicting one
                    // entry is fine: it costs a second of re-learning, once.
                    if (_irRlsByCar.Count >= IRacingRlsMaxCars) _irRlsByCar.Clear();
                    forCar = NewIRacingPredictor();
                    _irRlsByCar[irCar] = forCar;
                }
                _irRls = forCar;
            }

            // Telemetry stopped (pause, menu, replay, sim closed). Decay instead
            // of holding: the wheel latches the last cur once the stream stops,
            // so a held value is a held pull on a parked car.
            if (ageMs > 250.0)
            {
                _irRamp = 0f; _irPrevTicks = 0;
                _irLeadFrameTicks = 0;   // the gap breaks continuity; start clean
                // Drop the TIMING state, which is now meaningless, but keep the
                // FIT: a gap means paused, in the pits or in the garage, and the
                // car's steering physics did not change while you sat there.
                // Only a car change invalidates the fit, and that is handled by
                // swapping fits rather than by wiping one.
                _irRingPrimed = false;
                return null;
            }

            // Play the 360 Hz sub-tick samples out across the frame they cover,
            // linearly interpolated onto whatever instant this 1 kHz pass lands
            // on. That is what turns a 60 Hz staircase into something the wheel
            // can render smoothly. With no array, or with the user on the 60 Hz
            // feed, we simply hold the per-frame scalar.
            // LATENCY IS THE ENEMY HERE, not resolution. Unlike Mode B, this
            // path is a CLOSED LOOP through the sim: wheel position is an input
            // to iRacing, iRacing solves steering torque from it, we render that
            // torque, the wheel moves, and round it goes. Add enough phase lag
            // to a loop with this much gain and it does not just feel soft, it
            // oscillates and the swings grow.
            //
            // The sub-tick array is the six physics steps of the frame that just
            // happened, so [5] is the CURRENT state and equals the scalar
            // exactly (verified on the wheel). Playing [0] through [5] out over
            // the NEXT frame therefore starts a full frame behind and never
            // catches up: about 16.7 ms of pure delay bought nothing but
            // smoothing. Default is now the newest value, zero added lag.
            //
            // The interpolation is kept behind the toggle for anyone who wants
            // the smoother feel and can afford the delay, but it is off by
            // default and labelled as what it costs.
            var irCfg = Settings;
            bool use360 = irCfg != null && irCfg.IRacingUse360Hz;
            bool replayMode = irCfg != null && irCfg.IRacingForceMode == 1;
            // Mode 2, TREND ONLY: the projection without the texture. The six
            // samples are still read, but only to fit the line; the residual
            // that carries kerbs and surface detail is dropped. That is the
            // cell the other three left empty (owner, 2026-08-16): the plain
            // force is clean but goes stale between frames, and someone who
            // finds the texture busy had no way to have clean AND current.
            // Rides the Lead branch, which already computes both halves.
            bool trendOnly = irCfg != null && irCfg.IRacingForceMode == 2;
            float torque;
            if (f.Sub != null && use360 && replayMode)
            {
                // ---- REPLAY ----
                // Play the six sub-samples out in order, through a Hermite
                // curve, at the rate the sim produced them. Every sample is
                // rendered at its correct relative moment and each event stays
                // WHOLE, which is the advantage over splitting the signal: a
                // kerb strike arrives as one strike rather than as a slow part
                // now and a sharp part later.
                //
                // The cost is that a replay is behind by construction. That is
                // paid for below with a predictor driven by the WHEEL's own
                // velocity, which is read locally from HID and carries no
                // telemetry delay at all. Predicting a laggy signal from a
                // fresh one beats extrapolating it from itself.
                const double FrameMs = 1000.0 / 60.0;

                if (f.Ticks != _irRingFrameTicks)
                {
                    // New frame: the two newest samples age into the head of the
                    // ring so the first of the incoming six has curve context.
                    if (_irRingPrimed)
                    {
                        _irRing[0] = _irRing[6];
                        _irRing[1] = _irRing[7];
                    }
                    else
                    {
                        _irRing[0] = f.Sub[0];
                        _irRing[1] = f.Sub[0];
                        _irRingPrimed = true;
                    }
                    for (int i = 0; i < IRacingSubSamples; i++) _irRing[2 + i] = f.Sub[i];
                    _irRingFrameTicks = f.Ticks;

                    // ---- Learn and predict, once per frame ----
                    // Step does both halves: the entry queued a horizon ago is
                    // now checkable against the value that just arrived, and the
                    // current inputs go in to be judged later. Queuing is the
                    // whole point, because at the moment a prediction is made the
                    // truth it should be judged against has not happened yet.
                    double yNorm = f.Sub[IRacingSubSamples - 1] / f.MaxNm;
                    _irRlsX[0] = 1.0;
                    _irRlsX[1] = yNorm;
                    _irRlsX[2] = _mbDamperVelLp;
                    _irRlsX[3] = (f.Sub[IRacingSubSamples - 1] - f.Sub[0]) / f.MaxNm;

                    double predNorm = _irRls.Step(_irRlsX, yNorm);
                    // The correction is how far ahead of NOW the prediction sits,
                    // not the prediction itself: the replay already renders the
                    // measured values, and this only supplies what they are
                    // missing by being a frame old.
                    _irPredCorrection = (_irRls.Samples >= IRacingRlsMinSamples)
                        ? (predNorm - yNorm) : 0.0;
                }

                // Advance through the new samples at the sim's own 360 Hz.
                double pos = 2.0 + (ageMs / FrameMs) * (IRacingSubSamples - 1);
                if (pos < 1.0) pos = 1.0;
                else if (pos > 6.0) pos = 6.0;   // leave room for the +1 neighbour
                int k = (int)pos;
                if (k < 1) k = 1; else if (k > 6) k = 6;
                double t = pos - k;

                double hm0 = _irRing[k - 1], hm1 = _irRing[k], hm2 = _irRing[k + 1];
                double hm3 = (k + 2 <= 7) ? _irRing[k + 2] : _irRing[k + 1];
                // Catmull-Rom form of Hermite: tangents from the neighbours, so
                // the curve passes through every sample instead of smoothing it
                // away, which is the whole point of rendering the detail.
                double t2 = t * t, t3 = t2 * t;
                double replayed =
                    0.5 * ((2.0 * hm1)
                         + (-hm0 + hm2) * t
                         + (2.0 * hm0 - 5.0 * hm1 + 4.0 * hm2 - hm3) * t2
                         + (-hm0 + 3.0 * hm1 - 3.0 * hm2 + hm3) * t3);

                // LEARNED lag cancellation. The replay is a constant one frame
                // behind, so the correction is one frame's worth of predicted
                // movement: exactly what the fit above was trained to produce.
                //
                // Defaults to 1.0: use what the predictor worked out. It stays
                // adjustable as an escape hatch for anyone who dislikes the feel
                // of prediction, NOT as a number to hunt for. Needing to change
                // it per car would mean the learning had failed.
                double predBlend = irCfg != null ? irCfg.IRacingPredictGain : 0.0;
                if (predBlend > 0.0 && _irPredCorrection != 0.0)
                {
                    double lead = _irPredCorrection * predBlend * f.MaxNm;
                    // Final clamp. Even a fit that has gone wrong cannot put a
                    // large force on the wheel, which is the third of the three
                    // defences described on RlsPredictor.
                    double cap = f.MaxNm * 0.15;
                    if (lead > cap) lead = cap; else if (lead < -cap) lead = -cap;
                    replayed += lead;
                }

                torque = (float)replayed;
            }
            else if (f.Sub != null && use360)
            {
                // Use the sub-tick data as SLOPE, not as a replay.
                //
                // The six samples describe the frame that just ended, so [5] is
                // "now" and [0] is 16.7 ms ago. Playing them forward from [0] is
                // the one use of them that guarantees a frame of lag, which in a
                // loop that closes through the sim is what makes the wheel
                // oscillate. But the same six samples also say which way torque
                // is MOVING, and extrapolating along that is phase LEAD, which
                // is what settles a laggy loop rather than upsetting it.
                //
                // So: start at the newest value (zero lag) and project forward
                // by however long it has been since the frame landed.
                const double FrameMs = 1000.0 / 60.0;

                // Slope by LEAST SQUARES over all six samples, not a difference
                // between two of them. A two-point difference is the noisiest
                // slope estimate available, and this term is multiplied by time
                // and added to the force, so its noise lands straight on the
                // wheel. The regression uses every sample and is far steadier
                // for the same responsiveness.
                //
                // Samples are evenly spaced across the frame, so with indices
                // 0..5 the mean index is 2.5 and sum((i-2.5)^2) is 17.5, both
                // constants. That reduces the fit to one pass and no division
                // beyond the fixed denominator.
                double sxy = 0.0;
                for (int i = 0; i < IRacingSubSamples; i++)
                    sxy += (i - 2.5) * f.Sub[i];
                double slopePerIndex = sxy / 17.5;
                double stepMs = FrameMs / (IRacingSubSamples - 1);
                double slopePerMs = slopePerIndex / stepMs;

                // Never project further than one frame. Past that the next frame
                // is overdue and extrapolation is guessing, so it holds instead.
                double leadMs = ageMs;
                if (leadMs < 0.0) leadMs = 0.0;
                else if (leadMs > FrameMs) leadMs = FrameMs;

                double projected = f.Sub[IRacingSubSamples - 1] + slopePerMs * leadMs;

                // Clamp how far the projection may stray from the measured
                // value. Extrapolation amplifies noise, and an unbounded lead
                // term is its own instability; a bounded one is a stabiliser.
                // The bound is a fraction of the car's full scale, so it means
                // the same thing on a 26 Nm formula car and a 12 Nm road car.
                double maxDev = f.MaxNm * 0.15;
                double baseNm = f.Sub[IRacingSubSamples - 1];
                if (projected > baseNm + maxDev) projected = baseNm + maxDev;
                else if (projected < baseNm - maxDev) projected = baseNm - maxDev;

                // RESIDUAL INJECTION: the actual mid-frame shape, not just its
                // slope. Everything above uses the six samples only through one
                // number, so a spike at sample 2 that is gone by sample 5 gets
                // averaged out of existence and never reaches the wheel.
                //
                // The fix falls out of the fit already computed. Subtract the
                // fitted line from each sample and what is left is the detail
                // the line could not describe. Those residuals are ZERO-MEAN by
                // construction, so replaying them carries no DC: it cannot
                // shift the force, cannot close the loop, and therefore cannot
                // drive the oscillation. Only the line had to be current.
                //
                // So the line is rendered with LEAD (current, loop-critical)
                // and the residuals are replayed with a frame of DELAY (texture,
                // phase-insensitive). A kerb 16 ms late is imperceptible; a
                // centering force 16 ms late is what made the wheel walk.
                double mean = 0.0;
                for (int i = 0; i < IRacingSubSamples; i++) mean += f.Sub[i];
                mean /= IRacingSubSamples;

                double playPos = (leadMs / FrameMs) * (IRacingSubSamples - 1);
                if (playPos < 0.0) playPos = 0.0;
                else if (playPos > IRacingSubSamples - 1) playPos = IRacingSubSamples - 1;
                int pi = (int)playPos;
                if (pi > IRacingSubSamples - 2) pi = IRacingSubSamples - 2;
                double pf = playPos - pi;

                double r0 = f.Sub[pi]     - (mean + slopePerIndex * (pi     - 2.5));
                double r1 = f.Sub[pi + 1] - (mean + slopePerIndex * (pi + 1 - 2.5));
                double residual = r0 + (r1 - r0) * pf;

                // Bounded like the lead, for the same reason: a bad frame must
                // not be able to throw the wheel.
                if (residual > maxDev) residual = maxDev;
                else if (residual < -maxDev) residual = -maxDev;

                double raw = projected + (trendOnly ? 0.0 : residual);

                // CONTINUITY AT THE FRAME JOIN. Everything above is rebuilt
                // from scratch each frame: new samples, new fitted slope, lead
                // measured from the new arrival. Nothing makes the new curve
                // start where the old one left off, so at every boundary the
                // output STEPS by whatever the previous frame's projection got
                // wrong. Sixty of those a second is felt as tiny jolts rather
                // than as force arriving, worst under braking where the sim's
                // torque carries the fastest content and the projection is
                // therefore least accurate (owner rig, 2026-08-15: "it jerks
                // between the small movements instead of arriving smoothly",
                // and Replay, which joins its samples through a Hermite curve,
                // feels tamed by comparison).
                //
                // So carry the error across the join instead of stepping over
                // it: capture the gap at the boundary and let it decay to zero
                // over the frame on a Hermite blend that is flat at both ends
                // (h(0)=1, h(1)=0, h'=0 at both). The wheel then leaves each
                // frame exactly where it was and arrives at the new projection
                // smoothly. It costs nothing in latency at the join, which is
                // Lead's whole reason to exist: the FIRST tick of a frame still
                // renders the previous trajectory, and the new one has taken
                // over completely by the time the next frame lands.
                //
                // Bounded by the same maxDev as the projection: a genuinely
                // large frame-to-frame change is real force and must not be
                // smeared into a slew, only the small errors are blended.
                if (f.Ticks != _irLeadFrameTicks)
                {
                    bool firstAfterGap = _irLeadFrameTicks == 0;
                    _irLeadFrameTicks = f.Ticks;
                    double gap = firstAfterGap ? 0.0 : _irLeadPrevOut - raw;
                    if (gap > maxDev) gap = maxDev;
                    else if (gap < -maxDev) gap = -maxDev;
                    _irLeadOffset = gap;
                }
                double hs = leadMs / FrameMs;
                if (hs < 0.0) hs = 0.0; else if (hs > 1.0) hs = 1.0;
                double hBlend = 1.0 - hs * hs * (3.0 - 2.0 * hs);
                raw += _irLeadOffset * hBlend;

                _irLeadPrevOut = raw;
                torque = (float)raw;
            }
            else
            {
                // Newest value, zero added lag. f.Latest is the per-frame scalar,
                // which the wheel confirmed equals Sub[5] exactly.
                torque = f.Latest;
            }

            // Full scale: the user's own figure when they gave one, otherwise the
            // sim's. iRacing's max-force setting IS this number and the driver
            // already tuned it, so inheriting it beats asking twice. But it lives
            // in a menu belonging to a force-feedback system they have just been
            // told to switch off, which makes it an invisible dependency, so the
            // override exists for anyone who would rather say it here.
            // The divisor, and therefore everything about how cars relate to each
            // other. Order: this car's own value if we keep them per car, then
            // the shared value, then iRacing's own figure as the fallback so a
            // driver who has set nothing still gets something sane.
            double fullScaleNm = f.MaxNm;
            // R3E auto-strength: shrink the synthetic full scale toward this
            // car's learned normalized peak (fed on the reader thread) so
            // RaceRoom's weak percentage lands near target. The low-speed ramp
            // below fades the boost out while parked.
            if (f.FixedScale && (Settings?.R3EAutoStrength ?? true))
            {
                float frac = _r3eFullScaleFrac;
                if (frac > 0.01f) fullScaleNm = f.MaxNm * frac;
            }
            var irScale = Settings;
            // FixedScale frames (the R3E route) arrive pre-normalized with a
            // synthetic full scale; the overrides below are iRacing wheel
            // ratings in Nm and would divide them to nonsense.
            if (irScale != null && !f.FixedScale)
            {
                float perCar;
                if (MaxForcePerCarHere
                    && irScale.IRacingMaxForceByCar != null
                    && !string.IsNullOrEmpty(_activeCarId)
                    && irScale.IRacingMaxForceByCar.TryGetValue(_activeCarId, out perCar)
                    && perCar > 0.5f)
                {
                    fullScaleNm = perCar;
                }
                else if (!IsLmuGame(_activeGame) && irScale.IRacingMaxForceNmOverride > 0.5f)
                {
                    fullScaleNm = irScale.IRacingMaxForceNmOverride;
                }
            }
            if (!(fullScaleNm > 0.01)) return null;

            // LOW-SPEED AMPLIFICATION LIMIT. This path is a closed loop: the
            // sim solves steering torque FROM wheel position, so 1/fullScaleNm
            // is the loop's gain, not just a volume knob. A per-car number well
            // under the sim's own full scale is exactly what Auto produces on a
            // light car, and it multiplies everything the loop carries. Parked
            // there is no tyre damping to absorb any of it, so engine shake
            // alone can sustain a limit cycle: the owner's rig reproduced that
            // at idle, and turning per-car max force off (a bigger divisor, so
            // less gain) calmed BOTH detail modes (2026-08-15).
            //
            // So amplify no further than the sim's own scale while stopped, and
            // ramp to the driver's chosen number by the time the tyres are
            // doing the damping themselves. This costs nothing where it counts:
            // a parked wheel is the one place full-resolution force detail buys
            // nothing, and the ramp is complete well below any real cornering
            // speed. Only ever REDUCES gain: a number above the sim's own scale
            // is attenuation and cannot ring, so it is left alone.
            double simFullNm = f.MaxNm;
            if (simFullNm > 0.01 && fullScaleNm < simFullNm)
            {
                const double rampLoKmh = 5.0, rampHiKmh = 25.0;
                double gr = (_lastSpeedKmh - rampLoKmh) / (rampHiKmh - rampLoKmh);
                if (gr < 0.0) gr = 0.0; else if (gr > 1.0) gr = 1.0;
                fullScaleNm = simFullNm + (fullScaleNm - simFullNm) * gr;
            }

            double f01 = torque / fullScaleNm;

            // Strength. Its OWN field, not ModeBSatGain: that one is a
            // peak-torque fraction for the synthesis model and defaults to 0.50,
            // which would deliver half the torque iRacing asked for before
            // FfbScale even applies. Default here is 1.0, meaning "exactly what
            // the sim asked for".
            double gain = irCfg != null ? irCfg.IRacingForceGain : 1.0;
            if (gain < 0.0) gain = 0.0; else if (gain > 3.0) gain = 3.0;
            f01 *= gain;

            if (f01 > 1.0) f01 = 1.0; else if (f01 < -1.0) f01 = -1.0;

            // Engage ramp, same contract as the synthesis path: fade in over
            // ~300 ms so arming never steps the wheel to full torque.
            double dtMs = _irPrevTicks == 0 ? 1.0 : (now - _irPrevTicks) * 1000.0 / Stopwatch.Frequency;
            if (dtMs < 0.05) dtMs = 0.05; else if (dtMs > 50.0) dtMs = 50.0;
            _irPrevTicks = now;
            if (_irRamp < 1f)
            {
                if (_irRamp <= 0f) { _irResumeStampTicks = now; _irResumeTrace = null; }
                _irRamp += (float)(dtMs / 300.0);
                if (_irRamp > 1f) _irRamp = 1f;
            }

            // Author the FINAL sign here rather than borrowing the device's
            // tapped-path inversion. Same result on the wheel, but the sign now
            // lives in the path that owns it: a user cannot break iRacing by
            // flipping a toggle that exists to reconcile a capture we do not do,
            // and nobody has to know that this number gets negated later.
            double v = -f01 * _irRamp * 32767.0;
            if (v > short.MaxValue) v = short.MaxValue;
            else if (v < short.MinValue) v = short.MinValue;

            // Once per fade-in, a short trace of the first half second: the
            // authored force, the sim's own torque before the ramp, and where
            // the wheel is, at a few instants. A kick at resume was reported on
            // the rig (2026-09-13, "tries to center, then suddenly stops") with
            // no way to tell whose it was; this line says whether the torque
            // this path plays is the shape that was felt.
            if (_irResumeStampTicks != 0)
            {
                double sinceMs = (now - _irResumeStampTicks) * 1000.0 / Stopwatch.Frequency;
                if (_irResumeTrace == null) _irResumeTrace = new System.Text.StringBuilder(160);
                int slot = sinceMs < 25 ? 0 : sinceMs < 50 ? 1 : sinceMs < 100 ? 2 : sinceMs < 200 ? 3
                         : sinceMs < 300 ? 4 : sinceMs < 500 ? 5 : 6;
                if (slot > _irResumeSlot)
                {
                    _irResumeSlot = slot;
                    var ci = System.Globalization.CultureInfo.InvariantCulture;
                    _irResumeTrace.Append(((int)sinceMs).ToString(ci)).Append("ms:")
                        .Append(((int)(v * 100.0 / 32767.0)).ToString(ci)).Append("%/")
                        .Append(((int)(f01 * 100.0)).ToString(ci)).Append("%/")
                        .Append(_lastSteerNorm.ToString("0.00", ci)).Append(' ');
                }
                if (sinceMs >= 500.0)
                {
                    _irResumeStampTicks = 0;
                    _irResumeSlot = -1;
                    SimHub.Logging.Current.Info(
                        "[TF4ALL] iRacing force back on (ms: played% / sim torque% / wheel): " + _irResumeTrace);
                    _irResumeTrace = null;
                }
            }
            return (short)v;
        }

        private short? MaybeReshapeFfb(short? target)
        {
            bool springMode = _forceMode == ForceModeSpring;
            bool reshapeMode = _forceMode == ForceModeIRacing;
            bool modeB = _forceMode != ForceModeOff;
            if (springMode)
            {
                // Spring mode: the force IS the game's own spring, evaluated
                // at the wheel's physical position. Always a value while
                // armed (0 with no playing spring), so the damper below stays
                // active to catch residual wheel motion.
                target = ComputeSpringModeForce();
            }
            else if (reshapeMode)
            {
                // iRacing: the target is the sim's OWN steering torque, not a
                // synthesis. The stability stages below still apply, since they
                // are wheel-side conditioning rather than model conditioning.
                target = ComputeIRacingForce();
            }
            else if (modeB)
            {
                // Mode B: the game-derived target is REPLACED by synthesis.
                // Centering and the damper below still apply; they're
                // wheel-side stability, not game-force conditioning.
                var synth = ComputeModeBForce();
                if (!synth.HasValue)
                {
                    // Slip-starved (never fed, or dead past the dwell): the
                    // synthesizer has nothing to work with, so replacing the
                    // target would mute the wheel entirely (the 2026-08-13
                    // RS50/FH6 report: Forza's Data Out pointed at SimHub's
                    // port, slip never arrives, the game's real FFB was
                    // discarded, wheel totally dead). Pass the tapped game
                    // force through instead, exactly like Mode B off, and
                    // tell the user how to feed the plugin.
                    //
                    // Pass through ONLY while the session is provably live:
                    // fresh frames, the physics proxy reads driving, and
                    // SimHub's own pause/menu/replay flags are all clear.
                    // FH6 re-emits the frozen pre-pause force through
                    // pauses, results, replays, fast travel, and load
                    // screens (the tap stays "fresh" the whole time), and
                    // streaming that force at a stationary wheel walks it to
                    // the rotational stop (the issue #13 full-lock class).
                    // The physics proxy alone cannot catch a replay or a
                    // frozen pause frame (live-looking values), hence the
                    // flag gate on top. Residual exposure: a not-driving
                    // state the game reader does not flag, with frames still
                    // flowing, matches what Mode B off already ships; and
                    // when frames stop before any flag lands, the frozen
                    // value can ride the freshness bound for up to 250 ms.
                    //
                    // Blocked arm wire: with a tapped force present, hold
                    // ACTIVE zero so the frozen value cannot reach the wheel
                    // (for the stale sub-case this is byte-identical to the
                    // pre-fix ramp-out zero; for the never-fed sub-case the
                    // pre-fix wire was a silent keepalive, and active zero
                    // is the deliberate safer choice: wheel released, not
                    // handed a frozen ep0 force). With NO tapped force stay
                    // null/silent so tap-less setups (Secure Boot) keep
                    // native ep0 FFB through frame hiccups instead of
                    // getting muted. That matches the pre-fix wire for the
                    // never-fed sub-case; the stale+no-tap sub-case flips
                    // from the pre-fix mute to silent, which is the point.
                    //
                    // The stability tail is skipped in both arms: its terms
                    // are ramp-gated to zero in this state anyway, and they
                    // belong to synthesis, not to the game's own force.
                    var starvedSrc = _telemetrySource;
                    if (starvedSrc != null && starvedSrc.IsSessionActive
                        && starvedSrc.MsSinceLastFrame <= 250.0
                        && !_gameNotDrivingState)
                    {
                        NoteModeBSlipStarved();
                        return target;
                    }
                    _starvedLiveTicks = 0;
                    return target.HasValue ? (short?)0 : null;
                }
                NoteModeBSlipRecovered();
                target = synth;
                // The stationary spring, rendered here because the synthesis
                // assigned over the upstream stage's work. Same sign space as
                // the synthesis (the game's; the device negates and scales),
                // so the upstream recipe applies unchanged.
                if (_fxTestMode == 0 && ActiveGameAllowsStationarySpring
                    && EffectiveStationarySpringEnabled(_activeGame))
                {
                    var sprung = ApplyStationarySpring(target, inSynthesis: true);
                    _lastSpringAddLsb = sprung.HasValue ? sprung.Value - (target ?? 0) : 0;
                    target = sprung;
                }
            }
            else
            {
                // Pass-through terrain (Farming Simulator on HID++ wheels,
                // e.g. the G PRO): the game's extracted FFB flows here, not
                // through spring mode, so the terrain kick is ADDED onto the
                // game force. Only when a game force is present: a null
                // target is the native-FFB handoff and must stay null.
                var st = Settings;
                if (target.HasValue && st != null && st.SpringModeTerrainEnabled
                    && _activeGame != null
                    && _activeGame.StartsWith("FarmingSimulator", StringComparison.Ordinal))
                {
                    long nowT = Stopwatch.GetTimestamp();
                    double dtMsT = _ptKickPrevTicks == 0
                        ? 1.0 : (nowT - _ptKickPrevTicks) * 1000.0 / Stopwatch.Frequency;
                    if (dtMsT < 0.05) dtMsT = 0.05; else if (dtMsT > 50.0) dtMsT = 50.0;
                    _ptKickPrevTicks = nowT;
                    long kStampT = System.Threading.Interlocked.Read(ref _fsKickStampTicks);
                    float kickTargetT = (kStampT != 0 && nowT - kStampT < Stopwatch.Frequency / 4)
                        ? _mbKickCached : 0f;
                    float aT = (float)(1.0 - Math.Exp(-dtMsT / 8.0));
                    _springKickEma += (kickTargetT - _springKickEma) * aT;
                    int vT = target.Value + (int)Math.Round(
                        _springKickEma * (float)st.SpringModeTerrainGain * 0.5f * 32767f);
                    if (vT > short.MaxValue) vT = short.MaxValue;
                    else if (vT < short.MinValue) vT = short.MinValue;
                    target = (short)vT;
                }
            }
            // Mode B only past this point: the design's FORZAFFB Mode A
            // reshaper profile (slip-saturation reshape, WEIGHT/noise gate,
            // center-boosted damper) was deliberately not carried over.
            // With Mode B off, the tapped game force passes through untouched
            // (plus the FS terrain kick above when enabled).
            if (!modeB || !target.HasValue) return target;
            double v = target.Value;
            // The sim's torque alone, before the wheel-side terms below. The
            // reshape's stationary spring deficit-fills against THIS: damper
            // and friction are velocity terms, not centering, and must not
            // count as "the sim already centres".
            double simOnly = v;

            // Centering "fight": a directional force toward center
            // proportional to steering lock, so the wheel resists turning
            // even when the synthesized load force is light. Speed-scaled by
            // the model's trail ramp so a parked wheel isn't spring-loaded.
            // Both stability terms here are gated by the telemetry ramp
            // (_mbRamp): in menus (raceOn=0) the synthesized force is already
            // zero, but stale speed/steer snapshots used to keep centering
            // and the damper alive with no game force masking them, and the
            // naked damper chattered against HID quantization ("buzzes
            // out like crazy at center in the menu", ninth wheel test).
            // Ramp-gated, menus get a true zero stream: wheel free AND silent.
            // Spring mode swaps the ramp source (its own engage/stall ramp;
            // _mbRamp is slip-sample-driven and a spring game never feeds it)
            // and drops the centering fight entirely: the game's spring IS
            // the centering, adding ours would double-center. The damper
            // stays; it is the anti-ring half of rendering a spring.
            // Each mode owns its own engage ramp: _mbRamp is slip-sample-driven
            // and neither a spring game nor iRacing ever feeds it.
            float ramp = springMode ? _springRamp
                       : reshapeMode ? _irRamp
                       : _mbRamp;
            // Centering is dropped for both non-synthesis modes, for the same
            // reason: the force already carries its own centering (the game's
            // spring, or iRacing's solved self-aligning torque), so adding ours
            // would double-center and fight the driver.
            float centerGain = (springMode || reshapeMode) ? 0f
                : _pModeBCenterGain * _mbRamp
                * (float)Math.Min(_lastSpeedKmh / Math.Max(1.0, _satModel.SpeedFullKmh), 1.0);
            // Velocity damper gain, computed early because the physical-state
            // block below serves both stability terms. Adds a torque opposing
            // wheel motion so the centering force can't ring. Driven by the
            // PHYSICAL wheel velocity (HID steering reader, ~report-rate,
            // minimal lag) rather than Forza's 60 Hz EMA-smoothed telemetry
            // steer, because the let-go oscillation is a fast physical wheel
            // swing a lagged velocity can't catch. SIGN: a hot-lap trace
            // (2026-06-27) proved Forza's convention is physical-torque
            // ∝ -(FFB value), and the physical steer shares the game-steer
            // sign (corr 0.999), so a force that OPPOSES velocity is +Kd*vel
            // (the original `-=` was anti-damping and grew the oscillation).
            // Clamped to half scale.
            float damperGain = _pModeBDamperGain * ramp;
            // Implement drag's other half: load thickens the damper too, so
            // the heaviness reads as resistance, not just a stiffer spring.
            if (springMode && (Settings?.SpringModeDragEnabled ?? false))
            {
                // ADDITIVE, not multiplicative: the boost used to scale the
                // user's base Damping, so at a low base (0.07 shipped) full
                // working load added arithmetic dust and drag was only
                // feelable through the spring in turns (owner, 2026-08-08).
                // An additive term gives load its own resistance footing:
                // full load at gain 1 adds 0.2, the feel of a real Damping
                // slider move, straight-line included. Capped at the
                // slider's own max so a high base plus high gain cannot
                // overdamp into sluggishness.
                float dragLoad = EffectiveDragLoad01();
                if (dragLoad > 0f)
                {
                    damperGain += dragLoad * (float)Settings.SpringModeDragGain * 0.2f;
                    if (damperGain > 0.6f) damperGain = 0.6f;
                }
            }

            // Physical wheel state (position + velocity), shared by the
            // damper and, when Direct centering (MBCPD) is on, the centering
            // spring. Skipped entirely when no consumer needs it, so a
            // damper-off, PD-off recipe runs the legacy path bit-for-bit.
            float velLp = _mbDamperVelLp;
            float physSteer = float.NaN;   // NaN = no fresh physical position
            double dtD = 1.0;              // ms since the last physical-state tick
            // Stationary friction (R3E reshape): resynthesize RaceRoom's low-speed
            // parked damper, which lives in the FFB output this route replaces with
            // the sim's shared-memory steering force (that value is ~0 parked). It
            // needs the physical wheel velocity below, so fold it into needPhys.
            var stFrCfg = Settings;
            // Also under Telemetry Based FFB and Farming Simulator's spring
            // mode: both replace the game's force outright, parking resistance
            // included (owner, 2026-09-13 and 2026-09-19). Same setting and
            // controls; the sign follows the route below, and spring mode
            // shares the synthesis's frame (the device scales and negates both).
            bool wantR3EFriction = ((reshapeMode && IsSharedMemoryTakeoverGame(_activeGame))
                                    || _forceMode == ForceModeModeB
                                    || _forceMode == ForceModeSpring)
                && stFrCfg != null
                && stFrCfg.R3EStationaryDamper
                && stFrCfg.R3EStationaryDamperStrength > 0.0001;
            // Stationary spring under the armed reshape: the same per-game
            // spring ApplyStationarySpring renders on the tap route, rendered
            // here because the reshape assigns over its input. Wants the
            // physical wheel position below (RaceRoom publishes no steering
            // through SimHub, so physical is the only position there on either
            // route). FXTEST owns the wheel while it runs, as upstream.
            // Requires the friction: on the tap route the spring works against
            // RaceRoom's own parked damper, which this route replaces. With
            // the friction off the only dissipation left is the 0.07 stability
            // damper, and a lagged spring (HID position ~20 ms + the EMA) eats
            // most of that margin, so a let-go would hunt around centre
            // (review, 2026-09-12). The badge names this state.
            bool wantReshapeSpring = reshapeMode
                && _fxTestMode == 0
                && wantR3EFriction
                && ActiveGameAllowsStationarySpring
                && EffectiveStationarySpringEnabled(_activeGame);
            bool needPhys = damperGain != 0f || (_mbCenterPdOn && centerGain != 0f)
                || wantR3EFriction || wantReshapeSpring;
            if (needPhys)
            {
                // Prefer the physical wheel velocity; fall back to the telemetry
                // velocity if the HID reader is absent or stale.
                float vel = _steerVel;
                var sr = _steeringReader;
                if (sr != null)
                {
                    long t = sr.LastUpdateTicks;
                    if (t != 0)
                    {
                        if (t != _physVelPrevTicks)
                        {
                            float ps = sr.SteerNorm;
                            if (_physVelPrevTicks != 0)
                            {
                                double pdt = (t - _physVelPrevTicks) / (double)Stopwatch.Frequency;
                                if (pdt > 0.0002 && pdt < 0.05)
                                {
                                    float inst = (float)((ps - _physVelPrevSteer) / pdt);
                                    _physWheelVel += (inst - _physWheelVel) * 0.5f; // light EMA
                                }
                            }
                            _physVelPrevSteer = ps;
                            _physVelPrevTicks = t;
                        }
                        // Use physical state only while fresh; if the wheel
                        // stops streaming reports, zero the velocity so a stale
                        // value can't leave a constant offset torque on the
                        // wheel (and leave physSteer NaN so the centering
                        // spring falls back to the telemetry position).
                        if (Stopwatch.GetTimestamp() - t <= SteerMaxAgeTicks)
                        {
                            vel = _physWheelVel;
                            physSteer = sr.SteerNorm;
                        }
                        else _physWheelVel = 0f;
                    }
                }

                // Band-limit the stability-term velocity (thirteenth wheel
                // test, trace-proven). The damper is a delayed velocity
                // feedback: force moves the wheel, HID reports the velocity
                // ~15-20 ms late, so above ~1/(4·delay) the "opposing" force
                // arrives more than half a cycle late and PUMPS the motion.
                // The trace showed a self-sustained ~70 Hz limit cycle (force
                // in phase with physical velocity, game telemetry frozen) at
                // ±6k LSB, dead center of the G923's strongest motor band. A
                // ~25 ms low-pass drops loop gain ~11x at 70 Hz (kills the
                // cycle) while a genuine hands-off swing (1-3 Hz, what the
                // damper exists to catch) passes almost untouched. The
                // Direct-centering look-ahead term feeds on the SAME
                // band-limited velocity for the same reason: a raw velocity
                // lead would hand the 70 Hz loop its gain back through the
                // centering path.
                long nowD = Stopwatch.GetTimestamp();
                dtD = _mbDampPrevTicks == 0
                    ? 1.0
                    : (nowD - _mbDampPrevTicks) * 1000.0 / Stopwatch.Frequency;
                if (dtD < 0.1) dtD = 0.1; else if (dtD > 50.0) dtD = 50.0;
                _mbDampPrevTicks = nowD;
                float aD = (float)(1.0 - Math.Exp(-dtD / 25.0));
                _mbDamperVelLp += (vel - _mbDamperVelLp) * aD;
                velLp = _mbDamperVelLp;
                // (A second cascaded pole was tried here on 2026-08-15 and
                // REVERTED the same day. It was aimed at an engine-band ring
                // that turned out not to come through the damper at all: the
                // Lead detail mode's slope extrapolation is a differentiator
                // whose gain rises with frequency, and it is applied in
                // ComputeIRacingForce, before this term and unfiltered. All
                // the extra pole achieved was deafening the one term that
                // removes energy from the loop, exactly where it was needed.)
            }

            if (centerGain != 0f)
            {
                // Direct centering (MBCPD): spring on the wheel's OWN position
                // (fresh HID read) instead of the game's 60 Hz report, plus a
                // look-ahead term on the band-limited wheel velocity so the
                // spring aims at where the wheel is HEADED. A spring on a
                // lagged position is an oscillator; position + lead gives the
                // classic PD shape whose damping scales with the spring gain,
                // so centering cannot ring however the two sliders are set.
                // Toggle off: steerCmd is exactly the legacy clamped telemetry
                // steer (and |steer|*sign(steer) == steer), so the shipped
                // output is reproduced bit-for-bit.
                float steer = (_mbCenterPdOn && !float.IsNaN(physSteer)) ? physSteer : _lastSteerNorm;
                if (steer > 1f) steer = 1f; else if (steer < -1f) steer = -1f;
                float steerCmd = steer;
                if (_mbCenterPdOn)
                {
                    // Bumpless source handoff: when the HID reader goes stale
                    // (or comes back), the position source switches and the
                    // two sources disagree by the telemetry lag, which would
                    // step the spring force in one tick. Slew-cap the position
                    // at 0.012 norm/ms: ~2x the fastest real wheel swing
                    // (a 3 Hz let-go oscillation peaks near 0.006 norm/ms),
                    // so genuine motion passes untouched while a source step
                    // slides over ~15 ms. Also dissolves the 8-bit game-steer
                    // quantization on the fallback path.
                    float maxStep = (float)(0.012 * dtD);
                    float dStep = steerCmd - _mbCenterSteerPrev;
                    if (dStep > maxStep) steerCmd = _mbCenterSteerPrev + maxStep;
                    else if (dStep < -maxStep) steerCmd = _mbCenterSteerPrev - maxStep;
                    _mbCenterSteerPrev = steerCmd;

                    steerCmd += _pModeBCenterLeadMs * 0.001f * velLp;
                    if (steerCmd > 1f) steerCmd = 1f; else if (steerCmd < -1f) steerCmd = -1f;
                }
                v += centerGain * steerCmd * 32767.0;
            }

            if (damperGain != 0f)
            {
                // SIGN, and it is not the same in every mode. +Kd*vel OPPOSES
                // wheel motion in the synthesis convention (Forza hot-lap
                // trace, 2026-06-27). ComputeIRacingForce authors its own
                // final sign instead of borrowing the tapped path's inversion,
                // so at this point the reshape value carries the OPPOSITE
                // polarity, and the identical term drove the wheel instead of
                // resisting it: positive velocity feedback, which is why
                // raising Damping made the standstill ring WORSE rather than
                // settling it (owner rig, 2026-08-15, the discriminating
                // test). The closed loop through the sim is the one path that
                // most needs a working damper, so flip it to match.
                // No cap of its own (owner, 2026-09-12: "there shouldn't be
                // caps on damper, friction or spring"). The full-scale clamp
                // at the end is the wheel's limit and the only one.
                double damp = (reshapeMode ? -damperGain : damperGain) * velLp * 32767.0;
                v += damp;
            }

            if (wantR3EFriction)
            {
                // Car-speed gate: firm parked, fading to nothing by FadeKmh. Above
                // that the driver feels only the sim's own force. The GAIN is what
                // fades with speed, so the resistance's presence tracks car speed,
                // not turn speed.
                double fade = stFrCfg.R3EStationaryDamperFadeKmh;
                if (fade < 1.0) fade = 1.0;
                double gate = 1.0 - _lastSpeedKmh / fade;
                if (gate > 0.0)
                {
                    if (gate > 1.0) gate = 1.0;
                    // A viscous damper, NOT a relay. The first cut SATURATED on a
                    // small wheel motion, which in a feedback loop with the wheel's
                    // ~20 ms reporting lag acts like bang-bang and set up a limit
                    // cycle (owner, 2026-09-05: "it oscillates"). Linear in the
                    // band-limited velocity is dissipative and stable, and it is
                    // literally RaceRoom's own "stationary friction uses the damper
                    // effect". NO deadband:
                    // its edge made the force flick on and off as the wheel crept.
                    // A LIGHT low-pass on the FORCE only takes the edge off this
                    // term's own ripple. The graininess the owner felt turned out to
                    // be general wheel-render notchiness present on the TAP route too
                    // (2026-09-05), which the master Smoothing slider handles for
                    // every source (~3 ms was enough); a heavy filter here just
                    // double-smoothed and lagged the friction, so this stays light.
                    // OPPOSES motion, same convention as that damper (-vel for
                    // reshapeMode).
                    // The slider means what it says: no gain cap and no
                    // half-scale clamp (owner, 2026-09-12). Only the final
                    // full-scale clamp applies.
                    double gain = stFrCfg.R3EStationaryDamperStrength;
                    // The friction and the Damping slider are the same kind of
                    // term, velocity feedback off one delayed signal, and their
                    // SUM is what the loop has to survive. 0.6 of damper alone
                    // settles; 0.6 of damper plus 0.4 of friction rang on a
                    // let-go from lock (rig, Forza, 2026-09-13). So the friction
                    // yields as the damper rises, keeping the pair within the
                    // 0.6 the damper slider allows by itself: untouched at the
                    // 0.07 default, trimmed only past a damper of 0.2.
                    double headroom = 0.6 - _pModeBDamperGain;
                    if (headroom < 0.0) headroom = 0.0;
                    if (gain > headroom) gain = headroom;
                    // Opposes motion in each route's own frame: the takeover
                    // authors the motor sign (-vel), the synthesis is authored
                    // in the game's space where +vel opposes, the same split
                    // the damper above makes.
                    // On the synthesis route the term rides the same engage ramp
                    // as the damper and centering: without it the friction was
                    // at full strength from the first tick of an engage, and for
                    // the ~3 s a parked telemetry stall takes to be called starved
                    // (review, 2026-09-13). The takeover keeps its own ramp-free
                    // shape, which has been driven.
                    double fr = (reshapeMode ? -1.0 : ramp) * velLp * gain * gate * 32767.0;
                    // One slider, one weight on both routes. The takeover skips
                    // the device's FFB strength trim; the synthesis does not, so
                    // pre-compensate here the way the stationary spring does,
                    // and 0.40 lands as 0.40 either way (owner, 2026-09-13).
                    if (!reshapeMode)
                    {
                        float trim = _device != null ? _device.FfbScale : 1f;
                        if (trim < 0.05f) trim = 0.05f;
                        fr /= trim;
                    }
                    float aFr = (float)(1.0 - Math.Exp(-dtD / 6.0));
                    _r3eFrictionLp += (float)((fr - _r3eFrictionLp) * aFr);
                    v += _r3eFrictionLp;
                }
                else _r3eFrictionLp = 0f;   // faded out: don't carry a stale term
            }
            else _r3eFrictionLp = 0f;

            if (wantReshapeSpring)
            {
                // Same recipe as ApplyStationarySpring (position EMA, linear
                // speed fade, strength x |steer| of full scale, deficit-fill),
                // with two deliberate differences, both because TrueforceDevice
                // skips FfbInvertSign and FfbScale under FfbBypassTapCorrections
                // while the reshape is armed:
                //   SIGN: authored here as the MOTOR sign. Upstream, dir =
                //   sign(steer) in the game's space and the device negates it;
                //   here nothing negates, so the centering direction is
                //   -sign(steer), the same flip the damper and friction above
                //   carry (reshapeMode ? -gain : gain).
                //   SCALE: no division by FfbScale. The device does not multiply
                //   by it here, so the pre-compensation would land 1/FfbScale
                //   too strong.
                // Position: the fresh physical wheel (physSteer), else a fresh
                // game value, else no spring. No sim on this route publishes
                // steering through SimHub today, so physical is the working
                // case, exactly as on RaceRoom's tap route.
                float steerR = !float.IsNaN(physSteer) ? physSteer
                    : (Stopwatch.GetTimestamp() - System.Threading.Interlocked.Read(ref _lastSteerTicks)) <= SteerMaxAgeTicks
                        ? _lastSteerNorm
                        : float.NaN;
                float cutoffR = (float)EffectiveStationarySpringCutoff(_activeGame);
                float fadeR = cutoffR > 0f ? 1f - (_lastSpeedKmh / cutoffR) : 0f;
                int springAdd = 0;
                if (!float.IsNaN(steerR) && fadeR > 0f)
                {
                    if (fadeR > 1f) fadeR = 1f;
                    if (steerR > 1f) steerR = 1f; else if (steerR < -1f) steerR = -1f;
                    // Fresh start on every engage. The ramp below is ~0 for
                    // the first ticks after arming or a telemetry gap (pause,
                    // garage), and the spring contributes nothing there, so
                    // seeding the EMA from the live position costs nothing and
                    // means a wheel turned by hand during the gap never gets
                    // a kick toward where it USED to be from a stale EMA.
                    if (ramp < 0.05f) _rsSpringSteerEma = steerR;
                    else _rsSpringSteerEma += SpringSteerEmaAlpha * (steerR - _rsSpringSteerEma);
                    float steerS = _rsSpringSteerEma;
                    // Engage on the route's own 300 ms ramp, like the damper
                    // and the sim torque itself, so arming with lock on never
                    // steps the wheel (the reshape's stated contract).
                    double desired = EffectiveStationarySpringStrength(_activeGame)
                                   * Math.Abs(steerS) * fadeR * ramp * 32767.0;
                    // No cap (owner, 2026-09-12): strength x |steer| of full
                    // scale, exactly the tap route's meaning. The full-scale
                    // clamp at the end is the only limit, as it is upstream.
                    if (desired >= 1.0)
                    {
                        double dirR = (steerS > 0f) ? -1.0 : 1.0;
                        // Deficit-fill against the sim's own torque only: top
                        // up the same-direction part to the floor, never
                        // beyond, never against, so the spring lets go the
                        // moment the sim centres the wheel itself.
                        double have = (Math.Sign(simOnly) == Math.Sign(dirR)) ? Math.Abs(simOnly) : 0.0;
                        double add  = desired - have;
                        if (add > 0.0)
                        {
                            v += add * dirR;
                            // Trace value in the GAME's sign space, the tap
                            // route's convention, so `spring=` reads the same
                            // way on both routes for the same direction.
                            springAdd = -(int)(add * dirR);
                        }
                    }
                }
                _lastSpringAddLsb = springAdd;
            }

            if (v > short.MaxValue) v = short.MaxValue;
            else if (v < short.MinValue) v = short.MinValue;
            return (short)System.Math.Round(v);
        }

        /// <summary>Live-set one Mode B parameter from the "NAME value" access
        /// codes (BFULL / BSPD / BDIRK / BLOCKPT / BCIRCLE / BLEARN / BGTRIM /
        /// MBCPD). Applies immediately (the FFB thread reads these every
        /// tick), writes the matching Settings field where one exists, and
        /// persists. Values are clamped to sane ranges. Returns a
        /// human-readable status of what was set.</summary>
        public string SetModeBParam(string name, float value)
        {
            if (_device == null) return "wheel not initialized";
            float C(float v, float lo, float hi) => v < lo ? lo : (v > hi ? hi : v);
            switch ((name ?? string.Empty).ToUpperInvariant())
            {
                case "BFULL":
                    _satModel.FullU = C(value, 1.1f, 3f);
                    return $"Mode B full-drop utilization = {_satModel.FullU:0.00}";
                case "BSPD":
                    _satModel.SpeedFullKmh = C(value, 10f, 200f);
                    return $"Mode B trail ramp: full SAT by {_satModel.SpeedFullKmh:0} km/h";
                case "BDIRK":
                    _pModeBDirSoft = C(value, 0f, 0.5f);
                    if (Settings != null) { Settings.ModeBDirSoft = _pModeBDirSoft; PersistSettings(); }
                    return $"Mode B center softness = {_pModeBDirSoft:0.00} (0 = linear/legacy; higher = wider flat spot at center; fixes buzz vs jumpy trade)";
                case "BLOCKPT":
                    _pModeBLockupPoint = C(value, 0.2f, 2.0f);
                    if (Settings != null) { Settings.ModeBLockupPoint = _pModeBLockupPoint; PersistSettings(); }
                    return $"Mode B lockup point = {_pModeBLockupPoint:0.00} slip ratio (higher = wheel keeps its weight deeper into braking before it lightens; raise this if light braking goes limp)";
                case "BCIRCLE":
                    bool circleOn = value >= 0.5f;
                    if (circleOn && !_mbFrictionCircleOn) _mbCircleRatioEma = _lastFrontSlipRatioAbs;
                    else if (!circleOn && _mbFrictionCircleOn) _mbLockRatioEma = _lastFrontSlipRatio;
                    _mbFrictionCircleOn = circleOn;
                    if (Settings != null) { Settings.ModeBFrictionCircle = circleOn; PersistSettings(); }
                    return circleOn
                        ? "Friction circle ON: braking/wheelspin spend the tire's grip and force scales by the lateral share left (replaces the lockup gate)."
                        : "Friction circle OFF: standard lockup gate restored.";
                case "BLEARN":
                    _mbBrakeLearnOn = value >= 0.5f;
                    if (Settings != null) { Settings.ModeBLongitudinalGripLearn = _mbBrakeLearnOn; PersistSettings(); }
                    if (!_mbBrakeLearnOn)
                        return "Auto braking grip OFF: radius uses the manual braking-grip point (BLOCKPT).";
                    double rNow = _pModeBGripTrim * _mbGripPeakForRadius;   // same clamp the force path applies
                    if (rNow < 0.2) rNow = 0.2; else if (rNow > 2.0) rNow = 2.0;
                    return $"Auto braking grip ON: the circle/gate radius follows each car's grip auto-cal peak x trim (now {rNow:0.00}; trim {_pModeBGripTrim:0.00}).";
                case "BGTRIM":
                    _pModeBGripTrim = C(value, 0.3f, 1.5f);
                    if (Settings != null) { Settings.ModeBGripTrim = _pModeBGripTrim; PersistSettings(); }
                    return $"Braking-grip trim = {_pModeBGripTrim:0.00} (radius = trim x grip-cal peak; 1.00 = the raw detected grip, lower lightens sooner)";
                case "MBCPD":
                    _mbCenterPdOn = value >= 0.5f;
                    if (Settings != null) { Settings.ModeBCenterPd = _mbCenterPdOn; PersistSettings(); }
                    return _mbCenterPdOn
                        ? $"Direct centering ON: centering springs on the wheel's own position (look-ahead {_pModeBCenterLeadMs:0} ms), so the pull toward straight is fresh and cannot ring. Turn OFF and report your wheel model if centering ever pushes AWAY from center."
                        : "Direct centering OFF: centering uses game-reported steering (legacy).";
                default:
                    return $"unknown Mode B param '{name}' (try BFULL/BSPD/BDIRK/BLOCKPT/BCIRCLE/BLEARN/BGTRIM/MBCPD)";
            }
        }

        /// <summary>Rev-bar fraction for the rim LEDs on Forza sources, which
        /// carry no RpmPercent channel: raw revs mapped so the bar lights
        /// from 70 percent of max to the limiter. The 70 percent onset is the
        /// haptic-engine validated value.</summary>
        // Redline-flash latch for the derived Forza rev bar (telemetry
        // thread only). Hysteresis lives in the DispatchFrame LED block.
        private bool _forzaRedlineLatch;

        // The 10-LED strip lights across the top window BELOW the redline:
        // from RevBarFillWindowFrac of the redline RPM up to it. 0.85 = the
        // strip sequences over the last ~15% of revs before the shift point,
        // then goes full + flashes at the redline. A fraction of the redline
        // (not of MaxRpm) so a low CarFacts redline still gets a proportional
        // fill window instead of an onset above its own redline.
        private const double RevBarFillWindowFrac = 0.85;

        /// <summary>0..1 fill for the rev-LED strip: 0 below the fill window,
        /// 1 at or above <paramref name="fullRpm"/> (the resolved redline).</summary>
        private static double ForzaRevBar(double rpm, double fullRpm)
        {
            if (fullRpm <= 1.0) return 0.0;
            double onset = fullRpm * RevBarFillWindowFrac;
            if (rpm <= onset) return 0.0;
            double bar = (rpm - onset) / (fullRpm - onset);
            if (bar < 0.0) bar = 0.0; else if (bar > 1.0) bar = 1.0;
            return bar;
        }

        /// <summary>Run the simulated rev/shift sweep on the rim LEDs (settings
        /// "Test" button). Opens the HID++ channel on demand so it works with
        /// nothing running; safe regardless of active game.</summary>
        public void TestRpmLeds()
        {
            if (_rpmLeds == null) { SimHub.Logging.Current.Info("[RPM-LED] controller not initialized"); return; }
            // Normal only: the test is two full up/down sweeps plus a redline hold,
            // about eleven seconds of continuous level writes, and the first of them
            // re-arms the keepalive a slot write had just stopped.
            if (MasterMode != TrueforceMasterMode.Normal)
            { SimHub.Logging.Current.Info("[RPM-LED] test skipped: the bar is not ours to drive in this mode"); return; }
            int ms = _rpmLeds.RunTest();
            SimHub.Logging.Current.Info($"[RPM-LED] Test started, duration={ms} ms ({_rpmLeds.Status})");
        }

        /// <summary>Force the rim LEDs off (feature unchecked / plugin
        /// disabled). No telemetry frames arrive after that to drive the
        /// gate-off path, so callers must invoke this explicitly.</summary>
        public void TurnOffRpmLeds() => _rpmLeds?.ForceOff();

        /// <summary>The wheel's pattern selection as last read or written
        /// (0 = not seen yet). What both settings pickers display.</summary>
        public int GetWheelPatternSelection() => _rpmLeds?.KnownSelection ?? 0;

        /// <summary>Called by the settings pickers when they render with no
        /// known selection: open the LED channel in the background so the
        /// wheel's actual selection gets read (resolve seeds it via fn2) and
        /// the combo fills in, instead of sitting blank until a game or the
        /// Test button happens to open the channel. The probe writes HID++
        /// queries, so it obeys the same pipe-safety rule as every other
        /// one-shot: never while a game's own force feedback is live.</summary>
        public void EnsureWheelPatternRead()
        {
            if (_rpmLeds == null || _rpmLeds.KnownSelection > 0) return;
            // Not while the plugin is off. Note the pipe-safety test below cannot
            // stand in for this outside full mode: no telemetry source runs there,
            // so NoTelemetryArriving is trivially true and the test always passes.
            if (MasterMode == TrueforceMasterMode.Off) return;
            if (!OneShotLevelWritesAllowed) return;
            _rpmLeds.OpenInBackground();
        }

        /// <summary>The active car's remembered pattern, or null when the
        /// car has none (or no car is active).</summary>
        public int? GetCarRememberedPattern()
        {
            var s = Settings;
            if (s?.CarRevLightEffect == null) return null;
            if (string.IsNullOrEmpty(_activeGame) || string.IsNullOrEmpty(_activeCarId)) return null;
            return s.CarRevLightEffect.TryGetValue(_activeGame + "/" + _activeCarId, out int v) && v > 0
                ? v : (int?)null;
        }

        /// <summary>Remember a pattern for the active car: re-applied
        /// whenever this car loads. Optional automation only; the pick is
        /// already on the wheel. False when no car is active.</summary>
        public bool RememberPatternForActiveCar(int effect)
        {
            if (effect < 1 || effect > 9) return false;
            if (string.IsNullOrEmpty(_activeGame) || string.IsNullOrEmpty(_activeCarId)) return false;
            var s = Settings;
            if (s == null) return false;
            if (s.CarRevLightEffect == null)
                s.CarRevLightEffect = new Dictionary<string, int>();
            string key = _activeGame + "/" + _activeCarId;
            s.CarRevLightEffect[key] = effect;
            // The two kinds of pin are meant to be mutually exclusive, and the
            // library-pattern side already clears this one. Without the mirror, a car
            // with a pattern pinned kept showing that pattern after the user pinned a
            // wheel effect instead, because the pattern wins when both are set.
            s.CarLightPattern?.Remove(key);
            try { PersistSettingsCore(); } catch { }
            return true;
        }

        /// <summary>Pin a DELIBERATE pick to the active car, when the user has asked
        /// for that with "Always remember per car". A silent no-op otherwise.
        ///
        /// Deliberately not called from the paths that APPLY a remembered pattern, or
        /// it would re-pin what it had just read and a restore would look like a
        /// choice.</summary>
        private void MaybeAutoRememberForCar(string patternId, int effect)
        {
            if (Settings?.AlwaysRememberCarPattern != true) return;
            if (string.IsNullOrEmpty(_activeGame) || string.IsNullOrEmpty(_activeCarId)) return;
            try
            {
                if (!string.IsNullOrEmpty(patternId)) RememberLightPatternForActiveCar(patternId);
                else if (effect >= 1 && effect <= 9) RememberPatternForActiveCar(effect);
            }
            catch (Exception ex)
            { SimHub.Logging.Current.Warn("[TF4ALL] auto-remember failed: " + ex.Message); }
        }

        /// <summary>Forget the active car's remembered pattern. The wheel's
        /// CURRENT selection is deliberately untouched: removing automation
        /// must not yank the lights.</summary>
        public bool ForgetPatternForActiveCar()
        {
            if (string.IsNullOrEmpty(_activeGame) || string.IsNullOrEmpty(_activeCarId)) return false;
            var s = Settings;
            if (s?.CarRevLightEffect == null) return false;
            if (!s.CarRevLightEffect.Remove(_activeGame + "/" + _activeCarId)) return false;
            try { PersistSettingsCore(); } catch { }
            return true;
        }

        /// <summary>The dropdown action: set the wheel's pattern selection,
        /// exactly like using the base's own menu. Applies IMMEDIATELY, even
        /// while a game sends its own force feedback: a person clicking this
        /// dialog is not also mid-corner, so the momentary force interruption
        /// a switch causes there is one they chose, and gating it made a
        /// parked pattern change in a native-FFB game impossible. The
        /// AUTOMATED car-load apply keeps its safety gate, because that one
        /// really can fire mid-drive. Lands on a background task (a cold
        /// channel open can take seconds). Whether the firmware keeps the
        /// selection across a power cycle is untested; the base's own menu
        /// shows it either way.</summary>
        /// <param name="previewAfter">Sweep the strip once the selection has
        /// actually landed. The sweep used to be started by the caller on its own
        /// thread, which raced this one: the first steps drew the OLD pattern and
        /// it changed part-way through, so a quick walk down a list never showed
        /// the thing that had just been picked.</param>
        public void PickRevLightPattern(int effect, bool previewAfter = false)
        {
            if (_rpmLeds == null || effect < 1 || effect > 9) return;
            // Reachable from the always-visible rev-light dropdown, which is not the
            // same control as the slot writes BorrowSlot guards.
            if (MasterMode == TrueforceMasterMode.Off) return;
            // Whatever we were standing in the stage slot is no longer what the
            // wheel is showing, and neither are the car's own colors.
            LibraryPatternShowing = false;
            _autoAppliedColors = false;
            NoteLightSelectionChanged();
            MaybeAutoRememberForCar(null, effect);
            _rpmLeds.StagePattern(effect);   // arm applies it even if the live write loses
            Task.Run(() =>
            {
                try
                {
                    if (!_rpmLeds.SelectPatternNow(effect))
                        SimHub.Logging.Current.Info(
                            "[RPM-LED] could not set the wheel selection (see log)");
                    // The dash follows the pick straight away rather than waiting
                    // for the telemetry poll to notice, which never happens at all
                    // for someone cycling patterns in the menus with no game
                    // running. Not gated on the game's force feedback, for the
                    // same reason the pick itself is not: we have just written to
                    // this pipe, so reading the slot back adds no exposure.
                    PublishDashProfileForSelection(effect, _rpmLeds.MirrorSteps);
                    if (previewAfter) PreviewRevLightPattern();
                }
                catch (Exception ex)
                {
                    SimHub.Logging.Current.Error("[TF4ALL] pattern pick error", ex);
                }
            });
        }

        /// <summary>One-cycle rev sweep so a pattern pick is visible the
        /// moment it is made.
        ///
        /// Runs only in Normal mode, only while no game's force feedback is
        /// live (OneShotLevelWritesAllowed), and only while our own bar is dark.
        /// The pick and the slot write still land when it stands down, so in a
        /// game that lights the wheel itself the new colours show on the game's
        /// own bar at once, and that is the feedback.
        ///
        /// An earlier version of this comment said the sweep was deliberately
        /// NOT gated on force, because gating it had once made parked browsing
        /// in a native-FFB game impossible. That gate keyed on a game being
        /// loaded; this one keys on force actually flowing, which a parked car
        /// does not do, so parked browsing works and driving does not fight the
        /// game's bar. Do not remove it on the strength of the old note.</summary>
        public void PreviewRevLightPattern()
        {
            if (_rpmLeds == null) return;
            // FULL only, and gated here rather than at each caller because there are
            // three: PickRevLightPattern's previewAfter, and both rev-light combos,
            // which call this directly on a re-click of the already-selected row and
            // so never pass through the gated pick. The sweep is a 0-to-10-to-0 level
            // ramp, a lit hold and a ramp back down, roughly seven seconds of level
            // traffic, and it opens the channel itself if it is closed. That is the
            // continuous bar driving lights-only forbids and the wheel traffic off
            // forbids outright.
            if (MasterMode != TrueforceMasterMode.Normal) return;
            // Not while a game's own force feedback is live. This is the same
            // pipe-safety rule every other one-shot obeys, and the sweep is the
            // heaviest one-shot there is: roughly seven seconds of level writes
            // on the endpoint that force shares.
            //
            // The LiveBarIsLit test below is not enough on its own, and the RS50
            // report that found this shows why. It sees OUR bar, and our bar only
            // runs when the game's force is proven quiet. In a game that lights
            // the wheel itself (Assetto Corsa does), the force is never quiet, so
            // our bar is never lit, so this never self-suppressed: cycling a
            // pattern mid-session ran the sweep straight over the game's live bar
            // and the strip flickered between the two writers for seven seconds.
            // Without the sweep, the slot write still lands and the game's own
            // bar shows the new colours at once, which is the feedback the user
            // wanted. That is what "driving: the preview self-suppresses and the
            // live bar is the feedback" was always meant to mean.
            if (!PreviewSweepAllowed)
            {
                SimHub.Logging.Current.Info(
                    "[RPM-LED] preview sweep suppressed: a game is driving the bar.");
                return;
            }
            // Says WHY a sweep ran, because the alternative is guessing. The
            // rule is that a game driving the rim lights owns them and a sweep
            // would flicker against its writes, so a sweep during a game means
            // one of these two reads let it through and the pattern preview
            // flickered as a result (owner, in Assetto Corsa, 2026-09-03).
            SimHub.Logging.Current.Info(
                $"[RPM-LED] preview sweep allowed: nothingPlaying={NothingIsPlaying}, "
                + $"noTelemetry={NoTelemetryArriving()}, "
                + $"ledsHidppFree={_ledsHidppFree}, liveBarLit={_rpmLeds.LiveBarIsLit}.");
            // Only skip when the live bar is actually LIT, not merely when a
            // game is loaded. In the pits at idle the strip is dark, the live
            // feed is showing nothing to fight, and skipping here left a pattern
            // change with no feedback at all: a flicker from the write, then the
            // bar reasserting zero. The preview holds for a moment and the live
            // bar takes over again, which is correct, because the bar belongs to
            // the revs.
            //
            // Only where a game is PLAYING, though. The test asks whether the
            // strip is lit, not who lit it, and with nothing running the only
            // thing that can have lit it is our own ambient mode. That one
            // stands down for a preview on its own (OnAmbientLevel returns while
            // a preview owns the strip), so there is nothing to fight and
            // skipping meant a pattern pick did nothing at all while the audio
            // meter happened to be showing a loud passage.
            if (!NothingIsPlaying && _rpmLeds.LiveBarIsLit) return;
            // Parked, end LIT rather than dark. A sweep that finishes by turning
            // the strip off shows the user nothing, which is the whole reason
            // they picked something.
            //
            // On the PICK hold, not the edit one. This path is reached by
            // choosing a pattern, where the sweep has already shown it and the
            // full bar afterwards is just confirmation. Editing keeps the long
            // hold, because there the bar IS the thing being worked on.
            _rpmLeds.PreviewPattern(endLevel: WheelLedChannel.LedCount, holdMs: PickHoldMs);
        }

        /// <summary>Write one of the wheel's OWN slots, because the user is
        /// editing that slot itself rather than showing a pattern on the stage.
        /// The slot keeps its own name: they are changing their slot, and what it
        /// is called is theirs to set.</summary>
        public bool WriteOwnSlot(int slot, LightPattern pattern, out string message, bool sweep = true)
        {
            message = null;
            if (pattern == null || slot < 0 || slot >= WheelLedChannel.CustomSlotCount)
            { message = "No slot to write."; return false; }

            byte[] rgb = pattern.Rgb();
            if (rgb == null || rgb.Length < WheelLedChannel.LedCount * 3)
            { message = "That pattern's colors are unreadable."; return false; }

            // One decision for the write and its follow-up. A blocked show must
            // not leave a level behind: the sweep and the hold were what ramped
            // ShowLevel back to zero, so when they stand down the write settles
            // to the level the game last put on the strip (or the bar's own
            // level when the wire shows nothing recent) instead of lighting
            // all ten.
            bool show = MasterMode == TrueforceMasterMode.Normal && PreviewSweepAllowed;
            bool ok = BorrowSlot(new WheelLedChannel.WheelLedSlot
            {
                Slot = (byte)slot,
                DirectionWire = pattern.DirectionWire,
                Rgb = rgb,
            }, out message, displayLevel: show ? ShowLevel : StripLevelFromWire(), slotName: null, permanent: true,
               rawColors: pattern.TrimExempt);

            // The user's own slot, not one of ours standing in for a pattern.
            if (ok) LibraryPatternShowing = false;
            if (ok)
            {
                // Both of these DRIVE the bar, and only full mode may. Passing
                // sweep:false was not enough on its own: HoldLit re-arms the very
                // keepalive the slot write had just stopped, then holds the bar lit
                // for eight seconds and ramps it back down, which is around nine
                // seconds of level traffic per car load on the endpoint the game's
                // force feedback shares.
                // Same decision the write was made with. Both branches stand
                // down while a game's own force is live: the sweep also checks
                // for itself (it has other callers), and HoldLit is the same
                // kind of traffic.
                if (show)
                {
                    if (sweep) PreviewRevLightPattern();
                    else _rpmLeds.HoldLit(WheelLedChannel.LedCount, ShowHoldMs);
                }
            }
            return ok;
        }

        /// <summary>Make the wheel's five slots hold the first five patterns in
        /// the list, in order. That list position IS where a pattern lives, so
        /// this is what turns a move up or down into something that reaches the
        /// hardware.
        ///
        /// Only differences are written: each slot is read first and left alone
        /// when it already holds the right thing, so dragging one pattern up does
        /// not rewrite all five. Nothing is lost by a write, because whatever a
        /// slot held is still a pattern in the list, just lower down.</summary>
        public int SyncSlotsToWheel(out string message)
        {
            message = null;
            // Reordering or deleting a pattern in the editor lands here, and the
            // LIGHTSYNC tab stays live after a switch to off, so this needs its own
            // gate: the method opens the channel, reads every slot and writes names,
            // none of which passes through BorrowSlot.
            if (MasterMode == TrueforceMasterMode.Off)
            { message = "The plugin is switched off, so it is not writing to the wheel."; return 0; }
            if (_rpmLeds?.Channel == null) { message = "No supported wheel detected."; return 0; }
            if (!EnsureLedChannelOpen())
            { message = "Could not reach the wheel. Check it is connected and powered on."; return 0; }

            var want = LightPatterns.Patterns;
            // A slot on loan is holding something we put there on purpose, so
            // leave it alone. The caller decides whether the loan should end
            // first: a reorder says yes, opening the tab to look at what you
            // cycled to says no.
            //
            // HeldBorrowedSlot, not BorrowedSlot: the second is an in-memory
            // cache that starts at -1 and only fills once this process has
            // borrowed something itself, so a loan left open by a session that
            // died was invisible here and could be written over permanently,
            // which settles the loan and throws away the one copy of the user's
            // colors. The backup file is the authority on what is owed.
            int onLoan = HeldBorrowedSlot();
            if (onLoan < 0) onLoan = BorrowedSlot;
            int writes = 0, renames = 0, failed = 0, unreadable = 0;
            string lastError = null;

            for (int slot = 0; slot < WheelLedChannel.CustomSlotCount && slot < want.Count; slot++)
            {
                if (slot == onLoan) continue;
                var p = want[slot];
                if (p == null) continue;
                byte[] rgb = p.Rgb();
                if (rgb == null || rgb.Length < WheelLedChannel.LedCount * 3) continue;

                var have = ReadSlot(slot);
                if (have?.Rgb == null)
                {
                    // Unreadable. Writing anyway is how a slot the plugin never
                    // managed to read got permanently overwritten with nothing
                    // standing behind it. A read failure is also not evidence
                    // the slot is WRONG, so rewriting on every panel open would
                    // be five flash writes down the shared pipe for nothing.
                    // Skip it; the next open reads again.
                    unreadable++;
                    continue;
                }
                // Compare against what we WOULD send, not against what the
                // library stores. The library holds sRGB intent; the wheel
                // holds that intent after the color trim. Comparing the two
                // directly would never match on a calibrated wheel, so
                // colorsRight would be permanently false and this loop would
                // re-upload all five slots on every LIGHTSYNC tab open, which
                // is five flash writes down the pipe force feedback shares.
                string wireHex = ToWireHex(p);
                bool colorsRight = have?.Rgb != null
                    && have.DirectionWire == p.DirectionWire
                    && string.Equals(LightSlotBackupStore.ToHex(have.Rgb), wireHex,
                                     StringComparison.OrdinalIgnoreCase);

                if (colorsRight)
                {
                    // The colors are right but the NAME may not be. Slots keep
                    // whatever they were called before the plugin ever ran, and
                    // adopting the wheel's order matches on color alone, so the
                    // first five would sit there under their old names forever.
                    // Scrolling the base's own menu should read as the patterns
                    // that are actually in them. One name write, no color upload.
                    string wantName = WheelLedChannel.SlotNameFor(p.Name);
                    string haveName = ReadSlotName(slot);
                    // A name we cannot read is not a name we know to be RIGHT
                    // either, and skipping the write on an unreadable name meant
                    // slots 1 to 4 sat under their factory "CUSTOM n" labels
                    // forever: the color branch below is the only other thing
                    // that names a slot, and it never runs once the colors
                    // match. A name write is one cheap idempotent packet, far
                    // less than the color upload this branch exists to avoid.
                    if (!string.Equals(haveName ?? string.Empty, wantName, StringComparison.Ordinal)
                        && WriteSlotName(slot, p.Name))
                        renames++;
                    continue;
                }

                string msg;
                bool ok = BorrowSlot(new WheelLedChannel.WheelLedSlot
                {
                    Slot = (byte)slot,
                    DirectionWire = p.DirectionWire,
                    Rgb = rgb,
                }, out msg, displayLevel: ShowLevel, slotName: p.Name, permanent: true,
                   rawColors: p.TrimExempt);

                if (ok) writes++;
                else { failed++; lastError = msg; }
            }

            LightPatternStore.NormalizeSlots(LightPatterns);
            SaveLightPatterns();

            // A skipped slot is reported rather than swallowed. It means the
            // wheel did not answer for that slot, so it still holds whatever it
            // held, and the user's list and their wheel disagree until a read
            // succeeds. Saying nothing would read as "the wheel matches" when it
            // does not.
            string skipped = unreadable == 0 ? string.Empty
                : " " + (unreadable == 1
                    ? "One slot could not be read, so it was left as it is."
                    : unreadable + " slots could not be read, so they were left as they are.");

            message = (failed > 0
                ? "The wheel refused " + failed + " of the writes. " + (lastError ?? string.Empty)
                : writes == 0 && renames == 0 ? "The wheel already matches your list."
                : writes == 0 ? "Renamed " + renames + (renames == 1 ? " slot" : " slots") + " on the wheel."
                : writes == 1 ? "Updated one slot on the wheel."
                : "Updated " + writes + " slots on the wheel.") + skipped;
            if (writes > 0 || renames > 0 || unreadable > 0)
                SimHub.Logging.Current.Info(
                    $"[TF4ALL] slots synced: {writes} written, {renames} renamed, {unreadable} unreadable (left alone)");
            NoteSlotSyncOutcome(unreadable);
            return writes;
        }

        // ---- Slot-sync retry -------------------------------------------------
        //
        // Unreadable slots are not a permanent failure. They mean the wheel's
        // HID++ pipe was busy at the moment we asked, which is what happens when
        // the game is already running when SimHub starts: on the owner's rig
        // (RaceRoom, 2026-09-05) four sessions split exactly that way, "5
        // unreadable" in the two where the game came up first and a clean read in
        // the two where SimHub did. The pipe frees up later, so ask again instead
        // of leaving the wheel disagreeing with the user's list until they think
        // to restart in the right order.
        //
        // The OLED channel already recovers this way ("open attempt 1 failed;
        // retrying in 30 s"). This gives the rev-light slots the same treatment.
        private int _slotSyncRetryAtMs;      // 0 = nothing owed
        private int _slotSyncRetriesLeft;
        private const int SlotSyncRetryDelayMs = 30000;
        // Deliberately SHORT, and it was briefly raised to 20 minutes before
        // being put back (owner, 2026-09-12): "if a game is saturating the LEDs
        // then there's probably no reason to keep retrying if it means we
        // sacrifice performance". Exactly right. A saturated pipe stays
        // saturated for as long as the game drives the wheel, so a longer budget
        // buys no extra chance of success and just spends more workers on five
        // blocking reads each. And a game that owns the LED bar is one we should
        // be standing down from anyway.
        private const int SlotSyncMaxRetries   = 6;   // ~3 minutes of trying

        /// <summary>Arm, re-arm or stand down the retry from a sync's result.
        /// Called by SyncSlotsToWheel however it was reached, so a user-driven
        /// sync that succeeds also cancels a retry we owed.</summary>
        private void NoteSlotSyncOutcome(int unreadable)
        {
            if (unreadable <= 0)
            {
                if (_slotSyncRetryAtMs != 0)
                    SimHub.Logging.Current.Info(
                        "[TF4ALL] light slots read cleanly; they now match your list.");
                _slotSyncRetryAtMs = 0;
                _slotSyncRetriesLeft = 0;
                return;
            }

            // First sighting opens the budget. Re-arming on every attempt without
            // this would make the budget meaningless.
            if (_slotSyncRetryAtMs == 0 && _slotSyncRetriesLeft == 0)
            {
                _slotSyncRetriesLeft = SlotSyncMaxRetries;
                SimHub.Logging.Current.Info(
                    $"[TF4ALL] {unreadable} light slot(s) could not be read (the wheel's HID++ "
                    + "pipe was busy, which is what happens when the game starts before SimHub); "
                    + $"retrying in {SlotSyncRetryDelayMs / 1000} s.");
            }

            if (_slotSyncRetriesLeft > 0)
            {
                _slotSyncRetryAtMs = unchecked(Environment.TickCount + SlotSyncRetryDelayMs);
                return;
            }

            _slotSyncRetryAtMs = 0;
            SimHub.Logging.Current.Info(
                "[TF4ALL] light slots still unreadable; leaving them alone for this session, so the "
                + "rev lights and the wheel's screen stay off. This happens when the GAME is driving "
                + "the wheel's HID++ pipe, so it does not apply to iRacing, RaceRoom or Assetto Corsa "
                + "with the bridge, where the game's own force feedback is off. Elsewhere, starting "
                + "SimHub before the game avoids it.");
        }

        /// <summary>Once per SimHub tick: re-run a sync that could not read the
        /// wheel. Cheap and silent when nothing is owed.</summary>
        private void RetrySlotSyncIfUnread()
        {
            if (_slotSyncRetryAtMs == 0) return;
            // Wrap-safe: unchecked int subtraction stays correct across the
            // TickCount rollover, which a plain "now >= due" compare does not.
            if (unchecked(Environment.TickCount - _slotSyncRetryAtMs) < 0) return;
            if (MasterMode == TrueforceMasterMode.Off) return;
            if (_rpmLeds?.Channel == null) return;
            // One at a time. The reads take over a second when the pipe is busy,
            // which is longer than the retry interval, so without this a slow
            // attempt would have a second one stacked behind it.
            if (System.Threading.Interlocked.CompareExchange(ref _slotSyncRunning, 1, 0) != 0) return;

            _slotSyncRetriesLeft--;
            _slotSyncRetryAtMs = 0;   // the attempt itself re-arms below
            // OFF THE TICK THREAD, and this is the whole point of the change.
            //
            // These are five feature reads that each block to a 250 ms timeout
            // while the FFB stream saturates the HID++ pipe, so on SimHub's own
            // tick thread they froze it for over a second: SimHub flagged
            // "Abnormal Inactivity", the frozen tick read as a telemetry stall,
            // and the rev lights and screen were handed back then re-taken, which
            // is the flicker seen on 2026-09-05. The old answer was to refuse to
            // retry at all while the wheel was being driven, which made the retry
            // useless for the case it exists for: someone who starts the game
            // first and drives straight into a session never offers an idle
            // moment, the budget expires, and StageSlot has no slot it dares
            // borrow, so there is no LED or OLED control for the whole session.
            //
            // On a worker the reads can fail as often as they like and cost
            // nothing but their own thread. That is what lets the idle-only gate
            // go (owner, 2026-09-12).
            System.Threading.Tasks.Task.Run(() =>
            {
                try
                {
                    // Drop the cached map so this genuinely re-reads the wheel
                    // rather than answering from whatever armed the retry.
                    InvalidateSlotProgrammedCache();
                    string msg;
                    SyncSlotsToWheel(out msg);   // re-arms or stands down via NoteSlotSyncOutcome
                }
                catch (Exception ex)
                {
                    // The pattern list is also reachable from the settings UI, so
                    // a user editing it at the exact moment this fires can throw.
                    // Re-arm and let the next attempt pick it up.
                    _slotSyncRetryAtMs = unchecked(Environment.TickCount + SlotSyncRetryDelayMs);
                    SimHub.Logging.Current.Warn("[TF4ALL] slot-sync retry failed: " + ex.Message);
                }
                finally
                {
                    System.Threading.Interlocked.Exchange(ref _slotSyncRunning, 0);
                }
            });
        }

        /// <summary>1 while a slot-sync retry is in flight on a worker.</summary>
        private int _slotSyncRunning;

        /// <summary>The level to write with when we put something on the strip
        /// deliberately. Driving, keep the live rev level: the bar IS the display
        /// and overriding it fights the telemetry. Parked, light the whole strip,
        /// or the pick lands correctly and looks like it failed.
        ///
        /// One rule, in one place. The editor used to pass a full bar and the
        /// cycle the live level, which is exactly why clicking a pattern lit up
        /// and cycling to the same pattern did not.</summary>
        /// <summary>How long a lit strip stays up after an EDIT before going out.
        /// Long: the user is working on that pattern, each change re-arms it, and
        /// a bar that drops out between color picks is the thing they are trying
        /// to look at going away.</summary>
        private const int ShowHoldMs = 8000;

        /// <summary>How long a lit strip stays up after a PICK. Much shorter than
        /// an edit's hold, because picking is a glance and not a session: the
        /// sweep has already shown the pattern and its fill, and holding the full
        /// bar for another eight seconds afterwards reads as the wheel being
        /// stuck rather than as an answer.
        ///
        /// A second is the glance (owner, 2026-09-08). The fill itself already
        /// runs about two seconds, so the bar has been in front of the user the
        /// whole time it was rising; this is the beat at the top, not the look.
        ///
        /// Not zero. Ending dark would mean a pick shows nothing at the moment it
        /// finishes, which is the whole reason someone pressed.</summary>
        private const int PickHoldMs = 1000;

        private int ShowLevel =>
            (_rpmLeds?.IsDriving ?? false) ? -1 : WheelLedChannel.LedCount;

        /// <summary>Ask this wheel whether it implements the per-slot color
        /// feature, and what it currently holds. READ-ONLY: nothing is written to
        /// a slot and no effect is selected. Answers the one question blocking
        /// every color and layout feature, which mescon could only verify on an
        /// RS50.</summary>
        public string ProbeLedSlotFeature()
        {
            var ch = _rpmLeds?.Channel;
            if (ch == null) return "Rev-light channel not created (no supported wheel detected).";
            // Read-only in intent, but it opens the channel itself and sends five
            // HID++ queries, so it is still wheel traffic and off means off.
            if (MasterMode == TrueforceMasterMode.Off)
                return "The plugin is switched off, so the wheel was not probed.";
            try { return ch.ProbeSlotFeature(); }
            catch (Exception ex) { return "Slot probe failed: " + ex.Message; }
        }

        /// <summary>Car-load edge: put THIS car's own colors and fill direction
        /// into the lent slot, so the wheel matches the car's dash without anyone
        /// touching a setting.
        ///
        /// Deliberately quiet about failure. This fires unattended on every car
        /// change, so a car with no published data, no lent slot, or a wheel that
        /// will not answer must simply leave the lights exactly as they are. The
        /// previous pattern stays, which is the right outcome: it is the user's
        /// own, or the last car's, and either beats blanking the strip.
        ///
        /// Runs on a background task off the telemetry thread because a slot write
        /// is several HID++ reports with reply waits.</summary>
        private void ApplyCarColorsOnLoad(string game, string carId)
        {
            if (string.IsNullOrEmpty(carId)) return;

            // A pattern the user pinned to THIS car is applied by the car-load
            // edge, which runs before this. Nothing to do here but stand down;
            // applying the sticky pattern as well would fight it for the slot.
            if (HasExplicitCarLightChoice())
            {
                _autoAppliedColors = false;
                // Said out loud. This returned silently, and a pinned pattern
                // then looks exactly like the feature being broken: the car's
                // data is read and logged, and nothing reaches the wheel.
                SimHub.Logging.Current.Info(
                    $"[TF4ALL] car colors stood down for {carId}: a pattern is pinned to this car. "
                    + "Pick \"Auto (this car's own colors)\" to hand it back.");
                return;
            }

            // ONE switch. There used to be a second flag here that only the
            // checkbox's change handler ever set, so a settings file where the two
            // disagreed (restored from a backup, or written by a build before the
            // handler slaved them) gave a ticked box that did nothing until it was
            // toggled off and on. Reading the flag the control actually drives
            // makes that state impossible rather than merely unlikely.
            // The car's OWN dash colours first, where the game hands them to
            // us. Same ranking as the fill thresholds and for the same reason:
            // this is the car being driven, not a reading of it.
            // A fixed strip has no slot to put them in. StageSlot would answer
            // that eventually, but only after a round of slot reads that cannot
            // succeed, once per car load; and the setting that gets us here is
            // global, so a G PRO owner who ticked the box and then plugged in a
            // G923 (or let G HUB put their G PRO in G923 mode) arrives here on
            // every car. Ask the wheel first.
            byte[] acCarColors = WheelHasFixedLightPattern ? null : AcCarColorsForLighting();
            bool haveAcColors = acCarColors != null;
            bool haveData = haveAcColors
                         || (LovelyLightingEnabled && !WheelHasFixedLightPattern && _lovelyCar != null);

            if (!haveData)
            {
                // Nothing to say about this car.
                //
                // Only put the user's own pattern back if WE were the ones who
                // moved it, i.e. a previous car's colors are still showing.
                // Restoring unconditionally meant that in a game the dataset does
                // not cover at all (every Forza title), each car change rewrote a
                // slot and switched the wheel, for no reason and without anyone
                // asking. Leaving the lights alone is the correct answer when we
                // have nothing to contribute.
                if (_autoAppliedColors)
                {
                    _autoAppliedColors = false;
                    ApplyStickyPattern();
                }
                return;
            }

            Task.Run(() =>
            {
                try
                {
                    // Only act on the car that is STILL active: a background
                    // refresh or a quick car switch must not paint the wrong car's
                    // colors onto the wheel.
                    if (!string.Equals(_activeGame, game, StringComparison.Ordinal)
                        || !string.Equals(_activeCarId, carId, StringComparison.Ordinal)) return;

                    if (haveAcColors)
                    {
                        ApplyAcCarColors(acCarColors, carId);
                        return;
                    }

                    var car = _lovelyCar;
                    if (car == null) return;

                    var ramp = car.RampForGear("1") ?? car.HighestForwardGear();
                    var profile = LovelyLightMath.BuildProfile(car, ramp, WheelLedChannel.LedCount);

                    var rgb = new byte[WheelLedChannel.LedCount * 3];
                    for (int i = 0; i < WheelLedChannel.LedCount && i < profile.Colors.Length; i++)
                    {
                        rgb[i * 3 + 0] = profile.Colors[i].R;
                        rgb[i * 3 + 1] = profile.Colors[i].G;
                        rgb[i * 3 + 2] = profile.Colors[i].B;
                    }

                    // No stage: the slots would not read, so borrowing one would
                    // overwrite a pattern with nothing standing behind it. The
                    // car's colors are not worth that; leave the rim alone.
                    int stage = StageSlot();
                    if (stage == NoStageSlot)
                    {
                        SimHub.Logging.Current.Info(
                            "[TF4ALL] car colors not applied: " + NoStageSlotMessage);
                        return;
                    }

                    string msg;
                    // ALWAYS trimmed: no rawColors here, deliberately. These are
                    // upstream sRGB colors describing the real car, not bytes
                    // anyone tuned against this wheel, so they need the same
                    // correction as anything picked on screen.
                    bool ok = BorrowSlot(new WheelLedChannel.WheelLedSlot
                    {
                        Slot = (byte)stage,
                        DirectionWire = profile.DirectionWire,
                        Rgb = rgb,
                    }, out msg,
                       displayLevel: -1,                       // keep the live rev level
                       slotName: car.CarName ?? carId);        // the base's menu names the car

                    // Remember that the lights are OURS now, so the next car
                    // without data knows to put the user's pattern back. Set only
                    // on a write that landed.
                    if (ok)
                    {
                        _autoAppliedColors = true;
                        // CurrentId means "the library pattern currently on the
                        // wheel", and after this write there is not one. Leaving
                        // it pointing at the pattern we just painted over made
                        // ApplyStickyPattern's "already showing" shortcut fire on
                        // the NEXT car: it compared the sticky id against a stale
                        // CurrentId, matched, and returned without writing, so a
                        // car the dataset knows nothing about kept the previous
                        // car's colors instead of restoring the user's pick.
                        LightPatterns.CurrentId = null;
                        LibraryPatternShowing = false;
                    }

                    // The dash mirrors the car's colors whether or not the wheel
                    // write landed: on screen there is nothing to refuse us.
                    PublishDashLightProfile(rgb, profile.Layout, car.CarName ?? carId);

                    SimHub.Logging.Current.Info(ok
                        ? $"[TF4ALL] car colors applied for {carId}: {profile.Layout}, "
                          + (profile.UsedCarColors ? "the car's own colors" : "standard ramp")
                        : "[TF4ALL] car colors not applied: " + msg);
                }
                catch (Exception ex)
                {
                    SimHub.Logging.Current.Warn("[TF4ALL] car-color apply failed: " + ex.Message);
                }
            });
        }

        /// <summary>Paint the wheel with the car's OWN dash-LED colours.
        ///
        /// Cars carry fewer LEDs than the rim has steps (five is common against
        /// ten here), so each car LED covers a run of rim LEDs. The same
        /// proportional mapping the fill uses, so a colour change and the step
        /// that lights it land on the same LED rather than a step apart.</summary>
        private void ApplyAcCarColors(byte[] carRgb, string carId)
        {
            int strip = WheelLedChannel.LedCount;
            var rgb = AcCarStripColors(carRgb, strip);

            // Same refusal as the published-dataset path: no readable slot map
            // means no slot may be borrowed.
            int stage = StageSlot();
            if (stage == NoStageSlot)
            {
                SimHub.Logging.Current.Info(
                    "[TF4ALL] car colors not applied: " + NoStageSlotMessage);
                return;
            }

            string msg;
            // Trimmed, not raw: these describe a car on screen, so they need
            // the same correction as any other upstream sRGB colour. Same
            // reasoning as the published-dataset path above.
            bool ok = BorrowSlot(new WheelLedChannel.WheelLedSlot
            {
                Slot = (byte)stage,
                DirectionWire = 3,          // left to right, the order cars number LED_0..n in
                Rgb = rgb,
            }, out msg,
               displayLevel: -1,            // keep the live rev level
               slotName: carId);

            if (ok)
            {
                _autoAppliedColors = true;
                LightPatterns.CurrentId = null;
                LibraryPatternShowing = false;
            }

            PublishDashLightProfile(rgb, LightDirection.LeftToRight, carId);
            SimHub.Logging.Current.Info(ok
                ? $"[TF4ALL] car colors applied for {carId}: the car's own dash LED colors."
                : "[TF4ALL] car colors not applied: " + msg);
        }

        /// <summary>Spread the car's LED colours across the rim's steps. Strip
        /// LED i takes car LED floor(i * n / strip), so five car LEDs on a
        /// ten-step rim colour two steps each.</summary>
        private static byte[] AcCarStripColors(byte[] carRgb, int strip)
        {
            int n = carRgb.Length / 3;
            var rgb = new byte[strip * 3];
            if (n <= 0) return rgb;
            for (int i = 0; i < strip; i++)
            {
                int src = (int)((long)i * n / strip);
                if (src >= n) src = n - 1;
                rgb[i * 3 + 0] = carRgb[src * 3 + 0];
                rgb[i * 3 + 1] = carRgb[src * 3 + 1];
                rgb[i * 3 + 2] = carRgb[src * 3 + 2];
            }
            return rgb;
        }

        // ---- LIGHTSYNC slot borrow / restore ----

        /// <summary>Where the user's light-pattern library lives: INSIDE the
        /// user preset folder, which is the folder the backup bundler walks.
        ///
        /// It used to sit in a sibling called "TrueforceForAll-Library" under a
        /// comment claiming a folder backup carried it. It did not: that name is
        /// the LEGACY preset folder, migrated to TrueforceForAll\user by the
        /// one-time restructure, and the bundler walks the new one. So a user's
        /// whole pattern library was absent from backup, export, restore and
        /// cloud sync, while CarLightPattern (car to pattern id) travelled
        /// without it, which would land a second PC with per-car assignments
        /// pointing at patterns it does not have.
        ///
        /// Here it is carried with no backup-side change at all: Bundle() globs
        /// *.json under this folder recursively and restores it verbatim.
        /// BuiltinPresetStore.IsReservedMetadataFile keeps the preset scan from
        /// reading it as a game preset called "light-patterns".</summary>
        public string LightPatternFilePath => Path.Combine(
            UserPresets.CurrentFolder ?? UserPresets.DefaultFolder, "light-patterns.json");

        /// <summary>The pre-0.3.0 home. Kept only so the migration below can
        /// find a library that is already sitting there.</summary>
        private static string LegacyLightPatternFilePath => Path.Combine(
            TfPaths.CommonRoot, "TrueforceForAll-Library", "light-patterns.json");

        /// <summary>Carry an existing library across to the new home, once.
        ///
        /// Only ever writes into an EMPTY destination, so a library already at
        /// the new path always wins and re-running this can never overwrite it.
        /// The source is left in place: it costs a few KB, and it means a user
        /// who rolls back still has their patterns where the old build looks.</summary>
        private void MigrateLightPatternsIfNeeded()
        {
            try
            {
                string dest = LightPatternFilePath;
                if (string.IsNullOrEmpty(dest) || File.Exists(dest)) return;
                string src = LegacyLightPatternFilePath;
                if (!File.Exists(src)) return;
                string parent = Path.GetDirectoryName(dest);
                if (!string.IsNullOrEmpty(parent)) Directory.CreateDirectory(parent);
                File.Copy(src, dest);
                SimHub.Logging.Current.Info(
                    "[TF4ALL] Light-pattern library copied into the preset folder so backups carry it.");
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Warn("[TF4ALL] Light-pattern migration failed: " + ex.Message);
            }
        }

        // The library lives HERE rather than in the settings UI because a bound
        // button has to cycle it with no window open. The editor reads and writes
        // the same instance.
        private LightPatternStore _lightPatternStore;
        private LightPatternLibrary _lightPatterns;
        private readonly object _lightPatternGate = new object();

        public LightPatternStore LightPatternStoreInstance
        {
            get
            {
                lock (_lightPatternGate)
                {
                    // The user library is per-account, so signing in mid-session
                    // moves this file. A store built before that keeps the old path
                    // and would write the library into the account the user just
                    // left, where nothing reads it again.
                    if (_lightPatternStore != null
                        && !string.Equals(_lightPatternStore.FilePath, LightPatternFilePath,
                                          StringComparison.OrdinalIgnoreCase))
                    {
                        _lightPatternStore = null;
                        _lightPatterns = null;
                    }
                    if (_lightPatternStore == null)
                    {
                        // Runs before the first read, which is the only moment
                        // that matters: the store is created once and the file
                        // is loaded through it.
                        MigrateLightPatternsIfNeeded();
                        _lightPatternStore = new LightPatternStore(LightPatternFilePath)
                        { Log = m => SimHub.Logging.Current.Info(m) };
                    }
                    return _lightPatternStore;
                }
            }
        }

        public LightPatternLibrary LightPatterns
        {
            get
            {
                lock (_lightPatternGate)
                {
                    if (_lightPatterns == null)
                    {
                        _lightPatterns = LightPatternStoreInstance.Load();
                        if (LightPatternStore.AddBuiltins(_lightPatterns) > 0)
                            LightPatternStoreInstance.Save(_lightPatterns);
                    }
                    return _lightPatterns;
                }
            }
        }

        public void SaveLightPatterns() => LightPatternStoreInstance.Save(LightPatterns);

        /// <summary>Drop the cached light-pattern library so the next access reads
        /// the file again.
        ///
        /// Every path that REPLACES light-patterns.json underneath a running
        /// session has to call this. The library is held in memory and written back
        /// whole, so a stale copy does not merely show the wrong patterns: the next
        /// save puts it back over whatever was just restored, and the restore is
        /// undone without anything reporting a failure.</summary>
        private void InvalidateLightPatternCache(string why)
        {
            lock (_lightPatternGate)
            {
                _lightPatterns = null;
                _lightPatternStore = null;
            }
            SimHub.Logging.Current.Info("[TF4ALL] Light-pattern library reloaded from disk (" + why + ").");
        }

        /// <summary>The slot to borrow, worked out rather than asked for.
        ///
        /// In order: a slot already on loan per the on-disk backup (this session
        /// or one that died holding it), then a slot the user pinned, then the
        /// first slot that has never been programmed, and only when all five are
        /// in use, the last slot.
        ///
        /// It does NOT consider what the wheel is currently displaying. An
        /// earlier version of this comment said it did, and three pieces of
        /// user-facing copy were written from the comment rather than the body:
        /// the light-patterns guide, the LightsyncDynamicSlot doc, and the
        /// LIGHTSYNC tab's own note all told users a rule the code never had.
        /// The current selection IS known (RpmLedController.KnownSelection) but
        /// is used only to GIVE a slot back in ReleaseBorrowIfWheelMovedAway.
        ///
        /// Always a real slot, never "none": asking to show a pattern IS the
        /// permission to put it somewhere, and the contents are backed up and
        /// restored either way.</summary>
        public int StageSlot()
        {
            if (_stageSlot >= 0) return _stageSlot;

            // An unreturned backup means a slot is already on loan, from earlier
            // in this session or from one that died holding it. THAT is the stage:
            // taking a different one would strand our colors in theirs and hold
            // two slots at once.
            int held = HeldBorrowedSlot();
            if (held >= 0) return _stageSlot = held;

            // The user may name one outright. Almost nobody does.
            int pinned = Settings?.LightsyncDynamicSlot ?? -1;
            if (pinned >= 0 && pinned < WheelLedChannel.CustomSlotCount) return _stageSlot = pinned;

            // Otherwise the first slot they have never programmed. An all-black
            // slot is a factory slot nobody has touched, so borrowing it costs
            // them nothing, where taking one they built means overwriting real
            // work (saved and restored, but still a change they did not ask for).
            int spare = FirstUnprogrammedSlot();
            if (spare >= 0) return _stageSlot = spare;

            // Every slot is in use, so one has to be borrowed: take the last.
            // Latching is safe here because the map was actually read.
            if (_slotProgrammed != null) return _stageSlot = WheelLedChannel.CustomSlotCount - 1;

            // The map came from five FAILED reads, which looks identical to
            // "all five are in use" and is not the same thing at all. Borrowing
            // on that basis writes over a slot we never managed to look at, so
            // the backup that is supposed to hand it back holds nothing and the
            // user loses a pattern for good. Refuse instead, and let the caller
            // say so. The reads are retried (see RetrySlotSyncIfUnread), so a
            // session that started while the game already held the wheel's
            // HID++ pipe recovers on its own.
            return NoStageSlot;
        }

        /// <summary>What <see cref="StageSlot"/> returns when the wheel's slots
        /// could not be read, so no slot may be borrowed yet. Callers must check
        /// for it: casting it to a byte would address slot 255.</summary>
        public const int NoStageSlot = -1;

        /// <summary>The one message every caller shows when there is no stage.
        /// One wording, because the user meets this from six different buttons
        /// and it is the same situation each time.</summary>
        internal const string NoStageSlotMessage =
            "Could not read the wheel's light slots, so nothing was written. "
            + "This usually clears on its own within a minute; starting SimHub "
            + "before the game avoids it.";

        /// <summary>The slot on loan for this session, or -1 before one has been
        /// chosen. Latched: see <see cref="StageSlot"/>.</summary>
        private int _stageSlot = -1;

        /// <summary>Forget the chosen stage so the next request picks again. Only
        /// for changes that genuinely invalidate it, i.e. the user pinning a
        /// different slot. Callers must release any live borrow FIRST, or the
        /// backup would be left pointing at a slot nothing considers the stage
        /// any more.</summary>
        internal void ResetStageSlot() { _stageSlot = -1; }

        /// <summary>The first custom slot that has never been programmed (every
        /// LED black), or -1 if they are all in use. Only consulted on the rare
        /// fallback path, since it costs one read per slot.</summary>
        /// <summary>Which custom slots hold something. Cached, because a rim
        /// button must not wait on five HID++ round trips.
        ///
        /// The stage slot's answer here is meaningless while it is on loan, since
        /// what it holds is ours. Nothing asks: the cycle leaves the stage out of
        /// its slot list entirely, so the answer never has to be un-borrowed
        /// first.</summary>
        private bool[] _slotProgrammed;

        internal void InvalidateSlotProgrammedCache() { _slotProgrammed = null; }

        private bool[] SlotProgrammedMap()
        {
            var cached = _slotProgrammed;
            if (cached != null) return cached;

            var map = new bool[WheelLedChannel.CustomSlotCount];
            bool unreadable = false;

            for (int slot = 0; slot < map.Length; slot++)
            {
                byte[] rgb = ReadSlot(slot)?.Rgb;

                // Unreadable counts as IN USE. Never hand out a slot we could not
                // look at: that is exactly how someone's work gets written over
                // with no backup standing behind it.
                if (rgb == null) { map[slot] = true; unreadable = true; continue; }
                bool blank = true;
                foreach (byte b in rgb) if (b != 0) { blank = false; break; }
                map[slot] = !blank;
            }

            // Only remember an answer we actually got. A map built while the
            // channel was down says "all five in use" for the wrong reason, and
            // caching that would fix the cycle's running order to a guess for
            // the rest of the session.
            if (!unreadable) _slotProgrammed = map;
            return map;
        }

        private int FirstUnprogrammedSlot()
        {
            var map = SlotProgrammedMap();
            for (int slot = 0; slot < map.Length; slot++)
                if (!map[slot]) return slot;
            return -1;
        }

        /// <summary>Hand back any borrowed slot, because the user has chosen
        /// something REAL on the wheel: one of its built-in sweeps, or one of its
        /// own stored slots.
        ///
        /// There is no permanent slot of ours. We only ever occupy one while a
        /// pattern that is not on the wheel is being shown, so the moment the user
        /// picks something that IS on the wheel, the borrow has served its purpose
        /// and their slot goes back to them. At most one slot is ever borrowed,
        /// and only for as long as it is doing something.</summary>
        /// <summary>Notice when the user has moved the wheel off the slot we
        /// borrowed, using the base's own menu rather than the plugin, and give it
        /// back. Otherwise we would sit on their slot indefinitely while showing
        /// nothing, and keep writing into a slot they are no longer looking at.
        ///
        /// Cheap enough to call per frame: the common case is no borrow at all,
        /// which is one field read.</summary>
        private void ReleaseBorrowIfWheelMovedAway()
        {
            if (_rpmLeds == null) return;
            int showing = _rpmLeds.KnownSelection;
            if (showing < 1) return;                 // never read: say nothing

            if (_borrowedSlotCache < 0) return;      // nothing borrowed
            if (showing == 5 + _borrowedSlotCache) return;   // still on ours

            SimHub.Logging.Current.Info(
                $"[TF4ALL] wheel moved to effect {showing}; giving CUSTOM {_borrowedSlotCache + 1} back");
            ReleaseBorrowedSlot();
        }

        /// <summary>Which slot we believe is borrowed, kept in memory so the
        /// per-frame check above never touches the disk. Set when a borrow is
        /// taken, cleared when it is returned.</summary>
        private int _borrowedSlotCache = -1;

        /// <summary>Bumped every time WE change what the wheel is showing. The
        /// settings UI watches it so a pattern changed from a rim button moves the
        /// picker and the library list too, instead of them sitting on a selection
        /// that stopped being true the moment the button was pressed.
        ///
        /// A counter rather than an event: the UI already ticks, and an event
        /// raised from a background task would have to be marshalled onto the
        /// dispatcher by every subscriber.</summary>
        public int LightSelectionGeneration => _lightSelectionGen;
        private int _lightSelectionGen;

        private void NoteLightSelectionChanged()
            => System.Threading.Interlocked.Increment(ref _lightSelectionGen);

        /// <summary>The slot currently on loan, or -1. Exposed so the editor can
        /// leave it out when reconciling which pattern lives where: while it is
        /// lent, what that slot holds is ours and says nothing about the user's
        /// arrangement.</summary>
        public int BorrowedSlot => _borrowedSlotCache;

        /// <summary>Whether what the wheel is showing is one of OUR library
        /// patterns standing in the stage slot, as opposed to something the wheel
        /// itself holds. In memory and authoritative: the cycle used to answer
        /// this by loading the backup file from disk on every single press.
        ///
        /// Set where the showing happens rather than derived from "is a slot
        /// backed up", because that is also true while the user edits one of
        /// their OWN slots, and treating that as ours would let a cycle press
        /// restore their edit out from under them.</summary>
        private bool LibraryPatternShowing { get; set; }

        /// <summary>Direction value for one of the wheel's four built-in sweeps,
        /// given its 1-based effect number. The effect IS the direction, but the
        /// two lists are numbered differently, which is why this is written out
        /// rather than computed: effect 1 is inside-out (direction 1), 2 outside-in
        /// (2), 3 right-to-left (4), 4 left-to-right (3).</summary>
        internal static byte BuiltinEffectDirectionWire(int effect)
        {
            switch (effect)
            {
                case 1: return 1;   // Inside out
                case 2: return 2;   // Outside in
                case 3: return 4;   // Right to left
                default: return 3;  // Left to right
            }
        }

        /// <summary>The device's 1..4 direction value back to our enum. The two
        /// are numbered differently, so this is written out rather than cast.</summary>
        internal static LightDirection DirectionFromWire(byte wire)
        {
            switch (wire)
            {
                case 1:  return LightDirection.InsideOut;
                case 2:  return LightDirection.OutsideIn;
                case 4:  return LightDirection.RightToLeft;
                default: return LightDirection.LeftToRight;
            }
        }

        public void ReleaseBorrowedSlot()
        {
            LibraryPatternShowing = false;
            NoteLightSelectionChanged();
            int held = HeldBorrowedSlot();
            if (held < 0) return;
            string msg;
            if (RestoreSlot(held, out msg))
                SimHub.Logging.Current.Info($"[TF4ALL] gave CUSTOM {held + 1} back: {msg}");
        }

        /// <summary>The slot we hold an unreturned backup for, or -1. That IS the
        /// definition of "currently borrowed".</summary>
        private int HeldBorrowedSlot()
        {
            try
            {
                var map = SlotBackups.Load();
                foreach (var kv in map)
                    if (kv.Value != null && !kv.Value.Restored && !kv.Value.Blanked
                        && kv.Value.Slot < WheelLedChannel.CustomSlotCount)
                        return kv.Value.Slot;
            }
            catch { }
            return -1;
        }

        /// <summary>Tag for the "let the car's own data decide" choice. Not a
        /// pattern id: it means the absence of an override, which is why choosing
        /// it CLEARS the per-car entries rather than storing something.</summary>
        public const string AutoPatternTag = "*auto*";

        /// <summary>True when the user has pinned a specific pattern or effect to
        /// the active car. Their explicit choice outranks the database, so the
        /// automatic per-car apply stands down when this is true. Without this the
        /// two would both fire at car load and fight over the slot.</summary>
        public bool HasExplicitCarLightChoice()
        {
            var s = Settings;
            if (s == null || string.IsNullOrEmpty(_activeGame) || string.IsNullOrEmpty(_activeCarId)) return false;
            string key = _activeGame + "/" + _activeCarId;
            if (s.CarLightPattern != null && s.CarLightPattern.ContainsKey(key)) return true;
            if (s.CarRevLightEffect != null
                && s.CarRevLightEffect.TryGetValue(key, out int e) && e > 0) return true;
            return false;
        }

        /// <summary>Whether the active car would light itself if nothing were
        /// pinned. Drives the "Auto" entry in the pickers.
        ///
        /// TWO sources now: the published dataset, and the car's OWN dash data
        /// where the game hands it over. Auto is one idea to the user ("let this
        /// car pick"), so both feed the same entry rather than growing a second
        /// one that means almost the same thing.</summary>
        public bool AutoCarColorsAvailable()
            => (LovelyLightingEnabled && _lovelyCar != null) || AcCarColorsForLighting() != null;

        /// <summary>The active car's own dash-LED colours, if it gave any and the
        /// user has allowed per-car data to drive the lights.
        ///
        /// Deliberately NOT behind the community switch that gates the published
        /// dataset: this is the game's own file for the car being driven, nothing
        /// to do with the backend. It IS behind the lights opt-in, because that
        /// switch exists to ask before we borrow one of the user's five wheel
        /// slots, and this borrows one exactly the same way.</summary>
        private byte[] AcCarColorsForLighting()
        {
            if (Settings?.LovelyCarDataEnabled != true) return null;
            var c = (_telemetrySource as AcSharedMemoryTelemetrySource)?.CspAcLedStepColors;
            return c != null && c.Length >= 3 ? c : null;
        }

        /// <summary>Hand this car back to its own data by clearing any pinned
        /// choice, then apply it now so the change is visible immediately rather
        /// than at the next car load.</summary>
        public bool UseAutoForActiveCar()
        {
            var s = Settings;
            if (s == null || string.IsNullOrEmpty(_activeGame) || string.IsNullOrEmpty(_activeCarId)) return false;
            string key = _activeGame + "/" + _activeCarId;
            bool changed = (s.CarLightPattern?.Remove(key) ?? false)
                         | (s.CarRevLightEffect?.Remove(key) ?? false);
            if (changed) { try { PersistSettingsCore(); } catch { } }
            ApplyCarColorsOnLoad(_activeGame, _activeCarId);
            return true;
        }

        /// <summary>Put the user's own chosen pattern back on the wheel.
        ///
        /// Their pick is meant to STICK: choosing a pattern is a standing choice,
        /// not a one-car one. Without this, driving a car the database knows and
        /// then one it does not would leave the first car's colors on the wheel,
        /// which reads as the plugin having wandered off on its own.
        ///
        /// Silent and best-effort: nothing chosen yet means leave the wheel be.</summary>
        /// <summary>True while the lights are showing a CAR'S colors that we
        /// applied, rather than whatever the user chose. The only thing that
        /// justifies moving them back on the next car.</summary>
        private bool _autoAppliedColors;

        /// <summary>Whether the car's OWN colors are what the wheel is showing
        /// right now, as opposed to something the user has since picked.
        ///
        /// The pickers used to display "Auto" whenever a car had data and nothing
        /// was pinned to it, which is a statement about the CAR rather than about
        /// the wheel. Cycling with a rim button then changed the lights while the
        /// dropdown went on insisting they were automatic.</summary>
        public bool AutoColorsShowing => _autoAppliedColors;

        private void ApplyStickyPattern()
        {
            var lib = LightPatterns;
            string id = lib?.StickyId;
            if (string.IsNullOrEmpty(id)) return;
            if (string.Equals(lib.CurrentId, id, StringComparison.Ordinal)) return;   // already showing

            var p = lib.Patterns.FirstOrDefault(x => x.Id == id);
            if (p == null) return;

            Task.Run(() =>
            {
                try
                {
                    string msg;
                    if (!ApplyLightPattern(p, out msg))
                        SimHub.Logging.Current.Info("[TF4ALL] sticky pattern not applied: " + msg);
                }
                catch { }
            });
        }

        /// <summary>The library pattern remembered for the active car, or null.</summary>
        public LightPattern GetCarRememberedLightPattern()
        {
            var s = Settings;
            if (s?.CarLightPattern == null) return null;
            if (string.IsNullOrEmpty(_activeGame) || string.IsNullOrEmpty(_activeCarId)) return null;
            string id;
            if (!s.CarLightPattern.TryGetValue(_activeGame + "/" + _activeCarId, out id)) return null;
            return LightPatterns.Patterns.FirstOrDefault(p => p.Id == id);
        }

        /// <summary>Remember one of our patterns for the active car. Clears any
        /// remembered wheel EFFECT for the same car, because two remembered
        /// answers for one question is how a car ends up flickering between them
        /// at load.</summary>
        public bool RememberLightPatternForActiveCar(string patternId)
        {
            var s = Settings;
            if (s == null || string.IsNullOrEmpty(_activeGame) || string.IsNullOrEmpty(_activeCarId)) return false;
            if (string.IsNullOrEmpty(patternId)) return false;

            string key = _activeGame + "/" + _activeCarId;
            if (s.CarLightPattern == null) s.CarLightPattern = new Dictionary<string, string>();
            s.CarLightPattern[key] = patternId;
            s.CarRevLightEffect?.Remove(key);
            try { PersistSettingsCore(); } catch { }
            return true;
        }

        public bool ForgetLightPatternForActiveCar()
        {
            var s = Settings;
            if (s?.CarLightPattern == null) return false;
            if (string.IsNullOrEmpty(_activeGame) || string.IsNullOrEmpty(_activeCarId)) return false;
            if (!s.CarLightPattern.Remove(_activeGame + "/" + _activeCarId)) return false;
            try { PersistSettingsCore(); } catch { }
            return true;
        }

        /// <summary>Write a library pattern into the lent slot and mark it as the
        /// one showing. The single path everything uses to put one of OUR
        /// patterns on the wheel, so cycling, clicking and the per-car apply all
        /// behave identically.</summary>
        /// <param name="userChose">True when this came from the user picking or
        /// cycling, which makes it their standing choice. False for automatic
        /// applies, which must not redefine what they picked.</param>
        /// <param name="sweep">Play the fill animation as well as lighting the
        /// bar. Right for a deliberate pick, wrong for a live color edit, where
        /// restarting the sweep on every slider tick would flicker instead of
        /// showing the color the user is choosing.</param>
        public bool ApplyLightPattern(LightPattern pattern, out string message,
                                      bool userChose = false, bool sweep = true)
        {
            message = null;
            if (pattern == null) { message = "No pattern."; return false; }
            int slot = StageSlot();
            if (slot == NoStageSlot) { message = NoStageSlotMessage; return false; }

            byte[] rgb = pattern.Rgb();
            if (rgb == null || rgb.Length < WheelLedChannel.LedCount * 3)
            {
                message = "That pattern's colors are unreadable.";
                return false;
            }

            // One decision for the write and its follow-up; see WriteOwnSlot for
            // why the display level has to follow it.
            bool show = MasterMode == TrueforceMasterMode.Normal && PreviewSweepAllowed;
            bool ok = BorrowSlot(new WheelLedChannel.WheelLedSlot
            {
                Slot = (byte)slot,
                DirectionWire = pattern.DirectionWire,
                Rgb = rgb,
            }, out message,
               displayLevel: show ? ShowLevel : StripLevelFromWire(),
               slotName: pattern.Name,
               rawColors: pattern.TrimExempt);

            if (ok)
            {
                LightPatterns.CurrentId = pattern.Id;
                if (userChose)
                {
                    LightPatterns.StickyId = pattern.Id;
                    MaybeAutoRememberForCar(pattern.Id, 0);
                }
                SaveLightPatterns();
                PublishDashLightProfile(rgb, DirectionFromWire(pattern.DirectionWire), pattern.Name);
                LibraryPatternShowing = true;
                // A deliberate pick replaces the car's own colors, so they are no
                // longer what is on the wheel and nothing should claim they are.
                _autoAppliedColors = false;
                NoteLightSelectionChanged();
                // Sweeping is part of showing something, not an extra step every
                // caller has to remember. Forgetting it here is what made cycled
                // patterns invisible while parked. An edit does not sweep, but it
                // still lights the bar and re-arms the fade, so the strip stays up
                // for as long as the user keeps working on it.
                // Both of these DRIVE the bar, and only full mode may. Passing
                // sweep:false was not enough on its own: HoldLit re-arms the very
                // keepalive the slot write had just stopped, then holds the bar lit
                // for eight seconds and ramps it back down, which is around nine
                // seconds of level traffic per car load on the endpoint the game's
                // force feedback shares.
                // Same decision the write was made with. Both branches stand
                // down while a game's own force is live: the sweep also checks
                // for itself (it has other callers), and HoldLit is the same
                // kind of traffic.
                if (show)
                {
                    if (sweep) PreviewRevLightPattern();
                    else _rpmLeds.HoldLit(WheelLedChannel.LedCount, ShowHoldMs);
                }
            }
            return ok;
        }

        private LightSlotBackupStore _slotBackups;
        private LightSlotBackupStore SlotBackups => _slotBackups ?? (_slotBackups =
            new LightSlotBackupStore(Path.Combine(TfPaths.CommonRoot,
                "TrueforceForAll-Library", "lightsync-slot-backup.json"))
            { Log = m => SimHub.Logging.Current.Info(m) });

        /// <summary>Identity of the attached wheel, so a backup taken on one base
        /// is never written onto a different one.</summary>
        private string SlotWheelId => WheelStatus ?? "wheel";

        /// <summary>Read a stored slot, or null if it cannot be read. Used when
        /// lending a slot so the pattern already in it can be adopted rather than
        /// replaced.</summary>
        /// <summary>Make sure the HID++ channel is up before a lighting action.
        ///
        /// The channel normally opens on the first telemetry frame with the gate
        /// open, which means that parked in the settings panel with no game
        /// running it is CLOSED. Every slot read, slot write and effect select
        /// then fails quietly: the pick gets staged for later and the user sees
        /// nothing happen. The Test button has always forced it open for exactly
        /// this reason; anything the user drives from the panel needs the same.</summary>
        public bool EnsureLedChannelOpen()
        {
            var ch = _rpmLeds?.Channel;
            if (ch == null) return false;
            if (ch.IsReady) return true;
            try { return ch.OpenAndResolve(); }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Warn("[TF4ALL] LED channel open failed: " + ex.Message);
                return false;
            }
        }

        public WheelLedChannel.WheelLedSlot ReadSlot(int slot)
        {
            // A read is still a HID++ query on the endpoint the game's force shares,
            // and the settled contention model says any traffic there while force is
            // flowing cuts the force. The pattern editor reads all five slots on
            // every panel open, so this is not a rare path.
            if (MasterMode == TrueforceMasterMode.Off) return null;
            var ch = _rpmLeds?.Channel;
            if (ch == null) return null;
            try
            {
                WheelLedChannel.WheelLedSlot s;
                return ch.TryReadSlot(slot, out s) ? s : null;
            }
            catch { return null; }
        }

        /// <summary>Wheel LED brightness as a percentage, or -1 when the wheel
        /// does not offer it. Read-only, so it is safe to call whenever.</summary>
        public int ReadLedBrightness()
        {
            // Reading is harmless; OPENING to read is not, and this is called from
            // the pattern editor's ordinary refresh, so without this the gate on the
            // editor's own open bought nothing.
            if (MasterMode == TrueforceMasterMode.Off) return -1;
            if (!EnsureLedChannelOpen()) return -1;
            try { return _rpmLeds?.Channel?.TryReadBrightnessPercent() ?? -1; }
            catch { return -1; }
        }

        /// <summary>Set wheel LED brightness. Only ever called from the user
        /// moving the control: nothing writes this on load or shutdown.</summary>
        public bool WriteLedBrightness(int percent)
        {
            // Brightness is a DEVICE-level setting (HID++ 0x8040), not part of a
            // slot, so it never passed through BorrowSlot's gate. The LIGHTSYNC tab
            // stays live after a switch to off, and this slider would change the
            // user's wheel permanently in the mode that promises to leave their
            // lights exactly as they set them.
            if (MasterMode == TrueforceMasterMode.Off) return false;
            if (!EnsureLedChannelOpen()) return false;
            try { return _rpmLeds?.Channel?.TryWriteBrightnessPercent(percent) == true; }
            catch { return false; }
        }

        public string ReadSlotName(int slot)
        {
            // Same reasoning as ReadSlot: the pattern editor names all five slots on
            // every panel open, which is ten query and reply round trips on the
            // shared endpoint.
            if (MasterMode == TrueforceMasterMode.Off) return null;
            try { return _rpmLeds?.Channel?.TryReadSlotName(slot); }
            catch { return null; }
        }

        /// <summary>Name a slot as the wheel's own menu shows it. Capped at eight
        /// characters by the wire.</summary>
        public bool WriteSlotName(int slot, string name)
        {
            // Renaming a pattern in the editor writes the wheel directly. Same rule
            // as every other write: not while the plugin is off.
            if (MasterMode == TrueforceMasterMode.Off) return false;
            try { return _rpmLeds?.Channel?.TryWriteSlotName(slot, name) == true; }
            catch { return false; }
        }

        /// <summary>Write a pattern into ANY custom slot, not just the lent one.
        /// This is the user deliberately editing one of their own slots, so it is
        /// their intent rather than us borrowing, but it still takes a backup
        /// first so the original is recoverable.</summary>
        public bool WriteUserSlot(int slot, byte direction, byte[] rgb, out string message)
            => BorrowSlot(new WheelLedChannel.WheelLedSlot
               { Slot = (byte)slot, DirectionWire = direction, Rgb = rgb },
               out message, displayLevel: WheelLedChannel.LedCount);

        /// <summary>Take a backup of <paramref name="slot"/> if we do not already
        /// hold an unrestored one, then write <paramref name="want"/> into it.
        ///
        /// Order is the whole point: the original is read and COMMITTED TO DISK
        /// before the wheel is written. A crash between the two loses nothing; a
        /// crash after leaves a backup marked unrestored, which the next launch
        /// can act on.</summary>
        /// <param name="displayLevel">-1 keeps the current rev level; pass 10 to
        /// light the whole strip so a person can see what landed.</param>
        /// <param name="slotName">What to call the slot on the wheel while we are
        /// using it. The pattern's own name, so the base's menu reads as the thing
        /// being shown rather than as our branding.</param>
        /// <param name="permanent">The user means this write to STAY. No backup
        /// is taken and no restore is owed, and any loan already outstanding on
        /// that slot is settled rather than honoured, because handing back an old
        /// copy at shutdown would undo the change they just asked for. This is
        /// the whole difference between editing your own slot and lending one to
        /// the plugin.</param>
        /// <summary>The hex that a pattern's stored colors become on the wire
        /// once the LED color trim is applied.
        ///
        /// The library stores sRGB INTENT and the wheel holds that intent after
        /// trimming, so after calibration the two genuinely differ byte for
        /// byte, by design. Any code that compares what is on the wheel against
        /// what the library holds must therefore compare in THIS space, and
        /// must never try to divide the trim back out: division does not
        /// round-trip at 8 bits and would miss by a count or two. Three sites
        /// depend on this (SyncSlotsToWheel, AdoptSlotContentsAsPattern,
        /// LightPatternLibrary.AdoptWheelOrder); a fourth added later and left
        /// comparing raw hex would silently re-upload slots forever.</summary>
        /// <summary>The trim actually in force: the user's own numbers wherever
        /// they set them, the shipped tuning wherever they have not.
        ///
        /// Resolved at read rather than written to disk once, so retuning the
        /// shipped values later reaches everyone who never had an opinion, and
        /// never touches anyone who did. A stored 1.0 is a deliberate opt-out
        /// and stays.</summary>
        public void EffectiveLedTrim(out float r, out float g, out float b)
        {
            r = Settings?.LedTrimR ?? LedColorGain.ShippedR;
            g = Settings?.LedTrimG ?? LedColorGain.ShippedG;
            b = Settings?.LedTrimB ?? LedColorGain.ShippedB;
        }

        public string ToWireHex(byte[] intentRgb)
        {
            float r, g, b; EffectiveLedTrim(out r, out g, out b);
            return LightSlotBackupStore.ToHex(LedColorGain.Apply(intentRgb, r, g, b));
        }

        /// <summary>The hex a PATTERN becomes on the wire. An exempt pattern is
        /// already in the wheel's own space, so its wire form is its stored
        /// form. This is the ONLY place that decision is made, and every site
        /// that compares the wheel against the library must come through here.
        ///
        /// Normalised through ToHex rather than returning RgbHex directly:
        /// RgbHex is a hand-editable file field that may carry lowercase or
        /// stray whitespace, while ToHex always emits uppercase and FromHex
        /// returns null on anything malformed, so a corrupt entry matches
        /// nothing rather than matching by accident.</summary>
        public string ToWireHex(LightPattern p)
            => p == null ? string.Empty
             : p.TrimExempt ? LightSlotBackupStore.ToHex(p.Rgb())
             : ToWireHex(p.Rgb());

        /// <summary>The same answer as <see cref="ToWireHex(LightPattern)"/> but
        /// as bytes, for the identity checks that compare with a tolerance
        /// rather than as text.</summary>
        public byte[] ToWireBytes(LightPattern p)
        {
            if (p == null) return null;
            var rgb = p.Rgb();
            if (p.TrimExempt || rgb == null) return rgb;
            float r, g, b; EffectiveLedTrim(out r, out g, out b);
            return LedColorGain.Apply(rgb, r, g, b);
        }

        /// <param name="rawColors">The caller's colors are already in the
        /// wheel's own space (a pattern the user tuned by eye on the rim, or one
        /// imported out of the wheel's slots), so they go out untouched by the
        /// LED color trim. Anything that later compares this slot against that
        /// pattern must compare RAW too, which ToWireHex(LightPattern) handles
        /// as the single place that decision lives.</param>
        /// <summary>After a slot write in a mode that does not drive the bar, stop
        /// the keepalive the write just armed.
        ///
        /// A slot upload necessarily sets a level (the wheel renders nothing at 0,
        /// which is why the upload floors it), and setting a level arms a sender
        /// that then resends it every second for the rest of the session. In full
        /// mode that is exactly right. In lights-only it would be continuous traffic
        /// on the endpoint the game's force feedback shares, for a level that is the
        /// game's to set, which is the one thing the mode promises not to do.</summary>
        private void StopKeepAliveOutsideFull(WheelLedChannel ch)
        {
            if (ch == null || MasterMode == TrueforceMasterMode.Normal) return;
            try { ch.StopKeepAlive(); } catch { }
        }

        public bool BorrowSlot(WheelLedChannel.WheelLedSlot want, out string message,
                               int displayLevel = -1, string slotName = null,
                               bool permanent = false, bool rawColors = false)
        {
            message = null;
            // Off means off, including the lights. Every color that reaches a slot
            // comes through here (the car-load auto-apply, the pattern library, the
            // blank/restore rehearsal, the dev codes), so this one refusal is what
            // makes the master switch honest: before it, a "disabled" plugin still
            // repainted a Lightsync slot on every car load. RestoreSlot deliberately
            // does NOT come through here, so the way back to the user's own colors
            // stays open in every mode.
            if (MasterMode == TrueforceMasterMode.Off)
            {
                message = "The plugin is switched off, so it is not writing to the wheel.";
                return false;
            }
            var ch = _rpmLeds?.Channel;
            if (ch == null) { message = "No supported wheel detected."; return false; }
            if (want == null) { message = "Nothing to write."; return false; }
            // Parked with no game running the channel is closed, and every read
            // and write below would fail quietly.
            if (!EnsureLedChannelOpen())
            {
                message = "Could not reach the wheel. Check it is connected and powered on.";
                return false;
            }

            // A preview sweep drives the level on its own timer, so it would keep
            // stepping over the level this write sets and the pattern that just
            // landed would flicker or stay dark. Stand it down first; it is only
            // ever showing a previous pick, which this write supersedes.
            _rpmLeds.CancelPreview();

            // Everything upstream of here deals in sRGB intent: #FFFF00 means
            // yellow. This is the one place that turns intent into what THIS
            // wheel has to be sent to render it. `want` itself must not be
            // touched, because the code below keeps reading want.Slot and
            // callers hold the same object.
            //
            // Anything that later compares the wheel's bytes against a stored
            // pattern has to compare in this same corrected space. There are
            // three such sites (SyncSlotsToWheel, AdoptSlotContentsAsPattern,
            // LightPatternLibrary.AdoptWheelOrder) and all three run the stored
            // value through LedColorGain rather than trying to divide the gain
            // back out, which does not round-trip at 8 bits.
            // Clone() already deep-copies the array, so the caller's own bytes
            // are never handed to the channel even on the raw path.
            var wire = want.Clone();
            if (rawColors) wire.Rgb = want.Rgb;
            else
            {
                float tr, tg, tb; EffectiveLedTrim(out tr, out tg, out tb);
                wire.Rgb = LedColorGain.Apply(want.Rgb, tr, tg, tb);
            }

            try
            {
                var store = SlotBackups;
                var map = store.Load();

                if (permanent)
                {
                    // Settle any loan outstanding on this slot. What the user just
                    // chose is what belongs there now, and putting the old copy
                    // back at shutdown would quietly throw the edit away.
                    string owedKey;
                    var owed = LightSlotBackupStore.Find(map, SlotWheelId, want.Slot, out owedKey);
                    if (owed != null && !owed.Restored)
                    {
                        owed.Restored = true;
                        store.Save(map);
                        SimHub.Logging.Current.Info(
                            $"[TF4ALL] CUSTOM {want.Slot + 1} was written on purpose, so the loan on it is "
                            + "settled and nothing will be put back at shutdown");
                    }
                    if (_borrowedSlotCache == want.Slot) _borrowedSlotCache = -1;

                    if (!ch.TryWriteSlot(wire, displayLevel))
                    { message = "The wheel refused the write (see SimHub.txt)."; return false; }
                    StopKeepAliveOutsideFull(ch);
                    if (!string.IsNullOrWhiteSpace(slotName)) WriteSlotName(want.Slot, slotName);
                    InvalidateSlotProgrammedCache();
                    message = $"Saved into CUSTOM {want.Slot + 1}. It stays on the wheel with SimHub closed.";
                    return true;
                }

                // A backup file we could not parse is NOT the same as no backup.
                // Carrying on would re-read the slot, capture whatever is on it
                // (possibly our own colors from a previous borrow) and record
                // that as "the original", destroying the last trace of theirs.
                if (store.LastLoadCorrupt)
                {
                    message = "The slot backup file could not be read, so nothing was written. "
                            + "The unreadable file has been kept alongside it; your wheel is untouched.";
                    return false;
                }

                string key;
                var existing = LightSlotBackupStore.Find(map, SlotWheelId, want.Slot, out key);
                bool holdBackup = existing != null && !existing.Restored;

                if (!holdBackup)
                {
                    WheelLedChannel.WheelLedSlot original;
                    if (!ch.TryReadSlot(want.Slot, out original))
                    {
                        message = "Could not read the slot's current contents, so nothing was written. "
                                + "Refusing to overwrite something we cannot put back.";
                        return false;
                    }
                    var entry = LightSlotBackupStore.FromSlot(original, SlotWheelId, DateTime.UtcNow);
                    // Keep the slot's own name too, so giving it back restores how
                    // the wheel's menu reads, not just the colors.
                    entry.OriginalName = ReadSlotName(want.Slot);
                    map[LightSlotBackupStore.KeyFor(SlotWheelId, want.Slot)] = entry;

                    // The save MUST land before the wheel is touched. Reporting
                    // "backed up first" while the write silently failed was the
                    // worst bug in this path: the user would believe their colors
                    // were safe when the only copy had just been discarded.
                    if (!store.Save(map))
                    {
                        message = "Could not save a backup of your slot, so nothing was written. "
                                + "Your wheel is untouched. Check the SimHub folder is writable.";
                        return false;
                    }
                }

                if (!ch.TryWriteSlot(wire, displayLevel)) { message = "The wheel refused the write (see SimHub.txt)."; return false; }
                StopKeepAliveOutsideFull(ch);

                // Name the slot after what is IN it. Scrolling the base's own
                // LIGHTSYNC menu then reads as the pattern being shown, which is
                // the useful thing to see there; the original name is saved and
                // written back when the slot is handed over.
                if (!string.IsNullOrWhiteSpace(slotName)) WriteSlotName(want.Slot, slotName);
                _borrowedSlotCache = want.Slot;
                // A slot's contents just changed, so what the cycle believes about
                // which slots are filled is now one write out of date.
                InvalidateSlotProgrammedCache();

                message = holdBackup
                    ? $"Wrote CUSTOM {want.Slot + 1}. Your original is already backed up from earlier."
                    : $"Wrote CUSTOM {want.Slot + 1}. Your original was backed up first.";
                return true;
            }
            catch (Exception ex)
            {
                message = "Slot borrow failed: " + ex.Message;
                return false;
            }
        }

        /// <summary>Put a borrowed slot back exactly as we found it and mark the
        /// backup settled. Safe to call when nothing is owed: it says so.</summary>
        /// <param name="undoBlank">Set only by the human-typed SLOTRESTORE. The
        /// automatic paths must not undo a deliberate blank, or the rehearsal it
        /// exists for would not survive the next car load.</param>
        /// <summary>DEV (SLOTBLANK): record that this slot was deliberately
        /// emptied, so the automatic restore paths leave it alone and the blank
        /// survives a restart, WITHOUT settling the loan. The debt staying open is
        /// what keeps the user's real colors protected in the backup file.</summary>
        public bool MarkSlotBlanked(int slot, out string message)
        {
            message = null;
            try
            {
                var store = SlotBackups;
                var map = store.Load();
                if (store.LastLoadCorrupt)
                {
                    message = "The slot backup file could not be read, so the blank was not recorded.";
                    return false;
                }

                string key;
                var entry = LightSlotBackupStore.Find(map, SlotWheelId, slot, out key);
                if (entry == null)
                {
                    message = $"No backup held for CUSTOM {slot + 1}, so it was not marked blank.";
                    return false;
                }

                entry.Blanked = true;
                if (!store.Save(map))
                {
                    message = "Could not record the blank, so it will be undone at the next launch.";
                    return false;
                }
                message = $"CUSTOM {slot + 1} now reads as never programmed. Your colors are still "
                        + $"held in the backup; SLOTRESTORE{slot + 1} puts them back.";
                return true;
            }
            catch (Exception ex)
            {
                message = "Could not record the blank: " + ex.Message;
                return false;
            }
        }

        public bool RestoreSlot(int slot, out string message, bool undoBlank = false)
        {
            message = null;
            var ch = _rpmLeds?.Channel;
            if (ch == null) { message = "No supported wheel detected."; return false; }
            if (!EnsureLedChannelOpen())
            {
                message = "Could not reach the wheel, so the restore was not attempted. "
                        + "The backup is kept and will be applied when it can be.";
                return false;
            }

            try
            {
                var store = SlotBackups;
                var map = store.Load();

                string key;
                var entry = LightSlotBackupStore.Find(map, SlotWheelId, slot, out key);
                if (entry == null)
                {
                    message = $"No backup held for CUSTOM {slot + 1}; nothing to restore.";
                    return false;
                }
                // A settled loan normally means the debt is paid and there is
                // nothing to give back. The exception is a slot we deliberately
                // BLANKED: the rehearsal fills the empty slots it just created,
                // and SyncSlotsToWheel writes those permanently, which settles the
                // very loans the blanking opened. Refusing here would strand the
                // user's real colors in a file that still holds them perfectly,
                // with no way to write them back. So an explicit SLOTRESTORE beats
                // the settlement whenever the slot carries a blank we owe an undo
                // for. Seen 2026-08-24 doing exactly this on slots 1-4.
                if (entry.Restored && !(undoBlank && entry.Blanked))
                {
                    message = $"CUSTOM {slot + 1} was already restored.";
                    return false;
                }
                // A deliberately blanked slot is skipped by the AUTOMATIC restore
                // paths, which is what makes the blank survive a restart. Typing
                // SLOTRESTORE is not one of those: it is a person asking for their
                // colors back, so it goes through and clears the blank.
                // Blanked slots are skipped by the AUTOMATIC paths, which is what
                // makes a blank survive a restart. Typing SLOTRESTORE is not one of
                // those: it is a person asking for their colors back.
                if (entry.Blanked && !undoBlank)
                {
                    message = $"CUSTOM {slot + 1} is deliberately blanked (SLOTBLANK). "
                            + $"Type SLOTRESTORE{slot + 1} to put your colors back.";
                    return false;
                }
                entry.Blanked = false;

                var original = LightSlotBackupStore.ToSlot(entry);
                if (original == null)
                {
                    message = "The stored backup is unreadable, so nothing was written.";
                    return false;
                }
                // Write the slot we were ASKED to restore, not the number stored
                // in the file. The two are independent fields in a plain-text file
                // the header invites people to read, and on divergence the stored
                // one would send a restore into a slot nobody asked about.
                original.Slot = (byte)slot;
                if (!ch.TryWriteSlot(original)) { message = "The wheel refused the restore (see SimHub.txt)."; return false; }
                InvalidateSlotProgrammedCache();

                // Read it back and compare before calling the debt settled. A
                // write we merely believe landed is not proof: marking Restored
                // on an unconfirmed write would let the NEXT borrow re-read the
                // slot, still holding our colors, and record those as "the
                // original", losing the user's real ones for good.
                WheelLedChannel.WheelLedSlot after;
                bool verified = ch.TryReadSlot(slot, out after)
                                && after?.Rgb != null
                                && after.DirectionWire == original.DirectionWire
                                && after.Rgb.Length >= original.Rgb.Length
                                && !after.Rgb.Where((b, i) => i < original.Rgb.Length && b != original.Rgb[i]).Any();

                if (!verified)
                {
                    message = $"CUSTOM {slot + 1} was written back, but reading it returned something else, "
                            + "so the backup has been KEPT and can be applied again.";
                    return false;
                }

                // Put the slot's own name back too, so the wheel's menu stops
                // saying TF4ALL once it is theirs again.
                if (!string.IsNullOrWhiteSpace(entry.OriginalName))
                    WriteSlotName(slot, entry.OriginalName);

                entry.Restored = true;
                store.Save(map);
                if (_borrowedSlotCache == slot) _borrowedSlotCache = -1;
                message = $"CUSTOM {slot + 1} restored to what it was.";
                return true;
            }
            catch (Exception ex)
            {
                message = "Slot restore failed: " + ex.Message;
                return false;
            }
        }

        /// <summary>Any slot a previous session borrowed and never gave back.
        ///
        /// Called from End() so a clean exit settles the debt, and again after the
        /// wheel comes up so a session that CRASHED holding a slot is repaid at
        /// the next launch. Both matter: a slot write persists on the wheel, so
        /// without this the user's own colors stay overwritten indefinitely and
        /// only a hidden dev code could bring them back.</summary>
        public string RestoreOwedSlots()
        {
            try
            {
                var store = SlotBackups;
                var map = store.Load();
                var owed = new List<int>();
                foreach (var kv in map)
                    if (kv.Value != null && !kv.Value.Restored && !kv.Value.Blanked
                        && string.Equals(kv.Value.WheelId, SlotWheelId, StringComparison.OrdinalIgnoreCase))
                        owed.Add(kv.Value.Slot);

                // Nothing owed is the overwhelmingly common case, and it is
                // answered from disk, so a normal launch never touches the wheel.
                if (owed.Count == 0) return null;

                // Something IS owed, so the channel has to be open to give it
                // back. Only reached after a session died holding a slot.
                var ch = _rpmLeds?.Channel;
                if (ch != null && !ch.IsReady)
                {
                    try { ch.OpenAndResolve(); } catch { }
                }

                var done = new List<string>();
                foreach (int slot in owed)
                {
                    string msg;
                    if (RestoreSlot(slot, out msg)) done.Add("CUSTOM " + (slot + 1));
                }
                return done.Count > 0
                    ? "Restored a light slot a previous session left borrowed: " + string.Join(", ", done)
                    : null;
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Warn("[TF4ALL] owed-slot restore failed: " + ex.Message);
                return null;
            }
        }

        public string RpmLedStatus => _rpmLeds?.Status ?? "(n/a)";
        public bool RpmLedIsTesting => _rpmLeds?.IsTesting ?? false;

        // ---------- Wheel-base Dynamic OLED (experimental) ----------

        /// <summary>Walk the OLED through its screens (settings "Test"
        /// button). Opens the HID++ channel on demand so it works with nothing
        /// running.</summary>
        public void TestOled()
        {
            if (_oledDash == null) { SimHub.Logging.Current.Info("[OLED] controller not initialized"); return; }
            if (!OledWritesSafeNow)
            { SimHub.Logging.Current.Info("[OLED] test skipped: the screen is not ours to write in this mode"); return; }
            int ms = _oledDash.RunTest();
            SimHub.Logging.Current.Info($"[OLED] Test started, duration={ms} ms ({_oledDash.Status})");
        }

        /// <summary>Hand the OLED back to the wheel's own firmware (feature
        /// unchecked / plugin disabled). No telemetry frames arrive after that
        /// to drive the gate-off path, so callers must invoke this.</summary>
        public void TurnOffOled() => _oledDash?.ForceOff();

        /// <summary>True only on the wheels that actually have the base screen:
        /// the G PRO (either edition, and an RS50 in G PRO compatibility mode
        /// spoofs the Xbox PID) and the RS50 natively. The G923 has no screen at
        /// all, so its owners should never be offered the settings for one.
        /// False with no wheel detected: there is nothing to configure.</summary>
        public bool WheelHasOledScreen =>
            _hidWheelPid == 0xC272 || _hidWheelPid == 0xC268 || _hidWheelPid == 0xC276;

        /// <summary>A G PRO switched to G923 compatibility mode in G HUB: G923
        /// PID, G PRO product string and interface layout. Its firmware keeps
        /// the rev bar (as a five-step strip, through the G PRO's HID++
        /// interface) but drops the pattern slots and the screen, so only the
        /// level-bar routing follows the hardware; the screen and LIGHTSYNC
        /// gates stay on the PID, where a G923 PID correctly says no.</summary>
        private bool GProInG923Mode =>
            WheelDiscovery.IsGProInG923Mode(_hidWheelPid, _hidWheelProductString);

        /// <summary>True on the wheels whose rev-light pattern is selectable
        /// (built-in sweeps + custom LIGHTSYNC slots): the G PRO and RS50.
        /// A G923's strip lights a fixed look, so offering it a pattern
        /// picker would read as a feature its owner is missing. Same PID set
        /// as the screen today, but a separate property because the two are
        /// different capabilities that happen to coincide.</summary>
        /// <summary>Whether this wheel drives its rev lights over the LEGACY F8-12
        /// report on the gamepad collection rather than HID++ 0x807A. The G923
        /// PS/PC has no HID++ at all, so it is the only wheel on that path, and
        /// the only one the F8ANY experiment means anything on.</summary>
        public bool WheelIsLegacyF8 => _hidWheelPid == 0xC266 && !GProInG923Mode;

        /// <summary>The other side of that split: wheels whose rev bar is the
        /// HID++ 0x807A level channel. Ten steps on a G PRO or RS50, five on a
        /// G923 Xbox, and the strip length comes from the wheel itself rather
        /// than from this list. A G PRO wearing a G923 PID is here too, because
        /// the routing follows the hardware.</summary>
        public bool WheelIsHidppLevelBar =>
               _hidWheelPid == 0xC272 || _hidWheelPid == 0xC268   // G PRO (+ RS50 in compat mode)
            || _hidWheelPid == 0xC276                             // RS50 native
            || _hidWheelPid == 0xC26D || _hidWheelPid == 0xC26E   // G923 Xbox
            || GProInG923Mode;

        // ---------------- rim LEDs with no revs to draw ----------------

        /// <summary>Start or stop the audio meter thread to match the settings,
        /// and push the sensitivity through. Called at init, on a mode change
        /// and from the settings panel, so nothing polls the audio endpoint for
        /// a feature nobody has chosen.</summary>
        public void SyncAudioOutputMeter()
        {
            var meter = _audioLeds;
            if (meter == null) return;
            var s = Settings;
            // An arcade cabinet meters its audio between races whether or not either occasion was
            // set to it, so the meter has to be running for one to be available. Costs nothing when
            // no cabinet is live, because this only becomes true once one is.
            bool arcadeWantsAudio = ActiveGameIsArcade
                                 && _arcadeMemory != null && _arcadeMemory.Verified;
            bool wantAudio = s != null
                          && MasterMode != TrueforceMasterMode.Off
                          && (s.IdleLedMode == AmbientLedMode.AudioLevel
                           || s.NoRevLedMode == AmbientLedMode.AudioLevel
                           || arcadeWantsAudio);
            if (wantAudio)
            {
                meter.Start();
                return;
            }

            meter.Stop();
            // The strip does NOT come back here. Turning the meter off may leave
            // a sweep chosen for the other occasion, and the idle driver below
            // hands the bar over on its next tick either way; releasing from
            // here would blink the strip dark in between for no reason.
        }

        /// <summary>Reads engine data out of an arcade game's own memory. Null until an arcade game
        /// is running. Read only; see Id8MemoryTelemetry for the anti-cheat boundary.</summary>
        private Id8FrameFiller _arcadeMemory;

        /// <summary>Fills the game's own leaderboards and submits finished runs. Separate from
        /// _arcadeMemory because that one is strictly read only and stays that way: this is the
        /// only thing in the plugin that writes to a game's memory, and keeping the two apart is
        /// what makes that boundary checkable rather than a claim.</summary>
        private ArcadeLeaderboardService _arcadeBoards;

        /// <summary>Raises each finished Time Attack run once. A finished race is visible for
        /// hundreds of consecutive polls, so without this the same lap would submit repeatedly.</summary>
        private readonly Id8RunWatcher _arcadeRuns = new Id8RunWatcher();

        /// <summary>Guards against stacking overlapping network calls when the course changes
        /// while a previous fill is still in flight.</summary>
        private int _arcadeBoardBusy;

        /// <summary>Fill the boards for whatever course is up, and submit a finished run.
        ///
        /// Both halves are fire-and-forget: they touch the network, and the telemetry frame must
        /// not wait on that. Failure is silent by design here, because a leaderboard that cannot
        /// be reached is not a reason to disturb the wheel.</summary>
        private void StepArcadeLeaderboards(Id8FrameFiller filler)
        {
            var st = Settings;
            if (st?.Arcade == null || !st.Arcade.Id8LeaderboardsEnabled) return;
            // Gated on knowing the PROCESS, and nothing else. Not on a valid race sample, and not
            // on the telemetry reader having verified itself either: both are only true once the
            // game has built a session, which is to say once somebody is driving. The boards are
            // read from the menus, where the reader reports "the game has not built its session
            // yet" with verified=false, so either gate meant the boards were only ever written
            // while racing. A player who started the game and walked straight to the leaderboards
            // saw SEGA's placeholders, and since memory writes do not survive the process, that
            // was true again after every restart.
            //
            // Nothing is lost by dropping the checks, because the leaderboard tables are not in
            // the session. They hang off a static address, and Attach resolves them and runs
            // LayoutLooksRight, which refuses to write unless all four tables match the analysed
            // build. The fill validates itself; it never needed the telemetry reader's opinion.
            if (filler == null || string.IsNullOrEmpty(filler.GameProcessName)) return;

            if (_arcadeBoards == null)
                _arcadeBoards = new ArcadeLeaderboardService(
                    () => Settings,
                    msg => SimHub.Logging.Current.Info(msg),
                    async () => _auth != null ? await _auth.GetAccessTokenAsync() : null);

            // Attach lazily: the process is already known to the reader, and Attach is cheap and
            // idempotent once it has succeeded.
            Process game = FindArcadeProcess(filler.GameProcessName);
            if (game == null || !_arcadeBoards.Attach(game)) return;

            // Fill every board, not just the one being driven: the player browses the leaderboard
            // menu for courses they have not touched, and those would otherwise still show SEGA's
            // filler. The service latches this so it only actually runs once per attach.
            if (Interlocked.CompareExchange(ref _arcadeBoardBusy, 1, 0) == 0)
            {
                Task.Run(async () =>
                {
                    try { await _arcadeBoards.FillAllAsync(CancellationToken.None).ConfigureAwait(false); }
                    catch (Exception ex) { SimHub.Logging.Current.Warn("[TF4ALL] Arcade board fill failed: " + ex.Message); }
                    finally { Interlocked.Exchange(ref _arcadeBoardBusy, 0); }
                });
            }


            // The run watcher, unlike the fill, genuinely does need a live race sample: it is
            // watching for a finished lap. This is the guard that used to sit at the top and stop
            // the fill as well.
            Id8Sample s = filler.Last;

            // Menu work FIRST, and outside the validity guard below. Valid means the whole car
            // chain resolved, which only happens in a race, so anything that has to act on a menu
            // has to act before it: the ladder layout, and the rewrite deferred out of the results.
            ObserveArcadeLadder(s);

            if (!s.Valid) return;

            Id8FinishedRun run = _arcadeRuns.Observe(s, s.GameMode);
            if (run != null)
            {
                SimHub.Logging.Current.Info(
                    $"[TF4ALL] Arcade run finished: course {run.CourseId} dir {run.Direction} " +
                    $"car {run.CarId} {run.GoalMs} ms (clock read {run.ClockMs})");
                var toSend = run;

                // Show it, but NOT YET. Deferred to the moment the game leaves the race.
                //
                // The fill runs once per attach, so without a refill the player's own lap never
                // reaches the boards until they change a setting or relaunch: they set a record,
                // look, and it is not there. The game has just written its own copy, with the
                // cabinet name and card id on it, so the refill folds in THAT rather than anything
                // we invent.
                //
                // But the watcher fires at the GOAL, which is the middle of the results sequence:
                // the new-record flourish, the splits, the time they are reading. Rewriting the
                // boards there changes what they are looking at while they look at it. It matters
                // more under ladder climb, where the target is supposed to move on once beaten, and
                // the moment to move it is when they come back out to the course select.
                //
                // Independent of submission, which needs an account, the network and the disclosure
                // and can decline for any of them. Their own time appearing on their own cabinet
                // should not wait on any of that.
                _arcadeBoards.NoteFinishedRun();

                Task.Run(async () =>
                {
                    try { await _arcadeBoards.SubmitAsync(toSend, CancellationToken.None).ConfigureAwait(false); }
                    catch (Exception ex) { SimHub.Logging.Current.Warn("[TF4ALL] Arcade submit failed: " + ex.Message); }
                });
            }
        }

        /// <summary>Put the game's own shop board back, from the snapshot taken before we first
        /// wrote to it. For the settings toggle going off: leaving our rows in place until the
        /// player restarts the game would make "off" mean "off next time".</summary>
        public void RestoreArcadeBoards()
        {
            try { _arcadeBoards?.RestoreShopBoards(); }
            catch (Exception ex) { SimHub.Logging.Current.Warn("[TF4ALL] Arcade restore failed: " + ex.Message); }
        }

        /// <summary>Rewrite the boards for the course that is up now.
        ///
        /// The fill normally only runs when the course changes, so a source picked in the settings
        /// mid-session would otherwise not appear until the player left the course and came back,
        /// which reads as the setting not working.</summary>
        public void RefillArcadeBoards()
        {
            var boards = _arcadeBoards;
            var filler = _arcadeMemory;
            if (boards == null || filler == null) return;

            Task.Run(async () =>
            {
                try
                {
                    // force: nothing about the game has changed, only the chosen source, so the
                    // once-per-attach latch has to be overridden rather than worked around.
                    await boards.FillAllAsync(CancellationToken.None, force: true).ConfigureAwait(false);
                }
                catch (Exception ex) { SimHub.Logging.Current.Warn("[TF4ALL] Arcade refill failed: " + ex.Message); }
            });
        }

        /// <summary>The running arcade game, by the name the reader already matched.</summary>
        private static Process FindArcadeProcess(string processName)
        {
            if (string.IsNullOrEmpty(processName)) return null;
            try
            {
                Process[] all = Process.GetProcessesByName(processName);
                return all.Length > 0 ? all[0] : null;
            }
            catch { return null; }
        }

        /// <summary>The last lap time from the cabinet's own memory, else whatever SimHub had.
        /// SimHub has never heard of this game, so its lap fields sit at zero and the lap card
        /// never fired: the times are timed here instead, from the game's lap counter against its
        /// race clock.</summary>
        private int ArcadeLastLapOrDefault(int fallback)
        {
            var m = _arcadeMemory;
            if (m == null) return fallback;
            var s = m.Last;
            return (s.Valid && s.InRace && s.LastLapMs > 0) ? s.LastLapMs : fallback;
        }

        private int ArcadeBestLapOrDefault(int fallback)
        {
            var m = _arcadeMemory;
            if (m == null) return fallback;
            var s = m.Last;
            return (s.Valid && s.InRace && s.BestLapMs > 0) ? s.BestLapMs : fallback;
        }

        /// <summary>The technique the game just scored, held briefly so it can be read.
        ///
        /// These are the game's own judgement of good driving, not something inferred from physics,
        /// which is what makes them worth showing. The bit numbering was taken from the code that
        /// counts them rather than guessed: each counter shifts the flag word by its own amount and
        /// then announces a display id, and the two together give the pairing. An earlier guess
        /// that the bit equalled the id was wrong on every one.</summary>
        private string ArcadeTechniqueText()
        {
            var m = _arcadeMemory;
            if (m == null) { _arcadeTechniqueUntil = 0; return null; }

            // A wall hit gets its own, shorter moment: it is a mistake rather than a flourish and
            // wants to be gone before the next corner. It does NOT come from the technique bits.
            // The game names a wall hit in its technique table but never awards one anywhere in
            // this build, so the contact flag is the only real source for it.
            if (m.TakeWallHit())
            {
                _arcadeTechniqueText = m.LastHitWasCar ? "CONTACT" : "WALL HIT";
                _arcadeTechniqueIsImpact = true;
                _arcadeTechniqueUntil = Environment.TickCount + 1200;
            }

            uint bits = m.TakeTechniques();
            if (bits != 0)
            {
                string name = null;
                if ((bits & (1u << 3)) != 0) name = "GUTTER RUN";
                else if ((bits & (1u << 6)) != 0) name = "SHORTCUT";
                else if ((bits & (1u << 4)) != 0) name = "WHEEL LIFT";
                // bit 2 is tested and counted by the game but never set in this build.
                if (name != null)
                {
                    // An award outranks a wall hit: it is rarer and the better news.
                    _arcadeTechniqueText = name;
                    _arcadeTechniqueIsImpact = false;
                    _arcadeTechniqueUntil = Environment.TickCount + 2000;
                }
            }

            if (_arcadeTechniqueUntil == 0) return null;
            if (unchecked(Environment.TickCount - _arcadeTechniqueUntil) >= 0)
            {
                _arcadeTechniqueUntil = 0;
                return null;
            }
            return _arcadeTechniqueText;
        }

        private int _arcadeTechniqueUntil;
        private string _arcadeTechniqueText;

        /// <summary>Whether the technique on show is something that HURT rather than something
        /// that scored. Carried as a flag beside the text rather than re-derived from it: the
        /// display used to test the text against "WALL HIT" alone, so hitting another car came
        /// out as "NICE CONTACT". Whoever names a new impact should not have to know that.</summary>
        private bool _arcadeTechniqueIsImpact;

        /// <summary>Push the floor setting down to the live arcade source. Called when it is
        /// edited and whenever a source is created, since the source is rebuilt per game.</summary>
        /// <summary>Push the active cabinet's per-effect holds at the running
        /// source, so a slider is felt now rather than at the next launch.</summary>
        public void ApplyArcadeHolds()
        {
            var pub = _teknoSource as FfbArcadePluginSource;
            if (pub == null) return;
            var t = ArcadeTuningPeek(_activeGame);
            pub.SteadyHoldMs    = ClampArcadeHold(t.SteeringHoldMs);
            pub.VibrationHoldMs = ClampArcadeHold(t.VibrationHoldMs);
        }

        /// <summary>0 means "leave the published length alone". Anything shorter
        /// than one publisher frame cannot hold at all and would read as a control
        /// that silences the effect, so it is lifted to one frame instead.</summary>
        internal static int ClampArcadeHold(int ms)
        {
            if (ms <= 0) return 0;
            if (ms < 16) return 16;
            if (ms > 20000) return 20000;
            return ms;
        }

        public void ApplyArcadeMinForce()
        {
            var pub = _teknoSource as FfbArcadePluginSource;
            if (pub == null) return;
            int pct = Settings?.Arcade?.MinForcePercent ?? 0;
            pub.MinForce01 = pct <= 0 ? 0.0 : pct / 100.0;
        }

        /// <summary>Knock the wheel as the cabinet's menus are used. Called on the telemetry tick,
        /// which is the only place that sees the reader.
        ///
        /// The two strengths are the same voice as a gear change, which is what makes it read as
        /// mechanical rather than as a beep. A confirmation gets the full thud and moving through
        /// the options gets a third of it.
        ///
        /// What counts as confirming is approximate. The cabinet keeps no cursor or selected-item
        /// field anywhere we have mapped, so a change of screen stands in for it. Confirming
        /// something that leaves you on the same screen therefore feels like a move rather than a
        /// choice, which is the honest limit of what the game exposes.</summary>
        private void TickArcadeMenuHaptics()
        {
            if (Settings?.Arcade?.MenuHaptics != true) return;
            var m = _arcadeMemory;
            if (m == null || !m.Verified) return;
            int action = m.TakeMenuAction();
            if (action == 0) return;
            var gs = GearShift;
            if (gs == null) return;
            try { gs.PlayOneShot(action == 2 ? 1.0f : 0.33f); } catch { }
        }

        /// <summary>The starting lights as text. The race clock runs negative before GO, so the
        /// number is simply how many whole seconds are left, and GO is held for the first moment
        /// after it reaches zero.</summary>
        private string ArcadeCountdownText()
        {
            var m = _arcadeMemory;
            if (m == null) return null;
            var s = m.Last;
            if (!s.InRace || !s.Valid) return null;
            if (s.CountdownSeconds > 0)
                return s.CountdownSeconds.ToString(System.Globalization.CultureInfo.InvariantCulture);
            return s.JustStarted ? "GO" : null;
        }

        /// <summary>How the race ended, held for a few seconds so it is still there when the driver
        /// looks down. Latched on the transition rather than polled, because the fields it is
        /// judged from keep their values well past the moment they became true.</summary>
        private string ArcadeResultText()
        {
            var m = _arcadeMemory;
            if (m == null) { _arcadeResultShownUntil = 0; return null; }
            var s = m.Last;

            if (s.Finished && s.Valid && !_arcadeResultLatched)
            {
                _arcadeResultLatched = true;
                _arcadeResultShownUntil = Environment.TickCount + 6000;
                // Only a race decided at the goal gets a placing. Running out of time is its own
                // ending, and a measured session proved the difference matters: it ended on the two
                // minute limit with the rank field still at its initial 0, which the old logic
                // would have announced as a win.
                _arcadeResultText = s.Won == true ? "WIN"
                                  : s.Won == false ? "LOSE"
                                  : s.ReachedGoal ? "FINISH" : "TIME UP";
                // The fields behind this are only LIKELY in the map, so the reading that produced
                // the word is on the record next to it. One race settles the encoding.
                SimHub.Logging.Current.Info(
                    $"[TF4ALL] [ID8MEM] race over, showing '{_arcadeResultText}'. rank={s.ActorRank} "
                    + $"actorState={s.ActorState} resultCode={s.ResultCode} endReason={s.EndReason} "
                    + $"finishMs={s.FinishTimeMs} gap={s.GapMetres:0.0}m reachedGoal={s.ReachedGoal}");
            }
            else if (!s.Finished)
            {
                _arcadeResultLatched = false;
            }

            if (_arcadeResultShownUntil == 0) return null;
            if (unchecked(Environment.TickCount - _arcadeResultShownUntil) >= 0)
            {
                _arcadeResultShownUntil = 0;
                return null;
            }
            return _arcadeResultText;
        }

        private bool _arcadeMeterSynced;
        private bool _arcadeResultLatched;
        private int _arcadeResultShownUntil;
        private string _arcadeResultText;

        /// <summary>The attract message, scrolled. The large row on the wheel holds ten characters
        /// and "PRESS START" is eleven, so it was arriving cut off. Rather than shorten it to fit,
        /// the whole message runs past the window the way the greeting does, which also lets it say
        /// more than one thing without flicking between two static screens.</summary>
        private string ArcadeAttractWindow()
        {
            const string Message = "INITIAL D 8   PRESS START   ";
            const int Window = 10;
            const int StepMs = 220;
            // Doubled so a window near the end still has characters to read.
            string loop = Message + Message;
            int step = (Environment.TickCount / StepMs) % Message.Length;
            return loop.Substring(step, Window);
        }

        /// <summary>Has anyone swiped a card? Until they do, the game fills the player record with
        /// its own placeholder, whose name is katakana for "player". Romanised onto a wheel panel
        /// that reads like a fault rather than like a driver, so nothing about the player is worth
        /// showing yet.</summary>
        private bool ArcadeHasCard()
        {
            var m = _arcadeMemory;
            if (m == null) return false;
            var s = m.Last;
            return s.SessionValid && s.HasCard && !string.IsNullOrEmpty(s.PlayerNameAscii);
        }

        /// <summary>Top row between races: the driver once there is one, and otherwise nothing, so
        /// the attract message below has the large row to itself.</summary>
        private string ArcadeBetweenRacesTop()
        {
            var m = _arcadeMemory;
            if (m == null) return null;
            var s = m.Last;
            if (s.InRace) return null;

            // NO SESSION AT ALL IS THE MOST ATTRACT STATE THERE IS, and this used to return
            // nothing for it. The session pointer genuinely comes and goes while a cabinet idles,
            // so the panel went blank in exactly the state the message exists for, and only spoke
            // up in the one state where somebody had already pressed start. Identity is what needs
            // a session; the attract line needs nothing.
            if (!s.SessionValid) return ArcadeAttractWindow();

            // Nobody has swiped in, so there is no driver to name and the attract line takes the
            // row instead. It reads better up here than down in the car slot: the top row is where
            // the eye starts, and leaving it blank above a message made the panel look half broken.
            if (!ArcadeHasCard()) return ArcadeAttractWindow();
            // The panel draws ASCII only, and this is a Japanese game whose names are usually
            // katakana, so the romanised form is what can actually be read there. The unromanised
            // name still goes out on the Arcade.PlayerName property for dashes that can show it.
            return s.PlayerNameAscii;
        }

        /// <summary>Bottom row between races. With a card, the chosen car. Without one, an attract
        /// message that alternates every few seconds, because at that point there genuinely is no
        /// driver and no car, and inventing either is worse than saying what the cabinet is.</summary>
        private string ArcadeBetweenRacesBottom()
        {
            var m = _arcadeMemory;
            if (m == null) return null;
            var s = m.Last;
            if (s.InRace) return null;

            // Blank rather than null with no session, so the top row's attract line has the panel
            // to itself rather than sitting above whatever was there before.
            if (!s.SessionValid) return "";

            // The attract line lives on the top row now, so this one stays empty until there is
            // a real car to name.
            if (!ArcadeHasCard()) return "";

            var car = s.GarageCar ?? s.Car;
            // The panel row is short, so the code beats the full name: a driver knows AE86T. No car
            // chosen yet leaves the row blank rather than guessing at one.
            return car != null ? car.Code : "";
        }

        /// <summary>Lap number from the cabinet's own memory while it is racing, else whatever
        /// SimHub had. The map counts laps FINISHED, and a display wants the one being driven.</summary>
        private int ArcadeLapOrDefault(int fallback)
        {
            var m = _arcadeMemory;
            if (m == null) return fallback;
            var s = m.Last;
            return s.InRace && s.Valid ? s.LapsCompleted + 1 : fallback;
        }

        /// <summary>Total laps from the course record, else whatever SimHub had. Zero means the
        /// course is a sprint rather than a circuit, and a display should show no lap count.</summary>
        private int ArcadeTotalLapsOrDefault(int fallback)
        {
            var m = _arcadeMemory;
            if (m == null) return fallback;
            var s = m.Last;
            return s.InRace && s.Valid && s.TotalLaps > 0 ? s.TotalLaps : fallback;
        }

        /// <summary>Stamp rpm, gear, speed and the pedals onto an arcade frame from the game's own
        /// memory. Does nothing at all when the pointer chain does not resolve, so a build the map
        /// does not describe simply produces no engine data rather than wrong data.</summary>
        private void ApplyArcadeMemoryTelemetry(ref TelemetryFrame frame)
        {
            if (!ActiveGameIsArcade)
            {
                var stale = _arcadeMemory;
                if (stale != null)
                {
                    _arcadeMemory = null;
                    try { stale.Dispose(); } catch { }
                }
                // The boards live in the game's memory, so when the game goes so does everything
                // we knew about them. Detaching also drops the pre-write snapshot, which must be
                // retaken fresh next launch rather than carried across.
                try { _arcadeBoards?.Detach(); } catch { }
                _arcadeRuns?.Reset();
                return;
            }

            var filler = _arcadeMemory;
            if (filler == null)
            {
                filler = new Id8FrameFiller(msg => SimHub.Logging.Current.Info($"[TF4ALL] {msg}"));
                _arcadeMemory = filler;
            }
            // The frame counter only paces the retry, so any monotonic tick will do.
            try { filler.Fill(ref frame, Environment.TickCount / 2); } catch { }

            // Fill the game's leaderboards and submit a finished run. Deliberately after Fill, so
            // it works from the sample this frame just produced, and deliberately wrapped: a
            // leaderboard is a nicety and must never be able to take the telemetry path down.
            try { StepArcadeLeaderboards(filler); }
            catch (Exception ex) { SimHub.Logging.Current.Info("[TF4ALL] Arcade leaderboards: " + ex.Message); }
        }

        /// <summary>Which output is being metered, or why none is, for the
        /// settings panel.</summary>
        public string AudioOutputMeterStatus => _audioLeds?.Status ?? "off";

        /// <summary>Where the meter's own bar sits, 0..1, so the panel can show
        /// it moving while the sensitivity is being set.</summary>
        public double AudioOutputMeterLevel => _audioLeds?.Level01 ?? 0.0;

        /// <summary>What should be on the rim LEDs right now given that the revs
        /// are not driving them, or Off to leave the strip alone.
        ///
        /// Two occasions, resolved in this order and NOT the other one. A game
        /// being PLAYED that has never mentioned an engine is the no-revs case
        /// for as long as it runs, and it never falls through to the idle case.
        /// That order is the whole reason this is written down: the arcade
        /// sources publish no speed at all, so DashIdleElapsed reads a live
        /// cabinet as parked, and a fall-through would swap a running game's
        /// lights over to the idle choice partway through a race.
        ///
        /// The revs always win where there are revs. Neither occasion competes
        /// for the bar; they fill the gaps where nothing else can.</summary>
        /// <param name="gamePlaying">Whether a game is actually being played, as
        /// opposed to merely feeding us frames. Those came apart in testing: the
        /// arcade source publishes for as long as the cabinet IO block exists,
        /// so TeknoParrot sitting open at its menu looked exactly like a running
        /// game and held the no-revs case open forever. The caller answers this,
        /// because only it has the session signal.</param>
        private AmbientLedMode ResolveAmbientMode(bool gamePlaying)
        {
            var s = Settings;
            if (s == null) return AmbientLedMode.Off;
            // A mapped arcade cabinet answers this exactly rather than by latch: it says whether
            // a race is running right now. The strip can therefore go back to the ambient choice
            // between races, which is where the driver actually is when there is something to look
            // at. Everywhere else the one-way latch stands, because a sim that has ever reported an
            // engine will report one again and flicking the strip between two owners mid-session
            // would be worse than holding it.
            var arcadeMem = _arcadeMemory;
            if (gamePlaying && arcadeMem != null && arcadeMem.Verified)
            {
                var arc = arcadeMem.Last;
                if (arc.InRace) return AmbientLedMode.Off;   // the revs have the strip
                if (arc.SessionValid)
                {
                    // Between races, and NEITHER of the two occasions describes it properly. The
                    // no-revs one is about a game that never reports an engine, which this game
                    // does; making it the only way in meant asking for the audio meter here forced
                    // a claim about the game that is not true. The idle one is about a parked car,
                    // which is closer but is separately suppressed for a live cabinet.
                    //
                    // So take whichever the owner has actually chosen, and when they have chosen
                    // neither, meter the audio anyway. Between races a cabinet is showing menus and
                    // attract screens with music playing over them, the strip has nothing else to
                    // do, and asking someone to find a setting before the lights will move is a
                    // toggle for its own sake. The revs take it straight back the moment a race
                    // starts, so this cannot get in the way of driving.
                    if (s.IdleLedMode != AmbientLedMode.Off) return s.IdleLedMode;
                    if (s.NoRevLedMode != AmbientLedMode.Off) return s.NoRevLedMode;
                    return AmbientLedMode.AudioLevel;
                }
            }
            if (gamePlaying && !_revDataSeen) return s.NoRevLedMode;
            // Asked before DashIdleElapsed, which is stateful and shared: with
            // the idle occasion switched off there is no reason to be driving
            // somebody else's stop-watch on the telemetry thread.
            if (s.IdleLedMode == AmbientLedMode.Off) return AmbientLedMode.Off;
            return DashIdleElapsed() ? s.IdleLedMode : AmbientLedMode.Off;
        }

        /// <summary>The level that mode wants, in whole steps of the strip it is
        /// being drawn on. Off reads zero, which is also what a caller writes to
        /// release a strip it was driving.</summary>
        private int AmbientLevelFor(AmbientLedMode mode, int steps)
        {
            if (steps <= 0) return 0;
            switch (mode)
            {
                case AmbientLedMode.Sweep:
                    // A clock, not a counter: two callers at different rates
                    // (the telemetry path and the DataUpdate tick) then agree on
                    // the phase without either owning it.
                    return LedSweep.Level(
                        DateTime.UtcNow.Ticks / TimeSpan.TicksPerMillisecond,
                        Settings?.LedSweepPeriodMs ?? LedSweep.DefaultPeriodMs,
                        steps);

                case AmbientLedMode.AudioLevel:
                    double v = _audioLeds?.Level01 ?? 0.0;
                    if (double.IsNaN(v)) return 0;
                    int lvl = (int)Math.Floor(v * steps + 0.5);
                    return lvl < 0 ? 0 : lvl > steps ? steps : lvl;

                default:
                    return 0;
            }
        }

        /// <summary>Was the idle path last seen driving the strip, so it knows
        /// it has a release to do when it stops.</summary>
        private bool _ambientIdleDriving;

        /// <summary>Run the ambient lights with no telemetry arriving: SimHub
        /// open with nothing playing, or a game that has stopped feeding us.
        /// Lives on the DataUpdate tick because the telemetry path does not run
        /// at all in that state, exactly like the OLED's idle readout.
        ///
        /// The gate is Normal mode plus silence from the telemetry path, which
        /// is the same reasoning the OLED idle readout uses: with no game
        /// running there is no force anywhere, so the wheel's HID++ pipe is
        /// nobody's to cut. Where a game IS running and feeding us, the frame
        /// path drives this instead and it rides that path's tap-proven quiet
        /// gate like the rev lights do.</summary>
        private void DriveAmbientLedsIdle()
        {
            var leds = _rpmLeds;
            if (leds == null) return;

            var mode = MasterMode == TrueforceMasterMode.Normal && NoTelemetryArriving()
                     ? ResolveAmbientMode(gamePlaying: false)
                     : AmbientLedMode.Off;
            bool own = mode != AmbientLedMode.Off;
            // Nothing to write and nothing to hand back: stay off the wire
            // entirely rather than releasing an already released strip on every
            // tick of every session that never turns this on.
            if (!own && !_ambientIdleDriving) return;
            _ambientIdleDriving = own;

            try
            {
                if (WheelIsLegacyF8)
                {
                    int lvl = AmbientLevelFor(mode, G923LedCount);
                    DriveG923Leds(lvl / (double)G923LedCount, false, own);
                }
                else if (WheelIsHidppLevelBar)
                {
                    leds.OnAmbientLevel(AmbientLevelFor(mode, leds.MirrorSteps), own);
                }
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Error("[TF4ALL] ambient LED error", ex);
            }
        }

        public bool WheelHasSelectableLightPattern =>
            _hidWheelPid == 0xC272 || _hidWheelPid == 0xC268 || _hidWheelPid == 0xC276;

        /// <summary>Whether discovery has actually identified a wheel yet. Distinct
        /// from the capability properties above, which answer "false" both for a
        /// wheel that cannot do the thing AND for no wheel at all. Anything that
        /// HIDES a feature has to tell those two apart, or a wheel that was powered
        /// off at startup takes the feature away with it.</summary>
        public bool WheelDetected => _hidWheelPid != 0;

        public string OledStatus => _oledDash?.Status ?? "(n/a)";
        public bool OledIsTesting => _oledDash?.IsTesting ?? false;

        /// <summary>Whether writing the screen right now cannot disturb anyone's
        /// force feedback: no game at all, or Mode B holding the HID++ pipe
        /// free.</summary>
        public bool OledWritesSafeNow =>
            // The screen belongs to full mode. Checked FIRST because the two terms
            // below both read true forever outside it: _oledHidppFree is latched by
            // the frame path and NoTelemetryArriving is trivially true when no
            // telemetry source is running, so within half a second of switching to
            // off or lights-only this said "safe" while a game was mid-corner with
            // its own force feedback live.
            MasterMode == TrueforceMasterMode.Normal
            && (_oledHidppFree || NoTelemetryArriving());

        /// <summary>True when no telemetry frame has arrived recently, which is
        /// the honest test for "nothing is driving the wheel right now".
        ///
        /// This used to ask whether _activeGame was empty, which was wrong:
        /// that is SimHub's SELECTED game and stays set with nothing running,
        /// so the panel refused to preview and the idle readouts never fired
        /// even with every game closed. Frames stopping is the thing that
        /// actually means no force can be on the HID++ pipe.</summary>
        private bool NoTelemetryArriving()
        {
            long stamp = System.Threading.Interlocked.Read(ref _lastFrameTicks);
            if (stamp == 0) return true;   // nothing has ever arrived this run
            return Stopwatch.GetTimestamp() - stamp > FrameStallTicks;
        }

        /// <summary>Put the screen currently being edited on the wheel with
        /// stand-in telemetry. Returns how long it will be up, 0 if the channel
        /// is not ready yet, or -1 when a game is running and holding the pipe,
        /// which the caller turns into an explanation rather than silence.</summary>
        public int PreviewOledScreen()
        {
            if (_oledDash == null || Settings == null) return 0;
            if (!OledWritesSafeNow) return -1;
            var ctx = new OledFrameContext
            {
                Screen       = Settings.OledScreen,
                UseMph       = Settings.OledUseMph,
                CustomLayout = Settings.OledCustomLayout,
                CustomSlots  = Settings.OledCustomSlots?.ToArray(),
                CustomTexts  = Settings.OledCustomTexts?.ToArray(),
                // Stand-ins chosen to fill their fields: a preview whose values
                // are all blank teaches you nothing about a layout.
                DeltaSupported = true,
                LapDelta   = -0.42,
                Position   = 4,
                CurrentLap = 3,
                TotalLaps  = 12,
                LastLapMs  = 92481,
            };
            return _oledDash.ShowPreview(ctx);
        }

        /// <summary>Whether the running game reports a lap delta at all, from
        /// the SAME evidence the dash's box picker uses to grey out "Lap
        /// times": the curated per-game gap table plus anything this title has
        /// been driven long enough to have never reported. One source of truth,
        /// so the wheel screen and the phone agree about what a game can do.
        /// True with no game running, so nothing is hidden pre-emptively.</summary>
        public bool GameReportsLapDelta =>
            (_dashUnsupported ?? "").IndexOf(",Delta,", StringComparison.Ordinal) < 0;

        /// <summary>SimHub's running lap delta against the session best, or
        /// null when there is no reference lap yet. Gated on SessionBest (a
        /// TimeSpan, genuinely absent until a lap is banked) because the delta
        /// property itself reads a confident 0 when unset, which would print
        /// "+0.00" all session on a screen with no way to say "no data".
        /// PersistantTracker computes both, so this is game-agnostic.</summary>
        private double? TryGetLiveLapDelta(PluginManager pluginManager)
        {
            if (pluginManager == null) return null;
            try
            {
                if (!(pluginManager.GetPropertyValue("PersistantTrackerPlugin.SessionBest")
                        is TimeSpan best) || best.TotalSeconds <= 0.0)
                    return null;
                object v = pluginManager.GetPropertyValue(
                    "PersistantTrackerPlugin.SessionBestLiveDeltaSeconds");
                if (v == null) return null;
                return Convert.ToDouble(v, System.Globalization.CultureInfo.InvariantCulture);
            }
            catch { return null; }
        }

        // ---------- F8SWEEP test code (legacy F8 12 LED experiment) ----------

        /// <summary>Toggle the experimental legacy "F8 12" rev-LED sweep on the
        /// wheel's gamepad collection (the forza-wheel-leds path, off the HID++
        /// FFB pipe). Start it, drive a sim, and watch whether the LEDs sweep AND
        /// the FFB stays solid; type the code again to stop. Returns a
        /// human-readable status for the access-code box.</summary>
        /// <param name="resendMs">null = simple on/off toggle (paced mode). A value
        /// (re)starts or live-switches the sweep at that resend rate: 0 = paced
        /// (write-on-change), &gt;0 = forza-style resend every N ms (e.g. 16).</param>
        public string ToggleF8LedSweep(int? resendMs)
        {
            // Normal only. This opens the wheel's gamepad HID collection and then
            // resends the legacy F8-12 rev-LED report roughly sixty times a second
            // until it is switched off again, which is both wheel traffic off
            // forbids and the continuous bar driving lights-only forbids. It is a
            // dev code, but it was the last LED path with no gate.
            if (MasterMode != TrueforceMasterMode.Normal)
                return $"Master mode is {ModeLabel(MasterMode)}, so the rev LEDs are not ours to drive. "
                     + "Switch to Normal to use this.";
            try
            {
                if (_f8Leds == null)
                    _f8Leds = new TrueforceForAll.Core.LegacyLedF8Channel(
                        msg => SimHub.Logging.Current.Info(msg));

                // No argument => simple on/off toggle. Default ON = forza-speed
                // (~60 Hz resend), the worst-case FFB test (same rate
                // forza-wheel-leds writes at); type F8SLOW to compare against our
                // paced write-on-change footprint.
                if (!resendMs.HasValue)
                {
                    if (_f8Leds.IsSweeping)
                    {
                        _f8Leds.StopSweep();
                        return "F8 sweep stopped, LEDs off.";
                    }
                    resendMs = 16;
                }

                if (!_f8Leds.StartSweep(resendMs.Value))
                    return "F8 sweep couldn't open the wheel's gamepad collection (see SimHub log).";

                return "F8 sweep running " + _f8Leds.ModeLabel + " on " + _f8Leds.ResolvedInfo
                     + ". Drive a sim, watch LEDs + FFB. F8SWEEP stops; F8FAST/F8SLOW switch rate.";
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Info("[F8-LED] toggle failed: " + ex.Message);
                return "F8 sweep error: " + ex.Message;
            }
        }

        // ---------- Performance auto-ratchet ----------

        /// <summary>Polled from ProducerLoop. Once per RatchetWindowMs, snapshots
        /// the device + audio glitch counters and bumps the corresponding ring
        /// capacity if the per-window delta crossed RatchetThreshold. One-way
        /// only, never shrinks. Survived capacities are persisted to Settings
        /// so the user doesn't re-pay the discovery glitch cost next session.
        /// In Manual mode the ratchet is bypassed; user controls sizes directly.</summary>
        private void CheckAutoRatchet()
        {
            var perf = Settings?.Performance;
            if (perf == null || perf.Mode != PerformanceMode.Auto) return;
            if (_device == null) return;

            long now = Stopwatch.GetTimestamp();
            long windowTicks = Stopwatch.Frequency * RatchetWindowMs / 1000L;
            if (_autoRatchetLastCheckTicks != 0 && (now - _autoRatchetLastCheckTicks) < windowTicks) return;

            long tfNow    = _device.UnderrunCount;
            long audioNow = _audio?.GlitchCount ?? 0;

            // Skip the very first tick (no baseline yet). Also seed the
            // last-underrun-seen timestamps to "now" so a session that
            // starts clean has a real quiet-window anchor, without this,
            // _tfLastUnderrunSeenTicks would stay 0 and the (now - 0)
            // arithmetic would falsely make every clean session look like
            // it had been quiet for the entire wall-clock since boot.
            if (_autoRatchetLastCheckTicks == 0)
            {
                _autoRatchetLastTfCount    = tfNow;
                _autoRatchetLastAudioCount = audioNow;
                _autoRatchetLastCheckTicks = now;
                _tfLastUnderrunSeenTicks    = now;
                _audioLastUnderrunSeenTicks = now;
                return;
            }

            long tfDelta    = tfNow    - _autoRatchetLastTfCount;
            long audioDelta = audioNow - _autoRatchetLastAudioCount;
            _autoRatchetLastTfCount    = tfNow;
            _autoRatchetLastAudioCount = audioNow;
            _autoRatchetLastCheckTicks = now;

            // Update last-underrun-seen timestamps. Any non-zero delta
            // resets the quiet timer; this is what the DOWN check measures
            // against. Initialize on the first non-zero value so we don't
            // start with "60s ago" and step down immediately on a quiet
            // session.
            if (tfDelta    > 0) _tfLastUnderrunSeenTicks    = now;
            if (audioDelta > 0) _audioLastUnderrunSeenTicks = now;

            // ----- Ratchet UP -----
            // Forza UDP exposes IsRaceOn, when paused / in menu / loading,
            // CPU spikes there don't reflect race-time conditions, so don't
            // bake a ratchet UP from them. Other sources don't have an
            // equivalent flag; SimHub's own GameRunning isn't precise enough
            // (it's true the moment the launcher is up, including loading).
            bool suppressUp = false;
            var fz = _telemetrySource as ForzaUdpTelemetrySource;
            if (fz != null && !fz.LastIsRaceOn) suppressUp = true;

            // Two-window confirmation gate: only fire UP when BOTH the
            // previous and current window crossed the threshold. Filters
            // out one-off blips (single CPU stall, brief USB hiccup) that
            // aren't actually sustained pressure on the ring.
            bool tfOver    = tfDelta    >= RatchetThreshold;
            bool audioOver = audioDelta >= RatchetThreshold;
            bool tfFireUp    = tfOver    && _prevTfOverThreshold;
            bool audioFireUp = audioOver && _prevAudioOverThreshold;
            _prevTfOverThreshold    = tfOver;
            _prevAudioOverThreshold = audioOver;

            if (!suppressUp && tfFireUp && perf.TfRingSize < TrueforceDevice.MaxRingSize)
            {
                int oldCap = perf.TfRingSize;
                int newCap = oldCap * 2;
                if (newCap > TrueforceDevice.MaxRingSize) newCap = TrueforceDevice.MaxRingSize;
                ApplyTfRingSize(newCap);
                SimHub.Logging.Current.Info(
                    $"[TF4ALL] Auto-ratchet UP: Trueforce ring {oldCap} → {newCap} after {tfDelta} dropout-events/s (~{tfDelta * 20} ms cumulative, sustained 2 windows).");
                _tfLastRatchetActionTicks = now;
                _tfLastActionWasDown = false;
                _prevTfOverThreshold = false;   // re-arm the 2-window requirement
                FireRatchetEvent(true, oldCap, newCap);
            }

            if (!suppressUp && audioFireUp && perf.AudioRingSize < AudioCaptureSource.MaxRingSamples)
            {
                int oldCap = perf.AudioRingSize;
                int newCap = oldCap * 2;
                if (newCap > AudioCaptureSource.MaxRingSamples) newCap = AudioCaptureSource.MaxRingSamples;
                ApplyAudioRingSize(newCap);
                SimHub.Logging.Current.Info(
                    $"[TF4ALL] Auto-ratchet UP: audio ring {oldCap} → {newCap} after {audioDelta} dropout-events/s (~{audioDelta * 20} ms cumulative or laps, sustained 2 windows).");
                _audioLastRatchetActionTicks = now;
                _audioLastActionWasDown = false;
                _prevAudioOverThreshold = false;   // re-arm the 2-window requirement
                FireRatchetEvent(false, oldCap, newCap);
            }

            // ----- Ratchet DOWN -----
            // Conditions, all must hold:
            //   - capacity is above its minimum
            //   - quiet window: no underruns/glitches for >= RatchetDownQuietMs
            //   - cooldown: no ratchet action (up or down) for >=
            //     RatchetDownCooldownMs after an UP, or >=
            //     RatchetDownFastCooldownMs once descent has started.
            // Quiet operation: log entry only, no UI event fire (don't want
            // a modal interrupting the user every minute as the ring drains).
            long quietTicks         = Stopwatch.Frequency * RatchetDownQuietMs        / 1000L;
            long slowCooldownTicks  = Stopwatch.Frequency * RatchetDownCooldownMs     / 1000L;
            long fastCooldownTicks  = Stopwatch.Frequency * RatchetDownFastCooldownMs / 1000L;

            long tfCooldown    = _tfLastActionWasDown    ? fastCooldownTicks : slowCooldownTicks;
            long audioCooldown = _audioLastActionWasDown ? fastCooldownTicks : slowCooldownTicks;

            if (perf.TfRingSize > TrueforceDevice.MinRingSize
                && _tfLastUnderrunSeenTicks  != 0
                && (now - _tfLastUnderrunSeenTicks)    >= quietTicks
                && (_tfLastRatchetActionTicks == 0
                    || (now - _tfLastRatchetActionTicks) >= tfCooldown))
            {
                int oldCap = perf.TfRingSize;
                int newCap = oldCap / 2;
                if (newCap < TrueforceDevice.MinRingSize) newCap = TrueforceDevice.MinRingSize;
                ApplyTfRingSize(newCap);
                SimHub.Logging.Current.Info(
                    $"[TF4ALL] Auto-ratchet DOWN: Trueforce ring {oldCap} → {newCap} after {RatchetDownQuietMs / 1000} s of quiet.");
                _tfLastRatchetActionTicks = now;
                _tfLastActionWasDown = true;
                // Fire the event on DOWN too so the UI banner stays
                // accurate. Without this, a banner showing "8 → 16" would
                // remain stale after the ring auto-shrank back to 8; the
                // UI auto-dismisses when latest == original.
                FireRatchetEvent(true, oldCap, newCap);
            }

            if (perf.AudioRingSize > AudioCaptureSource.MinRingSamples
                && _audioLastUnderrunSeenTicks  != 0
                && (now - _audioLastUnderrunSeenTicks)    >= quietTicks
                && (_audioLastRatchetActionTicks == 0
                    || (now - _audioLastRatchetActionTicks) >= audioCooldown))
            {
                int oldCap = perf.AudioRingSize;
                int newCap = oldCap / 2;
                if (newCap < AudioCaptureSource.MinRingSamples) newCap = AudioCaptureSource.MinRingSamples;
                ApplyAudioRingSize(newCap);
                SimHub.Logging.Current.Info(
                    $"[TF4ALL] Auto-ratchet DOWN: audio ring {oldCap} → {newCap} after {RatchetDownQuietMs / 1000} s of quiet.");
                _audioLastRatchetActionTicks = now;
                _audioLastActionWasDown = true;
                FireRatchetEvent(false, oldCap, newCap);
            }
        }

        private void FireRatchetEvent(bool isTf, int oldCap, int newCap)
        {
            try { AutoRatchetBumped?.Invoke(isTf, oldCap, newCap); } catch { }
        }

        /// <summary>Apply a new Trueforce ring size to the live device and persist.
        /// Called by both the auto-ratchet path and Manual-mode UI sliders.</summary>
        public void ApplyTfRingSize(int newCapacity)
        {
            if (Settings?.Performance == null || _device == null) return;
            int sane = SanitizePow2(newCapacity, TrueforceDevice.MinRingSize, TrueforceDevice.MaxRingSize,
                                    TrueforceDevice.DefaultRingSize);
            Settings.Performance.TfRingSize = sane;
            _device.SetRingCapacity(sane);
            // Persist OFF this thread. The auto-ratchet calls this from the
            // realtime producer thread; a synchronous serialize + disk write
            // here stalls the ring at exactly the moment the system is already
            // struggling (which is what triggered the ratchet). The live ring
            // capacity is applied above; the disk flush is not time-sensitive.
            ScheduleSettingsFlush();
        }

        /// <summary>Apply a new audio ring size to the live capture source and persist.</summary>
        public void ApplyAudioRingSize(int newCapacity)
        {
            if (Settings?.Performance == null || _audio == null) return;
            int sane = SanitizePow2(newCapacity, AudioCaptureSource.MinRingSamples,
                                    AudioCaptureSource.MaxRingSamples, AudioCaptureSource.DefaultRingSamples);
            Settings.Performance.AudioRingSize = sane;
            _audio.SetRingCapacity(sane);
            // Same as ApplyTfRingSize: never write the settings file from the
            // realtime producer thread.
            ScheduleSettingsFlush();
        }

        /// <summary>Reset both rings to the smallest configured value. Auto mode
        /// will re-discover whether the machine can hold them; Manual mode
        /// keeps the small value until the user changes it.</summary>
        public void ResetPerformanceToLowest()
        {
            ApplyTfRingSize(TrueforceDevice.MinRingSize);
            ApplyAudioRingSize(AudioCaptureSource.MinRingSamples);
        }

        public void SetPerformanceMode(PerformanceMode mode)
        {
            if (Settings?.Performance == null) return;
            Settings.Performance.Mode = mode;
            PersistSettingsCore();
        }

        /// <summary>Clamp <paramref name="value"/> to [min, max] and round down
        /// to the nearest power of two. Used to defensively sanitize a value
        /// pulled from settings (which a hand-edited file could set to anything).</summary>
        private static int SanitizePow2(int value, int min, int max, int fallback)
        {
            if (value < min || value > max) return fallback;
            int p = 1;
            while ((p << 1) <= value) p <<= 1;
            if (p < min) p = min;
            if (p > max) p = max;
            return p;
        }

        // ---------- enhanced source selection ----------

        /// <summary>True when <paramref name="game"/> has a per-game enhanced
        /// source we should attempt to instantiate. Used both at game-change
        /// and as the gate for the periodic retry loop. Forza covers FH4/5/6
        /// and FM (2023) since they share the same Data Out wire format.</summary>
        private bool IsEnhancedEligible(string game)
        {
            if (game == "AssettoCorsa") return true;
            if (IsForzaGameName(game)) return true;
            return false;
        }

        /// <summary>Save current Settings to SimHub's common-settings store.
        /// UI code calls this after touching settings outside the on-the-fly
        /// path (e.g., persisting SharingAuthor from the export-info dialog).</summary>
        public void PersistSettings()
        {
            PersistSettingsCore();
            // Arm a debounced auto-backup when the user enabled auto-sync. Cheap and
            // guarded (no-op unless AutoSyncBackupEnabled + signed in); see RequestAutoBackup.
            RequestAutoBackup();
        }

        // Save without arming auto-sync. Used by the post-upload revision stamp so the
        // stamp's persist doesn't re-trigger another auto-backup cycle.
        //
        // THE settings-serialize choke point: every SaveCommonSettings in the plugin
        // routes through here (do not call SaveCommonSettings("GeneralSettings", ...)
        // directly). SaveCommonSettings walks the ENTIRE Settings graph with
        // Newtonsoft; a structural mutation of any collection in that graph
        // (EngineVariants, GamesWithRedline, CarOverrides, CommunityFactCache, ...)
        // on another thread mid-walk throws "Collection was modified" or corrupts
        // the write. The serialize and those mutations all hold _carFactsLock, so
        // they can never overlap. Monitor is reentrant, so callers already inside
        // _carFactsLock (ScheduleCarFactsFlush's drain loop) are fine.
        private void PersistSettingsCore()
        {
            if (Settings == null) return;
            // Pre-beta restore latch: once the update modal has put the
            // pre-beta snapshot back on disk, any later persist this session
            // (including the End() save while the installer closes SimHub)
            // would clobber the restored file with this session's beta-format
            // state, so the file on disk wins from here on.
            if (_suppressSettingsPersist) return;
            lock (_carFactsLock)
            {
                this.SaveCommonSettings("GeneralSettings", Settings);
            }
        }

        // See PersistSettingsCore. Volatile: set on the UI thread by the
        // update modal, read by whichever thread persists next. The getter
        // doubles as the "a restore already ran this session" signal, so a
        // retried update (e.g. installer cancelled at the UAC prompt) doesn't
        // restore again and overwrite the undo slot's parked beta data.
        private volatile bool _suppressSettingsPersist;
        internal bool SettingsPersistenceSuppressed => _suppressSettingsPersist;
        internal void SuppressSettingsPersistence() => _suppressSettingsPersist = true;
        internal void ResumeSettingsPersistence()   => _suppressSettingsPersist = false;

        // Build the backup envelope under _carFactsLock: BuildEnvelope walks the
        // whole Settings graph (JObject.FromObject), which must not overlap a
        // structural collection mutation on another thread (same rule as
        // PersistSettingsCore). The library file reads happen inside the lock
        // too, which lengthens the hold, but every caller runs on the thread
        // pool at backup/sync cadence, so a save that lands mid-build just
        // waits briefly instead of crashing.
        private BackupEnvelope BuildEnvelopeLocked()
        {
            lock (_carFactsLock)
            {
                return BackupService.BuildEnvelope(Settings, UserLibraryFolderForBackup(),
                    Environment.MachineName, DateTime.UtcNow);
            }
        }

        /// <summary>True when the Forza UDP section should be visible in the
        /// settings UI. Shown only while a Forza title is the active game;
        /// hidden in every other game so the panel stays uncluttered for
        /// the non-Forza majority.</summary>
        public bool ShouldShowForzaSection =>
            IsForzaGameName(_activeGame);

        /// <summary>True only while the game's process is actually running
        /// (SimHub data.GameRunning), not merely when a profile is selected.
        /// _currentGameName is null whenever nothing is running, so these are
        /// false for a profile that's open with the game closed. Used to gate
        /// the "set up UDP" prompt so it never fires on a selected-but-not-
        /// launched title.</summary>
        public bool IsGameRunning  => !string.IsNullOrEmpty(_currentGameName);
        public bool IsForzaRunning => IsForzaGameName(_currentGameName);

        /// <summary>True when the active game's telemetry includes ABS
        /// pump activity. Forza's Data Out wire format (FH4/FH5/FH6) does
        /// not surface this, and neither does SimHub's universal reader
        /// for those titles, so the ABS effect can't fire there. Drives a
        /// "not exposed by Forza UDP" badge in the settings UI so users
        /// don't tune the section expecting feedback that will never
        /// arrive. Other games default to true (they may or may not
        /// actually emit ABS; we surface it when they do).</summary>
        public bool ActiveGameSupportsAbs =>
            string.IsNullOrEmpty(_activeGame) || !IsForzaGameName(_activeGame);

        /// <summary>True when the "ABS not exposed by Forza UDP" badge should
        /// show. We only want it in a Forza context, not always: when editing
        /// a car preset, judge by that car preset's own game; when editing a
        /// game preset, judge by whether that preset is a Forza game's default;
        /// otherwise judge by the running/active game. This stops the badge
        /// from appearing while a non-Forza preset is open.</summary>
        /// <summary>True while a game is running that has no ABS, no DRS and no pit limiter, so
        /// their sections are hidden rather than badged.
        ///
        /// The established treatment for an effect that cannot fire in the current game is a badge
        /// and a dimmed section, because those settings are preset-scoped and still apply elsewhere.
        /// That reasoning does not reach these three on an arcade cabinet: they are not merely inert
        /// here, the game has no such systems at all, and a Japanese street racer will never gain
        /// them. A row that can never do anything is better absent than explained.</summary>
        public bool HideAssistEffectsForActiveGame
        {
            get
            {
                if (IsOfflineEditingCar)
                {
                    // ArcadeUnlocked too: a car preset saved under a cabinet outlives the switch,
                    // so without this an old ID8 preset opened for editing would still hide the
                    // assist sections on a build that no longer has an arcade path.
                    var g = GetCarPresetGame(_offlineEditCarId, _offlineEditCarPresetName);
                    return ArcadeUnlocked && !string.IsNullOrEmpty(g) && IsArcadeGameName(g);
                }
                return ActiveGameIsArcade;
            }
        }

        public bool ShowAbsUnsupportedBadge
        {
            get
            {
                // Editing a car preset: the car preset carries its own game.
                if (IsOfflineEditingCar)
                {
                    var g = GetCarPresetGame(_offlineEditCarId, _offlineEditCarPresetName);
                    return !string.IsNullOrEmpty(g) && IsForzaGameName(g);
                }
                // Editing a game preset: show only if it's a Forza game default.
                if (IsOfflineEditing)
                    return PresetIsForzaGameDefault(_offlineEditPresetName);
                // Live: judge by the active game.
                return !ActiveGameSupportsAbs;
            }
        }

        // True if any Forza game's auto-load default maps to this preset name.
        private bool PresetIsForzaGameDefault(string presetName)
        {
            if (string.IsNullOrEmpty(presetName) || Settings?.GameDefaults == null) return false;
            foreach (var kv in Settings.GameDefaults)
                if (IsForzaGameName(kv.Key) && string.Equals(kv.Value, presetName, StringComparison.Ordinal))
                    return true;
            return false;
        }

        /// <summary>True while a Forza title is the active game, whether we're
        /// reading the enhanced Forza UDP source or the SimHub fallback. Gates
        /// Forza-session behavior (the stationary-spring exclusion) on the
        /// session rather than the live source instance, so it still holds when
        /// a Forza session has fallen back to SimHub telemetry.</summary>
        private bool InForzaSession => IsForzaGameName(_activeGame);

        /// <summary>True when the stationary spring is supported on the
        /// active source. The spring conflicted with Forza's force feedback
        /// across pause and matchmaking transitions and could pull the wheel
        /// to its rotational stop; the precise mechanism wasn't isolated and
        /// several narrower gates were tried without reliably catching every
        /// case, so it is bypassed outright for the whole Forza session. Drives
        /// a "not used in Forza" badge next to the Stationary spring
        /// checkbox so users don't tune the section expecting a behavior
        /// that won't apply. Other sources unchanged.</summary>
        public bool ActiveSourceSupportsStationarySpring
            => !InForzaSession || ModeBEnabledForActiveGame;

        /// <summary>True if SimHub's GameName looks like any Forza title
        /// (Horizon or Motorsport). Drives Forza UDP section visibility.
        /// FM is included even though we auto-disable for it: the Data Out
        /// wire format is shared, so a user who manually re-enables for FM
        /// should still be able to configure the listener.</summary>
        private static bool IsForzaGameName(string game)
        {
            if (string.IsNullOrEmpty(game)) return false;
            return game == "FH4"
                || game == "FH5"
                || game == "FH6"
                || game == "FM7"
                || game == "FM8";
        }

        /// <summary>True if the game ships native Trueforce on PC. Plugin
        /// auto-disables on first encounter so our ep3 stream doesn't fight
        /// the game's own. Users can manually re-enable via the master
        /// toggle if they prefer our effects layered on top. SimHub
        /// GameName values verified against the SimHub install
        /// (LookupTables and PluginsData folder names).</summary>
        public static bool IsNativeTrueforceGame(string game)
        {
            if (string.IsNullOrEmpty(game)) return false;
            // Forza Motorsport (2023 reboot, internally FM8) ships native
            // Trueforce per Logitech's announcement. FM7 does NOT ship
            // native Trueforce, so it falls through to the Forza UDP
            // source for our enhanced effects.
            return game == "FM8"
                || game == "IRacing"
                || game == "AssettoCorsaCompetizione"
                || game == "AssettoCorsaRally"
                || game == "AssettoCorsaEVO"
                || game == "Automobilista2"
                || game == "BeamNgDrive"
                || game == "F12022"
                || game == "F12023"
                || game == "F12024"
                || game == "F12025"
                || game == "EAWRC23"
                || game == "PCars3"
                || game == "CodemastersGrid2019"
                || game == "CodemastersDirtRally2"
                || game == "WRC10"
                || game == "WRCGenerations"
                || game == "TDUSC"
                || game == "LMU";
        }

        /// <summary>True if a game has enough telemetry for Mode B to be
        /// OFFERED (the tab still gates it behind the per-game opt-in). The
        /// Forza titles all emit the Sled block (per-tire slip angle, combined
        /// slip, suspension travel) the tire model needs: FM8 (Motorsport, the
        /// one native-Trueforce title, where the pass-through path is
        /// impossible so Mode B is the only option) and FH4 / FH5 / FH6, whose
        /// own FFB works fine, so there Mode B is a REPLACEMENT the user opts
        /// into with the in-game force feedback and vibration set to 0 (the
        /// contention watchdog logs if the game still writes). Assetto Corsa
        /// is NOT here: its physics page has no per-tire slip angle, so the SAT
        /// model computes a zero direction and no force; it would need a
        /// derived slip angle first.</summary>
        private static bool IsModeBCapableGame(string game)
        {
            if (string.IsNullOrEmpty(game)) return false;
            return game == "FM8"
                || game == "FH4"
                || game == "FH5"
                || game == "FH6";
        }

        /// <summary>True for games whose Telemetry Based FFB is a RESHAPE of the
        /// sim's own steering torque rather than a synthesis from slip.
        /// iRacing only, and deliberately NOT in IsModeBCapableGame: that list
        /// arms the SAT model, which needs per-tire slip angle and combined
        /// slip. iRacing publishes neither (verified 2026-08-10: none of its
        /// 333 telemetry channels carry tire slip or load), so the SAT path
        /// would compute a zero direction and render nothing. What it DOES
        /// publish is SteeringWheelTorque in Nm, already solved by its own
        /// physics, plus a 360 Hz sub-tick array of the same. Reshaping that is
        /// strictly better than guessing at a model.</summary>
        private static bool IsIRacingReshapeGame(string game)
        {
            return string.Equals(game, "IRacing", StringComparison.Ordinal);
        }

        /// <summary>SimHub's GameName for RaceRoom ("RaceRoomRacingExperience";
        /// "RRRE" accepted defensively in case a build reports the short
        /// code).</summary>
        private static bool IsR3EGame(string game)
        {
            return string.Equals(game, "RaceRoomRacingExperience", StringComparison.OrdinalIgnoreCase)
                || string.Equals(game, "RRRE", StringComparison.OrdinalIgnoreCase);
        }

        /// <summary>SimHub's GameName for Le Mans Ultimate ("LMU", from its
        /// LMUManager in RfactorReader).</summary>
        private static bool IsLmuGame(string game)
        {
            return string.Equals(game, "LMU", StringComparison.OrdinalIgnoreCase);
        }

        /// <summary>The games whose handover reads the sim's own shared memory
        /// (RaceRoom, Le Mans Ultimate), whatever the route's state. The FFB
        /// tab keeps the take-over checkbox present for these on the tap route
        /// too, so it is the one switch for the handover.</summary>
        private static bool IsSharedMemoryTakeoverGame(string game)
        {
            return IsR3EGame(game) || IsLmuGame(game);
        }

        /// <summary>True while the shared-memory handover is switched on for
        /// <paramref name="game"/>.</summary>
        private bool SharedMemoryTakeoverOn(string game)
        {
            var s = Settings;
            if (s == null) return false;
            return (s.R3ESharedMemoryFfb && IsR3EGame(game))
                || (s.LmuSharedMemoryFfb && IsLmuGame(game));
        }

        /// <summary>True for games whose Telemetry Based FFB is a RESHAPE of
        /// the sim's own steering torque: iRacing always, and RaceRoom while
        /// the R3EFFB shared-memory route is opted in (dev A/B against the USB
        /// tap). This is the PIPELINE predicate; surfaces that mean "iRacing
        /// the sim" (its setup notice, loadTrueForceAPI handling, the direct
        /// SDK reader, incident points) stay on IsIRacingReshapeGame.</summary>
        private bool IsReshapeGame(string game)
        {
            if (IsIRacingReshapeGame(game)) return true;
            return SharedMemoryTakeoverOn(game);   // RaceRoom, Le Mans Ultimate
        }

        /// <summary>True if a game offers Telemetry Based FFB by ANY pipeline.
        /// The per-game opt-in, the tab toggle and the arming logic all key off
        /// this; which pipeline actually runs is decided in
        /// ApplyModeBFromSettings.</summary>
        private bool IsTelemetryFfbCapableGame(string game)
        {
            return IsModeBCapableGame(game) || IsReshapeGame(game);
        }

        /// <summary>Pick the right ITelemetrySource for <paramref name="game"/>
        /// (AC's MMF reader for "AssettoCorsa", Forza UDP listener for any
        /// Forza title, SimHub fallback otherwise) and hand-off OnFrame so
        /// exactly one source dispatches at a time. Called from DataUpdate on
        /// the SimHub data thread AND from ApplyForzaSettings on the UI
        /// thread; _sourceSwapLock serializes the two so the Forza create
        /// block can never run twice concurrently (a double bind leaks a
        /// listener that steals the port's datagrams). The new source's
        /// polling thread is fully started before the old source is detached,
        /// so the briefest possible window of "no dispatch" covers the swap.
        /// Pass <paramref name="silent"/>=true on retry attempts so we don't
        /// log a "fell back" message every second while AC is loading.</summary>
        // ---- Process-detected arcade games (TeknoParrot) ----

        // Keep-alive, like _forzaUdp and _fsPipeSource: it must survive while the
        // active source is something else, so it is disposed explicitly at every
        // teardown site rather than through _telemetrySource.
        private ITelemetrySource _teknoSource;

        /// <summary>Identity used when an arcade game is running but no configured
        /// process names it. Deliberately NOT prefixed "Custom_": HasUsefulTelemetry
        /// reads false for that prefix and would grey out telemetry UI for a source
        /// that has a genuinely live force stream.</summary>
        private const string GenericArcadeGameName = "TeknoParrotArcade";

        private long _arcadeProbeTicks;
        private bool _arcadeAmbiguityLogged;
        private bool _arcadeProbeLogged;
        private string _arcadeGameName;

        /// <summary>The synthetic game identity for a running arcade title, or
        /// null. Called once per data tick and throttled to 1 Hz internally.
        ///
        /// Identity comes from TeknoParrot's own profiles rather than from anything
        /// the user has to configure: each profile names the executable it runs, so
        /// a running process that matches one tells us exactly which cabinet this
        /// is. That matters because tuning is per cabinet, and a shared name would
        /// mean tuning Initial D detunes Wangan.
        ///
        /// The cheap test comes first. A shared block only exists while a game is
        /// up, and it is the thing we actually read, so its presence is both
        /// cheaper and truer than any process scan. Only once it is there do we
        /// look for which cabinet. With nothing running this costs two failed
        /// OpenExisting calls a second and never enumerates processes at all.</summary>
        private string DetectArcadeGameName()
        {
            var s = Settings?.Arcade;
            if (s == null || !s.Enabled) { _arcadeGameName = null; return null; }

            long now = Stopwatch.GetTimestamp();
            if (_arcadeProbeTicks != 0 && (now - _arcadeProbeTicks) < Stopwatch.Frequency)
                return _arcadeGameName;
            _arcadeProbeTicks = now;

            bool publisherBlock = FfbArcadePluginSource.Present(s.PublisherMapName);
            bool cabinetBlock = ArcadeBlockPresent();

            // Upgrade to the publisher the moment it appears.
            //
            // The route is chosen in SwapTelemetrySourceLocked, which runs when the
            // GAME CHANGES, and a cabinet is usually detected before its wrapper
            // has initialised: the publisher's block cannot exist yet, so the
            // choice fell to reading the IO block ourselves and was never revisited
            // for the rest of the session. That was not just the weaker route. Our
            // reader beacon is what tells a publishing build somebody is listening,
            // so never opening its block left it in its own fallback, still driving
            // the wheel through DirectInput while we rendered the same cabinet from
            // the IO block. Two engines on one wheel, and the wrapper's own
            // SharedMemoryOutput=2 looked like it was being ignored.
            if (publisherBlock && _teknoSource is TeknoParrotJvsTelemetrySource)
            {
                SimHub.Logging.Current.Info(
                    "[TF4ALL] Arcade: the publishing plugin's block has appeared, so switching to it "
                    + "from the IO-block decode. It has already decoded this cabinet, and opening its "
                    + "block is what stops it driving the wheel itself.");
                // Retire the IO-block reader FIRST. SwapTelemetrySourceLocked only builds an arcade
                // source when _teknoSource is null, so calling it with the old reader still in place
                // was a no-op: the upgrade never happened, this branch stayed true, and it logged and
                // retried once a second for the whole session while the publisher carried on driving
                // the wheel directly. Taken under the same lock the swap uses so the poll thread
                // cannot observe a half-swapped pair.
                try
                {
                    lock (_sourceSwapLock)
                    {
                        if (_teknoSource is TeknoParrotJvsTelemetrySource old)
                        {
                            if (ReferenceEquals(_telemetrySource, old)) _telemetrySource = null;
                            old.OnFrame = null;
                            try { old.Dispose(); } catch { }
                            _teknoSource = null;
                        }
                        SwapTelemetrySourceLocked(_activeGame, silent: true);
                    }
                }
                catch (Exception ex)
                {
                    SimHub.Logging.Current.Warn(
                        $"[TF4ALL] Arcade: the switch to the publishing plugin's block failed "
                        + $"({ex.GetType().Name}): {ex.Message}. Staying on the IO-block decode.");
                }
            }

            // Say what the first look saw, once. Without this a cabinet that never
            // gets detected produces no log at all, which cannot be told apart from
            // detection never running, and those two have completely different
            // fixes. One line a session, and it names the thing to check.
            if (!_arcadeProbeLogged)
            {
                _arcadeProbeLogged = true;
                SimHub.Logging.Current.Info(
                    $"[TF4ALL] Watching for arcade games. The FFB Arcade Plugin is "
                    + $"{(publisherBlock ? "sending force feedback" : "not sending anything yet")}, and "
                    + $"TeknoParrot is {(cabinetBlock ? "sharing its cabinet controls" : "not sharing anything yet")}. "
                    + "Neither one simply means no arcade game is running yet.");
            }

            bool anyBlock = publisherBlock || cabinetBlock;
            string found = anyBlock ? IdentifyRunningCabinet() : null;

            if (found != _arcadeGameName)
            {
                SimHub.Logging.Current.Info(found != null
                    ? $"[TF4ALL] Arcade game detected; running as '{found}'."
                    : "[TF4ALL] Arcade game closed.");
                _arcadeGameName = found;
            }
            return found;
        }

        /// <summary>Which configured cabinet is running, as a game identity, or the
        /// generic one when we cannot tell. Matched on the executable name from
        /// TeknoParrot's own profile, so it needs no configuration from the user.</summary>
        private string IdentifyRunningCabinet()
        {
            try
            {
                // Which executable names could possibly be a cabinet. Gathered
                // BEFORE the process walk because it decides which processes are
                // worth asking for a path.
                var targets = ArcadeModTargets();
                var pathWorthy = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                foreach (var t in targets)
                    if (!string.IsNullOrEmpty(t.ExeName)) pathWorthy.Add(t.ExeName);

                var running = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                var runningPaths = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                foreach (var p in Process.GetProcesses())
                {
                    try
                    {
                        string name = p.ProcessName;
                        running.Add(name);
                        // Full paths where we can get them, and ONLY for a name
                        // that already looks like a cabinet.
                        //
                        // MainModule throws a Win32Exception for every process we
                        // cannot open, which on a 32-bit host is most of a ~300
                        // entry process table, and SimHub logs a full stack trace
                        // for every first-chance throw. Asking about all of them
                        // once a second produced ~18k stack dumps and tens of
                        // megabytes of log per minute, which starved the UI badly
                        // enough to be visible as stutter. Reading another
                        // process's main module was always documented here as a
                        // bonus rather than the mechanism; this makes the cost
                        // match that billing.
                        if (pathWorthy.Contains(name))
                        {
                            try { runningPaths.Add(p.MainModule.FileName); } catch { }
                        }
                    }
                    catch { }
                    finally { try { p.Dispose(); } catch { } }
                }

                // A user mapping wins, for a cabinet TeknoParrot does not describe.
                var mapped = Settings?.Arcade?.Games;
                if (mapped != null)
                {
                    foreach (var kv in mapped)
                    {
                        if (string.IsNullOrEmpty(kv.Key) || string.IsNullOrEmpty(kv.Value)) continue;
                        if (running.Contains(kv.Key)) return kv.Value;
                    }
                }

                // Full path first. Two profiles can share an executable NAME while
                // living in different folders (the two Initial D Zero versions both
                // run InitialD0_DX11_Nu), and matching on the name alone would pick
                // whichever we happened to see first and then apply the other
                // cabinet's tuning.
                if (runningPaths.Count > 0)
                {
                    foreach (var t in targets)
                    {
                        if (string.IsNullOrEmpty(t.GameDir) || string.IsNullOrEmpty(t.ExeName)) continue;
                        foreach (var rp in runningPaths)
                        {
                            if (string.Equals(Path.GetDirectoryName(rp), t.GameDir, StringComparison.OrdinalIgnoreCase)
                                && string.Equals(Path.GetFileNameWithoutExtension(rp), t.ExeName, StringComparison.OrdinalIgnoreCase))
                            {
                                _arcadeMatchedExe = t.ExeName;
                                return ArcadeGameName(t.ProfileName);
                            }
                        }
                    }
                }

                // Name only. Ambiguous where two profiles share an executable name,
                // so say so rather than pick silently.
                ArcadeModTarget hit = null;
                bool ambiguous = false;
                foreach (var t in targets)
                {
                    if (string.IsNullOrEmpty(t.ExeName)) continue;
                    if (!running.Contains(t.ExeName)) continue;
                    if (hit != null && !string.Equals(hit.ExeName, t.ExeName, StringComparison.OrdinalIgnoreCase)) continue;
                    if (hit != null) ambiguous = true;
                    else hit = t;
                }
                if (hit != null)
                {
                    if (ambiguous && !_arcadeAmbiguityLogged)
                    {
                        _arcadeAmbiguityLogged = true;
                        SimHub.Logging.Current.Info(
                            $"[TF4ALL] More than one TeknoParrot profile runs '{hit.ExeName}', and the running "
                            + $"copy could not be told apart by path, so its tuning is filed under "
                            + $"'{ArcadeGameName(hit.ProfileName)}'.");
                    }
                    _arcadeMatchedExe = hit.ExeName;
                    return ArcadeGameName(hit.ProfileName);
                }

                NoteCabinetNotIdentified();
            }
            catch { }
            _arcadeMatchedExe = null;
            return GenericArcadeGameName;
        }

        private bool _arcadeIdentifyFailLogged;

        /// <summary>Say once that no cabinet was recognised.
        ///
        /// Deliberately does not list which programs the profiles expect against
        /// which are running. That list answers WHY, and it is the thing worth
        /// knowing when this fires, but it is a wall of executable names in a log
        /// a player reads to find out why their wheel is quiet. Owner's call
        /// (2026-09-07). If the question comes up again, the comparison is
        /// t.ExeName against the running process names, both already in hand at
        /// the call site.</summary>
        private void NoteCabinetNotIdentified()
        {
            if (_arcadeIdentifyFailLogged) return;
            _arcadeIdentifyFailLogged = true;
            SimHub.Logging.Current.Info(
                "[TF4ALL] An arcade game is running and sending force feedback, but none of "
                + "TeknoParrot's game profiles match it, so we cannot tell which cabinet it is.");
        }

        /// <summary>The executable that identified the running cabinet, or null when
        /// none did. Kept so a SimHub custom game profile can be matched against the
        /// cabinet it claims to describe rather than assumed to describe it.</summary>
        private string _arcadeMatchedExe;

        // Said once per cabinet so the log records that a custom game was renamed
        // rather than silently filed somewhere the user did not expect.
        private string _customGameNamedAs;

        private string _customGameMatchNoted;

        /// <summary>What the cabinet match had to work with, said once per game.
        ///
        /// Names both sides because either can be the empty one: the custom game
        /// may carry no program names, or TeknoParrot's profiles may not have been
        /// read yet. Those have different fixes and look identical from the
        /// outside, which is how this went round twice.</summary>
        private void NoteCustomGameMatchInputs(string gameCode, CustomGameInfo info,
                                               List<ArcadeModTarget> targets)
        {
            if (string.Equals(_customGameMatchNoted, gameCode, StringComparison.Ordinal)) return;
            _customGameMatchNoted = gameCode;

            string procs = info?.ProcessNames == null || info.ProcessNames.Length == 0
                ? "none"
                : string.Join(", ", info.ProcessNames);
            SimHub.Logging.Current.Info(
                "[TF4ALL] Checking whether custom game '" + (info?.Name ?? gameCode)
                + "' is an arcade cabinet. It runs: " + procs + ". Cabinets known: "
                + (targets == null ? 0 : targets.Count) + ".");
        }

        /// <summary>Which TeknoParrot cabinet this SimHub custom game runs, or null.
        ///
        /// A different question from CustomGameIsThisArcadeCabinet, which asks
        /// whether a cabinet ALREADY identified is the one a profile describes.
        /// This is asked when nothing has been identified, so it can only compare
        /// executable names, and it answers null when it cannot tell.
        ///
        /// It returns the profile rather than a yes/no on purpose. A yes/no can
        /// only be acted on by waiting for someone else to supply the name, and
        /// waiting is what left the game sitting at its guid with the arcade path
        /// switched off. The name was always available here.
        ///
        /// Ambiguity answers null. Two profiles sharing an executable cannot be
        /// told apart from a name alone, and guessing would file a user's tuning
        /// under the wrong cabinet, which is worse than the placeholder.</summary>
        private string ProfileForCustomGame(string gameCode)
        {
            var info = TryGetCustomGameInfo(gameCode);
            List<ArcadeModTarget> targets = null;
            try { targets = ArcadeModTargets(); }
            catch { }
            NoteCustomGameMatchInputs(gameCode, info, targets);

            if (info?.ProcessNames == null || info.ProcessNames.Length == 0) return null;
            if (targets == null || targets.Count == 0) return null;

            string hit = null;
            foreach (string p in info.ProcessNames)
            {
                if (string.IsNullOrEmpty(p)) continue;
                // Profiles are written with and without the extension, so compare
                // the way SimHub's own detection has to.
                string bare = p.EndsWith(".exe", StringComparison.OrdinalIgnoreCase)
                    ? p.Substring(0, p.Length - 4) : p;
                foreach (var t in targets)
                {
                    if (string.IsNullOrEmpty(t.ExeName) || string.IsNullOrEmpty(t.ProfileName)) continue;
                    if (!string.Equals(bare, t.ExeName, StringComparison.OrdinalIgnoreCase)) continue;
                    if (hit != null && !string.Equals(hit, t.ProfileName, StringComparison.OrdinalIgnoreCase))
                        return null;   // two cabinets, no way to choose
                    hit = t.ProfileName;
                }
            }
            return hit;
        }

        /// <summary>Is this SimHub custom game the arcade cabinet we are reading?
        ///
        /// Answered from the profile's own process names, which is the same list
        /// SimHub detects the game with, against the executable that identified the
        /// cabinet. Says YES when it cannot tell: an arcade block is already present
        /// and a cabinet already identified by the time this is asked, so the two
        /// being different games is far-fetched, and the cost of a wrong NO is a
        /// user's tuning quietly re-filed under a guid.</summary>
        private bool CustomGameIsThisArcadeCabinet(string gameCode)
        {
            var info = TryGetCustomGameInfo(gameCode);
            if (info?.ProcessNames == null || info.ProcessNames.Length == 0) return true;

            // The attached reader's own process is the best answer where there is
            // one, because it names the exact executable we are reading memory from.
            var filler = _arcadeMemory;
            string proc = filler != null ? filler.GameProcessName : null;
            if (string.IsNullOrEmpty(proc)) proc = _arcadeMatchedExe;
            if (string.IsNullOrEmpty(proc)) return true;

            foreach (string p in info.ProcessNames)
            {
                if (string.IsNullOrEmpty(p)) continue;
                // Profiles are written with and without the extension, so compare
                // the way SimHub's own detection has to.
                string bare = p.EndsWith(".exe", StringComparison.OrdinalIgnoreCase)
                    ? p.Substring(0, p.Length - 4) : p;
                if (string.Equals(bare, proc, StringComparison.OrdinalIgnoreCase)) return true;
            }
            return false;
        }

        /// <summary>Is this SimHub's stand-in for a car rather than a car?
        ///
        /// SimHub fabricates "DC__" plus its own startup timestamp for a game it has no car
        /// identity for, which is every custom game and Farming Simulator without our mod. It
        /// looks like an id and behaves like noise: it differs every session, so anything keyed
        /// on it (presets, car facts, engine pins, community lookups) can never resolve twice.
        /// Farming Simulator still falls back to it, so this names the shape rather than banning
        /// it, and each caller decides whether a placeholder is better than nothing.</summary>
        private static bool IsSimHubPlaceholderCarId(string carId)
        {
            return !string.IsNullOrEmpty(carId)
                && carId.StartsWith("DC__", StringComparison.Ordinal);
        }

        /// <summary>A comma or space separated list of numbers, skipping anything unreadable
        /// rather than refusing the whole line over one typo.</summary>
        private static double[] ParseNumberList(string text)
        {
            var found = new System.Collections.Generic.List<double>();
            if (string.IsNullOrEmpty(text)) return found.ToArray();
            foreach (string part in text.Split(new[] { ',', ' ', ';' }, StringSplitOptions.RemoveEmptyEntries))
            {
                double v;
                if (double.TryParse(part.Trim(), System.Globalization.NumberStyles.Float,
                        System.Globalization.CultureInfo.InvariantCulture, out v))
                    found.Add(v);
            }
            return found.ToArray();
        }

        /// <summary>DIAGNOSTIC (2026-09-06): search the running cabinet for a known string and
        /// log what surrounds every hit. Written to map the leaderboard, whose online board is
        /// filled with SEGA placeholder rows while the cabinet has no network, which makes it a
        /// repeated known string sitting in a table.
        ///
        /// Runs off the caller thread: a full address-space walk takes seconds and the access
        /// code box is on the UI thread. Read-only throughout.</summary>
        public string StartArcadeMemorySearch(string needle)
        {
            // Gated on being ATTACHED, not on the pointer chain having resolved. Verified means the
            // telemetry map checked out, which needs a session and a race; a memory search needs
            // only the process handle, and the leaderboard screen is exactly where the chain is not
            // resolved and where we most want to look.
            var filler = _arcadeMemory;
            string attachedTo = filler == null ? null : filler.GameProcessName;
            if (string.IsNullOrEmpty(attachedTo))
                return "Not attached to an arcade cabinet right now"
                     + (filler == null ? "" : ": " + filler.Status) + ".";
            if (string.IsNullOrWhiteSpace(needle)) needle = "SEGA";

            string text = needle.Trim();
            System.Threading.Tasks.Task.Run(() =>
            {
                try
                {
                    // A leading # means a NUMBER: "#360000" searches for that value as an int,
                    // a short, a float and a double at once, since how the game stores a duration
                    // is precisely what we are trying to find out.
                    string report;
                    if (text.StartsWith("#", StringComparison.Ordinal))
                    {
                        // "#" alone searches the three ways six minutes could be stored:
                        // milliseconds (the unit the game keeps its own race clock in), frames at
                        // sixty a second (the unit it keeps yaw and speed delta in), and
                        // centiseconds. A list is accepted too: "#360000,21600".
                        string body = text.Substring(1).Trim();
                        double[] values = body.Length == 0
                            ? new double[] { 360000, 21600, 36000 }
                            : ParseNumberList(body);
                        report = values.Length == 0
                            ? "could not read any numbers from " + body + "."
                            : filler.ScanForNumbers(values, 256);
                    }
                    else if (text.StartsWith("~", StringComparison.Ordinal))
                    {
                        // "~139932" is a time in MILLISECONDS, searched as a range rather than a
                        // value: milliseconds and centiseconds as integers, seconds as a float and
                        // a double, and frames. An exact search for a known lap time found nothing,
                        // which is what a duration accumulated in floating point looks like.
                        double ms;
                        report = double.TryParse(text.Substring(1).Trim(),
                                     System.Globalization.NumberStyles.Float,
                                     System.Globalization.CultureInfo.InvariantCulture, out ms)
                            ? filler.ScanForTime(ms, 32)
                            : "could not read a millisecond value from " + text.Substring(1) + ".";
                    }
                    else if (text.StartsWith("@", StringComparison.Ordinal))
                    {
                        // "@2,19,932" looks for those values sitting NEAR one another, which is how
                        // a record holding minutes, seconds and milliseconds separately would look.
                        // No single one of them is findable on its own; together they are rare.
                        double[] parts = ParseNumberList(text.Substring(1));
                        report = parts.Length < 2
                            ? "give at least two values, like @2,19,932."
                            : filler.ScanForCluster(parts, 64, 32);
                    }
                    else report = filler.ScanForString(text, 64);
                    SimHub.Logging.Current.Info("[TF4ALL] ID8 search for '" + text + "': " + report);
                }
                catch (Exception ex)
                {
                    SimHub.Logging.Current.Info("[TF4ALL] ID8 search for '" + text + "' failed: " + ex.Message);
                }
            });
            return "Searching " + attachedTo + " for '" + text + "'. Watch the log; it takes a few seconds.";
        }

        /// <summary>How to SAY a game identity, as opposed to how to file it.
        ///
        /// An arcade identity is "Arcade " plus TeknoParrot's profile id, a short code like
        /// ID8. A custom game's identity is the guid SimHub files it under. Neither can be
        /// prettied up in place: both are the preset key and the car-folder name, so
        /// changing one re-files everything a user has tuned. The screen is free to say the
        /// real title instead, and that is all this does.
        ///
        /// A custom game profile made for a cabinet IS that cabinet, running or not, so it
        /// is named as one. Failing that, SimHub's own name for the profile beats a guid for
        /// any custom game at all. Anything else falls through to the shared display map.
        ///
        /// Memoised on the last identity asked about. The old version read every TeknoParrot
        /// profile XML off disk per call, and the caller is a UI refresh on a timer.</summary>
        public string ArcadeDisplayName(string gameIdentity)
        {
            if (string.IsNullOrEmpty(gameIdentity)) return gameIdentity;
            if (string.Equals(gameIdentity, _gameTitleKey, StringComparison.Ordinal))
                return _gameTitleValue;

            string title = ComputeGameTitle(gameIdentity);
            _gameTitleKey = gameIdentity;
            _gameTitleValue = title;
            return title;
        }

        private string _gameTitleKey, _gameTitleValue;

        private string ComputeGameTitle(string gameIdentity)
        {
            try
            {
                if (gameIdentity.StartsWith("Arcade ", StringComparison.Ordinal))
                {
                    foreach (var t in ArcadeModTargets())
                    {
                        if (string.IsNullOrEmpty(t.FullName)) continue;
                        if (string.Equals(ArcadeGameName(t.ProfileName), gameIdentity, StringComparison.Ordinal))
                            return t.FullName;
                    }
                    return gameIdentity;
                }

                if (gameIdentity.StartsWith("Custom_", StringComparison.OrdinalIgnoreCase))
                {
                    // The cabinet's own title, where this profile runs one. True with
                    // the game closed, because the match is on the program a profile
                    // is configured to launch rather than on anything running.
                    string profile = ProfileForCustomGame(gameIdentity);
                    if (!string.IsNullOrEmpty(profile))
                    {
                        foreach (var t in ArcadeModTargets())
                            if (string.Equals(t.ProfileName, profile, StringComparison.OrdinalIgnoreCase)
                                && !string.IsNullOrEmpty(t.FullName))
                                return t.FullName;
                        return ArcadeGameName(profile);
                    }

                    // Not a cabinet, but SimHub still knows what the user called it.
                    var info = TryGetCustomGameInfo(gameIdentity);
                    if (!string.IsNullOrEmpty(info?.Name)) return info.Name;
                    return gameIdentity;
                }
            }
            catch { }

            return GameNames.Display(gameIdentity);
        }

        /// <summary>The game identity for a TeknoParrot profile. Kept path-safe and
        /// free of the "Custom_" prefix, because it becomes a preset key and a car
        /// folder name, and that prefix makes HasUsefulTelemetry read false.</summary>
        public static string ArcadeGameName(string profileName)
            => "Arcade " + (profileName ?? "").Replace('\\', ' ').Replace('/', ' ').Replace(':', ' ').Trim();

        /// <summary>True when TeknoParrot's cabinet IO block exists. Read-only, and
        /// opened then immediately closed: a presence test, not the reader.</summary>
        private static bool ArcadeBlockPresent()
        {
            string[] names =
            {
                "TeknoParrot_JvsState",
                "Local\\TeknoParrot_JvsState",
                "Global\\TeknoParrot_JvsState",
            };
            for (int i = 0; i < names.Length; i++)
            {
                try
                {
                    using (System.IO.MemoryMappedFiles.MemoryMappedFile.OpenExisting(
                               names[i], System.IO.MemoryMappedFiles.MemoryMappedFileRights.Read))
                        return true;
                }
                catch { }
            }
            return false;
        }

        /// <summary>Push the active cabinet's tuning at whichever arcade source is
        /// running, so a slider takes effect now rather than at the next launch.</summary>
        public void ApplyArcadeTuning()
        {
            _arcadeWaveGainDirty = true;
            var src = _teknoSource as IArcadeForceSource;
            if (src == null) return;
            var t = ArcadeTuningPeek(_activeGame);
            try { src.ApplyTuning(t.ForceScale, t.InvertDirection, t.AcceptPublishedDamper); } catch { }
        }

        /// <summary>True for any identity produced by arcade detection.</summary>
        private bool IsArcadeGameName(string game)
        {
            if (string.IsNullOrEmpty(game)) return false;
            if (string.Equals(game, GenericArcadeGameName, StringComparison.Ordinal)) return true;
            if (game.StartsWith("Arcade ", StringComparison.Ordinal)) return true;
            var g = Settings?.Arcade?.Games;
            if (g == null) return false;
            foreach (var kv in g)
                if (string.Equals(kv.Value, game, StringComparison.Ordinal)) return true;
            return false;
        }

        /// <summary>The tuning for one arcade identity WITHOUT storing anything.
        /// Use this to read: ArcadeTuningFor creates an entry as a side effect, so
        /// calling it from the settings refresh would seed a saved tuning for every
        /// game the user ever runs.</summary>
        public ArcadeGameTuning ArcadeTuningPeek(string game)
        {
            var s = Settings?.Arcade;
            ArcadeGameTuning t = null;
            if (s?.Tuning != null && !string.IsNullOrEmpty(game)) s.Tuning.TryGetValue(game, out t);
            return t ?? new ArcadeGameTuning();
        }

        /// <summary>The tuning for one arcade identity, created on first use so a
        /// control can write to it. Per cabinet, never global: these decoders scale
        /// their magnitudes by anything from 9 to 1000.</summary>
        public ArcadeGameTuning ArcadeTuningFor(string game)
        {
            var s = Settings?.Arcade;
            if (s == null) return new ArcadeGameTuning();
            if (s.Tuning == null)
                s.Tuning = new Dictionary<string, ArcadeGameTuning>(StringComparer.OrdinalIgnoreCase);
            string key = string.IsNullOrEmpty(game) ? GenericArcadeGameName : game;
            ArcadeGameTuning t;
            if (!s.Tuning.TryGetValue(key, out t) || t == null)
            {
                t = NewArcadeTuningFor(key);
                s.Tuning[key] = t;
            }
            return t;
        }

        /// <summary>A cabinet's opening tuning. Everything defaults to "do what
        /// the game's own settings say" except where we have measured that those
        /// settings are wrong for it.
        ///
        /// The one entry here is Initial D 8, and it is not a preference. The
        /// cabinet commands a steering force of zero while the car slides, which
        /// the reference plugin's decoder discards, so the previous force stands
        /// until its length runs out. That game ships FeedbackLength=5000, so out
        /// of the box the wheel keeps pushing for five seconds after the game said
        /// to stop. Measured from the cabinet's own IO block, 2026-09-07: 937
        /// readings across one lapse, every one of them the steering opcode, 930
        /// of them asking for zero.
        ///
        /// Deliberately a table rather than a rule. Ninety other cabinets go
        /// through this path and none of them have been measured, so they keep
        /// deferring to whatever their own author chose.</summary>
        private static ArcadeGameTuning NewArcadeTuningFor(string key)
        {
            var t = new ArcadeGameTuning();
            if (string.Equals(key, "Arcade ID8", StringComparison.OrdinalIgnoreCase))
                t.SteeringHoldMs = ArcadeFaithfulHoldMs;
            return t;
        }

        /// <summary>The steady-force hold a measured cabinet opens on, in
        /// milliseconds. Short enough that the wheel releases as soon as the game
        /// stops asking, which for Initial D 8 is what it actually commands.</summary>
        internal const int ArcadeFaithfulHoldMs = 50;

        private void SwapTelemetrySource(string game, bool silent = false)
        {
            lock (_sourceSwapLock) SwapTelemetrySourceLocked(game, silent);
        }

        private void SwapTelemetrySourceLocked(string game, bool silent)
        {
            // Normal only, checked HERE because this is the chokepoint every source
            // creation passes through. Gating only the game-change caller left three
            // ungated ways in (a Forza port or bind edit, an account switch and a
            // backup restore all call ApplyForzaSettings), each of which would bind
            // UDP 5300 and wire DispatchFrame in a mode that promises no telemetry,
            // and once bound nothing tore it down again for the rest of the session.
            if (MasterMode != TrueforceMasterMode.Normal) return;

            bool gameIsForza = IsForzaGameName(game);
            ITelemetrySource newSource = null;
            if (game == "AssettoCorsa")
            {
                var ac = new AcSharedMemoryTelemetrySource
                {
                    Logger = msg => SimHub.Logging.Current.Info($"[TF4ALL] {msg}"),
                    // Force from AC itself: arm the finalFF latch at
                    // construction so a session that starts with the path on
                    // Both latches are armed unconditionally for AC. The CSP
                    // bridge only supplies when its script is installed and
                    // running (otherwise the map is never fresh and the provider
                    // uses the tap), so arming it always is what makes the AC
                    // force automatic. The finalFF latch backs the dev "finalff"
                    // field.
                    FfbLatchEnabled = true,
                    CspBridgeLatchEnabled = true,
                    CspField = ParseCspField(Settings?.CspBridgeFfbField),
                    CspMaxNm = Settings?.CspBridgeMaxNm ?? 10.0,
                };
                try
                {
                    ac.Start();
                    newSource = ac;
                }
                catch (Exception ex)
                {
                    try { ac.Dispose(); } catch { }
                    if (!silent)
                    {
                        SimHub.Logging.Current.Warn(
                            $"[TF4ALL] AC enhanced source unavailable ({ex.GetType().Name}): {ex.Message}; falling back to SimHub.");
                    }
                }
            }
            else if (gameIsForza)
            {
                // The Forza UDP reader is the only source of Forza's per-tire
                // surface / kerb / cylinder data, so it is always on for Forza
                // (no user toggle). It binds only while a Forza title is the
                // active game; a port conflict falls back to SimHub below.
                // Created once and kept alive for the whole Forza session (see
                // _forzaUdp): even if it never receives a packet we hold it so
                // EvaluateForzaTelemetryFallback can upgrade back to it the
                // instant Forza's Data Out is pointed at our port.
                if (_forzaUdp == null)
                {
                    try
                    {
                        var bindIp = ParseIpOrAny(Settings.Forza.BindAddress);
                        var forwardTo = BuildForzaForwardEndpoint(Settings.Forza);
                        var fz = new ForzaUdpTelemetrySource(Settings.Forza.Port, bindIp, forwardTo)
                        {
                            Logger = msg => SimHub.Logging.Current.Info($"[TF4ALL] {msg}"),
                        };
                        fz.GapBridge.Enabled = Settings.Forza.ForwardGapBridge;
                        fz.Start();
                        _forzaUdp = fz;
                        _forzaUdpConfigKey = CurrentForzaConfigKey();
                    }
                    catch (Exception ex)
                    {
                        if (!silent)
                        {
                            SimHub.Logging.Current.Warn(
                                $"[TF4ALL] Forza UDP source unavailable on port {Settings.Forza.Port} " +
                                $"({ex.GetType().Name}): {ex.Message}; falling back to SimHub. " +
                                "If another listener (SimHub itself, Sim Racing Studio) holds the port, change Trueforce's port to a free one and re-point Forza's Data Out to it.");
                        }
                    }
                }
                // Attach the enhanced source optimistically.
                // EvaluateForzaTelemetryFallback (called each data tick) demotes
                // to the SimHub fallback within a tick if it stays silent while
                // SimHub is the one actually receiving Forza's telemetry.
                if (_forzaUdp != null) newSource = _forzaUdp;
            }
            else if (game != null && game.StartsWith("FarmingSimulator", StringComparison.Ordinal))
            {
                // Farming Simulator's enhanced source is the TF4ALL Enhanced Telemetry
                // game mod's pipe. Kept alive for the whole FS session even
                // with no client (one parked thread), so the mod connecting
                // mid-session upgrades within a tick; a silent pipe demotes to
                // the SimHub fallback the same way a silent Forza UDP does
                // (EvaluateFsTelemetryFallback).
                if (_fsPipeSource == null)
                {
                    try
                    {
                        var fs = new FarmingSimulatorTelemetrySource
                        {
                            Logger = msg => SimHub.Logging.Current.Info($"[TF4ALL] {msg}"),
                        };
                        fs.Start();
                        _fsPipeSource = fs;
                    }
                    catch (Exception ex)
                    {
                        if (!silent)
                            SimHub.Logging.Current.Warn(
                                $"[TF4ALL] Farming Simulator enhanced source unavailable ({ex.GetType().Name}): {ex.Message}; falling back to SimHub.");
                    }
                }
                if (_fsPipeSource != null) newSource = _fsPipeSource;
            }
            // Belt and braces against the naming gate above: a user is free to call a SimHub
            // profile "InitialD8" by hand, and a locked build must not build an arcade source
            // for it.
            else if (ArcadeUnlocked && IsArcadeGameName(game))
            {
                // The arcade reader opens TeknoParrot's cabinet IO block lazily on
                // its own thread, so unlike the AC source it never throws from
                // Start() and needs no 1 Hz re-acquire retry: the game can be
                // detected before TeknoParrot has published, and the reader simply
                // waits. Kept alive for the session like the Forza and FS sources.
                if (_teknoSource == null)
                {
                    try
                    {
                        var arc = Settings?.Arcade;
                        // Per cabinet, never global: these decoders scale their
                        // magnitudes by anything from 9 to 1000, so one shared
                        // force scale would mean tuning one title detunes the next.
                        var tune = ArcadeTuningFor(game);
                        // Two ways in, and the better one wins automatically.
                        // A publishing build of FFBArcadePlugin has already
                        // decoded the cabinet for us and covers roughly ninety
                        // games including the many whose forces are not in the IO
                        // block at all; reading the block ourselves reaches only
                        // the dozen we have written decoders for. So prefer the
                        // publisher whenever it is actually running.
                        if (FfbArcadePluginSource.Present(arc?.PublisherMapName))
                        {
                            var pub = new FfbArcadePluginSource
                            {
                                Logger = msg => SimHub.Logging.Current.Info($"[TF4ALL] {msg}"),
                                MapName = arc?.PublisherMapName,
                                ForceScale = tune.ForceScale,
                                InvertConstantDirection = tune.InvertDirection,
                                AcceptPublishedDamper = tune.AcceptPublishedDamper,
                                MinForce01 = (Settings?.Arcade?.MinForcePercent ?? 0) / 100.0,
                                // Stored under its original name; see ArcadeGameTuning.
                                SteadyHoldMs    = ClampArcadeHold(tune.SteeringHoldMs),
                                VibrationHoldMs = ClampArcadeHold(tune.VibrationHoldMs),
                            };
                            pub.Start();
                            _teknoSource = pub;
                        }
                        else
                        {
                            var tp = new TeknoParrotJvsTelemetrySource
                            {
                                Logger = msg => SimHub.Logging.Current.Info($"[TF4ALL] {msg}"),
                                ForceScale = tune.ForceScale,
                                InvertConstantDirection = tune.InvertDirection,
                                // Every cabinet encodes its command differently and
                                // the block says nothing about which game wrote it,
                                // so the protocol has to be chosen, not sniffed.
                                GameId = tune.GameId != 0 ? tune.GameId : 18,
                                SlotOverride = tune.FfbSlotOverride,
                            };
                            tp.Start();
                            _teknoSource = tp;
                        }
                    }
                    catch (Exception ex)
                    {
                        if (!silent)
                            SimHub.Logging.Current.Warn(
                                $"[TF4ALL] Arcade source unavailable ({ex.GetType().Name}): {ex.Message}.");
                    }
                }
                if (_teknoSource != null) newSource = _teknoSource;
            }
            if (newSource == null) newSource = _simHubSource;

            if (newSource != _telemetrySource)
            {
                // Detach old's dispatch BEFORE attaching new's so DispatchFrame is
                // never invoked from two threads concurrently. Both fields are
                // ref-typed; .NET guarantees torn-tear-safe writes.
                var old = _telemetrySource;
                if (old != null) old.OnFrame = null;
                newSource.OnFrame = DispatchFrame;
                _telemetrySource = newSource;

                // Reset port-discovery state on every source swap so a fresh
                // start (Forza was idle or just launched, port changed in
                // settings, etc.) restarts the discovery cycle.
                _discoverySourceStartedTicks = Stopwatch.GetTimestamp();
                _discoveryNextAttemptTicks   = 0;
                _discoverySourceKey = newSource;
                System.Threading.Volatile.Write(ref _discoveredAlternatePort, 0);

                // Dispose the previous enhanced source. _simHubSource is the
                // long-lived fallback and the Forza listener (_forzaUdp) is torn
                // down separately below; neither is disposed here.
                if (old != null && old != _simHubSource && old != _forzaUdp
                    && old != _fsPipeSource && old != _teknoSource && old != newSource)
                {
                    try { old.Dispose(); } catch { }
                }

                SimHub.Logging.Current.Info(
                    $"[TF4ALL] Telemetry source: {newSource.Name} (enhanced={newSource.IsEnhanced}).");
            }

            // Leaving Forza: tear down the keep-alive UDP listener now that the
            // active source has been swapped off it above.
            if (!gameIsForza && _forzaUdp != null)
            {
                try { _forzaUdp.Dispose(); } catch { }
                _forzaUdp = null;
                _forzaOnSimHubFallback = false;
            }

            // Leaving Farming Simulator: same for the keep-alive pipe server.
            bool gameIsFs = game != null && game.StartsWith("FarmingSimulator", StringComparison.Ordinal);
            if (!gameIsFs && _fsPipeSource != null)
            {
                try { _fsPipeSource.Dispose(); } catch { }
                _fsPipeSource = null;
            }

            // Leaving an arcade game: same again. This is what closes the shared
            // memory block when the cabinet exits. The synthetic name goes null the
            // moment TeknoParrot stops publishing, which fires the game-change
            // block, which lands here.
            if (!IsArcadeGameName(game) && _teknoSource != null)
            {
                try { _teknoSource.Dispose(); } catch { }
                _teknoSource = null;
            }
        }

        // Choose between the enhanced Forza UDP source and the SimHub fallback
        // based on which is actually receiving telemetry. Called every data tick
        // while a Forza title is active (cheap: a couple of field reads). This is
        // what prevents a dead wheel when a user's Forza "Data Out" is pointed at
        // SimHub's port instead of ours: the Forza listener binds but never
        // receives, so without this we'd sit on a silent source that reports
        // "paused" forever and the pause-release would hold the wheel at zero.
        private void EvaluateForzaTelemetryFallback()
        {
            var fz = _forzaUdp;
            if (fz == null) { _forzaOnSimHubFallback = false; return; }   // not a Forza session

            if (fz.PacketsReceived > 0)
            {
                // Forza UDP is receiving: use (or return to) the enhanced source.
                if (_telemetrySource != fz)
                {
                    var old = _telemetrySource;
                    if (old != null) old.OnFrame = null;
                    fz.OnFrame = DispatchFrame;
                    _telemetrySource = fz;
                    _discoverySourceStartedTicks = Stopwatch.GetTimestamp();
                    _discoveryNextAttemptTicks   = 0;
                    _discoverySourceKey = fz;
                    SimHub.Logging.Current.Info(
                        "[TF4ALL] Forza telemetry now reaching the plugin; using the enhanced Forza (UDP) source.");
                }
                _forzaOnSimHubFallback = false;
                return;
            }

            // Forza UDP is bound but silent. If SimHub is receiving Forza's
            // telemetry instead (Data Out pointed at SimHub, not us), run on the
            // SimHub fallback so force feedback + core effects keep working.
            if (_simHubSource != null && _simHubSource.MeasuredHz > 0)
            {
                if (_telemetrySource != _simHubSource)
                {
                    var old = _telemetrySource;
                    if (old != null) old.OnFrame = null;
                    _simHubSource.OnFrame = DispatchFrame;
                    _telemetrySource = _simHubSource;
                    SimHub.Logging.Current.Info(
                        "[TF4ALL] Forza telemetry is reaching SimHub but not the plugin; using the SimHub fallback. " +
                        "Point Forza's Data Out at the plugin (and forward to SimHub) for more detailed road/airborne feel.");
                }
                _forzaOnSimHubFallback = true;
            }
            // else: neither source has telemetry yet (startup, or Data Out not
            // set up anywhere). Stay on the optimistic enhanced source and leave
            // the fallback flag as-is; the no-telemetry setup banner covers it.
        }

        // The same decision for Farming Simulator: the enhanced pipe source
        // while the TF4ALL Enhanced Telemetry game mod is feeding it, the SimHub
        // fallback otherwise (mod not installed / not enabled). Upgrades back
        // within a tick of the mod's first frame, so installing or enabling
        // it mid-session needs no restart.
        // True once the pipe fed a frame for the CURRENT game session; reset
        // on game change. Distinguishes "mod not installed" (fast SimHub
        // fallback) from "pipe died mid-session" (game closing; long dwell).
        private bool _fsPipeFedThisGame;
        private void EvaluateFsTelemetryFallback()
        {
            var fs = _fsPipeSource;
            if (fs == null) return;                        // not an FS session

            if (fs.MsSinceLastFrame < 2000)
            {
                // Flag on FRAMES, not on the swap transition: when the
                // enhanced source is attached optimistically at game start
                // the upgrade branch below never runs, and a transition-set
                // flag stayed false, so the long close dwell never engaged
                // and the 03:22 game-close pull came back (2026-08-08).
                _fsPipeFedThisGame = true;
                if (_telemetrySource != fs)
                {
                    var old = _telemetrySource;
                    if (old != null) old.OnFrame = null;
                    fs.OnFrame = DispatchFrame;
                    _telemetrySource = fs;
                    SimHub.Logging.Current.Info(
                        "[TF4ALL] TF4ALL Enhanced Telemetry game mod is feeding the plugin; using the enhanced Farming Simulator source.");
                }
                return;
            }

            // A pipe that WAS feeding and went silent is a game shutting down
            // (or a mod crash), not a missing mod. Swapping to the SimHub
            // fallback after only 2 s re-attached DispatchFrame to SimHub's
            // zombie stream (it keeps re-emitting the game's frozen GameData
            // for seconds after process death), which re-stamped telemetry
            // freshness and ramped the just-cut synthetic spring back in:
            // trace-proven as the 02:28:06 game-close pull (2026-08-08). Sit
            // out a long dwell instead; a genuine mid-session mod death still
            // falls back, just 15 s later, while a game close is fully torn
            // down (SimHub frames stop too) long before the dwell elapses.
            long dwellMs = _fsPipeFedThisGame ? 15000 : 2000;
            if (fs.MsSinceLastFrame < dwellMs) return;

            if (_simHubSource != null && _simHubSource.MeasuredHz > 0
                && _telemetrySource != _simHubSource)
            {
                var old = _telemetrySource;
                if (old != null) old.OnFrame = null;
                _simHubSource.OnFrame = DispatchFrame;
                _telemetrySource = _simHubSource;
                SimHub.Logging.Current.Info(
                    "[TF4ALL] TF4ALL Enhanced Telemetry game mod not detected; using the SimHub fallback. " +
                    "Install the mod for terrain feel and physics-rate telemetry.");
            }
        }

        // ---------- Port discovery ----------

        // Polled from DataUpdate. Triggers a scan when:
        //   - The active source is a UDP source (Forza).
        //   - It's been running for >DiscoveryNoPacketsTriggerMs without
        //     receiving any packets.
        //   - The retry-interval gate has elapsed (DiscoveryRetryIntervalMs
        //     between attempts) so we keep trying if the user enables UDP
        //     in the game minutes after Trueforce starts.
        // Runs each scan on a background thread so the SimHub data tick
        // isn't blocked. _discoveryScanInFlight prevents overlapping runs.
        private bool _discoveryScanInFlight;
        private void MaybeStartPortDiscovery()
        {
            if (_discoveryScanInFlight) return;

            var src = _telemetrySource;
            if (src == null || src != _discoverySourceKey) return;

            // Source must be a UDP one with a "received N packets" counter
            // we can read. AC's MMF source and the SimHub fallback don't
            // benefit from port discovery.
            long received;
            int[] candidates;
            int currentPort;
            string kind;
            Func<byte[], int, bool> validator;
            if (src is ForzaUdpTelemetrySource fz)
            {
                received    = fz.PacketsReceived;
                candidates  = ForzaUdpTelemetrySource.DiscoveryCandidatePorts;
                currentPort = Settings?.Forza?.Port ?? 0;
                validator   = ForzaUdpTelemetrySource.IsValidPacketCandidate;
                kind        = "forza";
            }
            else return;

            if (received > 0) return;

            long now = Stopwatch.GetTimestamp();
            // First attempt: source must have been running at least
            // DiscoveryNoPacketsTriggerMs. Subsequent attempts: gated by
            // _discoveryNextAttemptTicks (set by the previous attempt's
            // completion).
            if (_discoveryNextAttemptTicks == 0)
            {
                long elapsedMs = (now - _discoverySourceStartedTicks) * 1000L / Stopwatch.Frequency;
                if (elapsedMs < DiscoveryNoPacketsTriggerMs) return;
            }
            else if (now < _discoveryNextAttemptTicks)
            {
                return;
            }

            // Filter the candidate list to skip the user's currently-configured
            // port, we already know that one isn't receiving (received==0).
            var filtered = new List<int>(candidates.Length);
            foreach (int p in candidates) if (p != currentPort) filtered.Add(p);
            if (filtered.Count == 0) return;

            _discoveryScanInFlight = true;

            var bindIp = ParseIpOrAny(Settings?.Forza?.BindAddress);
            System.Threading.Tasks.Task.Run(() =>
            {
                int hit = 0;
                try
                {
                    hit = UdpPortScanner.Scan(filtered, bindIp, validator,
                        DiscoveryScanTimeoutMs, System.Threading.CancellationToken.None);
                }
                catch (Exception ex)
                {
                    SimHub.Logging.Current.Warn($"[TF4ALL] Port discovery error: {ex.GetType().Name}: {ex.Message}");
                }
                finally
                {
                    _discoveryScanInFlight = false;
                    // Schedule the next allowed attempt. If the user has
                    // already adopted a discovered port and the source is
                    // now receiving packets, the receive-check at the top
                    // of MaybeStartPortDiscovery will short-circuit; we
                    // still set the gate so any future "back to zero"
                    // window has a fresh deadline rather than firing
                    // immediately.
                    _discoveryNextAttemptTicks = Stopwatch.GetTimestamp()
                        + Stopwatch.Frequency * DiscoveryRetryIntervalMs / 1000L;
                }

                if (hit > 0)
                {
                    System.Threading.Volatile.Write(ref _discoveredAlternatePort, hit);
                    SimHub.Logging.Current.Info(
                        $"[TF4ALL] Detected {kind} packets on alternate port {hit}.");
                    try { AlternatePortDiscovered?.Invoke(kind, hit); } catch { }
                }
            });
        }

        /// <summary>UI hook: switch the Forza listener to the
        /// just-discovered port and persist. Returns true if the switch
        /// was applied.</summary>
        public bool AdoptDiscoveredAlternatePort()
        {
            int port = DiscoveredAlternatePort;
            if (port <= 0 || Settings == null) return false;

            var src = _telemetrySource;
            if (src is ForzaUdpTelemetrySource && Settings.Forza != null)
            {
                Settings.Forza.Port = port;
                ApplyForzaSettings();
            }
            else return false;

            System.Threading.Volatile.Write(ref _discoveredAlternatePort, 0);
            return true;
        }

        /// <summary>UI hook: dismiss the discovered-port banner without
        /// switching. Suppresses re-discovery for the remainder of this
        /// source instance.</summary>
        public void DismissDiscoveredAlternatePort()
        {
            System.Threading.Volatile.Write(ref _discoveredAlternatePort, 0);
        }

        // 0.0.0.0 / blank / unparseable → IPAddress.Any so the listener accepts
        // packets on every local interface. Specific IPs are honored as-is.
        private static IPAddress ParseIpOrAny(string s)
        {
            if (string.IsNullOrWhiteSpace(s)) return IPAddress.Any;
            return IPAddress.TryParse(s.Trim(), out var ip) ? ip : IPAddress.Any;
        }

        // Build the forward endpoint used by ForzaUdpTelemetrySource.
        // Returns null when forwarding is disabled or the user's host/port is
        // invalid, the source treats null as "don't forward." Hostname (vs
        // IP) lookups go through Dns.GetHostAddresses so users can type
        // "localhost" or a NAS hostname; first resolved address wins.
        private static IPEndPoint BuildForzaForwardEndpoint(ForzaSettings fs)
        {
            if (fs == null || !fs.ForwardEnabled) return null;
            if (fs.ForwardPort < 1 || fs.ForwardPort > 65535) return null;
            string host = string.IsNullOrWhiteSpace(fs.ForwardHost) ? "127.0.0.1" : fs.ForwardHost.Trim();
            try
            {
                if (IPAddress.TryParse(host, out var ip))
                    return new IPEndPoint(ip, fs.ForwardPort);
                var addrs = System.Net.Dns.GetHostAddresses(host);
                foreach (var a in addrs)
                {
                    if (a.AddressFamily == System.Net.Sockets.AddressFamily.InterNetwork)
                        return new IPEndPoint(a, fs.ForwardPort);
                }
            }
            catch { }
            return null;
        }

        /// <summary>UI hook: persist the Forza section and rebind the listener
        /// when needed. Settings are saved unconditionally. The source is
        /// rebuilt whenever either (a) a Forza source is currently running
        /// (so port/bind/forward changes take effect, or a disable tears it
        /// down) or (b) a Forza title is the active game (so a port/bind
        /// change applies without waiting for a game change).
        /// <paramref name="onlyIfChanged"/>=true (bulk re-apply paths: slot
        /// mount, backup restore) skips the rebuild when the live listener was
        /// built from an identical config, so those paths never disturb a
        /// healthy stream.</summary>
        public void ApplyForzaSettings(bool onlyIfChanged = false)
        {
            if (Settings?.Forza == null) return;
            PersistSettingsCore();
            // The settings are saved in every mode; the LISTENER is a full-mode
            // thing. Returning here rather than further in also keeps the null
            // _simHubSource below out of reach, since nothing outside full has one.
            if (MasterMode != TrueforceMasterMode.Normal) return;

            lock (_sourceSwapLock)
            {
                // Test against the keep-alive listener, not the active source: while
                // on the SimHub fallback _telemetrySource is SimHub even though a
                // Forza listener is still bound and needs rebuilding.
                bool currentlyForza = _forzaUdp != null;
                bool shouldListen   = !string.IsNullOrEmpty(_activeGame) && IsForzaGameName(_activeGame);
                if (!currentlyForza && !shouldListen) return;

                string currentKey = CurrentForzaConfigKey();

                // Bulk re-apply paths (slot mount, backup restore) usually leave the
                // Forza config untouched; keep the healthy listener in place then
                // rather than blipping telemetry mid-drive with a dispose/rebind.
                // Explicit UI edits keep the unconditional rebuild (a re-typed port
                // stays a usable "kick the listener" gesture).
                if (onlyIfChanged && _forzaUdp != null
                    && string.Equals(currentKey, _forzaUdpConfigKey, StringComparison.Ordinal))
                    return;

                // Forward-only change (same receive port+bind; only the forward
                // endpoint and/or gap bridge differ): update the forward on the
                // LIVE source instead of tearing the listener down. Rebinding the
                // receive port while SimHub is also bound to it hands Forza's
                // datagrams to SimHub until a plugin restart, which cuts our
                // telemetry — and in Mode B, where the only force is synthesized
                // from that telemetry, the wheel goes dead (reported: "toggling
                // udp forward mid-play cuts ffb and tf until i restart the
                // plugin"). The forward is a separate send-only socket, so it can
                // change with zero disturbance to the stream feeding the effects.
                if (_forzaUdp != null
                    && !string.Equals(currentKey, _forzaUdpConfigKey, StringComparison.Ordinal)
                    && string.Equals(BindPrefixOf(currentKey), BindPrefixOf(_forzaUdpConfigKey),
                                     StringComparison.Ordinal))
                {
                    try
                    {
                        _forzaUdp.GapBridge.Enabled = Settings.Forza.ForwardGapBridge;
                        _forzaUdp.UpdateForward(BuildForzaForwardEndpoint(Settings.Forza));
                        _forzaUdpConfigKey = currentKey;
                        return;
                    }
                    catch
                    {
                        // Anything unexpected: fall through to the full rebuild,
                        // which re-establishes receive and forward from scratch.
                    }
                }

                // Tear the Forza listener down so SwapTelemetrySource rebuilds it
                // with the new port/bind/forward settings. Route the active source
                // back to the SimHub fallback first (if it was the enhanced one) so
                // the dispose runs cleanly; SwapTelemetrySource re-attaches and
                // EvaluateForzaTelemetryFallback re-evaluates from there.
                if (_forzaUdp != null)
                {
                    if (_telemetrySource == _forzaUdp)
                    {
                        _forzaUdp.OnFrame = null;
                        // Null-guarded: the fallback only exists in full mode, and
                        // this used to be an unconditional dereference.
                        if (_simHubSource != null) _simHubSource.OnFrame = DispatchFrame;
                        _telemetrySource = _simHubSource;
                    }
                    try { _forzaUdp.Dispose(); } catch { }
                    _forzaUdp = null;
                    _forzaOnSimHubFallback = false;
                }
                SwapTelemetrySourceLocked(_activeGame, silent: false);
            }
        }

        // Fingerprint of the settings ForzaUdpTelemetrySource is constructed
        // from (port, bind, forward endpoint, gap bridge). Matches the live
        // listener's stamp (_forzaUdpConfigKey) when a rebuild would produce
        // an identical source.
        private string CurrentForzaConfigKey()
        {
            var f = Settings?.Forza;
            if (f == null) return "";
            try
            {
                var fwd = BuildForzaForwardEndpoint(f);
                return f.Port + "|" + ParseIpOrAny(f.BindAddress) + "|"
                     + (fwd == null ? "" : fwd.ToString()) + "|" + f.ForwardGapBridge;
            }
            catch { return ""; }
        }

        // "port|bind|forward|gapbridge" -> "port|bind". Lets ApplyForzaSettings
        // tell a forward-only edit (same receive port+bind, so no rebind needed)
        // from one that must rebind the listener. Neither a port nor a dotted IP
        // contains '|', so the receive-key prefix is unambiguous.
        private static string BindPrefixOf(string configKey)
        {
            if (string.IsNullOrEmpty(configKey)) return configKey;
            int first = configKey.IndexOf('|');
            if (first < 0) return configKey;
            int second = configKey.IndexOf('|', first + 1);
            return second < 0 ? configKey : configKey.Substring(0, second);
        }

        public Control GetWPFSettingsControl(PluginManager pluginManager) => new SettingsControl(this);

        // ---------- per-car overrides (per-section) ----------

        public CarOverride GetActiveCarOverride()
        {
            if (string.IsNullOrEmpty(_activeCarId) || Settings == null) return null;
            Settings.CarOverrides.TryGetValue(_activeCarId, out var o);
            return o;
        }

        /// <summary>Apply per-section overrides for the active car (or revert to globals).</summary>
        public void ApplyActiveCarOverride()
        {
            if (Settings == null) return;
            var ovr = GetActiveCarOverride();

            ApplyEngineSettings(ovr?.EnginePulse  ?? Settings.EnginePulse);
            ApplyBumpsSettings (ovr?.RoadBumps    ?? Settings.RoadBumps);
            ApplyTractionSettings(ovr?.TractionLoss ?? Settings.TractionLoss);
            ApplyAxleSlipSettings(ovr?.AxleSlip ?? Settings.AxleSlip);
            ApplyKerbThumpSettings(ovr?.KerbThump ?? Settings.KerbThump);
            ApplyLockupJudderSettings(ovr?.LockupJudder ?? Settings.LockupJudder);
            ApplyShiftSettings (ovr?.GearShift    ?? Settings.GearShift);
            ApplyAbsSettings   (ovr?.AbsClick     ?? Settings.AbsClick);
            ApplyPitLimiterSettings(ovr?.PitLimiter ?? Settings.PitLimiter);
            ApplyDrsSettings   (ovr?.Drs          ?? Settings.Drs);
            ApplyCollisionSettings(ovr?.Collision ?? Settings.Collision);
            ApplyRevLimiterSettings(ovr?.RevLimiter ?? Settings.RevLimiter);
            ApplyAudioCaptureSettings(ovr?.AudioCapture ?? Settings.AudioCapture);
            ApplyAirborneSettings();   // global, no per-car override
            ApplyImplementThudSettings();   // global, no per-car override
        }

        public void ApplyImplementThudSettings()
        {
            var s = GetActiveCarOverride()?.ImplementThud ?? Settings?.ImplementThud;
            if (ImplementThud == null || s == null) return;
            ImplementThud.Enabled  = s.Enabled;
            ImplementThud.Gain     = SafeMath.SafeFloat(s.Gain, 0.0f, 10.0f, 1.0f);
            ImplementThud.Freq     = SafeMath.SafeFloat(s.Freq, 20.0f, 100.0f, 30.0f);
            ImplementThud.RaiseAmp = SafeMath.SafeFloat(s.RaiseAmp, 0.0f, 1.0f, 0.6f);
            ImplementThud.HumAmp   = SafeMath.SafeFloat(s.HumAmp, 0.0f, 1.0f, 0.30f);
            ImplementThud.HumFreq  = SafeMath.SafeFloat(s.HumFreq, 20.0f, 150.0f, 46.0f);
            ImplementThud.BendDepth   = SafeMath.SafeFloat(s.BendDepth, 0.0f, 0.5f, 0.15f);
            ImplementThud.SpeedPitch  = SafeMath.SafeFloat(s.SpeedPitch, 0.0f, 0.5f, 0.12f);
            ImplementThud.HarmonicAmp = SafeMath.SafeFloat(s.HarmonicAmp, 0.0f, 0.8f, 0.22f);
            ImplementThud.SpeedVolume = SafeMath.SafeFloat(s.SpeedVolume, 0.0f, 1.0f, 0.5f);
            ImplementThud.Waveform = s.Waveform;
        }

        // ===================================================================
        // Per-car override DRAFT model (PILOT: RevLimiter).
        // While a car is loaded, slider edits land in the car's IN-MEMORY
        // override (created on first edit from the current effective value),
        // never the global default, so tuning one car can't leak to others.
        // Nothing persists until an explicit Save. _lastPersistedCarOverrides
        // is the saved baseline; the gap to Settings.CarOverrides is the unsaved
        // draft, which is discarded on car change.
        // ===================================================================

        // Called before a section edit: ensure the car's in-memory override has
        // THIS section (seeded from the current effective value) so the edit
        // writes to the car, not the global. No-op with no car loaded (edits
        // then target the global default, as intended) or for non-car sections.
        public void EnsureSectionDraft(SectionKind kind)
        {
            if (!string.IsNullOrEmpty(_activeCarId) && SectionHasCarScope(kind))
                SnapshotSectionToCarOverride(kind);   // creates the section from global only when absent
        }

        // "Reset to default" draft: drop THIS section's override in memory so it
        // previews the game default live. Not persisted; Save commits the
        // removal (follow default), Revert restores the saved override.
        public void ResetSectionToDefaultDraft(SectionKind kind)
        {
            if (string.IsNullOrEmpty(_activeCarId) || Settings?.CarOverrides == null) return;
            if (Settings.CarOverrides.TryGetValue(_activeCarId, out var ovr) && ovr != null)
            {
                ClearOverrideSection(ovr, kind);
                if (ovr.IsEmpty) Settings.CarOverrides.Remove(_activeCarId);
            }
            ApplyActiveCarOverride();
        }

        // Discard a car's UNSAVED draft (on car change): restore its in-memory
        // override from the persisted baseline, or drop it if nothing was saved.
        // Runs on the data thread's car-change path, so the structural mutation
        // of CarOverrides holds _carFactsLock: a concurrent settings serialize
        // (UI save, background flush) enumerating the dictionary mid-add/remove
        // would throw "Collection was modified".
        private void DiscardUnsavedCarDraft(string carId)
        {
            if (string.IsNullOrEmpty(carId) || Settings?.CarOverrides == null) return;
            lock (_carFactsLock)
            {
                if (_lastPersistedCarOverrides != null
                    && _lastPersistedCarOverrides.TryGetValue(carId, out var saved)
                    && saved != null && !saved.IsEmpty)
                    Settings.CarOverrides[carId] = CloneCarOverride(saved);
                else
                    Settings.CarOverrides.Remove(carId);
            }
        }

        // Revert THIS section's draft to the car's saved state (persisted
        // override, or the game default if none). No car loaded → revert the
        // global section to the active preset (existing behavior).
        /// <returns>true when there was actually a draft to revert; false
        /// when nothing changed (e.g. a global-only section with no active
        /// preset). The dash revert uses this so it doesn't toast "reverted"
        /// and clear the bar over an edit it never undid.</returns>
        public bool RevertSectionDraft(SectionKind kind)
        {
            if (string.IsNullOrEmpty(_activeCarId)) return RevertSection(kind);
            if (Settings?.CarOverrides == null) return false;
            CarOverride saved = null;
            _lastPersistedCarOverrides?.TryGetValue(_activeCarId, out saved);
            Settings.CarOverrides.TryGetValue(_activeCarId, out var ovr);
            bool reverted = false;
            if (OverrideHasSection(saved, kind))
            {
                if (ovr == null) { ovr = new CarOverride(); Settings.CarOverrides[_activeCarId] = ovr; }
                CopyOverrideSection(saved, ovr, kind);
                reverted = true;
            }
            else if (ovr != null && OverrideHasSection(ovr, kind))
            {
                ClearOverrideSection(ovr, kind);
                if (ovr.IsEmpty) Settings.CarOverrides.Remove(_activeCarId);
                reverted = true;
            }
            ApplyActiveCarOverride();
            return reverted;
        }

        // Save scope: the draft becomes the GAME DEFAULT and stays pinned to
        // this car (both the default and this car's override get the values).
        // Reuses PromoteSectionToGlobal (lift override -> global) but re-pins the
        // override afterward, then persists both the preset and the car file.
        public bool SaveSectionToBoth(SectionKind kind)
        {
            PromoteSectionToGlobal(kind);                  // global = override values; drops the override
            SnapshotSectionToCarOverride(kind);            // re-pin: override = global (the same values)
            bool okDefault = SaveSectionToActivePreset(kind);
            bool okCar     = SaveSectionToActiveCarOverride(kind);
            ApplyActiveCarOverride();
            return okDefault || okCar;
        }

        // Commit a "reset" draft: persist that this car has NO override for the
        // section (follows the game default). Patches the on-disk car file to
        // drop just this section.
        public bool CommitSectionFollowDefault(SectionKind kind)
        {
            ResetSectionToDefaultDraft(kind);                  // clear in-memory section (preview default)
            return RemoveSectionFromActiveCarOverrideFile(kind);
        }

        // Patch the active car's on-disk override file to DROP a section, so the
        // car follows the game default for it. Mirrors SaveSectionToActiveCarOverride
        // but clears the section and needs no live in-memory override.
        public bool RemoveSectionFromActiveCarOverrideFile(SectionKind kind)
        {
            if (_carStore == null || string.IsNullOrEmpty(_activeCarId)) return false;
            string presetName = GetActiveCarPresetName(_activeCarId);
            if (string.IsNullOrEmpty(presetName)) return false;
            bool isBuiltin = IsCarPresetBuiltin(_activeCarId, presetName);
            if (isBuiltin && !DevMode) return false;
            if (!_lastPersistedCarOverrides.TryGetValue(_activeCarId, out var prev) || prev == null)
                return true;   // nothing persisted -> already follows the default

            var patched = CloneCarOverride(prev);
            ClearOverrideSection(patched, kind);
            if (isBuiltin)
            {
                WriteCarBuiltinThroughDev(_activeCarId, presetName, patched);
            }
            else
            {
                if (!_carStore.Save(_activeCarId, presetName, _activeGame ?? "", patched, isBuiltin: false,
                        defaultAuthor: CurrentAuthorForStamp()))
                {
                    SimHub.Logging.Current.Warn($"[TF4ALL] Clearing {kind} override for '{_activeCarId}' failed to write (see prior log line); baseline unchanged.");
                    return false;
                }
                // The store KEEPS an empty-but-community-tracked file, so
                // the baseline must keep the (empty, tracked) entry too:
                // dropping it made the next section save rebuild from a
                // bare CarOverride and strip the community lineage.
                if (patched.IsEmpty && !patched.HasCommunityTracking)
                    _lastPersistedCarOverrides.Remove(_activeCarId);
                else
                    _lastPersistedCarOverrides[_activeCarId] = CloneCarOverride(patched);
            }
            SimHub.Logging.Current.Info($"[TF4ALL] Cleared {kind} override for '{_activeCarId}' (follows game default).");
            return true;
        }

        // For the save popover: is THIS section a "reset" draft (override cleared
        // in memory while one is still persisted)? Then Save means "follow the
        // game default" (commit the removal), not a scope choice.
        public bool IsSectionResetDraft(SectionKind kind)
        {
            if (string.IsNullOrEmpty(_activeCarId)) return false;
            CarOverride live = null, saved = null;
            Settings?.CarOverrides?.TryGetValue(_activeCarId, out live);
            _lastPersistedCarOverrides?.TryGetValue(_activeCarId, out saved);
            return !OverrideHasSection(live, kind) && OverrideHasSection(saved, kind);
        }

        // True when the active car's in-memory override has THIS section (a
        // saved override or an unsaved draft). Drives the popover's
        // reset/follow-default affordances.
        public bool IsSectionOverridden(SectionKind kind) => OverrideHasSection(GetActiveCarOverride(), kind);

        // For the save popover's contextual "recommended" highlight: was THIS
        // section already part of the car's SAVED preset, before the current
        // unsaved edit? Checks the persisted baseline, NOT the live override,
        // because editing a section seeds it into the live draft
        // (EnsureSectionDraft), so the live override reports true for any
        // just-edited section.
        public bool IsSectionInSavedCarOverride(SectionKind kind)
        {
            if (string.IsNullOrEmpty(_activeCarId)) return false;
            CarOverride saved = null;
            _lastPersistedCarOverrides?.TryGetValue(_activeCarId, out saved);
            return OverrideHasSection(saved, kind);
        }

        // Sections that support a per-car override (have a field on CarOverride).
        // Master / Ducking / SpikeReduction are global-only.
        public static bool SectionHasCarScope(SectionKind kind)
        {
            switch (kind)
            {
                case SectionKind.Engine:
                case SectionKind.Bumps:
                case SectionKind.Traction:
                case SectionKind.AxleSlip:
                case SectionKind.KerbThump:
                case SectionKind.LockupJudder:
                case SectionKind.Shift:
                case SectionKind.Abs:
                case SectionKind.PitLimiter:
                case SectionKind.Drs:
                case SectionKind.Collision:
                case SectionKind.RevLimiter:
                case SectionKind.Audio:
                case SectionKind.Airborne:
                    return true;
                default:
                    return false;
            }
        }

        // ---- generic per-section accessors on a CarOverride ----
        private static bool OverrideHasSection(CarOverride ovr, SectionKind kind)
        {
            if (ovr == null) return false;
            switch (kind)
            {
                case SectionKind.Engine:     return ovr.EnginePulse  != null;
                case SectionKind.Bumps:      return ovr.RoadBumps    != null;
                case SectionKind.Traction:   return ovr.TractionLoss != null;
                case SectionKind.AxleSlip:   return ovr.AxleSlip     != null;
                case SectionKind.KerbThump:  return ovr.KerbThump    != null;
                case SectionKind.LockupJudder: return ovr.LockupJudder != null;
                case SectionKind.Shift:      return ovr.GearShift    != null;
                case SectionKind.Abs:        return ovr.AbsClick     != null;
                case SectionKind.PitLimiter: return ovr.PitLimiter   != null;
                case SectionKind.Drs:        return ovr.Drs          != null;
                case SectionKind.Collision:  return ovr.Collision    != null;
                case SectionKind.RevLimiter: return ovr.RevLimiter   != null;
                case SectionKind.Audio:      return ovr.AudioCapture != null;
                case SectionKind.Airborne:   return ovr.Airborne     != null;
                default: return false;
            }
        }
        private static void ClearOverrideSection(CarOverride ovr, SectionKind kind)
        {
            switch (kind)
            {
                case SectionKind.Engine:     ovr.EnginePulse  = null; break;
                case SectionKind.Bumps:      ovr.RoadBumps    = null; break;
                case SectionKind.Traction:   ovr.TractionLoss = null; break;
                case SectionKind.AxleSlip:   ovr.AxleSlip     = null; break;
                case SectionKind.KerbThump:  ovr.KerbThump    = null; break;
                case SectionKind.LockupJudder: ovr.LockupJudder = null; break;
                case SectionKind.Shift:      ovr.GearShift    = null; break;
                case SectionKind.Abs:        ovr.AbsClick     = null; break;
                case SectionKind.PitLimiter: ovr.PitLimiter   = null; break;
                case SectionKind.Drs:        ovr.Drs          = null; break;
                case SectionKind.Collision:  ovr.Collision    = null; break;
                case SectionKind.RevLimiter: ovr.RevLimiter   = null; break;
                case SectionKind.Audio:      ovr.AudioCapture = null; break;
                case SectionKind.Airborne:   ovr.Airborne     = null; break;
            }
        }
        private void CopyOverrideSection(CarOverride from, CarOverride to, SectionKind kind)
        {
            switch (kind)
            {
                case SectionKind.Engine:     to.EnginePulse  = Clone(from.EnginePulse);  break;
                case SectionKind.Bumps:      to.RoadBumps    = Clone(from.RoadBumps);    break;
                case SectionKind.Traction:   to.TractionLoss = Clone(from.TractionLoss); break;
                case SectionKind.AxleSlip:   to.AxleSlip     = Clone(from.AxleSlip);     break;
                case SectionKind.KerbThump:  to.KerbThump    = Clone(from.KerbThump);    break;
                case SectionKind.LockupJudder: to.LockupJudder = Clone(from.LockupJudder); break;
                case SectionKind.Shift:      to.GearShift    = Clone(from.GearShift);    break;
                case SectionKind.Abs:        to.AbsClick     = Clone(from.AbsClick);     break;
                case SectionKind.PitLimiter: to.PitLimiter   = Clone(from.PitLimiter);   break;
                case SectionKind.Drs:        to.Drs          = Clone(from.Drs);          break;
                case SectionKind.Collision:  to.Collision    = Clone(from.Collision);    break;
                case SectionKind.RevLimiter: to.RevLimiter   = Clone(from.RevLimiter);   break;
                case SectionKind.Audio:      to.AudioCapture = CloneOrNull(from.AudioCapture); break;
                case SectionKind.Airborne:   to.Airborne     = Clone(from.Airborne);     break;
            }
        }

        // ----- per-section: does the active car carry a REAL override here? -----
        // True only when the car has its own copy of the section AND that copy
        // differs from the game preset's value for the effect. A per-car section
        // whose values are content-identical to the game preset (e.g. right after
        // "Update game defaults" re-pins the override via SaveSectionToBoth, or a
        // freshly forked car preset before any tuning) is NOT a real override, so
        // it must not light the "★ car override" badge. The baseline is the active
        // game preset's section, falling back to the live game-level global when
        // the preset carries no value for the effect (Eq(present, null) is false,
        // so a genuine override with no baseline still shows).
        public bool IsEngineOverridden     { get { var o = GetActiveCarOverride()?.EnginePulse;  return o != null && !Eq(o, ActiveGamePresetSnapshot()?.EnginePulse  ?? Settings?.EnginePulse); } }
        public bool IsBumpsOverridden      { get { var o = GetActiveCarOverride()?.RoadBumps;    return o != null && !Eq(o, ActiveGamePresetSnapshot()?.RoadBumps    ?? Settings?.RoadBumps); } }
        public bool IsTractionOverridden   { get { var o = GetActiveCarOverride()?.TractionLoss; return o != null && !Eq(o, ActiveGamePresetSnapshot()?.TractionLoss ?? Settings?.TractionLoss); } }
        public bool IsAxleSlipOverridden   { get { var o = GetActiveCarOverride()?.AxleSlip;     return o != null && !Eq(o, ActiveGamePresetSnapshot()?.AxleSlip     ?? Settings?.AxleSlip); } }
        public bool IsKerbThumpOverridden  { get { var o = GetActiveCarOverride()?.KerbThump;    return o != null && !Eq(o, ActiveGamePresetSnapshot()?.KerbThump    ?? Settings?.KerbThump); } }
        public bool IsLockupJudderOverridden { get { var o = GetActiveCarOverride()?.LockupJudder; return o != null && !Eq(o, ActiveGamePresetSnapshot()?.LockupJudder ?? Settings?.LockupJudder); } }
        public bool IsShiftOverridden      { get { var o = GetActiveCarOverride()?.GearShift;    return o != null && !Eq(o, ActiveGamePresetSnapshot()?.GearShift    ?? Settings?.GearShift); } }
        public bool IsAbsOverridden        { get { var o = GetActiveCarOverride()?.AbsClick;     return o != null && !Eq(o, ActiveGamePresetSnapshot()?.AbsClick     ?? Settings?.AbsClick); } }
        public bool IsPitLimiterOverridden { get { var o = GetActiveCarOverride()?.PitLimiter;   return o != null && !Eq(o, ActiveGamePresetSnapshot()?.PitLimiter   ?? Settings?.PitLimiter); } }
        public bool IsDrsOverridden        { get { var o = GetActiveCarOverride()?.Drs;          return o != null && !Eq(o, ActiveGamePresetSnapshot()?.Drs          ?? Settings?.Drs); } }
        public bool IsCollisionOverridden  { get { var o = GetActiveCarOverride()?.Collision;    return o != null && !Eq(o, ActiveGamePresetSnapshot()?.Collision    ?? Settings?.Collision); } }
        public bool IsRevLimiterOverridden { get { var o = GetActiveCarOverride()?.RevLimiter;   return o != null && !Eq(o, ActiveGamePresetSnapshot()?.RevLimiter   ?? Settings?.RevLimiter); } }
        public bool IsAudioOverridden      { get { var o = GetActiveCarOverride()?.AudioCapture; return o != null && !Eq(o, ActiveGamePresetSnapshot()?.AudioCapture ?? Settings?.AudioCapture); } }

        // The active game preset's stored snapshot (the "game default" a per-car
        // override layers on top of), or null when no named preset is active.
        private GameSettingsSnapshot ActiveGamePresetSnapshot()
        {
            if (string.IsNullOrEmpty(_activePresetName) || Settings?.Presets == null) return null;
            Settings.Presets.TryGetValue(_activePresetName, out var snap);
            return snap;
        }

        // ----- write helpers used by the UI sliders -----
        // Each routes to the per-car section if it's overridden, else to the global section.
        public EnginePulseSettings  ActiveEngine   => GetActiveCarOverride()?.EnginePulse  ?? Settings.EnginePulse;
        public RoadBumpsSettings    ActiveBumps    => GetActiveCarOverride()?.RoadBumps    ?? Settings.RoadBumps;
        public TractionLossSettings ActiveTraction => GetActiveCarOverride()?.TractionLoss ?? Settings.TractionLoss;
        public AxleSlipSettings     ActiveAxleSlip => GetActiveCarOverride()?.AxleSlip     ?? Settings.AxleSlip;
        public KerbThumpSettings    ActiveKerbThump => GetActiveCarOverride()?.KerbThump   ?? Settings.KerbThump;
        public LockupJudderSettings ActiveLockupJudder => GetActiveCarOverride()?.LockupJudder ?? Settings.LockupJudder;
        public GearShiftSettings    ActiveShift    => GetActiveCarOverride()?.GearShift    ?? Settings.GearShift;
        public AbsClickSettings     ActiveAbs        => GetActiveCarOverride()?.AbsClick     ?? Settings.AbsClick;
        public PitLimiterSettings   ActivePitLimiter => GetActiveCarOverride()?.PitLimiter   ?? Settings.PitLimiter;
        public DrsSettings          ActiveDrs        => GetActiveCarOverride()?.Drs          ?? Settings.Drs;
        public CollisionSettings    ActiveCollision  => GetActiveCarOverride()?.Collision    ?? Settings.Collision;
        public RevLimiterSettings   ActiveRevLimiter => GetActiveCarOverride()?.RevLimiter   ?? Settings.RevLimiter;
        public AudioCaptureSettings ActiveAudio    => GetActiveCarOverride()?.AudioCapture ?? Settings.AudioCapture;
        public AirborneSettings     ActiveAirborne => GetActiveCarOverride()?.Airborne     ?? Settings.Airborne;
        // Global-only (SectionHasCarScope excludes it), so the override arm
        // only matters for legacy data; normally this IS Settings.ImplementThud.
        public ImplementThudSettings ActiveImplementThud => GetActiveCarOverride()?.ImplementThud ?? Settings?.ImplementThud;

        // ----- apply settings to live effect -----
        private void ApplyEngineSettings(EnginePulseSettings s)
        {
            if (EnginePulse == null || s == null) return;

            // 2026-07 engine centralization: the engine TYPE no longer comes
            // from the preset. EnginePulse.Layout / CustomPattern /
            // ActiveCustomIsElectric are owned by the car-facts resolution
            // (the variant's UserEngineLayout pin; see
            // ResolveAndApplyCarFactsForActiveCar), which re-runs after preset
            // applies. The legacy Layout / CustomEngineId fields on
            // EnginePulseSettings are relocated once at Init
            // (EngineChoiceMovedToCarFactsV1) and ignored here. This method
            // applies FEEL only.

            EnginePulse.Enabled            = s.Enabled;
            EnginePulse.Gain               = SafeMath.SafeFloat(s.Gain, 0.0f, 10.0f, 1.0f);
            EnginePulse.PitchMultiplier    = SafeMath.SafeFloat(s.Pitch, 0.1f, 4.0f, 1.0f);
            EnginePulse.LowpassHz          = SafeMath.SafeDouble(s.LowpassHz, 20.0, 20000.0, 12000.0);
            EnginePulse.Waveform           = s.Waveform;
            EnginePulse.LoadLayerEnabled   = s.LoadLayerEnabled;
            EnginePulse.LoadLayerGain      = SafeMath.SafeFloat(s.LoadLayerGain, 0.0f, 10.0f, 1.0f);
            EnginePulse.HighRpmBoostEnabled = s.HighRpmBoostEnabled;
            EnginePulse.HighRpmBoostAmount = SafeMath.SafeFloat(s.HighRpmBoostAmount, 0.0f, 2.0f, 0.4f);

            // ElectricMode cascade: if the pinned custom engine is electric,
            // its mode wins (a per-custom override of the per-preset default).
            // Else the per-preset setting drives EV behavior.
            var pinCustom = _activePinnedCustomEngine;
            EnginePulse.ElectricMode = (pinCustom != null && pinCustom.IsElectric)
                ? pinCustom.ElectricMode
                : s.ElectricMode;
        }
        private void ApplyBumpsSettings(RoadBumpsSettings s)
        {
            if (RoadBumps == null || s == null) return;
            RoadBumps.Enabled            = s.Enabled;
            RoadBumps.Gain               = SafeMath.SafeFloat(s.Gain, 0.0f, 10.0f, 1.0f);
            RoadBumps.Waveform           = s.Waveform;
            RoadBumps.Freq               = SafeMath.SafeFloat(s.Freq, 20.0f, 500.0f, 100.0f);
            RoadBumps.SurfaceEnabled     = s.SurfaceEnabled;
            RoadBumps.SurfaceGain        = SafeMath.SafeFloat(s.SurfaceGain, 0.0f, 10.0f, 1.0f);
            RoadBumps.SurfaceFreq        = SafeMath.SafeFloat(s.SurfaceFreq, 20.0f, 500.0f, 100.0f);
            RoadBumps.SurfaceWaveform    = s.SurfaceWaveform;
            RoadBumps.SurfaceLowpassHz   = SafeMath.SafeDouble(s.SurfaceLowpassHz, 20.0, 20000.0, 5000.0);
            RoadBumps.SurfaceHighpassHz  = SafeMath.SafeDouble(s.SurfaceHighpassHz, 0.0, 1000.0, 30.0);
            RoadBumps.SurfaceRumbleScale = SafeMath.SafeFloat(s.SurfaceRumbleScale, 0.0f, 10.0f, 1.0f);
        }
        private void ApplyTractionSettings(TractionLossSettings s)
        {
            if (TractionLoss == null || s == null) return;
            // Farming Simulator has ONE slip voice: Axle slip (owner call
            // 2026-08-08; both effects would render the same unsigned slip
            // twice there). Hard-gated here, not just hidden in the UI, so
            // a hidden section can't keep rendering a rumble nobody can
            // find the knob for. The apply-all reruns on game change, so
            // leaving FS restores the user's setting. Possible future
            // direction: deprecate Traction loss in favor of Axle slip
            // everywhere.
            bool fsGame = _activeGame != null
                && _activeGame.StartsWith("FarmingSimulator", StringComparison.Ordinal);
            TractionLoss.Enabled         = s.Enabled && !fsGame;
            TractionLoss.Gain            = SafeMath.SafeFloat(s.Gain, 0.0f, 10.0f, 1.0f);
            TractionLoss.Sensitivity     = SafeMath.SafeFloat(s.Sensitivity, 0.0f, 10.0f, 1.0f);
            TractionLoss.Waveform        = s.Waveform;
            TractionLoss.Freq            = SafeMath.SafeFloat(s.Freq, 20.0f, 500.0f, 100.0f);
            TractionLoss.NoiseLowpassHz  = SafeMath.SafeDouble(s.NoiseLowpassHz, 20.0, 20000.0, 8000.0);
            TractionLoss.NoiseHighpassHz = SafeMath.SafeDouble(s.NoiseHighpassHz, 0.0, 1000.0, 30.0);
        }
        private void ApplyAxleSlipSettings(AxleSlipSettings s)
        {
            if (AxleSlip == null || s == null) return;
            AxleSlip.Enabled            = s.Enabled;
            AxleSlip.Gain               = SafeMath.SafeFloat(s.Gain, 0.0f, 10.0f, 1.0f);
            // 150 ms is the validated fixed lead; the toggle only turns the
            // early warning on or off.
            AxleSlip.PredictiveLeadMs   = s.PredictiveSlip ? 150f : 0f;
            AxleSlip.RevLockedRearPulse = s.RevLockedRearPulse;
            AxleSlip.FrontAmp = SafeMath.SafeFloat(s.FrontStrength, 0.0f, 1.0f, 0.30f);
            AxleSlip.RearAmp  = SafeMath.SafeFloat(s.RearStrength,  0.0f, 1.0f, 0.205f);
            // Pitch sliders move the band CENTER; each band keeps the
            // engine's proportional width (front 0.75x..1.25x of center,
            // rear 40/55x..70/55x, i.e. the original 150..250 / 40..70
            // shapes). The rear min also remains the floor of the
            // wheelspin-locked pulse. Fallbacks are the owner-tuned baseline
            // (2026-07-14), matching the settings-class defaults.
            float frontCenter = SafeMath.SafeFloat(s.FrontPitchHz, 100.0f, 350.0f, 200.0f);
            AxleSlip.FrontFreqMinHz = frontCenter * 0.75f;
            AxleSlip.FrontFreqMaxHz = frontCenter * 1.25f;
            float rearCenter = SafeMath.SafeFloat(s.RearPitchHz, 25.0f, 90.0f, 35.0f);
            AxleSlip.RearFreqMinHz = rearCenter * (40.0f / 55.0f);
            AxleSlip.RearFreqMaxHz = rearCenter * (70.0f / 55.0f);
            AxleSlip.JudderMaxDepth = SafeMath.SafeFloat(s.JudderDepth, 0.0f, 1.0f, 0.8f);
            AxleSlip.OnsetUtil      = SafeMath.SafeFloat(s.OnsetUtil, 0.5f, 0.98f, 0.85f);
        }
