        /// <summary>Scan the user-imports folder for *.json files and import
        /// each by content type. Imported files move into
        /// <c>imported/&lt;timestamp&gt;/</c> so they don't re-import. Quiet:
        /// logs only, no UI. Safe to call once per plugin start.</summary>
        public string ImportFromUserImportsFolder()
        {
            string folder = UserImportsFolderPath;
            if (string.IsNullOrEmpty(folder) || !Directory.Exists(folder)) return null;
            int gameOk = 0, carOk = 0, packGameOk = 0, packCarOk = 0, failed = 0;
            var imported = new List<string>();
            string archiveRoot = Path.Combine(folder, UserImportsArchiveSubfolder);
            // Recurse so a dropped-in folder (e.g. an unzipped pack) also imports.
            // Skip anything already inside the archive subfolder.
            foreach (var path in Directory.GetFiles(folder, "*.json", SearchOption.AllDirectories))
            {
                if (path.StartsWith(archiveRoot, StringComparison.OrdinalIgnoreCase)) continue;
                try
                {
                    string type = ReadFileTypeField(path);
                    if (string.Equals(type, PresetFile.FileType, StringComparison.Ordinal))
                    {
                        ImportPreset(path);
                        gameOk++; imported.Add(path);
                    }
                    else if (string.Equals(type, CarPresetFile.FileType, StringComparison.Ordinal))
                    {
                        ImportCarPreset(path);
                        carOk++; imported.Add(path);
                    }
                    else if (string.Equals(type, PresetPackManifest.FileType, StringComparison.Ordinal))
                    {
                        var r = ImportPack(path);
                        packGameOk += r.PresetsImported;
                        packCarOk  += r.CarsImported;
                        imported.Add(path);
                    }
                    else
                    {
                        SimHub.Logging.Current.Warn($"[TF4ALL] Skipping unknown file in imports folder: {Path.GetFileName(path)} (Type='{type}').");
                        failed++;
                    }
                }
                catch (Exception ex)
                {
                    SimHub.Logging.Current.Warn($"[TF4ALL] Failed to import '{Path.GetFileName(path)}': {ex.Message}");
                    failed++;
                }
            }

            // Pack archives are binary (not *.json), so scan them separately and
            // route each to ImportPack. A dropped .tfpack/.zip now installs here
            // the same way the manual Import button handles it.
            var packFiles = new List<string>();
            packFiles.AddRange(Directory.GetFiles(folder, "*.tfpack", SearchOption.AllDirectories));
            packFiles.AddRange(Directory.GetFiles(folder, "*.zip", SearchOption.AllDirectories));
            foreach (var path in packFiles)
            {
                if (path.StartsWith(archiveRoot, StringComparison.OrdinalIgnoreCase)) continue;
                try
                {
                    var r = ImportPack(path);
                    packGameOk += r.PresetsImported;
                    packCarOk  += r.CarsImported;
                    imported.Add(path);
                }
                catch (Exception ex)
                {
                    SimHub.Logging.Current.Warn($"[TF4ALL] Failed to import pack '{Path.GetFileName(path)}': {ex.Message}");
                    failed++;
                }
            }

            if (imported.Count > 0)
            {
                try
                {
                    string archive = Path.Combine(folder, UserImportsArchiveSubfolder,
                        DateTime.Now.ToString("yyyyMMdd-HHmmss"));
                    Directory.CreateDirectory(archive);
                    foreach (var p in imported)
                    {
                        try { File.Move(p, Path.Combine(archive, Path.GetFileName(p))); }
                        catch (Exception ex) { SimHub.Logging.Current.Warn($"[TF4ALL] Couldn't archive imported file '{p}': {ex.Message}"); }
                    }
                }
                catch (Exception ex) { SimHub.Logging.Current.Warn($"[TF4ALL] Couldn't create imports archive: {ex.Message}"); }
            }

            int total = gameOk + carOk + packGameOk + packCarOk;
            if (total == 0 && failed == 0) return null;
            string msg = $"Imports folder scan: {gameOk} game, {carOk} car";
            if (packGameOk + packCarOk > 0) msg += $", pack ({packGameOk} game + {packCarOk} car)";
            if (failed > 0) msg += $", {failed} skipped/failed";
            msg += ".";
            SimHub.Logging.Current.Info($"[TF4ALL] {msg}");
            return msg;
        }

        // Read just the top-level Type field from a JSON file, fast and tolerant.
        private static string ReadFileTypeField(string path)
        {
            try
            {
                var o = Newtonsoft.Json.Linq.JObject.Parse(File.ReadAllText(path));
                return (string)o["Type"] ?? "";
            }
            catch { return ""; }
        }

        /// <summary>DEV authoring mode (the app owner). When on, saving a
        /// preset writes it through to the built-in folder: editing a built-in
        /// overwrites it in place, a new preset becomes a built-in. Non-dev
        /// users keep the protective fork-on-built-in behaviour.</summary>
        public bool DevMode => Settings?.DevModeUnlocked == true;

        // Persist a game preset snapshot to its file. Picks the right folder:
        //   - EXISTING built-in AND DevMode  -> built-in folder (DEV authoring).
        //   - Everything else                -> user library folder.
        //   - Built-in name in non-DEV       -> caller refuses; we just no-op.
        // After writing, reloads the touched store and rebuilds the runtime
        // cache so Settings.Presets reflects the new file content.
        private bool PersistGamePresetToFolder(string presetName, GameSettingsSnapshot snap)
        {
            if (string.IsNullOrEmpty(presetName) || snap == null) return false;
            bool isBuiltin = IsBuiltinPreset(presetName);
            if (isBuiltin && !DevMode) return false; // protective; caller already refused
            try
            {
                string json = Newtonsoft.Json.JsonConvert.SerializeObject(
                    snap, Newtonsoft.Json.Formatting.Indented);
                if (isBuiltin)
                {
                    BuiltinPresetWriter.WriteGame(BuiltinPresets.CurrentFolder, presetName, json);
                    BuiltinPresets.Reload();
                    SimHub.Logging.Current.Info($"[TF4ALL] DEV: wrote '{presetName}' to the built-in folder.");
                }
                else
                {
                    BuiltinPresetWriter.WriteGame(UserPresets.CurrentFolder, presetName, json);
                    UserPresets.Reload();
                    SimHub.Logging.Current.Info($"[TF4ALL] Wrote user preset '{presetName}' to the library folder.");
                }
                RebuildPresetCacheFromFolders();
                return true;
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Warn($"[TF4ALL] Persist '{presetName}' failed: {ex.Message}");
                return false;
            }
        }

        /// <summary>Export one library game preset into the built-in folder as
        /// a data file (+ manifest entry), then reload the store.</summary>
        public bool PromoteGamePresetToBuiltin(string presetName, out string error)
        {
            error = null;
            try
            {
                if (Settings?.Presets == null
                    || !Settings.Presets.TryGetValue(presetName, out var snap) || snap == null)
                { error = "preset not found in library"; return false; }
                string json = Newtonsoft.Json.JsonConvert.SerializeObject(
                    snap, Newtonsoft.Json.Formatting.Indented);
                string rel = BuiltinPresetWriter.WriteGame(BuiltinPresets.CurrentFolder, presetName, json);
                BuiltinPresets.Reload();
                SimHub.Logging.Current.Info($"[TF4ALL] Exported game preset '{presetName}' -> built-in '{rel}'.");
                return true;
            }
            catch (Exception ex) { error = ex.Message; return false; }
        }

        /// <summary>Export one library car preset into the built-in folder as a
        /// CarPresetFile (IsBuiltin=true, PresetName "&lt;carId&gt; (default)").</summary>
        public bool PromoteCarPresetToBuiltin(string carId, string presetName, out string error)
        {
            error = null;
            try
            {
                var all = GetAllCarPresets();
                if (all == null || !all.TryGetValue(carId, out var perCar)
                    || !perCar.TryGetValue(presetName, out var entry) || entry == null)
                { error = "car preset not found"; return false; }

                // Promote always writes to the factory folder; presetName from
                // UI (typically a user row, but harmless on a factory row) may
                // carry the display suffix -- strip to the on-disk form.
                string diskName = ToDiskName(presetName);
                var file = new CarPresetFile
                {
                    Type       = CarPresetFile.FileType,
                    Version    = 2,
                    GameName   = entry.GameName ?? "",
                    CarId      = carId,
                    PresetName = diskName,
                    IsBuiltin  = true,
                    Override   = entry.Override,
                };
                string json = Newtonsoft.Json.JsonConvert.SerializeObject(
                    file, Newtonsoft.Json.Formatting.Indented);
                string rel = BuiltinPresetWriter.WriteCar(BuiltinPresets.CurrentFolder, file.GameName, carId, diskName, json);
                // First built-in for this car becomes its default; otherwise
                // leave the existing default (owner picks via Set as default).
                if (!BuiltinPresets.CarDefaultBindings.ContainsKey(carId))
                    BuiltinPresetWriter.SetCarDefault(BuiltinPresets.CurrentFolder, carId, diskName);
                BuiltinPresets.Reload();
                SimHub.Logging.Current.Info($"[TF4ALL] Exported car preset '{carId}/{diskName}' -> built-in '{rel}'.");
                return true;
            }
            catch (Exception ex) { error = ex.Message; return false; }
        }

        // (Phase 3 change-folder / GitHub-repair note: after switching the built-in
        // folder, the full refresh sequence is BuiltinPresets.Reload() +
        // RebuildPresetCacheFromFolders() + LoadAndMigrateCarPresets(). The old
        // ImportBuiltinsFromFolder/ReseedBuiltinsFromFolder wrappers were deleted
        // 2026-07-08; the rebuild's clear-and-rebuild + defaults self-heal subsumes
        // them. History: e64eb16.)

        /// <summary>Validate the built-in folder (parse + missing-section
        /// flag). Returns human-readable lines for the dev panel.</summary>
        public List<string> ValidateBuiltins()
            => BuiltinPresets.Validate(BuiltinGameSections);

        /// <summary>Startup migration, latched by Settings.ForzaCarIdsNormalizedV1:
        /// normalize legacy "Forza_&lt;n&gt;" car ids
        /// to "Car_&lt;n&gt;" so they match what SimHub's data feed reports
        /// (Trueforce's UDP fallback used to emit Forza_&lt;n&gt;; now emits
        /// Car_&lt;n&gt;). Per-car rules:
        /// <list type="bullet">
        ///   <item>Both "Car_&lt;n&gt;" and "Forza_&lt;n&gt;" exist: keep Car,
        ///   delete the Forza directory.</item>
        ///   <item>Only "Forza_&lt;n&gt;" exists: rename to "Car_&lt;n&gt;",
        ///   rewriting each file's CarId field and the inner PresetName when
        ///   it embedded the old carId (e.g. "Forza_455 (default)" -&gt;
        ///   "Car_455 (default)").</item>
        /// </list>
        /// Applies to factory + user folders, both car-defaults.json files,
        /// and the live Settings.CarDefaults + Settings.CarOverrides
        /// dicts. Reloads stores at the end and persists settings.</summary>
        public int DevNormalizeForzaCarIds(out string summary)
        {
            var lines = new List<string>();
            int renamed = 0, deduped = 0, dictHits = 0;

            NormalizeForzaInFolder(BuiltinPresets.CurrentFolder, "factory", lines, ref renamed, ref deduped);
            NormalizeForzaInFolder(UserPresets.CurrentFolder,    "user",    lines, ref renamed, ref deduped);

            NormalizeForzaInCarDefaultsFile(BuiltinPresets.CurrentFolder, "factory", lines);
            NormalizeForzaInCarDefaultsFile(UserPresets.CurrentFolder,    "user",    lines);

            if (Settings?.CarDefaults  != null) dictHits += NormalizeForzaInStringDict(Settings.CarDefaults);
            if (Settings?.CarOverrides != null) dictHits += NormalizeForzaInOverrideDict(Settings.CarOverrides);
            if (dictHits > 0) lines.Add($"Settings dicts: rewrote {dictHits} entry/entries");

            int total = renamed + deduped + dictHits;
            if (total > 0)
            {
                BuiltinPresets.Reload();
                UserPresets.Reload();
                LoadAndMigrateCarPresets();
                PersistSettingsCore();
                SimHub.Logging.Current.Info($"[TF4ALL] DEV: normalized {renamed} carId rename(s), {deduped} dedup(s), {dictHits} settings entries.");
            }
            summary = total == 0
                ? "No Forza_xxx car ids found. (Already normalized.)"
                : $"Normalized {renamed} car directory/ies, deduped {deduped}, rewrote {dictHits} settings entries.";
            if (lines.Count > 0) summary += "\n" + string.Join("\n", lines);
            return total;
        }

        private static void NormalizeForzaInFolder(string root, string label, List<string> lines, ref int renamed, ref int deduped)
        {
            if (string.IsNullOrEmpty(root) || !Directory.Exists(root)) return;
            string carsRoot = Path.Combine(root, "cars");
            if (!Directory.Exists(carsRoot)) return;

            foreach (var gameDir in Directory.GetDirectories(carsRoot))
            {
                string gameName = Path.GetFileName(gameDir);
                foreach (var carDir in Directory.GetDirectories(gameDir))
                {
                    string oldCarId = Path.GetFileName(carDir);
                    if (!oldCarId.StartsWith("Forza_", StringComparison.Ordinal)) continue;
                    string newCarId = "Car_" + oldCarId.Substring("Forza_".Length);
                    string newCarDir = Path.Combine(gameDir, newCarId);
                    // A Car_<n> tree may already exist (e.g. a tuning made on
                    // this branch plus a legacy Forza_<n> one for the same
                    // car). Never drop the Forza_<n> tunings wholesale: an
                    // identical Override is a true duplicate (skip it), a
                    // distinct one is recovered under a unique name so no user
                    // data is lost.
                    bool collision = Directory.Exists(newCarDir);
                    int written = 0, skipped = 0;
                    foreach (var path in Directory.GetFiles(carDir, "*.json"))
                    {
                        try
                        {
                            var f = Newtonsoft.Json.JsonConvert.DeserializeObject<CarPresetFile>(File.ReadAllText(path));
                            if (f == null) continue;
                            f.CarId = newCarId;
                            string newPresetName = f.PresetName;
                            if (!string.IsNullOrEmpty(newPresetName))
                            {
                                if (newPresetName == oldCarId)
                                    newPresetName = newCarId;
                                else if (newPresetName.StartsWith(oldCarId + " ", StringComparison.Ordinal)
                                      || newPresetName.StartsWith(oldCarId + "(", StringComparison.Ordinal))
                                    newPresetName = newCarId + newPresetName.Substring(oldCarId.Length);
                            }
                            if (string.IsNullOrEmpty(newPresetName)) newPresetName = newCarId;
                            if (collision)
                            {
                                if (ForzaDirHasMatchingOverride(newCarDir, f)) { skipped++; continue; }
                                newPresetName = ForzaUniquePresetName(newCarDir, newPresetName);
                            }
                            f.PresetName = newPresetName;
                            string json = Newtonsoft.Json.JsonConvert.SerializeObject(
                                f, Newtonsoft.Json.Formatting.Indented);
                            BuiltinPresetWriter.WriteCar(root, gameName, newCarId, newPresetName, json);
                            written++;
                        }
                        catch (Exception ex)
                        {
                            SimHub.Logging.Current.Warn($"[TF4ALL] NormalizeForza: failed to rewrite '{path}': {ex.Message}");
                        }
                    }
                    // Drop the now-stale Forza_<n> directory (its presets are
                    // now under Car_<n>, or were exact duplicates).
                    try { Directory.Delete(carDir, recursive: true); } catch { }
                    if (collision)
                    {
                        deduped++;
                        lines.Add(written > 0
                            ? $"{label}/{gameName}/{oldCarId}: merged into {newCarId} ({written} recovered, {skipped} duplicate(s) dropped)"
                            : $"{label}/{gameName}/{oldCarId}: {skipped} duplicate(s) dropped (Car_<n> equivalent exists)");
                    }
                    else
                    {
                        renamed++;
                        lines.Add($"{label}/{gameName}/{oldCarId} -> {newCarId} ({written} file(s))");
                    }
                }
            }
        }

        // True if a car preset already in newCarDir carries the same Override
        // as f (a genuine duplicate that needs no recovery copy).
        private static bool ForzaDirHasMatchingOverride(string newCarDir, CarPresetFile f)
        {
            try
            {
                if (!Directory.Exists(newCarDir)) return false;
                string mine = Newtonsoft.Json.JsonConvert.SerializeObject(f.Override);
                foreach (var p in Directory.GetFiles(newCarDir, "*.json"))
                {
                    try
                    {
                        var e = Newtonsoft.Json.JsonConvert.DeserializeObject<CarPresetFile>(File.ReadAllText(p));
                        if (e?.Override == null) continue;
                        if (Newtonsoft.Json.JsonConvert.SerializeObject(e.Override) == mine) return true;
                    }
                    catch { /* unreadable sibling: ignore */ }
                }
            }
            catch { /* best effort */ }
            return false;
        }

        // A preset name not already used by a car preset in newCarDir, so a
        // recovered Forza_<n> tuning never overwrites an existing Car_<n> one.
        private static string ForzaUniquePresetName(string newCarDir, string baseName)
        {
            var existing = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            try
            {
                if (Directory.Exists(newCarDir))
                    foreach (var p in Directory.GetFiles(newCarDir, "*.json"))
                    {
                        try
                        {
                            var e = Newtonsoft.Json.JsonConvert.DeserializeObject<CarPresetFile>(File.ReadAllText(p));
                            if (!string.IsNullOrEmpty(e?.PresetName)) existing.Add(e.PresetName);
                        }
                        catch { /* ignore */ }
                    }
            }
            catch { /* best effort */ }
            if (!existing.Contains(baseName)) return baseName;
            int n = 2;
            string cand;
            do { cand = baseName + " (recovered " + n++ + ")"; } while (existing.Contains(cand));
            return cand;
        }

        // "Forza_455" -> "Car_455", "Forza_455 (edited)" -> "Car_455 (edited)".
        // Mirrors the PresetName rewrite in NormalizeForzaInFolder: the ordinal
        // must end the token (end of string, " " or "("), so a user-typed name
        // like "Forza_455x" passes through untouched, matching its file.
        private static string NormalizeForzaOrdinalName(string name)
        {
            if (string.IsNullOrEmpty(name) || !name.StartsWith("Forza_", StringComparison.Ordinal)) return name;
            int start = "Forza_".Length;
            int end = start;
            while (end < name.Length && char.IsDigit(name[end])) end++;
            if (end == start) return name;
            if (end < name.Length && name[end] != ' ' && name[end] != '(') return name;
            return "Car_" + name.Substring(start);
        }

        private static int NormalizeForzaInStringDict(Dictionary<string, string> d)
        {
            int n = 0;
            foreach (var key in new List<string>(d.Keys))
            {
                bool forzaKey = key.StartsWith("Forza_", StringComparison.Ordinal);
                // Binding VALUES follow the same rename as the preset files
                // they point at ("Forza_455 (edited)" -> "Car_455 (edited)");
                // a value left on the old name dangles and the car silently
                // reverts to the factory default. Only ordinal-keyed cars
                // qualify: on a content-id car a Forza_-looking preset name
                // is the user's own and its file is not renamed.
                bool ordinalKey = forzaKey || key.StartsWith("Car_", StringComparison.Ordinal);
                string val = d[key];
                string newVal = ordinalKey ? NormalizeForzaOrdinalName(val) : val;
                if (!forzaKey && string.Equals(newVal, val, StringComparison.Ordinal)) continue;
                string newKey = forzaKey ? "Car_" + key.Substring("Forza_".Length) : key;
                d.Remove(key);
                if (!d.ContainsKey(newKey)) d[newKey] = newVal;
                n++;
            }
            return n;
        }

        private static int NormalizeForzaInOverrideDict(Dictionary<string, CarOverride> d)
        {
            int n = 0;
            foreach (var key in new List<string>(d.Keys))
            {
                if (!key.StartsWith("Forza_", StringComparison.Ordinal)) continue;
                string newKey = "Car_" + key.Substring("Forza_".Length);
                var val = d[key];
                d.Remove(key);
                if (!d.ContainsKey(newKey)) d[newKey] = val;
                n++;
            }
            return n;
        }

        private static void NormalizeForzaInCarDefaultsFile(string folder, string label, List<string> lines)
        {
            if (string.IsNullOrEmpty(folder)) return;
            string path = Path.Combine(folder, BuiltinPresetStore.CarDefaultsFileName);
            if (!File.Exists(path)) return;
            try
            {
                var o = Newtonsoft.Json.Linq.JObject.Parse(File.ReadAllText(path));
                var props = new List<Newtonsoft.Json.Linq.JProperty>(o.Properties());
                bool changed = false;
                foreach (var p in props)
                {
                    bool forzaKey = p.Name.StartsWith("Forza_", StringComparison.Ordinal);
                    bool ordinalKey = forzaKey || p.Name.StartsWith("Car_", StringComparison.Ordinal);
                    // The binding VALUE (preset name) gets the same rename as
                    // the preset file it points at, else it dangles and the
                    // later stale-binding cleanup drops it, silently
                    // deselecting the user's tuning for that car.
                    string val = p.Value != null && p.Value.Type == Newtonsoft.Json.Linq.JTokenType.String
                        ? (string)p.Value : null;
                    string newVal = ordinalKey ? NormalizeForzaOrdinalName(val) : val;
                    bool valChanged = !string.Equals(newVal, val, StringComparison.Ordinal);
                    if (!forzaKey)
                    {
                        if (!valChanged) continue;
                        p.Value = newVal;
                        changed = true;
                        lines.Add($"{label}/car-defaults.json: {p.Name} value -> {newVal}");
                        continue;
                    }
                    string newKey = "Car_" + p.Name.Substring("Forza_".Length);
                    if (o[newKey] != null)
                    {
                        p.Remove();
                        changed = true;
                        lines.Add($"{label}/car-defaults.json: dropped {p.Name} (Car_<n> exists)");
                        continue;
                    }
                    var v = valChanged ? (Newtonsoft.Json.Linq.JToken)newVal : p.Value;
                    string oldName = p.Name;
                    p.Remove();
                    o[newKey] = v;
                    changed = true;
                    lines.Add(valChanged
                        ? $"{label}/car-defaults.json: {oldName} -> {newKey} (value {newVal})"
                        : $"{label}/car-defaults.json: {oldName} -> {newKey}");
                }
                if (changed) File.WriteAllText(path, o.ToString(Newtonsoft.Json.Formatting.Indented));
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Warn($"[TF4ALL] NormalizeForza car-defaults '{path}': {ex.Message}");
            }
        }

        /// <summary>Re-scan factory + user folders from disk and rebuild every
        /// runtime cache (game preset map, car defaults, car store). Use after
        /// external edits to the folders (drop-in files, manual edits) so the
        /// in-memory state catches up without a SimHub restart. The caller
        /// still needs to call PresetManagerControl.RefreshLists() to redraw
        /// the UI rows.</summary>
        public string ReloadLibraryFromFolders()
        {
            // Install anything dropped into the import folder first, so a Refresh
            // picks up newly-dropped presets/packs (not just at plugin startup).
            string importMsg = null;
            try { importMsg = ImportFromUserImportsFolder(); }
            catch (Exception ex) { SimHub.Logging.Current.Warn($"[TF4ALL] Import-folder scan on refresh failed: {ex.Message}"); }
            BuiltinPresets.Reload();
            UserPresets.Reload();
            RebuildPresetCacheFromFolders();
            LoadAndMigrateCarPresets();
            string msg = $"Reloaded library from folders: {BuiltinPresets.BuiltinPresetJsons.Count} game + {BuiltinPresets.CarPresetJsons.Count} car built-in(s), {UserPresets.PresetJsons.Count} user game preset(s), {UserPresets.CarPresetJsons.Count} user car preset(s).";
            if (!string.IsNullOrEmpty(importMsg)) msg = importMsg + " " + msg;
            SimHub.Logging.Current.Info($"[TF4ALL] {msg}");
            return msg;
        }

        /// <summary>Give an unmapped game its own preset seeded from the
        /// Assetto Corsa baseline (which ships as the user's AC tuning) and
        /// bind it as that game's default, then apply it live. No-op if the
        /// game already has a preset of that name (binds to it instead). Called
        /// from the game-change path the first time an unmapped title appears.</summary>
        private void EnsureSeededGamePreset(string gameName)
        {
            if (Settings == null || string.IsNullOrEmpty(gameName)) return;
            if (Settings.Presets      == null) Settings.Presets      = new Dictionary<string, GameSettingsSnapshot>();
            if (Settings.GameDefaults == null) Settings.GameDefaults = new Dictionary<string, string>();

            // Seed from the AC baseline (always installed by
            // InstallBuiltinPresetsIfMissing). Bail safely if it's somehow absent.
            if (!Settings.Presets.TryGetValue("Assetto Corsa (default)", out var seed) || seed == null)
                return;

            // The readable name, not the code. SimHub's codes are keys and are
            // never renamed, but a preset's NAME is free, and a player looking at
            // a dropdown row saying "RRRE" has to know it means RaceRoom. Existing
            // presets keep whatever they were called; only new seeds get this.
            string presetName = GameNames.Display(gameName);
            if (string.IsNullOrEmpty(presetName)) presetName = gameName;
            if (!Settings.Presets.ContainsKey(presetName))
            {
                // Write the seeded copy as a user-library file (it's a fresh,
                // user-mutable preset for this newly-seen game).
                try
                {
                    var clone = CloneSnapshot(seed);
                    // Stamp a sentinel PackName so BackfillAuthorOnLocalPresets
                    // recognises this as a shipped seed, not user-authored
                    // work, and skips stamping the user's name on it.
                    // SaveSectionToActivePreset clears the sentinel on the
                    // user's first edit so the preset becomes "theirs" the
                    // moment they touch a slider.
                    clone.PackName = SeededPresetSentinel;
                    string json = Newtonsoft.Json.JsonConvert.SerializeObject(
                        clone, Newtonsoft.Json.Formatting.Indented);
                    BuiltinPresetWriter.WriteGame(UserPresets.CurrentFolder, presetName, json);
                    UserPresets.Reload();
                    RebuildPresetCacheFromFolders();
                }
                catch (Exception ex)
                {
                    SimHub.Logging.Current.Warn($"[TF4ALL] Seeded preset write for '{presetName}' failed: {ex.Message}");
                }
            }

            SetDefaultPresetForGame(gameName, presetName);

            if (Settings.Presets.TryGetValue(presetName, out var applied))
                ApplyGamePreset(applied);
            _activePresetName = presetName;
            SimHub.Logging.Current.Info(
                $"[TF4ALL] No default for '{gameName}'; created preset '{presetName}' seeded from the Assetto Corsa baseline.");
        }

        // Deep-clone a snapshot via JSON round-trip so the new game's preset
        // doesn't alias the AC baseline's nested section objects.
        private static GameSettingsSnapshot CloneSnapshot(GameSettingsSnapshot s)
            => Newtonsoft.Json.JsonConvert.DeserializeObject<GameSettingsSnapshot>(
                   Newtonsoft.Json.JsonConvert.SerializeObject(s));

        /// <summary>One-shot migration + initial load for per-car preset files.
        /// Files are the canonical store post-Model-G. Steps, in order:
        ///
        ///   1. Seed file store from legacy data sources (in-Settings
        ///      CarOverrides, preset-nested CarOverrides) for upgrades from
        ///      pre-files versions. File-wins-on-conflict so re-runs don't
        ///      clobber files the user has already edited.
        ///   2. Migrate v1 single-preset-per-car files to the v2
        ///      multi-preset naming (<c>&lt;carId&gt;~&lt;presetName&gt;.tfcar.json</c>)
        ///      with PresetName=CarId. Each migrated car gets a CarDefaults
        ///      entry pointing at its migrated user preset, so the active
        ///      override doesn't change.
        ///   3. Install / refresh built-in factory car presets shipped via
        ///      BuiltinCarPresets. Always rewrites factory files so a future
        ///      release that updates a default just lands.
        ///   4. Load every preset back into memory and resolve the active
        ///      preset for each car into Settings.CarOverrides (the live
        ///      cache the effects read from).</summary>
        private void LoadAndMigrateCarPresets()
        {
            if (Settings == null || _carStore == null) return;
            if (Settings.CarOverrides == null) Settings.CarOverrides = new Dictionary<string, CarOverride>();
            if (Settings.CarDefaults  == null) Settings.CarDefaults  = new Dictionary<string, string>();

            // Load the user-side car files once. Reused for the existence check
            // in steps 1 + 2 AND for the cache rebuild in step 4. The check is
            // "does this carId have ANY preset file yet?", not "is there a file
            // specifically named <carId>/<carId>.json", a v0.1.20 user whose
            // car preset was renamed (file at <carId>/<Custom name>.json) would
            // otherwise get a duplicate written by step 1.
            var loaded = _carStore.LoadAll();
            var carIdsWithUserFiles = new HashSet<string>(loaded.Keys, StringComparer.Ordinal);

            // Factory carId -> game map: recovers the game for cache-migrated
            // cars (Settings.CarOverrides is keyed by carId only, no game).
            var factoryCarGames = BuildFactoryCarGameMap();

            // 1) Migrate Settings.CarOverrides → files (only if no file yet for
            //    that carId). Use carId as the preset name so the migrated
            //    entry has a stable identity in the new multi-preset model.
            //
            //    CarDefaults.ContainsKey gates this: once a car has any
            //    binding (its own user file OR a built-in default), the
            //    migration for that car is done. Step 5 below repopulates
            //    Settings.CarOverrides from disk on every load, so without
            //    this guard a deleted user-tier file would silently resurrect
            //    on next launch from the cached live override.
            int migrated = 0;
            foreach (var kv in new Dictionary<string, CarOverride>(Settings.CarOverrides))
            {
                if (kv.Value == null || kv.Value.IsEmpty) continue;
                if (Settings.CarDefaults.ContainsKey(kv.Key)) continue;
                if (carIdsWithUserFiles.Contains(kv.Key)) continue;
                // Skip cars that duplicate a factory built-in: the factory
                // version provides it with its game. Skipping at import (vs
                // import-then-archive) avoids the blank-game Unknown copies the
                // old path created when the .tfcar.json migration was skipped.
                if (IsFactoryCarDuplicate(kv.Key, kv.Value)) continue;
                string g1 = factoryCarGames.TryGetValue(NormalizeForzaPrefix(kv.Key), out var fg1) ? fg1 : (_activeGame ?? "");
                // Preset name = human-readable car name when one is known
                // (CarFacts user-rename -> baked tables), else the carId
                // itself. Without this Forza ordinals migrated as "Car_2267"
                // instead of "2016 Mazda MX-5". The post-migration
                // ordinal-rename pass also catches this, but doing it at
                // creation time avoids a transient ordinal-named file +
                // a CarDefaults entry that has to be updated again later.
                string migratedPresetName = ResolveCarHumanName(g1, kv.Key) ?? kv.Key;
                _carStore.Save(kv.Key, migratedPresetName, g1, kv.Value, isBuiltin: false);
                carIdsWithUserFiles.Add(kv.Key);
                if (!Settings.CarDefaults.ContainsKey(kv.Key))
                    Settings.CarDefaults[kv.Key] = migratedPresetName;
                migrated++;
            }
            // 2) Migrate each preset's CarOverrides → files (file-wins).
            //    Game presets going forward don't include CarOverrides, but
            //    legacy data may still be present in saved presets.
            if (Settings.Presets != null)
            {
                foreach (var presetKv in Settings.Presets)
                {
                    var snap = presetKv.Value;
                    if (snap?.CarOverrides == null) continue;
                    foreach (var carKv in snap.CarOverrides)
                    {
                        if (carKv.Value == null || carKv.Value.IsEmpty) continue;
                        if (carIdsWithUserFiles.Contains(carKv.Key)) continue;
                        if (IsFactoryCarDuplicate(carKv.Key, carKv.Value)) continue;
                        string g2 = factoryCarGames.TryGetValue(NormalizeForzaPrefix(carKv.Key), out var fg2) ? fg2 : (_activeGame ?? "");
                        _carStore.Save(carKv.Key, carKv.Key, g2, carKv.Value, isBuiltin: false);
                        carIdsWithUserFiles.Add(carKv.Key);
                        if (!Settings.CarDefaults.ContainsKey(carKv.Key))
                            Settings.CarDefaults[carKv.Key] = carKv.Key;
                        migrated++;
                    }
                }
            }
            // If steps 1 or 2 actually wrote any new files, refresh the loaded
            // map so step 4's resolution sees them.
            if (migrated > 0) loaded = _carStore.LoadAll();

            // 3) Rebuild Settings.CarDefaults from the folders. It's a runtime
            //    cache now; user library wins on collision (their explicit
            //    choice overrides the factory seed). Any stale persisted dict
            //    value is dropped (the user library file is the truth).
            if (Settings.CarDefaults == null) Settings.CarDefaults = new Dictionary<string, string>();
            Settings.CarDefaults.Clear();
            // Factory car-defaults.json values are on-disk names (no suffix);
            // the merged car-preset map keys factory entries with the
            // " (Built-In)" suffix to keep them separate from any same-named
            // user file. Stamp the suffix when copying factory bindings so
            // ResolveActiveCarPresetName can find the factory entry by key.
            // User bindings are written by SwitchActiveCarPreset already in
            // the right form (suffixed when the user picked a factory row),
            // so they pass through unchanged and override factory on collision.
            foreach (var kv in BuiltinPresets.CarDefaultBindings)
                Settings.CarDefaults[kv.Key] = kv.Value + BuiltinNameSuffix;
            foreach (var kv in UserPresets.CarDefaults)
                Settings.CarDefaults[kv.Key] = kv.Value;

            // 4) Merge BUILT-IN cars from the built-in folder on top of the
            //    user-file map we loaded at the top of this method. Built-in
            //    wins on a (carId, presetName) collision (factory IS the
            //    truth for those). Resolve the active preset per car into
            //    Settings.CarOverrides.
            MergeBuiltinCarPresetsInto(loaded);

            foreach (var carKv in loaded)
            {
                string carId    = carKv.Key;
                var perCar      = carKv.Value;
                string activeName = ResolveActiveCarPresetName(carId, perCar);
                if (activeName != null && perCar.TryGetValue(activeName, out var entry))
                {
                    Settings.CarOverrides[carId] = entry.Override;
                    _lastPersistedCarOverrides[carId] = CloneCarOverride(entry.Override);
                    if (!Settings.CarDefaults.ContainsKey(carId))
                        Settings.CarDefaults[carId] = activeName;
                }
            }

            // Self-heal stale or case-drifted user car-default bindings,
            // same idea as the game-default normalization in
            // RebuildPresetCacheFromFolders. If a Settings.CarDefaults
            // value doesn't match any preset name for that carId in the
            // merged map, either correct the case (case-insensitive) or
            // drop the entry. Avoids "this car has a binding but the
            // active preset never resolves" silent failures.
            {
                var rekey = new List<KeyValuePair<string, string>>();
                var stale = new List<string>();
                // Snapshot: this runs on the library-reload/import path which can
                // overlap a data-tick car-change writing Settings.CarDefaults; the
                // copy avoids a "Collection was modified" throw during enumeration.
                foreach (var kv in new Dictionary<string, string>(Settings.CarDefaults))
                {
                    if (string.IsNullOrEmpty(kv.Value)) continue;
                    if (!loaded.TryGetValue(kv.Key, out var perCar)) { stale.Add(kv.Key); continue; }
                    if (perCar.ContainsKey(kv.Value)) continue;
                    string ciMatch = null;
                    foreach (var k in perCar.Keys)
                    {
                        if (string.Equals(k, kv.Value, StringComparison.OrdinalIgnoreCase))
                        { ciMatch = k; break; }
                    }
                    if (ciMatch != null) rekey.Add(new KeyValuePair<string, string>(kv.Key, ciMatch));
                    else                 stale.Add(kv.Key);
                }
                foreach (var p in rekey)
                {
                    SimHub.Logging.Current.Info($"[TF4ALL] Car default for '{p.Key}' normalized: '{Settings.CarDefaults[p.Key]}' -> '{p.Value}'.");
                    Settings.CarDefaults[p.Key] = p.Value;
                }
                foreach (var k in stale)
                {
                    SimHub.Logging.Current.Warn($"[TF4ALL] Car default for '{k}' dropped: target '{Settings.CarDefaults[k]}' no longer exists (its preset was renamed or removed).");
                    Settings.CarDefaults.Remove(k);
                }
                // Heal the device-wide car-defaults file the same way the
                // game-defaults reconciler does, so a stale binding warns
                // once instead of re-importing forever. Only entries that
                // actually came from the file are written back (in-memory
                // seeds from ResolveActiveCarPresetName never are).
                if (rekey.Count > 0 || stale.Count > 0)
                {
                    try
                    {
                        bool wrote = false;
                        foreach (var p in rekey)
                            if (UserPresets.CarDefaults.ContainsKey(p.Key))
                            { BuiltinPresetWriter.SetCarDefault(UserPresets.CurrentFolder, p.Key, p.Value); wrote = true; }
                        foreach (var k in stale)
                            if (UserPresets.CarDefaults.ContainsKey(k))
                            { BuiltinPresetWriter.RemoveCarDefault(UserPresets.CurrentFolder, k); wrote = true; }
                        if (wrote) UserPresets.Reload();
                    }
                    catch (Exception ex)
                    {
                        SimHub.Logging.Current.Warn($"[TF4ALL] Healing the car-defaults file failed: {ex.Message}");
                    }
                }
            }

            // Overlay the active user's per-user CAR default overrides on
            // top of the device-wide file-based view. Stale entries
            // (preset deleted) silently fall back to the device-wide
            // default; the active-user override doesn't bind the device.
            var slot = GetActiveUserSlot();
            if (slot?.OverrideCarDefaults != null)
            {
                var allPresetMap = GetAllCarPresets();
                foreach (var kv in slot.OverrideCarDefaults)
                {
                    if (string.IsNullOrEmpty(kv.Key) || string.IsNullOrEmpty(kv.Value))
                        continue;
                    if (allPresetMap == null
                        || !allPresetMap.TryGetValue(kv.Key, out var perCar)
                        || perCar == null
                        || !perCar.ContainsKey(kv.Value))
                        continue;
                    Settings.CarDefaults[kv.Key] = kv.Value;
                }
            }

            // User's explicit "None for this car" wins last over any factory
            // built-in or device-wide binding. Without this pass, picking
            // None for a car that has a factory built-in default silently
            // bounces back to the factory pick the next time CarDefaults
            // is rebuilt.
            if (slot?.SuppressedCarDefaults != null && slot.SuppressedCarDefaults.Count > 0)
            {
                foreach (var carId in slot.SuppressedCarDefaults)
                {
                    Settings.CarDefaults.Remove(carId);
                    // The resolve loop above seeded CarOverrides with the
                    // factory tune for any car that has a built-in default,
                    // including one the user cleared to None. Strip that too,
                    // or the wheel plays the suppressed factory preset from
                    // startup until the first car change (the audit's
                    // "None-clear leaves the factory override applied" bug).
                    Settings.CarOverrides?.Remove(carId);
                    _lastPersistedCarOverrides?.Remove(carId);
                }
            }

            if (migrated > 0)
                SimHub.Logging.Current.Info(
                    $"[TF4ALL] Car presets: migrated {migrated} legacy entries.");
        }

        // Add the built-in car presets (loaded from the built-in folder via
        // BuiltinPresets.CarPresetJsons) into the in-memory map alongside the
        // user files. Factory entries are stamped with a " (Built-In)" suffix
        // on both PresetName and the perCar dict key (see below), so they
        // COEXIST with a same-named user entry under a distinct key rather than
        // overwriting it; the runtime resolver adds the suffix when looking up
        // a factory binding.
        private void MergeBuiltinCarPresetsInto(Dictionary<string, Dictionary<string, CarPresetEntry>> map)
        {
            foreach (var kv in BuiltinPresets.CarPresetJsons)
            {
                try
                {
                    var f = Newtonsoft.Json.JsonConvert.DeserializeObject<CarPresetFile>(kv.Value);
                    if (f == null || string.IsNullOrEmpty(f.CarId) || f.Override == null) continue;
                    string presetName = string.IsNullOrEmpty(f.PresetName) ? f.CarId : f.PresetName;
                    var entry = new CarPresetEntry
                    {
                        CarId      = f.CarId,
                        PresetName = presetName,
                        GameName   = f.GameName ?? "",
                        IsBuiltin  = true,
                        Override   = f.Override,
                    };
                    if (!map.TryGetValue(f.CarId, out var perCar))
                    {
                        perCar = new Dictionary<string, CarPresetEntry>(StringComparer.Ordinal);
                        map[f.CarId] = perCar;
                    }
                    // Stamp every factory entry with a " (Built-In)" suffix in
                    // both the entry's PresetName AND the perCar dict key.
                    // This is purely a display-layer rename: the disk file
                    // stays at the original name; the suffix is added here so
                    // (1) the Preset Manager row shows it's a built-in and
                    // (2) user vs factory entries with the same on-disk name
                    // never collide in the merged map. Plugin methods strip
                    // the suffix at disk-op boundaries via ToDiskName.
                    string displayName = presetName + BuiltinNameSuffix;
                    entry.PresetName = displayName;
                    perCar[displayName] = entry;
                }
                catch (Exception ex)
                {
                    SimHub.Logging.Current.Warn($"[TF4ALL] Skipping malformed built-in car preset '{kv.Key}': {ex.Message}");
                }
            }
        }

        /// <summary>Rewrite every on-disk car-preset file for the active car
        /// whose GameName is empty, stamping the current <c>_activeGame</c>.
        /// Skips built-in (default) files because those refresh from
        /// BuiltinCarPresets on Init via InstallOrUpdateBuiltinCarPresets.
        /// Called from DataUpdate's car-change branch behind a per-session
        /// (game, carId) dedup so it runs at most once per pair per session.</summary>
        private void BackfillGameNameForActiveCar()
        {
            try
            {
                var loaded = _carStore.LoadAll();
                if (!loaded.TryGetValue(_activeCarId, out var perCar)) return;
                int rewritten = 0;
                foreach (var entry in perCar.Values)
                {
                    if (entry == null || entry.IsBuiltin) continue;
                    if (!string.IsNullOrEmpty(entry.GameName)) continue;
                    _carStore.Save(entry.CarId, entry.PresetName, _activeGame, entry.Override, isBuiltin: false);
                    rewritten++;
                }
                if (rewritten > 0)
                    SimHub.Logging.Current.Info(
                        $"[TF4ALL] Backfilled GameName='{_activeGame}' on {rewritten} preset(s) for car '{_activeCarId}'.");
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Warn(
                    $"[TF4ALL] BackfillGameNameForActiveCar('{_activeCarId}', '{_activeGame}') failed: {ex.Message}");
            }
        }

        /// <summary>Rename presets whose PresetName equals the carId (the
        /// historical default for newly-saved presets pre-DisplayName) to the
        /// resolver-provided DisplayName. Idempotent — once the rename has
        /// happened, subsequent invocations find PresetName != CarId and skip.
        /// Updates CarDefaults so the pointer to the active preset stays
        /// correct. Skips when the target DisplayName name already exists
        /// (don't clobber a user-saved file with the same name).</summary>
        private void BackfillDisplayNameForActiveCar()
        {
            string carId       = _activeCarId;
            string displayName = _activeCarDisplayName;
            if (string.IsNullOrEmpty(carId) || string.IsNullOrEmpty(displayName)) return;
            // Equal names → nothing to do (e.g. AC carIds are already descriptive)
            if (string.Equals(carId, displayName, StringComparison.OrdinalIgnoreCase)) return;
            try
            {
                var loaded = _carStore.LoadAll();
                if (!loaded.TryGetValue(carId, out var perCar)) return;
                int rewritten = 0;
                // Snapshot keys: we mutate the store inside the loop.
                var names = new List<string>(perCar.Keys);
                foreach (var oldName in names)
                {
                    var entry = perCar[oldName];
                    if (entry == null || entry.IsBuiltin) continue;
                    // Only rename when the user clearly never customized the
                    // preset name. Heuristic: PresetName equals CarId.
                    if (!string.Equals(entry.PresetName, carId, StringComparison.OrdinalIgnoreCase)) continue;
                    // Don't clobber an existing different file at the target name
                    if (_carStore.Exists(carId, displayName)) continue;
                    // Save under new name (writes the new file) and delete the old.
                    _carStore.Save(carId, displayName, _activeGame, entry.Override, isBuiltin: false);
                    _carStore.Delete(carId, oldName);
                    // Re-point CarDefaults if it pointed at the renamed preset.
                    if (Settings?.CarDefaults != null
                        && Settings.CarDefaults.TryGetValue(carId, out var ptr)
                        && string.Equals(ptr, oldName, StringComparison.OrdinalIgnoreCase))
                    {
                        Settings.CarDefaults[carId] = displayName;
                    }
                    // If this was the currently-active preset name, update it
                    // so the UI reflects the rename without needing a reload.
                    if (string.Equals(_activePresetName, oldName, StringComparison.OrdinalIgnoreCase))
                        _activePresetName = displayName;
                    rewritten++;
                }
                if (rewritten > 0)
                {
                    PersistSettingsCore();
                    SimHub.Logging.Current.Info(
                        $"[TF4ALL] Renamed {rewritten} preset(s) for car '{carId}' to '{displayName}'.");
                }
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Warn(
                    $"[TF4ALL] BackfillDisplayNameForActiveCar('{_activeCarId}') failed: {ex.Message}");
            }
        }

        /// <summary>Pick the preset to load for a car. CarDefaults[carId]
        /// wins if it points at a real preset on disk; else fall back to the
        /// first built-in "(default)" preset for the car; else null (no
        /// active preset, effects fall through to globals).</summary>
        private string ResolveActiveCarPresetName(string carId,
            IReadOnlyDictionary<string, CarPresetEntry> perCar)
        {
            if (Settings?.CarDefaults != null
                && Settings.CarDefaults.TryGetValue(carId, out var name)
                && !string.IsNullOrEmpty(name)
                && perCar.ContainsKey(name))
                return name;
            foreach (var kv in perCar)
                if (kv.Value.IsBuiltin) return kv.Key;
            return null;
        }

        /// <summary>Deep-clone a CarOverride so the last-persisted snapshot
        /// is independent of the live in-memory override.</summary>
        private static CarOverride CloneCarOverride(CarOverride o)
        {
            if (o == null) return null;
            return new CarOverride
            {
                EnginePulse  = o.EnginePulse  == null ? null : Clone(o.EnginePulse),
                RoadBumps    = o.RoadBumps    == null ? null : Clone(o.RoadBumps),
                TractionLoss = o.TractionLoss == null ? null : Clone(o.TractionLoss),
                AxleSlip     = o.AxleSlip     == null ? null : Clone(o.AxleSlip),
                KerbThump    = o.KerbThump    == null ? null : Clone(o.KerbThump),
                LockupJudder = o.LockupJudder == null ? null : Clone(o.LockupJudder),
                GearShift    = o.GearShift    == null ? null : Clone(o.GearShift),
                AbsClick     = o.AbsClick     == null ? null : Clone(o.AbsClick),
                PitLimiter   = o.PitLimiter   == null ? null : Clone(o.PitLimiter),
                Drs          = o.Drs          == null ? null : Clone(o.Drs),
                Collision    = o.Collision    == null ? null : Clone(o.Collision),
                RevLimiter   = o.RevLimiter   == null ? null : Clone(o.RevLimiter),
                AudioCapture = CloneOrNull(o.AudioCapture),
                Airborne     = o.Airborne     == null ? null : Clone(o.Airborne),
                ImplementThud = o.ImplementThud == null ? null : Clone(o.ImplementThud),
                // Community lineage is identity, not tuning. A single section
                // edit + Save goes through here (SaveSectionToActiveCarOverride),
                // so dropping these would wipe the downloaded/uploaded lineage on
                // the next save (Share gate then treats it as locally authored
                // and re-uploads as a new row instead of an update).
                CommunitySourceId         = o.CommunitySourceId,
                CommunityUploadedById     = o.CommunityUploadedById,
                CommunityUploadedByUserId = o.CommunityUploadedByUserId,
                CommunityUploadedBodyHash = o.CommunityUploadedBodyHash,
                CommunityUploadedVersion  = o.CommunityUploadedVersion,
                CommunityAllowInPacks     = o.CommunityAllowInPacks,
            };
        }

        /// <summary>Write the active car's override to the active car preset
        /// file (Settings.CarDefaults[activeCarId]) and update the
        /// last-persisted snapshot. Refuses to overwrite a built-in factory
        /// preset; callers must check IsActiveCarPresetBuiltin() and fork
        /// via SaveActiveCarPresetAs(newName) instead. Returns true if the
        /// write happened.</summary>
        public bool PersistActiveCarOverride()
        {
            if (_carStore == null || string.IsNullOrEmpty(_activeCarId) || Settings?.CarOverrides == null) return false;
            string presetName = GetActiveCarPresetName(_activeCarId);
            if (string.IsNullOrEmpty(presetName)) return false;
            // DEV authoring: built-in cars get written through to the factory
            // folder, mirroring the SavePresetAs DEV bypass for games.
            if (IsCarPresetBuiltin(_activeCarId, presetName))
            {
                if (!DevMode) return false;   // non-dev: caller forks via SaveActiveCarPresetAs
                WriteCarBuiltinThroughDev(_activeCarId, presetName);
                return true;
            }

            Settings.CarOverrides.TryGetValue(_activeCarId, out var ovr);
            // Save reports I/O failure via its return now (it catches
            // internally, so a try/catch here would never fire). On failure
            // leave the baseline untouched so a retry still sees the section
            // dirty and the caller can surface "couldn't save".
            if (!_carStore.Save(_activeCarId, presetName, _activeGame ?? "", ovr, isBuiltin: false,
                    defaultAuthor: CurrentAuthorForStamp()))
            {
                SimHub.Logging.Current.Warn($"[TF4ALL] Save of car preset '{presetName}' for '{_activeCarId}' failed (see prior log line).");
                return false;
            }
            // Match Save's keep-rule: an empty-but-community-tracked override
            // is KEPT on disk, so its baseline must be kept too. Dropping it
            // let the next section save rebuild from a bare CarOverride and
            // strip the community lineage.
            if (ovr == null || (ovr.IsEmpty && !ovr.HasCommunityTracking))
                _lastPersistedCarOverrides.Remove(_activeCarId);
            else
                _lastPersistedCarOverrides[_activeCarId] = CloneCarOverride(ovr);
            return true;
        }

        /// <summary>Fork the current live override into a new user preset
        /// for the active car. Sets CarDefaults[activeCarId] to the new
        /// name. Returns true on success. Used by the UI fork-on-default
        /// flow when the user saves changes while on a built-in preset.</summary>
        public bool SaveActiveCarPresetAs(string newPresetName)
        {
            if (_carStore == null || Settings == null || string.IsNullOrEmpty(_activeCarId)) return false;
            if (string.IsNullOrEmpty(newPresetName)) return false;
            // User-typed name might inadvertently carry the display-only
            // " (Built-In)" suffix (e.g. forked from a built-in's auto-suggest);
            // strip so the on-disk filename and CarDefaults binding are clean.
            string newDisk = ToDiskName(newPresetName);
            if (IsCarPresetBuiltin(_activeCarId, newDisk))
            {
                // A user file saved under a factory DISK name is shadowed
                // by the builtin merge: it never shows in the dropdown and
                // the factory content wins after restart. Refuse instead
                // of writing an invisible file (backstop behind the UI's
                // suggestion diversion; also catches a hand-typed name).
                SimHub.Logging.Current.Warn(
                    $"[TF4ALL] Refusing to save car preset '{newDisk}' for '{_activeCarId}': that name belongs to a built-in. Pick a different name.");
                return false;
            }
            Settings.CarOverrides.TryGetValue(_activeCarId, out var ovr);
            if (ovr == null || (ovr.IsEmpty && !ovr.HasCommunityTracking))
            {
                // CarPresetStore.Save silently deletes-and-returns for an
                // empty override, so proceeding would mint a binding to a
                // file that was never written: the caller reports success,
                // and the next restart drops the dangling binding back to
                // the previous preset (the v0.2.5 SAVE-BOTH on-wheel repro,
                // where SavePresetAs's draft fold had just emptied the
                // override). No car-specific tuning is a failure here.
                SimHub.Logging.Current.Warn(
                    $"[TF4ALL] Fork '{newDisk}' for '{_activeCarId}' aborted: no car-specific tuning to save.");
                return false;
            }
            // A failed write must abort the fork BEFORE binding: binding to a
            // name whose file was never written leaves a dangling default
            // that ReloadActiveCarOverrideFromStore then resolves to nothing,
            // wiping the live tuning (the audit's fork gun). Save reports the
            // failure via its return.
            if (!_carStore.Save(_activeCarId, newDisk, _activeGame ?? "", ovr, isBuiltin: false,
                    defaultAuthor: CurrentAuthorForStamp()))
            {
                SimHub.Logging.Current.Warn($"[TF4ALL] Fork of car preset '{newDisk}' for '{_activeCarId}' failed (see prior log line); not binding.");
                return false;
            }
            // Match Save's keep-rule (empty-but-tracked files are kept).
            if (ovr == null || (ovr.IsEmpty && !ovr.HasCommunityTracking))
                _lastPersistedCarOverrides.Remove(_activeCarId);
            else
                _lastPersistedCarOverrides[_activeCarId] = CloneCarOverride(ovr);
            // Bind through the durable path. The old raw
            // Settings.CarDefaults[carId] write only lived until the next
            // library rebuild: post-migration CarDefaults is never
            // serialized (ShouldSerializeCarDefaults) and
            // LoadAndMigrateCarPresets reconstructs it from
            // car-defaults.json + slot overrides, neither of which the raw
            // write touched, so every fork's binding silently evaporated on
            // restart (the CarDefaults analog of the GameDefaults raw-write
            // bug fixed in the select-is-default rework).
            // SwitchActiveCarPreset persists the binding properly and
            // reloads the override from the file just saved (identical
            // content, so no feel change).
            if (!SwitchActiveCarPreset(_activeCarId, newDisk))
            {
                SimHub.Logging.Current.Warn(
                    $"[TF4ALL] Car preset '{newDisk}' saved but binding it for '{_activeCarId}' failed.");
                return false;
            }
            return true;
        }

        /// <summary>Wipe a car's per-car file AND its in-memory override.
        /// Refused for built-in presets (delete-protection). The car will
        /// fall back to the next-best preset (factory default if one exists,
        /// else globals) on its next ApplyActiveCarOverride.</summary>
        public bool DeleteCarPreset(string carId, string presetName)
        {
            if (_carStore == null || string.IsNullOrEmpty(carId) || string.IsNullOrEmpty(presetName)) return false;
            // presetName from UI carries the " (Built-In)" suffix for factory
            // entries; disk file names never do. Strip to the on-disk form for
            // any file/dict lookup.
            string diskName = ToDiskName(presetName);
            // A user file shadowed under a factory disk name is a deletable
            // leftover, not the factory preset (which lives in the built-in
            // folder). Refuse only an ACTUAL factory preset - a factory name
            // with no user file to remove - so the user can recover a frozen
            // shadow file that the suffix-agnostic builtin check otherwise
            // locked (the audit's "no UI path to remove their own file").
            bool userFileExists = _carStore.Exists(carId, diskName);
            bool wasBuiltin = IsCarPresetBuiltin(carId, presetName) && !userFileExists;
            if (wasBuiltin && !DevMode) return false;   // DEV authoring may delete built-ins
            string game = GetCarPresetGame(carId, presetName);
            if (!_carStore.Delete(carId, diskName))
            {
                SimHub.Logging.Current.Warn($"[TF4ALL] Delete of car preset '{carId}/{diskName}' failed (see prior log line).");
                return false;
            }
            if (Settings?.CarDefaults != null
                && Settings.CarDefaults.TryGetValue(carId, out var active)
                && string.Equals(active, presetName, StringComparison.Ordinal))
            {
                Settings.CarDefaults.Remove(carId);
                if (carId == _activeCarId)
                    ReloadActiveCarOverrideFromStore();
            }
            if (wasBuiltin && DevMode)
            {
                try
                {
                    BuiltinPresetWriter.DeleteCar(BuiltinPresets.CurrentFolder, game ?? "", carId, diskName);
                    // If that was the car's built-in default, drop the binding.
                    // CarDefaultBindings values come from car-defaults.json (disk
                    // form, never suffixed), so compare against diskName.
                    if (BuiltinPresets.CarDefaultBindings.TryGetValue(carId, out var def)
                        && string.Equals(def, diskName, StringComparison.Ordinal))
                        BuiltinPresetWriter.RemoveCarDefault(BuiltinPresets.CurrentFolder, carId);
                    BuiltinPresets.Reload();
                }
                catch (Exception ex) { SimHub.Logging.Current.Warn($"[TF4ALL] DEV delete car folder file failed: {ex.Message}"); }
            }
            PersistSettingsCore();
            RequestAutoBackup();   // car preset file deleted: persist the default change + arm auto-sync
            return true;
        }

        /// <summary>Rename a car preset on disk. Updates CarDefaults for that
        /// car if the renamed preset was the active one. Refuses on built-ins
        /// and when the target name already exists for that car. Used by the
        /// preset manager.</summary>
        public bool RenameCarPreset(string carId, string oldName, string newName)
        {
            if (_carStore == null || Settings == null) return false;
            if (string.IsNullOrEmpty(carId) || string.IsNullOrEmpty(oldName) || string.IsNullOrEmpty(newName)) return false;
            if (string.Equals(oldName, newName, StringComparison.Ordinal)) return true;
            // A shadowed user file (factory disk name with a real file on
            // disk) is renamable - renaming it away from the factory name is
            // itself the way to un-freeze it. Refuse only an actual factory
            // preset with no user file to move.
            bool userFileExists = _carStore.Exists(carId, ToDiskName(oldName));
            bool wasBuiltin = IsCarPresetBuiltin(carId, oldName) && !userFileExists;
            if (wasBuiltin && !DevMode)
            {
                SimHub.Logging.Current.Warn($"[TF4ALL] Refusing to rename built-in car preset '{carId}/{oldName}'.");
                return false;
            }
            // The names from UI may carry the " (Built-In)" suffix (factory
            // rows) -- strip to the disk form for file/dict ops. Don't allow
            // the suffix in user-typed newName either (that's display sugar,
            // not a real name).
            string oldDisk = ToDiskName(oldName);
            string newDisk = ToDiskName(newName);
            // Collision check needs to consider built-ins too in DEV (otherwise
            // we'd silently overwrite a sibling built-in for the same car).
            if (_carStore.Exists(carId, newDisk)) return false;
            if (BuiltinPresets.CarPresetJsons.ContainsKey(carId + "/" + newDisk)) return false;

            if (wasBuiltin)
            {
                // DEV: rename the factory file + rewrite its inner PresetName so
                // the load key (carId + "/" + PresetName) matches the new filename.
                string game = GetCarPresetGame(carId, oldName) ?? "";
                BuiltinPresetWriter.RenameCar(BuiltinPresets.CurrentFolder, game, carId, oldDisk, newDisk);
                try
                {
                    if (BuiltinPresets.CarPresetJsons.TryGetValue(carId + "/" + oldDisk, out var staleJson))
                    {
                        var f = Newtonsoft.Json.JsonConvert.DeserializeObject<CarPresetFile>(staleJson);
                        if (f != null)
                        {
                            f.PresetName = newDisk;
                            f.IsBuiltin = true;
                            string json = Newtonsoft.Json.JsonConvert.SerializeObject(f, Newtonsoft.Json.Formatting.Indented);
                            BuiltinPresetWriter.WriteCar(BuiltinPresets.CurrentFolder, f.GameName ?? game, carId, newDisk, json);
                        }
                    }
                }
                catch (Exception ex) { SimHub.Logging.Current.Warn($"[TF4ALL] DEV rename PresetName rewrite failed: {ex.Message}"); }
                BuiltinPresets.Reload();
                LoadAndMigrateCarPresets();
                if (carId == _activeCarId) ReloadActiveCarOverrideFromStore();
                SimHub.Logging.Current.Info($"[TF4ALL] DEV: renamed built-in car preset '{carId}/{oldDisk}' to '{newDisk}'.");
                return true;
            }

            var loaded = _carStore.LoadAll();
            if (!loaded.TryGetValue(carId, out var perCar) || !perCar.TryGetValue(oldDisk, out var entry)) return false;

            // Keep pack identity across a rename so the Source column doesn't
            // flip to "Local" for an imported preset the user renamed.
            _carStore.Save(carId, newDisk, entry.GameName ?? "", entry.Override, isBuiltin: false,
                packName: entry.PackName, author: entry.Author);
            _carStore.Delete(carId, oldDisk);

            if (Settings.CarDefaults != null
                && Settings.CarDefaults.TryGetValue(carId, out var active)
                && string.Equals(active, oldName, StringComparison.Ordinal))
            {
                Settings.CarDefaults[carId] = newDisk;
                PersistSettingsCore();
            }
            if (carId == _activeCarId) ReloadActiveCarOverrideFromStore();
            RequestAutoBackup();   // car preset file renamed: arm auto-sync
            SimHub.Logging.Current.Info($"[TF4ALL] Renamed car preset '{carId}/{oldName}' to '{newName}'.");
            return true;
        }

        /// <summary>Deep-copy a car preset under a new name (same carId).
        /// JSON round-trip clone so the new file is independent. Refuses if
        /// the target already exists.</summary>
        public string DuplicateCarPreset(string carId, string sourceName, string newName = null)
        {
            if (_carStore == null) return null;
            if (string.IsNullOrEmpty(carId) || string.IsNullOrEmpty(sourceName)) return null;
            // newName null/blank = auto-name with the numeric-suffix
            // convention; see DuplicatePreset (owner call 2026-07-13).
            if (string.IsNullOrWhiteSpace(newName))
                newName = MakeUniqueCarPresetName(carId, ToDiskName(sourceName));
            // sourceName may be a factory display name (suffixed); pull from
            // the merged map (which has both user + suffixed factory entries)
            // and persist the clone as a user file under the on-disk newName.
            string sourceDisk = ToDiskName(sourceName);
            string newDisk    = ToDiskName(newName);
            if (_carStore.Exists(carId, newDisk)) return null;

            CarPresetEntry entry = null;
            var all = GetAllCarPresets();
            if (all != null && all.TryGetValue(carId, out var perCarAll))
                perCarAll.TryGetValue(sourceName, out entry);

            if (entry == null) return null;
            var json = Newtonsoft.Json.JsonConvert.SerializeObject(entry.Override);
            var clone = Newtonsoft.Json.JsonConvert.DeserializeObject<CarOverride>(json, SafeJson.Settings);
            // A duplicate of an imported preset stays attributed to its
            // pack. When the source had no Author, stamp the duplicator (the
            // user) via defaultAuthor so the new preset reads as theirs in
            // the Source column. Carry Description + AuthorVersion too so
            // the duplicate is a faithful copy, not a metadata-stripped one.
            _carStore.Save(carId, newDisk, entry.GameName ?? "", clone, isBuiltin: false,
                packName:      entry.PackName,
                author:        entry.Author,
                description:   entry.Description,
                authorVersion: entry.AuthorVersion,
                defaultAuthor: CurrentAuthorForStamp());
            RequestAutoBackup();   // new car preset file: arm auto-sync so the duplicate propagates
            SimHub.Logging.Current.Info($"[TF4ALL] Duplicated car preset '{carId}/{sourceDisk}' as '{newDisk}'.");
            return newDisk;
        }

        /// <summary>Re-resolve the active preset for the active car after a
        /// preset switch / delete and update Settings.CarOverrides + the
        /// persisted-snapshot baseline + the live effect parameters.</summary>
        public void ReloadActiveCarOverrideFromStore()
        {
            if (string.IsNullOrEmpty(_activeCarId) || Settings == null || _carStore == null) return;
            var loaded = _carStore.LoadAll();
            // The store only walks the user library; factory presets must be
            // merged in here just like the startup load and GetCarPresets do.
            // Without the merge a builtin-bound car's suffixed name never
            // resolves below, both fallthrough branches remove the override,
            // and the factory tune goes silent on every car change or
            // dropdown pick while the picker still shows it active (the
            // 2026-07 save-matrix audit's "factory presets are inert"
            // blocker).
            MergeBuiltinCarPresetsInto(loaded);
            if (!loaded.TryGetValue(_activeCarId, out var perCar) || perCar.Count == 0)
            {
                Settings.CarOverrides.Remove(_activeCarId);
                _lastPersistedCarOverrides.Remove(_activeCarId);
                ApplyActiveCarOverride();
                return;
            }
            // Explicit None stays None: with built-ins merged here, the
            // resolver's no-binding fallback would otherwise re-pin the
            // first factory entry for a car the user cleared (suppression
            // latched by ClearCarPresetBindingCore). Honor it the way the
            // startup rebuild's suppression pass does.
            bool hasBinding = Settings.CarDefaults != null
                && Settings.CarDefaults.TryGetValue(_activeCarId, out var boundTo)
                && !string.IsNullOrEmpty(boundTo);
            if (!hasBinding)
            {
                var slotNone = GetActiveUserSlot();
                if (slotNone?.SuppressedCarDefaults != null
                    && slotNone.SuppressedCarDefaults.Contains(_activeCarId))
                {
                    Settings.CarOverrides.Remove(_activeCarId);
                    _lastPersistedCarOverrides.Remove(_activeCarId);
                    ApplyActiveCarOverride();
                    return;
                }
            }
            string activeName = ResolveActiveCarPresetName(_activeCarId, perCar);
            if (activeName != null && perCar.TryGetValue(activeName, out var entry))
            {
                Settings.CarOverrides[_activeCarId] = entry.Override;
                _lastPersistedCarOverrides[_activeCarId] = CloneCarOverride(entry.Override);
                if (Settings.CarDefaults == null) Settings.CarDefaults = new Dictionary<string, string>();
                Settings.CarDefaults[_activeCarId] = activeName;
            }
            else
            {
                Settings.CarOverrides.Remove(_activeCarId);
                _lastPersistedCarOverrides.Remove(_activeCarId);
            }
            ApplyActiveCarOverride();
        }

        /// <summary>Switch the active preset for a car to the named one and
        /// reload the override into live state. Used by the dropdown.</summary>
        public bool SwitchActiveCarPreset(string carId, string presetName)
        {
            if (string.IsNullOrEmpty(carId) || string.IsNullOrEmpty(presetName)) return false;
            if (Settings == null) return false;
            // Don't bind to a preset that doesn't exist. A stale name (e.g.
            // a fork whose file failed to write, or a deleted preset) would
            // otherwise write a dangling default that the next reload
            // resolves to nothing, wiping the live override. A real preset
            // is either a user file on disk or a known factory entry.
            string diskName = ToDiskName(presetName);
            bool presetExists = (_carStore != null && _carStore.Exists(carId, diskName))
                                || IsCarPresetBuiltin(carId, presetName);
            if (!presetExists)
            {
                SimHub.Logging.Current.Warn(
                    $"[TF4ALL] Refusing to bind car '{carId}' to '{presetName}': no such preset on disk or in the factory set.");
                return false;
            }
            if (Settings.CarDefaults == null) Settings.CarDefaults = new Dictionary<string, string>();
            // Effective view bumps either way - existing readers see the
            // new binding immediately, regardless of whether it goes to
            // the file or the slot override.
            Settings.CarDefaults[carId] = presetName;

            // Per-user defaults: first-setter writes the device-wide
            // car-defaults.json (shared across local users); every
            // subsequent set goes to the active user's slot override
            // so other accounts on this install keep their own choice.
            bool deviceWideAlreadySet =
                UserPresets.CarDefaults != null
                && UserPresets.CarDefaults.TryGetValue(carId, out var existing)
                && !string.IsNullOrEmpty(existing);
            if (!deviceWideAlreadySet)
            {
                try
                {
                    BuiltinPresetWriter.SetCarDefault(UserPresets.CurrentFolder, carId, presetName);
                    UserPresets.Reload();
                }
                catch (Exception ex)
                {
                    SimHub.Logging.Current.Warn($"[TF4ALL] Persist car-default for '{carId}' failed: {ex.Message}");
                }
            }
            else
            {
                var slot = GetActiveUserSlot();
                if (slot != null)
                {
                    if (slot.OverrideCarDefaults == null)
                        slot.OverrideCarDefaults = new Dictionary<string, string>();
                    slot.OverrideCarDefaults[carId] = presetName;
                    try { PersistSettingsCore(); }
                    catch (Exception ex)
                    {
                        SimHub.Logging.Current.Warn(
                            $"[TF4ALL] Persist user car-default override for '{carId}' failed: {ex.Message}");
                    }
                }
            }
            // The user just picked a binding for this car explicitly, so
            // any prior "None" suppression for it is no longer their
            // intent. Drop the slot's suppression marker if present.
            ClearCarSuppression(carId);
            if (carId == _activeCarId) ReloadActiveCarOverrideFromStore();
            return true;
        }

        /// <summary>Drop a car's "None" suppression marker on the active slot.
        /// A fresh explicit binding (dropdown pick, import, set-pack-as-
        /// defaults) overrides a prior None choice, so the startup rebuild's
        /// suppression pass must not strip the new binding back out.</summary>
        private void ClearCarSuppression(string carId)
        {
            if (string.IsNullOrEmpty(carId)) return;
            GetActiveUserSlot()?.SuppressedCarDefaults?.Remove(carId);
        }

        /// <summary>Set a car's default preset (the Presets-tab "Set as default"
        /// action). Same as SwitchActiveCarPreset, but in DEV authoring mode it
        /// also writes car-defaults.json so the built-in default is recorded in
        /// the folder. (SwitchActiveCarPreset itself stays folder-free since
        /// it's also used while just selecting a car to edit.)</summary>
        public bool SetCarDefaultPreset(string carId, string presetName)
        {
            if (!SwitchActiveCarPreset(carId, presetName)) return false;
            if (DevMode)
            {
                // Factory car-defaults.json references on-disk filenames -- strip
                // the display suffix before writing or future loads of the file
                // would point at "<name> (Built-In)" which doesn't exist on disk.
                try { BuiltinPresetWriter.SetCarDefault(BuiltinPresets.CurrentFolder, carId, ToDiskName(presetName)); BuiltinPresets.Reload(); }
                catch (Exception ex) { SimHub.Logging.Current.Warn($"[TF4ALL] DEV write car-default failed: {ex.Message}"); }
            }
            return true;
        }

        /// <summary>Make <paramref name="carId"/> the active car for editing AND
        /// switch it to <paramref name="presetName"/>, even when telemetry hasn't
        /// identified a car (paused / menu) or you're physically in a different
        /// car. Pins _activeCarId so the normal per-car flow (live override,
        /// slider edits, Save) targets this car and its preset loads live. While
        /// you're actually driving, the next telemetry frame re-asserts the real
        /// car; while paused / at a menu the pin holds. Lets the car-preset
        /// picker work any time, which is what the UI needs.</summary>
        public bool SelectCarForEditing(string carId, string presetName)
        {
            if (string.IsNullOrEmpty(carId) || string.IsNullOrEmpty(presetName)) return false;
            _activeCarId = carId;                            // pin as active
            return SwitchActiveCarPreset(carId, presetName); // carId == _activeCarId now -> reloads + applies
        }

        /// <summary>Clear a car's per-car preset selection so it stops applying
        /// a per-car override and falls back to the game preset's globals. Pins
        /// the car as active, drops its CarDefaults entry and live override, and
        /// re-applies (no override = game globals), then persists. The car
        /// picker's "None" row and the dash picker's NONE row call this. The
        /// saved preset FILES are left on disk (this is a deselect, not a
        /// delete). The explicit None sticks even for cars shipping a factory
        /// built-in preset: the SuppressedCarDefaults marker below keeps the
        /// rebuild from restoring the factory binding.</summary>
        public bool ClearActiveCarPreset(string carId)
        {
            if (string.IsNullOrEmpty(carId) || Settings == null) return false;
            _activeCarId = carId;   // pin so the apply targets this car
            ClearCarPresetBindingCore(carId);
            // Re-derive the full in-memory effective view. Fine HERE because
            // the reload's override rewrite only clobbers the draft of the
            // car being cleared, which is the point of a clear (desktop
            // confirms the discard first). ClearCarDefaultPreset must NOT
            // do this: see the note there.
            try { LoadAndMigrateCarPresets(); } catch { }
            ApplyActiveCarOverride();   // override or globals, whichever wins now
            PersistSettings();
            // If this car was only pinned by a manual UI pick (we're parked, not
            // actually driving it), releasing its preset should also release the
            // active car so the picker un-filters back to the full per-game list
            // and Car Facts hides. While actually driving, the next telemetry
            // frame re-asserts the real car, so we must NOT unpin then.
            if (!IsLiveCarPresent && string.Equals(_activeCarId, carId, StringComparison.Ordinal))
                _activeCarId = null;
            return true;
        }

        /// <summary>Clear a car's default preset WITHOUT disturbing the live
        /// state of whichever car is actually active. The Preset Manager's
        /// "Clear default" action calls this for arbitrary cars: pinning the
        /// target as active (what ClearActiveCarPreset does) would briefly
        /// retarget the live wheel while the user is driving something else.
        /// For the active car it delegates to ClearActiveCarPreset so the
        /// cleared override also stops sounding immediately.</summary>
        public bool ClearCarDefaultPreset(string carId)
        {
            if (string.IsNullOrEmpty(carId) || Settings == null) return false;
            if (string.Equals(carId, _activeCarId, StringComparison.Ordinal))
                return ClearActiveCarPreset(carId);
            ClearCarPresetBindingCore(carId);
            // Deliberately NO LoadAndMigrateCarPresets here: the full reload
            // rewrites EVERY car's CarOverrides entry from disk, which would
            // silently wipe the ACTIVE car's unsaved draft while the user is
            // driving it. The core's targeted removals already leave this
            // car's effective state correct (no binding, no override, None
            // suppressed), and no other car's state changed.
            PersistSettings();
            return true;
        }

        // Shared deselect plumbing for the two clears above: drop the binding
        // (per-user override first, else device-wide file), the cached
        // CarDefaults/CarOverrides entries, and latch the explicit-None
        // suppression. Callers own the active-car pinning, any full-view
        // reload (NOT safe for non-active cars, see ClearCarDefaultPreset),
        // live re-apply, and persist.
        private void ClearCarPresetBindingCore(string carId)
        {
            // Per-user defaults: if THIS user has an override binding
            // for the car, drop just the override (they fall back to
            // the install-wide binding). Otherwise drop from the
            // device-wide car-defaults.json so the install no longer
            // auto-loads anything for the car.
            var slot = GetActiveUserSlot();
            bool clearedOverride = false;
            if (slot?.OverrideCarDefaults != null
                && slot.OverrideCarDefaults.Remove(carId))
            {
                clearedOverride = true;
            }
            if (!clearedOverride)
            {
                try
                {
                    BuiltinPresetWriter.RemoveCarDefault(UserPresets.CurrentFolder, carId);
                    UserPresets.Reload();
                }
                catch (Exception ex)
                {
                    SimHub.Logging.Current.Warn(
                        $"[TF4ALL] Clear car default for '{carId}' failed: {ex.Message}");
                }
            }
            Settings.CarDefaults?.Remove(carId);
            Settings.CarOverrides?.Remove(carId);
            _lastPersistedCarOverrides?.Remove(carId);
            // Record the user's explicit "None" decision in the active slot
            // so the rebuild can suppress any factory built-in binding for
            // this car. Without this the rebuild restores the factory
            // default whenever one exists and the user's None pick bounces.
            if (slot != null)
            {
                if (slot.SuppressedCarDefaults == null)
                    slot.SuppressedCarDefaults = new HashSet<string>(StringComparer.Ordinal);
                slot.SuppressedCarDefaults.Add(carId);
            }
        }

        /// <summary>Returns the preset name currently active for a car
        /// (CarDefaults lookup), or null if unset.</summary>
        public string GetActiveCarPresetName(string carId)
        {
            if (Settings?.CarDefaults == null || string.IsNullOrEmpty(carId)) return null;
            return Settings.CarDefaults.TryGetValue(carId, out var n) ? n : null;
        }

        /// <summary>Returns all presets currently on disk for a car. Empty
        /// dict if the car has none. Used by the UI to populate the
        /// per-car preset dropdown. Includes factory built-ins merged on top
        /// of user files (built-in wins on a same-name collision).</summary>
        public IReadOnlyDictionary<string, CarPresetEntry> GetCarPresets(string carId)
        {
            if (_carStore == null || string.IsNullOrEmpty(carId))
                return new Dictionary<string, CarPresetEntry>();
            var loaded = _carStore.LoadAll();
            MergeBuiltinCarPresetsInto(loaded);
            return loaded.TryGetValue(carId, out var perCar)
                ? perCar
                : new Dictionary<string, CarPresetEntry>();
        }

        /// <summary>Returns every car preset across every car, indexed by
        /// carId then presetName. Single LoadAll pass for the preset manager
        /// (used when no specific car is active). Includes factory built-ins
        /// so the preset manager can tag them with the Built-in badge.</summary>
        public IReadOnlyDictionary<string, IReadOnlyDictionary<string, CarPresetEntry>> GetAllCarPresets()
        {
            if (_carStore == null)
                return new Dictionary<string, IReadOnlyDictionary<string, CarPresetEntry>>();
            var raw = _carStore.LoadAll();
            MergeBuiltinCarPresetsInto(raw);
            var wrapped = new Dictionary<string, IReadOnlyDictionary<string, CarPresetEntry>>(raw.Count);
            foreach (var kv in raw) wrapped[kv.Key] = kv.Value;
            return wrapped;
        }

        /// <summary>Display-layer suffix that MergeBuiltinCarPresetsInto stamps
        /// on every factory car preset's PresetName, so user vs factory entries
        /// with the same on-disk name don't collide in the merged map and so the
        /// UI row clearly reads as a built-in. Disk filenames never include the
        /// suffix; ToDiskName strips it back off at disk-op boundaries.</summary>
        public const string BuiltinNameSuffix = " (Built-In)";

        /// <summary>True iff <paramref name="name"/> ends with the built-in
        /// display suffix (i.e. was stamped by MergeBuiltinCarPresetsInto).</summary>
        internal static bool HasBuiltinSuffix(string name)
            => !string.IsNullOrEmpty(name)
            && name.EndsWith(BuiltinNameSuffix, StringComparison.Ordinal);

        /// <summary>Return the on-disk PresetName by stripping the
        /// " (Built-In)" suffix when present. Idempotent; safe to call on
        /// names that don't have the suffix (user presets, factory names
        /// already loaded from disk).</summary>
        internal static string ToDiskName(string name)
            => HasBuiltinSuffix(name)
                ? name.Substring(0, name.Length - BuiltinNameSuffix.Length)
                : name;

        /// <summary>True iff the named car preset is a factory built-in.
        /// Requires the display suffix AND a matching unsuffixed entry in
        /// BuiltinPresets.CarPresetJsons: that way a user file literally
        /// named "X" (with the factory also shipping "X") isn't mistaken
        /// for the factory entry just because the names overlap.</summary>
        public bool IsCarPresetBuiltin(string carId, string presetName)
        {
            if (string.IsNullOrEmpty(carId) || string.IsNullOrEmpty(presetName))
                return false;
            // Match against the factory set by DISK name, with or without
            // the display suffix. Bindings reach here in both forms (the
            // account car-defaults file stores the suffixed display name;
            // the rebuilt in-memory CarDefaults can hold the bare name),
            // and requiring the suffix let a bare factory name slip
            // through as "user": saves then wrote a user-folder file the
            // builtin merge SHADOWS, so the save was invisible in the
            // dropdown and ineffective after restart (the 2026-07-22
            // Both-on-factory repro). A user file deliberately named like
            // a factory preset is shadowed by the merge anyway, so
            // treating the name as built-in is truthful either way.
            string disk = ToDiskName(presetName);
            return BuiltinPresets.CarPresetJsons.ContainsKey(carId + "/" + disk);
        }

        // ---------- Source attribution (Preset Manager "Source" column) ----------

        /// <summary>Label shown in the Preset Manager's Source column for a
        /// game preset row. "Built-In" for factory presets, the pack label for
        /// presets recorded in the installed-packs sidecar, the snapshot's
        /// own PackName/Author (for stamped local saves or recovered pack
        /// metadata when the sidecar entry was lost), else "Local".</summary>
        public string ResolveGamePresetSource(string presetName, bool isBuiltin)
        {
            if (isBuiltin) return "Built-In";
            var pack = _installedPacks?.FindPackForGame(presetName);
            var fromPack = PackLabel(pack?.PackName, pack?.Author);
            if (fromPack != null) return fromPack;
            // Fallback: read the snapshot's own attribution. Catches both
            // user-stamped local presets (snap.Author = SharingAuthor) and
            // orphan pack-imported presets whose sidecar entry was lost.
            // Seeded-from-AC-baseline sentinel is treated as Local (the user
            // hasn't touched it yet; once they do, the sentinel clears).
            GameSettingsSnapshot snap = null;
            if (Settings?.Presets != null) Settings.Presets.TryGetValue(presetName, out snap);
            string snapPack = NullIfBlank(snap?.PackName);
            if (string.Equals(snapPack, SeededPresetSentinel, StringComparison.Ordinal)) snapPack = null;
            return PackLabel(snapPack, snap?.Author) ?? "Local";
        }

        // Author string stamped on locally-saved presets. Null when the user
        // hasn't set Settings.SharingAuthor, in which case saves leave Author
        // blank and ResolveGamePresetSource falls through to "Local". Single
        // source of truth so the policy lives in one place.
        private string CurrentAuthorForStamp() => NullIfBlank(Settings?.SharingAuthor);

        // Sentinel PackName stamped on the AC-baseline seed file written by
        // EnsureSeededGamePreset. Used in two places: (a) BackfillAuthorOnLocal-
        // Presets skips snapshots carrying this so an untouched seed never
        // gets attributed to the user; (b) SaveSectionToActivePreset clears
        // it on the user's first edit, after which the preset behaves like
        // any other user-authored work. The literal string is chosen to be
        // unambiguous if it ever leaks into the UI (which it shouldn't).
        internal const string SeededPresetSentinel = "(seeded from Assetto Corsa baseline)";

        /// <summary>One-shot backfill: walk every user-library game-preset
        /// and car-preset file, set Author = <paramref name="author"/> on
        /// the ones whose Author AND PackName are both blank (= the user's
        /// own unattributed work). Files that already carry pack lineage or
        /// an explicit author are left alone. Returns the count of files
        /// touched. Triggered from the Settings UI on the first blank-to-set
        /// transition of Settings.SharingAuthor.</summary>
        public int BackfillAuthorOnLocalPresets(string author)
        {
            author = NullIfBlank(author);
            if (author == null) return 0;
            int touched = 0;

            // ---- Game presets ----
            try
            {
                string gamesDir = System.IO.Path.Combine(UserPresets.CurrentFolder ?? "", "games");
                if (System.IO.Directory.Exists(gamesDir))
                {
                    foreach (var path in System.IO.Directory.GetFiles(gamesDir, "*.json"))
                    {
                        try
                        {
                            var snap = Newtonsoft.Json.JsonConvert.DeserializeObject<GameSettingsSnapshot>(
                                System.IO.File.ReadAllText(path));
                            if (snap == null) continue;
                            if (!string.IsNullOrEmpty(snap.Author) || !string.IsNullOrEmpty(snap.PackName)) continue;
                            snap.Author = author;
                            System.IO.File.WriteAllText(path,
                                Newtonsoft.Json.JsonConvert.SerializeObject(snap, Newtonsoft.Json.Formatting.Indented));
                            touched++;
                        }
                        catch (Exception ex)
                        {
                            SimHub.Logging.Current.Warn($"[TF4ALL] Backfill: couldn't update '{path}': {ex.Message}");
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Warn($"[TF4ALL] Backfill (games) failed: {ex.Message}");
            }

            // ---- Car presets ----
            try
            {
                string carsRoot = System.IO.Path.Combine(UserPresets.CurrentFolder ?? "", "cars");
                if (System.IO.Directory.Exists(carsRoot))
                {
                    foreach (var path in System.IO.Directory.GetFiles(carsRoot, "*.json", System.IO.SearchOption.AllDirectories))
                    {
                        // Skip the cleanup-archive backups produced by the
                        // legacy-builtin cleanup migration.
                        if (path.IndexOf($"{System.IO.Path.DirectorySeparatorChar}.cleanup-", StringComparison.Ordinal) >= 0)
                            continue;
                        try
                        {
                            var f = Newtonsoft.Json.JsonConvert.DeserializeObject<CarPresetFile>(
                                System.IO.File.ReadAllText(path));
                            if (f == null || f.Override == null) continue;
                            if (!string.IsNullOrEmpty(f.Author) || !string.IsNullOrEmpty(f.PackName)) continue;
                            f.Author = author;
                            System.IO.File.WriteAllText(path,
                                Newtonsoft.Json.JsonConvert.SerializeObject(f, Newtonsoft.Json.Formatting.Indented));
                            touched++;
                        }
                        catch (Exception ex)
                        {
                            SimHub.Logging.Current.Warn($"[TF4ALL] Backfill: couldn't update '{path}': {ex.Message}");
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Warn($"[TF4ALL] Backfill (cars) failed: {ex.Message}");
            }

            // Reload + rebuild so the in-memory cache reflects the new
            // attribution and the Source column refreshes on next read.
            try
            {
                UserPresets.Reload();
                RebuildPresetCacheFromFolders();
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Warn($"[TF4ALL] Backfill reload failed: {ex.Message}");
            }

            SimHub.Logging.Current.Info($"[TF4ALL] Author backfill: stamped '{author}' on {touched} local preset file(s).");
            return touched;
        }

        /// <summary>Label shown in the Preset Manager's Source column for a car
        /// preset row. "Built-In" for factory presets; else the pack label when
        /// the preset is in the installed-packs sidecar OR the on-disk car file
        /// carries pack metadata (passed in by the caller); else "Local".</summary>
        public string ResolveCarPresetSource(string carId, string presetName, bool isBuiltin,
            string filePackName = null, string fileAuthor = null)
        {
            if (isBuiltin) return "Built-In";
            // Sidecar first (richest identity), then the car file's own
            // PackName/Author (loose-imported single car files), then Local.
            var pack = _installedPacks?.FindPackForCar(carId, presetName);
            return PackLabel(pack?.PackName, pack?.Author)
                ?? PackLabel(filePackName, fileAuthor)
                ?? "Local";
        }

        // Compose a Source label from a pack name and author. Prefer
        // "PackName (Author)" when both exist, else PackName, else Author.
        // Returns null when neither is present (caller falls back to "Local").
        private static string PackLabel(string packName, string author)
        {
            string p = NullIfBlank(packName);
            string a = NullIfBlank(author);
            if (p != null && a != null) return $"{p} ({a})";
            return p ?? a;
        }

        /// <summary>True iff the active preset for the active car is a
        /// factory built-in. Used by the UI to gate save behavior.</summary>
        public bool IsActiveCarPresetBuiltin()
        {
            if (string.IsNullOrEmpty(_activeCarId)) return false;
            string presetName = GetActiveCarPresetName(_activeCarId);
            return !string.IsNullOrEmpty(presetName) && IsCarPresetBuiltin(_activeCarId, presetName);
        }

        /// <summary>True iff the live per-car override for the active car
        /// has drifted from the snapshot last loaded from disk. Used by the
        /// UI to roll car-preset edits into the global "★ unsaved"
        /// indicator and to gate the Save preset button's car-side save
        /// step.</summary>
        public bool IsActiveCarPresetDirty()
        {
            if (Settings?.CarOverrides == null || string.IsNullOrEmpty(_activeCarId)) return false;
            Settings.CarOverrides.TryGetValue(_activeCarId, out var live);
            _lastPersistedCarOverrides.TryGetValue(_activeCarId, out var saved);

            bool liveEmpty  = live  == null || live.IsEmpty;
            bool savedEmpty = saved == null || saved.IsEmpty;
            if (liveEmpty && savedEmpty) return false;   // nothing on either side

            // Compare EFFECTIVE per-section values: a section absent from an
            // override means "follow the game default", so effective = the
            // override's section if present, else the active preset's section
            // (snap). This mirrors EffectEquals and is what lets a change-then-
            // revert clear the dirty state: a draft override whose values equal
            // the game default reads clean against a car with no saved override,
            // instead of sticking dirty forever just because EnsureSectionDraft
            // materialized an override. (The old CarOverrideEquals compared
            // live-vs-saved directly, so a default-valued draft stayed dirty,
            // and it ignored PitLimiter/Drs/Collision/RevLimiter entirely.)
            GameSettingsSnapshot snap = null;
            if (!string.IsNullOrEmpty(_activePresetName) && Settings.Presets != null)
                Settings.Presets.TryGetValue(_activePresetName, out snap);

            if (!Eq(live?.EnginePulse  ?? snap?.EnginePulse,  saved?.EnginePulse  ?? snap?.EnginePulse))  return true;
            if (!Eq(live?.RoadBumps    ?? snap?.RoadBumps,    saved?.RoadBumps    ?? snap?.RoadBumps))    return true;
            if (!Eq(live?.TractionLoss ?? snap?.TractionLoss, saved?.TractionLoss ?? snap?.TractionLoss)) return true;
            if (!Eq(live?.AxleSlip     ?? snap?.AxleSlip,     saved?.AxleSlip     ?? snap?.AxleSlip))     return true;
            if (!Eq(live?.KerbThump    ?? snap?.KerbThump,    saved?.KerbThump    ?? snap?.KerbThump))    return true;
            if (!Eq(live?.LockupJudder ?? snap?.LockupJudder, saved?.LockupJudder ?? snap?.LockupJudder)) return true;
            if (!Eq(live?.GearShift    ?? snap?.GearShift,    saved?.GearShift    ?? snap?.GearShift))    return true;
            if (!Eq(live?.AbsClick     ?? snap?.AbsClick,     saved?.AbsClick     ?? snap?.AbsClick))     return true;
            if (!Eq(live?.PitLimiter   ?? snap?.PitLimiter,   saved?.PitLimiter   ?? snap?.PitLimiter))   return true;
            if (!Eq(live?.Drs          ?? snap?.Drs,          saved?.Drs          ?? snap?.Drs))          return true;
            if (!Eq(live?.Collision    ?? snap?.Collision,    saved?.Collision    ?? snap?.Collision))    return true;
            if (!Eq(live?.AudioCapture ?? snap?.AudioCapture, saved?.AudioCapture ?? snap?.AudioCapture)) return true;
            if (!Eq(live?.RevLimiter   ?? snap?.RevLimiter ?? new RevLimiterSettings(),
                    saved?.RevLimiter  ?? snap?.RevLimiter ?? new RevLimiterSettings())) return true;
            if (!Eq(live?.ImplementThud ?? snap?.ImplementThud, saved?.ImplementThud ?? snap?.ImplementThud)) return true;
            return false;
        }

        /// <summary>Snapshot a section's current values into the per-car
        /// override (in-memory only; does NOT write to disk). If the
        /// section already has an override, keeps it as-is. After this call
        /// Settings.CarOverrides[activeCarId] reflects what would be saved
        /// to disk; the caller decides whether to persist (in-place save)
        /// or fork to a new user preset.</summary>
        public void SnapshotSectionToCarOverride(SectionKind kind)
        {
            if (string.IsNullOrEmpty(_activeCarId) || Settings == null) return;
            if (Settings.CarOverrides == null) Settings.CarOverrides = new Dictionary<string, CarOverride>();
            if (!Settings.CarOverrides.TryGetValue(_activeCarId, out var ovr) || ovr == null)
            {
                ovr = new CarOverride();
                Settings.CarOverrides[_activeCarId] = ovr;
            }
            switch (kind)
            {
                case SectionKind.Engine:   if (ovr.EnginePulse  == null) ovr.EnginePulse  = Clone(Settings.EnginePulse);    break;
                case SectionKind.Bumps:    if (ovr.RoadBumps    == null) ovr.RoadBumps    = Clone(Settings.RoadBumps);      break;
                case SectionKind.Traction: if (ovr.TractionLoss == null) ovr.TractionLoss = Clone(Settings.TractionLoss);   break;
                case SectionKind.AxleSlip:   if (ovr.AxleSlip     == null) ovr.AxleSlip     = Clone(Settings.AxleSlip);       break;
                case SectionKind.KerbThump:  if (ovr.KerbThump    == null) ovr.KerbThump    = Clone(Settings.KerbThump);      break;
                case SectionKind.LockupJudder: if (ovr.LockupJudder == null) ovr.LockupJudder = Clone(Settings.LockupJudder);  break;
                case SectionKind.Shift:    if (ovr.GearShift    == null) ovr.GearShift    = Clone(Settings.GearShift);      break;
                case SectionKind.Abs:        if (ovr.AbsClick     == null) ovr.AbsClick     = Clone(Settings.AbsClick);       break;
                case SectionKind.PitLimiter: if (ovr.PitLimiter   == null) ovr.PitLimiter   = Clone(Settings.PitLimiter);     break;
                case SectionKind.Drs:        if (ovr.Drs          == null) ovr.Drs          = Clone(Settings.Drs);            break;
                case SectionKind.Collision:  if (ovr.Collision    == null) ovr.Collision    = Clone(Settings.Collision);      break;
                case SectionKind.RevLimiter: if (ovr.RevLimiter   == null) ovr.RevLimiter   = Clone(Settings.RevLimiter);     break;
                case SectionKind.Audio:      if (ovr.AudioCapture == null) ovr.AudioCapture = CloneOrNull(Settings.AudioCapture); break;
                case SectionKind.Airborne:   if (ovr.Airborne     == null) ovr.Airborne     = Clone(Settings.Airborne);       break;
                default: return;  // Master / Ducking / SpikeReduction aren't per-car
            }
            ApplyActiveCarOverride();
        }

        /// <summary>"Update game defaults" save action when the section is
        /// car-overridden: lifts the override values up to the global
        /// section, then drops the override (so the new global takes
        /// effect for this car too). Caller should follow with
        /// SavePresetAs to commit the new global into the active preset.
        /// Prefer calling the two halves directly around the preset write
        /// (CopySectionToGlobals before, ReleaseSectionFromCarLayer after
        /// success) so a cancelled or failed save can't destroy the car
        /// preset's saved section (2026-07 save-matrix audit).</summary>
        public void PromoteSectionToGlobal(SectionKind kind)
        {
            CopySectionToGlobals(kind);
            ReleaseSectionFromCarLayer(kind);
        }

        /// <summary>First half of the game-side section save: copy the
        /// section's live (audible) values into the global section WITHOUT
        /// releasing the car layer's claim on it - no override mutation, no
        /// car-file write. On cancel or failure THIS car's override still
        /// masks the copied global; the global itself stays modified until
        /// the next preset apply (same as the old promote), which cars
        /// without their own override can hear.</summary>
        public void CopySectionToGlobals(SectionKind kind)
        {
            if (Settings == null || string.IsNullOrEmpty(_activeCarId)) return;
            if (Settings.CarOverrides == null
                || !Settings.CarOverrides.TryGetValue(_activeCarId, out var ovr)
                || ovr == null) return;
            switch (kind)
            {
                case SectionKind.Engine:   if (ovr.EnginePulse  != null) Settings.EnginePulse  = Clone(ovr.EnginePulse);    break;
                case SectionKind.Bumps:    if (ovr.RoadBumps    != null) Settings.RoadBumps    = Clone(ovr.RoadBumps);      break;
                case SectionKind.Traction: if (ovr.TractionLoss != null) Settings.TractionLoss = Clone(ovr.TractionLoss);   break;
                case SectionKind.AxleSlip:   if (ovr.AxleSlip     != null) Settings.AxleSlip     = Clone(ovr.AxleSlip);       break;
                case SectionKind.KerbThump:  if (ovr.KerbThump    != null) Settings.KerbThump    = Clone(ovr.KerbThump);      break;
                case SectionKind.LockupJudder: if (ovr.LockupJudder != null) Settings.LockupJudder = Clone(ovr.LockupJudder);  break;
                case SectionKind.Shift:    if (ovr.GearShift    != null) Settings.GearShift    = Clone(ovr.GearShift);      break;
                case SectionKind.Abs:        if (ovr.AbsClick     != null) Settings.AbsClick     = Clone(ovr.AbsClick);       break;
                case SectionKind.PitLimiter: if (ovr.PitLimiter   != null) Settings.PitLimiter   = Clone(ovr.PitLimiter);     break;
                case SectionKind.Drs:        if (ovr.Drs          != null) Settings.Drs          = Clone(ovr.Drs);            break;
                case SectionKind.Collision:  if (ovr.Collision    != null) Settings.Collision    = Clone(ovr.Collision);      break;
                case SectionKind.RevLimiter: if (ovr.RevLimiter   != null) Settings.RevLimiter   = Clone(ovr.RevLimiter);     break;
                case SectionKind.Audio:      if (ovr.AudioCapture != null) Settings.AudioCapture = CloneOrNull(ovr.AudioCapture); break;
                case SectionKind.Airborne:   if (ovr.Airborne     != null) Settings.Airborne     = Clone(ovr.Airborne);       break;
                default: break;
            }
        }

        /// <summary>Second half of the game-side section save, to be called
        /// only AFTER the game preset write is confirmed: drop the car
        /// layer's claim on the section so the just-saved global value is
        /// what plays from now on. The live section is cleared in memory
        /// and the SAVED car preset file is patched from the persisted
        /// baseline - never from the live override, which would silently
        /// commit sibling sections' unsaved drafts and break their Revert
        /// (2026-07 audit). When dropping the section would empty a USER
        /// preset's file, the release becomes a RE-PIN at the just-saved
        /// values instead: a named car preset is never deleted or stranded
        /// by a game-side save, and it must not keep the pre-save values
        /// either - the save is only reachable while the section is dirty,
        /// so a stale pin would silently revert the save on the next car
        /// change, light a phantom car-dirty star, and invite a car Save
        /// that persists the missing live entry as a file delete
        /// (adversarial review of the first cut).</summary>
        /// <returns>True when the car layer now matches the just-saved state on
        /// disk; false when a car-file write failed (the caller should surface it
        /// rather than report a clean save, so the user knows the car preset may
        /// revert on the next load). "Nothing to release" is a success.</returns>
        public bool ReleaseSectionFromCarLayer(SectionKind kind)
        {
            if (Settings == null || string.IsNullOrEmpty(_activeCarId)) return true;
            if (!SectionHasCarScope(kind)) return true;

            string boundName    = GetActiveCarPresetName(_activeCarId);
            bool   boundBuiltin = !string.IsNullOrEmpty(boundName)
                                  && IsCarPresetBuiltin(_activeCarId, boundName);
            if (!boundBuiltin
                && OverrideHasSection(GetActiveCarOverride(), kind)
                && _lastPersistedCarOverrides.TryGetValue(_activeCarId, out var saved0)
                && saved0 != null && OverrideHasSection(saved0, kind))
            {
                var wouldRemain = CloneCarOverride(saved0);
                ClearOverrideSection(wouldRemain, kind);
                if (wouldRemain.IsEmpty && !wouldRemain.HasCommunityTracking)
                {
                    // Keep-alive re-pin: live claim stays, file + baseline
                    // move to the just-saved values (in place, lineage
                    // preserved), so file == effective state everywhere.
                    bool repinned = SaveSectionToActiveCarOverride(kind);
                    if (repinned)
                        SimHub.Logging.Current.Info(
                            $"[TF4ALL] Car preset for '{_activeCarId}' kept alive: {kind} is its only section, re-pinned at the just-saved values.");
                    ApplyActiveCarOverride();
                    return repinned;
                }
            }

            bool fileOk = true;
            if (Settings.CarOverrides != null
                && Settings.CarOverrides.TryGetValue(_activeCarId, out var live)
                && live != null)
            {
                ClearOverrideSection(live, kind);
                if (live.IsEmpty && !live.HasCommunityTracking)
                    Settings.CarOverrides.Remove(_activeCarId);
            }
            if (_lastPersistedCarOverrides.TryGetValue(_activeCarId, out var saved)
                && saved != null && OverrideHasSection(saved, kind))
            {
                fileOk = RemoveSectionFromActiveCarOverrideFile(kind);
            }
            ApplyActiveCarOverride();
            return fileOk;
        }

        /// <summary>WYSIWYG for whole-preset saves: live effect edits made
        /// while a car is loaded sit in the car's in-memory draft override
        /// (EnsureSectionDraft), so SnapshotCurrentAsPreset's read of the
        /// GLOBAL sections would silently save pre-edit values and leave the
        /// edited sections dirty. Folds every PURE draft (a section present
        /// on the live override but absent from the persisted car baseline,
        /// i.e. never committed to the car preset) into its global and drops
        /// the draft - like PromoteSectionToGlobal, but WITHOUT touching the
        /// car preset file: drafts were never on disk, and persisting here
        /// would silently commit sibling drafts to the car file. Sections
        /// present in the SAVED car preset are intentional per-car tuning:
        /// they stay overridden and belong to the car Save button. No-op
        /// during offline CAR editing, where every draft is destined for the
        /// car preset instead.</summary>
        private void FoldDraftSectionsIntoGlobals()
        {
            if (IsOfflineEditingCar) return;
            if (Settings?.CarOverrides == null || string.IsNullOrEmpty(_activeCarId)) return;
            if (!Settings.CarOverrides.TryGetValue(_activeCarId, out var live) || live == null) return;
            _lastPersistedCarOverrides.TryGetValue(_activeCarId, out var saved);

            bool folded = false;
            foreach (SectionKind kind in Enum.GetValues(typeof(SectionKind)))
            {
                if (!SectionHasCarScope(kind)) continue;
                if (!OverrideHasSection(live, kind)) continue;
                if (saved != null && OverrideHasSection(saved, kind)) continue;   // saved car tuning, not a draft
                switch (kind)
                {
                    case SectionKind.Engine:     Settings.EnginePulse  = Clone(live.EnginePulse);        live.EnginePulse  = null; break;
                    case SectionKind.Bumps:      Settings.RoadBumps    = Clone(live.RoadBumps);          live.RoadBumps    = null; break;
                    case SectionKind.Traction:   Settings.TractionLoss = Clone(live.TractionLoss);       live.TractionLoss = null; break;
                    case SectionKind.AxleSlip:   Settings.AxleSlip     = Clone(live.AxleSlip);           live.AxleSlip     = null; break;
                    case SectionKind.KerbThump:  Settings.KerbThump    = Clone(live.KerbThump);          live.KerbThump    = null; break;
                    case SectionKind.LockupJudder: Settings.LockupJudder = Clone(live.LockupJudder);     live.LockupJudder = null; break;
                    case SectionKind.Shift:      Settings.GearShift    = Clone(live.GearShift);          live.GearShift    = null; break;
                    case SectionKind.Abs:        Settings.AbsClick     = Clone(live.AbsClick);           live.AbsClick     = null; break;
                    case SectionKind.PitLimiter: Settings.PitLimiter   = Clone(live.PitLimiter);         live.PitLimiter   = null; break;
                    case SectionKind.Drs:        Settings.Drs          = Clone(live.Drs);                live.Drs          = null; break;
                    case SectionKind.Collision:  Settings.Collision    = Clone(live.Collision);          live.Collision    = null; break;
                    case SectionKind.RevLimiter: Settings.RevLimiter   = Clone(live.RevLimiter);         live.RevLimiter   = null; break;
                    case SectionKind.Audio:      Settings.AudioCapture = CloneOrNull(live.AudioCapture); live.AudioCapture = null; break;
                    case SectionKind.Airborne:   Settings.Airborne     = Clone(live.Airborne);           live.Airborne     = null; break;
                    default: continue;
                }
                folded = true;
            }
            if (!folded) return;
            if (live.IsEmpty) Settings.CarOverrides.Remove(_activeCarId);
            // Effective values are unchanged (they moved from the draft to
            // the global); re-derive so the pipeline reads the new location.
            ApplyActiveCarOverride();
        }

        /// <summary>True if the named preset is a built-in / read-only one.
        /// Built-ins refuse delete and refuse in-place overwrite, the UI
        /// forks to a user-named preset instead.</summary>
        public bool IsBuiltinPreset(string presetName) => BuiltinPresets.IsBuiltin(presetName);

        /// <summary>One-time migration of legacy per-game presets (keyed by
        /// game name with no separate "preset library" concept) into the new
        /// model: each becomes a preset named after the game, and the game's
        /// default is bound to it. Idempotent, runs once when GamePresets is
        /// non-empty and the new fields are still empty.</summary>
        private void MigrateLegacyGamePresets()
        {
            if (Settings?.GamePresets == null || Settings.GamePresets.Count == 0) return;
            if (Settings.Presets == null) Settings.Presets = new Dictionary<string, GameSettingsSnapshot>();
            if (Settings.GameDefaults == null) Settings.GameDefaults = new Dictionary<string, string>();
            int moved = 0;
            foreach (var kv in Settings.GamePresets)
            {
                if (kv.Value == null) continue;
                if (!Settings.Presets.ContainsKey(kv.Key))
                    Settings.Presets[kv.Key] = kv.Value;
                if (!Settings.GameDefaults.ContainsKey(kv.Key))
                    Settings.GameDefaults[kv.Key] = kv.Key;
                moved++;
            }
            Settings.GamePresets.Clear();
            if (moved > 0)
            {
                PersistSettingsCore();
                SimHub.Logging.Current.Info($"[TF4ALL] Migrated {moved} legacy game-preset(s) to named library.");
            }
        }

        // Promote existing Settings.CarCylinderCache entries to seed
        // EngineVariants in Settings.CarFacts. The cache is the cylinder-only
        // ancestor of the CarFacts layer; on the first run after this build
        // ships, each cached entry becomes a single "Stock" variant inside
        // its bundle. Idempotent: gated by Settings.CarFactsMigratedV1 at
        // the call site, and per-key skipped if a bundle already exists
        // (so a partial migration mid-flight wouldn't clobber edits).
        //
        // Cache shape: Dictionary<gameName, Dictionary<carId, encodedInt>>.
        // Encoding (mirrors CarCylinderResolver): EvSentinel (-1) = electric,
        // otherwise bits 0-4 = cylinder count (1-16), bits 8-11 = EngineConfig.
        // One-time migration: walks every car preset on disk and renames
        // any whose name matches the ordinal "Car_NNN" pattern to the
        // baked human-readable name from BuiltinCarCylinders.TryGetDisplayName
        // (game-aware, so FH5 + FH6 ordinals get their own per-game name
        // tables, no cross-game aliasing). Result: "Car_2267" -> "1997
        // Mazda RX-7" for FH6, "Car_242" -> the matching FH5 entry, etc.
        // Idempotent; gated by Settings.CarPresetOrdinalNamesMigratedV1.
        // Game-aware resolved car name. Mirrors the cascade used for the
        // active car (CarFacts user-set CarName -> baked tables) but works
        // for ANY (game, carId) — no _activeCarId / community-consensus
        // dependency. Used at preset-creation sites so freshly-saved
        // presets pick up a human name from the start instead of relying
        // on the ordinal-rename catch-up. Returns null when no name is
        // known; callers fall back to the carId.
        internal string ResolveCarHumanName(string game, string carId)
        {
            if (string.IsNullOrEmpty(game) || string.IsNullOrEmpty(carId)) return null;
            string key = game + "/" + carId;
            if (Settings?.CarFacts != null
                && Settings.CarFacts.TryGetValue(key, out var bundle)
                && bundle != null
                && !string.IsNullOrWhiteSpace(bundle.CarName))
                return bundle.CarName.Trim();
            // The SIM's own official name, when the sim tells us. iRacing
            // publishes CarScreenName in its session info, so its cars should
            // never show blank and should never need the user to type a name
            // the game already knows. Below a stored fact on purpose: an
            // explicit user or community name is a deliberate correction and
            // outranks even the game.
            if (string.Equals(game, _activeGame, StringComparison.Ordinal)
                && string.Equals(carId, _activeCarId, StringComparison.Ordinal))
            {
                string simName = ActiveSimCarName;
                if (!string.IsNullOrWhiteSpace(simName)) return simName.Trim();
            }
            if (BuiltinCarCylinders.TryGetDisplayName(game, carId, out var catalogName)
                && !string.IsNullOrWhiteSpace(catalogName))
                return catalogName.Trim();
            // Shipped seed. Carries names for games the baked catalog does not
            // cover (iRacing today), and unlike the sim name it is available
            // with the game closed, which is when tuning usually happens.
            if (CarCylinderResolver.TryResolve(game, carId, out var seedSpec)
                && !string.IsNullOrWhiteSpace(seedSpec?.DisplayName))
                return seedSpec.DisplayName.Trim();
            // AC only, and last: the name AC's own car picker shows, read out
            // of the car's ui_car.json. The baked table carries no AC display
            // names (the folder ids were assumed descriptive, which holds for
            // "ks_toyota_ae86" and not at all for mod ids), so without this
            // every AC car falls through to the bare carId. Display-only, it
            // never becomes a CarFacts fact or a community submission; see
            // CarCylinderResolver.TryGetAcLocalDisplayName.
            if (string.Equals(game, "AssettoCorsa", StringComparison.OrdinalIgnoreCase)
                && CarCylinderResolver.TryGetAcLocalDisplayName(carId, out var acName)
                && !string.IsNullOrWhiteSpace(acName))
                return acName;
            return null;
        }

        private static readonly System.Text.RegularExpressions.Regex OrdinalCarPresetNameRegex =
            new System.Text.RegularExpressions.Regex(
                @"^Car_\d+$",
                System.Text.RegularExpressions.RegexOptions.IgnoreCase
                | System.Text.RegularExpressions.RegexOptions.Compiled);

        private void MigrateCarPresetOrdinalNames()
        {
            if (_carStore == null) return;
            Dictionary<string, Dictionary<string, CarPresetEntry>> loaded;
            try { loaded = _carStore.LoadAll(); }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Warn(
                    $"[TF4ALL] Ordinal-name migration: LoadAll failed: {ex.Message}");
                return;
            }
            if (loaded == null || loaded.Count == 0) return;

            int renamed = 0, collisions = 0, lookupMisses = 0, builtinsIncluded = 0;
            // Snapshot keys upfront because RenameCarPreset mutates the
            // underlying store and re-enumerating mid-loop is unsafe.
            var pairs = new List<(string carId, string presetName, string game)>();
            foreach (var carKv in loaded)
            {
                if (string.IsNullOrEmpty(carKv.Key) || carKv.Value == null) continue;
                foreach (var presetKv in carKv.Value)
                {
                    if (presetKv.Value == null) continue;
                    pairs.Add((carKv.Key, presetKv.Key, presetKv.Value.GameName));
                }
            }
            // DEV-mode-only: also walk built-in car presets. RenameCarPreset
            // refuses to touch built-ins unless DevMode is on, so this just
            // adds them to the pool of candidates; the per-row gate decides
            // whether the rename actually goes through. Builtin entries
            // are keyed as "carId/presetName" with the JSON body as value;
            // GameName is parsed from the JSON for the lookup.
            if (DevMode && BuiltinPresets.CarPresetJsons != null)
            {
                foreach (var biKv in BuiltinPresets.CarPresetJsons)
                {
                    if (string.IsNullOrEmpty(biKv.Key)) continue;
                    int slash = biKv.Key.IndexOf('/');
                    if (slash <= 0 || slash >= biKv.Key.Length - 1) continue;
                    string biCar    = biKv.Key.Substring(0, slash);
                    string biPreset = biKv.Key.Substring(slash + 1);
                    if (!OrdinalCarPresetNameRegex.IsMatch(biPreset)) continue;
                    string biGame = null;
                    try
                    {
                        var parsed = Newtonsoft.Json.Linq.JObject.Parse(biKv.Value);
                        biGame = (string)parsed["GameName"];
                    }
                    catch { /* skip malformed built-in */ continue; }
                    if (string.IsNullOrEmpty(biGame)) continue;
                    pairs.Add((biCar, biPreset, biGame));
                    builtinsIncluded++;
                }
            }

            foreach (var (carId, oldName, game) in pairs)
            {
                if (!OrdinalCarPresetNameRegex.IsMatch(oldName)) continue;
                if (string.IsNullOrEmpty(game)) continue;
                // Name lookup: CarFacts user-set name first, then baked
                // per-game tables. Shared with the at-creation pre-fill
                // sites so an ordinal Car_NNN that's auto-named at save
                // time gets the same answer as the rename pass.
                string humanName = ResolveCarHumanName(game, carId);
                if (string.IsNullOrWhiteSpace(humanName))
                {
                    lookupMisses++;
                    continue;
                }
                // Don't pretend to rename to the same name.
                if (string.Equals(oldName, humanName, StringComparison.Ordinal)) continue;
                // Skip on name collision: another preset already owns the
                // target name for this car (could be a built-in or a user
                // preset the migration already renamed). RenameCarPreset
                // would also refuse but the explicit log is more useful.
                if (_carStore.Exists(carId, ToDiskName(humanName))
                    || BuiltinPresets.CarPresetJsons.ContainsKey(carId + "/" + ToDiskName(humanName)))
                {
                    collisions++;
                    continue;
                }
                try
                {
                    if (RenameCarPreset(carId, oldName, humanName))
                    {
                        renamed++;
                        // Mirror the rename into CarDefaults so a default that
                        // pointed at the old name follows it (RenameCarPreset
                        // already does this internally but we're defensive).
                    }
                }
                catch (Exception ex)
                {
                    SimHub.Logging.Current.Warn(
                        $"[TF4ALL] Ordinal-name migration: rename '{carId}/{oldName}' -> "
                        + $"'{humanName}' failed: {ex.Message}");
                }
            }

            if (renamed > 0 || collisions > 0 || lookupMisses > 0 || builtinsIncluded > 0)
                SimHub.Logging.Current.Info(
                    $"[TF4ALL] Ordinal car-preset name migration: renamed={renamed}, "
                    + $"collisions={collisions}, lookup_misses={lookupMisses}"
                    + (DevMode ? $", builtins_walked={builtinsIncluded}" : ""));
        }

        private void MigrateCarCylinderCacheToCarFacts()
        {
            const int EvSentinel  = -1;
            const int CylBits     = 0x1F;
            const int ConfigShift = 8;
            const int ConfigBits  = 0xF00;

            if (Settings?.CarCylinderCache == null) return;
            if (Settings.CarFacts == null)
                Settings.CarFacts = new Dictionary<string, CarFactsBundle>();

            int seeded = 0;
            foreach (var gameKv in Settings.CarCylinderCache)
            {
                string game = gameKv.Key;
                if (string.IsNullOrEmpty(game) || gameKv.Value == null) continue;
                foreach (var carKv in gameKv.Value)
                {
                    string carId = carKv.Key;
                    if (string.IsNullOrEmpty(carId)) continue;
                    int encoded = carKv.Value;

                    // Skip EV entries: the legacy cache stored electric as
                    // a sentinel and the EnginePulse path detects electric
                    // separately via the resolver. Variants only carry
                    // EngineConfig values that the FiringPatternDb knows,
                    // so seeding "electric" as a variant would mislead.
                    if (encoded == EvSentinel) continue;

                    int cyl = encoded & CylBits;
                    int cfgIdx = (encoded & ConfigBits) >> ConfigShift;
                    if (cfgIdx < 0 || cfgIdx > (int)EngineConfig.Custom) cfgIdx = 0;
                    EngineConfig cfg = (EngineConfig)cfgIdx;
                    if (cyl < 1 || cyl > 16) continue;

                    string key = game + "/" + carId;
                    if (Settings.CarFacts.TryGetValue(key, out var existing) && existing != null
                        && existing.EngineVariants != null && existing.EngineVariants.Count > 0)
                        continue;

                    var variant = new EngineVariant
                    {
                        Id            = Guid.NewGuid().ToString("N"),
                        Label         = "Stock",
                        Cylinders     = cyl,
                        EngineConfig  = cfg,
                        RedlineRpm    = null,
                        Source        = CarFactSource.Scanner,
                        Confirmations = 0,
                    };
                    var bundle = existing ?? new CarFactsBundle();
                    if (bundle.EngineVariants == null)
                        bundle.EngineVariants = new List<EngineVariant>();
                    bundle.EngineVariants.Add(variant);
                    Settings.CarFacts[key] = bundle;
                    seeded++;
                }
            }

            if (seeded > 0)
                SimHub.Logging.Current.Info(
                    $"[TF4ALL] Seeded {seeded} car-fact variant(s) from the cylinder cache.");
        }

        // CarFacts lookup at apply time. Resolution order:
        //   1. Authoritative stored variant for (game,carId) — User, Community,
        //      or Scanner with Confirmations > 0 — wins outright (user-
        //      confirmed local truth or community-vetted data).
        //   2. Else if BuiltinCarCylinders has an entry, synthesize a virtual
        //      "Baked" variant (Source=Baked, Id="baked:{game}/{carId}"). The
        //      bake is the curated baseline shipped in the DLL (~890 AC cars
        //      + ~840 FH5 cars); we surface it through CarFacts so the apply
        //      cascade, the future Stage 2 variant picker, and submission
        //      flows all see one unified source of car facts.
        //   3. Else if an unconfirmed Scanner-seed stored variant exists (the
        //      legacy CarCylinderCache migration cohort), use it as last
        //      resort.
        //   4. Otherwise no variant; caller falls through to the heuristic
        //      tokenizer / telemetry paths.
        // (Telemetry-based "unambiguous match" disambiguation is Stage 3.)
        private bool TryResolveActiveVariant(string game, string carId, out EngineVariant variant)
            => TryResolveVariantCore(game, carId, includeCommunity: true, out variant);

        // Shared cascade body for TryResolveActiveVariant (community rung
        // included) and TryResolveNonCommunityVariant (community rung
        // skipped). ONE copy of the stored-pick / bake-synthesis /
        // last-resort ladder so the two resolvers can never drift.
        private bool TryResolveVariantCore(string game, string carId,
            bool includeCommunity, out EngineVariant variant)
        {
            variant = null;
            if (string.IsNullOrEmpty(game) || string.IsNullOrEmpty(carId)) return false;

            // Community consensus is the top of the cascade when present for
            // the active car. We synthesize a transient EngineVariant from
            // the in-memory consensus (set by NotifyCommunityConsensus) so
            // the rest of the apply path treats it like any other variant.
            // Not persisted - re-fetched every session.
            if (includeCommunity && TrySynthesizeCommunityVariant(game, carId, out var commVar))
            {
                variant = commVar;
                return true;
            }

            EngineVariant storedPick = PickStoredVariant(game, carId);
            bool storedIsAuthoritative = storedPick != null
                && !(storedPick.Source == CarFactSource.Scanner && storedPick.Confirmations == 0);
            if (storedIsAuthoritative)
            {
                variant = storedPick;
                return true;
            }

            // Bake-class hit: defer to CarCylinderResolver which applies AC
            // swap-override + DetectEngineConfig refinements on top of the
            // raw bake values. Gating on BuiltinCarCylinders.TryGet first
            // means we only enter this branch for cars the bake knows about
            // (resolver heuristic-tokenizer hits are NOT surfaced here as
            // Baked: they stay in the legacy fallback path with Source
            // labels like "cylword" / "tag" / "codename").
            // EV special case: bake's IsElectric flag has no first-class
            // representation in EngineVariant yet, and a stale ICE Scanner
            // seed shouldn't shadow a known-electric bake entry. Return
            // false so the caller drops into the legacy resolver branch,
            // which handles EngineLayout.Electric correctly.
            if (BuiltinCarCylinders.TryGet(game, carId, out var rawBake))
            {
                if (rawBake.IsElectric) return false;
                if (CarCylinderResolver.TryResolve(game, carId, out var refined)
                    && refined != null
                    && !refined.IsElectric
                    && refined.Cylinders >= 1 && refined.Cylinders <= 16)
                {
                    // Preserve the AC swap-override attribution when the
                    // refinement pass changed the layout: lets the diagnostic
                    // banner read "(heuristic: swap-override)" instead of
                    // "(from built-in car list)" so a wrong swap-override
                    // is distinguishable from a wrong base bake entry.
                    var resolvedSource = string.Equals(refined.Source,
                        "swap-override", StringComparison.OrdinalIgnoreCase)
                        ? CarFactSource.SwapOverride
                        : CarFactSource.Baked;
                    variant = new EngineVariant
                    {
                        Id            = "baked:" + game + "/" + carId,
                        Label         = "Stock",
                        Cylinders     = refined.Cylinders,
                        EngineConfig  = refined.EngineConfig,
                        RedlineRpm    = null,
                        Source        = resolvedSource,
                        Confirmations = 0,
                    };
                    return true;
                }
            }

            if (storedPick != null)
            {
                variant = storedPick;
                return true;
            }

            return false;
        }

        // Picks one variant from the stored CarFacts bundle (if any), or null
        // when no stored data exists. Selection rules within the bundle:
        //   - Single variant → use it.
        //   - CarFactsSelection set (explicit picker choice) → use that
        //     variant by Id.
        //   - Else rank by SourcePriority then by Confirmations (higher
        //     wins); first-seen breaks ties at the lowest level.
        // Source priority codifies the docs' "User wins over Community wins
        // over Scanner-confirmed wins over Scanner-unconfirmed" rule, so a
        // User correction always beats a higher-Confirmations Community or
        // migrated Scanner variant. Without this, a fresh User correction
        // (Confirmations=0) would lose to anything pre-existing - which
        // silently no-ops the entire Correct... flow on any car that already
        // had a bundle.
        // THE signature-compatibility rule, single-sourced (was hand-repeated
        // in PickStoredVariant, EnsureVariantForLiveSignatureCore_Locked, and
        // FindActiveStoredVariant). A variant matches live telemetry when
        // every field present on BOTH sides agrees: Cylinders exactly, MaxRpm
        // and RedlineRpm by band. A field missing on the variant is an
        // under-specified legacy row and matches anything; a field missing on
        // telemetry can't discriminate, so it's a free pass.
        private static bool VariantMatchesSignature(EngineVariant v,
            int? telCyl, int telMaxBand, int telRedBand)
        {
            if (v == null) return false;
            if (v.Cylinders >= 1 && telCyl.HasValue && v.Cylinders != telCyl.Value) return false;
            if (v.MaxRpm.HasValue && telMaxBand > 0 && BandMaxRpm(v.MaxRpm.Value) != telMaxBand) return false;
            if (v.RedlineRpm.HasValue && telRedBand > 0 && BandRpm(v.RedlineRpm.Value) != telRedBand) return false;
            return true;
        }

        private EngineVariant PickStoredVariant(string game, string carId)
        {
            if (Settings?.CarFacts == null) return null;
            string key = game + "/" + carId;

            // Snapshot under _carFactsLock: the variant writers add CarFacts keys
            // and append to EngineVariants under this lock on other threads (car
            // load auto-create, community fetch), while this resolver runs on the
            // source, DataUpdate, and UI threads. An unlocked enumeration here can
            // throw or read a corrupt dictionary mid-rehash. Everything past the
            // lock works on the `pool` snapshot, so the hold time stays tiny.
            var pool = new List<EngineVariant>();
            string chosenId = null;
            lock (_carFactsLock)
            {
                if (!Settings.CarFacts.TryGetValue(key, out var bundle) || bundle == null) return null;
                var variants = bundle.EngineVariants;
                if (variants == null || variants.Count == 0) return null;

                // User-source variants are no longer part of the auto-detect
                // cascade. A Share submission goes to the community DB; the
                // local CarFact is no longer written. Existing User-source
                // variants from prior versions are ignored here so they don't
                // silently override the new Community / Baked / Scanner order
                // ("auto means auto"). Per-car explicit picks live in the
                // dropdown / car preset, not in CarFacts.
                // Use a fresh filtered list so any single-variant fast-path
                // below sees the right element.
                for (int i = 0; i < variants.Count; i++)
                {
                    var cand = variants[i];
                    if (cand != null && cand.Source != CarFactSource.User)
                        pool.Add(cand);
                }
                if (Settings.CarFactsSelection != null)
                    Settings.CarFactsSelection.TryGetValue(key, out chosenId);
            }
            if (pool.Count == 0) return null;
            if (pool.Count == 1) return pool[0];

            if (!string.IsNullOrEmpty(chosenId))
            {
                for (int i = 0; i < pool.Count; i++)
                    if (pool[i].Id == chosenId)
                        return pool[i];
            }

            // Signature match: prefer the variant whose (Cylinders,
            // MaxRpm, RedlineRpm) matches live telemetry before falling
            // through to raw priority. This is what lets a Forza in-game
            // swap from stock to a higher-rev engine automatically apply
            // the right variant. MaxRpm is the universally-available
            // discriminator (Forza UDP and SimHub fallback both carry
            // it); RedlineRpm adds finer discrimination on games that
            // expose it (AC, Codies titles). A field missing on the
            // variant matches anything (under-specified row from legacy
            // data); a field missing on telemetry can't discriminate so
            // it's a free pass. Cyl falls back to CatalogCyl for games
            // that don't carry NumCylinders in telemetry (SimHub
            // fallback). Priority + Confirmations rank within the
            // matching subset.
            int? telCyl = ActiveCarEffectiveCyl();
            int telMaxBand = BandMaxRpm(EnginePulse?.ObservedMaxRpm ?? 0);
            int telRedBand = BandRpm(EnginePulse?.ObservedRedlineRpm ?? 0);
            if (telCyl.HasValue || telMaxBand > 0 || telRedBand > 0)
            {
                EngineVariant sigMatch = null;
                int sigPriority = int.MinValue;
                int sigConf = int.MinValue;
                for (int i = 0; i < pool.Count; i++)
                {
                    var cand = pool[i];
                    if (!VariantMatchesSignature(cand, telCyl, telMaxBand, telRedBand)) continue;
                    int prio = SourcePriority(cand.Source);
                    if (prio > sigPriority
                        || (prio == sigPriority && cand.Confirmations > sigConf))
                    {
                        sigMatch = cand;
                        sigPriority = prio;
                        sigConf = cand.Confirmations;
                    }
                }
                if (sigMatch != null) return sigMatch;
            }

            EngineVariant best = null;
            int bestPriority = int.MinValue;
            int bestConf = int.MinValue;
            for (int i = 0; i < pool.Count; i++)
            {
                var cand = pool[i];
                int prio = SourcePriority(cand.Source);
                if (prio > bestPriority
                    || (prio == bestPriority && cand.Confirmations > bestConf))
                {
                    best = cand;
                    bestPriority = prio;
                    bestConf = cand.Confirmations;
                }
            }
            return best;
        }

        // Synthesizes a transient CarFactSource.Community variant from the
        // in-memory consensus stash if it matches (game, carId). Used by
        // TryResolveActiveVariant to seat Community at the top of the
        // cascade WITHOUT persisting anything to Settings.CarFacts (which
        // would conflate ephemeral consensus with durable user data).
        private bool TrySynthesizeCommunityVariant(
            string game, string carId, out EngineVariant variant)
        {
            variant = null;
            var c = _activeCarCommunityConsensus;
            if (c == null) return false;
            // Cache key is variant-aware so an in-session swap (Forza)
            // doesn't keep applying the stock variant's consensus after
            // telemetry has moved to a new signature. When the key
            // mismatches, the resolver falls through to non-community
            // sources and SettingsControl's per-tick refresh will
            // re-fetch with the new signature on the next pass.
            string currentSig = ComputeActiveCarVariantSignature(game, carId);
            if (_activeCarCommunityKey != game + "/" + carId + "/" + (currentSig ?? "")) return false;
            if (string.IsNullOrEmpty(c.Layout)) return false;
            // Map the stored enum-name string back to (cyl, EngineConfig)
            // for the legacy apply path. The schema whitelists only valid
            // EngineLayout enum names, so the parse should succeed.
            if (!Enum.TryParse<Effects.EngineLayout>(c.Layout, true, out var layout))
                return false;
            int cyl; Effects.EngineConfig cfg;
            if (layout == Effects.EngineLayout.Custom)
            {
                // CUSTOM rides a community-supplied def in c.Custom.
                // Synthesize a variant with EngineConfig.Custom + cyl=0
                // sentinel; the apply path detects this and routes
                // synthesis through the community custom def directly
                // (CustomPattern + ActiveCustomIsElectric set by the
                // resolver instead of by ApplyEnginePulseSettings).
                if (c.Custom == null || string.IsNullOrEmpty(c.Custom.Name))
                    return false;
                cyl = 0;
                cfg = Effects.EngineConfig.Custom;
            }
            else if (!Effects.FiringPatternDb.TryLayoutToCylAndConfig(layout, out cyl, out cfg))
                return false;
            // Redline rides on the same synthesized variant when the
            // community has a redline consensus matching the current
            // variant signature. Without this, a community-resolved layout
            // would still let a stale local CarFacts redline win or fall
            // through to the heuristic - and a redline correction
            // submission wouldn't actually drive the rev-limiter buzz.
            // Key format must match NotifyCommunityRedlineConsensus's
            // writer: "game/carId/<sig>". Earlier versions read this
            // without the sig suffix, which never matched, so the
            // synthesized variant's RedlineRpm was always null.
            int? communityRedline =
                CommunityRedlineConsensusReady(game + "/" + carId + "/" + (currentSig ?? ""))
                    ? (int?)_activeCarCommunityRedlineConsensus.Rpm : null;

            variant = new EngineVariant
            {
                Id            = "community:" + game + "/" + carId,
                Label         = "Community",
                Cylinders     = cyl,
                EngineConfig  = cfg,
                RedlineRpm    = communityRedline,
                Source        = CarFactSource.Community,
                Confirmations = c.SupportingSubmissions,
            };
            return true;
        }

        // Called by SettingsControl after a per-car community fetch returns
        // (success or null). Stores the consensus in memory and re-runs the
        // CarFacts cascade so the engine-pulse panel updates immediately.
        // Pass null consensus when the fetch returned no data; the resolver
        // then falls through to Baked / Scanner / Telemetry.
        internal void NotifyCommunityConsensus(
            string game, string carId, string variantSignature,
            EngineLayoutConsensus consensus)
        {
            if (string.IsNullOrEmpty(game) || string.IsNullOrEmpty(carId)) return;
            // Only relevant when the fetch matches the still-active car;
            // a stale fetch from a previous car must not overwrite the
            // cache. The signature rides into the cache key too so the
            // resolver only honors this consensus while telemetry is
            // still on the variant the fetch targeted.
            if (game != _activeGame || carId != _activeCarId) return;
            if (Settings?.UseCommunityCarFacts != true) return;   // car facts off -> don't apply community data
            _activeCarCommunityKey = game + "/" + carId + "/" + (variantSignature ?? "");
            _activeCarCommunityConsensus = consensus;
            ResolveAndApplyCarFactsForActiveCar(carId, logResolution: false);
            ApplyActiveCarOverride();
        }

        /// <summary>Sibling of <see cref="NotifyCommunityConsensus"/> for the
        /// car_name fact. Pushes a community-name consensus result into the
        /// in-memory cache and re-runs the resolver so the header /
        /// presets show the canonical name. Pass null to drop the cache
        /// (e.g. when the per-car fetch returned no row).</summary>
        internal void NotifyCarNameConsensus(
            string game, string carId, CarNameConsensus consensus)
        {
            if (string.IsNullOrEmpty(game) || string.IsNullOrEmpty(carId)) return;
            if (game != _activeGame || carId != _activeCarId) return;
            if (Settings?.UseCommunityCarFacts != true) return;   // car facts off -> don't apply community data
            _activeCarCommunityNameKey = game + "/" + carId;
            _activeCarCommunityNameConsensus = consensus;
            ResolveAndApplyCarFactsForActiveCar(carId, logResolution: false);
            ApplyActiveCarOverride();
        }

        /// <summary>Synchronous fetch of the community CarName consensus for
        /// (game, carId). Public passthrough so SettingsControl can hit
        /// this without exposing CommunityClient. Mirrors <see
        /// cref="FetchEngineLayoutConsensus"/>.</summary>
        // Language tag carried in car_name's variant_signature so each language
        // forms its own consensus (an English plurality can't bury a correct
        // name in another language). Derived from the OS UI language for now;
        // when the plugin UI itself is localized this can switch to the chosen
        // UI language. Two-letter ISO so en-US / en-GB share one "en" bucket.
        internal static string CommunityNameLocaleSig()
        {
            string lang = null;
            try { lang = System.Globalization.CultureInfo.CurrentUICulture?.TwoLetterISOLanguageName; }
            catch { /* fall through to the default below */ }
            if (string.IsNullOrEmpty(lang) || lang == "iv") lang = "en";
            return "lang=" + lang.ToLowerInvariant();
        }

        internal CarNameConsensus FetchCarNameConsensus(string game, string carId)
        {
            return _community?.FetchCarNameConsensus(game, carId, CommunityNameLocaleSig());
        }

        /// <summary>Variant-aware fetch of the community redline consensus
        /// for (game, carId). Plumbed through the current EnginePulse
        /// signature so the row matching THIS variant is what comes
        /// back.</summary>
        internal RedlineConsensus FetchRedlineConsensus(string game, string carId)
        {
            return _community?.FetchRedlineConsensus(game, carId,
                ComputeActiveCarVariantSignature(game, carId), CommunityRedlineMinSupport);
        }

        /// <summary>Fetch the active message-of-the-day feed. Anon-read, so it
        /// only needs CommunityEnabled + a trusted backend URL, not sign-in.
        /// Returns null on failure (the strip keeps its offline cache).</summary>
        internal async System.Threading.Tasks.Task<System.Collections.Generic.List<MotdItem>> FetchMotdAsync()
        {
            return _community != null ? await _community.FetchMotdAsync() : null;
        }

        /// <summary>Persist the MOTD level radio choice.</summary>
        internal void SetMotdLevel(MotdLevel level)
        {
            if (Settings == null) return;
            Settings.MotdLevel = level;
            PersistSettingsCore();
        }

        /// <summary>Persist MOTD client state (cache refresh + dismiss bookkeeping).</summary>
        internal void SaveMotdState()
        {
            if (Settings == null) return;
            PersistSettingsCore();
        }

        /// <summary>Dev: drop the entire community preset browse cache.</summary>
        internal void ClearBrowseCache() => _browseCache?.Clear();

        /// <summary>Mark every re-fetchable network cache stale (null their fetch
        /// timestamps) WITHOUT wiping them, so the next access refetches fresh while
        /// the offline copies still apply. Covers the MOTD feed, the community
        /// car-fact cache, and the preset browse cache.</summary>
        internal void MarkAllNetworkCachesStale()
        {
            if (Settings != null)
            {
                if (Settings.MotdCache != null) Settings.MotdCache.FetchedAtUtc = null;
                var fc = Settings.CommunityFactCache;
                if (fc != null)
                    foreach (var e in fc.Values)
                        if (e != null) e.FetchedAtUtc = null;
                PersistSettingsCore();
            }
            _browseCache?.MarkAllStale();
        }

        /// <summary>Sibling of <see cref="NotifyCommunityConsensus"/> for the
        /// redline fact. Cache + re-resolve so RevLimiter.CarFactsRedline
        /// picks up the new value on the same tick. Pass null to drop the
        /// cache (e.g. when the fetch returned no row).</summary>
        internal void NotifyRedlineConsensus(
            string game, string carId, string variantSignature,
            RedlineConsensus consensus)
        {
            if (string.IsNullOrEmpty(game) || string.IsNullOrEmpty(carId)) return;
            if (game != _activeGame || carId != _activeCarId) return;
            if (Settings?.UseCommunityCarFacts != true) return;   // car facts off -> don't apply community data
            _activeCarCommunityRedlineKey = game + "/" + carId + "/" + (variantSignature ?? "");
            _activeCarCommunityRedlineConsensus = consensus;
            ResolveAndApplyCarFactsForActiveCar(carId, logResolution: false);
            ApplyActiveCarOverride();
        }

        // ===================================================================
        // Community-fact cache (offline + TTL). See
        // TrueforceSettings.CommunityFactCache / UseCommunityCarFacts. The cache
        // is the local-first source: replayed on car change so community car
        // facts apply instantly and offline, and refreshed over the network only
        // when stale (CommunityCacheTtl) or on a manual refresh.
        // ===================================================================

        private static string CommunityCacheKey(string game, string carId, string sig)
            => (game ?? "") + "/" + (carId ?? "") + "/" + (sig ?? "");

        /// <summary>True when a cached entry exists for (game, carId, sig) and was
        /// fetched within the TTL (so no background refresh is due on car open).
        /// A malformed / missing timestamp counts as stale.</summary>
        internal bool IsCommunityCacheFresh(string game, string carId, string sig)
        {
            var e = GetCommunityCacheEntry(game, carId, sig);
            if (e == null || string.IsNullOrEmpty(e.FetchedAtUtc)) return false;
            if (!DateTime.TryParse(e.FetchedAtUtc,
                    System.Globalization.CultureInfo.InvariantCulture,
                    System.Globalization.DateTimeStyles.RoundtripKind, out var when))
                return false;
            // A partial fetch (some fact type came back empty, which may mean
            // "the community has none" or may mean that one call failed) ages
            // out in hours instead of a week, so a failure cannot masquerade as
            // fact until the TTL expires.
            var ttl = e.Partial
                ? TrueforceSettings.CommunityCachePartialTtl
                : TrueforceSettings.CommunityCacheTtl;
            return (DateTime.UtcNow - when.ToUniversalTime()) < ttl;
        }

        private CommunityFactCacheEntry GetCommunityCacheEntry(string game, string carId, string sig)
        {
            if (Settings?.CommunityFactCache == null) return null;
            // Locked: WriteCommunityFactCache inserts/rehashes from the fetch
            // callback thread while this read can run on the data/UI threads.
            lock (_carFactsLock)
            {
                return Settings.CommunityFactCache.TryGetValue(CommunityCacheKey(game, carId, sig), out var e) ? e : null;
            }
        }

        /// <summary>Persist the latest community fetch for (game, carId, sig) so it
        /// applies offline and refreshes only when stale. Any consensus may be
        /// null (no data for that fact type). Infrequent (TTL-gated), so a direct
        /// save is fine.</summary>
        internal void WriteCommunityFactCache(string game, string carId, string sig,
            CarNameConsensus name, EngineLayoutConsensus layout, RedlineConsensus redline)
        {
            if (Settings == null || string.IsNullOrEmpty(game) || string.IsNullOrEmpty(carId)) return;
            // Structural mutations (create/remove/insert/prune) hold _carFactsLock
            // so a concurrent settings serialize on another thread can't enumerate
            // the dictionary mid-change.
            lock (_carFactsLock)
            {
                if (Settings.CommunityFactCache == null)
                    Settings.CommunityFactCache = new Dictionary<string, CommunityFactCacheEntry>();
                // Don't store a fully-empty entry (it would just suppress refresh of a
                // car the community has nothing for); only cache when something landed.
                if (name == null && layout == null && redline == null)
                {
                    Settings.CommunityFactCache.Remove(CommunityCacheKey(game, carId, sig));
                }
                else
                {
                    Settings.CommunityFactCache[CommunityCacheKey(game, carId, sig)] = new CommunityFactCacheEntry
                    {
                        FetchedAtUtc = DateTime.UtcNow.ToString("o", System.Globalization.CultureInfo.InvariantCulture),
                        Name = name, Layout = layout, Redline = redline,
                        // Anything missing keeps this entry on the short TTL:
                        // the fetch primitives return null both for "no
                        // consensus" and for a failed call, so a partial result
                        // must not be trusted for a full week.
                        Partial = name == null || layout == null || redline == null,
                    };
                    PruneCommunityFactCache();
                }
            }
            try { PersistSettingsCore(); } catch { }
        }

        // Bound the cache so it can't grow without limit over a long-lived install
        // (the banded variant signature mints a key per car per tune band). Evict
        // the oldest entries by FetchedAtUtc when over the cap. Entries are tiny
        // (a few small consensus snapshots) and a dedicated multi-game driver can
        // legitimately touch a lot of cars, so the cap is generous; eviction is
        // only a backstop against pathological growth. Cheap re-fetch on next
        // visit, so eviction is harmless.
        private const int CommunityFactCacheMax = 2000;
        private void PruneCommunityFactCache()
        {
            var cache = Settings?.CommunityFactCache;
            if (cache == null || cache.Count <= CommunityFactCacheMax) return;
            var oldestFirst = new List<KeyValuePair<string, CommunityFactCacheEntry>>(cache);
            oldestFirst.Sort((a, b) => string.CompareOrdinal(
                a.Value?.FetchedAtUtc ?? "", b.Value?.FetchedAtUtc ?? ""));   // ISO-8601 sorts chronologically
            int toRemove = cache.Count - CommunityFactCacheMax;
            for (int i = 0; i < toRemove && i < oldestFirst.Count; i++)
                cache.Remove(oldestFirst[i].Key);
        }

        /// <summary>Apply a cached community fetch for the active car (game, carId,
        /// sig) into the in-memory consensus, exactly as a live fetch would. Lets
        /// community car facts apply instantly and offline. No-op when the user has
        /// turned car facts off, or when no entry exists. Returns the replayed
        /// cache entry, or null when car facts are off or no entry exists.</summary>
        internal CommunityFactCacheEntry ReplayCommunityCache(string game, string carId, string sig)
        {
            if (Settings?.UseCommunityCarFacts != true) return null;
            var e = GetCommunityCacheEntry(game, carId, sig);
            if (e == null) return null;
            // Push the cached snapshots through the same Notify path a fetch uses.
            NotifyCarNameConsensus(game, carId, e.Name);
            NotifyCommunityConsensus(game, carId, sig, e.Layout);
            NotifyRedlineConsensus(game, carId, sig, e.Redline);
            return e;
        }

        // ===================================================================
        // Headless community-facts refresh. Until 2026-07 the panel's meter
        // timer (MaybeRefreshEngineCommunityContext) was the ONLY driver of
        // the community fetch AND the offline-cache replay, so with SimHub on
        // any other view a car change never applied community facts: the
        // car-change handler clears the in-memory consensus and nothing
        // refilled it, leaving the rev limiter on the 0.85*MaxRpm estimate
        // until the panel opened (found via the remote dash, which makes
        // panel-closed sessions normal). This mirrors the panel's block:
        // local-first cache replay, then a TTL-gated background fetch ->
        // cache write -> Notify* apply. Runs on the telemetry thread; the
        // fetch itself is offloaded (sync primitives, 10 s timeout). The
        // panel keeps its own copy for the community-context UI row; each
        // side's fetched-key dedupe bounds the overlap to at most one
        // redundant fetch per car, and the Notify gates make a late apply
        // for a departed car a no-op.
        // ===================================================================
        private string _headlessCommunityFetchedKey;
        private volatile bool _headlessCommunityFetchInFlight;

        internal void MaybeRefreshCommunityFactsHeadless()
        {
            string game = _activeGame, carId = _activeCarId;
            if (string.IsNullOrEmpty(game) || string.IsNullOrEmpty(carId)) return;
            if (Settings?.UseCommunityCarFacts != true) return;

            string sig = ComputeActiveCarVariantSignatureForActive() ?? "";
            string key = game + "/" + carId + "/" + sig;
            if (_headlessCommunityFetchedKey == key) return;

            // LOCAL-FIRST: cached facts apply instantly and offline. Runs on
            // every key change, including while a fetch for an older key is
            // still in flight.
            ReplayCommunityCache(game, carId, sig);

            // Network refresh only when the master is on and the cache is
            // stale. Sign-in is NOT required (anon-readable consensus).
            if (Settings?.CommunityEnabled != true || IsCommunityCacheFresh(game, carId, sig))
            {
                _headlessCommunityFetchedKey = key;   // handled without a fetch
                return;
            }
            // A fetch for an OLDER key is still in flight. Typical on car
            // change: the signature fills in from the first telemetry frames
            // well inside the fetch's lifetime, so the variant detector's
            // call lands here. Deliberately do NOT record this key: the
            // in-flight task's completion re-runs this method, and the
            // current key then gets its own replay + fetch pass. Recording
            // it here was the original bug - the new key read as handled,
            // the old fetch's results were dropped as stale, and community
            // facts never applied until the settings panel opened.
            if (_headlessCommunityFetchInFlight) return;

            _headlessCommunityFetchedKey = key;
            _headlessCommunityFetchInFlight = true;

            System.Threading.Tasks.Task.Run(() =>
            {
                EngineLayoutConsensus layoutResult  = null;
                CarNameConsensus      nameResult    = null;
                RedlineConsensus      redlineResult = null;
                try { layoutResult  = FetchEngineLayoutConsensus(game, carId); } catch { }
                try { nameResult    = FetchCarNameConsensus(game, carId); } catch { }
                try { redlineResult = FetchRedlineConsensus(game, carId); } catch { }
                _headlessCommunityFetchInFlight = false;
                try
                {
                    // Apply only when the key is still current (the resolver
                    // gates consensus on the LIVE signature, so stale-key
                    // results could never apply anyway) and something came
                    // back. All-null is almost always a network failure and
                    // the primitives can't tell that from "no data": never
                    // overwrite a good cache or clear applied values on it.
                    if (_headlessCommunityFetchedKey == key
                        && (layoutResult != null || nameResult != null || redlineResult != null))
                    {
                        WriteCommunityFactCache(game, carId, sig, nameResult, layoutResult, redlineResult);
                        NotifyCarNameConsensus(game, carId, nameResult);
                        NotifyRedlineConsensus(game, carId, sig, redlineResult);
                        NotifyCommunityConsensus(game, carId, sig, layoutResult);
                        SimHub.Logging.Current.Info(
                            $"[TF4ALL] Headless community facts applied for {game}/{carId} (sig '{sig}').");
                    }
                }
                catch (Exception ex)
                {
                    SimHub.Logging.Current.Warn($"[TF4ALL] Headless community refresh failed: {ex.Message}");
                }
                // The live key may have moved on while this fetch ran
                // (signature warm-up, another car change): run one more pass
                // for whatever is current. No-ops when already handled, so
                // this converges instead of looping.
                try { MaybeRefreshCommunityFactsHeadless(); } catch { }
            });
        }

        /// <summary>Mint the car-fact fallback submitter id on first consent:
        /// a random GUID, never derived from hardware or the account, sent as
        /// submit_car_fact's p_anon_id. Only used server-side when the request
        /// carries no user token (signed-in submissions are keyed to the
        /// account instead). Idempotent; persists only when it actually
        /// minted. Travels in backups (BackupProjection Portable) so one
        /// human counts as one contributor across PCs.</summary>
        internal void EnsureCarFactsAnonId()
        {
            if (Settings == null) return;
            if (!string.IsNullOrEmpty((Settings.CarFactsAnonId ?? "").Trim())) return;
            Settings.CarFactsAnonId = Guid.NewGuid().ToString("N");
            try { PersistSettingsCore(); } catch { }
        }

        // ---- Anonymous usage statistics (telemetry_ping, migration 0127) ----

        /// <summary>Mint the analytics id if missing. Separate from the car-fact anon id
        /// so the two anonymous datasets can't be cross-linked. Random, never
        /// hardware-derived. Unlike CarFactsAnonId it deliberately does NOT travel in
        /// backups (BackupProjection MachineLocal): a backup lives under the user's account,
        /// so carrying it would record account -> anon-id and make the telemetry
        /// joinable to a real identity. A second PC mints its own and counts as a second
        /// install, which is the accepted trade.</summary>
        internal void EnsureAnalyticsAnonId()
        {
            if (Settings == null) return;
            if (!string.IsNullOrEmpty((Settings.AnalyticsAnonId ?? "").Trim())) return;
            Settings.AnalyticsAnonId = Guid.NewGuid().ToString("N");
            try { PersistSettingsCore(); } catch { }
        }

        // Portable settings that must NOT ride the snapshot even though they are
        // genuine user state: free text the user typed, and account- / id-derived
        // values. Non-portable fields (USB pins, paths, auth, migration latches,
        // nag / UI state, caches) need no entry here: the Portable gate in
        // BuildUsageSettingsSnapshot already drops everything outside Portable.
        // AnalyticsAnonId is the exception that proves that rule: it is Excluded,
        // not Portable, so the gate above already drops it and this entry can never
        // fire. It stays listed deliberately, so that reclassifying it (which is how
        // it reached the backup envelope once already) cannot silently start
        // stamping the anon id into its own settings snapshot.
        private static readonly System.Collections.Generic.HashSet<string> UsageSnapshotDeny =
            new System.Collections.Generic.HashSet<string>(StringComparer.Ordinal)
        {
            "AnalyticsAnonId", "CarFactsAnonId", "SharingAuthor", "HasEverSupported",
            "OledGreetingText", "OledCustomTexts",
            "DashIdleDriverName", "DashIdleNumber", "DashIdleColor", "DashIdleFont",
        };

        // The only STRING settings sent by value: short fixed selector strings, no
        // free text. Every other string stays out (paths, names, ids, greetings).
        // Enum-typed selectors (IdleLedMode, OledScreen, ...) are captured by the
        // enum branch below and need no entry here; dictionaries (CarLightPattern)
        // are dropped by the scalar rule.
        private static readonly System.Collections.Generic.HashSet<string> UsageSnapshotStringAllow =
            new System.Collections.Generic.HashSet<string>(StringComparer.Ordinal)
        {
            "DashTheme", "DashIdleStyle", "CspBridgeFfbField",
        };

        /// <summary>Build the anonymous settings snapshot as a compact JSON object.
        /// Emits only the genuine user settings (BackupProjection.Portable) that are
        /// scalar bool / number / enum, plus a short allowlist of enum-like strings,
        /// minus the portable-but-sensitive fields in UsageSnapshotDeny. Machine
        /// fields, auth, migration latches, nag / UI state and caches are all
        /// excluded by the Portable gate, so no personal or machine data rides
        /// along, and a newly added field is sent only once it is deliberately
        /// classified Portable and is a plain scalar.</summary>
        internal string BuildUsageSettingsSnapshot()
        {
            try
            {
                if (Settings == null) return null;
                var o = new Newtonsoft.Json.Linq.JObject();
                foreach (var p in typeof(TrueforceSettings).GetProperties(
                    System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Instance))
                {
                    if (!p.CanRead || !p.CanWrite) continue;
                    // Only genuine user settings: BackupProjection's Portable set.
                    // This drops machine-local fields (USB, paths, auth) and the
                    // Excluded bucket (migration latches, nag / UI state, caches) in
                    // one move, and is safe-by-default (a new field is emitted only
                    // once someone deliberately classifies it Portable).
                    if (!BackupProjection.Portable.Contains(p.Name)) continue;
                    if (UsageSnapshotDeny.Contains(p.Name)) continue;   // portable-but-sensitive
                    var t = Nullable.GetUnderlyingType(p.PropertyType) ?? p.PropertyType;
                    bool isBool = t == typeof(bool);
                    bool isNum  = t == typeof(int) || t == typeof(long)
                               || t == typeof(float) || t == typeof(double);
                    bool isEnum = t.IsEnum;
                    bool isStr  = t == typeof(string);
                    if (!isBool && !isNum && !isEnum && !isStr) continue;   // no collections / objects
                    if (isStr && !UsageSnapshotStringAllow.Contains(p.Name)) continue;
                    object v;
                    try { v = p.GetValue(Settings); } catch { continue; }
                    if (v == null) continue;
                    if (isStr)
                    {
                        string sv = ((string)v).Trim();
                        if (sv.Length == 0 || sv.Length > 40) continue;     // enum-like only
                        o[p.Name] = sv;
                    }
                    else if (isEnum)
                    {
                        o[p.Name] = v.ToString();                           // enum name, never PII
                    }
                    else
                    {
                        // PresetPayloadSerializer, not the parameterless FromObject: that
                        // overload resolves through JsonSerializer.CreateDefault() and so
                        // honours the process-global JsonConvert.DefaultSettings, which
                        // any plugin in the host can set. A converter registered there
                        // that claims double/float would change this snapshot's bytes,
                        // change its hash, and make it re-send daily with nothing
                        // actually changed. The preset path was already immune; this
                        // makes the two paths agree.
                        o[p.Name] = Newtonsoft.Json.Linq.JToken.FromObject(v, PresetPayloadSerializer);
                    }
                }
                return o.ToString(Newtonsoft.Json.Formatting.None);
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Warn("[TF4ALL] Usage snapshot build failed: " + ex.Message);
                return null;
            }
        }

        /// <summary>Send the anonymous usage ping if it is enabled and has not
        /// already been sent today (UTC). Self-gating, so it is safe to call on
        /// startup and on a timer. Fire-and-forget; never blocks.</summary>
        internal void MaybeSendUsagePing()
        {
            // Serializes the BUILD only. It is released as soon as the POST is
            // dispatched, so two requests can still be in flight at once (the day stamp
            // no longer suppresses re-entry until a 2xx lands). That overlap is
            // tolerated rather than prevented: CommitUsagePing is idempotent, and the
            // server upserts. What this does prevent is two threads building the
            // payload, which walks the preset graph under _carFactsLock.
            if (System.Threading.Interlocked.CompareExchange(ref _usagePingBusy, 1, 0) != 0) return;
            try
            {
                if (_shuttingDown || Settings == null || _telemetryClient == null) return;
                if (!Settings.ShareUsageStats) return;                 // master off = nothing sent
                // SimHub can be open with our plugin switched off; that is not an
                // active user. Skip when the plugin is turned off entirely.
                // LightsyncOnly still counts (the wheel's lights are in use).
                if (StoredMasterMode == TrueforceMasterMode.Off) return;
                string today = UsageDayKey();
                if (string.Equals(Settings.LastTelemetryPingDay, today, StringComparison.Ordinal))
                    return;                                            // already pinged today
                EnsureAnalyticsAnonId();
                string anonId = (Settings.AnalyticsAnonId ?? "").Trim();
                if (anonId.Length == 0) return;
                // _usageGameName, not _currentGameName: the same process-presence
                // signal the game-day recorder uses, so a title open in menus is
                // reported rather than showing up as no game at all.
                // Never send a user-added game's label: SimHub names custom titles
                // "Custom_<label>", whose suffix can be free text the user typed.
                string game = _usageGameName;
                if (!string.IsNullOrEmpty(game)
                    && game.StartsWith("Custom_", StringComparison.OrdinalIgnoreCase))
                    game = "Custom";
                // Settings snapshot, only when it changed since the last accepted
                // send, so storage scales with installs rather than install-days.
                // The new hash is held locally and committed only on success.
                string snapshot     = BuildUsageSettingsSnapshot();
                string snapshotHash = string.IsNullOrEmpty(snapshot) ? null : HashSnapshot(snapshot);
                bool   sendSnapshot = !string.IsNullOrEmpty(snapshotHash)
                    && !string.Equals(snapshotHash, Settings.LastTelemetrySettingsHash ?? "",
                                      StringComparison.Ordinal);

                // Per-game-day activity accumulated since the last ping. Fold in the
                // live game too: NoteTelemetryGameActivity only fires on a game
                // TRANSITION, so a session that spans UTC midnight, or one that began
                // with the plugin switched off, would otherwise never be recorded.
                string gamesJson = null;
                System.Collections.Generic.List<string> sentGameDays = null;
                var played = new System.Collections.Generic.HashSet<string>(StringComparer.Ordinal);
                PruneUsageGameDays();
                lock (_carFactsLock)
                {
                    var list = Settings.TelemetryGameDays;
                    if (list != null)
                    {
                        if (!string.IsNullOrEmpty(game))
                        {
                            string liveKey = game + "|" + today;
                            if (!list.Contains(liveKey))
                            {
                                if (list.Count >= UsageGameDayCap) list.RemoveAt(0);
                                list.Add(liveKey);
                            }
                        }
                        if (list.Count > 0)
                        {
                            var games = new Newtonsoft.Json.Linq.JArray();
                            sentGameDays = new System.Collections.Generic.List<string>(list);
                            foreach (var entry in sentGameDays)
                            {
                                int bar = entry.IndexOf('|');
                                if (bar <= 0 || bar >= entry.Length - 1) continue;
                                string g = entry.Substring(0, bar);
                                games.Add(new Newtonsoft.Json.Linq.JObject
                                    { ["g"] = g, ["d"] = entry.Substring(bar + 1) });
                                played.Add(g);
                            }
                            if (games.Count > 0)
                                gamesJson = games.ToString(Newtonsoft.Json.Formatting.None);
                        }
                    }
                }

                // Every game we have ever reported a body for is re-evaluated too, not
                // just the ones played since the last ping. Without this the preset test
                // fires only while a game still has an undrained activity entry, so a
                // preset retuned offline (edit it Tuesday afternoon, do not launch the
                // game) was never reported until that game was next played, and never at
                // all if it was not. The global settings snapshot has no such gate, and
                // the rule should be the same for both: send it when the body differs
                // from what we last delivered. Also self-heals the 10-body batch limit,
                // whose overflow games used to lose their activity entry in the same
                // ping and drop out of the evaluation set entirely.
                lock (_carFactsLock)
                {
                    var knownGames = Settings.TelemetryGamePresetHashes;
                    if (knownGames != null)
                        foreach (var kv in knownGames) played.Add(kv.Key);
                }

                // Per-game preset bodies for those games, staged (not stamped) so a
                // lost send re-sends them rather than marking them already delivered.
                var stagedPresetHashes =
                    new System.Collections.Generic.Dictionary<string, string>(StringComparer.Ordinal);
                string gamePresetsJson = BuildChangedGamePresetsJson(played, stagedPresetHashes);

                string commitHash  = sendSnapshot ? snapshotHash : null;
                var    commitDays  = sentGameDays;
                var    commitOwner = Settings;              // identity checked at commit
                // One line per ping, so what was sent is answerable from a log alone.
                // Without it the only telemetry lines are failures, and a ping that
                // carried nothing looks exactly like a ping that never happened; that
                // ambiguity already cost a live test. Counts only, never content.
                SimHub.Logging.Current.Info(string.Format(
                    "[TF4ALL] Usage ping: game='{0}' snapshot={1} gameDays={2} presets={3}",
                    game ?? "(none)", sendSnapshot ? "yes" : "unchanged",
                    commitDays?.Count ?? 0, stagedPresetHashes.Count));
                _telemetryClient.SendPing(anonId, CurrentVersionString(),
                    Settings.LastUsedWheel, game, sendSnapshot ? snapshot : null,
                    gamesJson, gamePresetsJson,
                    receipt => CommitUsagePing(commitOwner, today, commitHash, commitDays,
                                               stagedPresetHashes, receipt));
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Warn("[TF4ALL] Usage ping error: " + ex.Message);
            }
            finally
            {
                // Released once the POST is DISPATCHED (it is fire-and-forget), not
                // when it completes: the commit is idempotent, and the day stamp
                // suppresses the next tick once the server has accepted one.
                System.Threading.Interlocked.Exchange(ref _usagePingBusy, 0);
            }
        }

        private int _usagePingBusy;

        // Stable hex SHA-256 of the snapshot JSON, for the once-a-day
        // settings-changed check. Property order is stable (reflection order over
        // a fixed set), so an unchanged snapshot hashes the same across runs; a
        // reorder at worst re-sends the snapshot once, which is harmless.
        private static string HashSnapshot(string snapshot)
        {
            if (string.IsNullOrEmpty(snapshot)) return "";
            try
            {
                using (var sha = System.Security.Cryptography.SHA256.Create())
                {
                    byte[] h = sha.ComputeHash(System.Text.Encoding.UTF8.GetBytes(snapshot));
                    var sb = new System.Text.StringBuilder(h.Length * 2);
                    foreach (byte b in h) sb.Append(b.ToString("x2"));
                    return sb.ToString();
                }
            }
            catch { return ""; }
        }

        private string   _telemetryLastNotedGame;
        private DateTime _telemetryLastNotedDate;   // UTC date component, MinValue until first note

        /// <summary>The live game as ANALYTICS sees it: set whenever SimHub reports the
        /// title's process up, even if no telemetry is flowing. Deliberately separate
        /// from <see cref="_currentGameName"/>, which stays gated on GameRunning because
        /// the force path must not act on a title that is sending nothing.</summary>
        private volatile string _usageGameName;

        /// <summary>Today's UTC date as the wire format expects it. InvariantCulture
        /// is load-bearing, not tidiness: ToString on the current culture uses that
        /// culture's CALENDAR, so a th-TH install writes 2569-09-21, ar-SA writes
        /// 1448-04-10 and fa-IR writes 1405-06-30. All three are ISO-shaped, so they
        /// pass the server's regex and then fall outside its date window, which
        /// discards them while still answering 2xx. Those installs would count toward
        /// DAU and never toward per-game DAU, silently.</summary>
        private static string UsageDayKey() => UsageDayKey(DateTime.UtcNow);

        private static string UsageDayKey(DateTime utc) =>
            utc.ToString("yyyy-MM-dd", System.Globalization.CultureInfo.InvariantCulture);

        // The server takes at most 200 game-days and 10 preset bodies per call and
        // ignores anything past that, so the client never builds more than it will
        // accept (an over-long array used to be dropped whole, silently).
        private const int UsageGameDayCap  = 200;
        private const int UsagePresetBatch = 10;

        // Called every DataUpdate with the live game name (or null). Cheap on the
        // hot path: two ordinal compares with no allocation; the record runs only on
        // a transition into a game, and only while usage stats are on and the plugin
        // is not off. Accumulates a (game|UTC-day) entry that the once-a-day ping
        // drains, so we learn per-game daily activity without extra pings.
        private void NoteTelemetryGameActivity(string game)
        {
            // The latch is keyed on game AND UTC date. Game alone made it blind to
            // midnight: a session starting 20:30 and ending 01:00 never re-noted, so
            // the new day got no entry at all unless the six-hour timer happened to
            // tick before the user quit (it is MaybeSendUsagePing, not this method,
            // that folds the live game in, and End() does not flush). Comparing the
            // DateTime.Date rather than a formatted string keeps the hot path
            // allocation-free; the string is built only once a transition is real.
            DateTime utcNow = DateTime.UtcNow;
            if (string.Equals(game, _telemetryLastNotedGame, StringComparison.Ordinal)
                && utcNow.Date == _telemetryLastNotedDate) return;
            if (string.IsNullOrEmpty(game)) { _telemetryLastNotedGame = null; return; }  // stopped
            try
            {
                // Gates BEFORE latching: latching first would consume the transition, so
                // a game launched while stats were off (or the plugin was Off) could
                // never be noted once the gate opened, even though it is still running.
                if (_shuttingDown || Settings == null || !Settings.ShareUsageStats) return;
                if (StoredMasterMode == TrueforceMasterMode.Off) return;
                _telemetryLastNotedGame = game;
                _telemetryLastNotedDate = utcNow.Date;
                string g = game.StartsWith("Custom_", StringComparison.OrdinalIgnoreCase) ? "Custom" : game;
                string key = g + "|" + UsageDayKey(utcNow);
                bool added = false;
                // _carFactsLock, not a private lock: this is a structural mutation of a
                // collection in the Settings graph on the data thread, and
                // PersistSettingsCore / BuildEnvelopeLocked walk that whole graph with
                // Newtonsoft. Same contract as the GamesWithRedline add above.
                lock (_carFactsLock)
                {
                    var list = Settings.TelemetryGameDays;
                    if (list != null && !list.Contains(key))
                    {
                        // Evict oldest-first at the cap, never refuse the add. Refusing
                        // was terminal: an entry whose day has aged past the server's
                        // 60-day window can never be confirmed, so CommitUsagePing never
                        // removes it. Let 200 of those accumulate (an install that plays
                        // daily with no successful ping for a couple of months, a rig
                        // offline in a garage) and the queue is permanently full of
                        // entries that can never leave: activity stops being recorded for
                        // good, the live game can no longer be folded in, and the preset
                        // feed dies with it because `played` comes from this same list.
                        // Keeping the newest 200 days is what the analytics want anyway.
                        if (list.Count >= UsageGameDayCap) list.RemoveAt(0);
                        list.Add(key);
                        added = true;
                    }
                }
                // Persist off the hot path so the entry survives a close before the next
                // ping. At most one save per game per UTC day, and it lands at game
                // START, where PersistSettingsCore's whole-graph write holds
                // _carFactsLock and can briefly stall the data thread. Accepted: the
                // alternative is losing the day's activity when SimHub closes.
                if (added) System.Threading.Tasks.Task.Run(() => { try { PersistSettingsCore(); } catch { } });
            }
            catch { /* telemetry must never disturb DataUpdate */ }
        }

        // Identity / attribution fields that must never ride a preset body: author
        // and description (free text), pack name, and the community-upload ids (one
        // is a user uuid). Also the per-car override map (the payload is the GAME
        // default; per-car is a separate, much larger question) and the custom-
        // engine id. Stripped at any depth.
        private static readonly System.Collections.Generic.HashSet<string> PresetPayloadDeny =
            new System.Collections.Generic.HashSet<string>(StringComparer.Ordinal)
        {
            "Author", "AuthorVersion", "PackName", "Description",
            "CommunitySourceId", "CommunityUploadedById", "CommunityUploadedByUserId",
            "CommunityUploadedBodyHash", "CommunityUploadedVersion",
            "CarOverrides", "DeclinedCommunityRedlineSig", "UserCustomEngineId",
            // Reachable from EnginePulseSettings and user-authored:
            // CustomFiringPatternName is a name the user types. They are also kept
            // out by ShouldSerialize* on those properties, but that block is
            // documented as migration hygiene for retired fields, so it must not be
            // this payload's only defense.
            "CustomEngineId", "CustomFiringPattern", "CustomFiringPatternName",
            // Retired legacy car-fact values. Not personal data, but they are NUMBERS,
            // so StripTextLeaves cannot backstop them: today they are only kept out by
            // ShouldSerialize* on those properties, and that block is documented as
            // removable migration hygiene.
            "Cylinders", "FiringOrderEnabled",
        };

        private static void StripPresetIdentity(Newtonsoft.Json.Linq.JToken tok)
        {
            if (tok is Newtonsoft.Json.Linq.JObject o)
            {
                foreach (var name in System.Linq.Enumerable.ToList(
                    System.Linq.Enumerable.Select(o.Properties(), p => p.Name)))
                    if (PresetPayloadDeny.Contains(name)) o.Remove(name);
                foreach (var p in o.Properties()) StripPresetIdentity(p.Value);
            }
            else if (tok is Newtonsoft.Json.Linq.JArray a)
            {
                foreach (var item in a) StripPresetIdentity(item);
            }
        }

        /// <summary>Serializer for the per-game preset payload. Clears the converter on
        /// enum members so they serialize as INTEGERS. Newtonsoft applies a member-level
        /// [JsonConverter(typeof(StringEnumConverter))] regardless of serializer
        /// settings, so without this every enum in the preset graph becomes a string and
        /// StripTextLeaves deletes it (verified: 143 leaves -> 119, losing all 14
        /// Waveform / Mode / ElectricMode / SurfaceWaveform fields). Resolver
        /// subclassing follows the existing PresetBodyHasher pattern.
        ///
        /// BOTH hooks are needed. CreateProperty clears the MEMBER attribute, which is
        /// what the settings model uses today; CreateContract clears a TYPE-level
        /// attribute on the enum declaration itself, which nothing uses today but which
        /// is the obvious tidy-up when someone notices the 14 identical member
        /// attributes. Without the second hook that refactor silently reinstates the
        /// bug, because a type-level converter is resolved from the enum's contract and
        /// never passes through CreateProperty.</summary>
        private sealed class EnumsAsIntegersResolver : Newtonsoft.Json.Serialization.DefaultContractResolver
        {
            protected override Newtonsoft.Json.Serialization.JsonProperty CreateProperty(
                System.Reflection.MemberInfo member, Newtonsoft.Json.MemberSerialization memberSerialization)
            {
                var p = base.CreateProperty(member, memberSerialization);
                var t = Nullable.GetUnderlyingType(p.PropertyType) ?? p.PropertyType;
                if (t != null && t.IsEnum) p.Converter = null;
                // ItemConverter is the third route: [JsonProperty(ItemConverterType =
                // typeof(StringEnumConverter))] on a collection-of-enums member would
                // still write strings, and StripTextLeaves would then empty the array.
                // Nothing in the graph is a collection of enums today, so this is a
                // guard against the shape rather than a fix for a live bug.
                p.ItemConverter = null;
                return p;
            }

            protected override Newtonsoft.Json.Serialization.JsonContract CreateContract(Type objectType)
            {
                var c = base.CreateContract(objectType);
                var t = Nullable.GetUnderlyingType(objectType) ?? objectType;
                if (t != null && t.IsEnum) c.Converter = null;
                return c;
            }
        }

        private static readonly Newtonsoft.Json.JsonSerializer PresetPayloadSerializer =
            new Newtonsoft.Json.JsonSerializer
            {
                ContractResolver = new EnumsAsIntegersResolver(),
            };

        private static bool IsTextLeaf(Newtonsoft.Json.Linq.JToken t)
        {
            var v = t as Newtonsoft.Json.Linq.JValue;
            if (v == null) return false;
            switch (v.Type)
            {
                case Newtonsoft.Json.Linq.JTokenType.String:
                case Newtonsoft.Json.Linq.JTokenType.Uri:
                case Newtonsoft.Json.Linq.JTokenType.Guid:
                case Newtonsoft.Json.Linq.JTokenType.Date:
                case Newtonsoft.Json.Linq.JTokenType.Bytes:
                    return true;
                default:
                    return false;
            }
        }

        /// <summary>Second pass, and the one that actually holds the line: drop every
        /// TEXT leaf, so a free-text, path or id field added to GameSettingsSnapshot or
        /// any of its effect classes later cannot reach the payload by default (name
        /// denial alone is a blocklist over a surface that grows).
        ///
        /// This is only safe because the payload is serialized with
        /// <see cref="PresetPayloadSerializer"/>, which forces enums to integers. The
        /// enums here carry a [JsonConverter(StringEnumConverter)] attribute, which
        /// beats serializer settings, so a plain serializer writes them as TEXT and
        /// this pass would delete all 14 of them (Waveform, Mode, ElectricMode,
        /// SurfaceWaveform, ...). Anything serialized here that is genuinely text and
        /// genuinely wanted has the same problem and must be given a non-text
        /// representation, not an exemption. Property NAMES are not inspected: no
        /// dictionary is reachable from the snapshot today (CarOverrides is denied by
        /// name), but a dictionary added later would carry its user-controlled KEYS
        /// through this pass untouched.</summary>
        private static void StripTextLeaves(Newtonsoft.Json.Linq.JToken tok)
        {
            if (tok is Newtonsoft.Json.Linq.JObject o)
            {
                foreach (var name in System.Linq.Enumerable.ToList(
                    System.Linq.Enumerable.Select(o.Properties(), p => p.Name)))
                {
                    var val = o[name];
                    if (IsTextLeaf(val)) o.Remove(name);
                    else StripTextLeaves(val);
                }
            }
            else if (tok is Newtonsoft.Json.Linq.JArray a)
            {
                for (int i = a.Count - 1; i >= 0; i--)
                {
                    if (IsTextLeaf(a[i])) a.RemoveAt(i);
                    else StripTextLeaves(a[i]);
                }
            }
        }

        /// <summary>For each played game, its DEFAULT preset body (identity and text
        /// stripped) plus the user's per-game intent triplet, as [{g, p}], but only
        /// for games whose body changed since we last sent it. New hashes are STAGED
        /// into <paramref name="staged"/> rather than
        /// written to Settings, so a send that never lands cannot mark a body as
        /// "already sent". Takes _carFactsLock: it walks the Settings preset graph,
        /// which is the documented rule (see BuildEnvelopeLocked).</summary>
        private string BuildChangedGamePresetsJson(
            System.Collections.Generic.HashSet<string> played,
            System.Collections.Generic.Dictionary<string, string> staged)
        {
            try
            {
                if (played == null || played.Count == 0 || staged == null) return null;
                var arr = new Newtonsoft.Json.Linq.JArray();
                // Hashes accumulate HERE, not into `staged`, until the payload is fully
                // built. `staged` is captured by the on-success commit, so writing into
                // it early meant a mid-loop throw (the catch returns null, sending no
                // presets) still marked those games delivered, defeating the very
                // guarantee staging exists to give.
                var built = new System.Collections.Generic.Dictionary<string, string>(StringComparer.Ordinal);
                lock (_carFactsLock)
                {
                    if (Settings?.GameDefaults == null || Settings.Presets == null) return null;
                    var known = Settings.TelemetryGamePresetHashes;
                    foreach (var g in played)
                    {
                        if (arr.Count >= UsagePresetBatch) break;        // server takes 10
                        if (!Settings.GameDefaults.TryGetValue(g, out var presetName)
                            || string.IsNullOrEmpty(presetName)) continue;
                        if (!Settings.Presets.TryGetValue(presetName, out var snap) || snap == null) continue;
                        // PresetPayloadSerializer, not the parameterless FromObject: it
                        // both avoids JsonConvert.DefaultSettings AND forces enums to
                        // integers, without which StripTextLeaves below deletes every
                        // enum in the body. The hash is taken AFTER stripping, so that
                        // loss would also have made waveform/mode edits un-resendable.
                        var body = Newtonsoft.Json.Linq.JObject.FromObject(snap, PresetPayloadSerializer);
                        StripPresetIdentity(body);
                        StripTextLeaves(body);
                        // The three per-game things the user DECIDED, riding along on
                        // the body that is already going out. Without them the Mode B
                        // tuning corpus cannot be read: we can see that someone moved
                        // ModeBBrakeGain, but not whether they run telemetry FFB in
                        // iRacing, in FH6, or nowhere at all, so every Mode B number we
                        // collect is unattributable.
                        //
                        // HERE and not in BuildUsageSettingsSnapshot. That blob is one
                        // column with an 8192 byte cap, and telemetry_ping nulls it
                        // WHOLE when it goes over while still answering ok, so nothing
                        // fails and nothing retries; it measured 4932 bytes over 161
                        // keys on 2026-09-24, about 60 percent of the limit, and it
                        // grows with every setting classified Portable. Crossing that
                        // line costs the entire settings half of usage statistics for
                        // every install on the build at once. This body gets its own
                        // 8192 byte budget per (anon_id, game), and the largest live
                        // body measured 1871 bytes on 2026-09-24, so roughly 6300
                        // spare; these three keys cost the scarce one nothing.
                        //
                        // ORDERING IS LOAD-BEARING, do not move this. StripTextLeaves is
                        // name-blind: it sweeps the whole body and drops every text leaf
                        // it meets, so anything injected above it that is, or later
                        // becomes, text vanishes without a word. That is also why the
                        // mode goes out as its integer rather than its name, the same
                        // reason PresetPayloadSerializer forces every other enum to an
                        // integer. The other side is worse: the hash below is what
                        // decides whether this game is resent at all, so injecting
                        // AFTER it means a user switching a game to Lightsync only
                        // changes nothing the hash can see, no resend ever fires, and
                        // the feature is silently dead.
                        //
                        // WARNING for whoever adds the fourth key: this site is
                        // DOWNSTREAM of both privacy passes. Neither StripPresetIdentity
                        // (the name deny-list) nor StripTextLeaves (the type-based
                        // backstop) can see anything written here. Only non-text,
                        // non-identifying scalars may be added at this point. Anything
                        // text-valued, an active preset name, a car id, a custom game
                        // name, either gets a numeric form or goes through the normal
                        // body above, where the sweeps can see it.
                        //
                        // A key is emitted only when the map actually holds this game.
                        // Absence has to stay readable as "never chose": the game-change
                        // path deliberately stopped writing its own default into
                        // GameModes precisely because doing so made that default
                        // indistinguishable from a decision, and reading it back here
                        // must not undo that. The leading underscore keeps these clear
                        // of GameSettingsSnapshot's property names, which is where every
                        // other key in the body comes from.
                        if (Settings.ModeBGameEnabled != null
                            && Settings.ModeBGameEnabled.TryGetValue(g, out var mbOn))
                            body["_modeB"] = mbOn;
                        // _mode is TrueforceMasterMode as stored: 0 Off, 1 Lightsync
                        // only, 2 Normal. Renumbering that enum reinterprets every row
                        // already collected.
                        if (Settings.GameModes != null
                            && Settings.GameModes.TryGetValue(g, out var gMode))
                            body["_mode"] = (int)gMode;
                        if (Settings.GameEnabled != null
                            && Settings.GameEnabled.TryGetValue(g, out var gOn))
                            body["_enabled"] = gOn;
                        string hash = HashSnapshot(body.ToString(Newtonsoft.Json.Formatting.None));
                        if (known != null && known.TryGetValue(g, out var last)
                            && string.Equals(last, hash, StringComparison.Ordinal)) continue;   // unchanged
                        built[g] = hash;
                        arr.Add(new Newtonsoft.Json.Linq.JObject { ["g"] = g, ["p"] = body });
                    }
                }
                if (arr.Count == 0) return null;
                string json = arr.ToString(Newtonsoft.Json.Formatting.None);   // can throw; staged stays empty
                foreach (var kv in built) staged[kv.Key] = kv.Value;
                return json;
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Warn("[TF4ALL] Game preset payload build failed: " + ex.Message);
                return null;
            }
        }

        /// <summary>Drop queued game-days the server can no longer accept, and keep
        /// the queue inside its cap. Returns true when anything was removed.
        ///
        /// Deliberately NOT gated on ShareUsageStats, and called from Init as well as
        /// from the ping. The send path is gated, so an install that opted out would
        /// otherwise keep whatever it had queued at that moment in its settings file
        /// indefinitely: never sent, because sending is off, and never pruned, because
        /// the only pruner ran behind the same gate. Holding a play history for someone
        /// who opted out serves no purpose. Age-based rather than wholesale, so turning
        /// the switch off and straight back on still reports the day.</summary>
        private bool PruneUsageGameDays()
        {
            try
            {
                if (Settings == null) return false;
                // The server accepts a 60-day window; anything older is refused, so it
                // is never echoed in a receipt, so CommitUsagePing never removes it.
                // Left alone such an entry is immortal: re-serialized into every future
                // ping and occupying a cap slot for good. Cut at 55 days, safely inside
                // the window, so nothing still deliverable is thrown away.
                string cutoff = UsageDayKey(DateTime.UtcNow.AddDays(-55));
                lock (_carFactsLock)
                {
                    var list = Settings.TelemetryGameDays;
                    if (list == null || list.Count == 0) return false;
                    int before = list.Count;
                    list.RemoveAll(e =>
                    {
                        int b = e == null ? -1 : e.IndexOf('|');
                        return b <= 0 || b >= e.Length - 1
                            || string.CompareOrdinal(e.Substring(b + 1), cutoff) < 0;
                    });
                    // A file edited by hand, or written by an older build with a larger
                    // cap, can still arrive over the limit; trim oldest-first.
                    while (list.Count > UsageGameDayCap) list.RemoveAt(0);
                    return list.Count != before;
                }
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Info("[TF4ALL] Usage game-day prune failed: " + ex.Message);
                return false;
            }
        }

        /// <summary>Let a deliberate opt-IN send today's activity even though the
        /// once-a-day stamp has already been spent. Turning the switch on is a fresh,
        /// explicit consent, so the right response is to report rather than to sit on
        /// what is already queued until tomorrow. It also makes the toggle the only
        /// thing a tester needs in order to force a send; there is otherwise no way to
        /// trigger one, which made the feature untestable by hand.
        ///
        /// Cheap to abuse only in the sense that toggling repeatedly re-sends: the
        /// server upserts on (anon_id, day) so the row count cannot grow, and
        /// MaybeSendUsagePing single-flights through _usagePingBusy.</summary>
        internal void AllowUsagePingAgainToday()
        {
            try
            {
                if (Settings == null) return;
                Settings.LastTelemetryPingDay = null;
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Info("[TF4ALL] Usage ping re-arm failed: " + ex.Message);
            }
        }

        /// <summary>Commit the ping's local state, called ONLY after the server
        /// accepted it, and then only for what the server's RECEIPT says it actually
        /// stored. Nothing is stamped or dropped before that, so a failed send, or a
        /// payload the server filtered (too large, out of its date window, past its
        /// per-install game cap), retries on the next tick instead of being recorded
        /// as delivered. That second half matters more than it looks: the resend test
        /// is a hash compare, so a payload wrongly marked delivered is not lost for
        /// one ping, it is lost until the user happens to change that setting again.
        /// A null receipt (an older server, an unreadable body) commits the day stamp
        /// only, which costs one extra send and can never lose data.</summary>
        private void CommitUsagePing(TrueforceSettings owner, string day, string snapshotHash,
            System.Collections.Generic.List<string> sentGameDays,
            System.Collections.Generic.Dictionary<string, string> presetHashes,
            TelemetryReceipt receipt)
        {
            try
            {
                // This runs on a ThreadPool thread up to the HTTP timeout after dispatch.
                // Bail if we are tearing down (it would write the settings file after
                // End()'s final save) or if the settings graph was REPLACED meanwhile by
                // an import / restore: stamping a different object costs that install a
                // day of DAU under a freshly minted id. Same guard pattern the other
                // post-async callbacks in this file use.
                if (owner == null || _shuttingDown || !ReferenceEquals(Settings, owner)) return;
                SimHub.Logging.Current.Info(receipt == null
                    ? "[TF4ALL] Usage ping accepted, no receipt: stamping the day only."
                    : string.Format("[TF4ALL] Usage ping stored: settings={0} gameDays={1} presets={2}",
                        receipt.SettingsStored ? "yes" : "no",
                        receipt.Games.Count, receipt.Presets.Count));
                // The line above prints settings=no in two completely different
                // situations: the ordinary one, where we sent no snapshot at all
                // because its hash had not changed, and the one that matters, where
                // we did send one and the server threw it away. Those look identical
                // in a log, and the second is the only warning anyone gets.
                //
                // telemetry_ping nulls the WHOLE settings blob when it exceeds 8192
                // bytes and still answers ok, so nothing fails, nothing retries, and
                // the settings half of usage statistics simply stops arriving. The
                // blob is every scalar in BackupProjection.Portable, so it grows each
                // time a setting is classified Portable for backup: measured 4932
                // bytes over 161 keys on 2026-09-24, about 60 percent of the limit.
                // That makes this a GLOBAL cliff rather than a per-install one. When
                // it is crossed it is crossed by every install on that build at once,
                // which is exactly the kind of failure that goes unnoticed for months.
                // Warn, not Info: it means a feature has silently stopped working.
                if (!string.IsNullOrEmpty(snapshotHash) && receipt != null && !receipt.SettingsStored)
                    SimHub.Logging.Current.Warn(
                        "[TF4ALL] Usage ping: the settings snapshot was sent but the server did not "
                        + "store it, which means it is over the 8 KB payload limit. Settings "
                        + "statistics are no longer being recorded from this install; the rest of "
                        + "the ping (wheel, version, games played) was unaffected. The snapshot is "
                        + "left unstamped so it retries, but it will keep being refused until the "
                        + "payload gets smaller.");
                // Every write below goes through `owner`, never a fresh read of the
                // Settings property: the guard has already proven owner is the live
                // graph, and re-reading a plain auto-property would let an import
                // landing in between write this ping's state into the NEW object,
                // which is the exact outcome the guard exists to prevent.
                lock (_carFactsLock)
                {
                    // Re-checked inside the lock: End() sets the flag and then does its
                    // own final save, so a callback that read it a moment earlier would
                    // otherwise persist over the top of that save. Leaving the entries
                    // queued is the right outcome; they go out on the next run.
                    if (_shuttingDown) return;
                    owner.LastTelemetryPingDay = day;
                    if (!string.IsNullOrEmpty(snapshotHash) && receipt != null && receipt.SettingsStored)
                        owner.LastTelemetrySettingsHash = snapshotHash;
                    // Drop exactly the entries the server confirmed, BY VALUE. Not by
                    // index or count: the day stamp now lands only on success, so two
                    // pings can briefly overlap, and an index-based drop would then
                    // remove entries that were never sent. Remove(item) on an
                    // already-removed key is a no-op, which makes a repeated commit
                    // harmless. Anything unconfirmed, and anything the data thread
                    // appended meanwhile, stays queued.
                    var list = owner.TelemetryGameDays;
                    if (list != null && sentGameDays != null && receipt != null)
                        foreach (var key in sentGameDays)
                            if (receipt.Games.Contains(key)) list.Remove(key);
                    if (presetHashes != null && presetHashes.Count > 0 && receipt != null)
                    {
                        var h = owner.TelemetryGamePresetHashes;
                        if (h == null)
                        {
                            h = new System.Collections.Generic.Dictionary<string, string>(StringComparer.Ordinal);
                            owner.TelemetryGamePresetHashes = h;
                        }
                        foreach (var kv in presetHashes)
                            if (receipt.Presets.Contains(kv.Key)) h[kv.Key] = kv.Value;
                    }
                }
                PersistSettingsCore();
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Warn("[TF4ALL] Usage ping commit failed: " + ex.Message);
            }
        }

        /// <summary>Fire-and-forget submission of a redline correction.
        /// Mirrors <see cref="SubmitEngineLayoutToCommunity"/>: gated by
        /// CommunityEnabled, plumbs the active car's variant signature
        /// through so Forza swaps don't all share one redline row.</summary>
        public void SubmitRedlineToCommunity(string game, string carId, int rpm,
            IReadOnlyList<GearRedline> perGear = null)
        {
            _community?.SubmitRedlineAsync(game, carId, rpm,
                ComputeActiveCarVariantSignature(game, carId), perGear);
            // Car facts are anonymous: the contribution note tracks whether a
            // submission actually went out, which needs community on + the
            // car-data sharing consent, not a signed-in account.
            if (Settings?.CommunityEnabled == true && Settings.AutoSubmitCarFacts)
                NoteMotdContribution(MotdContribution.CarFact);
        }


        // Rank for variant selection: bigger wins. User (local correction) is
        // top: a user who clicked Correct knows what's actually in this car
        // and that overrides everything we sourced elsewhere. Community sits
        // mid: it's vetted but generic, the user can still override. Scanner
        // (heuristic) is the lowest stored tier; below it the caller's
        // Baked / resolver fallback takes over.
        // Cascade priority used by PickStoredVariant. CarFactSource.User
        // is intentionally absent: User-tagged rows are legacy data from
        // an earlier correction API that was superseded by the inline
        // "Correct..." engine-layout affordance and silent telemetry-driven
        // variant auto-create. PickStoredVariant filters User-source out
        // of the pool entirely so it never reaches this switch.
        private static int SourcePriority(CarFactSource s)
        {
            switch (s)
            {
                case CarFactSource.UserVariant:  return 45;
                case CarFactSource.Community:    return 40;
                case CarFactSource.SwapOverride: return 30;
                case CarFactSource.Baked:        return 20;
                case CarFactSource.Scanner:      return 10;
                case CarFactSource.GameTelemetry: return 0;
                default:                         return 0;
            }
        }

        // Re-resolve and apply the CarFacts cascade for the active car. Called
        // by the car-change handler and by post-correction flows (so a user
        // correction takes effect live without forcing a car swap). Mutates
        // the EnginePulse + RevLimiter slots that the apply-path reads:
        //   EnginePulse.AutoLayout / AutoLayoutSource / CatalogCyl
        //   RevLimiter.CarFactsRedline
        //   _activeCarDisplayName
        // Idempotent: safe to call repeatedly. logResolution=true emits an Info
        // log line summarizing which source won; the post-correction caller
        // passes true to leave a trace of the new resolved state.
        public void ResolveAndApplyCarFactsForActiveCar(string carId, bool logResolution)
        {
            if (RevLimiter != null) RevLimiter.CarFactsRedline = null;
            if (EnginePulse == null) return;

            EnginePulse.AutoLayout = null;
            EnginePulse.AutoLayoutSource = null;
            EnginePulse.NonCommunityAutoLayout = null;
            EnginePulse.NonCommunityAutoLayoutSource = null;
            // Observed* fields are NOT reset here - they belong to the
            // active car's live observations and are cleared only on car
            // change (in the active-car-change handler). Resetting on
            // every resolver pass would wipe the variant signature each
            // time a community fetch returns, briefly emptying it until
            // the next telemetry frame.
            EnginePulse.CatalogCyl = null;
            // Pin state must not outlive its car: since the 2026-07
            // centralization this method is the ONLY writer of the effect's
            // user slot, so clear it up front (the pin block below re-sets it
            // when a pin resolves for the current car). Without this, a
            // no-car resolve (back to menu) kept playing the previous car's
            // pinned engine.
            EnginePulse.Layout = Effects.EngineLayout.Auto;
            EnginePulse.CustomPattern = null;
            EnginePulse.ActiveCustomIsElectric = false;
            _activePinnedCustomEngine = null;
            _activeCarDisplayName = null;
            _activeCarCommunityDisplayName = null;

            if (string.IsNullOrEmpty(carId)) return;

            // CarFacts (the community-vetted layer) feeds variants for this
            // car. Two separable contributions:
            //   1. Cylinders + EngineConfig → AutoLayout
            //   2. RedlineRpm + CarName     → applied independently
            // The split apply lets a redline-only or name-only bundle still
            // contribute without forcing a cylinder count.
            bool haveVariant = TryResolveActiveVariant(_activeGame, carId, out var v);

            // CarName cascade (chassis-level, variant-independent):
            //   1. Local CarFacts bundle CarName (from a prior Rename
            //      action). Local wins so the user's explicit rename is
            //      respected - silently overriding it with the community
            //      consensus would defeat the purpose of renaming. The UI
            //      surfaces the community name alongside when they differ.
            //   2. Community consensus (fetched name for this car). Used
            //      when the user hasn't renamed locally.
            //   3. CarCylinderResolver's catalog-derived display name
            //      (set later when the resolver hits a catalog entry).
            string ck = _activeGame + "/" + carId;
            _activeCarCommunityDisplayName = null;
            string localName = null;
            // Locked: variant auto-create adds CarFacts keys (dictionary rehash)
            // under _carFactsLock on other threads while this runs on the
            // data/UI threads; an unlocked TryGetValue can misread mid-rehash.
            lock (_carFactsLock)
            {
                if (Settings?.CarFacts != null
                    && Settings.CarFacts.TryGetValue(ck, out var bundle)
                    && bundle != null
                    && !string.IsNullOrEmpty(bundle.CarName))
                    localName = bundle.CarName;
            }
            string communityName = (_activeCarCommunityNameConsensus != null
                && _activeCarCommunityNameKey == ck
                && !string.IsNullOrEmpty(_activeCarCommunityNameConsensus.Name))
                ? _activeCarCommunityNameConsensus.Name : null;
            // Telemetry-reported OFFICIAL name (FS mod's getFullName). The
            // game itself is the authority the car_name fact models, so it
            // outranks community consensus (which exists for games that
            // don't expose names) but never a local rename.
            string telemetryName = null;
            if (_activeGame != null
                && _activeGame.StartsWith("FarmingSimulator", StringComparison.Ordinal))
                telemetryName = _fsPipeSource?.CarDisplayName;
            else if (IsR3EGame(_activeGame))
                telemetryName = _r3eCarDisplayName;
            else if (ActiveGameIsArcade)
            {
                // The game's own name for the car, read from its data files by the static analysis.
                // It is the authority here in exactly the way the mod's name is for Farming
                // Simulator, so it belongs on the same rung.
                var arcadeCar = ArcadeCarNow();
                if (arcadeCar != null) telemetryName = arcadeCar.Name;
            }
            if (!string.IsNullOrEmpty(localName))
            {
                _activeCarDisplayName = localName;
                // Stash the community name so the UI can show a "community
                // says: X" affordance when it differs from the local pick.
                if (!string.IsNullOrEmpty(communityName)
                    && !string.Equals(communityName, localName, StringComparison.Ordinal))
                    _activeCarCommunityDisplayName = communityName;
            }
            else if (!string.IsNullOrEmpty(telemetryName))
                _activeCarDisplayName = telemetryName;
            else if (!string.IsNullOrEmpty(communityName))
                _activeCarDisplayName = communityName;

            // 3. Catalog display name (FH5 cylinder-table names / FH6 name-only
            //    table). Lowest priority: only when the user hasn't renamed and
            //    the community has no consensus. The per-branch resolver lookups
            //    below already cover FH5 via the cylinder bake, but FH6 has no
            //    cylinder entry, so seed the name here from the catalog so both
            //    games light up the header, Rename prefill, and preset auto-name
            //    uniformly. Cheap in-memory lookup; nothing is persisted.
            if (string.IsNullOrEmpty(_activeCarDisplayName)
                && BuiltinCarCylinders.TryGetDisplayName(_activeGame, carId, out var catalogName))
                _activeCarDisplayName = catalogName;

            // Per-variant redline resolution:
            //   - The user's OWN values (default gear-0 + per-gear overrides) go
            //     into the effect's per-gear map; they win over everything below.
            //   - The live community consensus (matching the current signature)
            //     is handed over as CarFactsRedline; the effect uses it only when
            //     the user pinned nothing AND the game reports no telemetry
            //     redline (the cascade order is set in ResolveEffectiveRedline).
            // The stored variant's own RedlineRpm is NOT used as the buzz point:
            // the effect reads the LIVE telemetry redline directly, so a captured
            // snapshot can't outrank the current value.
            string currentSigForRedline = ComputeActiveCarVariantSignature(_activeGame, carId);
            var activeStoredForRedline = FindActiveStoredVariant();
            // Build the map under the lock: this runs on the data thread, while
            // the UI thread structurally mutates the same PerGearRedlines list.
            Dictionary<int, int> userGearMap;
            lock (_carFactsLock) { userGearMap = BuildUserGearRedlineMap(activeStoredForRedline); }
            string redlineKey = ck + "/" + (currentSigForRedline ?? "");
            bool liveCommunityMatches = CommunityRedlineConsensusReady(redlineKey);
            // Per-gear gears are each independently support-floored by the fetch
            // assembler, and they only exist when an overall 'redline' consensus
            // row anchors the variant. So a gear can be solidly agreed even when
            // the OVERALL value is still below the support floor (drivers agree on
            // a specific gear's measured limit while their overall defaults
            // diverge). Gate the per-gear map only on the cached consensus
            // matching the live variant, NOT on the overall floor, so an accurate
            // gear still reaches the buzz. The overall value (CarFactsRedline)
            // stays gated on the overall floor.
            bool communityKeyMatches = _activeCarCommunityRedlineConsensus != null
                && _activeCarCommunityRedlineKey == redlineKey;
            if (RevLimiter != null)
            {
                RevLimiter.UserGearRedlines  = userGearMap;
                RevLimiter.CarFactsRedline   = liveCommunityMatches
                    ? (int?)_activeCarCommunityRedlineConsensus.Rpm : null;
                var commGears = communityKeyMatches ? _activeCarCommunityRedlineConsensus.Gears : null;
                RevLimiter.CommunityGearRedlines = (commGears != null && commGears.Count > 0) ? commGears : null;
                // (RevLimiter.IsElectric is set at the END of this method:
                // the pin block and layout resolution below are what decide
                // the effect's electric state, so gating here read stale
                // pre-pin data and lagged a resolve behind a pin change.)
            }

            // User engine pin (Car facts): the engine analogue of the redline
            // pin. A pinned UserEngineLayout on the stored variant wins the
            // whole cascade below by writing the effect's user slot
            // (EnginePulse.Layout); auto-detection keeps resolving underneath
            // so clearing the pin falls straight back to it. A Custom pin
            // resolves against the library; a dangling reference plays as
            // Auto (same safety net the retired preset path had).
            var pinnedVariant = FindActiveStoredVariant();
            var pinLayout = pinnedVariant?.UserEngineLayout;
            CustomEngineDef pinCustom = null;
            if (pinLayout == Effects.EngineLayout.Custom)
            {
                string pinId = pinnedVariant?.UserCustomEngineId;
                if (!string.IsNullOrEmpty(pinId) && Settings.CustomEngines != null)
                {
                    foreach (var c in Settings.CustomEngines)
                        if (string.Equals(c?.Id, pinId, StringComparison.Ordinal)) { pinCustom = c; break; }
                }
                if (pinCustom == null)
                {
                    pinLayout = null;
                    SimHub.Logging.Current.Info(
                        $"[TF4ALL] Pinned custom engine Id '{pinId}' is not in the library; "
                        + "falling back to Auto engine layout.");
                }
            }
            _activePinnedCustomEngine = pinCustom;
            EnginePulse.Layout = pinLayout ?? Effects.EngineLayout.Auto;
            EnginePulse.ActiveCustomIsElectric = pinCustom != null && pinCustom.IsElectric;
            EnginePulse.CustomPattern = pinCustom != null && !pinCustom.IsElectric
                                        && !string.IsNullOrWhiteSpace(pinCustom.Pattern)
                ? Effects.FiringPatternDb.ParseCustom(pinCustom.Pattern)
                : null;
            if (pinCustom != null && pinCustom.IsElectric)
                EnginePulse.ElectricMode = pinCustom.ElectricMode;
            else if (ActiveEngine != null)
                EnginePulse.ElectricMode = ActiveEngine.ElectricMode;

            // Community Custom: special apply path. The synthesized
            // variant carries cyl=0 + EngineConfig.Custom; the firing
            // pattern + electric flag come from the community def
            // (_activeCarCommunityConsensus.Custom). Only honored when
            // the user hasn't pinned an engine for this variant - an
            // explicit pin already drove the path above and mustn't be
            // overridden.
            bool communityCustomAvailable =
                   haveVariant
                && v.Source == CarFactSource.Community
                && v.EngineConfig == Effects.EngineConfig.Custom
                && _activeCarCommunityConsensus?.Custom != null
                && !string.IsNullOrEmpty(_activeCarCommunityConsensus.Custom.Name)
                && pinLayout == null;
            if (communityCustomAvailable)
            {
                var def = _activeCarCommunityConsensus.Custom;
                EnginePulse.AutoLayout = Effects.EngineLayout.Custom;
                EnginePulse.AutoLayoutSource = "community";
                EnginePulse.CatalogCyl = null;
                EnginePulse.ActiveCustomIsElectric = def.IsElectric;
                EnginePulse.CustomPattern = !def.IsElectric
                    && !string.IsNullOrWhiteSpace(def.Pattern)
                    ? Effects.FiringPatternDb.ParseCustom(def.Pattern)
                    : null;
                if (string.Equals(def.ElectricMode, "SILENT",
                                  StringComparison.OrdinalIgnoreCase))
                    EnginePulse.ElectricMode = ElectricCarMode.Silent;
                else
                    EnginePulse.ElectricMode = ElectricCarMode.MutedHum;
                if (logResolution)
                    SimHub.Logging.Current.Info(
                        $"[TF4ALL] Car '{carId}' resolved to community custom "
                        + $"'{def.Name}' (electric={def.IsElectric})");
                // EV awareness for the limiter: computed from the electric
                // state THIS branch just wrote (early return skips the shared
                // assignment at the end of the method).
                if (RevLimiter != null)
                    RevLimiter.IsElectric = EnginePulse != null && EnginePulse.IsElectricEffective;
                return;
            }

            bool variantUsableForLayout = haveVariant
                && v.Cylinders >= 1 && v.Cylinders <= 16;

            if (variantUsableForLayout)
            {
                EnginePulse.AutoLayout = Effects.FiringPatternDb.LayoutFromLegacy(
                    v.Cylinders, v.EngineConfig, false);
                EnginePulse.AutoLayoutSource = MapCarFactSourceToUiLabel(v.Source);
                EnginePulse.CatalogCyl = v.Cylinders;
                if (string.IsNullOrEmpty(_activeCarDisplayName)
                    && CarCylinderResolver.TryResolve(_activeGame, carId, out var ds))
                    _activeCarDisplayName = ds.DisplayName;
                if (logResolution)
                    SimHub.Logging.Current.Info(
                        $"[TF4ALL] Car '{carId}' resolved from CarFacts: "
                        + $"variant='{v.Label}', cyl={v.Cylinders}, config={v.EngineConfig}, "
                        + $"redline={(v.RedlineRpm.HasValue ? v.RedlineRpm.Value.ToString() : "-")}, "
                        + $"source={v.Source} -> layout={EnginePulse.AutoLayout}");
            }
            else if (EnginePulse.ObservedIsElectric)
            {
                // The game itself counted the cylinders of the car that is
                // actually loaded and came back with none. That is first-hand
                // truth about this car, so it outranks a catalog keyed on the
                // car's id: Forza's EV lineup is large, grows with every
                // update, and the FH6 table carries names only. Same rung as
                // RaceRoom's own EngineType below.
                EnginePulse.AutoLayout = Effects.EngineLayout.Electric;
                EnginePulse.AutoLayoutSource = "telemetry";
                EnginePulse.CatalogCyl = null;
                if (string.IsNullOrEmpty(_activeCarDisplayName)
                    && CarCylinderResolver.TryResolve(_activeGame, carId, out var evSpec))
                    _activeCarDisplayName = evSpec.DisplayName;
                if (logResolution)
                    SimHub.Logging.Current.Info(
                        $"[TF4ALL] Car '{carId}' resolved from the game's own cylinder count: "
                        + "no cylinders, so electric.");
            }
            else if (CarCylinderResolver.TryResolve(_activeGame, carId, out var carSpec))
            {
                EnginePulse.AutoLayout = Effects.FiringPatternDb.LayoutFromLegacy(
                    carSpec.Cylinders, carSpec.EngineConfig, carSpec.IsElectric);
                EnginePulse.AutoLayoutSource = carSpec.Source;
                EnginePulse.CatalogCyl = carSpec.Cylinders;
                if (string.IsNullOrEmpty(_activeCarDisplayName))
                    _activeCarDisplayName = carSpec.DisplayName;
                if (logResolution)
                    SimHub.Logging.Current.Info(
                        $"[TF4ALL] Car '{carId}' resolved: cyl={carSpec.Cylinders}, "
                        + $"electric={carSpec.IsElectric}, source={carSpec.Source}, "
                        + $"engineConfig={carSpec.EngineConfig} ({carSpec.EngineConfigSource ?? "auto"}), "
                        + $"name={carSpec.DisplayName ?? "(none)"}"
                        + $" -> layout={EnginePulse.AutoLayout}");
            }
            else if (ActiveGameIsArcade && ArcadeCarNow() != null)
            {
                // The cabinet's own car table, recovered by static analysis of the game and
                // verified against its bytes. It knows the cylinder count and both tachometer
                // faces for every car in the game, which is more than the seed catalog can offer
                // for a title it has never heard of. A rotary reports no cylinders and the firing
                // rate of a four instead, which is what the pulse actually needs.
                var ac = ArcadeCarNow();
                bool tunedFace = _arcadeMemory != null && _arcadeMemory.Last.TunedFace;
                EnginePulse.AutoLayout = Effects.FiringPatternDb.LayoutFromLegacy(
                    ac.PulseCylinderEquivalent, Effects.EngineConfig.Auto, false);
                EnginePulse.AutoLayoutSource = "the game's own car table";
                EnginePulse.CatalogCyl = ac.PulseCylinderEquivalent;
                if (RevLimiter != null) RevLimiter.CarFactsRedline = ac.Redline(tunedFace);
                if (string.IsNullOrEmpty(_activeCarDisplayName)) _activeCarDisplayName = ac.Name;
                if (logResolution)
                    SimHub.Logging.Current.Info(
                        $"[TF4ALL] Car '{carId}' resolved from the cabinet's own table: "
                        + $"{ac.Name}, {(ac.IsRotary ? "rotary, pulsing as a 4" : ac.Cylinders + " cylinders")}, "
                        + $"{ac.GearCount} gears, redline {ac.Redline(tunedFace)} of {ac.DialMax(tunedFace)} "
                        + $"({(tunedFace ? "tuned" : "stock")} face) -> layout={EnginePulse.AutoLayout}");
            }
            else if (IsR3EGame(_activeGame) && _r3eEngineType == R3EEngineElectric)
            {
                // Seed miss, but RaceRoom itself says this car is electric.
                // The sim publishes no cylinder count, so this branch can only
                // ever resolve the EV way: a car the seed has never seen (new
                // DLC) still gets silence rather than a generic six-cylinder
                // hum. Combustion and hybrid say nothing we can act on and
                // fall through to the manual path below.
                EnginePulse.AutoLayout = Effects.EngineLayout.Electric;
                EnginePulse.AutoLayoutSource = "telemetry";
                EnginePulse.CatalogCyl = null;
                if (logResolution)
                    SimHub.Logging.Current.Info(
                        $"[TF4ALL] Car '{carId}' resolved from RaceRoom's own EngineType: electric.");
            }
            else if (_telemetrySource?.ProvidesNumCylinders == true)
            {
                // Resolver missed but the active source will populate
                // NumCylinders shortly (Forza UDP). Label the source so the
                // UI doesn't briefly show "couldn't detect" between
                // car-change and first frame. AutoLayout itself stays null
                // until OnTelemetry runs.
                EnginePulse.AutoLayoutSource = "telemetry";
            }
            else if (logResolution)
            {
                SimHub.Logging.Current.Info(
                    $"[TF4ALL] Car '{carId}' not auto-resolved, user can set engine layout manually.");
            }

            // Preview the non-community auto value when community is the
            // current source AND the user might want to switch away from it.
            // Drives the "Use built-in instead" affordance label. Skipped
            // when source isn't community (no alternative needed) or no
            // concrete next-best resolves (Baked / Scanner empty + telemetry
            // pending - we don't preview "(pending)" since there's no value
            // to show).
            if (string.Equals(EnginePulse.AutoLayoutSource, "community",
                              StringComparison.OrdinalIgnoreCase))
            {
                if (TryResolveNonCommunityVariant(_activeGame, carId, out var nv)
                    && nv.Cylinders >= 1 && nv.Cylinders <= 16)
                {
                    EnginePulse.NonCommunityAutoLayout =
                        Effects.FiringPatternDb.LayoutFromLegacy(
                            nv.Cylinders, nv.EngineConfig, false);
                    EnginePulse.NonCommunityAutoLayoutSource =
                        MapCarFactSourceToUiLabel(nv.Source);
                }
                else if (BuiltinCarCylinders.TryGet(_activeGame, carId, out var rawBakeCheck)
                         && rawBakeCheck.IsElectric)
                {
                    // Electric fallback: show the EV pick under the Use-
                    // built-in instead link so the user gets the same alt
                    // option the resolver would land on if community were
                    // suppressed.
                    EnginePulse.NonCommunityAutoLayout = Effects.EngineLayout.Electric;
                    EnginePulse.NonCommunityAutoLayoutSource = "baked";
                }
            }

            // Silent auto-create/upgrade: keep the stored variant for
            // the live telemetry signature in sync. Creates a Scanner
            // row when none matches, fills MaxRpm/RedlineRpm on a
            // legacy under-specified row. No user-facing prompt; the
            // variant signature IS the identity.
            EnsureVariantForLiveSignature();
            // Stamp the cache so DispatchFrame's per-frame signature
            // compare knows what we just applied. Anything that changes
            // the live signature after this (Forza mid-session engine
            // swap; telemetry warming up enough to add a new component)
            // re-enters this method on the next frame.
            _lastAppliedVariantSignature =
                ComputeActiveCarVariantSignature(_activeGame, _activeCarId);

            // EV awareness: the limiter stays silent on EVs unless the user
            // explicitly opted in. Set LAST so it reflects the pin block and
            // the layout resolution above (setting it earlier gated on the
            // previous resolve's electric state).
            if (RevLimiter != null)
                RevLimiter.IsElectric = EnginePulse != null && EnginePulse.IsElectricEffective;
        }

        /// <summary>Auto-create or upgrade the stored EngineVariant for the
        /// active car so its (Cylinders, MaxRpm, RedlineRpm) matches what
        /// telemetry is currently reporting. Runs silently at the tail of
        /// every CarFacts resolve and after each car change. Three cases:
        ///   1. No stored variant matches the live cyl + maxRpm + redline
        ///      bands → create a new Scanner-source variant with an
        ///      auto-generated label ("4 cyl, 7400 RPM").
        ///   2. A stored variant matches on the components both sides have
        ///      AND telemetry has fields the variant doesn't → upgrade the
        ///      stored row in place (fill in MaxRpm and/or RedlineRpm).
        ///   3. A stored variant fully covers telemetry → no-op.
        /// Replaces the older "ActiveCarUnknownVariantSignature → modal
        /// prompt" flow. The variant signature is the identity; the
        /// "register" step is implicit, so no user-facing prompt fires.
        /// User can still rename / delete variants in the Manage UI.</summary>
        public void EnsureVariantForLiveSignature()
        {
            if (string.IsNullOrEmpty(_activeGame) || string.IsNullOrEmpty(_activeCarId)) return;
            bool changed;
            lock (_carFactsLock) { EnsureVariantForLiveSignatureCore_Locked(out changed); }
            if (!changed) return;
            // Persist OFF this (telemetry/data) thread; the flush serializes
            // under _carFactsLock so it can't collide with a concurrent Add.
            ScheduleCarFactsFlush();
            // Re-resolve so the just-created / upgraded variant flows
            // through PickStoredVariant and RevLimiter.CarFactsRedline.
            // Logging stays off here - it's automatic plumbing, not a
            // user action worth a line in the log.
            ResolveAndApplyCarFactsForActiveCar(_activeCarId, logResolution: false);
        }

        /// <summary>The find-or-create body of <see cref="EnsureVariantForLiveSignature"/>.
        /// ASSUMES <c>_carFactsLock</c> is already held. Returns the stored variant
        /// to operate on (matched, upgraded, or freshly created) and sets
        /// <paramref name="changed"/> when the CarFacts list was actually mutated.
        /// Does NOT schedule a flush or re-resolve - the caller does that once,
        /// after its own mutation, OUTSIDE the lock.
        ///
        /// Pulled out so the redline / per-gear CRUD can do find-or-create AND
        /// their own write under a SINGLE lock acquisition. The old pattern
        /// (FindActiveStoredVariant, then EnsureVariantForLiveSignature, then
        /// FindActiveStoredVariant again, then mutate) spanned three separate lock
        /// windows, so a concurrent telemetry-thread upgrade could land between the
        /// create and the re-find and the user's write could target a stale row or
        /// be lost. Atomic now.</summary>
        private EngineVariant EnsureVariantForLiveSignatureCore_Locked(out bool changed)
        {
            changed = false;
            if (Settings == null) return null;
            if (string.IsNullOrEmpty(_activeGame) || string.IsNullOrEmpty(_activeCarId)) return null;

            int telMaxBand = BandMaxRpm(EnginePulse?.ObservedMaxRpm ?? 0);
            int telRedBand = BandRpm(EnginePulse?.ObservedRedlineRpm ?? 0);
            // Cyl: telemetry-direct first, then resolver/bake fallback.
            // Forza UDP populates ObservedCyl; SimHub-fallback games leave
            // it null but the resolver fills CatalogCyl from the bake.
            int? telCyl = ActiveCarEffectiveCyl();

            // No discriminator at all (engine off / pre-telemetry). We can't
            // safely create a new row, but an existing variant may still be
            // the one we're on (single variant, pinned selection, or last-used).
            // Defer to the read-only finder so an edit targets that row rather
            // than failing. changed stays false -> no spurious create/flush.
            // (FindActiveStoredVariant re-enters _carFactsLock, which Monitor
            // allows recursively on the same thread.)
            //
            // A cyl count on its own IS enough to create: it's a real
            // discriminator (FindActiveStoredVariant and PickStoredVariant both
            // match on it), and the row starts under-specified so the upgrade
            // branch below fills MaxRpm/RedlineRpm in place the moment they
            // appear. Requiring a rev range here was a dead end for any game
            // that gives us cylinders but no MaxRpm: no row could ever be
            // created, so the cyl-only signature matched nothing and every
            // redline / engine pin was refused forever.
            if (telMaxBand <= 0 && telRedBand <= 0 && !telCyl.HasValue)
                return FindActiveStoredVariant();

            string key = _activeGame + "/" + _activeCarId;

            // Telemetry source-of-truth at observation time. These are
            // what go into the row when we create or upgrade.
            int telMaxRpm = telMaxBand > 0 ? (int)Math.Round(EnginePulse.ObservedMaxRpm) : 0;
            int telRedRpm = telRedBand > 0 ? (int)Math.Round(EnginePulse.ObservedRedlineRpm) : 0;

            if (Settings.CarFacts == null)
                Settings.CarFacts = new Dictionary<string, CarFactsBundle>();
            if (!Settings.CarFacts.TryGetValue(key, out var bundle) || bundle == null)
            {
                bundle = new CarFactsBundle();
                Settings.CarFacts[key] = bundle;
            }
            if (bundle.EngineVariants == null)
                bundle.EngineVariants = new List<EngineVariant>();

            // Look for a stored variant compatible with live telemetry.
            // Compatible = cyl agrees (or either side has 0/unknown) +
            // any field present on both sides shares the same band. A
            // variant with no MaxRpm/RedlineRpm is "under-specified" and
            // matches any telemetry — we'll upgrade it below by filling
            // in the missing components. 0 / null cyl acts as a wildcard
            // so SimHub-fallback games (where bake + telemetry might
            // not have agreed at one point) still match cleanly.
            EngineVariant match = null;
            for (int i = 0; i < bundle.EngineVariants.Count; i++)
            {
                var v = bundle.EngineVariants[i];
                if (!VariantMatchesSignature(v, telCyl, telMaxBand, telRedBand)) continue;
                match = v;
                break;
            }

            if (match != null)
            {
                // Upgrade in place when telemetry brings new info that
                // the stored row doesn't have. Once filled, this row
                // will discriminate against future engine swaps that
                // change the now-known field.
                if (match.Cylinders < 1 && telCyl.HasValue)
                {
                    match.Cylinders = telCyl.Value;
                    changed = true;
                }
                if (!match.MaxRpm.HasValue && telMaxBand > 0)
                {
                    match.MaxRpm = telMaxRpm;
                    changed = true;
                }
                if (!match.RedlineRpm.HasValue && telRedBand > 0)
                {
                    match.RedlineRpm = telRedRpm;
                    changed = true;
                }
                if (changed)
                {
                    // Refresh auto-label only when the existing label
                    // looks auto-generated (matches the AutoLabel
                    // pattern). User-renamed labels are preserved.
                    if (IsAutoVariantLabel(match.Label))
                        match.Label = BuildAutoVariantLabel(match.Cylinders,
                                                            match.MaxRpm,
                                                            match.RedlineRpm,
                                                            EnginePulse?.ObservedIsElectric == true);
                }
                return match;
            }

            // No compatible variant: create one. Source = Scanner
            // (auto-observed, not user-confirmed). EngineConfig
            // stays Auto: the EnginePulse "Layout" picker is the
            // user-facing surface for layout overrides, separate
            // from variant identity. Cylinders = 0 (unknown) when
            // neither telemetry nor bake gave us a count - the
            // signature still discriminates via MaxRpm/RedlineRpm.
            var fresh = new EngineVariant
            {
                Id            = Guid.NewGuid().ToString("N"),
                Cylinders     = telCyl ?? 0,
                MaxRpm        = telMaxBand > 0 ? (int?)telMaxRpm : null,
                RedlineRpm    = telRedBand > 0 ? (int?)telRedRpm : null,
                EngineConfig  = EngineConfig.Auto,
                Source        = CarFactSource.Scanner,
                Confirmations = 0,
            };
            fresh.Label = BuildAutoVariantLabel(fresh.Cylinders,
                                               fresh.MaxRpm,
                                               fresh.RedlineRpm,
                                               EnginePulse?.ObservedIsElectric == true);
            bundle.EngineVariants.Add(fresh);
            changed = true;
            return fresh;
        }

        // =====================================================================
        // Per-variant user redline (Auto-mode redline overrides).
        // The redline lives in the CarFacts layer, on the EngineVariant row
        // matching the live signature, so it travels per variant (a tune that
        // changes MaxRpm is a different variant) and wins over the community
        // consensus for that variant only.
        // =====================================================================

        // The stored variant row matching the live signature, or null. Mirrors
        // EnsureVariantForLiveSignature's match criteria (cyl + maxrpm + redline
        // bands, absent fields acting as wildcards). Read-only: never creates.
        private EngineVariant FindActiveStoredVariant()
        {
            if (Settings?.CarFacts == null
                || string.IsNullOrEmpty(_activeGame) || string.IsNullOrEmpty(_activeCarId))
                return null;
            string key = _activeGame + "/" + _activeCarId;
            lock (_carFactsLock)
            {
                if (!Settings.CarFacts.TryGetValue(key, out var bundle)
                    || bundle?.EngineVariants == null || bundle.EngineVariants.Count == 0) return null;
                int telMaxBand = BandMaxRpm(EnginePulse?.ObservedMaxRpm ?? 0);
                int telRedBand = BandRpm(EnginePulse?.ObservedRedlineRpm ?? 0);
                int? telCyl = ActiveCarEffectiveCyl();
                bool haveDiscriminator = telCyl.HasValue || telMaxBand > 0 || telRedBand > 0;

                if (!haveDiscriminator)
                {
                    // Empty-signature window (engine off / pre-telemetry). Don't
                    // pin to an arbitrary first row (PickStoredVariant gates the
                    // same way). One variant is unambiguous; otherwise fall back
                    // to the user's pinned selection, then the LAST variant we
                    // were actually on, then give up so the caller refuses to
                    // edit until telemetry (or a selection) disambiguates.
                    if (bundle.EngineVariants.Count == 1) return bundle.EngineVariants[0];
                    string wantId = null;
                    if (Settings.CarFactsSelection != null
                        && Settings.CarFactsSelection.TryGetValue(key, out var selId)
                        && !string.IsNullOrEmpty(selId))
                        wantId = selId;
                    else if (_lastActiveVariantIdByCar.TryGetValue(key, out var lastId))
                        wantId = lastId;
                    if (!string.IsNullOrEmpty(wantId))
                        for (int i = 0; i < bundle.EngineVariants.Count; i++)
                            if (bundle.EngineVariants[i]?.Id == wantId) return bundle.EngineVariants[i];
                    return null;
                }

                for (int i = 0; i < bundle.EngineVariants.Count; i++)
                {
                    var v = bundle.EngineVariants[i];
                    if (!VariantMatchesSignature(v, telCyl, telMaxBand, telRedBand)) continue;
                    _lastActiveVariantIdByCar[key] = v.Id;   // remember "last used" for the empty-signature fallback
                    return v;
                }
                return null;
            }
        }

        /// <summary>The user's saved per-variant redline for the active variant,
        /// or null when they haven't pinned one.</summary>
        public int? GetActiveVariantUserRedline() => FindActiveStoredVariant()?.UserRedlineRpm;

        /// <summary>The community redline consensus for the active variant
        /// signature, or null when none / out of range.</summary>
        public int? GetActiveVariantCommunityRedline()
        {
            if (string.IsNullOrEmpty(_activeGame) || string.IsNullOrEmpty(_activeCarId)) return null;
            string sig = ComputeActiveCarVariantSignature(_activeGame, _activeCarId);
            string key = _activeGame + "/" + _activeCarId + "/" + (sig ?? "");
            return CommunityRedlineConsensusReady(key) ? (int?)_activeCarCommunityRedlineConsensus.Rpm : null;
        }

        /// <summary>True when the active variant's community redline is CONFIRMED
        /// (backed by enough distinct drivers), not just usable. Single source of
        /// truth for the confirmed-vs-unconfirmed boundary so the UI never restates
        /// the threshold.</summary>
        internal bool IsActiveCommunityRedlineConfirmed()
        {
            var c = GetActiveVariantCommunityConsensus();
            return c != null && c.SupportingSubmissions >= CommunityRedlineConfirmedSupport;
        }

        /// <summary>The active variant's community redline ONLY when it is confirmed
        /// (>= the confirmed support floor); null for a lone/unconfirmed value. Use
        /// this where we tell the user "the community says X" so a single (often
        /// self-) submission is never attributed to the community.</summary>
        internal int? GetActiveVariantConfirmedCommunityRedline()
        {
            var c = GetActiveVariantCommunityConsensus();
            if (c == null || c.SupportingSubmissions < CommunityRedlineConfirmedSupport) return null;
            return (c.Rpm >= 500 && c.Rpm <= 25000) ? (int?)c.Rpm : null;
        }

        // Two tiers of community-redline support:
        //   USABLE (>= 1): a single submission is a usable fact - better than the
        //     0.85 guess - so the cascade applies it ("first submission = fact").
        //   CONFIRMED (>= 2): enough distinct drivers agree that we present it AS
        //     "the community" (vs "unconfirmed") and stop nudging for confirmation.
        // A lone submission is still USED, just labelled "unconfirmed" rather than
        // claimed as established consensus (which would mislabel one driver's guess
        // - the original concern). The user can always set their own over it.
        private const int CommunityRedlineMinSupport = 1;       // value usable in the cascade
        private const int CommunityRedlineConfirmedSupport = 2; // counts as confirmed "community" consensus

        // True when the cached community redline matches the given cache key, is in
        // range, AND is at least USABLE (>= 1 supporter) - i.e. fit to drive the
        // cascade. (Confirmed-vs-unconfirmed labelling uses the count directly.)
        private bool CommunityRedlineConsensusReady(string expectedKey)
        {
            var c = _activeCarCommunityRedlineConsensus;
            return c != null
                && _activeCarCommunityRedlineKey == expectedKey
                && c.Rpm >= 500 && c.Rpm <= 25000
                && c.SupportingSubmissions >= CommunityRedlineMinSupport;
        }

        // (The live redline slider draft, PreviewRedlineRpm, was removed with
        // the car-facts centralization: the Car facts redline box commits via
        // SaveActiveVariantUserRedline directly, no draft state.)

        /// <summary>Commit the given value as THIS variant's user redline. Ensures
        /// a stored variant row exists for the live signature, stamps it,
        /// persists, clears the draft, and re-resolves. Returns the saved value,
        /// or null when no variant signature is available yet (no telemetry).</summary>
        public int? SaveActiveVariantUserRedline(int rpm)
        {
            if (Settings == null || rpm < 500 || rpm > 25000) return null;
            if (string.IsNullOrEmpty(_activeGame) || string.IsNullOrEmpty(_activeCarId)) return null;
            // Find-or-create AND write under one lock so a concurrent telemetry
            // upgrade can't slip in between and lose the pin.
            lock (_carFactsLock)
            {
                var variant = EnsureVariantForLiveSignatureCore_Locked(out _);
                if (variant == null) return null;  // no discriminator observed yet
                variant.UserRedlineRpm = rpm;
                variant.AdoptedCommunityRedlineRpm = null;   // a deliberate pin supersedes any adopted community value
            }
            ScheduleCarFactsFlush();
            ResolveAndApplyCarFactsForActiveCar(_activeCarId, logResolution: false);
            return rpm;
        }

        // The library CustomEngineDef the active variant's engine pin resolves
        // to, set by ResolveAndApplyCarFactsForActiveCar. Read by
        // ApplyEngineSettings so a feel-slider apply can't clobber an electric
        // custom's ElectricMode override. null = no custom pinned.
        private CustomEngineDef _activePinnedCustomEngine;

        /// <summary>The user's saved per-variant engine pin for the active
        /// variant, or (null, "") when they haven't pinned one.</summary>
        public (Effects.EngineLayout? layout, string customId) GetActiveVariantUserEngine()
        {
            var v = FindActiveStoredVariant();
            return (v?.UserEngineLayout, v?.UserCustomEngineId ?? "");
        }

        /// <summary>Commit the given engine type as THIS variant's user pin
        /// (the engine analogue of SaveActiveVariantUserRedline). Auto / null
        /// clears the pin so the cascade (community / telemetry / heuristic)
        /// takes over again; customId is only meaningful with Layout ==
        /// Custom. Persists and re-resolves. Returns false when no variant
        /// signature is available yet (no telemetry observed).</summary>
        public bool SaveActiveVariantUserEngine(Effects.EngineLayout? layout, string customId)
        {
            if (Settings == null) return false;
            if (string.IsNullOrEmpty(_activeGame) || string.IsNullOrEmpty(_activeCarId)) return false;
            if (layout == Effects.EngineLayout.Auto) layout = null;   // Auto = no pin
            lock (_carFactsLock)
            {
                var variant = EnsureVariantForLiveSignatureCore_Locked(out _);
                if (variant == null) return false;  // no discriminator observed yet
                variant.UserEngineLayout   = layout;
                variant.UserCustomEngineId = layout == Effects.EngineLayout.Custom ? (customId ?? "") : "";
            }
            ScheduleCarFactsFlush();
            ResolveAndApplyCarFactsForActiveCar(_activeCarId, logResolution: false);
            return true;
        }

        /// <summary>The user's engine pin for a SPECIFIC stored variant of the
        /// active car, by variant Id (the Manage-variants modal edits any
        /// variant, not just the one currently driven). (null, "") = no pin
        /// or unknown id.</summary>
        public (Effects.EngineLayout? layout, string customId) GetActiveCarVariantUserEngineById(string variantId)
        {
            if (string.IsNullOrEmpty(_activeGame) || string.IsNullOrEmpty(_activeCarId)) return (null, "");
            if (string.IsNullOrEmpty(variantId) || Settings?.CarFacts == null) return (null, "");
            string key = _activeGame + "/" + _activeCarId;
            // Dictionary lookup INSIDE the lock: the telemetry thread's variant
            // auto-create adds CarFacts keys under it, and an unlocked
            // TryGetValue can misread mid-rehash.
            lock (_carFactsLock)
            {
                if (!Settings.CarFacts.TryGetValue(key, out var bundle) || bundle?.EngineVariants == null) return (null, "");
                foreach (var v in bundle.EngineVariants)
                    if (v != null && v.Id == variantId)
                        return (v.UserEngineLayout, v.UserCustomEngineId ?? "");
            }
            return (null, "");
        }

        /// <summary>Commit an engine pin on a SPECIFIC stored variant of the
        /// active car, by variant Id (Manage-variants modal). Auto / null
        /// clears the pin. Persists and re-resolves so a pin on the live
        /// variant applies immediately; a pin on another variant applies
        /// when that variant next matches telemetry.</summary>
        public bool SaveActiveCarVariantUserEngineById(string variantId, Effects.EngineLayout? layout, string customId)
        {
            if (string.IsNullOrEmpty(_activeGame) || string.IsNullOrEmpty(_activeCarId)) return false;
            if (string.IsNullOrEmpty(variantId) || Settings?.CarFacts == null) return false;
            if (layout == Effects.EngineLayout.Auto) layout = null;   // Auto = no pin
            string key = _activeGame + "/" + _activeCarId;
            bool saved = false;
            // Dictionary lookup INSIDE the lock (see GetActiveCarVariantUserEngineById).
            lock (_carFactsLock)
            {
                if (!Settings.CarFacts.TryGetValue(key, out var bundle) || bundle?.EngineVariants == null) return false;
                foreach (var v in bundle.EngineVariants)
                {
                    if (v == null || v.Id != variantId) continue;
                    v.UserEngineLayout   = layout;
                    v.UserCustomEngineId = layout == Effects.EngineLayout.Custom ? (customId ?? "") : "";
                    saved = true;
                    break;
                }
            }
            if (!saved) return false;
            ScheduleCarFactsFlush();
            ResolveAndApplyCarFactsForActiveCar(_activeCarId, logResolution: false);
            return true;
        }

        /// <summary>Pin, or clear, the redline on ONE listed variant rather than
        /// the one being driven. Same shape as SaveActiveCarVariantUserEngineById,
        /// and the same reason for existing: the variants window lists rows the
        /// driver is not currently in, and SaveActiveVariantUserRedline can only
        /// reach the live signature.
        ///
        /// A null rpm clears the pin and lets resolution decide again. It does
        /// NOT touch AdoptedCommunityRedlineRpm, so clearing falls back to the
        /// community value where there is one, which is what "no longer my own
        /// number" should mean. Pinning does clear it, matching the live setter:
        /// a deliberate pin supersedes an adopted value.</summary>
        public bool SaveActiveCarVariantUserRedlineById(string variantId, int? rpm)
        {
            if (string.IsNullOrEmpty(_activeGame) || string.IsNullOrEmpty(_activeCarId)) return false;
            if (string.IsNullOrEmpty(variantId) || Settings?.CarFacts == null) return false;
            // Same range the live setter accepts, so the two cannot disagree
            // about what counts as a plausible redline.
            if (rpm.HasValue && (rpm.Value < 500 || rpm.Value > 25000)) return false;
            string key = _activeGame + "/" + _activeCarId;
            bool saved = false;
            lock (_carFactsLock)
            {
                if (!Settings.CarFacts.TryGetValue(key, out var bundle) || bundle?.EngineVariants == null) return false;
                foreach (var v in bundle.EngineVariants)
                {
                    if (v == null || v.Id != variantId) continue;
                    v.UserRedlineRpm = rpm;
                    if (rpm.HasValue) v.AdoptedCommunityRedlineRpm = null;
                    saved = true;
                    break;
                }
            }
            if (!saved) return false;
            ScheduleCarFactsFlush();
            ResolveAndApplyCarFactsForActiveCar(_activeCarId, logResolution: false);
            return true;
        }

        /// <summary>Re-run car-facts resolution for the active car. Public
        /// wrapper for UI paths that change resolution inputs without going
        /// through a pin save (e.g. editing a custom engine's pattern).</summary>
        public void ReresolveActiveCarFacts()
        {
            if (!string.IsNullOrEmpty(_activeCarId))
                ResolveAndApplyCarFactsForActiveCar(_activeCarId, logResolution: false);
        }

        // One-time relocation of per-car engine picks (2026-07 engine
        // centralization). For every cached CarOverride whose EnginePulse
        // carries an explicit engine choice (after folding the two pre-2026
        // legacy shapes), pin every variant of every CarFacts bundle for that
        // carId that doesn't already carry a pin. CarOverrides is keyed by
        // carId alone (game-agnostic, exactly as the old apply path was), so
        // all games' bundles for that carId receive the pin - a faithful
        // translation of the old behavior. Cars with a pick but no facts
        // bundle yet lose the pick (auto-detect takes over on next drive).
        private void MigrateEngineChoicesToCarFacts()
        {
            if (Settings?.CarOverrides == null || Settings.CarFacts == null) return;
            int pinned = 0;
            foreach (var kv in Settings.CarOverrides)
            {
                var s = kv.Value?.EnginePulse;
                if (s == null) continue;

                // Fold the pre-flat-enum shape (Cylinders + EngineConfig).
                var layout = s.Layout;
                if (layout == Effects.EngineLayout.Auto
                    && (s.Cylinders != 0 || s.EngineConfig != Effects.EngineConfig.Auto))
                    layout = Effects.FiringPatternDb.LayoutFromLegacy(s.Cylinders, s.EngineConfig, false);

                // Fold the pre-library inline custom pattern into a library def.
                string customId = s.CustomEngineId ?? "";
                if (layout == Effects.EngineLayout.Custom && string.IsNullOrEmpty(customId)
                    && !string.IsNullOrWhiteSpace(s.CustomFiringPattern))
                {
                    var def = new CustomEngineDef
                    {
                        Id         = Guid.NewGuid().ToString("N"),
                        Name       = string.IsNullOrWhiteSpace(s.CustomFiringPatternName)
                                        ? "Imported custom" : s.CustomFiringPatternName.Trim(),
                        IsElectric = false,
                        Pattern    = s.CustomFiringPattern,
                    };
                    if (Settings.CustomEngines == null)
                        Settings.CustomEngines = new System.Collections.Generic.List<CustomEngineDef>();
                    Settings.CustomEngines.Add(def);
                    customId = def.Id;
                }
                if (layout == Effects.EngineLayout.Auto) continue;
                if (layout == Effects.EngineLayout.Custom && string.IsNullOrEmpty(customId)) continue;

                string carId = kv.Key;
                if (string.IsNullOrEmpty(carId)) continue;
                lock (_carFactsLock)
                {
                    foreach (var fb in Settings.CarFacts)
                    {
                        if (fb.Value?.EngineVariants == null) continue;
                        if (!fb.Key.EndsWith("/" + carId, StringComparison.Ordinal)) continue;
                        foreach (var variant in fb.Value.EngineVariants)
                        {
                            if (variant == null || variant.UserEngineLayout != null) continue;
                            variant.UserEngineLayout   = layout;
                            variant.UserCustomEngineId = layout == Effects.EngineLayout.Custom ? customId : "";
                            pinned++;
                        }
                    }
                }
            }
            if (pinned > 0)
                SimHub.Logging.Current.Info(
                    $"[TF4ALL] Engine-choice migration: pinned {pinned} variant(s) from per-car presets.");
        }

        // One-time cleanup after the engine relocation: a per-car override
        // whose ONLY content was the engine pick does nothing anymore (the
        // pick lives in the variant pin), but its EnginePulse section kept
        // the "overridden" Engine badge lit and froze feel against future
        // preset edits. Drop the section when: the entry carried a pick,
        // every OTHER section is null, the feel fields equal the current
        // global (Eq ignores the legacy engine fields), and the entry has no
        // community share identity (shared bodies keep their exact content).
        private void PruneEngineOnlyCarOverrides()
        {
            int pruned = 0;
            foreach (var carKv in GetAllCarPresets())
            {
                foreach (var pKv in carKv.Value)
                {
                    var entry = pKv.Value;
                    if (entry == null || entry.IsBuiltin || entry.Override == null) continue;
                    var ov = entry.Override;
                    if (ov.EnginePulse == null) continue;
                    if (!string.IsNullOrEmpty(ov.CommunitySourceId)
                        || !string.IsNullOrEmpty(ov.CommunityUploadedById)) continue;
                    bool hadPick = ov.EnginePulse.Layout != Effects.EngineLayout.Auto
                        || !string.IsNullOrEmpty(ov.EnginePulse.CustomEngineId)
                        || ov.EnginePulse.Cylinders != 0
                        || ov.EnginePulse.EngineConfig != Effects.EngineConfig.Auto;
                    if (!hadPick) continue;
                    bool othersNull =
                           ov.RoadBumps == null && ov.TractionLoss == null && ov.GearShift == null
                        && ov.AbsClick == null && ov.PitLimiter == null && ov.Drs == null
                        && ov.Collision == null && ov.RevLimiter == null && ov.AxleSlip == null
                        && ov.KerbThump == null && ov.LockupJudder == null && ov.AudioCapture == null
                        && ov.Airborne == null && ov.ImplementThud == null;
                    if (!othersNull) continue;
                    if (!Eq(ov.EnginePulse, Settings.EnginePulse)) continue;   // user also tuned feel: keep
                    ov.EnginePulse = null;   // same instance as the CarOverrides cache entry
                    try
                    {
                        _carStore?.Save(entry.CarId, entry.PresetName, entry.GameName, ov);
                        pruned++;
                    }
                    catch (Exception ex)
                    {
                        SimHub.Logging.Current.Warn(
                            $"[TF4ALL] Engine-only override prune of '{entry.CarId}/{entry.PresetName}' failed: {ex.Message}");
                    }
                }
            }
            if (pruned > 0)
                SimHub.Logging.Current.Info(
                    $"[TF4ALL] Pruned {pruned} engine-only car override section(s).");
        }

        // NOTE: "adopt community redline" was retired (in Auto the cascade already
        // applies the community value directly, so copying it into a local pin was
        // ceremony), and the Confirm banner that replaced it was retired too with
        // the set-not-share framing pass: agreement now accrues from other
        // drivers' auto-submitted saves. The variant model's
        // DeclinedCommunityRedlineSig field is vestigial (nothing reads or
        // writes it anymore); kept so existing CarFacts files round-trip.

        /// <summary>The value currently pinned for the active variant: the user's
        /// own redline, else a previously-adopted community value. Drives the
        /// "community changed - switch?" prompt (it fires when live community
        /// differs from this).</summary>
        public int? GetActiveVariantPinnedRedline()
        {
            var v = FindActiveStoredVariant();
            return v?.UserRedlineRpm ?? v?.AdoptedCommunityRedlineRpm;
        }

        // Combine the variant's default (gear 0 = UserRedlineRpm, or a back-compat
        // adopted value) and per-gear overrides (1..N) into one gear->rpm map for
        // the rev-limiter effect. null when the user has set nothing.
        private static Dictionary<int, int> BuildUserGearRedlineMap(EngineVariant v)
        {
            if (v == null) return null;
            Dictionary<int, int> map = null;
            int? gear0 = v.UserRedlineRpm ?? v.AdoptedCommunityRedlineRpm;
            if (gear0.HasValue && gear0.Value >= 500 && gear0.Value <= 25000)
                (map = map ?? new Dictionary<int, int>())[0] = gear0.Value;
            if (v.PerGearRedlines != null)
                for (int i = 0; i < v.PerGearRedlines.Count; i++)
                {
                    var gr = v.PerGearRedlines[i];
                    if (gr != null && gr.Gear >= 1 && gr.Gear <= 16 && gr.Rpm >= 500 && gr.Rpm <= 25000)
                        (map = map ?? new Dictionary<int, int>())[gr.Gear] = gr.Rpm;
                }
            return map;
        }

        /// <summary>The active variant's per-gear redline overrides (gears 1..N),
        /// sorted ascending. The default (gear 0) is the single UserRedlineRpm and
        /// is edited via the existing redline control, not this list.</summary>
        public IReadOnlyList<GearRedline> GetActiveVariantPerGearRedlines()
        {
            var outList = new List<GearRedline>();
            var v = FindActiveStoredVariant();
            lock (_carFactsLock)
            {
                if (v?.PerGearRedlines != null)
                    for (int i = 0; i < v.PerGearRedlines.Count; i++)
                    {
                        var gr = v.PerGearRedlines[i];
                        if (gr != null && gr.Gear >= 1) outList.Add(new GearRedline { Gear = gr.Gear, Rpm = gr.Rpm });
                    }
            }
            outList.Sort((a, b) => a.Gear.CompareTo(b.Gear));
            return outList;
        }

        /// <summary>Set (or update) a per-gear redline override (gear 1..N).</summary>
        public bool SetActiveVariantPerGearRedline(int gear, int rpm)
        {
            if (gear < 1 || gear > 16 || rpm < 500 || rpm > 25000) return false;
            if (string.IsNullOrEmpty(_activeGame) || string.IsNullOrEmpty(_activeCarId)) return false;
            // Find-or-create AND write under one lock (see SaveActiveVariantUserRedline).
            lock (_carFactsLock)
            {
                var variant = EnsureVariantForLiveSignatureCore_Locked(out _);
                if (variant == null) return false;
                if (variant.PerGearRedlines == null) variant.PerGearRedlines = new List<GearRedline>();
                var existing = variant.PerGearRedlines.Find(g => g != null && g.Gear == gear);
                if (existing != null) existing.Rpm = rpm;
                else variant.PerGearRedlines.Add(new GearRedline { Gear = gear, Rpm = rpm });
            }
            ScheduleCarFactsFlush();
            ResolveAndApplyCarFactsForActiveCar(_activeCarId, logResolution: false);
            return true;
        }

        /// <summary>Remove a per-gear redline override (gear falls back to the default).</summary>
        public bool RemoveActiveVariantPerGearRedline(int gear)
        {
            bool removed;
            lock (_carFactsLock)
            {
                var variant = FindActiveStoredVariant();   // reentrant lock; find + remove are atomic together
                if (variant?.PerGearRedlines == null) return false;
                removed = variant.PerGearRedlines.RemoveAll(g => g != null && g.Gear == gear) > 0;
            }
            if (!removed) return false;
            ScheduleCarFactsFlush();
            ResolveAndApplyCarFactsForActiveCar(_activeCarId, logResolution: false);
            return true;
        }

        /// <summary>Append the next per-gear override row, seeded from the current
        /// effective redline. Returns the new gear number, or 0 if none could be
        /// added (no variant yet, or already at 16 gears).</summary>
        public int AddActiveVariantGear()
        {
            if (string.IsNullOrEmpty(_activeGame) || string.IsNullOrEmpty(_activeCarId)) return 0;
            // Snapshot the cross-thread effective-redline once for the seed.
            int? seedSrc = RevLimiter?.EffectiveRedlineRpm;
            int nextGear;
            // Find-or-create AND append under one lock (see SaveActiveVariantUserRedline).
            lock (_carFactsLock)
            {
                var variant = EnsureVariantForLiveSignatureCore_Locked(out _);
                if (variant == null) return 0;
                if (variant.PerGearRedlines == null) variant.PerGearRedlines = new List<GearRedline>();
                nextGear = 1;
                for (int i = 0; i < variant.PerGearRedlines.Count; i++)
                    if (variant.PerGearRedlines[i] != null && variant.PerGearRedlines[i].Gear >= nextGear)
                        nextGear = variant.PerGearRedlines[i].Gear + 1;
                if (nextGear > 16) return 0;
                int seed = variant.UserRedlineRpm ?? seedSrc ?? 7000;
                if (seed < 500 || seed > 25000) seed = 7000;
                variant.PerGearRedlines.Add(new GearRedline { Gear = nextGear, Rpm = seed });
            }
            ScheduleCarFactsFlush();
            ResolveAndApplyCarFactsForActiveCar(_activeCarId, logResolution: false);
            return nextGear;
        }

        /// <summary>The full community redline consensus for the active variant
        /// (overall + per-gear), or null. Used by adopt to copy the whole profile.</summary>
        internal RedlineConsensus GetActiveVariantCommunityConsensus()
        {
            if (string.IsNullOrEmpty(_activeGame) || string.IsNullOrEmpty(_activeCarId)) return null;
            string sig = ComputeActiveCarVariantSignature(_activeGame, _activeCarId);
            string key = _activeGame + "/" + _activeCarId + "/" + (sig ?? "");
            // Gate on the support floor so adopt copies a real consensus, never a
            // single (often self-) submission reflected back by the server.
            return CommunityRedlineConsensusReady(key) ? _activeCarCommunityRedlineConsensus : null;
        }

        /// <summary>The variant we're effectively on: the stored row matching the
        /// live signature, else the resolver's pick (community-synth / baked).</summary>
        public EngineVariant GetActiveResolvedVariant()
        {
            var stored = FindActiveStoredVariant();
            if (stored != null) return stored;
            if (!string.IsNullOrEmpty(_activeGame) && !string.IsNullOrEmpty(_activeCarId)
                && TryResolveActiveVariant(_activeGame, _activeCarId, out var v))
                return v;
            return null;
        }

        /// <summary>At-a-glance facts for the active car, for the Car Facts
        /// summary panel. Read-only snapshot; the panel formats it.</summary>
        public sealed class CarFactsSummary
        {
            public bool HasCar;
            public string CarName;
            public string CommunityCarName;     // non-null only when it differs from CarName
            public bool HasVariant;
            public int Cylinders;               // 0 = unknown
            public string EngineTypeDisplay;    // resolved layout: "V8" / "Inline 6" / "Rotary"; null if unknown
            public bool EngineTypeIsUserOverride; // the user pinned a layout in Car facts (variant UserEngineLayout)
            public string EngineTypeProvenance;   // "user" | "community" | "game" | "auto"
            public int? MaxRpm;                 // the rev ceiling that defines this variant / tune
            public string VariantLabel;
            public CarFactSource VariantSource;
            public int? EffectiveRedline;       // the value the buzz fires at
            public string RedlineSource;        // "user" | "community" | "game" | "estimated" | "derived" | "none"
            public bool HasUserRedline;         // the user pinned one for this variant
            public int? UserRedline;            // the exact pinned value (shown precisely, not the stale resolved one)
            public int? CommunityRedline;       // consensus for this variant (for "use community")
            public string ActiveVariantId;      // stored variant the redline fields came from; null in the unresolved window
            public int PerGearOverrideCount;    // per-gear overrides on that variant (drives the editor auto-show)
        }

        public CarFactsSummary GetActiveCarFactsSummary()
        {
            var s = new CarFactsSummary();
            if (string.IsNullOrEmpty(_activeCarId)) return s;   // HasCar stays false
            s.HasCar = true;
            // Resolve the name from the stored facts / catalog for this
            // (game, carId) rather than the live-telemetry display-name cache,
            // so it's populated even for a car entered via offline edit (which
            // never went through the live car-load resolver).
            s.CarName = ResolveCarHumanName(_activeGame, _activeCarId)
                        ?? ActiveCarDisplayName ?? "";
            s.CommunityCarName = ActiveCarCommunityDisplayName;

            var v = GetActiveResolvedVariant();
            if (v != null)
            {
                s.HasVariant = true;
                s.VariantLabel = string.IsNullOrEmpty(v.Label) ? "(unnamed)" : v.Label;
                s.VariantSource = v.Source;
                s.Cylinders = v.Cylinders;
            }
            if (s.Cylinders < 1)
            {
                int? c = ActiveCarEffectiveCyl();
                if (c.HasValue && c.Value >= 1) s.Cylinders = c.Value;
            }

            // Engine TYPE = the resolved firing layout (V8 / Inline 6 / Rotary),
            // not the variant's auto-label. This is what auto-detection actually
            // landed on even when the picker shows "Auto", so the user can see
            // it and tell whether it's wrong.
            var layout = EnginePulse != null ? EnginePulse.EffectiveLayout : Effects.EngineLayout.Auto;
            if (layout != Effects.EngineLayout.Auto)
                s.EngineTypeDisplay = Effects.FiringPatternDb.LayoutDisplayName(layout);

            // "User" = a Car facts pin on the active variant (the preset's
            // Layout field is legacy since the 2026-07 centralization).
            s.EngineTypeIsUserOverride = FindActiveStoredVariant()?.UserEngineLayout != null;
            if (s.EngineTypeIsUserOverride) s.EngineTypeProvenance = "user";
            else
            {
                string als = EnginePulse?.AutoLayoutSource;   // "community"/"telemetry"/"baked"/"cache"/...
                if (string.Equals(als, "community", StringComparison.OrdinalIgnoreCase)) s.EngineTypeProvenance = "community";
                else if (string.Equals(als, "telemetry", StringComparison.OrdinalIgnoreCase)) s.EngineTypeProvenance = "game";
                else s.EngineTypeProvenance = "auto";
            }

            // Prefer the LIVE rev ceiling so a tune change shows immediately and
            // the user can tell what the plugin is currently tracking; fall back
            // to the variant's captured value only when telemetry isn't live.
            double liveMax = EnginePulse?.ObservedMaxRpm ?? 0;
            if (liveMax >= 500) s.MaxRpm = (int)Math.Round(liveMax);
            else if (v != null && v.MaxRpm.HasValue && v.MaxRpm.Value > 0) s.MaxRpm = v.MaxRpm.Value;

            s.EffectiveRedline  = RevLimiter?.EffectiveRedlineRpm;
            var storedForRedline = FindActiveStoredVariant();
            // Treat a legacy adopted value (written by the retired adopt flow, now
            // never set) as the user's own pin - the buzz already does, via
            // BuildUserGearRedlineMap, so the label / Share must agree.
            int? userRl    = storedForRedline?.UserRedlineRpm ?? storedForRedline?.AdoptedCommunityRedlineRpm;
            s.UserRedline       = userRl;
            // "HasUserRedline" = something genuinely THEIRS to share: an own pinned
            // default or any per-gear override.
            int perGearCount    = storedForRedline?.PerGearRedlines?.Count ?? 0;
            s.HasUserRedline    = userRl.HasValue || perGearCount > 0;
            s.ActiveVariantId   = storedForRedline?.Id;
            s.PerGearOverrideCount = perGearCount;
            s.CommunityRedline  = GetActiveVariantCommunityRedline();
            // A community value is USED from the first submission, but only
            // CLAIMED as "the community" once a second driver agrees; a lone
            // submission is labelled "unconfirmed" instead. (Single source of
            // truth for the threshold via IsActiveCommunityRedlineConfirmed.)
            bool commConfirmed = IsActiveCommunityRedlineConfirmed();
            if (userRl.HasValue) s.RedlineSource = "user";
            else if (s.CommunityRedline.HasValue && RevLimiter?.CarFactsRedline == s.CommunityRedline.Value)
                s.RedlineSource = commConfirmed ? "community" : "community_unconfirmed";
            else if ((EnginePulse?.ObservedRedlineRpm ?? 0) >= 500) s.RedlineSource = "game";
            else if (RevLimiter?.IsRedlineGuessed == true) s.RedlineSource = "estimated";
            else if (s.EffectiveRedline.HasValue) s.RedlineSource = "derived";
            else s.RedlineSource = "none";
            return s;
        }

        // Auto-generated variant labels follow "N cyl, M RPM" with an
        // optional ", R redline" suffix when redline is known. The
        // pattern lets EnsureVariantForLiveSignature refresh the label
        // on upgrade without clobbering a label the user typed themselves.
        private static readonly System.Text.RegularExpressions.Regex AutoLabelPattern =
            new System.Text.RegularExpressions.Regex(
                @"^(\d+ cyl|electric|engine)(, \d+ RPM)?(, \d+ redline)?$",
                System.Text.RegularExpressions.RegexOptions.Compiled);

        internal static bool IsAutoVariantLabel(string label)
        {
            if (string.IsNullOrWhiteSpace(label)) return true;
            return AutoLabelPattern.IsMatch(label);
        }

        internal static string BuildAutoVariantLabel(int cyl, int? maxRpm, int? redlineRpm,
                                                     bool isElectric = false)
        {
            var sb = new System.Text.StringBuilder();
            // Cyl=0 sentinel = "unknown cyl count" (SimHub-fallback game
            // with no bake entry). Lead with "engine" instead of "0 cyl"
            // so the label reads cleanly, or with "electric" when the zero
            // is an answer rather than a gap.
            sb.Append(cyl >= 1 ? (cyl + " cyl") : (isElectric ? "electric" : "engine"));
            if (maxRpm.HasValue && maxRpm.Value > 0)
                sb.Append(", ").Append(maxRpm.Value).Append(" RPM");
            if (redlineRpm.HasValue && redlineRpm.Value > 0)
                sb.Append(", ").Append(redlineRpm.Value).Append(" redline");
            return sb.ToString();
        }

        // (Removed: RegisterNewEngineVariant + DismissUnknownVariantSignature.
        // Both fed the "register new variant?" modal, which is gone now that
        // EnsureVariantForLiveSignature auto-creates variants from telemetry.
        // Community submissions still happen explicitly through the engine-
        // layout / redline / car-name share dialogs, not at variant creation.)

        /// <summary>Return the stored engine variants for the active car
        /// in display order. Legacy User-source variants are filtered out
        /// (PickStoredVariant ignores them, so showing them in the picker
        /// would just confuse the user). Empty list when there's no
        /// active car or no bundle yet. Caller MUST NOT mutate the
        /// returned list - use RenameActiveCarVariant / DeleteActiveCarVariant
        /// for mutations so the resolver + persist sequence stays
        /// inside the plugin.</summary>
        public IReadOnlyList<EngineVariant> GetActiveCarVariants()
        {
            if (string.IsNullOrEmpty(_activeGame) || string.IsNullOrEmpty(_activeCarId))
                return Array.Empty<EngineVariant>();
            if (Settings?.CarFacts == null) return Array.Empty<EngineVariant>();
            string key = _activeGame + "/" + _activeCarId;
            // Snapshot under the lock: the SimHub data thread can Add to this
            // list concurrently (EnsureVariantForLiveSignature), which would make
            // a bare foreach here throw "Collection was modified".
            lock (_carFactsLock)
            {
                if (!Settings.CarFacts.TryGetValue(key, out var bundle) || bundle?.EngineVariants == null)
                    return Array.Empty<EngineVariant>();
                var pool = new List<EngineVariant>(bundle.EngineVariants.Count);
                foreach (var v in bundle.EngineVariants)
                    if (v != null && v.Source != CarFactSource.User)
                        pool.Add(v);
                return pool;
            }
        }

        /// <summary>Resolve the redline to DISPLAY for one stored variant in the
        /// manage-variants list, mirroring what the rev limiter actually uses now
        /// that "adopt" is retired: the user's own pin wins (a legacy adopted value
        /// counts as the user's, same as the resolver), else the community consensus
        /// cached for this variant's signature (only when car facts are on, so what
        /// we show matches what the wheel uses), else a stored absolute redline
        /// (telemetry-captured; Forza never has one). Returns null with source
        /// "none" when nothing is stored and the wheel derives it live. <paramref
        /// name="source"/> is "user" / "community" / "community_unconfirmed" /
        /// "stored" / "none" so the UI can tag community-derived values.</summary>
        public int? ResolveVariantDisplayRedline(string game, string carId, EngineVariant v, out string source)
        {
            source = "none";
            if (v == null) return null;
            // 1) The user's own pin (legacy adopted value folded in, matching the
            //    resolver at GetActiveVariantPinnedRedline / the buzz cascade).
            int? pin = v.UserRedlineRpm ?? v.AdoptedCommunityRedlineRpm;
            if (pin.HasValue) { source = "user"; return pin; }
            // 2) Community consensus cached for this exact variant signature. Gated
            //    on UseCommunityCarFacts so a row never shows a value the wheel
            //    isn't applying. Usable at >= 1 supporter (matches the cascade);
            //    only >= 2 is labelled "community" rather than "unconfirmed".
            if (Settings?.UseCommunityCarFacts == true
                && !string.IsNullOrEmpty(game) && !string.IsNullOrEmpty(carId))
            {
                var r = GetCommunityCacheEntry(game, carId, ComputeStoredVariantSignature(v))?.Redline;
                if (r != null && r.Rpm >= 500 && r.Rpm <= 25000
                    && r.SupportingSubmissions >= CommunityRedlineMinSupport)
                {
                    source = r.SupportingSubmissions >= CommunityRedlineConfirmedSupport
                        ? "community" : "community_unconfirmed";
                    return r.Rpm;
                }
            }
            // 3) A stored absolute redline (telemetry-captured; non-Forza).
            if (v.RedlineRpm.HasValue) { source = "stored"; return v.RedlineRpm; }
            return null;
        }

        // Rebuild a stored variant's banded signature from its captured fields,
        // matching the live ComputeActiveCarVariantSignature format
        // ("cyl=..;maxrpm=..;redline=..") so it keys into the same
        // CommunityFactCache entries. Bands are idempotent on the stored
        // (already-rounded) values, so this reproduces the key written at fetch.
        private static string ComputeStoredVariantSignature(EngineVariant v)
        {
            if (v == null) return string.Empty;
            var parts = new List<string>(3);
            if (v.Cylinders >= 1 && v.Cylinders <= 16) parts.Add("cyl=" + v.Cylinders);
            int maxBand = v.MaxRpm.HasValue ? BandMaxRpm(v.MaxRpm.Value) : 0;
            if (maxBand > 0) parts.Add("maxrpm=" + maxBand);
            int redBand = v.RedlineRpm.HasValue ? BandRpm(v.RedlineRpm.Value) : 0;
            if (redBand > 0) parts.Add("redline=" + redBand);
            return parts.Count == 0 ? string.Empty : string.Join(";", parts);
        }

        /// <summary>Pin a specific variant as the active car's default
        /// pick. Writes Settings.CarFactsSelection[{game}/{carId}] = id
        /// (or clears the entry when id is null/empty), saves, and
        /// re-resolves so the new pick applies live. Returns false on
        /// no active car / no settings.</summary>
        public bool SetActiveCarVariantSelection(string variantId)
        {
            if (string.IsNullOrEmpty(_activeGame) || string.IsNullOrEmpty(_activeCarId)) return false;
            if (Settings == null) return false;
            if (Settings.CarFactsSelection == null)
                Settings.CarFactsSelection = new Dictionary<string, string>();
            string key = _activeGame + "/" + _activeCarId;
            if (string.IsNullOrEmpty(variantId))
                Settings.CarFactsSelection.Remove(key);
            else
                Settings.CarFactsSelection[key] = variantId;
            try { PersistSettingsCore(); } catch { }
            ResolveAndApplyCarFactsForActiveCar(_activeCarId, logResolution: true);
            ApplyActiveCarOverride();
            return true;
        }

        /// <summary>Rename a stored EngineVariant. Cosmetic only - no
        /// re-resolve. Returns false on no active car / no bundle /
        /// missing variant id / unchanged label. The label is trimmed
        /// and capped at 64 chars to match the upload-time validator.</summary>
        public bool RenameActiveCarVariant(string variantId, string newLabel)
        {
            if (string.IsNullOrEmpty(_activeGame) || string.IsNullOrEmpty(_activeCarId)) return false;
            if (string.IsNullOrEmpty(variantId)) return false;
            if (Settings?.CarFacts == null) return false;
            string key = _activeGame + "/" + _activeCarId;
            if (!Settings.CarFacts.TryGetValue(key, out var bundle) || bundle?.EngineVariants == null) return false;
            string label = (newLabel ?? "").Trim();
            if (label.Length == 0) return false;
            if (label.Length > 64) label = label.Substring(0, 64);
            bool renamed = false;
            lock (_carFactsLock)
            {
                foreach (var v in bundle.EngineVariants)
                {
                    if (v == null || v.Id != variantId) continue;
                    if (string.Equals(v.Label, label, StringComparison.Ordinal)) return false;
                    v.Label = label;
                    renamed = true;
                    break;
                }
            }
            if (!renamed) return false;
            ScheduleCarFactsFlush();
            RequestAutoBackup();   // engine-variant rename is settings-only (not a library file): the drift backstop won't catch it
            return true;
        }

        /// <summary>Remove a stored EngineVariant from the active car's
        /// bundle. Also clears Settings.CarFactsSelection[key] if it
        /// pointed at the deleted variant, so the resolver falls back
        /// to ranked cascade on the next pass. Saves + re-resolves.
        /// Returns false on no active car / missing variant.</summary>
        public bool DeleteActiveCarVariant(string variantId)
        {
            if (string.IsNullOrEmpty(_activeGame) || string.IsNullOrEmpty(_activeCarId)) return false;
            if (string.IsNullOrEmpty(variantId)) return false;
            if (Settings?.CarFacts == null) return false;
            string key = _activeGame + "/" + _activeCarId;
            // Deleting the ACTIVE variant is blocked at the UI (telemetry would
            // just recreate it), so delete is only ever a stale/inactive row -
            // no redline carry-over needed.
            bool removed = false;
            lock (_carFactsLock)
            {
                if (!Settings.CarFacts.TryGetValue(key, out var bundle) || bundle?.EngineVariants == null) return false;
                if (bundle.EngineVariants.RemoveAll(v => v != null && v.Id == variantId) == 0) return false;
                removed = true;
                if (Settings.CarFactsSelection != null
                    && Settings.CarFactsSelection.TryGetValue(key, out var sel)
                    && string.Equals(sel, variantId, StringComparison.Ordinal))
                    Settings.CarFactsSelection.Remove(key);
            }
            if (!removed) return false;
            ScheduleCarFactsFlush();
            RequestAutoBackup();   // car-facts variant deleted: arm auto-sync (CarFacts is portable)
            ResolveAndApplyCarFactsForActiveCar(_activeCarId, logResolution: true);
            ApplyActiveCarOverride();
            return true;
        }

        // Same shape as TryResolveActiveVariant but with the Community rung
        // explicitly skipped. Used by the engine-pulse panel to preview what
        // "Use built-in instead" would resolve to, and to drive the
        // user-action's downstream re-resolution.
        private bool TryResolveNonCommunityVariant(
            string game, string carId, out EngineVariant variant)
            => TryResolveVariantCore(game, carId, includeCommunity: false, out variant);

/// <summary>Persist the community-data toggle. Off = submissions are
        /// suppressed inside CommunityClient + (post Backend Phase 2) the
        /// consensus pull is skipped. SimHub's autosave catches this on
        /// plugin teardown, but writing through here makes the change
        /// immediately durable so it survives a SimHub crash.</summary>
        /// <summary>Raised after CommunityEnabled is toggled, from either the
        /// Settings checkbox or the share funnel. UI panels subscribe so the same
        /// follow-up (account row, MOTD, cache-stale, checkbox sync) runs no matter
        /// which surface flipped it.</summary>
        public event Action<bool> CommunityEnabledChanged;

        public void SetCommunityEnabled(bool on)
        {
            if (Settings == null) return;
            Settings.CommunityEnabled = on;
            PersistSettingsCore();
            // The Lovely dataset rides this switch, so the active car has to be
            // re-read or dropped right now. Without it the redlines already
            // published keep driving the shift cue after the user has turned
            // community features off, and turning them back on does nothing
            // until the next car change.
            try { OnLovelyDataAvailabilityChanged(); }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Warn("[TF4ALL] Lovely reload on community toggle failed: " + ex.Message);
            }
            try { CommunityEnabledChanged?.Invoke(on); }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Warn("[TF4ALL] CommunityEnabledChanged subscriber threw: " + ex.Message);
            }
        }

        /// <summary>Persist the "apply community car facts" toggle and make the
        /// change take effect on the active car immediately. Off clears the
        /// in-memory community consensus so names / layouts / redlines stop being
        /// applied at once; On re-applies from the local cache (no network needed)
        /// and re-resolves. Independent of CommunityEnabled (the networking master),
        /// so On + CommunityEnabled off = cache-only / offline use.</summary>
        public void SetUseCommunityCarFacts(bool on)
        {
            if (Settings == null) return;
            Settings.UseCommunityCarFacts = on;
            PersistSettingsCore();
            if (!on)
            {
                // Stop applying community car facts right now.
                _activeCarCommunityKey = null;        _activeCarCommunityConsensus = null;
                _activeCarCommunityNameKey = null;     _activeCarCommunityNameConsensus = null;
                _activeCarCommunityRedlineKey = null;  _activeCarCommunityRedlineConsensus = null;
            }
            else if (!string.IsNullOrEmpty(_activeGame) && !string.IsNullOrEmpty(_activeCarId))
            {
                // Re-apply from cache instantly (the UI separately decides whether
                // a network refresh is also due).
                ReplayCommunityCache(_activeGame, _activeCarId,
                    ComputeActiveCarVariantSignature(_activeGame, _activeCarId));
            }
            if (!string.IsNullOrEmpty(_activeCarId))
                ResolveAndApplyCarFactsForActiveCar(_activeCarId, logResolution: false);
        }

        /// <summary>Fire-and-forget submission of an engine-layout
        /// correction to the community backend. No-op when CommunityEnabled
        /// is false OR no backend URL / anon key is configured.
        /// CommunityClient is internal to the plugin assembly, so callers
        /// outside this class (the SettingsControl save-prompt handler) go
        /// through this passthrough.</summary>
        public void SubmitEngineLayoutToCommunity(string game, string carId, EngineLayout layout)
        {
            _community?.SubmitEngineLayoutAsync(game, carId, layout,
                ComputeActiveCarVariantSignature(game, carId));
            // Car facts are anonymous: the contribution note tracks whether a
            // submission actually went out, which needs community on + the
            // car-data sharing consent, not a signed-in account.
            if (Settings?.CommunityEnabled == true && Settings.AutoSubmitCarFacts)
                NoteMotdContribution(MotdContribution.CarFact);
        }

        /// <summary>Submit a custom-engine assignment to the community.
        /// Payload carries the full def so receivers can play it without
        /// importing - the receiver's plugin synthesizes a transient
        /// in-memory CustomEngineDef for the active car only. Same
        /// gating + variant signature plumbing as the built-in
        /// engine_layout path.</summary>
        public void SubmitCustomEngineToCommunity(string game, string carId,
            string name, string pattern, bool isElectric, string electricMode)
        {
            _community?.SubmitCustomEngineAsync(game, carId,
                name, pattern, isElectric, electricMode,
                ComputeActiveCarVariantSignature(game, carId));
            // Car facts are anonymous: the contribution note tracks whether a
            // submission actually went out, which needs community on + the
            // car-data sharing consent, not a signed-in account.
            if (Settings?.CommunityEnabled == true && Settings.AutoSubmitCarFacts)
                NoteMotdContribution(MotdContribution.CarFact);
        }

        // ---- Preset sharing passthroughs (PresetSharingClient is internal
        //      to the assembly; these wrap it for the UI layers). ----

        // Specific copy for the last upload failure so modals can
        // show "Slow down a moment..." / "Sign in expired..." instead
        // of one generic "network or rate limit" fallback.
        // Friendly, self-sufficient copy for the last upload failure. The raw
        // server/exception detail is NOT appended here (it leaks backend jargon
        // the user can't act on); it's logged where the error is stamped
        // (PresetSharingClient.StampUploadErrorFromStatus) for support instead.
        internal string DescribeLastUploadError()
        {
            if (_presetSharing == null) return "Upload failed.";
            switch (_presetSharing.LastUploadError)
            {
                case UploadError.Blocked:
                    return "Your account is restricted from uploading.";
                case UploadError.NotAuthenticated:
                    return "Sign-in expired. Sign in again and retry.";
                case UploadError.RateLimited:
                    return "Slow down a moment, then try again.";
                case UploadError.DuplicateName:
                    return "You already shared an item with this name. Update your existing upload instead, or pick a different name.";
                case UploadError.ValidationFailed:
                    return "The server rejected this upload. If you've already shared a preset with this name, rename it and try again.";
                case UploadError.ServerError:
                    return "Community backend hit an error. Try again in a minute.";
                case UploadError.NetworkFailure:
                    return "Couldn't reach the community backend. Check your connection, then retry.";
                default:
                    return "Upload failed.";
            }
        }

        // True when the last upload was rejected because the account/device is
        // banned. Share dialogs use this to pop the appeal modal in place.
        internal bool LastUploadWasBlocked()
            => _presetSharing != null && _presetSharing.LastUploadError == UploadError.Blocked;

        internal async Task<string> UploadCarPresetToCommunityAsync(
            string name, string game, string carId, JObject body,
            string author, string description, List<string> effectTags,
            int bodyVersion = 1, bool allowInPacks = false)
        {
            if (_presetSharing == null) return null;
            var id = await _presetSharing.UploadCarPresetAsync(
                name, game, carId, body, author, description, effectTags,
                bodyVersion, allowInPacks: allowInPacks);
            if (!string.IsNullOrEmpty(id))
            {
                InvalidateBrowseCacheForKind("car", game, carId);
                NoteMotdContribution(MotdContribution.Share);
            }
            return id;
        }

        // ---- Community-BROWSE cache (offline-first lists; see CommunityBrowseCacheStore) ----
        // Read-through cache wrapping the six browse fetches below. Lazy per entry
        // (one key per opened view), 72h TTL, force on manual refresh, invalidate
        // on the user's own upload/delete/vote. Never mass-refreshed.

        private static string BrowseKey(string type, string game, string carId, string sort, int limit)
            => string.Join("/", type, game ?? "", carId ?? "", sort ?? "", limit.ToString());

        private List<PresetSummary> BrowseCacheReadThrough(string key, int offset, bool force, Func<List<PresetSummary>> fetch)
        {
            if (_browseCache == null) return fetch();
            if (offset > 0)
            {
                // "Load more" (Show more): fetch the next page and GROW the cached
                // accumulated list for this view, so a return visit shows everything
                // the user had loaded. Returns just the new page (the UI appends).
                // Generation captured BEFORE the network read: if a delete/vote
                // invalidates while the fetch is in flight, the store drops this
                // write instead of re-caching the pre-delete list (which would
                // resurrect the deleted row from cache for up to the TTL).
                int gen = _browseCache.CurrentGeneration;
                var more = fetch();
                if (more != null && more.Count > 0) _browseCache.Append(key, more, gen);
                return more;
            }
            if (!force)
            {
                var cached = _browseCache.TryGet(key, out bool fresh);
                if (fresh && cached != null) return cached;
            }
            int gen0 = _browseCache.CurrentGeneration;   // pre-read capture, same reason
            var result = fetch();
            if (result != null) { _browseCache.Put(key, result, gen0); return result; }
            // Fetch failed (offline / signed out): serve the stale cache rather than
            // nothing, and never overwrite a good entry with a null.
            return _browseCache.TryGet(key, out _);
        }

        /// <summary>Drop the cached browse lists a user's own action made stale.
        /// kind: "car"|"game"|"engine"|"pack".</summary>
        public void InvalidateBrowseCacheForKind(string kind, string game, string carId)
        {
            if (_browseCache == null) return;
            switch (kind)
            {
                case "game":   _browseCache.InvalidatePrefix("game/" + (game ?? "") + "/");
                               _browseCache.InvalidatePrefix("trendingGame/"); break;
                case "engine": _browseCache.InvalidatePrefix("engine/"); break;
                case "pack":   _browseCache.InvalidatePrefix("pack/"); break;
                default:       _browseCache.InvalidatePrefix("car/" + (game ?? "") + "/" + (carId ?? "") + "/");
                               _browseCache.InvalidatePrefix("trendingCar/"); break;
            }
        }

        internal List<PresetSummary> FetchCommunityPresetsForCar(
            string game, string carId, string sort = "wilson", int limit = 20, bool force = false, int offset = 0)
            => BrowseCacheReadThrough(BrowseKey("car", game, carId, sort, limit), offset, force,
                () => _presetSharing?.FetchPresetsForCar(game, carId, sort, limit, offset));

        /// <summary>Cross-car browse / search for the community browser, once
        /// the user broadens past the active-car default (a search term and/or
        /// a multi-game filter). Live (not cached): results are query-specific
        /// and transient, and skipping the browse cache avoids polluting it
        /// with per-keystroke keys. kind: car|game|engine|pack; games == null/
        /// empty = all games (engines/packs ignore games entirely).</summary>
        internal List<PresetSummary> BrowseOrSearchCommunity(
            string kind, string query, IList<string> games,
            string sort = "wilson", int limit = 25, int offset = 0)
        {
            if (_presetSharing == null) return null;
            switch (kind)
            {
                case "game":   return _presetSharing.SearchGamePresets(query, games, sort, limit, offset);
                case "engine": return _presetSharing.SearchCustomEngines(query, sort, limit, offset);
                case "pack":   return _presetSharing.SearchPacks(query, sort, limit, offset);
                default:
                    var carIds = string.IsNullOrWhiteSpace(query)
                        ? null
                        : ResolveCarIdsByName(games, query);
                    return _presetSharing.SearchPresets(query, carIds, games, sort, limit, offset);
            }
        }

        // Resolve a human car-name query (e.g. "mx5") to the opaque car_ids
        // the preset rows store, so the community search can surface a car by
        // its real name. Merges the built-in name tables with local CarFacts
        // names (user renames / cached community names). Scoped to the given
        // games when provided; scans all games when null/empty.
        private List<string> ResolveCarIdsByName(IList<string> games, string query)
        {
            var set = new HashSet<string>(StringComparer.Ordinal);
            if (string.IsNullOrWhiteSpace(query)) return new List<string>();
            // Folded so accented and plain-ASCII spellings match either way
            // (FindCarIdsByDisplayName folds internally; the CarFacts loop
            // below matches folded-vs-folded with the same helper).
            string q = BuiltinCarCylinders.FoldDiacritics(query.Trim());
            var scopeGames = (games != null && games.Count > 0) ? games : null;

            // Built-in catalogs (Forza ordinal names, FH5 curated names, AC
            // descriptive ids).
            if (scopeGames == null)
            {
                foreach (var id in BuiltinCarCylinders.FindCarIdsByDisplayName(null, q, 200))
                    set.Add(id);
            }
            else
            {
                foreach (var g in scopeGames)
                    foreach (var id in BuiltinCarCylinders.FindCarIdsByDisplayName(g, q, 200))
                        set.Add(id);
            }

            // Local CarFacts names (key = "<game>/<carId>").
            try
            {
                var cf = Settings?.CarFacts;
                if (cf != null)
                {
                    foreach (var kv in cf)
                    {
                        if (set.Count >= 300) break;
                        var bundle = kv.Value;
                        if (bundle == null || string.IsNullOrEmpty(bundle.CarName)) continue;
                        if (BuiltinCarCylinders.FoldDiacritics(bundle.CarName)
                                .IndexOf(q, StringComparison.OrdinalIgnoreCase) < 0) continue;
                        string key = kv.Key ?? "";
                        int slash = key.IndexOf('/');
                        if (slash <= 0 || slash >= key.Length - 1) continue;
                        string g  = key.Substring(0, slash);
                        string id = key.Substring(slash + 1);
                        if (scopeGames != null
                            && !scopeGames.Any(x => string.Equals(x, g, StringComparison.OrdinalIgnoreCase)))
                            continue;
                        set.Add(id);
                    }
                }
            }
            catch { /* name resolution is best-effort; fall back to text match */ }

            return new List<string>(set);
        }

        /// <summary>Candidate games for the community browser's game filter:
        /// the active game, games the user has local presets for, and every
        /// game with a built-in car catalog. Sorted, de-duplicated.</summary>
        internal List<string> GetCommunityFilterGames()
        {
            var set = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            if (!string.IsNullOrEmpty(ActiveGame)) set.Add(ActiveGame);
            if (Settings?.GameDefaults != null)
                foreach (var k in Settings.GameDefaults.Keys)
                    if (!string.IsNullOrEmpty(k)) set.Add(k);
            try
            {
                foreach (var kv in GetAllCarPresets())
                    foreach (var p in kv.Value.Values)
                        if (!string.IsNullOrEmpty(p?.GameName)) set.Add(p.GameName);
            }
            catch { }
            foreach (var g in BuiltinCarCylinders.CatalogGames()) set.Add(g);
            return set.OrderBy(g => g, StringComparer.OrdinalIgnoreCase).ToList();
        }

        // Server-side per-game shared-preset counts for the community filter
        // chips, so games nobody on THIS machine has played still get offered
        // (a farmingsimulator25 upload was invisible in every other install's
        // browser) and the busiest games can surface first. Fetched at most
        // once per TTL and only from the chip rebuild path, so it rides the
        // user opening the panel rather than a background poll. Failures keep
        // whatever counts we last got and retry no sooner than the attempt
        // backoff.
        private volatile Dictionary<string, int> _communityGamesRemote;
        private DateTime _communityGamesRemoteUtc;
        private DateTime _communityGamesAttemptUtc;
        private int _communityGamesFetchInFlight;
        private static readonly TimeSpan CommunityGamesTtl     = TimeSpan.FromHours(6);
        private static readonly TimeSpan CommunityGamesBackoff = TimeSpan.FromSeconds(60);

        /// <summary>Latest server-side game -> shared-preset-count map, or
        /// null before the first successful fetch. Case-insensitive keys.
        /// Callers must not mutate it (the reference is swapped whole).</summary>
        internal Dictionary<string, int> GetCommunityGameUploadCounts() => _communityGamesRemote;

        /// <summary>Refresh the server-side game counts if stale. When the
        /// fetch lands games the current cache didn't have, onNewGames runs
        /// (on the worker thread; callers marshal to their dispatcher).</summary>
        internal void PrefetchCommunityGames(Action onNewGames)
        {
            if (Settings == null || !Settings.CommunityEnabled) return;
            var now = DateTime.UtcNow;
            if (_communityGamesRemote != null && (now - _communityGamesRemoteUtc) < CommunityGamesTtl) return;
            if ((now - _communityGamesAttemptUtc) < CommunityGamesBackoff) return;
            if (Interlocked.CompareExchange(ref _communityGamesFetchInFlight, 1, 0) != 0) return;
            _communityGamesAttemptUtc = now;
            Task.Run(() =>
            {
                try
                {
                    var fetched = _presetSharing?.FetchCommunityGameCounts();
                    if (fetched == null) return;   // keep the stale counts on failure
                    var prior = _communityGamesRemote;
                    _communityGamesRemote    = fetched;
                    _communityGamesRemoteUtc = DateTime.UtcNow;
                    bool grew = prior == null
                        || fetched.Keys.Any(k => !prior.ContainsKey(k));
                    if (grew) onNewGames?.Invoke();
                }
                catch (Exception ex)
                {
                    SimHub.Logging.Current.Warn("[TF4ALL] Community game-list prefetch failed: " + ex.Message);
                }
                finally { Interlocked.Exchange(ref _communityGamesFetchInFlight, 0); }
            });
        }

        internal PresetFull FetchCommunityPresetBody(string id)
        {
            return _presetSharing?.FetchPresetBody(id);
        }

        // Awaitable variants. Callers (ToggleVote) await + revert the
        // optimistic UI on false so a rate-limit / blocked-user / no-
        // auth rejection doesn't leave the row visually voted forever.
        internal Task<bool> TryVoteCommunityPresetAsync(string id, int value)
            => VoteThenNoteAsync(_presetSharing?.TryVotePresetAsync(id, value), value);

        internal Task<bool> TryVoteCommunityGamePresetAsync(string id, int value)
            => VoteThenNoteAsync(_presetSharing?.TryVoteGamePresetAsync(id, value), value);

        internal Task<bool> TryVoteCommunityCustomEngineAsync(string id, int value)
            => VoteThenNoteAsync(_presetSharing?.TryVoteCustomEngineAsync(id, value), value);

        internal Task<bool> TryVoteCommunityPackAsync(string id, int value)
            => VoteThenNoteAsync(_presetSharing?.TryVotePackAsync(id, value), value);

        // Awaits a vote and, on a real (non-retraction) success, stamps voter
        // recency so the "go vote" community nudge stays hidden for a while.
        private async Task<bool> VoteThenNoteAsync(Task<bool> voteTask, int value)
        {
            bool ok = await (voteTask ?? Task.FromResult(false)).ConfigureAwait(false);
            if (ok && value != 0) NoteMotdContribution(MotdContribution.Vote);
            return ok;
        }

