        /// <summary>Record a freshly-downloaded community preset so the
        /// next plugin-load update-check knows to compare against it.
        /// Idempotent on preset_id. Kind = "car" / "game" / "engine"
        /// / "pack" routes the update check to the right server table.
        /// allowInPacks is the author's "may be re-bundled" permission,
        /// captured at download time so the local pack creator can
        /// filter selectable rows.
        /// originalBodyHash + ownerUserId feed the auto-update gate: the
        /// background sweep only silently re-applies an update when the
        /// local body still matches the hash from this stamp (no local
        /// edits since download).</summary>
        public void RecordDownloadedCommunityPreset(string presetId, string localPresetName,
            string carId, string gameName, int contentVersion,
            string kind = "car", bool allowInPacks = false,
            string originalBodyHash = null, string ownerUserId = null)
        {
            if (Settings == null || string.IsNullOrEmpty(presetId)) return;
            if (Settings.DownloadedCommunityPresets == null)
                Settings.DownloadedCommunityPresets = new Dictionary<string, DownloadedPresetRecord>();
            Settings.DownloadedCommunityPresets[presetId] = new DownloadedPresetRecord
            {
                LocalPresetName     = localPresetName,
                CarId               = carId,
                GameName            = gameName,
                SeenContentVersion  = contentVersion,
                DownloadedAt        = DateTime.UtcNow,
                Kind                = string.IsNullOrEmpty(kind) ? "car" : kind,
                AllowInPacks        = allowInPacks,
                OriginalBodyHash    = originalBodyHash,
                OwnerUserId         = ownerUserId,
            };
            try { PersistSettingsCore(); } catch { }
        }

        /// <summary>Run the update-check: ask the server for the current
        /// state of every downloaded preset and return the ones whose
        /// content_version is now higher than the local SeenContentVersion.
        /// Background-thread safe; the result is plain data the UI
        /// renders on the dispatcher.</summary>
        // Headless auto-update sweep for downloaded community presets. Until
        // 2026-07 the ONLY driver of the update check was the settings
        // panel's Loaded handler (MaybeShowCommunityUpdates), so a user who
        // enabled Auto-update but never opened the panel got no updates:
        // same panel-gating shape as the community car-facts bug. Runs from
        // the update-check cadence (startup check + the user-configured
        // UpdateCheckIntervalHours re-poll) and only silent-applies; rows
        // needing a user decision (edited local copy, packs, no baseline)
        // stay in the tracker for the panel's modal on next open. No-op
        // when Auto-update or community networking is off.
        private volatile bool _presetSweepInFlight;
        internal async Task MaybeAutoUpdateCommunityPresetsHeadless()
        {
            if (_shuttingDown) return;
            if (Settings?.AutoUpdateDownloadedPresets != true) return;
            if (Settings?.CommunityEnabled != true) return;
            if (_presetSweepInFlight) return;
            _presetSweepInFlight = true;
            try
            {
                var updates = await FindCommunityPresetUpdatesAsync();
                if (updates == null || updates.Count == 0) return;
                var residual = await AutoApplyCommunityPresetUpdatesAsync(updates);
                int applied = updates.Count - (residual?.Count ?? 0);
                if (applied > 0)
                    SimHub.Logging.Current.Info(
                        $"[TF4ALL] Background preset auto-update: {applied} downloaded preset(s) refreshed"
                        + ((residual?.Count ?? 0) > 0 ? $", {residual.Count} awaiting a decision in the Preset Manager." : "."));
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Warn($"[TF4ALL] Background preset auto-update failed: {ex.Message}");
            }
            finally { _presetSweepInFlight = false; }
        }

        internal async Task<List<(PresetSummary Server, DownloadedPresetRecord Local)>> FindCommunityPresetUpdatesAsync()
        {
            var found = new List<(PresetSummary, DownloadedPresetRecord)>();
            if (Settings?.DownloadedCommunityPresets == null
                || Settings.DownloadedCommunityPresets.Count == 0)
                return found;
            // Snapshot the local map before any background work so a
            // concurrent download mid-check doesn't confuse us. Copied under
            // the serialize lock: the headless sweep runs this method on a
            // pool thread, where an unlocked copy could race a structural
            // mutation from the UI or data thread.
            Dictionary<string, DownloadedPresetRecord> localById;
            lock (_carFactsLock)
            {
                localById = new Dictionary<string, DownloadedPresetRecord>(
                    Settings.DownloadedCommunityPresets, StringComparer.Ordinal);
            }
            // Split ids by kind so each one routes to its dedicated
            // get_*_by_ids RPC. Tables don't share id space, so each
            // bucket queries independently.
            var carIds    = new List<string>();
            var gameIds   = new List<string>();
            var engineIds = new List<string>();
            var packIds   = new List<string>();
            foreach (var kv in localById)
            {
                string k = kv.Value?.Kind;
                if      (string.Equals(k, "game",   StringComparison.OrdinalIgnoreCase)) gameIds.Add(kv.Key);
                else if (string.Equals(k, "engine", StringComparison.OrdinalIgnoreCase)) engineIds.Add(kv.Key);
                else if (string.Equals(k, "pack",   StringComparison.OrdinalIgnoreCase)) packIds.Add(kv.Key);
                else                                                                     carIds.Add(kv.Key);
            }
            List<PresetSummary> serverRows;
            // Per-bucket fetch outcome. The fetch clients return null for
            // network failure, timeout, non-2xx AND signed-out, so a null
            // bucket is NO INFORMATION, never "these rows were deleted".
            // Before this distinction one failed round classified every
            // tracked id as orphaned and permanently wiped the tracker;
            // survivable when it needed the panel open to fire, fatal once
            // the headless sweep started running it unattended (SimHub
            // autostarting before Wi-Fi was enough).
            bool carBucketOk = true, gameBucketOk = true, engineBucketOk = true, packBucketOk = true;
            try
            {
                var fetched = await Task.Run(() =>
                {
                    var combined = new List<PresetSummary>();
                    bool cOk = true, gOk = true, eOk = true, pOk = true;
                    if (carIds.Count > 0)
                    {
                        var carRows = _presetSharing?.FetchPresetsByIds(carIds);
                        if (carRows != null) combined.AddRange(carRows); else cOk = false;
                    }
                    if (gameIds.Count > 0)
                    {
                        var gameRows = _presetSharing?.FetchGamePresetsByIds(gameIds);
                        if (gameRows != null) combined.AddRange(gameRows); else gOk = false;
                    }
                    if (engineIds.Count > 0)
                    {
                        var engineRows = _presetSharing?.FetchCustomEnginesByIds(engineIds);
                        if (engineRows != null) combined.AddRange(engineRows); else eOk = false;
                    }
                    if (packIds.Count > 0)
                    {
                        var packRows = _presetSharing?.FetchPacksByIds(packIds);
                        if (packRows != null) combined.AddRange(packRows); else pOk = false;
                    }
                    return (combined, cOk, gOk, eOk, pOk);
                });
                serverRows    = fetched.combined;
                carBucketOk    = fetched.cOk;
                gameBucketOk   = fetched.gOk;
                engineBucketOk = fetched.eOk;
                packBucketOk   = fetched.pOk;
            }
            catch { return found; }
            if (serverRows == null) return found;

            var serverById = serverRows.Where(r => !string.IsNullOrEmpty(r.Id))
                                       .ToDictionary(r => r.Id, r => r);

            // True only when the id's OWN bucket got a real server response.
            bool BucketAnswered(DownloadedPresetRecord rec)
            {
                string k = rec?.Kind;
                if (string.Equals(k, "game",   StringComparison.OrdinalIgnoreCase)) return gameBucketOk;
                if (string.Equals(k, "engine", StringComparison.OrdinalIgnoreCase)) return engineBucketOk;
                if (string.Equals(k, "pack",   StringComparison.OrdinalIgnoreCase)) return packBucketOk;
                return carBucketOk;
            }

            // Author-deleted (suppressed) rows are filtered out of the
            // response; drop the local record so we stop checking. Only an
            // id whose bucket ACTUALLY ANSWERED can be orphaned.
            var orphaned = new List<string>();
            foreach (var kv in localById)
            {
                if (!serverById.TryGetValue(kv.Key, out var server))
                {
                    if (BucketAnswered(kv.Value)) orphaned.Add(kv.Key);
                    continue;
                }
                if (server.ContentVersion > kv.Value.SeenContentVersion)
                    found.Add(((PresetSummary)server, kv.Value));
            }
            // Garbage-collect orphaned entries.
            if (orphaned.Count > 0)
            {
                // Log orphans before removing so debugging "where did
                // my update notification go?" is possible from the
                // SimHub log. The local preset file is preserved; only
                // the update-tracker entry is being cleared.
                SimHub.Logging.Current.Info(
                    $"[TF4ALL] {orphaned.Count} community update tracker(s) removed (server row deleted). " +
                    "Local presets preserved.");
                // Structural mutation under the serialize lock (this can run
                // on a pool thread in the headless sweep).
                lock (_carFactsLock)
                {
                    foreach (var id in orphaned)
                        Settings.DownloadedCommunityPresets.Remove(id);
                }
                try { PersistSettingsCore(); } catch { }
            }
            return found;
        }

        /// <summary>Mark a downloaded preset's SeenContentVersion as
        /// caught up to a given server version. Used when the user
        /// either applies an update or Skip-dismisses the prompt.</summary>
        public void AcknowledgeCommunityPresetVersion(string presetId, int contentVersion)
        {
            if (Settings?.DownloadedCommunityPresets == null) return;
            if (Settings.DownloadedCommunityPresets.TryGetValue(presetId, out var rec))
            {
                rec.SeenContentVersion = contentVersion;
                try { PersistSettingsCore(); } catch { }
            }
        }

        /// <summary>Silently re-apply any community update where the local
        /// body still matches the OriginalBodyHash from download (i.e. the
        /// user hasn't edited it locally). Returns the residual list of
        /// updates that still need user input (edited locally, unsupported
        /// kind, or fetch/save failed) so the caller can route those into
        /// PresetUpdatesAvailableWindow as today.
        ///
        /// No-ops (returns the input unchanged) when
        /// AutoUpdateDownloadedPresets is off. Packs are never auto-applied:
        /// they bundle multiple entries across kinds and a silent re-save
        /// would clobber per-entry user state.</summary>
        internal async Task<List<(PresetSummary Server, DownloadedPresetRecord Local)>>
            AutoApplyCommunityPresetUpdatesAsync(
                List<(PresetSummary Server, DownloadedPresetRecord Local)> updates)
        {
            var residual = new List<(PresetSummary, DownloadedPresetRecord)>();
            if (updates == null || updates.Count == 0) return residual;
            if (Settings?.AutoUpdateDownloadedPresets != true)
            {
                residual.AddRange(updates);
                return residual;
            }
            foreach (var pair in updates)
            {
                var server = pair.Server;
                var local  = pair.Local;
                if (server == null || local == null)
                {
                    residual.Add(pair);
                    continue;
                }
                // No baseline -> can't prove "unedited"; user decides.
                if (string.IsNullOrEmpty(local.OriginalBodyHash))
                {
                    residual.Add(pair);
                    continue;
                }
                string kind = (local.Kind ?? "car").ToLowerInvariant();
                // Pack updates touch multiple library entries at once;
                // never silent-apply (would overwrite user edits inside
                // the bundle without consent).
                if (kind == "pack")
                {
                    residual.Add(pair);
                    continue;
                }
                bool applied = false;
                try
                {
                    applied = await Task.Run(() =>
                        TryAutoApplyOne(kind, server, local));
                }
                catch (Exception ex)
                {
                    SimHub.Logging.Current.Warn(
                        "[TF4ALL] Auto-update failed for " + server.Id + ": " + ex.Message);
                }
                if (!applied) residual.Add(pair);
            }
            return residual;
        }

        // Per-row body+hash compare + re-fetch + re-save + re-stamp.
        // Runs on a background thread (called from Task.Run). Returns
        // true when the row was silently applied and should NOT appear
        // in the user-facing residual list.
        private bool TryAutoApplyOne(string kind,
            PresetSummary server, DownloadedPresetRecord local)
        {
            if (kind == "car")
            {
                if (string.IsNullOrEmpty(local.CarId) || local.CarId == "*") return false;
                if (string.IsNullOrEmpty(local.LocalPresetName)) return false;
                var perCar = GetCarPresets(local.CarId);
                if (perCar == null) return false;
                if (!perCar.TryGetValue(local.LocalPresetName, out var entry)) return false;
                if (entry?.Override == null) return false;
                string currentHash = PresetBodyHasher.ComputeCarOverrideHash(entry.Override);
                if (!string.Equals(currentHash, local.OriginalBodyHash, StringComparison.Ordinal))
                    return false;
                PresetFull full = _presetSharing?.FetchPresetBody(server.Id);
                if (full?.Body == null || full.Summary == null) return false;
                CarOverride newOvr = null;
                List<CustomEngineDef> customs = null;
                try
                {
                    var ovrToken = full.Body["override"];
                    if (ovrToken != null) newOvr = ovrToken.ToObject<CarOverride>();
                    var ceToken = full.Body["custom_engines"];
                    if (ceToken is Newtonsoft.Json.Linq.JArray ja)
                        customs = ja.ToObject<List<CustomEngineDef>>();
                }
                catch { return false; }
                if (newOvr == null) return false;
                if (customs != null && customs.Count > 0)
                    ImportCommunityCustomEngines(customs);
                SaveImportedCommunityCarPreset(
                    local.CarId, local.LocalPresetName,
                    local.GameName ?? full.Summary.Game ?? "",
                    newOvr,
                    full.Summary.Author, full.Summary.Description,
                    communitySourceId: full.Summary.Id,
                    allowInPacks: full.Summary.AllowInPacks);
                string newHash = PresetBodyHasher.ComputeCarOverrideHash(newOvr);
                StampAutoUpdatedDownloadRecord(server.Id, server.ContentVersion, newHash);
                SimHub.Logging.Current.Info(
                    "[TF4ALL] Auto-updated community car preset '" + local.LocalPresetName
                    + "' (v" + local.SeenContentVersion + " -> v" + server.ContentVersion + ").");
                return true;
            }
            if (kind == "game")
            {
                if (string.IsNullOrEmpty(local.LocalPresetName)) return false;
                if (Settings?.Presets == null) return false;
                if (!Settings.Presets.TryGetValue(local.LocalPresetName, out var localSnap)) return false;
                if (localSnap == null) return false;
                string currentHash = PresetBodyHasher.ComputeGameSnapshotBodyHash(localSnap);
                if (!string.Equals(currentHash, local.OriginalBodyHash, StringComparison.Ordinal))
                    return false;
                PresetFull full = _presetSharing?.FetchGamePresetBody(server.Id);
                if (full?.Body == null || full.Summary == null) return false;
                GameSettingsSnapshot newSnap = null;
                List<CustomEngineDef> customs = null;
                try
                {
                    var snapToken = full.Body["snapshot"];
                    if (snapToken != null) newSnap = snapToken.ToObject<GameSettingsSnapshot>();
                    var ceToken = full.Body["custom_engines"];
                    if (ceToken is Newtonsoft.Json.Linq.JArray ja)
                        customs = ja.ToObject<List<CustomEngineDef>>();
                }
                catch { return false; }
                if (newSnap == null) return false;
                if (customs != null && customs.Count > 0)
                    ImportCommunityCustomEngines(customs);
                bool saved = SaveImportedCommunityGamePreset(
                    local.LocalPresetName, newSnap,
                    full.Summary.Author, full.Summary.Description,
                    communitySourceId: full.Summary.Id,
                    allowInPacks: full.Summary.AllowInPacks);
                if (!saved) return false;
                string newHash = PresetBodyHasher.ComputeGameSnapshotBodyHash(newSnap);
                StampAutoUpdatedDownloadRecord(server.Id, server.ContentVersion, newHash);
                SimHub.Logging.Current.Info(
                    "[TF4ALL] Auto-updated community game preset '" + local.LocalPresetName
                    + "' (v" + local.SeenContentVersion + " -> v" + server.ContentVersion + ").");
                return true;
            }
            if (kind == "engine")
            {
                if (Settings?.CustomEngines == null) return false;
                CustomEngineDef localDef = null;
                foreach (var e in Settings.CustomEngines)
                {
                    if (e == null) continue;
                    if (string.Equals(e.CommunitySourceId, server.Id, StringComparison.Ordinal)
                        || string.Equals(e.Id, server.Id, StringComparison.Ordinal))
                    {
                        localDef = e;
                        break;
                    }
                }
                if (localDef == null) return false;
                string currentHash = PresetBodyHasher.ComputeCustomEngineHash(localDef);
                if (!string.Equals(currentHash, local.OriginalBodyHash, StringComparison.Ordinal))
                    return false;
                PresetFull full = _presetSharing?.FetchCommunityCustomEngineBody(server.Id);
                if (full?.Body == null || full.Summary == null) return false;
                CustomEngineDef newDef = null;
                try { newDef = full.Body.ToObject<CustomEngineDef>(); }
                catch { return false; }
                if (newDef == null) return false;
                SaveImportedCommunityCustomEngine(newDef,
                    communitySourceId: full.Summary.Id,
                    allowInPacks: full.Summary.AllowInPacks);
                string newHash = PresetBodyHasher.ComputeCustomEngineHash(newDef);
                StampAutoUpdatedDownloadRecord(server.Id, server.ContentVersion, newHash);
                SimHub.Logging.Current.Info(
                    "[TF4ALL] Auto-updated community custom engine '" + (newDef.Name ?? local.LocalPresetName)
                    + "' (v" + local.SeenContentVersion + " -> v" + server.ContentVersion + ").");
                return true;
            }
            return false;
        }

        // Restamp the DownloadedPresetRecord after an auto-update: bump
        // SeenContentVersion (so the same revision won't re-surface) and
        // refresh OriginalBodyHash to the newly-saved body so the next
        // sweep can detect any future local edits.
        private void StampAutoUpdatedDownloadRecord(string presetId, int newContentVersion, string newBodyHash)
        {
            if (Settings?.DownloadedCommunityPresets == null) return;
            if (!Settings.DownloadedCommunityPresets.TryGetValue(presetId, out var rec)) return;
            rec.SeenContentVersion = newContentVersion;
            rec.OriginalBodyHash   = newBodyHash;
            try { PersistSettingsCore(); } catch { }
        }

        // ===================== Community voting UX =====================
        // Client side of the "rate what you run" feature. The server RPC
        // already refuses a fresh vote from a user who hasn't downloaded
        // the item ("download before voting"); these helpers + the
        // DownloadedPresetRecord fields let the UI gate the vote BEFORE it
        // bounces, mirror the chosen direction without a round trip, and
        // surface a one-time, non-blocking "rate it?" nudge.

        // Nudge only becomes eligible once the user has actually run a
        // downloaded preset a couple of times (so we never nag on a fresh
        // download they haven't tried yet).
        public const int VoteNudgeMinUses = 2;
        // After ANY nudge fires, suppress every nudge for this long so a
        // user who downloads several presets in one sitting isn't nagged
        // for each.
        public const int VoteNudgeGlobalCooldownHours = 48;
        // After this many consecutive "Later" dismissals (no vote in between)
        // the nudge goes dormant - the user has shown they won't engage with
        // it. Any nudge vote resets the streak.
        public const int VoteNudgeMaxConsecutiveDismissals = 3;

        // Preset ids whose UseCount has already been bumped this plugin
        // session, so a single seating only counts once no matter how many
        // times the active-card refresh fires. Seeded empty at startup.
        private readonly HashSet<string> _useCountedThisSession =
            new HashSet<string>(StringComparer.Ordinal);

        /// <summary>True when the given community item id is in the active
        /// user's downloaded-presets map. Used by the browse-list vote gate
        /// and the active-card vote control to decide whether a fresh vote
        /// is allowed locally before the server round trip.</summary>
        public bool HasDownloadedCommunity(string id) =>
            Settings?.DownloadedCommunityPresets != null
            && !string.IsNullOrEmpty(id)
            && Settings.DownloadedCommunityPresets.ContainsKey(id);

        /// <summary>Record the local user's last-known vote for a downloaded
        /// community item (-1/0/1) and persist. No-op when the id isn't a
        /// tracked download. Called by the active-card vote control / nudge
        /// after a successful server vote so the UI stays in sync.</summary>
        public void SetDownloadedCommunityVote(string id, int value)
        {
            if (Settings?.DownloadedCommunityPresets == null
                || string.IsNullOrEmpty(id)) return;
            if (Settings.DownloadedCommunityPresets.TryGetValue(id, out var rec)
                && rec != null)
            {
                rec.MyVote = value;
                try { PersistSettingsCore(); } catch { }
            }
        }

        /// <summary>Mark a downloaded community item's one-time vote nudge as
        /// shown (so it never returns for this item) and stamp the global
        /// cooldown clock. Persists. No-op when the id isn't tracked.</summary>
        public void MarkVoteNudgeShown(string id)
        {
            if (Settings?.DownloadedCommunityPresets == null
                || string.IsNullOrEmpty(id)) return;
            if (Settings.DownloadedCommunityPresets.TryGetValue(id, out var rec)
                && rec != null)
            {
                rec.PromptedForVote = true;
                Settings.LastVoteNudgeUtc = DateTime.UtcNow;
                try { PersistSettingsCore(); } catch { }
            }
        }

        /// <summary>User dismissed a vote nudge with "Later". Bumps the
        /// consecutive-dismissal streak; once it hits
        /// VoteNudgeMaxConsecutiveDismissals the nudge goes dormant.</summary>
        public void NoteVoteNudgeDismissed()
        {
            if (Settings == null) return;
            Settings.ConsecutiveVoteNudgeDismissals += 1;
            try { PersistSettingsCore(); } catch { }
        }

        /// <summary>User voted from a nudge - they engage with it, so clear
        /// the dismissal streak and keep asking about future presets.</summary>
        public void ResetVoteNudgeDismissals()
        {
            if (Settings == null || Settings.ConsecutiveVoteNudgeDismissals == 0) return;
            Settings.ConsecutiveVoteNudgeDismissals = 0;
            try { PersistSettingsCore(); } catch { }
        }

        /// <summary>When the named car preset is a community download, bump
        /// its UseCount at most once per plugin session and persist. Called
        /// from the active-card refresh after the applied car preset is
        /// resolved; returns the matched download id (or null) so the caller
        /// can drive the vote control / nudge off the same lookup.</summary>
        public string NoteActiveCommunityCarPresetUsed(string carId, string presetName)
        {
            if (Settings?.DownloadedCommunityPresets == null
                || string.IsNullOrEmpty(carId)
                || string.IsNullOrEmpty(presetName)) return null;
            // Resolve the applied car preset's community source id via the
            // override's CommunitySourceId (the same stable identity the
            // share-gate uses; survives rename / duplicate).
            string communityId = GetCommunitySourceIdForCarPreset(carId, presetName);
            if (string.IsNullOrEmpty(communityId)) return null;
            if (!Settings.DownloadedCommunityPresets.TryGetValue(communityId, out var rec)
                || rec == null)
                return null;
            if (_useCountedThisSession.Add(communityId))
            {
                rec.UseCount += 1;
                try { PersistSettingsCore(); } catch { }
            }
            return communityId;
        }

        /// <summary>Community source id stamped on a car preset's override
        /// at download time, or null when the preset is locally authored /
        /// missing. Null carId/presetName -> null.</summary>
        public string GetCommunitySourceIdForCarPreset(string carId, string presetName)
        {
            if (string.IsNullOrEmpty(carId) || string.IsNullOrEmpty(presetName))
                return null;
            var perCar = GetCarPresets(carId);
            if (perCar == null) return null;
            if (perCar.TryGetValue(presetName, out var entry)
                && entry?.Override != null
                && !string.IsNullOrEmpty(entry.Override.CommunitySourceId))
                return entry.Override.CommunitySourceId;
            return null;
        }

        // ---- Per-local-user data slots ------------------------------------
        //
        // When the same install is used by more than one Supabase
        // account (a shared family PC, etc.), each account gets its
        // own DownloadedCommunityPresets + SharingAuthor under
        // Settings.UserSlots[<user-id>]. Settings.ActiveSlotKey names
        // the currently-mounted slot; legacy fields Settings.Downloaded
        // CommunityPresets and Settings.SharingAuthor are reset to
        // reference that slot's data, so existing call sites work
        // unchanged. SignOut switches to the anonymous slot ("") so
        // the prior user's data is preserved (not lost) and the next
        // user inherits a clean view.

        /// <summary>Public event UI panels subscribe to so they can
        /// reset their per-session latches + in-memory caches when
        /// the active local user changes. Fires AFTER the new slot
        /// is mounted. Argument: the new slot key (lower-cased email
        /// or "" for anonymous).</summary>
        public event Action<string> AuthIdentityChanged;

        // Convenience accessor for the currently-mounted user data
        // slot. Returns null only when Settings is null (pre-init).
        internal UserDataSlot GetActiveUserSlot()
        {
            if (Settings?.UserSlots == null) return null;
            string key = Settings.ActiveSlotKey ?? "";
            UserDataSlot slot;
            if (!Settings.UserSlots.TryGetValue(key, out slot))
            {
                slot = new UserDataSlot();
                Settings.UserSlots[key] = slot;
            }
            return slot;
        }

        // Stash + remount on identity change. Called from the
        // CommunityAuth.ActiveIdentityChanged event.
        private void OnActiveIdentityChanged(string newKey)
        {
            newKey = newKey ?? "";
            // Decide how the incoming slot's saved profile is treated BEFORE the
            // mount touches anything: the modal (when one is needed) then blocks
            // over a fully consistent prior-identity state, and the mount itself
            // never pumps messages mid-swap. This event fires from user sign-in /
            // sign-out clicks AND from the session-heartbeat remote-revoke path;
            // the revoke path sets _suppressNextIdentityPrompt first so an
            // unattended tick can never pop a modal over a race (it keeps the
            // legacy silent apply).
            var profileChoice = ProfileApplyChoice.Apply;
            bool suppressed = _suppressNextIdentityPrompt;
            _suppressNextIdentityPrompt = false;
            if (!suppressed)
            {
                try { profileChoice = DecideProfileChoiceInteractive(newKey); }
                catch (Exception ex)
                {
                    // A broken prompt must not decide FOR replacing live tuning.
                    SimHub.Logging.Current.Warn(
                        "[TF4ALL] Account-switch prompt failed (" + ex.GetType().Name + "); keeping current tuning.");
                    profileChoice = ProfileApplyChoice.KeepCurrent;
                }
            }
            try { MountUserSlot(newKey, profileChoice); }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Error(
                    "[TF4ALL] Slot remount failed: " + ex.Message);
            }
            // Drop any per-car community consensus the previous
            // identity fetched - the new identity must refresh from
            // the server rather than see the prior user's view.
            _activeCarCommunityKey             = null;
            _activeCarCommunityConsensus       = null;
            _activeCarCommunityNameKey         = null;
            _activeCarCommunityNameConsensus   = null;
            _activeCarCommunityRedlineKey      = null;
            _activeCarCommunityRedlineConsensus = null;
            // Allow the next user (or anonymous after sign-out) to
            // see the welcome pitch once if they haven't yet.
            _initWelcomePromptOffered = false;
            // Drop per-identity state BEFORE notifying subscribers: a UI panel refreshing during the
            // event (supporter badge / Discord row) must not read the PRIOR user's cached status.
            // The account-status cache (entitlement + Discord link) is per-identity; presence belongs
            // to the prior identity too, so a stale "peer online" can't keep the pull/heartbeat running
            // across the switch. The reconcile below re-probes presence for the new identity.
            InvalidateAccountStatusCache();
            _hasActivePeer = false;
            System.Threading.Interlocked.Exchange(ref _presenceCheckedUtcTicks, 0);
            try { AuthIdentityChanged?.Invoke(newKey ?? ""); }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Warn(
                    "[TF4ALL] AuthIdentityChanged subscriber threw: " + ex.Message);
            }
            // Re-arm both timers for the new identity (both stop cleanly once signed out).
            UpdateAutoPullTimer();
            UpdateSessionHeartbeatTimer();
            // Reconcile sync state for the new identity: probe presence, run the drift backstop, and
            // catch up if a peer is online. ignoreActivity so a fresh sign-in pulls without first
            // requiring an interaction; the peer gate still spares solo users.
            ReconcileSyncState(ignoreActivity: true);
        }

        // Ensures Settings.UserSlots exists, runs the one-time legacy
        // migration if needed, then mounts the active slot. Called
        // exactly once during Init, before any community fetch can
        // touch DownloadedCommunityPresets or SharingAuthor.
        private void EnsureUserSlotsMounted()
        {
            if (Settings == null) return;
            if (Settings.UserSlots == null)
                Settings.UserSlots = new Dictionary<string, UserDataSlot>();

            // Stable key for the signed-in account = the immutable Supabase user-id (falls back to
            // the email key only if a session somehow lacks one). "" = anonymous / signed-out.
            var sess = Settings.AuthSession;
            string signedInUserId = (sess != null && !string.IsNullOrEmpty(sess.UserId)) ? sess.UserId : null;

            // One-time: re-key this user's email-keyed slot (from the never-shipped email scheme /
            // pre-user-id test builds) to the user-id, so an email change can't orphan it. Other
            // accounts' email-keyed slots reconcile on their next sign-in (see MountUserSlot).
            if (!Settings.SlotsKeyedByUserIdV1)
            {
                if (signedInUserId != null)
                    RekeySlot(CommunityAuth.SlotKeyFromEmail(sess.Email), signedInUserId);
                Settings.SlotsKeyedByUserIdV1 = true;
                try { PersistSettingsCore(); } catch { }
            }

            // F04: Snapshot the legacy-data owner email on first sign-in so the pre-slot migration anchors to the right user even if auth flips before EnsureUserSlotsMounted runs.
            bool hasLegacyData = (Settings.DownloadedCommunityPresets?.Count ?? 0) > 0
                              || !string.IsNullOrEmpty(Settings.SharingAuthor);
            if (!Settings.UserSlotsMigratedV1
                && hasLegacyData
                && string.IsNullOrEmpty(Settings.LegacyDataOwnerEmail)
                && sess != null)
            {
                Settings.LegacyDataOwnerEmail = sess.Email ?? "";
            }

            // Pre-slot legacy data targets the signed-in user-id; only when no user-id is available
            // does it fall back to an email-derived key (legacy-owner snapshot or current email).
            string emailFallbackKey = CommunityAuth.SlotKeyFromEmail(Settings.LegacyDataOwnerEmail);
            if (string.IsNullOrEmpty(emailFallbackKey))
                emailFallbackKey = CommunityAuth.SlotKeyFromEmail(sess?.Email);
            string desiredKey = signedInUserId ?? emailFallbackKey ?? "";

            if (!Settings.UserSlotsMigratedV1)
            {
                // F20: if slots are already populated, migration ran on a prior launch; just repair the flag without re-running migration (resists reset-tampering).
                if (Settings.UserSlots.Count > 0)
                {
                    SimHub.Logging.Current.Warn(
                        "[TF4ALL] UserSlotsMigratedV1 was reset but slots exist; restoring flag.");
                    Settings.UserSlotsMigratedV1 = true;
                    try { PersistSettingsCore(); } catch { }
                }
                else
                {
                    // F12: flip the latch BEFORE any slot mutation or save so a crashed save can't re-trigger migration on next launch.
                    Settings.UserSlotsMigratedV1 = true;
                    // Move any pre-slot DownloadedCommunityPresets +
                    // SharingAuthor into the slot keyed by the legacy data
                    // owner so existing local history doesn't disappear on
                    // first run. Skip if the target slot already has data
                    // (clobber safety).
                    if (!Settings.UserSlots.ContainsKey(desiredKey))
                    {
                        var seed = new UserDataSlot
                        {
                            DownloadedCommunityPresets =
                                Settings.DownloadedCommunityPresets
                                ?? new Dictionary<string, DownloadedPresetRecord>(),
                            SharingAuthor = Settings.SharingAuthor ?? "",
                        };
                        Settings.UserSlots[desiredKey] = seed;
                    }
                    else
                    {
                        SimHub.Logging.Current.Info(
                            "[TF4ALL] Migration: target slot already has data; skipping legacy migration to avoid clobber.");
                    }
                    Settings.ActiveSlotKey = desiredKey;
                    try { PersistSettingsCore(); } catch { }
                }
            }
            MountUserSlot(desiredKey);
        }

        // Move a slot's contents from oldKey to newKey (used to re-key email-keyed slots to the
        // immutable user-id). Clobber-safe: only moves when newKey is absent, so it never overwrites
        // an existing user-id slot or deletes data it didn't merge. Fixes ActiveSlotKey if it pointed
        // at oldKey. No-op for empty/equal keys or a missing source.
        private void RekeySlot(string oldKey, string newKey)
        {
            if (Settings?.UserSlots == null) return;
            if (string.IsNullOrEmpty(oldKey) || string.IsNullOrEmpty(newKey)
                || string.Equals(oldKey, newKey, StringComparison.Ordinal)) return;
            if (!Settings.UserSlots.TryGetValue(oldKey, out var slot)) return;
            if (Settings.UserSlots.ContainsKey(newKey)) return;   // target exists: leave the stale key (no clobber)
            Settings.UserSlots[newKey] = slot;
            Settings.UserSlots.Remove(oldKey);
            if (string.Equals(Settings.ActiveSlotKey ?? "", oldKey, StringComparison.Ordinal))
                Settings.ActiveSlotKey = newKey;
            SimHub.Logging.Current.Info("[TF4ALL] Re-keyed a user slot to the stable account id.");
        }

        // Swap which account is live: its community history, its preset LIBRARY (a private folder
        // per account), its portable settings PROFILE, and its per-PC sync state. Stash the current
        // view INTO the prior slot FIRST (so nothing in-flight is lost, and so the slot is seeded
        // from the authoritative live state) before mounting the new one. A same-key mount (startup
        // / post-restore re-link) therefore only refreshes the slot from live and never applies a
        // stale profile back; a real account CHANGE applies the new account's saved profile + sync
        // state and re-applies them to the live pipeline + UI.
        // How MountUserSlot treats the incoming slot's saved settings profile on a real
        // account change. Decided by the CALLER before the mount runs (the interactive
        // prompt lives in OnActiveIdentityChanged), so the mount never blocks on UI while
        // its state is half-swapped.
        // KeepCurrent is the USER's choice from the prompt: the live tuning wins
        // AND becomes this account's saved profile, exactly as the dialog says.
        // KeepCurrentUnprompted is the failure fallback (no prompt was shown):
        // the live tuning still wins, but the incoming account's saved profile
        // is left ALONE, because overwriting it was never consented to and the
        // same failure that triggered the fallback may have left the outgoing
        // profile stale or empty.
        internal enum ProfileApplyChoice { Apply, KeepCurrent, KeepCurrentUnprompted }

        // Re-entrancy guard: a nested mount (an auto-pull apply racing an identity
        // change) would corrupt the half-swapped slot state, so it is skipped + logged.
        private int _mountInProgress;

        private void MountUserSlot(string newKey, ProfileApplyChoice profileChoice = ProfileApplyChoice.Apply)
        {
            if (System.Threading.Interlocked.CompareExchange(ref _mountInProgress, 1, 0) != 0)
            {
                SimHub.Logging.Current.Info(
                    "[TF4ALL] Nested slot mount skipped (a mount is already in progress).");
                return;
            }
            try { MountUserSlotCore(newKey, profileChoice); }
            finally { System.Threading.Interlocked.Exchange(ref _mountInProgress, 0); }
        }

        private void MountUserSlotCore(string newKey, ProfileApplyChoice profileChoice)
        {
            if (Settings == null) return;
            if (Settings.UserSlots == null)
                Settings.UserSlots = new Dictionary<string, UserDataSlot>();
            newKey = newKey ?? "";

            string priorKey = Settings.ActiveSlotKey ?? "";
            bool accountChanged = !string.Equals(priorKey, newKey, StringComparison.Ordinal);

            // Stash the current visible state into the prior slot so anything the user added since
            // the last mount is preserved. StashLiveProfileInto also SEEDS the slot's profile from
            // live, which is why a same-key startup mount can never overwrite live with a stale copy.
            if (!Settings.UserSlots.TryGetValue(priorKey, out var priorSlot))
            {
                priorSlot = new UserDataSlot();
                Settings.UserSlots[priorKey] = priorSlot;
            }
            priorSlot.DownloadedCommunityPresets =
                Settings.DownloadedCommunityPresets
                ?? new Dictionary<string, DownloadedPresetRecord>();
            priorSlot.SharingAuthor = Settings.SharingAuthor ?? "";
            StashLiveProfileInto(priorSlot);

            // Reconcile a pre-user-id email-keyed slot for the account being mounted (a returning
            // account from an old test build), so its history/profile carries to the user-id key.
            if (Settings.AuthSession != null && !string.IsNullOrEmpty(Settings.AuthSession.UserId)
                && string.Equals(newKey, Settings.AuthSession.UserId, StringComparison.Ordinal))
                RekeySlot(CommunityAuth.SlotKeyFromEmail(Settings.AuthSession.Email), newKey);

            // Mount the new slot. Creating it empty if the user has
            // never signed in with this account before.
            if (!Settings.UserSlots.TryGetValue(newKey, out var newSlot))
            {
                newSlot = new UserDataSlot();
                Settings.UserSlots[newKey] = newSlot;
            }

            // Per-account preset library: re-point UserPresets at this account's OWN folder, seeding
            // it (copy from the current library) the first time so signing in brings the user's
            // presets with them. The car-preset + installed-pack stores follow automatically (they
            // read UserPresets.CurrentFolder via a lambda).
            string token = ResolveLibraryToken(newKey, newSlot);
            SeedAccountLibraryIfFirstMount(token, newSlot, UserPresets.CurrentFolder);
            try { UserPresets.Initialize(AccountLibraryFolder(token)); }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Warn(
                    "[TF4ALL] Account library re-point failed: " + ex.GetType().Name);
            }
            _lastLibFingerprint = null;   // folder changed: force the auto-sync drift backstop to recompute

            // Per-account settings profile + sync state (only on a real account switch; a same-key
            // mount leaves the authoritative live state in place).
            if (accountChanged)
            {
                if (newSlot.ProfileSeededV1 && !string.IsNullOrEmpty(newSlot.ProfileSettingsJson))
                {
                    // Existing slot with its own saved feel/effects profile. Loading it
                    // over a live session is exactly how an evening of Mode B tuning got
                    // silently reverted by a mid-session sign-in (2026-07-31: the
                    // drift-recipe revert), so the CALLER decides (interactive switches
                    // prompt in OnActiveIdentityChanged, before this mount mutates
                    // anything; Init re-mounts and revoke sign-outs keep the legacy
                    // apply). Every outcome is logged; the old silence is what made the
                    // revert a mystery. "Keep current" adopts the live tuning INTO the
                    // switched-to slot (the same shape as the brand-new-slot seed
                    // below), so the choice sticks and the next auto-sync push carries
                    // it to the cloud.
                    if (profileChoice == ProfileApplyChoice.Apply)
                    {
                        // Apply its saved feel/effects profile + its own sync state.
                        ApplyProfileToLive(newSlot);
                        SimHub.Logging.Current.Info(
                            "[TF4ALL] Account switch: loaded the incoming slot's saved tuning profile.");
                    }
                    else
                    {
                        // Adopt the kept tuning as this account's saved profile
                        // ONLY when the user actually chose that in the prompt
                        // and we have a real profile to write. An unprompted
                        // fallback keep, or an empty outgoing profile (the stash
                        // shares the failure that caused the fallback), would
                        // otherwise destroy the incoming account's saved tuning:
                        // an empty ProfileSettingsJson with ProfileSeededV1 left
                        // true reads as a brand-new slot on the next switch, so
                        // that account's tuning and sync state are gone for good.
                        if (profileChoice == ProfileApplyChoice.KeepCurrent
                            && !string.IsNullOrEmpty(priorSlot.ProfileSettingsJson))
                        {
                            newSlot.ProfileSettingsJson = priorSlot.ProfileSettingsJson;
                            newSlot.ProfileForzaJson    = priorSlot.ProfileForzaJson;
                        }
                        // Sync state still follows the slot (it is account
                        // bookkeeping, not feel), exactly as ApplyProfileToLive
                        // would have set it.
                        Settings.AutoSyncBackupEnabled        = newSlot.AutoSyncBackupEnabled;
                        Settings.BackupLastSyncedRevision     = newSlot.BackupLastSyncedRevision ?? "";
                        Settings.BackupLastSyncedEnvelopeJson = newSlot.BackupLastSyncedEnvelopeJson ?? "";
                        // The kept tuning is a local edit this account's cloud
                        // has never seen: tuning done while signed out never
                        // armed the auto-backup (RequestAutoBackup returns
                        // early when signed out). Arm it now through the SAME
                        // entry point an ordinary edit uses, so the push is
                        // actually scheduled. Setting the dirty flag by hand
                        // was not enough and was worse than nothing: the mount
                        // deliberately ends in PersistSettingsCore (which never
                        // arms), so nothing would have uploaded, while a set
                        // dirty flag also short-circuits RunLibraryDriftCheck,
                        // disabling the only remaining push backstop for the
                        // rest of the session. Going through RequestAutoBackup
                        // also self-gates on signed-in + auto-sync, so a
                        // sign-OUT keep or an account with sync off no longer
                        // strands the flag. The dirty state additionally makes
                        // the auto-pull that follows this switch take the
                        // 3-way merge path instead of fast-forwarding the
                        // cloud copy over the tuning the user chose to keep.
                        RequestAutoBackup();
                        SimHub.Logging.Current.Info(
                            "[TF4ALL] Account switch: kept the current tuning; the incoming slot's saved profile now matches it.");
                    }
                }
                else
                {
                    // Brand-new account: inherit the current live profile (a copy) so signing in
                    // doesn't reset the dialed-in feel. Auto-sync starts OFF and the synced baseline
                    // empty so a fresh account never auto-pushes to its empty cloud unprompted.
                    newSlot.ProfileSettingsJson = priorSlot.ProfileSettingsJson;
                    newSlot.ProfileForzaJson    = priorSlot.ProfileForzaJson;
                    newSlot.ProfileSeededV1     = true;
                    newSlot.AutoSyncBackupEnabled        = false;
                    newSlot.BackupLastSyncedRevision     = "";
                    newSlot.BackupLastSyncedEnvelopeJson = "";
                    Settings.AutoSyncBackupEnabled        = false;
                    Settings.BackupLastSyncedRevision     = "";
                    Settings.BackupLastSyncedEnvelopeJson = "";
                    // live profile fields already hold this account's seed (unchanged): no apply.
                }
            }

            Settings.DownloadedCommunityPresets = newSlot.DownloadedCommunityPresets
                ?? new Dictionary<string, DownloadedPresetRecord>();
            Settings.SharingAuthor = newSlot.SharingAuthor ?? "";
            Settings.ActiveSlotKey = newKey;

            // Different user is now active: their once-per-session UseCount
            // bumps should start fresh (the prior user's bumps were against
            // a different DownloadedCommunityPresets map).
            _useCountedThisSession.Clear();

            // Re-derive Settings.GameDefaults + CarDefaults from the (now re-pointed) account folder
            // so the active user's per-user overrides overlay the device-wide file-based view.
            // Skipped during Init when the cache hasn't been built yet - the regular Init sequence
            // runs RebuildPresetCacheFromFolders + LoadAndMigrateCarPresets in order anyway.
            if (Settings.Presets != null)
            {
                try { RebuildPresetCacheFromFolders(); }
                catch (Exception ex)
                {
                    // F24: log exception type only; ex.Message can include file paths.
                    SimHub.Logging.Current.Error(
                        "[TF4ALL] Game-default re-derive on slot mount failed: " + ex.GetType().Name);
                }
                // On a REAL account switch, discard the prior account's in-memory per-car overrides
                // (and the persisted-baseline cache) BEFORE loading this account's car presets: so
                // A's entries for cars B never loads don't linger in memory (and bias dirty/save
                // detection), and A's unsaved active-car draft isn't migrated onto disk into B's
                // library by LoadAndMigrateCarPresets's in-memory->file migration step. B's saved
                // cars still load from B's folder; only the prior account's transient state is dropped.
                if (accountChanged)
                {
                    try { Settings.CarOverrides?.Clear(); } catch { }
                    try { _lastPersistedCarOverrides?.Clear(); } catch { }
                }
                try { LoadAndMigrateCarPresets(); }
                catch (Exception ex)
                {
                    SimHub.Logging.Current.Error(
                        "[TF4ALL] Car-default re-derive on slot mount failed: " + ex.GetType().Name);
                }
                // The active car's effective override may have changed;
                // re-resolve it so the live audio + FFB stays consistent.
                if (!string.IsNullOrEmpty(_activeCarId))
                {
                    try { ReloadActiveCarOverrideFromStore(); }
                    catch (Exception ex)
                    {
                        SimHub.Logging.Current.Error(
                            "[TF4ALL] Re-apply active car override on slot mount failed: " + ex.GetType().Name);
                    }
                }
            }

            // On a real account switch, re-apply the new profile to the live pipeline + UI and
            // re-evaluate the (now per-account) auto-sync opt-in. Same paths the cloud restore uses.
            if (accountChanged)
            {
                ApplyGlobalFfbToLive();   // master gain + FFB scalars aren't covered by ApplyActiveCarOverride
                // The slot's profile can carry a different PluginEnabled (Portable field) without a
                // SetPluginEnabled transition; reconcile the device's pause state to the new value.
                SyncDeviceToPluginEnabled("Account switch");
                try { ApplyActiveCarOverride(); }
                catch (Exception ex) { SimHub.Logging.Current.Error("[TF4ALL] Effect re-apply on slot mount failed: " + ex.GetType().Name); }
                try { ApplyForzaSettings(onlyIfChanged: true); }
                catch (Exception ex) { SimHub.Logging.Current.Warn("[TF4ALL] Telemetry re-apply on slot mount failed: " + ex.GetType().Name); }
                try { LibraryReloaded?.Invoke(); }
                catch (Exception ex) { SimHub.Logging.Current.Warn("[TF4ALL] Library-reloaded notify on slot mount failed: " + ex.GetType().Name); }
                try { UpdateAutoPullTimer(); }
                catch (Exception ex) { SimHub.Logging.Current.Warn("[TF4ALL] Auto-pull timer refresh on slot mount failed: " + ex.GetType().Name); }
                // The incoming profile carries the whole Mode B recipe, and
                // ApplyGlobalFfbToLive covers only master gain + the FFB
                // scalars. Without these the settings and the panel show the
                // account's tuning while the 1 kHz path keeps rendering the
                // PREVIOUS feel until something else re-applies (the same
                // pairing ApplyPendingCrossWheelFfb already does).
                try { ApplyModeBFromSettings(); ApplyModeBFeel(); }
                catch (Exception ex) { SimHub.Logging.Current.Error("[TF4ALL] Mode B re-apply on slot mount failed: " + ex.GetType().Name); }
                // The profile carries DashTabOrder/DashTabsDisabled (Portable);
                // rebuild the dash's slot map so the phone follows the new
                // layout without a restart.
                RefreshDashTabSlots();
            }

            try { PersistSettingsCore(); }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Error(
                    "[TF4ALL] Persist after slot mount failed: " + ex.GetType().Name);
            }
        }

        // ---- Per-account profile + library helpers (see UserDataSlot) ----

        // The TrueforceForAll root folder (parent of the shared "user" library). Per-account
        // libraries live under <root>\accounts\<token>.
        private static string TrueforceRootFolder()
        {
            try { return System.IO.Path.GetDirectoryName(UserPresets.DefaultFolder); }
            catch { return null; }
        }

        // Filesystem-safe per-account library token. Prefers the immutable Supabase user_id (UUID)
        // when this slot is the signed-in account; falls back to a sanitized email. "" => anonymous
        // (the shared DefaultFolder). Cached on the slot so it survives sign-out (when the live
        // AuthSession.UserId is no longer available).
        private string ResolveLibraryToken(string slotKey, UserDataSlot slot)
        {
            if (string.IsNullOrEmpty(slotKey)) return "";   // anonymous slot uses the shared folder
            if (slot != null && !string.IsNullOrEmpty(slot.LibraryToken)) return slot.LibraryToken;
            // The slot key IS the immutable account id now (a UUID, already filesystem-safe);
            // sanitize defensively in case of the rare email-key fallback path.
            string token = SanitizeFolderToken(slotKey);
            if (slot != null) slot.LibraryToken = token;
            return token;
        }

        private static string SanitizeFolderToken(string raw)
        {
            if (string.IsNullOrEmpty(raw)) return "anon";
            var invalid = System.IO.Path.GetInvalidFileNameChars();
            var sb = new System.Text.StringBuilder(raw.Length);
            foreach (char c in raw)
                sb.Append(System.Array.IndexOf(invalid, c) >= 0 ? '_' : c);
            string s = sb.ToString();
            return string.IsNullOrEmpty(s) ? "anon" : s;
        }

        // Resolve an account token to its on-disk library folder. "" (anonymous) => the shared
        // DefaultFolder; otherwise <root>\accounts\<token>.
        private static string AccountLibraryFolder(string token)
        {
            if (string.IsNullOrEmpty(token)) return UserPresets.DefaultFolder;
            string root = TrueforceRootFolder();
            return string.IsNullOrEmpty(root)
                ? UserPresets.DefaultFolder
                : System.IO.Path.Combine(root, "accounts", token);
        }

        // First time an account's library folder is used, seed it by COPYING the current library
        // (so signing in brings the user's presets with them). Latched per-slot; only ever READS the
        // source and WRITES the target, so the shared/anonymous folder is never moved or modified.
        // Anonymous ("" token) uses the shared folder and is never seeded.
        private void SeedAccountLibraryIfFirstMount(string token, UserDataSlot slot, string sourceFolder)
        {
            if (string.IsNullOrEmpty(token) || slot == null) return;   // anonymous: nothing to seed
            if (slot.LibrarySeededV1) return;
            try
            {
                string target = AccountLibraryFolder(token);
                bool sameFolder = !string.IsNullOrEmpty(sourceFolder)
                    && string.Equals(System.IO.Path.GetFullPath(sourceFolder),
                                     System.IO.Path.GetFullPath(target), StringComparison.OrdinalIgnoreCase);
                bool targetHasFiles = System.IO.Directory.Exists(target) && BackupLibrary.Bundle(target).Count > 0;
                if (!sameFolder && !targetHasFiles && !string.IsNullOrEmpty(sourceFolder))
                {
                    var src = BackupLibrary.Bundle(sourceFolder);
                    if (src.Count > 0)
                    {
                        int skipped = BackupLibrary.Restore(target, src);
                        SimHub.Logging.Current.Info(
                            "[TF4ALL] Seeded a private library for this account (" + (src.Count - skipped) + " files) from the existing library.");
                    }
                    else { try { System.IO.Directory.CreateDirectory(target); } catch { } }
                }
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Warn("[TF4ALL] Account library seed failed: " + ex.GetType().Name);
            }
            slot.LibrarySeededV1 = true;
        }

        // Serialize the live PORTABLE settings profile (the same subset that travels to the cloud,
        // minus the community-history fields the slot mounts separately) + this account's per-PC
        // sync state INTO the slot. This is also the SEED on first mount (live is the source of
        // truth), which is why a same-key startup mount can never overwrite live with a stale copy.
        // Serialize the live PORTABLE profile in the stash format (settings minus the
        // slot-mounted community fields, plus the Forza prefs). False on failure.
        private bool TryBuildLiveProfile(out string settingsJson, out string forzaJson)
        {
            settingsJson = null;
            forzaJson    = "";
            try
            {
                // Built under the settings-serialize choke point, exactly like
                // PersistSettingsCore: Build walks the whole settings graph
                // with Newtonsoft while the telemetry thread can be inserting
                // into CarGripCalibration / CarFacts, which threw "Collection
                // was modified" mid-switch.
                Newtonsoft.Json.Linq.JObject s;
                string forza;
                lock (_carFactsLock)
                {
                    var env = BackupProjection.Build(Settings, "", DateTime.UtcNow);
                    s     = env.Settings ?? new Newtonsoft.Json.Linq.JObject();
                    forza = env.Forza?.ToString(Newtonsoft.Json.Formatting.None) ?? "";
                }
                s.Remove("DownloadedCommunityPresets");   // slot-mounted separately
                s.Remove("SharingAuthor");                // slot-mounted separately
                settingsJson = s.ToString(Newtonsoft.Json.Formatting.None);
                forzaJson    = forza;
                return true;
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Error("[TF4ALL] Profile stash failed: " + ex.GetType().Name);
                return false;
            }
        }

        private void StashLiveProfileInto(UserDataSlot slot)
        {
            if (slot == null || Settings == null) return;
            if (TryBuildLiveProfile(out string settingsJson, out string forzaJson))
            {
                slot.ProfileSettingsJson = settingsJson;
                slot.ProfileForzaJson    = forzaJson;
                slot.ProfileSeededV1     = true;
            }
            slot.AutoSyncBackupEnabled        = Settings.AutoSyncBackupEnabled;
            slot.BackupLastSyncedRevision     = Settings.BackupLastSyncedRevision ?? "";
            slot.BackupLastSyncedEnvelopeJson = Settings.BackupLastSyncedEnvelopeJson ?? "";
        }

        // Apply a slot's saved portable profile + per-PC sync state onto the live settings
        // (machine/hardware fields untouched). Caller re-applies to the live pipeline + UI after.
        private void ApplyProfileToLive(UserDataSlot slot)
        {
            if (slot == null || Settings == null) return;
            try
            {
                if (!string.IsNullOrEmpty(slot.ProfileSettingsJson))
                {
                    var env = new BackupEnvelope
                    {
                        Settings = Newtonsoft.Json.Linq.JObject.Parse(slot.ProfileSettingsJson),
                        Forza = string.IsNullOrEmpty(slot.ProfileForzaJson)
                            ? null : Newtonsoft.Json.Linq.JObject.Parse(slot.ProfileForzaJson),
                    };
                    BackupProjection.ApplySettings(env, Settings);
                    // A profile stashed before the master switch became three-state
                    // has no MasterMode key, and ApplySettings only writes the keys
                    // it finds, so the OUTGOING account's mode would survive the
                    // switch and decide the incoming one. Same answer as the other
                    // two pre-enum paths: Normal, with the profile's own GameEnabled
                    // map carrying its per-game choices.
                    if (env.Settings["MasterMode"] == null)
                        Settings.MasterMode = TrueforceMasterMode.Normal;
                    // And the per-game map, for the same reason: a profile stashed
                    // before GameModes existed would otherwise leave the OUTGOING
                    // account's per-game choices governing the incoming one.
                    if (env.Settings["GameModes"] == null)
                        RebuildGameModesFromEnabled("account profile");
                    // Same reconcile as the restore path: the incoming profile
                    // carries both Lovely gates and neither handler has run.
                    try { OnLovelyDataAvailabilityChanged(); }
                    catch (Exception ex)
                    {
                        SimHub.Logging.Current.Warn("[TF4ALL] Lovely re-apply after profile swap failed: " + ex.Message);
                    }
                }
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Error("[TF4ALL] Profile apply failed: " + ex.GetType().Name);
            }
            Settings.AutoSyncBackupEnabled        = slot.AutoSyncBackupEnabled;
            Settings.BackupLastSyncedRevision     = slot.BackupLastSyncedRevision ?? "";
            Settings.BackupLastSyncedEnvelopeJson = slot.BackupLastSyncedEnvelopeJson ?? "";
        }

        // Set on the UI thread just before a PROGRAMMATIC SignOut (the session-heartbeat
        // remote-revoke path) so the identity-change handler never prompts for a switch the
        // user did not click; consumed (and cleared) by the next OnActiveIdentityChanged.
        // Same-thread set-then-consume: the revoke path dispatches SignOut to the UI thread
        // and FireIdentityChanged runs synchronously inside it.
        private bool _suppressNextIdentityPrompt;

        // The self-mutating learned state inside a portable profile (grip calibration,
        // car facts, the per-game auto-remembered enables). Ordinary driving changes these,
        // so they are excluded from the "did the tuning actually change?" comparison; they
        // still travel with whichever profile wins.
        private static readonly string[] LearnedProfileKeys =
            { "CarGripCalibration", "CarFacts", "CarFactsSelection", "GameEnabled", "GameModes" };

        // True when two portable profiles carry the same DELIBERATE tuning (learned state
        // stripped, field order/formatting insensitive). Parse failure counts as "differs":
        // when in doubt, ask rather than silently replace.
        private static bool TuningProfilesMatch(string aJson, string bJson)
        {
            try
            {
                var a = Newtonsoft.Json.Linq.JObject.Parse(string.IsNullOrEmpty(aJson) ? "{}" : aJson);
                var b = Newtonsoft.Json.Linq.JObject.Parse(string.IsNullOrEmpty(bJson) ? "{}" : bJson);
                foreach (var k in LearnedProfileKeys) { a.Remove(k); b.Remove(k); }
                return Newtonsoft.Json.Linq.JToken.DeepEquals(a, b);
            }
            catch { return false; }
        }

        // Decide, BEFORE the mount mutates anything, how an interactive account switch
        // treats the incoming slot's saved profile. Apply when there is nothing to ask
        // (same key, brand-new slot, identical deliberate tuning, or no live profile to
        // compare); otherwise the user chooses via the destructive-styled prompt.
        private ProfileApplyChoice DecideProfileChoiceInteractive(string newKey)
        {
            var s = Settings;
            if (s?.UserSlots == null) return ProfileApplyChoice.Apply;
            string priorKey = s.ActiveSlotKey ?? "";
            if (string.Equals(priorKey, newKey ?? "", StringComparison.Ordinal))
                return ProfileApplyChoice.Apply;   // same-key refresh never applies a profile anyway
            if (!s.UserSlots.TryGetValue(newKey ?? "", out var incoming) || incoming == null
                || !incoming.ProfileSeededV1 || string.IsNullOrEmpty(incoming.ProfileSettingsJson))
                return ProfileApplyChoice.Apply;   // brand-new slot inherits live: nothing to ask
            if (!TryBuildLiveProfile(out string liveJson, out _))
            {
                // Cannot compare. Fail CLOSED: applying here would silently
                // replace live tuning with the account's, which is the exact
                // revert this prompt exists to prevent, and the user would
                // never be asked. Unprompted, so the incoming account's saved
                // profile is left untouched and stays recoverable by switching
                // back (the prompted keep deliberately overwrites it; this one
                // must not, and its snapshot failure may have left the
                // outgoing profile stale or empty anyway).
                SimHub.Logging.Current.Warn(
                    "[TF4ALL] Account switch: could not snapshot the live tuning to compare; keeping the current tuning and leaving the account's saved profile untouched.");
                return ProfileApplyChoice.KeepCurrentUnprompted;
            }
            if (TuningProfilesMatch(incoming.ProfileSettingsJson, liveJson))
                return ProfileApplyChoice.Apply;   // identical tuning: apply is a no-op
            return PromptLoadIncomingProfile(signOut: string.IsNullOrEmpty(newKey));
        }

        // Modal choice for an interactive switch whose incoming profile differs from the
        // live tuning. Destructive styling on purpose: the safe "Keep current tuning"
        // button carries BOTH IsDefault and IsCancel, so Enter, Esc, and closing the
        // dialog all keep the current tuning, and only a deliberate click on the red
        // load button replaces it (an earlier two-button draft put load on the cancel
        // slot, where Esc triggered it: the exact revert this prompt exists to prevent).
        // Copy is direction-aware: on sign-out the incoming profile is the local
        // pre-sign-in tuning, not any account's. No WPF context = keep current.
        private ProfileApplyChoice PromptLoadIncomingProfile(bool signOut)
        {
            var app = System.Windows.Application.Current;
            if (app?.Dispatcher == null)
            {
                SimHub.Logging.Current.Info(
                    "[TF4ALL] Account switch: no UI available for the tuning prompt; keeping current tuning.");
                return ProfileApplyChoice.KeepCurrent;
            }
            string body, loadLabel;
            if (signOut)
            {
                body = "Signing out. The tuning saved from before you signed in is different from your current settings."
                     + "\n\nKeep what you have now, or switch back to your pre-sign-in tuning?";
                loadLabel = "Load pre-sign-in tuning";
            }
            else
            {
                body = "This account's saved tuning is different from your current settings."
                     + "\n\nKeep what you have now (it becomes this account's saved tuning), or switch to the tuning saved on this account?";
                loadLabel = "Load account tuning";
            }
            bool load = app.Dispatcher.Invoke(() =>
                TrueforceDialog.Show(null, "Trueforce For All", body,
                    DialogKind.Destructive,
                    okLabel: loadLabel,
                    cancelLabel: "Keep current tuning") == true);
            SimHub.Logging.Current.Info(load
                ? "[TF4ALL] Account switch: user chose to load the incoming saved tuning."
                : "[TF4ALL] Account switch: user chose to keep the current tuning.");
            return load ? ProfileApplyChoice.Apply : ProfileApplyChoice.KeepCurrent;
        }

        // Push the global (non-per-car) FFB scalars from Settings to the live mixer + device. The
        // per-car/per-effect values re-apply via ApplyActiveCarOverride; these globals otherwise only
        // re-apply on a car LOAD, so an account switch must push them explicitly or the wheel keeps
        // the previous account's master gain / scale until the next car change.
        private void ApplyGlobalFfbToLive()
        {
            try
            {
                if (_mixer != null) _mixer.MasterGain = Settings.MasterGain;
                ApplyTrueforceEq();
                if (_device != null)
                {
                    _device.FfbScale                = Settings.FfbScale;
                    _device.FfbInvertSign           = Settings.FfbInvertSign;
                    _device.FfbSmoothTimeConstantMs = EffectiveSmoothingMs();
                    _device.FfbSpikeTamingEnabled   = Settings.FfbSpikeTamingEnabled;
                    _device.FfbSpikeUseSlewLimiter  = Settings.FfbSpikeUseSlewLimiter;
                    _device.FfbSpikeMaxLsbPerMs     = Settings.FfbSpikeMaxLsbPerMs;
                    _device.FfbPeakSoftLimitLsb     = Settings.FfbPeakSoftLimitLsb;
                    _device.FfbSpikeTransientThresholdLsb = Settings.EffectiveSpikeTransientThresholdLsb;
                }
            }
            catch (Exception ex) { SimHub.Logging.Current.Error("[TF4ALL] Global FFB re-apply on slot mount failed: " + ex.GetType().Name); }
        }

        // Init-side welcome path: same modal SettingsControl pops, but
        // owned by the SimHub main window so it works even when the
        // user hasn't navigated to the Trueforce panel yet. Mirrors
        // the SettingsControl version's latch behavior (consume on
        // commit, not on display).
        private void MaybeShowNetworkedWelcomeFromInit()
        {
            if (Settings == null) return;
            if (Settings.HasSeenNetworkedWelcome) return;
            if (string.IsNullOrEmpty(Settings.CommunityBackendUrl)
                || string.IsNullOrEmpty(Settings.CommunityBackendAnonKey))
                return;
            var nextAt = Settings.WelcomeNextShowAt;
            if (nextAt.HasValue && nextAt.Value > DateTime.UtcNow) return;

            // Process-wide guard: only one welcome modal per session. The
            // Settings-panel path shares this flag, so an open panel that's
            // already showing (or has shown) the welcome stops this init path
            // from stacking a duplicate behind it. Set at the commit point so
            // the early-return gates above don't consume it.
            if (WelcomeWindow.ShownThisSession) return;
            WelcomeWindow.ShownThisSession = true;

            var owner = System.Windows.Application.Current?.MainWindow;

            WelcomeWindow welcome;
            try { welcome = new WelcomeWindow { Owner = owner }; }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Info(
                    "[TF4ALL] Init welcome construct failed: " + ex.Message);
                return;
            }
            // If no owner is loaded yet, fall back to a manual center so
            // the dialog isn't off-screen.
            if (owner == null)
                welcome.WindowStartupLocation = System.Windows.WindowStartupLocation.CenterScreen;
            welcome.ShowDialog();

            // The welcome is a PROCEED, not a consent gate: any dismissal
            // latches it and leaves the default-on community + car-data
            // sharing in place (the modal's disclosure line is the sharing
            // notice; opt-out lives in Settings). Mirrors the
            // SettingsControl version so semantics line up.
            Settings.HasSeenNetworkedWelcome = true;
            Settings.WelcomeNextShowAt       = null;
            if (Settings.CommunityEnabled != true) SetCommunityEnabled(true);
            if (Settings.AutoSubmitCarFacts != true) Settings.AutoSubmitCarFacts = true;
            Settings.CarFactsConsentAsked = true;
            EnsureCarFactsAnonId();
            try { PersistSettingsCore(); } catch { }

            // Optional account, run after the proceed commit so cancelling
            // changes nothing. (Username bootstrap is a SettingsControl
            // concern; the panel runs it on its next account refresh.)
            if (welcome.SignInRequested && !AuthIsSignedIn)
            {
                try
                {
                    var signIn = new SignInWindow(this) { Owner = owner };
                    if (owner == null)
                        signIn.WindowStartupLocation = System.Windows.WindowStartupLocation.CenterScreen;
                    signIn.ShowDialog();
                }
                catch (Exception ex)
                {
                    SimHub.Logging.Current.Warn(
                        "[TF4ALL] Init sign-in failed: " + ex.Message);
                }
            }
        }

